INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (34, 'vi', 'Nhân dịp Hội nghị ITS toàn cầu tại Singapore và Hãng PTV cho ra mắt các bản cập nhật mới nhất bao gồm PTV Visum 2020, PTV Vissim & PTV Viswalk 2020, PTV đang có chương trình siêu khuyến mãi vào tháng 10!', 'Tin công ty', 'PTV KHUYẾN MÃI ĐẶC BIỆT TRONG THÁNG 10 ', 'ptv-khuyen-mai-dac-biet-trong-thang-10', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (37, 'vi', 'Trong 2 ngày 04/04/2019 và ngày 05/04/2019 công ty Cổ phần Tin học và Tư vấn Xây dựng (CIC) phối hợp cùng Hãng AET Flood Defence Limited (Anh Quốc) đã tổ chức thành công buổi thuyết trình và giới thiệu, demo sản phẩm ĐÊ MỀM CHỐNG NGẬP cho công ty PMC và công ty Nam Cường. Đây là 2 đơn vị lớn với năng lực quản lý và điều hành rất nhiều khu chung cư và các tòa nhà cao tầng, nhà văn phòng cho thuê...', 'Tin công ty', 'Giới thiệu giải pháp ĐÊ MỀM CHỐNG NGẬP - NGĂN LŨ (Hãng AET - UK) cho 2 đơn vị lớn trong lĩnh vực quản lý tòa nhà là Công ty CP Quản lý & Khai thác Toà nhà PMC & Công ty CP Tập đoàn Nam Cường', 'gioi-thieu-giai-phap-de-mem-chong-ngap-ngan-lu-hang-aet-uk-c', NULL, NULL, 'Giải pháp đê mềm chống ngập của hãng AET, ngăn lũ. Chống ngập cho các tòa nhà, tầng hầm.', 'đê mềm chống ngập, chống ngập các tòa nhà chung cư, chống ngập tầng hầm chung cư') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (38, 'vi', 'Sau khi cung cấp phần mềm DNV PHAST (giúp phân tích và đánh giá rủi ro trong công nghiệp) vào tháng 4 năm 2019 cho PTSC M&C. CIC tiếp tục được tin tưởng cung cấp các phần mềm cho dự án Gallaf như AVEVA''s Instrumentation™, AVEVA PDM & E3D Bundle (AVEVA Everything3D), Fisa Duct, Air Humid Handling và  AVEVA BOCAD', 'Tin công ty', 'Công ty CP Công nghệ và Tư vấn CIC trúng thầu cung cấp các phần mềm cho Công ty TNHH MTV Dịch vụ Cơ khí Hàng hải (PTSC M&C)', 'cong-ty-cp-cong-nghe-va-tu-van-cic-trung-thau', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (39, 'vi', 'Công ty PTSC M&C là đơn vị hàng đầu trong lĩnh vực dịch vụ xây lắp dầu khí, với vị thế và uy tín của PTSC M&C, Công ty luôn tiên phong áp dụng các công cụ quản lý tiến tiến và hệ thống tiêu chuẩn chất lượng vào các hoạt động sản xuất kinh doanh. Điều này giúp khẳng định hơn nữa uy tín và thương hiệu PTSC M&C trên thị trường trong nước và khu vực quốc tế.', 'Tin công ty', 'CIC trúng thầu cung cấp phần mềm PHAST - CIC Company ', 'cic-trung-thau-cung-cap-phan-mem-phast', NULL, NULL, 'CIC trúng thầu cung cấp phần mềm PHAST - CIC Company ', 'phần mềm PHAST') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (40, 'vi', 'Mới đây trong 03 ngày từ 28/2 đến 2/3/2019, công ty Cổ phần Tin học và Tư vấn Xây dựng (CIC) đã hoàn thành cài đặt, chuyển giao và đào tạo phần mềm AERMOD VIEW - giúp phân tích và đánh giá phát thải khí - của hãng Lake Environmental (Canada) – cho Công ty Cổ phần tư vấn xây dựng điện 1 (PECC1)', 'Tin công ty', 'CIC hoàn thành phần mềm AERMOD VIEW cho Công ty PECC1', 'cic-hoan-thanh-phan-mem-aermod-view', NULL, NULL, 'CIC hoàn thành phần mềm AERMOD VIEW cho Công ty PECC1', 'phần mềm AERMOD VIEW') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (41, 'vi', 'Mới đây vào ngày 25/1/2019, công ty Cổ phần Tin học và Tư vấn Xây dựng (CIC) – đại diện cho hãng Sunrise System (UK) tại Việt Nam đã hoàn thành cài đặt và chuyển giao phần mềm PIPENET cho thiết kế và phân tích ứng suất đường ống - thông qua một nhà cung cấp - cho người dùng cuối là Công ty Cổ phần Tư vấn Xây dựng Điện 1 (PECC1).', 'Tin công ty', 'CIC hoàn thành cài đặt và chuyển giao phần mềm PIPENET', 'cic-hoan-thanh-cai-dat-va-chuyen-giao-phan-mem-pipenet', NULL, NULL, 'CIC hoàn thành cài đặt và chuyển giao phần mềm PIPENET', 'phần mềm PIPENET') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (45, 'vi', 'Mới đây, Chính phủ vừa ban hành Nghị định số 138/2018/NĐ-CP về "SỬA ĐỔI, BỔ SUNG MỘT SỐ ĐIỀU NGHỊ ĐỊNH SỐ 65/2016/NĐ-CP NGÀY 01 THÁNG 7 NĂM 2016 CỦA CHÍNH PHỦ QUY ĐỊNH VỀ ĐIỀU KIỆN KINH DOANH DỊCH VỤ ĐÀO TẠO LÁI XE Ô TÔ VÀ DỊCH VỤ SÁT HẠCH LÁI XE"', 'Tin công ty', 'Trung tâm dạy lái xe phải có Thiết bị mô phỏng để đào tạo lái xe', 'thiet-bi-mo-phong-de-dao-tao-lai-xe', NULL, NULL, 'Trung tâm dạy lái xe phải có Thiết bị mô phỏng để đào tạo lái xe', 'Thiết bị mô phỏng đào tạo lái xe') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (46, 'vi', 'SMRT Singapore (Hệ thống giao thông công cộng cao tốc Singapore) và hãng Lander Simulation (Tây Ban Nha) gần đây đã ký một thỏa thuận về việc cung cấp một hệ thống mô phỏng hoàn toàn tự động và không người lái cho Circle Line (tạm dịch là Tuyến Vòng). Tuyến có chiều dài 35.5 km, 30 trạm hoạt động và hàng năm có khoảng 160 triệu lượt hành khách.', 'Tin công ty', 'SMRT Singapore và hãng Lander Simulation (Tây Ban Nha) đã ký thỏa thuận áp dụng hệ thống mô phỏng trong đào tạo lái tàu!', 'smrt-singapore-va-hang-lander-simulation-ky-thoa-thuan', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (47, 'vi', 'Làm thế nào để  thiết kế, ứng dụng hiệu quả khi mô phỏng các nút giao thông cùng mức, các nút giao thông điều khiển bằng đèn tín hiệu - Khai thác các tính năng mới nhất của phần mềm VISSIM 10.', 'Tin công ty', 'Hội thảo đào tạo: Mô phỏng thiết kế cảnh quan Nút giao thông với VISSIM 10 lần I', 'hoi-thao-dao-tao-mo-phong-thiet-ke-canh-quan-nut-giao-thong', NULL, NULL, 'Mô phỏng thiết kế cảnh quan Nút giao thông với VISSIM 10 lần I', 'Mô phỏng thiết kế cảnh quan Nút giao thông') ON CONFLICT (entity_id, locale) DO NOTHING;
