INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (50, 'vi', 'Sử dụng điện thoại di động khi lái xe là hành vi bị cấm trong Công ước quốc tế nhưng tại Việt Nam việc này chưa được luật hoá.', 'Tin công ty', 'Đề xuất cấm dùng điện thoại di động khi lái ôtô', 'de-xuat-cam-dung-dien-thoai-di-dong-khi-lai-oto', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (51, 'vi', 'Ngày 21/08/2017, Viện Năng lượng và CIC đã ký kết Hợp đồng cung cấp phần mềm MIKE 3, theo đó, CIC sẽ cung cấp cho VNL phần mềm MIKE 3 cùng khóa đào tạo sử dụng phần mềm.', 'Tin công ty', 'CIC trúng Gói thầu “Mua sắm phần mềm MIKE 3” của Viện Năng Lượng', 'cic-trung-thau-goi-thau-phan-mem-mike-3-cua-vien-nang-luong', NULL, NULL, 'CIC trúng Gói thầu “Mua sắm phần mềm MIKE 3” của Viện Năng Lượng', 'phần mềm MIKE 3') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (52, 'vi', 'Trường Đại học Thủy lợi là một trong những trường đại học được thành lập đầu tiên sau khi hoà bình được lập lại ở miền Bắc. Trong suốt chặng đường gần 60 năm qua, Trường Đại học Thủy lợi đã và đang không ngừng phát triển trở thành một trường đầu ngành của cả nước đào tạo nguồn nhân lực có trình độ và chất lượng cao trong lĩnh vực thủy lợi, thủy điện, tài nguyên, môi trường, phòng chống và giảm nhẹ thiên tai. Trường có đội ngũ giảng viên giỏi, và đặc biệt, có cơ sở vật chất thuộc loại tốt nhất ở Việt Nam hiện nay.', 'Tin công ty', 'CIC Trúng Gói thầu “Mua mới bộ thiết bị phát hiện sớm dòng thấm tập trung” của Trường Đại học Thủy lợi', 'cic-trung-goi-thau-mua-moi-bo-thiet-bi-phat-hien-som-dong-th', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (53, 'vi', 'BREEZE SOFTWARE là tập đoàn cung cấp phần mềm mô hình hoá phân tán không khí, cháy, nổ và đánh giá rủi ro hàng đầu trên thị trường, được các chuyên gia và giới hàn lâm trong lĩnh vực môi trường, an toàn và các mối nguy hại ứng dụng trong chính phủ, các ngành công nghiệp, và tư vấn trên khắp thế giới.', 'Tin công ty', 'Công ty Cổ phần Tin học và Tư vấn xây dựng (CIC) và BREEZE Software chính thức trở thành đối tác chiến lược', 'cong-ty-co-phan-tin-hoc-va-tu-van-xay-dung-cic-va-breeze-sof', NULL, NULL, 'CIC Company và BREEZE Software chính thức trở thành đối tác chiến lược ', 'mô hình hóa phân tán không khí, mô hình hóa cháy nổ, đánh giá rủi ro') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (54, 'vi', 'Từ ngày 10/4 đến 15/4 năm 2017, Viện Chiến lược và Phát triền Giao thông Vận tải (TDSI) cùng với Công ty Cổ phần Tin học và Tư vấn Xây dựng (CIC) đã phối hợp tổ chức khóa đào tạo “ Ứng dụng mô hình mô phỏng giao thông vi mô và vĩ mô bằng phần mềm Vissim, Visum”.', 'Tin công ty', 'CIC hoàn thành khóa đào tạo phần mềm mô phỏng giao thông VISSIM và phần mềm quy hoạch giao thông VISUM cho TDSI', 'cic-hoan-thanh-khoa-dao-tao-phan-mem-mo-phong-giao-thong-vis', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (55, 'vi', 'Ngày 31/3 vừa qua, Công ty CP Tin học và Tư vấn xây dựng (CIC) đã tiến hành bàn giao các phần mềm mô phỏng, quy hoạch giao thông VISSIM, VISUM của hãng PTV (Đức) cho Viện Chiến lược và Phát triển Giao thông Vận tải (TDSI).', 'Tin công ty', 'CIC hoàn thành bàn giao, nghiệm thu Hợp đồng cung cấp gói phần mềm mô phỏng và quy hoạch giao thông VISSIM, VISUM cho Viện Chiến lược và Phát triển Giao thông Vận tải (TDSI)', 'cic-hoan-thanh-ban-giao-nghiem-thu-hop-dong-vissim-visum', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (56, 'vi', 'Hãng Dynamic Solutions-International, LLC (DSI) hoạt động về kỹ thuật, quy hoạch và nghiên cứu tại Mỹ. Trong hơn 25 năm qua, DSI đã hoàn thành tốt hàng trăm dự án về tài nguyên nước và môi trường. Do đó DSI có thể hỗ trợ khách hàng, chia sẻ kinh nghiệm với các tiêu chuẩn tốt nhất. Với vô số đề tài ứng dụng EE vào nghiên cứu và đã được công bố, EFDC_Explorer đã và đang khẳng định vị trí của mình trên trên diễn đàn công nghệ toàn cầu.', 'Tin công ty', 'CIC trở thành nhà phân phối duy nhất của hãng DSI tại Việt Nam', 'cic-tro-thanh-nha-phan-phoi-duy-nhat-cua-hang-dsi', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (57, 'vi', 'Với kinh nghiệm hơn 25 năm hoạt động trên lĩnh vực Công nghệ thông tin trong ngành xây dựng, Công ty Cổ phần Tin học và Tư vấn Xây dựng (CIC) tự tin vào năng lực phân phối các thiết bị công nghệ cao nhập khẩu và phát triển phần mềm, có khả năng tư vấn, cung cấp tốt các giải pháp công nghệ giúp các công ty cấp nước sạch nâng cao hiệu quả hoạt động sản xuất – kinh doanh, đặc biệt là Giải pháp sử dụng thiết bị cầm tay (PDA/ Handheld) đọc-ghi chỉ số đồng hồ nước và Giải pháp phần mềm quản lý sản xuất – kinh doanh cho các công ty cấp nước.', 'Tin công ty', 'CIC KÝ KẾT HỢP ĐỒNG VÀ HOÀN THÀNH BÀN GIAO 32 THIẾT BỊ ĐỌC  GHI CHỈ SỐ ĐỒNG HỒ NƯỚC DTX20010E CHO CÔNG TY CP VIWACO', 'hop-dong-hoan-thanh-ban-giao-32-thiet-bi-doc-ghi-so-dong-ho', NULL, NULL, 'Ứng dụng giải pháp PDA đọc ghi chỉ số đồng hồ nước', 'ứng dụng giải pháp PDA, ghi chỉ số đồng hồ nước') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (58, 'vi', 'Sau nhiều tháng nỗ lực, Công ty CP Tin học và Tư vấn Xây dựng (CIC) đã tiến hành bàn giao thiết bị Mô phỏng lái xe gắn máy cho Trung tâm Nghiên cứu Giao Thông Vận Tải Việt Đức (VGTRC). ', 'Tin công ty', 'CIC hoàn thành gói thầu: “Cung cấp thiết bị mô hình hóa lái xe gắn máy"  ', 'ban-giao-nghiem-thu-thiet-bi-mo-hinh-hoa-lai-xe-gan-may', NULL, NULL, 'CIC hoàn thành gói thầu: “Cung cấp thiết bị mô hình hóa lái xe gắn máy"  ', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (59, 'vi', 'Viện Thiết kế/ Bộ Quốc phòng (DCCD) - với hơn 60 năm xây dựng và phát triển, bằng những đóng góp to lớn cho ngành xây dựng của Quân đội và đất nước, đã và đang trở thành một trong những đơn vị tư vấn đầu ngành của Bộ Quốc phòng nói riêng và trên cả nước nói chung.', 'Tin công ty', 'CIC Trúng thầu Gói thầu số 11 “Mua sắm thiết bị thí nghiệm, kiểm định công trình cầu, đường” của Viện Thiết kế/ Bộ Quốc phòng', 'cic-trung-thau-goi-thau-so-11-mua-sam-thiet-bi-thi-nghiem', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (60, 'vi', 'Ngày 22 tháng 11 năm 2015, Công ty CP Tin học và Tư vấn Xây dựng (CIC) ký kết thỏa thuận hợp tác với hãng phần mềm Sunrise Systems (Anh), CIC chính thức trở thành nhà phân phối duy nhất, cung cấp toàn bộ sản phẩm của hãng tại thị trường Việt Nam.', 'Tin công ty', 'CIC trở thành nhà phân phối duy nhất bộ phần mềm PIPENET của hãng Sunrise Systems tại Việt Nam', 'cic-tro-thanh-nha-phan-phoi-duy-nhat-bo-phan-mem-pipenet', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (61, 'vi', 'Bài trình bày của CIC tập trung vào vai trò của mô hình hóa trong ứng cứu khẩn cấp và lập kế hoạch ứng cứu sự cố tràn dầu. Đồng thời cũng giới thiệu Hệ thống giải pháp mô phỏng tràn dầu OILMAP của hãng RPS APASA trong việc dự báo nhanh quỹ đạo của dầu tràn.', 'Tin công ty', 'CIC tham luận tại khóa Huấn luyện về ứng phó sự cố tràn dầu thuộc khuôn khổ GOT Tranining lần thứ IX - 2016', 'cic-tham-luan-tai-khoa-huan-luyen-ve-ung-pho-su-co-tran-dau', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (62, 'vi', 'Ngày 14/3/2016, CIC và DNV GL phối hợp tổ chức Hội thảo phần mềm Synergi Life của hãng DNV GL vào công tác quản lý rủi ro & an toàn, sức khỏe, môi trường trong doanh nghiệp.', 'Tin công ty', 'Hội thảo Ứng dụng phần mềm Quản lý Rủi ro & An toàn, Sức khỏe, Môi trường trong doanh nghiệp', 'hoi-thao-ung-dung-phan-mem-quan-ly-rui-ro-toan-suc-khoe', NULL, NULL, 'Hội thảo phần mềm Synergi Life cho công tác quản lý rủi ro & an toàn, sức khỏe, môi trường trong doa', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (63, 'vi', 'Synergi Life là một giải pháp hoàn thiện dành cho việc quản lý rủi ro và QHSE, quản lý tất cả những bất thường, các sự cố, rủi ro, các phân tích, đánh giá, kiểm toán rủi ro và cả những đề xuất cải tiến.', 'Tin công ty', 'CIC và DNV GL tổ chức Hội thảo phần mềm: “QUẢN LÝ RỦI RO & QHSE”', 'cic-va-dnv-gl-chuc-hoi-thao-phan-mem-quan-ly-rui-ro-qhse-1', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (64, 'vi', 'Sáng ngày 24/2/2016, tại Trung tâm Hội nghị Quốc gia Mễ Trì - Từ Liêm - Hà Nội, Công ty Cổ phần Tin học và Tư vấn Xây dựng (CIC) đã tham gia Triển lãm quốc tế lần thứ 8 về công nghệ đóng tàu, hàng hải và công trình biển – Vietship 2016 do Tổng công ty Công nghiệp tàu thủy (SBIC) tổ chức.', 'Tin công ty', 'Triển lãm Quốc tế lần thứ 8 về công nghệ đóng tàu, hàng hải và công trình biển – Vietship 2016.', 'trien-lam-quoc-te-lan-thu-8-ve-cong-nghe-dong-tau-hang-hai-v', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (65, 'vi', 'Ngày 12/11/2015 CIC được nhận được quyết định Trúng thầu Gói thầu VGU-P8-Y14-G “Thiết bị mô hình hóa lái xe gắn máy” thuộc dự án “Mua thiết bị nghiên cứu cho Trung tâm Nghiên cứu Giao thông (VGTRC)”', 'Tin công ty', 'CIC trúng thầu Gói thầu cung cấp "Thiết bị mô hình hóa lái xe gắn máy” cho Đại học Việt Đức (VGU)', 'cic-trung-thau-goi-thau-cung-cap-thiet-bi-mo-hinh-hoa-lai-xe', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (66, 'vi', 'Từ ngày 21/10 – 23/10/2015, tại Trung tâm Hội nghị triển lãm Sài Gòn. Ban lãnh đạo Công ty Cổ phần Tin học và Tư vấn Xây dựng (CIC) tham dự Hội nghị và Triển lãm 2015 với chủ đề “Petrovietnam-40 năm hội nhập và phát triển”.', 'Tin công ty', 'CIC tham dự Hội nghị và Triển lãm 2015', 'cic-du-hoi-nghi-va-trien-lam-2015-voi-chu-de-petrovietnam', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (67, 'vi', 'Công ty TNHH một thành viên Tư vấn thiết kế và Tư vấn xây dựng - Bộ Quốc phòng (Tên Quốc phòng là Viện thiết kế/ Bộ Quốc phòng, gọi tắt DCCD) - là doanh nghiệp trực thuộc Bộ Quốc phòng (tiền thân là Phòng Thiết kế - thành lập ngày 23/01/1955).', 'Tin công ty', 'CIC Trúng thầu Gói thầu số 03 “Mua sắm thiết bị thí nghiệm, kiểm định công trình cầu, đường” trị giá hơn 9 tỷ đồng của Viện Thiết kế/ Bộ Quốc phòng', 'cic-trung-thau-goi-thau-so-03-mua-sam-thiet-bi-thi-nghiem', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (68, 'vi', 'NDT Systems (Hoa Kỳ) là một trong những hãng thiết bị đi đầu trong lĩnh vực kiểm tra không phá hủy kim loại. Sản phẩm của NDT Systems bao gồm một loạt các thiết bị: thiết bị siêu âm đo chiều dày kim loại, siêu âm dò khuyết tật  cầm tay, hệ thống siêu âm hiển thị hình ảnh. Cùng với sự phát triển của công nghệ, NDT Systems liên tục đưa ra các dòng sản phẩm mới để phục vụ cho nhu cầu ngày càng cao của khách hàng.', 'Tin công ty', 'Ký kết hợp đồng cung cấp 01 thiết bị siêu âm đo chiều dày kim loại TG110-DL của hãng NDT Systems (Hoa Kỳ) cho Trung tâm Kiểm định Kỹ thuật An toàn máy, Thiết bị Nông nghiệp (RST)', 'articleky-ket-hop-dong-cung-cap-01-thiet-bi-sieu-am-do-chie', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (69, 'vi', 'Theo đúng tiến độ hợp đồng đã ký kết, ngày 09/06/2015, kỹ thuật viên của CIC - MTK cùng với Chuyên gia của hãng đã tiến hành bàn giao và hướng dẫn sử dụng cho Thư viện Quốc gia Việt Nam', 'Tin công ty', 'Hoàn thành bàn giao lắp đặt hướng dẫn sử dụng Hệ thống xử lý và hiển thị dữ liệu số có cấu trúc MagicBox CCS Đức cho Thư viện Quốc gia Việt Nam', 'hoan-thanh-ban-giao-lap-dat-va-huong-dan-su-dung-he-thong-xu', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (70, 'vi', 'Trong hai ngày, 17/3 tại TP. Hồ Chí Minh và 18/3/2015 tại Tp Vũng Tàu,  CIC và DNV GL đã tổ chức thành công hội thảo “QUẢN LÝ QHSE VÀ RỦI RO DOANH NGHIỆP. Tham dự hai buổi hội thảo có các chuyên gia trong ngành An toàn - sức khỏe - môi trường đến từ hãng DNV GL và gần 100 khách hàng đại diện của hơn 40 doanh nghiệp trong và ngoài ngành dầu khí.', 'Tin công ty', 'Hội thảo "Quản lý QHSE và rủi ro doanh nghiệp"', 'hoi-thao-quan-ly-qhse-va-rui-ro-doanh-nghiep', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (71, 'vi', 'Trong ngành xây dựng cầu đường hiện nay, việc sử dụng cọc khoan nhồi làm nền móng cho công trình đã trở nên phổ biến, nhất là những công trình đòi hỏi nền móng phải chịu được tải trọng lớn truyền xuống hoặc những công trình xây dựng tại những nơi có điều kiện địa chất phức tạp.', 'Tin công ty', 'Ký kết hợp đồng cung cấp 01 bộ thiết bị siêu âm cọc khoan nhồi CHUM của hãng Piletest (Israel) cho Công ty TNHH Tư vấn và Kiểm định Bắc Hải.', 'ky-ket-hop-dong-cung-cap-01-bo-thiet-bi-sieu-am-coc-khoan-nh', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (72, 'vi', 'Được thành lập cách đây trên 19 năm, hãng Piletest (Israel) chuyên về lĩnh vực phát triển các hệ thống kiểm tra nhằm đảm bảo chất lượng cọc, đồng thời cũng cung cấp các thiết bị thực hiện đánh giá chất lượng các hệ thống móng sâu.', 'Tin công ty', 'Ký kết hợp đồng cung cấp 01 bộ thiết bị siêu âm cọc khoan nhồi CHUM của hãng Piletest (Israel) cho Công ty Cổ phần Lộc Thiên', 'ky-ket-hop-dong-cung-cap-01-bo-thiet-bi-sieu-am-coc-khoan', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (73, 'vi', 'Công tác Giám sát ảnh hưởng chấn động do nổ mìn đang ngày càng được các cơ quan quản lý nhà nước và các đơn vị sử dụng vật liệu nổ công nghiệp (VLNCN) quan tâm một cách sâu sắc.', 'Tin công ty', 'Ký kết Hợp đồng cung cấp thiết bị đo chấn động Micromate của hãng Instantel (Canada) cho Tổng công ty Kinh tế kỹ thuật Công nghiệp Quốc phòng (GAET)', 'ky-ket-hop-dong-cung-cap-thiet-bi-do-chan-dong-micromate', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (74, 'vi', 'Ngày 03/11/2014, Công ty Cổ phần Tin học và Tư vấn Xây dựng (CIC) cùng với Chi nhánh Tổng Công ty Cấp nước Sài Gòn TNHH Một thành viên – Xí nghiệp Truyền dẫn Nước sạch (SAWACO) đã ký Hợp đồng kinh tế số 2063/HĐMB-TDNS-QLDA, cung cấp 01 thiết bị Radar xuyên đất (GPR/Georadar) RIS MF Hi-Mod #3 của hãng IDS (Italia).', 'Tin công ty', 'Ký kết Hợp đồng, hoàn thành bàn giao, lắp đặt và hướng dẫn sử dụng thiết bị Radar xuyên đất (GPR Georadar) cho Chi nhánh Tổng Công ty Cấp nước Sài Gòn TNHH Một thành viên – Xí nghiệp Truyền dẫn Nước sạch (SAWACO)', 'articleky-ket-hop-dong-hoan-thanh-ban-giao-lap-dat-va-huong', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (75, 'vi', 'Theo đúng tiến độ hợp đồng đã ký kết, ngày 24/11/2014, kỹ thuật viên của CIC cùng với chuyên gia của hãng APS đã tiến hành bàn giao và hướng dẫn sử dụng cho IMSAT.', 'Tin công ty', 'Hoàn thành bàn giao, lắp đặt và hướng dẫn sử dụng hệ thống máy nén 3 trục đá Wille Geotechnik của hãng APS (Đức) cho Viện Khoa học Công nghệ Mỏ - Vinacomin (IMSAT)', 'hoan-thanh-ban-giao-lap-dat-va-huong-dan-su-dung-he-thong-ma', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (76, 'vi', 'Ngày 26/06/2014, Công ty Cổ phần Tin học và Tư vấn Xây dựng (CIC) cùng với Công ty Cổ phần Tư vấn Dịch vụ Công nghệ Tài nguyên - Môi trường(TECOS) đã ký Hợp đồng kinh tế số 09/PPTB-CICHĐ2014, cung cấp 01 thiết bị Radar xuyên đất (GPR/Georadar) RIS MF Hi-Mod #4 và angten TR 80 cho Viện Khoa học Đo đạc và Bản đồ (VIGAC).', 'Tin công ty', 'Hoàn thành bàn giao, lắp đặt và hướng dẫn sử dụng thiết bị Radar xuyên đất (GPR Georadar) RIS MF Hi-Mod #4 và ăngten TR 80 cho Viện Khoa học Đo đạc và Bản đồ (VIGAC) - Bộ Tài nguyên và Môi trường.', 'articlehoan-thanh-ban-giao-lap-dat-va-huong-dan-su-dung-thi', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (77, 'vi', 'Công nghệ Radar xuyên đất (Georadar -GPR) là một phương pháp địa vật lý hiện đại dựa trên lý thuyết của trường sóng điện từ ở dải tần số từ 10 - 3000 Mhz để nghiên cứu cấu trúc và đặc tính của kết cấu vật chất nông với độ phân giải cao. Trên thế giới, công nghệ Georadar đã được ứng dụng rộng rãi trong nhiều lĩnh vực mang lại hiệu quả thiết thực như ứng dụng bản đồ hóa các công trình ngầm trong thành phố, ứng dụng kiểm tra chất lượng công trình xây dựng, công trình giao thông, khảo sát địa chất và môi trường,...', 'Tin công ty', 'Trúng thầu và hoàn thiện thương thảo hợp đồng cung cấp thiết bị Radar xuyên đất (Georadar – GPR) model RIS MF Hi-Mod #3 của Hãng IDS (Italia)', 'trung-thau-va-hoan-thien-thuong-thao-hop-dong-cung-cap-thiet', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (78, 'vi', 'CIC ký hợp đồng cung cấp 01 máy georadar RIS MF Hi-mod #4 cho Viện Khoa học Đo đạc và Bản đồ (VIGAC)', 'Tin công ty', 'CIC ký hợp đồng cung cấp 01 máy georadar RIS MF Hi-mod #4 cho Viện Khoa học Đo đạc và Bản đồ (VIGAC)', 'cic-ky-hop-dong-cung-cap-01-may-georadar-ris-mf-hi-mod-4-cho', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (80, 'vi', 'Ký hợp đồng cung cấp 04 bộ thiết bị WAVE ON-P đo chấn động, tiếng ồn của hãng GDS (Hàn Quốc) với Công ty TNHH Tư vấn Xây dựng, Địa kỹ thuật và Môi trường (COGECO)', 'Tin công ty', 'Ký hợp đồng cung cấp 04 bộ thiết bị WAVE ON-P đo chấn động, tiếng ồn của hãng GDS (Hàn Quốc) với Công ty TNHH Tư vấn Xây dựng, Địa kỹ thuật và Môi trường (COGECO)', 'ky-hop-dong-cung-cap-04-bo-thiet-bi-wave-p-do-chan-dong-tien', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (81, 'vi', 'Từ ngày, 19 - 21/03/2014, Công ty cổ phần Tin học & Tư vấn Xây dựng CIC đã triển khai bàn giao, hướng dẫn sử dụng 56 máy DT-X8-10E cho Công ty TNHH MTV Cấp nước Hải Phòng theo dự án nhân rộng lần thứ 2 Giải pháp sử dụng thiết bị cầm tay (PDA/Handheld) ghi đọc chỉ số đồng hồ nước cho các chi nhánh ở xa nhất của Công ty như Đồ Sơn, Cát Bà...', 'Tin công ty', 'Hoàn thành bàn giao, hướng dẫn sử dụng 56 máy DT-X8-10E cho Công ty TNHH MTV Cấp nước Hải Phòng thuộc dự án nhân rộng lần 2 GP sử dụng thiết bị cầm tay PDA ghi đọc chỉ số đồng hồ nước', 'hoan-thanh-ban-giao-huong-dan-su-dung-56-may-dt-x8-10e-cho-c', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (82, 'vi', 'Ký hợp đồng cung cấp thiết bị đo chấn động và sóng không khí Blastmate III (hãng Instantel) với Trung tâm Bồi dưỡng và Tư vấn nổ mìn thuộc Hội kỹ thuật nổ mìn Việt Nam', 'Tin công ty', 'Ký hợp đồng cung cấp thiết bị đo chấn động và sóng không khí Blastmate III (hãng Instantel) với Trung tâm Bồi dưỡng và Tư vấn nổ mìn thuộc Hội kỹ thuật nổ mìn Việt Nam', 'ky-hop-dong-cung-cap-thiet-bi-do-chan-dong-va-song-khong-khi', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
