INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (85, 'vi', 'Hoàn thành khóa đào tạo, hướng dẫn sử dụng thiết bị Georadar Ris Plus với ăngten 40 MHz và ăngten 200 MHz cho Viện Khoa học Địa chất và Khoáng sản', 'Tin công ty', 'Hoàn thành khóa đào tạo, hướng dẫn sử dụng thiết bị Georadar Ris Plus với ăngten 40 MHz và ăngten 200 MHz cho Viện Khoa học Địa chất và Khoáng sản', 'hoan-thanh-khoa-dao-tao-huong-dan-su-dung-thiet-bi-georadar-', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (86, 'vi', 'Trường đại học Hồng Đức là trường đại học công lập đa ngành, một địa chỉ uy tín về đào tạo, nghiên cứu khoa học, chuyển giao công nghệ tại khu vực Bắc Trung Bộ.', 'Tin công ty', 'CIC ký hợp đồng cung cấp 01 thiết bị siêu âm cọc khoan nhồi CHUM của hãng Piletest (Israel) và 01 thiết bị định vị cốt thép HM của hãng Elcometer (Anh Quốc) với Trường đại học Hồng Đức', 'cic-ky-hop-dong-cung-cap-01-thiet-bi-sieu-am-coc-khoan-nhoi-', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (87, 'vi', 'Trúng thầu và ký hợp đồng cung cấp thiết bị radar xuyên đất (Georadar – GPR) model Ris Plus của hãng IDS (Italia):”Thiết bị trắc địa, địa vật lý” cho Viện Khoa học Địa chất và Khoáng sản', 'Tin công ty', 'Trúng thầu và ký hợp đồng cung cấp thiết bị radar xuyên đất (Georadar )của hãng IDS :”Thiết bị trắc địa, địa vật lý” cho Viện Khoa học Địa chất và Khoáng sản', 'trung-thau-va-ky-hop-dong-cung-cap-thiet-bi-radar-xuyen-dat', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (88, 'vi', 'Ngày 8/11/2013, tại trường Đại học kiến trúc Hồ Chí Minh,Cục Giám định Nhà nước về chất lượng công trình xây dựng - Bộ Xây dựng đã tổ chức thành công Hội thảo quốc tế về "CÔNG NGHỆ TIÊN TIẾN TRONG QUAN TRẮC VÀ KIỂM ĐỊNH CÔNG TRÌNH XÂY DỰNG".', 'Tin công ty', 'Hội thảo quốc tế về “CÔNG NGHỆ TIÊN TIẾN TRONG QUAN TRẮC VÀ KIỂM ĐỊNH CÔNG TRÌNH XÂY DỰNG”', 'hoi-thao-quoc-te-ve-cong-nghe-tien-tien-trong-quan-trac', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (89, 'vi', 'CIC tiếp tục tổ chức thành công đợt khảo sát thiết bị Radar xuyên đất (GPR/Georadar) tại Hà Nội', 'Tin công ty', 'CIC tiếp tục tổ chức thành công đợt khảo sát thiết bị Radar xuyên đất (GPR Georadar) tại Hà Nội', 'cic-tiep-tuc-chuc-thanh-cong-dot-khao-sat-thiet-bi-radar-xuy', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (90, 'vi', 'Sáng ngày 12/09/2013, hội thảo đã diễn ra tại Trường Đại học Thủy Lợi với sự tham gia của đông đảo các giảng viên Khoa Công trình, Viện Kỹ thuật công trình,...', 'Tin công ty', 'Hội thảo “Giới thiệu ứng dụng công nghệ radar xuyên đất (Georadar – GPR) trong khảo sát, kiểm tra tình trạng thân đê, thân đập” tại Đại học Thủy Lợi', 'hoi-thao-gioi-thieu-ung-dung-cong-nghe-radar-xuyen-dat-geora', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (91, 'vi', 'Công ty CIC trúng gói thầu “ Mua bán phần mềm Tính toán vết dầu loang, theo dõi hướng di chuyển của dầu tràn”', 'Tin công ty', 'Công ty CIC trúng gói thầu “ Mua bán phần mềm Tính toán vết dầu loang, theo dõi hướng di chuyển của dầu tràn”', 'cong-ty-cic-trung-goi-thau-mua-ban-phan-mem-tinh-toan-vet-da', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (92, 'vi', ' Công Ty TNHH Thương Mại Xây Dựng và Chuyển Giao Công Nghệ Mại Lâm là doanh nghiệp tư vấn, triển khai các dịch vụ kỹ thuật trong xây dựng, địa kỹ thuật và môi trường uy tín tại Việt Nam.', 'Tin công ty', 'Ký hợp đồng cung cấp 01 bộ thiết bị siêu âm cọc khoan nhồi CHUM (Hãng Piletest) với Công Ty TNHH Thương Mại Xây Dựng và Chuyển Giao Công Nghệ Mại Lâm', 'ky-hop-dong-cung-cap-01-bo-thiet-bi-sieu-am-coc-khoan-nhoi-c', NULL, NULL, 'Ký hợp đồng cung cấp 01 bộ thiết bị siêu âm cọc khoan nhồi CHUM (Hãng Piletest) với Công Ty TNHH Thư', 'siêu âm cọc khoan nhồi, cọc khoan nhồi, piletest, siêu âm cọc, CHUM') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (93, 'vi', 'Từ ngày 23 - 25/04/2013, Công ty Cổ phần Tin học & Tư vấn Xây dựng (CIC) đã tổ chức thành công các buổi thử nghiệm thiết bị Radar xuyên đất tại Hà Nội với các thông tin chi tiết như sau:', 'Tin công ty', 'CIC tổ chức thành công các buổi thử nghiệm thiết bị Radar xuyên đất GPR Georadar tại Hà Nội', 'cic-chuc-thanh-cong-cac-buoi-thu-nghiem-thiet-bi-radar-xuyen', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (94, 'vi', 'Thỏa thuận hợp tác giữa Hiệp hội Tư vấn xây dựng Việt Nam (VECAS) và Công ty CP Tin học và Tư vấn xây dựng', 'Tin công ty', 'Thỏa thuận hợp tác giữa Hiệp hội Tư vấn xây dựng Việt Nam (VECAS) và Công ty CP Tin học và Tư vấn xây dựng', 'thoa-thuan-hop-tac-giua-hiep-hoi-tu-van-xay-dung-viet-nam-ve', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (95, 'vi', 'Hãng phần mềm Deltares cung cấp các giải pháp chất lượng cao về thiết kế và phân tích các vấn đề về nước xung quanh khu vực sông, cửa sông, ven biển, ...', 'Tin công ty', 'CIC là nhà phân phối chính thức của Deltares tại Việt Nam', 'cic-la-nha-phan-phoi-chinh-thuc-cua-deltares-tai-viet-nam', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (96, 'vi', 'Ngày 11/01/2013, Công ty Cổ phần Tin học & Tư vấn Xây dựng (CIC) đã hoàn tất công tác bàn giao, lắp đặt và hướng dẫn sử dụng thiết bị kiểm tra cáp thép LRM-XXI Diagnostic System cho Viện Cầu Hầm thuộc Viện Khoa học và Công nghệ Giao thông Vận tải (ITST) trong dự án "Mua sắm trang thiết bị thí nghiệm tăng cường năng lực NCKH năm 2012". Đây là dự án cung cấptrang thiết bị nhằm nâng cao công tác nghiên cứu khoa học cho các đơn vị trong viện ITST .', 'Tin công ty', 'Hoàn tất bàn giao và hướng dẫn sử dụng thiết bị kiểm tra cáp thép LRM-XXI Diagnostic System cho Viện Cầu Hầm thuộc Viện Khoa học và Công nghệ Giao thông Vận tải (ITST)', 'hoan-tat-ban-giao-va-huong-dan-su-dung-thiet-bi-kiem-tra-cap', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (97, 'vi', 'Ngày 26/12/2012, Công ty Cổ phần Tin học & Tư vấn Xây dựng (CIC) đã hoàn tất công tác bàn giao, lắp đặt và hướng dẫn sử dụng thiết bị thăm dò địa chấn PASI 16S24-U cho Trường Đại học Khoa học Tự nhiên TP.HCM thuộc "dự án thành phần QG-HCM-07". Đây là dự án cung cấp  trang thiết bị phục vụ  phòng thí nghiệm nhằm nâng cao công tác nghiên cứu và giảng dạy cho  khoa Vật lý.', 'Tin công ty', 'Hoàn tất bàn giao và hướng dẫn sử dụng thiết bị thăm dò địa chấn PASI 16S24-U cho Trường Đại học Khoa học Tự nhiên TP.HCM', 'hoan-tat-ban-giao-va-huong-dan-su-dung-thiet-bi-tham-do-dia', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (98, 'vi', 'Ngày 17/11/2012, Công ty Cổ phần Tin học & Tư vấn Xây dựng (CIC) đã bắt đầu tiến hành bàn giao, lắp đặt và hướng dẫn sử dụng Thiết bị radar xuyên đất (GPR/Georadar) RIS MF Hi-Mod #2 của Hãng IDS (Italia) cho Công ty TNHH Tư vấn Xây dựng Công trình ngầm Đô thị tại Thành phố Hồ Chí Minh. Nội dung chi tiết bao gồm:', 'Tin công ty', 'Hoàn tất bàn giao, lắp đặt và hướng dẫn sử dụng Thiết bị Radar xuyên đất GPR Georadar cho Công ty TNHH Tư vấn Xây dựng Công trình ngầm Đô thị', 'hoan-tat-ban-giao-lap-dat-va-huong-dan-su-dung-thiet-bi-rada', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (99, 'vi', 'Như tin đã đưa, Trường Đại học Khoa học Tự nhiên trực thuộc Trường Đại học Quốc gia TP.HCM là một trường đại học kỹ thuật đầu ngành trong cả nước với các ngành mũi nhọn như: Toán - Tin học, Công nghệ thông tin, Khoa học máy tính, Hệ thống thông tin, Kỹ thuật phần mềm, Vật lý - Vật lý kỹ thuật, Điện tử - Viễn thông, Địa chất, .... Vừa qua, Trường đã tổ chức đấu thầu thành công gói thầu số 2: "Cung cấp và lắp đặt trang thiết bị tiếp theo cho các phòng thí nghiệm cơ bản Khoa Vật lý thuộc Trường Đại học Khoa học Tự nhiên năm 2012 - Dự án thành phần QG-HCM-07", theo hình thức đấu thầu rộng rãi, nhằm nâng cao năng lực công tác nghiên cứu - giảng dạy của Khoa Vật lý, và đã lựa chọn được nhà cung cấp theo đúng trình tự, thủ tục quy định trong Luật Đấu thầu.', 'Tin công ty', 'Ký hợp đồng cung cấp thiết bị thăm dò địa chấn của Hãng PASI Italia cho Trường Đại học Khoa học Tự nhiên Thành Phố Hồ Chí Minh', 'ky-hop-dong-cung-cap-thiet-bi-tham-do-dia-chan-24-kenh-model', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (100, 'vi', '"Cung cấp và lắp đặt trang thiết bị tiếp theo cho các phòng thí nghiệm cơ bản Khoa Vật lý thuộc Trường Đại học Khoa học Tự nhiên năm 2012 - Dự án thành phần QG-HCM-07"', 'Tin công ty', 'Trúng thầu cung cấp thiết bị thăm dò địa chấn 24 kênh Model 16S24-U của Hãng PASI (Italia) gói thầu số 2', 'trung-thau-cung-cap-thiet-bi-tham-do-dia-chan-24-kenh-model-', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (101, 'vi', 'Hiện tượng cáp dự ứng lực bị đứt trong quá trình khai thác do việc bơm vữa bảo vệ không tốt (để lại các lỗ rỗng) và sự rỉ mòn, đứt các sợi thép bên trong là một vấn đề đáng báo động trong lĩnh vực thi công cầu ví dụ như cầu Thị Nại (Quy Nhơn - Bình Định) - cây cầu vượt biển dài nhất Việt Nam tính cho đến thời điểm này.', 'Tin công ty', 'Cung cấp thiết bị kiểm tra cáp thép LRM®- XXI Diagnostic System cho Gói thầu “Mua sắm trang thiết bị thí nghiệm tăng cường năng lực NCKH 2012” của Viện Khoa học & Công nghệ Giao thông Vận tải (ITST)', 'cung-cap-thiet-bi-kiem-tra-cap-thep-lrmr-xxi-diagnostic', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (102, 'vi', 'Ngày 05/09/2012, Công ty Cổ phần Tin học & Tư vấn Xây dựng (CIC) đã ký hợp đồng với Công ty TNHH Tư vấn Xây dựng Công trình ngầm Đô thị để cung cấp Thiết bị Radar xuyên đất RIS MF Hi-Mod #2 của Hãng IDS (Italia).', 'Tin công ty', 'Cung cấp Thiết bị Radar xuyên đất (GPR Georadar) Hãng IDS (Italia) cho Công ty TNHH Tư vấn Xây dựng Công trình ngầm Đô thị', 'cung-cap-thiet-bi-radar-xuyen-dat-gprgeoradar-ris-mf-hi-mod-', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (550, 'vi', 'Trong các phần mềm CAD nói chung, hay trong enjiCAD thì Layout là công cụ vô cùng quan trọng trong việc thiết kế hay quản lý bản vẽ. Tuy nhiên để sử dụng tốt được lệnh Layout thì còn nhiều người vẫn còn rất mơ hồ về công cụ này. Sau đây CIC Software xin được chia sẻ cho các bạn chi tiết về cách sử dụng lệnh Layout.', 'Tin chuyên ngành', 'Sử dụng Layout trong phần mềm CAD enjiCAD thế nào cho hiệu quả', 'su-dung-layout-trong-enjicad-the-nao-cho-hieu-qua', NULL, NULL, 'Sử dụng Layout trong phần mềm CAD enjiCAD thế nào cho hiệu quả', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (104, 'vi', 'Các Hợp đồng trong Quý II/2012 của Trung tâm Phân phối Thiết bị Nhập khẩu', 'Tin công ty', 'Các Hợp đồng trong Quý II/2012 của Trung tâm Phân phối Thiết bị Nhập khẩu', 'cac-hop-dong-trong-quy-ii2012-cua-trung-tam-phan-phoi-thiet-', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (105, 'vi', 'Công ty CP Tin học & Tư vấn Xây dựng (CIC) ký hợp đồng cung cấp các thiết bị thí nghiệm địa kỹ thuật cho Tổng Công ty Tư vấn Thiết kế Giao thông Vận tải (TEDI)', 'Tin công ty', 'CIC ký kết hợp đồng cung cấp các thiết bị thí nghiệm địa kỹ thuật cho Tổng Công ty Tư vấn Thiết kế Giao thông Vận tải (TEDI)', 'cic-ky-ket-hop-dong-cung-cap-cac-thiet-bi-thi-nghiem-dia-ky-', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (106, 'vi', 'Tin tức liên quan đến Hợp đồng CIC quý1/2012 - Trung tâm Phân phối PM Nhập khẩu (CIC)', 'Tin công ty', 'Tin tức liên quan đến Hợp đồng CIC quý1/2012 - Trung tâm Phân phối PM Nhập khẩu (CIC)', 'tin-tuc-lien-quan-den-hop-dong-cic-quy12012-trung-tam-phan-p', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (107, 'vi', 'Ngoài mảng phát triển phần mềm, tư vấn dự án CNTT, tư vấn xây dựng, Công ty Cổ phần Tin học & Tư vấn Xây dựng (CIC) tự hào là đơn vị phân phối có uy tín của hơn 40 hãng thiết bị và phần mềm nổi tiếng trên thế giới như: Piletest (Israel), NDT James Instruments (Hoa Kỳ), IDS (Italia), GDS (Anh Quốc), Geonor (Na Uy), PASI (Italia), Instantel (Canada), PTV (Đức), Metro (Australia), ASA (Mỹ), Autodesk (Hoa Kỳ), CSI (Hoa Kỳ), Plaxis (Hà Lan)...', 'Tin công ty', 'Hội thảo: “Giới thiệu các ứng dụng của thiết bị Georadar” diễn ra ngày 13/01/2012', 'hoi-thao-gioi-thieu-cac-ung-dung-cua-thiet-bi-georadar-dien-', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (108, 'vi', 'Ngày 01/12/2011, Công ty Cổ phần Tin học và Tư vấn Xây dựng (CIC) đã ký hợp đồng cung cấp hai thiết bị Georadar RIS MF Hi-Mod #3 và RIS Hi-Pave HR1 để dò tìm và lập bản đồ hố lún sụp/công trình ngầm. Trong đó, RIS Hi-Pave HR1 là thiết bị dò nhanh với vận tốc tối đa lên trên 100 km/giờ giúp phát hiện nhanh các khu vực lún sụp tiềm tàng, RIS MF Hi-Mod #3 là thiết bị dò chậm giúp phát hiện chính xác vị trí lún sụp, đồng thời cung cấp cơ sở dữ liệu đáng tin cậy cho công tác lập bản đồ công trình ngầm.', 'Tin công ty', 'Hoàn tất bàn giao và hướng dẫn sử dụng hai thiết bị Georadar RIS MF Hi-Mod #3 và RIS Hi-Pave HR1 cho Khu Quản lý Giao thông Đô thị số 1 - Sở Giao thông Vận tải TP.HCM.', 'hoan-tat-ban-giao-va-huong-dan-su-dung-hai-thiet-bi-georadar', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (110, 'vi', 'Hội nghị Dealer Day 2011 Khu vực Châu Á của Hãng IDS đã diễn ra thành công tại Malaysia từ ngày 16 - 18/11/2011', 'Tin công ty', 'Hội nghị Dealer Day 2011 Khu vực Châu Á của Hãng IDS tại Malaysia', 'hoi-nghi-dealer-day-2011-khu-vuc-chau-cua-hang-ids-tai-malay', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (111, 'vi', 'Ngày 25/10/2011, kỹ thuật viên của Công ty CP Tin học & Tư vấn Xây dựng (CIC) đã tiến hành bàn giao và thử nghiệm Thiết bị georadar Detector Duo của hãng IDS cho Trường Đại học KHTN TP.HCM sau nhiều tháng nỗ lực khắc phục các vướng mắc phát sinh từ Nghị quyết 11 của Chính phủ. PGS.TS. Nguyễn Thành Vấn - Trưởng Bộ môn Địa Vật lý - Trường Đại học KHTN TP.HCM đánh giá rất cao Thiết bị georadar Detector với ưu điểm vượt trội "Ăngten tần số kép", ông Vấn đánh giá: Nhiều công trình ngầm trước đây không phát hiện được khi sử dụng các thiết bị georadar khác, nhưng đã dễ dàng phát hiện được với Detector Duo.', 'Tin công ty', 'Hoàn tất bàn giao và thử nghiệm Thiết bị georadar (radar xuyên đất) Detector Duo của hãng IDS (Italia) cho Trường Đại học Khoa học Tự nhiên TP.HCM.', 'hoan-tat-ban-giao-va-thu-nghiem-thiet-bi-georadar-radar-xuye', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (112, 'vi', 'Ký hợp đồng cung cấp thiết bị đo chấn động và sóng không khí Blastmate III (hãng Instantel) với Công ty CP Tư vấn Đầu tư và Dịch vụ Kỹ thuật Mỏ Địa chất', 'Tin công ty', 'Ký hợp đồng cung cấp thiết bị đo chấn động và sóng không khí Blastmate III (hãng Instantel) với Công ty CP Tư vấn Đầu tư và Dịch vụ Kỹ thuật Mỏ Địa chất', 'ky-hop-dong-cung-cap-thiet-bi-do-chan-dong-va-song-khong-khi', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (113, 'vi', 'Cung cấp thiết bị kiểm tra bê tông, cốt thép Elcometer 3312 Model THD cho Công ty TNHH Giao thông Vận tải - Trường Đại học Giao thông Vận tải', 'Tin công ty', 'Cung cấp thiết bị kiểm tra bê tông, cốt thép Elcometer 3312 Model THD cho Công ty TNHH Giao thông Vận tải - Trường Đại học Giao thông Vận tải', 'cung-cap-thiet-bi-kiem-tra-be-tong-cot-thep-elcometer-3312-m', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (114, 'vi', 'Ngày 05/07/2011, Công ty CP Tin học & Tư vấn Xây dựng (CIC) đã ký hợp đồng cung cấp Thiết bị siêu âm cọc khoan nhồi CHUM - 100 m cho Dự án đầu tư trang thiết bị thí nghiệm của Trường ĐH Công nghệ GTVT. Hiện CIC đang chuẩn bị tiến hành bàn giao và hướng dẫn sử dụng cho khách hàng.', 'Tin công ty', 'Cung cấp Thiết bị siêu âm cọc khoan nhồi CHUM – 100 m của hãng Piletest cho Dự án đầu tư trang thiết bị thí nghiệm của Trường Đại học Công nghệ Giao thông Vận tải', 'cung-cap-thiet-bi-sieu-am-coc-khoan-nhoi-chum-100-m-cua-hang', NULL, NULL, 'Cung cấp Thiết bị siêu âm cọc khoan nhồi CHUM  của hãng Piletest cho Dự án đầu tư trang thiết bị', 'siêu âm cọc khoan nhồi, cọc khoan nhồi, piletest, siêu âm cọc, CHUM, khuyến mãi') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (115, 'vi', 'Ngày 28/04/2011, Công ty CP Tin học và Tư vấn Xây dựng (CIC) đã ký hợp đồng cung cấp', 'Tin công ty', 'CIC hoàn tất bàn giao Thiết bị cắt cánh hiện trường H-70 của hãng Genor (Na Uy) cho Tổng Công ty Tư vấn Thiết kết Giao thông Vận tải (TEDI)', 'cic-hoan-tat-ban-giao-thiet-bi-cat-canh-hien-truong-h-70-cua', NULL, NULL, '', 'Thiết bị cắt cánh hiện trường H-70 ') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (116, 'vi', 'Ngày 06/05/2010, Công ty CP Tin học & Tư vấn Xây dựng (CIC) nhận được Thông báo số 243/KHTN-QTTB về việc trúng thầu cung cấp thiết bị Georadar Detector Duo của hãng IDS (Italia) cho Trường ĐH Khoa học Tự nhiên TP. HCM.', 'Tin công ty', 'Trúng thầu cung cấp thiết bị radar xuyên đất (georadar) cho Bộ môn Vật lý Địa cầu, Khoa Vật lý, trường ĐH Khoa học Tự nhiên TP. HCM.', 'trung-thau-cung-cap-thiet-bi-radar-xuyen-dat-georadar-cho-bo', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (117, 'vi', 'Ngày 31/12/2010, Công ty CP Phát triển Xây dựng 199 đã ký hợp đồng đầu tư thiết bị siêu câm cọc khoan nhồi CHM của hãng Piletest (Israel). Thiết bị CHUM nói riêng và các thiết bị kiểm tra chất lượng móng - cọc của hãng Piletest nói chung ngày càng được nhiều đơn vị tại Việt Nam tin dùng, so với các thiết bị cạnh tranh khác, nó có một số ưu điểm như sau:', 'Tin công ty', 'Cung cấp thiết bị siêu âm cọc khoan nhồi cho Công ty Cổ phần Phát triển Xây dựng 199', 'cung-cap-thiet-bi-sieu-am-coc-khoan-nhoi-cho-cong-ty-co-phan', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (118, 'vi', 'CIC tiếp tục hợp tác với Công ty TNHH MTV Hoá chất Mỏ - TKV (MICCO) thực hiện ký kết mua sắm thiết bị đo chấn động và sóng không khí Blastmate III (Instantel).', 'Tin công ty', 'CIC BÀN GIAO 04 MÁY ĐO CHẤN ĐỘNG VÀ SÓNG KHÔNG KHÍ BLASTMATE III CHO TKV ', 'cic-ban-giao-04-may-do-chan-dong-va-song-khong-khi-blastmate', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (120, 'vi', 'Công ty TNHH một thành viên Công nghiệp Hoá chất mỏ là một đơn vị thuộc Tập đoàn Công nghiệp Than - Khoáng sản có nhiệm vụ một vòng khép kín: từ nghiên cứu, sản xuất, phối chế - thử nghiệm, bảo quản, dự trữ quốc gia Vật liệu nổ công nghiệp (VLNCN), xuất nhập khẩu thuốc nổ, nguyên liệu, hoá chất để sản xuất VLNCN, đến dịch vụ sau cung ứng: Vận chuyển, thiết kế mỏ, nổ mìn và các nhiệm vụ khác ngoài VLNCN.', 'Tin công ty', 'Công ty CP Tin học và tư vấn Xây dựng vừa bàn giao thiết bị đo dao động Blastmate III của hãng Instantel cho Công ty công nghiệp hoá chất mỏ.', 'cong-ty-cp-tin-hoc-va-tu-van-xay-dung-vua-ban-giao-thiet-bi-', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (123, 'vi', 'Công ty CIC đã cung cấp thiết bị của hãng Roadscanners dò tìm vết nứt cho đường hầm Thủ Thiêm, giúp xử lý các sự cố rò rỉ nước, phát hiện các vết nứt ngầm trong công trình.', 'Tin công ty', 'CIC cung cấp Thiết bị dò tìm vết nứt cho Đường hầm sông Sài Gòn', 'cic-cung-cap-thiet-bi-do-tim-vet-nut-cho-duong-ham-song-sai-gon', NULL, NULL, 'CIC cung cấp Thiết bị dò tìm vết nứt cho Đường hầm sông Sài Gòn', 'dò tìm vết nứt, phát hiện vết nứt ngầm, hãng Roadscanners, công trình') ON CONFLICT (entity_id, locale) DO NOTHING;
