INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (210, 'vi', 'Ngày 5/2/2020 vừa qua, Công ty CP Công nghệ và Tư vấn CIC đã hoàn thành bàn giao nghiệm thu ETVision system của hãng Argus Science (Mỹ) cho trường ĐH Việt Đức, theo dự án “Mua sắm thiết bị cho ngành EEIT (giai đoạn 2) và thiết bị cho trung tâm nghiên cứu giao thông vận tải Việt Đức (VGTRC)', 'Tin công ty', ' Nghiệm thu Thiết bị theo dõi chuyển động mắt: ETVision system', 'ban-giao-etvision-system', NULL, NULL, ' Nghiệm thu Thiết bị theo dõi chuyển động mắt: ETVision system', 'ETVision system') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (212, 'vi', 'Ngày 10/01/2020 vừa qua, tại tầng 6 tòa nhà CIC - CDC Bộ xây dựng, tập thể Công ty CP Công nghệ và Tư vấn CIC đã tổ chức thành công trọn vẹn Lễ tổng kết hoạt động sản xuất kinh doanh năm 2019 và định hướng hoạt động năm 2020.', 'Tin công ty', 'Tổng kết 2019 vững mạnh, hướng tới 2020 đột phá', 'tong-ket-2019-vung-manh-huong-toi-2020-dot-pha', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (215, 'vi', 'Ngày 26/11/2019 vừa qua, Công ty CP Công nghệ và Tư vấn CIC đã phối hợp cùng đối tác là Công ty Bentley tổ chức thành công Hội thảo “Chuyên đề về giải pháp địa kỹ thuật  ứng dụng phần mềm Bentley Plaxis 2019”', 'Tin công ty', 'Chuyên đề về giải pháp kỹ thuật ứng dụng phần mềm Bentley Plaxis 2019', 'chuyen-de-ve-giai-phap-ky-thuat-phan-mem-bentley-plaxis-2019', NULL, NULL, 'Chuyên đề về giải pháp kỹ thuật ứng dụng phần mềm Bentley Plaxis 2019', 'phần mềm Bentley Plaxis 2019') ON CONFLICT (entity_id, locale) DO NOTHING;
