INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (214, 'vi', 'Tiếp nối sự thành công và hiệu quả áp dụng của CSIxRevit cho việc mô hình tương tác BIM giữa phần mềm ETABS và Autodesk Revit. Vừa qua hãng Computers and Structures, Inc (CSI) vừa cho ra mắt công cụ CSiXCAD.', 'Tin chuyên ngành', 'Hãng Computers and Structures, Inc (CSI) vừa cho ra mắt phần mềm CSiXCAD', 'hang-csi-ra-mat-phan-mem-csixcad', NULL, NULL, 'Hãng Computers and Structures, Inc (CSI) vừa cho ra mắt phần mềm CSiXCAD', 'phần mềm CSiXCAD') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (217, 'vi', 'Ngày 05/03/2020, Tổng Giám đốc Công ty CP Công nghệ và tư vấn CIC đã ra quyết định bổ nhiệm ông Trịnh Văn Tâm, Cử nhân Công nghệ thông tin, giữ chức vụ Phó Giám đốc Trung tâm phân phối phần mềm nhập khẩu trong xây dựng.', 'Tin công ty', 'Bổ nhiệm ông Trịnh Văn Tâm giữ chức vụ  Phó giám đốc Trung tâm phân phối phần mềm nhập khẩu trong xây dựng', 'bo-nhiem-ong-trinh-van-tam-giu-chuc-vupho-giam-doc-trung-tam-phan-phoi-phan-mem-nhap-khau-trong-xay-dung', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (549, 'vi', 'Trong công việc thiết kế sẽ thường phát sinh những phép tính, những chỉ số cần phải tính toán chính xác sử dụng ngay cho bản vẽ. Việc phải tìm mở công cụ máy tính hay tính toán trên internet sẽ tốn nhiều thao tác cũng như mất nhiều thời gian thiết kế. Để xử lý nhanh các phép tính này ta có thể sử dụng công cụ máy tính ngay trong giao diện của enjiCAD rất nhanh và tiện lợi.', 'Tin chuyên ngành', 'Cách sử dụng máy tính nhanh ngay trong giao diện của enjiCAD', 'cach-su-dung-may-tinh-nhanh-ngay-trong-giao-dien-cua-enjicad', NULL, NULL, 'Cách sử dụng máy tính nhanh ngay trong giao diện của enjiCAD', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (219, 'vi', 'Sau thành công của phần mềm enjICAD phiên bản 2019, Công ty CP Công nghệ và tư vấn CIC xin tiếp tục giới thiệu phần mềm enjiCAD phiên bản 2020  với nhiều cải tiến và tính năng mới.', 'Tin chuyên ngành', 'Ra mắt phiên bản mới phần mềm enjiCAD 2020', 'ra-mat-phien-ban-moi-phan-mem-enjicad-2020', NULL, NULL, 'Ra mắt phiên bản mới phần mềm enjiCAD 2020', 'phần mềm enjiCAD 2020') ON CONFLICT (entity_id, locale) DO NOTHING;
