INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (222, 'vi', 'Môi trường thế giới và nguy cơ cạn kiệt nguồn tài nguyên năng lượng thúc đẩy con người tìm kiếm các nguồn tài nguyên mới thay thế. Năng lượng mặt trời là một nguồn tài nguyên không thể cạn kiệt. INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (223, 'vi', 'Vào 13h30 - 15h00, ngày 09 tháng 04, hãng phần mềm BIM CubiCost sẽ tổ chức Hội nghị online với chủ đề “Kỹ thuật số tương lai cùng CubiCost” dành riêng cho khu vực Đông Nam Á với quy mô lên tới 2000 người, số người tham dự tại Việt Nam tối đa là 300 người.', 'Tin chuyên ngành', 'Phần mềm BIM CubiCost tổ chức Hội nghị online với chủ đề “Kỹ thuật số tương lai cùng CubiCost”', 'phan-mem-bim-cubicost-to-chuc-hoi-nghi-online', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
