INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (225, 'vi', 'LiDAR – (Light Detection And Ranging) – là công nghệ viễn thám chủ động sử dụng các loại tia laser để khảo sát đối tượng từ xa. Dữ liệu thu được của hệ thống là tập hợp đám mây điểm phản xạ 3 chiều của tia laser từ đối tượng được khảo sát ở dưới mặt đất.', 'Tin chuyên ngành', 'Công nghệ LiDAR – Giải pháp hiện đại cho khảo sát 3D', 'cong-nghe-lidar-–-giai-phap-hien-dai-cho-khao-sat-3d', NULL, NULL, 'Công nghệ LiDAR – Giải pháp hiện đại cho khảo sát 3D', '') ON CONFLICT (entity_id, locale) DO NOTHING;
