INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (226, 'vi', 'Ngày 02-03-2020, Công ty Cổ phần công nghệ và tư vấn CIC ký hợp đồng cung cấp phần mềm SAP2000, CSIxRevit cho Công ty cổ phần Tư vấn Thiết kế Cảng - Kỹ thuật Biển (PORTCOAST). SAP2000 là phần mềm mô hình phân tích thiết kế kết cấu tổng hợp và CSIxRevit là công cụ kết nối giữa SAP2000 với nền tảng công cụ BIM Autodesk Revit.', 'Tin công ty', 'Cung cấp phần mềm SAP2000 v22, CSIxRevit cho PORTCOAST', 'cung-cap-phan-mem-sap2000-csixrevit-cho-portcoast', NULL, NULL, 'Cung cấp phần mềm SAP2000 v22, CSIxRevit cho PORTCOAST', 'phần mềm SAP2000') ON CONFLICT (entity_id, locale) DO NOTHING;
