INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (228, 'vi', 'Trước tình hình đại dịch Covid-19 hoành hành, Viện Bentley hân hạnh mang đến cơ hội thể hiện sự NĂNG ĐỘNG, TÍCH CỰC và NHIỆT HUYẾT cho các bạn trẻ với những khối óc sáng tạo trong thời gian đóng cửa trường học và tự cách ly.', 'Tin chuyên ngành', 'Viện Bentley  tổ chức  "CUỘC THI SÁNG TẠO CHO SINH VIÊN CƠ SỞ HẠ TẦNG KỸ THUẬT 2020" với giải thưởng lên tới 5.000$', 'vien-bentleyto-chuc-cuoc-thi-sang-tao-cho-sinh-vien-co-so-ha-tang-ky-thuat-2020voi-giai-thuong-len-toi-5000', NULL, NULL, 'Viện Bentley  tổ chức  "CUỘC THI SÁNG TẠO CHO SINH VIÊN CƠ SỞ HẠ TẦNG KỸ THUẬT 2020"', 'bentley') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (230, 'vi', 'BIM là một quy trình liên quan tới việc tạo lập và quản lý những đặc trưng kỹ thuật số (được gọi là mô hình thông tin kỹ thuật số) trong các khâu thiết kế, thi công và vận hành các công trình (công trình ở đây có thể là công trình xây dựng hay các sản phẩm công nghiệp).', 'Tin chuyên ngành', 'Ứng dụng BIM trong xây dựng và Giải pháp từ CIC', 'ung-dung-bim', NULL, NULL, 'Ứng dụng BIM trong xây dựng và Giải pháp từ CIC Company', 'Ứng dụng BIM') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (567, 'vi', 'Với công cụ tạo mô hình đường và địa hình Allplan Road mới, chúng tôi muốn cung cấp một thiết bị có chức năng cao, hiệu suất cao nhưng dễ sử dụng giải pháp. Mục tiêu của chúng tôi là có thể lập mô hình hình học mặt cắt ngang phức tạp và thực hiện các thay đổi dự án bất kỳ lúc nào trong suốt quá trình thiết kế. Bất chấp khả năng mô hình hóa các cấu trúc đường phức tạp về mặt hình học, chúng tôi đặc biệt chú trọng vào mức độ thân thiện với người dùng cao về giao diện đầu vào rõ ràng và quy trình làm việc trực quan.', 'Tin chuyên ngành', 'GIẢI PHÁP MÔ HÌNH ĐƯỜNG THAM SỐ - ALLPLAN ROAD', 'giai-phap-mo-hinh-duong-tham-so-allplan-road', NULL, NULL, 'GIẢI PHÁP MÔ HÌNH ĐƯỜNG THAM SỐ - ALLPLAN ROAD', 'allplan, allplan road') ON CONFLICT (entity_id, locale) DO NOTHING;
