INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (570, 'vi', 'Để đáp ứng nhu cầu đo gió trên cao ngày càng tăng của các dự án điện gió ngoài khơi. Hãng ZephIR – Vương Quốc Anh, đã cung cấp thiết bị ZX 300M được thiết kế đặc biệt để khảo sát, đánh giá năng lượng gió ngoài khơi.', 'Tin chuyên ngành', 'ZX 300M – Giải pháp đo gió trên cao cho các dự án điện gió ngoài khơi', 'zx-300m-–-giai-phap-do-gio-tren-cao-cho-cac-du-an-dien-gio-ngoai-khoi', NULL, NULL, 'ZX 300M – Giải pháp đo gió trên cao cho các dự án điện gió ngoài khơi', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (296, 'vi', 'Kiểm tra định kỳ đường dây truyền tải điện là rất quan trọng để đảm bảo hệ thống phân phối điện hoạt động liên tục ổn định. Các phương pháp kiểm tra truyền thống trên mặt đất với sự tham gia của các đoàn khảo sát thường rất tốn công và thời gian. Để tính toán được độ võng dây chính xác thì cần phải sử dụng đến các thiết bị nặng nề như thanh đo chiều cao, máy kinh vĩ. Việc mang những thiết bị nặng khảo sát trong các khu vực rừng, núi sẽ gây ra rất nhiều khó khăn, nguy hiểm cho các cán bộ khảo sát.', 'Tin chuyên ngành', 'Giải pháp khảo sát đường dây truyền tải điện - Sử dụng công nghệ Lidar kết hợp với Máy bay không người lái UAV', 'giai-phap-khao-sat-duong-day-truyen-tai-dien-su-dung-cong-nghe-lidar-ket-hop-voi-may-bay-khong-nguoi-lai-uav', NULL, NULL, 'Giải pháp khảo sát đường dây truyền tải điện - Công nghệ Lidar kết hợp với Máy bay không người lái', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (297, 'vi', 'Phần mềm NX được phát triển bởi Siemens PLM Software, NX là giải pháp tổng thể CAD/CAM/CAE linh hoạt, tối ưu và có tính đồng bộ cao. Giúp các doanh nghiệp giải quyết mọi vấn đề khó khăn trong việc cải thiện chất lượng sản phẩm, đưa sản phẩm ra thị trường nhanh hơn, và có thể tối ưu hóa những dữ liệu thiết kế cũ.', 'Tin chuyên ngành', 'Giới thiệu phần mềm NX của Siemens PLM Software', 'gioi-thieu-phan-mem-nx-cua-siemens-plm-software', NULL, NULL, 'Giới thiệu phần mềm NX của Siemens PLM Software', 'phần mềm NX của Siemens PLM Software') ON CONFLICT (entity_id, locale) DO NOTHING;
