INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (396, 'vi', 'Cả nước đang bước vào mùa mưa bão, đồng nghĩa, các ẩn họa trên đường khi người dân khi tham gia giao thông gặp phải luôn thường trực; trong đó, hệ thống cây xanh ở hai bên đường có thể ngã đổ bất cứ lúc nào. Để chủ động bảo vệ an toàn cây xanh mùa mưa bão, các cơ quan chức năng cần thực hiện nhiều giải pháp phòng ngừa để tránh các tai nạn đáng tiếc xảy ra.', 'Tin chuyên ngành', 'Các giải pháp công nghệ hỗ trợ kiểm tra tình trạng sức khỏe cây xanh', 'cac-giai-phap-cong-nghe-ho-tro-kiem-tra-trinh-trang-suc-khoe-cay-xanh', NULL, NULL, 'Các giải pháp công nghệ hỗ trợ kiểm tra trình trạng sức khỏe cây xanh', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (397, 'vi', 'Một trong những yếu tố quan trọng nhất trong thiết kế và lắp đặt trang trại điện gió chính là tốc độ gió trong khu vực. Với giải pháp Thiết bị đo gió viễn thám, giờ đây các nhà đầu tư có thể có số liệu chính xác nhất để phục vụ việc khai thác điện gió.', 'Tin chuyên ngành', 'Thiết bị đo gió trên cao – Sản phẩm ứng dụng công nghệ trong khảo sát và quản lý trang trại điện gió', 'thiet-bi-do-gio-tren-cao-quan-ly-trang-trai-dien-gio', NULL, NULL, 'Thiết bị đo gió trên cao – Sản phẩm ứng dụng công nghệ trong khảo sát và quản lý trang trại điện gió', 'đo gió, thiết bị đo gió, điện gió, đo gió trên cao') ON CONFLICT (entity_id, locale) DO NOTHING;
