INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (390, 'vi', 'Với phiên bản Creo 7.0 mới, khách hàng sẽ được thấy và trải nghiệm những đột phá mạnh mẽ, mang tính cách mạng. Thế hệ phần mềm thiết kế mới đáp ứng và phát triển những tính năng: mô phỏng thời gian thực, sản xuất phụ gia và thiết kế đa khung', 'Tin chuyên ngành', 'Tin tức mới về sản phẩm phần mềm thiết kế PTC Creo 7.0', 'tin-tuc-moi-ve-san-pham-ptc-creo70', NULL, NULL, 'Tin tức mới về sản phẩm phần mềm thiết kế PTC Creo 7.0', 'Creo 7.0') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (391, 'vi', 'Ngày 22/05/2020 vừa qua, Công ty CP Công nghệ & Tư vấn CIC đã long trọng tổ chức Chương trình “Đại hội đồng cổ đông 2020”.  Chương trình đã thành công tốt đẹp và nhận được sự đồng thuận cao từ Hội đồng cổ đông của Công ty về kết quả kinh doanh năm 2019 và kế hoạch sản xuất kinh doanh năm 2020.', 'Tin công ty', 'CIC tổ chức thành công Đại hội đồng cổ đông năm 2020', 'cic-to-chuc-thanh-cong-dai-hoi-dong-co-dong-nam-2020', NULL, NULL, 'CIC tổ chức thành công Đại hội đồng cổ đông năm 2020', 'Đại hội đồng cổ đông CIC ') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (393, 'vi', '', 'Quan hệ cổ đông', 'Nghị quyết ĐHCĐ thường niên 2020', 'nghi-quyet-dhcd-thuong-nien-2020', NULL, NULL, 'Nghị quyết ĐHCĐ thường niên 2020', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (394, 'vi', 'Primtech 3D - giải pháp phần mềm 3D hàng đầu cho thiết kế trạm biến áp chứa một cơ sở dữ liệu lớn với khoảng 4000 mô hình mẫu thông minh của các trạm lớn nhỏ trên thế giới vì vậy có thể hoàn thành 80% công việc thiết kế chỉ trong nửa giờ, đồng thời giúp tăng tiến độ dự án và giúp cho các kỹ sư có thể thiết kế được nhiều trạm hơn trong cùng 1 thời gian so với các phần mềm khác.', 'Tin chuyên ngành', 'Thuyết minh đặc tính kỹ thuật phần mềm Primtech', 'thuyet-minh-dac-tinh-ky-thuat-phan-mem-primtech', NULL, NULL, 'Thuyết minh đặc tính kỹ thuật phần mềm Primtech', 'phần mềm Primtech') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (400, 'vi', 'Nhằm thúc đẩy việc ứng dụng BIM trong xây dựng tại Việt Nam, vào tháng 7 này, Glodon Vietnam sẽ tổ chức cuộc thi BIM dành cho QS lần đầu tiên ở Việt Nam năm 2020. Đây là cuộc thi có tính chuyên môn cao, khai thác trên nền tảng phần mềm Cubicost, với giá trị mỗi giải thưởng lên tới hơn 2000 USD.', 'Tin chuyên ngành', 'Glodon Vietnam tổ chức Cuộc thi BIM dành cho QS tại Việt Nam 2020', 'glodon-vietnam-to-chuc-cuoc-thi-bim-danh-cho-qs-tai-viet-nam-2020', NULL, NULL, 'Cuộc thi BIM dành cho QS tại Việt Nam 2020', 'BIM, BIM software') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (401, 'vi', 'Vừa qua, CIC  cung cấp thiết bị ghi địa chấn 48 kênh Summit X One của hàng DMT (Đức) cho Tổng công ty tư vấn & thiết kế giao thông vận tải – CTCP (TEDI)', 'Tin công ty', 'CIC cung cấp thiết bị ghi địa chấn 48 kênh SUMMIT X ONE của hãng DMT (Đức) cho Tổng công ty Tư vấn thiết kế GTVT – CTCP (TEDI)', 'cic-cung-cap-thiet-bi-ghi-dia-chan-48-kenh-summit-x-one-cua-hang-dmt-duc-cho-tong-cong-ty-tu-van-thiet-ke-giao-thong-van-tai-–-ctcp-tedi', NULL, NULL, 'CIC  cung cấp thiết bị ghi địa chấn 48 kênh Summit X One cho Tổng công ty tư vấn thiết kế GTVT', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (402, 'vi', 'Logistic và chuỗi cung ứng đang ngày ngày ảnh hưởng đến cuộc sống hiện đại của chúng ta. Ngành Logistics đảm bảo hàng hóa và dịch vụ đến đúng nơi và đúng thời điểm. Các nhà Logistics giám sát vòng đời của sản phẩm, vị trí lưu hàng và trạng thái vận chuyển….Đi đôi với sự phát triển kinh tế và ngoại thương của Việt Nam, nhu cầu về nhân lực ngành Logistics, đặc biệt là nhân lực chất lượng cao ngày càng tăng. Không có Logistics, mọi hoạt động sản xuất, kinh doanh đứng trước nguy cơ bị dừng lại. Chính vì vậy việc cung cấp những nhân lực có trình độ cao trong ngành Logistic và quản lý chuỗi cung ứng là một yêu cầu cấp thiết. Hiện nay một số trường như Đại học Giao thông Vận tải, Đại Học Kinh tế Quốc dân, Đại học Việt Đức…đã mở chuyên ngành Logistic và quản lý chuỗi cung ứng. Trong đó, Trường Đại học Việt Đức, nơi tiên phong trong ứng dụng công nghệ trong đào tạo và nghiên cứu đã trang bị những phần mềm hàng đầu để sinh viên có thể học và thực hành.', 'Tin công ty', 'CIC trúng gói thầu “Cung cấp các Phần mềm Logistics và quản lý chuỗi cung ứng” cho Trung tâm Nghiên cứu giao thông vận tải Việt Đức thuộc Trường ĐH Việt Đức', 'cic-trung-goi-thau-cung-cap-cac-phan-mem-logistics-va-quan-ly-chuoi-cung-ung-cho-trung-tam-nghien-cuu-giao-thong-van-tai-viet-duc-thuoc-truong-dh-viet-duc', NULL, NULL, 'CIC trúng thầu “Cung cấp các Phần mềm Logistics và quản lý chuỗi cung ứng” cho Trường ĐH Việt Đức', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (403, 'vi', 'Hội thảo trực tuyến về hạ tầng giao thông dành cho các nước đông nam á đưa ra các bài thuyết trình đầy đủ thông tin với các sản phẩm và chuyên gia hàng đầu của hãng BENTLEY nhằm giúp cho các bạn có thể khám phá nhưng kỹ thuật mới để luôn cập nhật nhưng giải pháp hàng đầu trong ngành hạ tầng giao thông và luôn đi đầu trong công nghệ thiết kế hạ tầng giao thông. Người tham gia sẽ nhận được nhưng ý tưởng sáng tạo, quy trình và những bài học thực tiến tốt nhất, đồng thời được trải nghiệm những tiến bộ trong việc đẩy nhanh tiến độ với giải pháp của BENTLEY cho các dự án giao.', 'Tin chuyên ngành', 'Bentley tổ chức Chuỗi hội thảo trực tuyến về hạ tầng giao thông dành cho các nước Đông Nam Á', 'bentley-to-chuc-chuoi-hoi-thao-truc-tuyen-ve-ha-tang-giao-thong-danh-cho-cac-nuoc-dong-nam-a', NULL, NULL, 'Bentley tổ chức Chuỗi hội thảo trực tuyến về hạ tầng giao thông dành cho các nước Đông Nam Á', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (404, 'vi', 'Vật liệu ngày càng đóng vai trò quan trọng trong quá trình đổi mới công nghệ. Đẩy mạnh nghiên cứu, giảng dạy ngành khoa học vật liệu có ý nghĩa hết sức quan trọng, đem lại sự phát triển công nghệ đặc biệt cần thiết cho các nước đang phát triển điển hình như Việt Nam hiện nay. Trường Đại học Việt Đức là một trong những cơ sở nghiên cứu và đào tạo hàng đầu trong lĩnh vực khoa học vật liệu ở Việt Nam.', 'Tin công ty', 'CIC trúng gói thầu “Mua sắm phần mềm cho ngành Khoa học vật liệu" của Trường Đại học Việt Đức', 'cic-trung-goi-thau-mua-sam-phan-mem-cho-nganh-khoa-hoc-vat-lieucua-truong-dai-hoc-viet-duc', NULL, NULL, 'CIC trúng gói thầu “Mua sắm phần mềm cho ngành Khoa học vật liệu" của Trường Đại học Việt Đức', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (405, 'vi', 'SYSTRA là công ty kỹ thuật cung cấp dữ liệu có mức độ phức tạp cao cho một trong những dự án đường sắt lớn nhất thế giới - HS2. Với sự thành công trong việc cung cấp hiệu quả các sản phẩm chất lượng cao góp phần tạo nên sự uy tín trong ngành.', 'Tin chuyên ngành', 'Thông tin về Tập đoàn Kỹ thuật và Tư vấn SYSTRA - Pháp', 'thong-tin-ve-tap-doan-ky-thuat-va-tu-van-systra-phap', NULL, NULL, 'Thông tin về Tập đoàn Kỹ thuật và Tư vấn SYSTRA - Pháp', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (406, 'vi', 'Ngày 31/7/2020, tại trụ sở của Viện Năng Lượng – thuộc Bộ Công Thương, Công ty CP Công nghệ và Tư vấn CIC đã có buổi trình bày, giới thiệu và làm rõ các yếu tố kỹ thuật cũng như thương mại của giải pháp thiết bị đo gió sử dụng công nghệ sóng âm thanh của hãng AQS System (Thụy Điển). Tham gia buổi họp có TS. Nguyễn Anh Tuấn – Giám đốc Trung tâm Năng lượng tái tạo cùng đầy đủ các nghiên cứu viên của Trung tâm.', 'Tin công ty', 'CIC giới thiệu thiết bị đo gió sử dụng công nghệ sóng âm thanh của hãng AQS System cho Viện năng lượng', 'cic-gioi-thieu-thiet-bi-do-gio-su-dung-cong-nghe-song-am-thanh-cua-hang-aqs-system-cho-vien-nang-luong', NULL, NULL, 'CIC giới thiệu thiết bị đo gió sử dụng công nghệ sóng âm thanh hãng AQS System cho Viện năng lượng', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (407, 'vi', 'Ngày 27/09 vừa qua, nhân dịp Kỷ niệm 6 năm thành lập Tổ chức Hội viên tư vấn xây dựng thành phố Hà Nội thuộc Hiệp hội Tư vấn xây dựng Việt Nam (VECAS), Công ty CP Công nghệ và Tư vấn CIC đã có phần giới thiệu ra mắt chính thức Phần mềm enjiCAD - Phần mềm CAD cho kỹ sư Việt, có thể thay thế hoàn toàn phần mềm A.CAD cùng hàng loạt ưu điểm vượt trội.', 'Tin công ty', 'CIC ra mắt Phần mềm enjiCAD - Phần mềm CAD cho kỹ sư Việt', 'cic-ra-mat-phan-mem-enjicad-phan-mem-cad-cho-ky-su-viet', NULL, NULL, 'CIC ra mắt Phần mềm enjiCAD - Phần mềm CAD cho kỹ sư Việt', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (408, 'vi', 'openBIM chưa được biết đến hoặc chưa được áp dụng rộng rãi tại Việt Nam. Vậy nó là gì? Có những lợi ích gì và có thể áp dụng như thế nào vào các dự án xây dựng?', 'Tin chuyên ngành', 'Tìm hiểu về openBIM', 'tim-hieu-ve-openbim', NULL, NULL, 'Tìm hiểu về openBIM', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (409, 'vi', 'Công ty CIC tự hào là  đối tác cung cấp các phần mềm  liên quan tới xây dựng, kỹ thuật, thiết kế ,... cho Công ty Mai – Archi.', 'Tin công ty', 'Công ty CIC vinh dự là cộng sự và đối tác cung cấp phần mềm cho công ty Mai – Archi', 'cong-ty-cic-tu-hao-la-cong-su-va-doi-tac-cung-cap-phan-mem-cho-cong-ty-mai-–-archi', NULL, NULL, 'Công ty CIC vinh dự là cộng sự và đối tác cung cấp phần mềm cho công ty Mai – Archi', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (410, 'vi', 'Hãng CSI vừa cho ra mắt version mới của phần mềm CSiCol. CSiCol v10 ngoài các tính năng như trước đây, hiện đã được bổ sung thêm các tính năng mới trong đó có tính năng nhập thông tin cột từ Etabs, hoạc nhập tiết diện từ text và file CAD DXF. Chi tiết tính năng mới của CSiCol v10 được tổng hợp như dưới đây:', 'Tin chuyên ngành', 'Phát hành CSiCol v10', 'phat-hanh-csicol-v10', NULL, NULL, 'Phát hành CSiCol v10', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (412, 'vi', 'GeoStudio 2021 với nhiều nâng cấp vượt trội so với các phiên bản trước, hứa hẹn cải thiện tốc độ tính toán và cả độ chính xác. Hãy cùng CIC điểm qua các cải tiến nổi bật trông phiên bản mới này của GeoStudio.', 'Tin chuyên ngành', 'Có gì mới trong GeoStudio 2021?', 'co-gi-moi-trong-geostudio-2021', NULL, NULL, 'Có gì mới trong GeoStudio 2021?', 'geostudio2021') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (413, 'vi', 'Ngày 07/10/2020, Công ty Cổ phần Công Nghệ và Tư Vấn CIC ký hợp đồng cung cấp Máy dò tìm cáp ngầm RD8100 của Hãng Radiodetection cho Tổng Công ty Điện lực Hồ Chí Minh TNHH - Ban Quản lý dự án lưới điện phần phối Tp/Hồ Chí Minh.', 'Tin công ty', 'CIC cung cấp 2 máy dò cáp ngầm cho Ban Quản lý dự án lưới điện phân phối Thành phố Hồ Chí Minh', 'cic-cung-cap-2-may-do-cap-ngam-cho-ban-quan-ly-du-an-luoi-dien-phan-phoi-thanh-pho-ho-chi-minh', NULL, NULL, 'CIC cung cấp 2 máy dò cáp ngầm cho Ban Quản lý dự án lưới điện phân phối Thành phố Hồ Chí Mi', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (414, 'vi', 'Trong ngành xây dựng hiện nay, việc sử dụng cọc khoan nhồi làm nền móng cho công trình đã trở nên phổ biến, nhất là những công trình đòi hỏi nền móng phải chịu được tải trọng lớn truyền xuống hoặc những công trình xây dựng tại những nơi có điều kiện địa chất phức tạp', 'Tin công ty', 'CIC Ký kết hợp đồng cung cấp 01 bộ thiết bị siêu âm cọc khoan nhồi CHUM của hãng Piletest (Israel) cho Công ty Sumitomo Mitsui Construction Co., Ltd', 'cic-ky-ket-hop-dong-cung-cap-01-bo-thiet-bi-sieu-am-coc-khoan-nhoi-chum-cua-hang-piletest-israel-cho-cong-ty-sumitomo-mitsui-construction-co-ltd', NULL, NULL, 'CIC cung cấp bộ thiết bị siêu âm cọc khoan nhồi CHUM cho Công ty Sumitomo Mitsui Construction', 'siêu âm cọc khoan nhồi, cọc khoan nhồi, piletest, siêu âm cọc, CHUM') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (415, 'vi', 'Tháng 10/2020, CIC đã ký kết hợp đồng cung cấp thiết bị đo độ dẫn nhiệt của vật liệu cho Viện Nhiệt đới Môi trường.', 'Tin công ty', 'CIC trúng thầu gói thầu cung cấp : “ Thiết bị đo độ dẫn nhiệt của vật liệu” cho Viện Nhiệt đới Môi trường', 'cic-trung-thau-goi-thau-cung-cap-:thiet-bi-do-do-dan-nhiet-cua-vat-lieu-cho-vien-nhiet-doi-moi-truong', NULL, NULL, 'CIC trúng thầu gói thầu cung cấp : “ Thiết bị đo độ dẫn nhiệt của vật liệu” cho Viện Nhiệt đới Môi t', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (416, 'vi', 'Tháng 10/2020, Tổng công ty Đầu tư và Phát triển công nghiệp (Becamex) đã ký kết hợp đồng đầu tư hệ thống Robot kiểm tra cống ngầm với Công ty CP Công nghệ và Tư vấn CIC nhằm giám sát, kiểm tra hệ thống cống ngầm trong các khu công nghiệp, dân cư, đô thị và hạ tầng giao thông.', 'Tin công ty', 'CIC ký hợp đồng cung cấp thiết bị Robot khảo sát kiểm tra cống ngầm cho BECAMEX', 'cic-ky-hop-dong-cung-cap-thiet-bi-robot-khao-sat-kiem-tra-cong-ngam-cho-becamex', NULL, NULL, 'CIC ký hợp đồng cung cấp thiết bị Robot khảo sát kiểm tra cống ngầm cho BECAMEX', '') ON CONFLICT (entity_id, locale) DO NOTHING;
