INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (418, 'vi', 'Công ty TNHH Archetype Việt Nam và Công ty TNHH Rankine & Hill Việt Nam là các nhà thầu lớn và uy tín trong lĩnh vực xây dựng tại Việt Nam.', 'Tin công ty', 'CIC HCM - Cung cấp các sản phẩm phần mềm của hãng CSI cho các công ty Rankine & Hill và Archetype VN', 'cic-hcm-cung-cap-cac-san-pham-phan-mem-cua-hang-csi-cho-cac-cong-ty-rankine-amp;-hill-va-archetype-vn', NULL, NULL, 'CIC HCM - Cung cấp các sản phẩm phần mềm của hãng CSI cho các công ty Rankine & Hill và Archetype VN', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (419, 'vi', 'Ngày 27/11/2020 vừa qua, tại Khách sạn Mường Thanh Luxury Phú Quốc, tập thể Ban lãnh đạo và CBNV Công ty CP Công nghệ và Tư vấn CIC đã tổ chức thành công Lễ kỷ niệm 30 năm ngày thành lập Công ty, 27/11/1990 - 27/11/2020.', 'Tin công ty', 'Lễ kỷ niệm 30 năm ngày thành lập Công ty CP Công nghệ và Tư vấn CIC', 'le-ky-niem-30-nam-ngay-thanh-lap-cong-ty-cp-cong-nghe-va-tu-van-cic', NULL, NULL, 'Lễ kỷ niệm 30 năm ngày thành lập Công ty CP Công nghệ và Tư vấn CIC', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (420, 'vi', '', 'Tin chuyên ngành', 'Phần mềm tính toán liên kết thép (Steel Connection) nào tốt nhất', 'phan-mem-tinh-toan-lien-ket-thep-steel-connection-nao-tot', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (421, 'vi', 'Phần mềm nào sẽ là giải pháp tốt nhất cho bài toán về năng suất và giá cả hiện tại cho ngành sản xuất gỗ tại Việt Nam?INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (422, 'vi', 'Sản xuất hệ cửa nói chung và hệ cửa nhôm kính nói riêng là một trong những ngành công nghiệp luôn giữ được sức nóng của mình trên thị trường. Với đặc điểm đa dạng về chủng loại, mẫu mã  từ các dòng thanh nhôm như nhôm hệ Xingfa, nhôm Tung Kuang, nhôm Việt Pháp,.. cho đến các mẫu mã sản phẩm đáp ứng thị hiếu của nhiều phân khúc khách hàng. Bên cạnh đó phụ kiện nhôm kính, dây chuyền gia công nhôm kính cũng được phân loại với giá cả dao động phụ thuộc vào quy mô sản xuất và khả năng tài chính của doanh nghiệp .', 'Tin chuyên ngành', 'Giải pháp công nghệ ngành Sản xuất kính - cửa trong xây dựng', 'giai-phap-cong-nghe-nganh-vat-lieu-xay-dung', NULL, NULL, 'Giải pháp công nghệ ngành vật liệu xây dựng', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (423, 'vi', 'CIC là đơn vị có hơn 30 năm kinh nghiệm trong lĩnh vực phát triển phần mềm, cung cấp các giải pháp Công nghệ thông tin cho các ngành xây dựng, cơ khí chế tạo và sản xuất. Trong đó có phần mềm enjiCAD – giải pháp CAD thay thế bản quyền vĩnh viễn với chi phí đầu tư thấp mà tính năng tương đương với AutoCAD hiện hành. Phần mềm enjiCAD vừa mới được phát hành từ cuối năm 2019 nhưng khi tung ra thị trường thì đã thu hút được lượng lớn khách hàng quan tâm và tin tưởng sử dụng trong đó phải kể đến các đơn vị lớn về xây dựng, cơ khí và sản xuất.', 'Tin công ty', 'Phần mềm enjiCAD - 1 năm khởi đầu thành công', 'phan-mem-enjicad-1-nam-khoi-dau-thanh-cong', NULL, NULL, 'Phần mềm enjiCAD - 1 năm khởi đầu thành công', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (424, 'vi', 'Ngày 01/12/2020, Công ty CP Công nghệ và Tư vấn CIC đã có buổi trình bày, giới thiệu về Robot giám sát trạm biến áp tự động của hãng Quantumspatial cho Công ty Truyền tải Điện 3. Tham gia buổi họp bao gồm Ông Huỳnh Quang Thịnh – Trưởng phòng kỹ thuật, các cán bộ kỹ thuật cùng các trưởng trạm trực thuộc của Tổng Công ty truyền tải điện 3, các trưởng trạm, Ông Ian Berdie – Chủ tịch và Ông Scott – chuyên gia kỹ thuật của hãng Quantum (Mỹ) và đại diện Công ty CP Công nghệ và Tư vấn CIC.', 'Tin công ty', 'CIC thực hiện demo Robot Giám sát trạm biến áp của hãng Quantumspatial', 'cic-thuc-hien-demo-robot-giam-sat-tram-bien-ap-cua-hang-quantumspatial', NULL, NULL, 'CIC thực hiện demo Robot Giám sát trạm biến áp của hãng Quantumspatial', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (425, 'vi', 'Ngày 30 tháng 11 năm 2020 Công ty Cổ phần Công nghệ và Tư vấn CIC ký kết Hợp Đồng “Trang bị thuê bao dữ liệu môi trường EDS dùng cho hệ thống lập kế hoạch tìm kiếm cứu nạn tối ưu (SAROPS)” tại Trung tâm Phối hợp Tìm kiếm Cứu nạn Hàng Hải Việt Nam.', 'Tin công ty', 'CIC ký kết hợp đồng Trang bị thuê bao dữ liệu môi trường  EDS với Trung tâm Phối hợp Tìm kiếm Cứu nạn Hàng Hải Việt Nam', 'cic-ky-ket-hop-dong-trang-bi-thue-bao-du-lieu-moi-truongvoi-trung-tam-phoi-hop-tim-kiem-cuu-nan-hang-hai-viet-nam', NULL, NULL, 'CIC ký hợp đồng Thuê bao dữ liệu môi trường  với Trung tâm Phối hợp Tìm kiếm Cứu nạn Hàng hải', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (426, 'vi', 'Ngày 18 tháng 12 năm 2020, Công ty Cổ phần Công nghệ và Tư vấn CIC đã bàn giao cài đặt và đào tạo phần mềm MIKE 21 tại Đoàn Đo đạc Biên vẽ hải đồ và Nghiên cứu biển. Đoàn Đo đạc Biên vẽ hải đồ và Nghiên cứu biển thực hiện các chức năng đặc biệt quan trọng như công tác đo đạc, biên vẽ hải đồ và nghiên cứu biển phục vụ nhiệm vụ quản lý, bảo vệ chủ quyền biển, đảo, thềm lục địa của Tổ quốc.', 'Tin công ty', 'CIC bàn giao và đào tạo phần mềm MIKE 21 cho Đoàn Đo đạc Biên vẽ hải đồ và Nghiên cứu biển', 'cic-ban-giao-va-dao-tao-phan-mem-mike-21-cho-doan-do-dac-bien-ve-hai-do-va-nghien-cuu-bien', NULL, NULL, 'CIC bàn giao và đào tạo phần mềm MIKE 21 cho Đoàn Đo đạc Biên vẽ hải đồ và Nghiên cứu biển', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (427, 'vi', 'Cuối tháng 12/2020, CIC đã ký Hợp đồng cung cấp các gói phần mềm giao thông PTV VISSIM, PTV VISUM, PTV VISWALK của hãng PTV Group (Đức) cho người dùng cuối là Trường Đại Học Sư Phạm Kỹ Thuật TP.HCM.', 'Tin công ty', 'CIC ký Hợp đồng cung cấp các phần mềm mô phỏng giao thông - PTV VISSIM, quy hoạch giao thông - PTV VISUM, và mô phỏng người đi bộ PTV VISWALK cho Trường ĐH Sư Phạm Kỹ Thuật TP.HCM (HCMUTE)', 'cic-ky-hop-dong-cung-cap-cac-phan-mem-mo-phong-giao-thong-ptv-vissim-va-quy-hoach-giao-thong-ptv-visum-cho-truong-dh-su-pham-ky-thuat-tphcm', NULL, NULL, 'CIC ký Hợp đồng cung cấp các phần mềm PTV VISSIM và PTV VISUM cho Trường ĐH Sư Phạm Kỹ Thuật TP.HCM', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (428, 'vi', 'Mở đầu năm 2021 cũng là thời điểm CIC ra mắt phần mềm enjiCAD phiên bản mới 2021 với những nâng cấp về hiệu năng cũng như bổ sung và cập nhật thêm các tính năng cần thiết cho người sử dụng nhưng vẫn giữ giao diện thân thuộc và dễ sử dụng như phiên bản trước đó.', 'Tin công ty', 'CIC ra mắt enjiCAD phiên bản 2021', 'cic-ra-mat-enjicad-phien-ban-2021', NULL, NULL, 'CIC ra mắt enjiCAD phiên bản 2021', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (429, 'vi', 'Ngày 24/12/2020, Công ty Cổ phần Công Nghệ và Tư vấn CIC đã ký kết Hợp đồng cung cấp Phần mềm PIPENET –Module Spray/Sprinkler cho Công ty TNHH SHINRYO VIỆT NAM.', 'Tin công ty', 'Công ty Cổ phần Công nghệ và Tư vấn CIC ký kết Hợp đồng cung cấp phần mềm PIPENET cho công ty TNHH SHINRYO VIỆT NAM', 'cong-ty-co-phan-cong-nghe-va-tu-van-cic-ky-ket-hop-dong-cung-cap-phan-mem-pipenet-cho-cong-ty-tnhh-shinryo-viet-nam', NULL, NULL, 'CIC ký kết Hợp đồng cung cấp phần mềm PIPENET cho công ty TNHH SHINRYO VIỆT NAM', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (430, 'vi', 'CSI vừa phát hành loạt videos tiêu điểm cho công cụ CSiXCAD, nêu bật các tính năng và khả năng của phần mềm.', 'Tin chuyên ngành', 'Bộ Video giới thiệu các tính năng chính của CSiXCAD', 'bo-video-gioi-thieu-cac-tinh-nang-chinh-cua-csixcad', NULL, NULL, 'Bộ Video giới thiệu các tính năng chính của CSiXCAD', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (431, 'vi', 'Tháng 12 năm 2020 vừa qua, Công ty Cổ phần Công nghệ và Tư vấn CIC đã Cung cấp Robot khảo sát kiểm tra cống ngầm Hãng Pearpoint - Mỹ  và đào tạo sử dụng thiết bị cho Tổng Công ty Đầu tư và Phát triển Công Nghiệp (BECAMEX).', 'Tin công ty', 'Công ty CP Công nghệ & Tư vấn CIC hoàn thành bàn giao, đào tạo vận hành Robot Khảo sát Kiểm tra cống ngầm cho Tổng Công ty CP Đầu tư & Phát triển (BECAMEX)', 'cong-ty-cp-cong-nghe-amp;-tu-van-cic-hoan-thanh-ban-giao-dao-tao-van-hanh-robot-khao-sat-kiem-tra-cong-ngam-cho-tong-cp-cong-ty-dau-tu-amp;-phat-trien-becamex', NULL, NULL, 'CIC hoàn thành bàn giao, đào tạo vận hành Robot Khảo sát Kiểm tra cống ngầm cho BECAMEX', 'pear point, robot cống ngầm') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (432, 'vi', 'Ngày 22/01/2021 vừa qua, tại tầng 6 tòa nhà CIC - CDC Bộ xây dựng, tập thể Công ty CP Công nghệ và Tư vấn CIC đã tổ chức thành công trọn vẹn Lễ tổng kết hoạt động sản xuất kinh doanh năm 2020 và định hướng phát triển năm 2021.', 'Tin công ty', 'CIC tổ chức Lễ tổng kết hoạt động sản xuất kinh doanh năm 2020 và định hướng phát triển năm 2021', 'cic-to-chuc-le-tong-ket-hoat-dong-san-xuat-kinh-doanh-nam-2020-va-dinh-huong-phat-trien-nam-2021', NULL, NULL, 'CIC tổ chức Lễ tổng kết hoạt động sản xuất kinh doanh năm 2020 và định hướng phát triển năm 2021', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (433, 'vi', 'Minitab – Một ứng dụng, phần mềm thống kê tiện dụng và mạnh mẽ, sử dụng dễ dàng và hiệu quả. Minitab có thể Mô hình hóa, phân tích và khai thác sức mạnh dữ liệu để giải quyết các vấn đề nan giải. Minitab có các công cụ thống kê đáng tin cậy nhất trên thị thường nhằm tận dụng tối đa dữ liệu, đưa ra xu hướng, dự đoán các mẫu, tìm ra mối quan hệ giữa các biến, trực quan hóa các tương tác dữ liệu và xác định các yếu tố quan trọng.', 'Tin chuyên ngành', 'Phần mềm Minitab', 'phan-mem-minitab', NULL, NULL, 'Phần mềm Minitab', 'minitab') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (434, 'vi', 'Đầu tháng 1 năm 2021, tại văn phòng CÔNG TY TNHH SHINRYO VIỆT NAM diễn ra khóa đào tạo Phần mềm PIPENET - Module Spray/Sprinkler chuyên cho lĩnh vực phòng cháy chữa cháy.', 'Tin công ty', 'CIC hoàn thành khóa đào tạo sử dụng Phần mềm PIPENET – Module Spray/Sprinkler cho Công ty TNHH Shinryo Việt Nam', 'cic-hoan-thanh-khoa-dao-tao-su-dung-phan-mem-pipenet-–-module-spraysprinkler-cho-cong-ty-tnhh-shinryo-viet-nam', NULL, NULL, 'CIC hoàn thành khóa đào tạo sử dụng Phần mềm PIPENET – module Spray/Sprinkler cho Shinryo Việt Nam', 'Pipenet') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (435, 'vi', 'Ngày 19/01/2021, vừa mới đây thì CIC đã ký kết Hợp đồng phần mềm enjiCAD Professional - Network cho Công ty TNHH BECM Việt Nam.', 'Tin công ty', 'CIC ký kết Hợp đồng cung cấp phần mềm enjiCAD cho Công ty TNHH BECM Việt Nam', 'cic-ky-ket-hop-dong-cung-cap-phan-mem-enjicad-cho-cong-ty-tnhh-becm-viet-nam', NULL, NULL, 'CIC ký kết Hợp đồng cung cấp phần mềm enjiCAD cho Công ty TNHH BECM Việt Nam', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (436, 'vi', 'Ngày 16/01/2021 vừa qua,  CIC đã tiến hành bàn giao bản quyền và cài đặt phần mềm GStars CAD cho Công Ty TNHH King''s Grating.', 'Tin công ty', 'CIC ký kết hợp đồng cung cấp phần mềm GstarCAD cho công ty TNHH King’s Grating', 'cic-ky-ket-hop-dong-cung-cap-phan-mem-gstarcad-cho-cong-ty-tnhh-king’s-grating', NULL, NULL, 'CIC ký kết hợp đồng cung cấp phần mềm GstarCAD cho công ty TNHH King’s Grating', 'phần mềm cad, bàn giao phần mềm CAD, AutoCAD, enjiCAD') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (437, 'vi', 'Từ quá trình tìm hiểu, thực hiện dự án đến suốt thời gian đi tư vấn doanh nghiệp, tôi nhận thấy có vài hiểu lầm về BIM mà tôi nghĩ nên ghi lại ở đây:', 'Tin chuyên ngành', 'Những hiểu lầm về BIM (phần 1)', 'nhung-hieu-lam-ve-bim-phan-1', NULL, NULL, 'Những hiểu lầm về BIM (phần 1)', 'BIM, BIM software, tu van BIM') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (438, 'vi', 'Tiếp theo phần 1, sau đây là những điều và những quan niệm  sai lầm về BIM:', 'Tin chuyên ngành', 'Những hiểu lầm về BIM (phần 2)', 'nhung-hieu-lam-ve-bim-phan-2', NULL, NULL, 'Những hiểu lầm về BIM (phần 2)', 'BIM, BIM software, tư vấn BIM') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (439, 'vi', 'Kể từ đại dịch toàn cầu bắt đầu, nhiều lãnh đạo doanh nghiệp đã phân tích cách Virus Corona gây ra sự chuyển đổi kỹ thuật số trong mọi ngành một cách nhanh chong. Các doanh nghiệp muốn tồn tại phải thích ứng với một thế giới “điều khiển từ xa”.', 'Tin chuyên ngành', 'Xây dựng 4.0: Tại sao đây là thời điểm để triển khai BIM và xây dựng kỹ thuật số', 'xay-dung-40:-tai-sao-day-la-thoi-diem-de-trien-khai-bim-va-xay-dung-ky-thuat-so', NULL, NULL, 'Xây dựng 4.0: Tại sao đây là thời điểm để triển khai BIM và xây dựng kỹ thuật số', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (440, 'vi', 'Việc ứng dụng phần mềm Lantek trong thiết kế và lập trình gia công  giúp tiết kiệm thời gian , tối ưu quy trình sản xuất từ đó góp phần nâng cao hiệu quả kinh tế cho các doanh nghiệp', 'Tin chuyên ngành', 'Ứng dụng phần mềm Lantek trong ngành gia công kim loại tấm', 'ung-dung-phan-mem-lantek-trong-nganh-gia-cong-kim-loai-tam', NULL, NULL, 'Ứng dụng phần mềm Lantek trong ngành gia công kim loại tấm', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (441, 'vi', 'BIM trong thị trường ngành xây dựng toàn cầu đạt 7,53 tỷ đô, và sẽ đạt 15.0% CAGR vào năm 2027, theo Allied Market Research. Gia tăng hiệu quả và năng suất tại các công trường xây dựng và việc sử dụng trong các hoạt động xây dựng mô-đun hoặc đúc sẵn thúc đẩy sự tăng trưởng của BIM toàn cầu trong thị trường xây dựng.', 'Tin chuyên ngành', 'Báo cáo của Allied Market Research về ứng dụng BIM', 'bao-cao-cua-allied-market-research-ve-ung-dung-bim', NULL, NULL, 'Báo cáo của Allied Market Research về ứng dụng BIM', 'BIM, BIM software, tư vấn BIM') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (442, 'vi', 'Ngày 20/02 vừa qua đã diễn ra lễ ký kết hợp tác đối tác chiến lược giữa Công ty TNHH German Software Intelligence (GSI) của Đức và Công ty CP Công nghệ và Tư vấn CIC về việc phân phối sản phẩm ALLPLAN cho thị trường Việt Nam. Theo đó, CIC sẽ là đối tác phân phối duy nhất của Công ty GSI cho sản phẩm ALLPLAN tại Việt Nam.', 'Tin công ty', 'Công ty CP Công nghệ & Tư vấn CIC trở thành nhà phân phối duy nhất sản phẩm ALLPLAN tại Việt Nam', 'cong-ty-cp-cong-nghe-amp;-tu-van-cic-tro-thanh-nha-phan-phoi-duy-nhat-san-pham-allplan-tai-viet-nam', NULL, NULL, 'Công ty CP Công nghệ & Tư vấn CIC trở thành nhà phân phối duy nhất sản phẩm ALLPLAN tại Việt Nam', 'BIM, BIM software, tư vấn BIM, allplan, cầu đường') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (443, 'vi', 'Nghị quyết Triệu tập ĐHCĐTN năm 2021', 'Quan hệ cổ đông', 'Nghị quyết Triệu tập ĐHCĐTN năm 2021', 'nghi-quyet-trieu-tap-dhcdtn-nam-2021', NULL, NULL, 'Nghị quyết Triệu tập ĐHCĐTN năm 2021', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (444, 'vi', 'Những năm gần đây sạt lở đất diễn ra ngày càng nhiều và ngày càng nghiêm trọng hơn. Có nhiều nguyên nhân dẫn đến tình trạng này có thể kể đến như: Kết quả của những chấn động tự nhiên làm mất sự liên kết của đất, đá trên sườn đồi và núi ở vùng có địa hình dốc lớn, địa chất yếu có độ rỗng lớn, vùng đất pha cát/đá và vùng rừng thưa; Rừng bị chặt phá nhiều; Địa hình đồi núi cao, dốc lớn, xây dựng công trình thiếu nghiên cứu các yếu tối địa chất.', 'Tin chuyên ngành', 'Sạt lở đất và các giải pháp quan trắc sạt lở đất', 'giam-sat-sat-lo-dat', NULL, NULL, 'Giám sát sạt lở đất', 'sạt lở đất, quan trắc sạt lở đất, thiết bị quan trắc sạt lở') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (445, 'vi', 'Tiếp nối thành công chuỗi chương trình “ALLPLAN Đồng Hành Cùng Sinh Viên Việt Nam”, ngày 2/4/2021 vừa qua, CIC phối hợp cùng công ty GSI – đối tác chính thức của Allplan tại khu vực châu Á, đã tổ chức buổi hội thảo với chủ đề “Quy trình làm việc hiệu quả trong xây dựng dân dụng với ALLPLAN” tại Đại Học Công Nghệ Tp. Hồ Chí Minh – HUTECH.', 'Tin chuyên ngành', 'Hội thảo chuyên đề “Quy trình làm việc hiệu quả trong xây dựng dân dụng với AllPlan”', 'hoi-thao-chuyen-de-quy-trinh-lam-viec-hieu-qua-trong-xay-dung-dan-dung-voi-allplan', NULL, NULL, 'Hội thảo chuyên đề “Quy trình làm việc hiệu quả trong xây dựng dân dụng với AllPlan”', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (446, 'vi', 'Hãng Radiodetection (Anh Quốc) đã chính thức ra mắt các dòng máy phát & thiết bị định vị dò cáp ngầm RD8200 & RD7200 mới với nhiều cải tiến.', 'Tin chuyên ngành', 'Hãng Radiodetection (Anh Quốc) chính thức ra mắt các dòng máy phát & thiết bị định vị dò cáp ngầm RD8200 & RD7200 mới', 'hang-radiodetection-anh-quoc-chinh-thuc-ra-mat-cac-dong-may-phat-amp;-thiet-bi-dinh-vi-do-cap-ngam-rd8200-amp;-rd7200-moi', NULL, NULL, 'Hãng Radiodetection (Anh Quốc) chính thức ra mắt các dòng máy phát & thiết bị định vị dò cáp ngầm RD', 'radiodetection, siêu âm xuyên đất, radar xuyên đất') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (447, 'vi', 'Hiện nay các nhà máy điện, trạm biến áp và lưới điện phát triển rất nhanh chóng cả về số lượng, quy mô và chất lượng dẫn tới việc quản lý vận hành các hệ thống điện lớn sẽ đòi hỏi phải có số lượng nhân công lớn làm tăng chi phí. Hơn nữa, nhiều hạng mục công việc bắt buộc phải tự động hóa hoàn toàn mới đáp ứng được các yêu cầu kỹ thuật. Vì vậy, việc ứng dụng các hệ thống thông tin, đo lường, điều khiển để tự động hóa trong hệ thống điện là một hướng đi tất yếu.', 'Tin chuyên ngành', 'Robot giám sát trạm biến áp', 'robot-giam-sat-tram-bien-ap', NULL, NULL, 'Robot giám sát trạm biến áp', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (448, 'vi', 'Kiểm tra định kỳ đường dây tải điện là công việc rất quan trọng để đảm bảo việc cung cấp điện không bị gián đoạn. Các phương pháp kiểm tra truyền thống dựa trên cơ sở liên quan đến các nhóm khảo sát thường rất tốn công sức và thời gian. Phương pháp tính toán khoảng cách giữa võng của dây truyền tải và cây thường dùng đến đến các thiết bị nặng như que đo chiều cao và máy kinh vĩ. Đây là một công việc khó khăn đối với nhân viên kiểm tra trong những vùng sâu hoang dã hoặc vùng có địa hình nguy hiểm.', 'Tin chuyên ngành', 'Sử dụng AUV gắn LiDAR lập bản đồ hành lang và giám sát an toàn đường dây truyền tải điện', 'su-dung-auv-gan-lidar-lap-ban-do-hanh-lang-va-giam-sat-an-toan-duong-day-truyen-tai-dien', NULL, NULL, 'Sử dụng AUV gắn LiDAR lập bản đồ hành lang và giám sát an toàn đường dây truyền tải điện', 'AUV, lidar, drone') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (449, 'vi', 'Trong dự án này, nhóm nghiên cứu tiến hành nghiên cứu các tác động của rừng đối với gió, bao gồm sự thay đổi của gió và sức gió. Trong rừng, có sự thay đổi sức gió lớn hơn so với những nơi không có rừng. Điều này có thể dẫn đến việc giảm sản lượng điện. Các phép đo tại từng vị trí tuabin gió riêng lẻ có chi phí quá đắt. Do đó, người ta phải sử dụng các mô hình để ước tính trước sản lượng gió. Tuy nhiên, đọ chính xác của mô hình đối với nơi có rừng lớn hơn nhiều so với những nơi không có rừng.', 'Tin chuyên ngành', 'Dự án nghiên cứu sự thay đổi của sức gió trong rừng sử dụng Thiết bị đo gió trên cao bằng công nghệ SoDAR AQ510 của hãng AQS – Thụy Điển', 'du-an-nghien-cuu-su-thay-doi-cua-suc-gio-trong-rung-su-dung-thiet-bi-do-gio-tren-cao-bang-cong-nghe-sodar-aq510-cua-hang-aqs-–-thuy-dien', NULL, NULL, 'Dự án nghiên cứu sự thay đổi của sức gió trong rừng sử dụng Thiết bị đo gió trên cao bằng công nghệ', 'Năng lượng gió, Rừng, Dòng xoáy, Tải trọng tuabin gió, Lập mô hình theo tỷ lệ Mesoscale, Lập mô hình') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (450, 'vi', 'Tiếp nối 2 phần trước của những sai lầm về BIM, phần 3 này tiếp tục nhắc tới một số nguyên tắc rất quan trọng trong việc quản lý và trao đổi thông tin vẫn thường gặp phải.', 'Tin chuyên ngành', 'Những hiểu lầm về BIM (phần 3)', 'nhung-hieu-lam-ve-bim-phan-3', NULL, NULL, 'Những hiểu lầm về BIM (phần 3)', 'BIM, phần mềm BIM, tư vấn BIM, cầu đường') ON CONFLICT (entity_id, locale) DO NOTHING;
