INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (461, 'vi', 'Hiện nay, các dự án xây dựng càng ngày càng trở nên phức tạp và yêu cầu cao về tiến độ cũng như độ chính xác. Để đáp ứng những yêu cầu trên các kỹ sư cũng cần phải sử dụng những công cụ mạnh mẽ và hiệu quả hơn. Công cụ đó phải có thể làm việc được trên cả môi trường 2D và 3D, giao tiếp tốt với các phần mềm khác và đưa ra chất lượng tốt nhất.', 'Tin công ty', 'Hội thảo "Ứng dụng BIM AllPlan cho kết cấu - Giải pháp mới mang lại hiệu quả cao"', 'hoi-thaoung-dung-bim-allplan-cho-ket-cau-giai-phap-moi-mang-lai-hieu-qua-cao-', NULL, NULL, 'Hội thảo "Ứng dụng BIM AllPlan cho kết cấu - Giải pháp mới mang lại hiệu quả cao"', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (462, 'vi', 'Mới đây,  CIC đã tiếp tục trở thành đối tác độc quyền chính thức phân phối các sản phẩm của hãng DMT GmbH & Co. KG (DMT) – một hãng thiết bị địa chấn nổi tiếng có trụ sở tại Am TÜV 1, 45307 Essen, Đức.', 'Tin công ty', 'CIC chính thức trở thành đại lý độc quyền phân phối các thiết bị của hãng DMT (Đức)', 'cic-chinh-thuc-tro-thanh-dai-ly-doc-quyen-cua-hang-dmt-duc', NULL, NULL, 'CIC chính thức trở thành đối tác độc quyền của hãng DMT (Đức)', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (463, 'vi', 'Ngày 27/04 vừa qua, Công ty CP Công nghệ và Tư vấn CIC đã phối hợp cùng Bộ Xây dựng và hãng phần mềm AllPlan tổ chức thành công hội thảo với chủ đề “Ứng dụng BIM AllPlan trong xây dựng - Giải pháp mới mang lại hiệu quả cao”. Hội thảo đã thu hút đông đảo sự tham gia của gần 200 người tham dự là đại diện cho các đơn vị, tổ chức hoạt động trong lĩnh vực xây dựng, thiết kế.', 'Tin công ty', 'Tổ chức thành công hội thảo “Ứng dụng BIM AllPlan trong xây dựng - Giải pháp mới mang lại hiệu quả cao”', 'to-chuc-thanh-cong-hoi-thao-ung-dung-bim-allplan-trong-xay-dung-giai-phap-moi-mang-lai-hieu-qua-cao', NULL, NULL, 'Tổ chức thành công “Ứng dụng BIM AllPlan trong xây dựng - Giải pháp mới mang lại hiệu quả cao”', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (464, 'vi', 'Khi ngành công nghiệp năng lượng gió mở rộng và các dự án quy mô dần được phát triển, các tua bin gió ngày càng trở lên lớn hơn về đường kính cánh quạt cũng như chiều cao trục. Do đó việc đánh giá chính xác về tài nguyên gió trở lên khó khăn hơn đối với các phương pháp truyền thống như gắn cảm biến đo gió lên cột.', 'Tin chuyên ngành', 'Giải pháp đo gió cho nhà máy điện gió hiện đại', 'giai-phap-do-gio-cho-nha-may-dien-gio-hien-dai', NULL, NULL, 'Đo gió trên cao', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (465, 'vi', 'Ngày 22/3/2021, CIC chính thức trúng thầu và ký hợp đồng với Viện Vật lý Địa cầu – thuộc Viện Hàn lâm Khoa học Việt Nam gói thầu số 8PTV-HB-TB: Cung cấp, lắp đặt thiết bị giám sát chấn động gây ra do nổ mìn khu vực nhà máy thủy điện Hòa Bình mở rộng', 'Tin công ty', 'CIC trúng thầu Gói thầu số 8PTV-HB-TB: Cung cấp, lắp đặt thiết bị giám sát chấn động gây ra do nổ mìn khu vực nhà máy thủy điện Hòa Bình mở rộng', 'cic-trung-thau-goi-thau-so-8ptv-hb-tb:-cung-cap-lap-dat-thiet-bi-giam-sat-chan-dong-gay-ra-do-no-min-khu-vuc-nha-may-thuy-dien-hoa-binh-mo-rong', NULL, NULL, 'CIC trúng thầu Gói thầu Cung cấp, lắp đặt thiết bị giám sát chấn động gây ra do nổ mìn', 'giám sát chấn động online, thiết bị giám sát nổ mìn, thiết bị giám sát chấn động') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (466, 'vi', 'Công ty Cổ phần Công nghệ và Tư vấn CIC tuyển dụng vị trí Sale Engineer - Kỹ sư bán hàng tại Chi nhánh TP Hồ Chí Minh với mức lương hấp dẫn.', 'Tin tuyển dụng', 'Tuyển dụng Kỹ sư bán hàng - Sales Engineer  ', 'tuyen-dung-ky-su-ban-hang-sales-engineer', NULL, NULL, 'Tuyển dụng Kỹ sư bán hàng - Sales Engineer  ', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (468, 'vi', 'Ngày 12/05/2021, Công ty CP Công nghệ và Tư vấn CIC và Nghề nội thất đã có buổi trình bày, giới thiệu về phần mềm Logikal - phần mềm chuyên dụng thiết kế, sản xuất hệ cửa sổ, cửa đi, hệ vách dựng của hãng Orgadata (Đức). Buổi giới thiệu đã diễn ra thành công với sự tham gia của nhiều đơn vị là các nhà thầu nhôm kính lớn tại Việt Nam.', 'Tin chuyên ngành', 'Tổ chức thành công hội thảo online với chủ đề “Giải pháp công nghệ cho các nhà thầu nhôm kính”', 'to-chuc-thanh-cong-hoi-thao-online-voi-chu-de-giai-phap-cong-nghe-cho-cac-nha-thau-nhom-kinh', NULL, NULL, 'Tổ chức thành công hội thảo online với chủ đề “Giải pháp công nghệ cho các nhà thầu nhôm kính”', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (469, 'vi', 'Ngày 14/05/2021 vừa qua, Công ty CP Công nghệ & Tư vấn CIC đã tổ chức thành công Chương trình “Đại hội đồng cổ đông 2021”.  Dù sự bùng phát của đại dịch COVID-19 gây nhiều ảnh hưởng, nhưng chương trình đã thành công tốt đẹp và nhận được sự đồng thuận cao từ Hội đồng cổ đông của Công ty về kết quả kinh doanh năm 2020 và kế hoạch sản xuất kinh doanh năm 2021.', 'Tin công ty', 'CIC tổ chức thành công Đại hội đồng cổ đông năm 2021', 'cic-to-chuc-thanh-cong-dai-hoi-dong-co-dong-nam-2021', NULL, NULL, 'CIC tổ chức thành công Đại hội đồng cổ đông năm 2021', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (470, 'vi', 'Trong quá trình phát triển, CIC không ngừng tìm kiếm những đối tác công nghệ nước ngoài có phần mềm và giải pháp công nghệ cao phù hợp với nhu cầu ở Việt Nam. Một trong những đối tác trong lĩnh vực giao thông của chúng tôi là hãng PTV Group (CHLB Đức) – nhà cung cấp hàng đầu về các phần mềm và giải pháp trong giao thông như: phần mềm mô phỏng giao thông VISSIM, phần mềm quy hoạch giao thông VISUM mà đã được dùng phổ biến trong nước... Ngoài ra hãng PTV có giải pháp quản lý giao thông thông minh theo thời gian thực – PTV OPTIMA, giải pháp đã được ứng dụng ở nhiều thành phố thông minh trên thế giới có điều kiện giao thông tương tự Việt Nam.', 'Tin chuyên ngành', 'Thư mời tham dự hội thảo "Giải pháp quản lý giao thông thông minh theo thời gian thực" do CIC và PTV Group (Đức) tổ chức', 'moi-tham-du-hoi-thao-truc-tuyen-ve-quan-ly-giao-thong-thong-minh-theo-thoi-gian-thuc', NULL, NULL, 'Mời tham dự hội thảo trực tuyến về quản lý giao thông thông mình theo thời gian thực', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (471, 'vi', '', 'Quan hệ cổ đông', 'Nghị quyết 2021 CIC', 'nghi-quyet-2021-cic', NULL, NULL, 'Nghị quyết 2021 CIC', '') ON CONFLICT (entity_id, locale) DO NOTHING;
