INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (547, 'vi', 'Chính phủ và các chủ đầu tư đã bắt đầu bắt buộc sử dụng BIMvà các mô hình 3D thông minh trong công trình xây dựng của họ, vì tính hiệu quả, chính xác và khả năng trao đổi thông tin mà nó mang lại. Tuy nhiên, theo khảo sát thực tế có 40% kỹ sư và kiến trúc sư vẫn sử dụng các bản vẽ 2D trong công việc hàng ngày. Vậy tại sao bản vẽ 2D vẫn tồn tại?', 'Tin chuyên ngành', 'Có phải 2D CAD ngày càng lỗi thời?', 'co-phai-2d-cad-ngay-cang-loi-thoi', NULL, NULL, 'Có phải 2D CAD ngày càng lỗi thời?', 'kết cấu, allplan, BIM, Allplan Bridge') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (548, 'vi', 'Trong quá trình thiết kế hẳn anh em sẽ có nhiều lúc phải tìm tâm của các hình tròn hay đa giác. Với hình tròn thì rất đơn giản, ta chỉ cần click chuột trái vào đường tròn sẽ tìm được tâm đường tròn. Còn với các đa giác thì không làm được như vậy, cách làm thủ công bằng việc kẻ các đường để lấy giao điểm sẽ rất tốn thời gian.', 'Tin chuyên ngành', 'Cách tìm tâm các hình đa giác (Polygon)', 'cach-tim-tam-cac-hinh-da-giac-polygon', NULL, NULL, 'Cách tìm tâm các hình đa giác (Polygon)', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (474, 'vi', 'Với bí quyết công nghệ truyền động toàn diện, DMT đã phát triển một hệ thống trực tuyến được phối hợp hoàn hảo cho lĩnh vực năng lượng gió, dựa trên tiếng ồn tạo ra để phát hiện sớm hư hỏng trong bộ truyền động của tuabin gió.', 'Tin chuyên ngành', 'DMT là đối tác tin cậy để tối ưu hóa trang trại điện gió của bạn', 'giai-phap-giam-sat-toi-uu-hoa-trang-trai-dien-gio', NULL, NULL, 'DMT là đối tác tin cậy để tối ưu hóa trang trại điện gió của bạn', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (475, 'vi', 'DMT cung cấp dịch vụ tư vấn đo lường chuyên nghiệp và các dịch vụ khác trong lĩnh vực điện gió.', 'Tin chuyên ngành', 'DMT nhà cung cấp dịch vụ kiểm tra, tư vấn, đo lường hàng đầu trong ngành công nghiệp điện gió', 'dmt-nha-cung-cap-dich-vu-kiem-tra-tu-van-do-luong-hang-dau-trong-nganh-cong-nghiep-dien-gio', NULL, NULL, 'DMT nhà cung cấp dịch vụ kiểm tra, tư vấn, đo lường hàng đầu trong ngành công nghiệp điện gió', 'dmt, điện gió, thiết bị điện gió,') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (476, 'vi', 'Sáng ngày 1/6 /2021 vừa qua, công ty CP Công nghệ và Tư vấn CIC cùng hãng phần mềm PTV Group (Đức) đã phối hợp tổ chức thành công Hội thảo trực tuyến về “Giải pháp quản lý Giao thông thông minh theo thời gian thực”.', 'Tin công ty', 'Hội thảo về “Giải pháp quản lý Giao thông thông minh theo thời gian thực” do công ty CIC và hãng PTV Group phối hợp tổ chức đã diễn ra thành công tốt đẹp', 'hoi-thao-ve-giai-phap-quan-ly-giao-thong-thong-minh-theo-thoi-gian-thuc-do-cong-ty-cic-va-hang-ptv-group-phoi-hop-to-chuc-da-dien-ra-thanh-cong-tot-dep', NULL, NULL, 'Hội thảo về “Giải pháp quản lý Giao thông thông minh theo thời gian thực” thành công tốt đẹp', 'ptv, giao thông, phần mềm giao thông') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (477, 'vi', 'Hãng CSI (Computers and Structures, Inc.) vừa ra mắt phiên bản SAP2000 v23.2.0 và CSiBridge 23.2.0 hoàn toàn mới, dưới đây là những tính năng mới nổi bật của hai phần mềm này', 'Tin chuyên ngành', 'Phát hành SAP2000 v23.2.0 và CSiBridge 23.2.0', 'phat-hanh-sap2000-v2320-va-csibridge-2320', NULL, NULL, 'Phát hành SAP2000 v23.2.0 và CSiBridge 23.2.0', 'sap2000, csixrevit, csi, BIM, Autodesk') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (478, 'vi', 'Với giao diện Tiếng Việt, Cubicost TASC mong muốn mang đến trải nghiệm thuận tiện và dễ dàng hơn cho tất cả mọi người. Và đây cũng là mong muốn của nhiều người dùng Cubicost TASC từ trước cho đến nay.', 'Tin chuyên ngành', 'Phần mềm BIM 5D Cubicost TASC ra mắt phiên bản tiếng Việt', 'phan-mem-bim-5d-cubicost-tasc-ra-mat-phien-ban-tieng-viet', NULL, NULL, 'Phần mềm BIM 5D Cubicost TASC ra mắt phiên bản tiếng Việt', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (479, 'vi', 'Hệ thống đường dây truyền tải điện Việt Nam là một mạng lưới cơ sở hạ tầng kỹ thuật phức tạp. Từ hàng trăm nhà máy điện các loại được dẫn bằng hệ thống lưới điện trên 8.000 km đường dây 500kV, gần 16.500 km đường dây 220kV phân phối điện đến các khu công nghiệp, hộ dân tiêu thu,… cho thấy quy mô và tầm quan trọng của hệ thống đường dây truyền tải điện. Để đảm bảo cung cấp đủ điện cho phát triển kinh tế xã hội của đất nước và đời sống của nhân dân thì việc giám sát đảm bảo an toàn cho đường dây truyền tải điện trước sự hao mòn do thời gian, sự cố do nắng nóng, mưa bão sạt lở là thực sự cần thiết. Hiểu rõ vấn đề gặp phải của ngành điện, Công ty Cổ phần Công nghệ và Tư vấn CIC đã hợp tác cùng hãng LineVision giới thiệu “Hệ thống LineVision V3 - Giải pháp giám sát đường dây truyền tải điện” nhằm giải quyết vấn đề này.', 'Tin chuyên ngành', 'Giải pháp giám sát đường dây truyền tải điện', 'giai-phap-giam-sat-duong-day-truyen-tai-dien', NULL, NULL, 'Giải pháp giám sát đường dây truyền tải điện', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (480, 'vi', 'Vừa qua công ty CIC và công ty Cổ phần xây dựng CENTRAL (www.centralcons.vn) đã cùng nhau ký kết bản hợp đồng, theo đó CIC sẽ cung cấp số lượng lớn bản quyền phần mềm vẽ kỹ thuật enjiCAD cho công ty CENTRAL để phục vụ các công việc hiện thời.', 'Tin công ty', 'CIC Cung cấp số lượng lớn phần mềm vẽ kỹ thuật enjiCAD cho công ty CENTRAL', 'cic-cung-cap-so-luong-lon-phan-mem-ve-ky-thuat-enjicad-cho-cong-ty-central', NULL, NULL, 'CIC Cung cấp số lượng lớn phần mềm vẽ kỹ thuật enjiCAD cho công ty CENTRAL', '') ON CONFLICT (entity_id, locale) DO NOTHING;
