INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (486, 'vi', 'Công ty cổ phần Công nghệ và tư vấn CIC phối hợp cùng trang thông tin điện tử Nghenoithat.vn và Hãng phần mềm Pytha Lab (Đức) tổ chức hội thảo trực tuyến với chủ đề “Giải pháp công nghệ nâng cao hiệu quả thiết kế và sản xuất nội thất gỗ”', 'Tin công ty', 'Webinar online với chủ đề “Giải pháp công nghệ nâng cao hiệu quả thiết kế và sản xuất nội thất gỗ”', 'webinar-online-voi-chu-de-giai-phap-cong-nghe-nang-cao-hieu-qua-thiet-ke-va-san-xuat-noi-that-go', NULL, NULL, 'Webinar online với chủ đề “Giải pháp công nghệ nâng cao hiệu quả thiết kế và sản xuất nội thất gỗ”', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (487, 'vi', 'Hệ thống giám sát đường dây truyền tải ASTROSE dựa trên việc giám sát cục bộ đường đây điện, các cảm biến sẽ được lắp trực tiếp trên đường dây, chúng hoạt động độc lập và sử dụng nguồn năng lượng từ đường dây giúp việc thu thập dữ liệu chính xác, thời gian hoạt động liên tục dài, liên tục. Thiết bị được thiết kế để sử dụng suốt vòng đời của dự án giám sát.', 'Tin chuyên ngành', 'Giám sát truyền tải điện với ASTROSE', 'giam-sat-truyen-tai-dien-voi-astrose', NULL, NULL, 'Giám sát truyền tải điện với ASTROSE', 'ASTROSE, giám sát truyền tải điện') ON CONFLICT (entity_id, locale) DO NOTHING;
