INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (491, 'vi', 'Khả năng chống cháy là khả năng của một kết cấu tòa nhà chống lại các tác động của đám cháy đã phát triển toàn diện mà không làm mất đi khả năng chịu tải, tính ổn định, tính toàn vẹn và cách nhiệt của nó. Chúng ta phải đối mặt với những trạng thái giới hạn nào, và làm thế nào để một kỹ sư kết cấu đánh giá đúng ảnh hưởng của lửa?', 'Tin chuyên ngành', 'Phương pháp và quy định - Kiểm tra khả năng chống cháy, ứng dụng với IdeaStatica Concrete', 'phuong-phap-va-quy-dinh---kiem-tra-kha-nang-chong-chay-ung-dung-voi-ideastatica-concrete', NULL, NULL, 'Phương pháp và quy định - Kiểm tra khả năng chống cháy, ứng dụng với IdeaStatica Concrete', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (492, 'vi', 'Bản phát hành mới nhất của ADAPT-Builder (Phiên bản 20.0.1) bao gồm các cải tiến đối với đầu vào mô hình, chỉnh màu và hiển thị kết quả.', 'Tin chuyên ngành', 'Cải tiến tính năng trong phần mềm ADAPT-Builder v20.0.1 mới phát hành', 'cai-tien-tinh-nang-trong-phan-mem-adapt-builder-v2001-moi-phat-hanh', NULL, NULL, 'Cải tiến tính năng trong phần mềm ADAPT-Builder v20.0.1 mới phát hành', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (493, 'vi', 'Ngày 27/7 vừa qua, Công ty CP Công nghệ và Tư vấn CIC phối hợp với Hãng phần mềm Opera đã tổ chức thành công buổi hội thảo trực tuyến để giới thiệu về những tính năng, ưu điểm vượt trội của phần mềm Opera – giải pháp hiệu quả cho nhà thầu nhôm kính.', 'Tin công ty', 'Opera webinar: “Giải pháp công nghệ cho các nhà thầu nhôm kính”', 'opera-webinar:-giai-phap-cong-nghe-cho-cac-nha-thau-nhom-kinh', NULL, NULL, 'Opera webinar: “Giải pháp công nghệ cho các nhà thầu nhôm kính”', 'phần mềm nội thất, phần mềm nhôm kính') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (494, 'vi', 'Vào 14:00 giờ chiều ngày 25/08/2021, Công ty Cổ phần Công nghệ và Tư vấn CIC sẽ tổ chức hội thảo online với chủ đề "Robot cống ngầm cho kiểm tra, vệ sinh và sửa chữa đường cống thoát nước’’', 'Tin công ty', 'CIC và hãng Sewer Robotics (Hà Lan) tổ chức hội thảo “Robot cống ngầm cho kiểm tra, vệ sinh và sửa chữa đường cống thoát nước’’', 'cic-to-chuc-hoi-thao-online-voi-chu-de-robot-cong-ngam-cho-kiem-tra-ve-sinh-va-sua-chua-duong-cong-thoat-nuoc’’', NULL, NULL, 'CIC tổ chức hội thảo online với chủ đề “Robot cống ngầm cho kiểm tra, vệ sinh và sửa chữa đường cống', '') ON CONFLICT (entity_id, locale) DO NOTHING;
