INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (496, 'vi', 'Trong enjiCAD có một lệnh rất hay và hữu ích, giúp chúng ta có thể lựa chọn, lọc ra các đối tượng có cùng tính chất nhanh chóng và dễ dàng. Hôm nay chúng ta cùng tìm hiểu về các thuộc tính và cách sử dụng lệnh SELECTSIMILAR để có thể tăng tốc độ thiết kế nhé.', 'Tin chuyên ngành', 'Sử dụng lệnh SELECTSIMILAR trong enjiCAD', 'su-dung-lenh-selectsimilar-trong-enjicad', NULL, NULL, 'Sử dụng lệnh SELECTSIMILAR trong enjiCAD', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (497, 'vi', 'Lĩnh vực điện gió ngoài khơi trên toàn cầu đã chứng kiến nhiều cú nhảy trong năm 2018 và vẫn đang tiếp tục phát triển nhanh chóng. Theo ước tính, vào năm 2030 lĩnh vực này có thể đạt hơn 115GW công suất lắp đặt trên toàn cầu và Cơ quan Năng lượng Quốc tế dự tính sẽ phát triển đến 200GW vào năm 2040. Điện gió nổi là lĩnh vực thu hút nhiều nhà phát triển cũng như các nhà thầu trong lĩnh vực dầu khí đang tìm cách đang dạng hóa ngành này.', 'Tin chuyên ngành', 'Webinar | OpenWindPower Floating Platform: Giải pháp cho thiết kế Tua-bin gió nổi ngoài khơi', 'webinar--openwindpower-floating-platform:-giai-phap-cho-thiet-ke-tua-bin-gio-noi-ngoai-khoi', NULL, NULL, 'Webinar | OpenWindPower Floating Platform: Giải pháp cho thiết kế Tua-bin gió nổi ngoài khơi', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (498, 'vi', 'Cuối tháng 8/2021, Công ty CIC đã hoàn thành bàn giao phần mềm mô phỏng hậu quả DNV PHAST cho Công ty PTSC MC. CIC là đại diện được ủy quyền chính thức ở Việt Nam của hãng DNV, cung cấp các phần mềm PHAST, SAFETI, LEAK, USFOS, SESAM, SYNERGI LIFE…', 'Tin công ty', 'CIC hoàn thành cung cấp phần mềm PHAST của hãng DNV (Na Uy)', 'cic-cung-cap-phan-mem-usfos-cua-hang-dnvgl-cho-cong-ty-tnhh-dich-vu-co-khi-hang-hai-ptsc-mc', NULL, NULL, 'CIC hoàn thành cung cấp phần mềm PHAST của hãng DNV (Na Uy)', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (499, 'vi', 'Công ty Cổ phần Công nghệ và Tư vấn CIC đã cung cấp phần mềm Usfos cho Công ty TNHH Dịch vụ Cơ khí Hàng hải (PTSC MC) nhằm thực hiện dự án Gallaf Batch 3 EPC 05 thuộc mỏ Al-Shaheen nằm tại vùng biển ngoài khơi Qatar và cũng là một trong những mỏ dầu ngoài khơi lớn nhất thế giới.', 'Tin công ty', 'CIC cung cấp phần mềm USFOS cho PTSC MC phục vụ dự án Dự án Gallaf', 'cic-cung-doi-tac-cua-minh-dnv-cung-cap-phan-mem-usfos-cho-ptsc-mc-phuc-vu-du-an-du-an-gallaf', NULL, NULL, 'CIC cung cấp phần mềm USFOS cho PTSC MC phục vụ dự án Dự án Gallaf', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (500, 'vi', 'Chiều ngày 25/08/2021 vừa qua, công ty CP Công nghệ và Tư vấn CIC kết hợp với hãng Sew Robotics đã tổ chức thành công hội thảo trực tuyến về giải pháp Robot cống ngầm, với chủ đề “Robot cống ngầm cho kiểm tra, vệ sinh và sửa chữa đường cống thoát nước”', 'Tin công ty', 'Báo cáo kết quả hội thảo trực tuyến về Robot cống ngầm', 'bao-cao-ket-qua-hoi-thao-truc-tuyen-ve-robot-cong-ngam', NULL, NULL, 'Báo cáo kết quả hội thảo trực tuyến về Robot cống ngầm', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (501, 'vi', 'Một trong những thách thức lớn nhất trong ngành xây dựng đến từ các đội khác nhau làm việc trong cùng một dự án. Các quy trình làm việc riêng biệt này có thể dẫn đến thông tin sai lệch, các vấn đề phối hợp và nhiều rủi ro khác nhau do thiếu cộng tác.', 'Tin chuyên ngành', 'Khả năng tương tác trong ngành AEC', 'kha-nang-tuong-tac-trong-nganh-aec', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (502, 'vi', 'BIM được phát triển dựa trên nền tảng công nghệ số, đang được áp dụng rộng rãi trong ngành Xây dựng ở nhiều quốc gia và được coi là một trong những giải pháp quan trọng để tiếp cận cuộc cách mạng công nghiệp 4.0 trong ngành Xây dựng.', 'Tin công ty', 'Hội thảo "Chuyển đổi số dành cho các kỹ sư kết cấu công trình với giải pháp BIM - Allplan"', 'ung-dung-bim–-allplan-trong-ket-cau-cong-trinh-–-nhung-du-an-thuc-te-mang-lai-hieu-qua-cao', NULL, NULL, 'Hội thảo "Chuyển đổi số dành cho các kỹ sư kết cấu công trình với giải pháp BIM - Allplan"', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (503, 'vi', 'Các công nghệ đột phá mới trên nền tảng kỹ thuật của Ansys mang lại một cái nhìn sâu sắc hơn về kỹ thuật khả năng tiếp cận nhanh và sự đơn giản hóa cao.', 'Tin chuyên ngành', 'Phần mềm Ansys 2021 - Giải pháp tăng tốc trong sản xuất, phát triển sản phẩm mới', 'phan-mem-ansys-2021-giai-phap-tang-toc-trong-san-xuat-phat-trien-san-pham-moi', NULL, NULL, 'Phần mềm Ansys 2021 - Giải pháp tăng tốc trong sản xuất, phát triển sản phẩm mới', 'ansys') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (504, 'vi', 'Tình hình dịch bệnh Covid 19 đang rất phức tạp, khi cả nước thực hiện “ai ở đâu, ở yên tại đó” chúng ta đều hiểu sẽ phải đối mặt một giai đoạn đầy khó khăn, thách thức.INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (505, 'vi', 'Có một số xu hướng hiện đại đang định hình tương lai của các dự án BIM. Dưới đây là một số xu hướng quan trọng nhất trong BIM.', 'Tin chuyên ngành', 'Các xu hướng hàng đầu trong BIM hiện nay', 'cac-xu-huong-hang-dau-trong-bim-hien-nay', NULL, NULL, 'Các xu hướng hàng đầu trong BIM hiện nay', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (506, 'vi', 'Ngày 15/09 vừa qua, Công ty CP Công nghệ và Tư vấn CIC đã phối hợp cùng Công ty GSI, hãng ALLPLAN của Đức và Viện Kinh tế Xây dựng tổ chức thành công hội thảo trực tuyến với chuyên đề &quot;Chuyển đổi số dành cho các kỹ sư kết cấu công trình với giải pháp BIM-Allplan&quot;.', 'Tin công ty', 'Gần 500 kỹ sư và chuyên gia xây dựng đã tham dự hội thảo trực tuyến &quot;Chuyển đổi số dành cho các kỹ sư kết cấu công trình với giải pháp BIM-Allplan&quot; do CIC và Viện kinh tế xây dựng tổ chức', 'gan-500-ky-su-va-chuyen-gia-xay-dung-da-tham-du-hoi-thao-truc-tuyen--chuyen-doi-so-danh-cho-cac-ky-su-ket-cau-cong-trinh-voi-giai-phap-bim-allplan--do-cic-va-vien-kinh-te-xay-dung-to-chuc', NULL, NULL, 'Gần 500 kỹ sư và chuyên gia xây dựng đã tham dự hội thảo trực tuyến &quot;Chuyển đổi số dành cho các kỹ s', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (507, 'vi', 'Compal Electronics kết hợp với Ansys tăng tốc phát triển sản phẩm máy tính xách tay 5GINSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (508, 'vi', 'CIC xin trân trọng gửi đến Quý Cơ quan, Tổ chức thông tin về buổi hội thảo trực tuyến với chủ đề: Ứng dụng phần mềm PTV trong mô phỏng giao thông tại Việt Nam.', 'Tin chuyên ngành', 'THƯ MỜI THAM DỰ HỘI THẢO TRỰC TUYẾN: ỨNG DỤNG PHẦN MỀM PTV TRONG MÔ PHỎNG GIAO THÔNG TẠI VIỆT NAM', 'thu-moi-tham-du-hoi-thao-truc-tuyen:-ung-dung-phan-mem-ptv-trong-mo-phong-giao-thong-tai-viet-nam', NULL, NULL, 'THƯ MỜI THAM DỰ HỘI THẢO TRỰC TUYẾN: ỨNG DỤNG PHẦN MỀM PTV TRONG MÔ PHỎNG GIAO THÔNG TẠI VIỆT NAM', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (510, 'vi', 'Có một số điểm tương đồng chính giữa Digital Twin và BIM (Building Information Modeling). BIM tập trung vào thiết kế và xây dựng của một tòa nhà. Digital Twin mô hình hóa cách mọi người tương tác với các môi trường xây dựng.', 'Tin chuyên ngành', 'Cặp song sinh kỹ thuật số (Digital Twins) so với Xây dựng mô hình thông tin (BIM)', 'cap-song-sinh-ky-thuat-so-digital-twins-so-voi-xay-dung-mo-hinh-thong-tin-bim', NULL, NULL, 'Cặp song sinh kỹ thuật số (Digital Twins) so với Xây dựng mô hình thông tin (BIM)', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (511, 'vi', 'Ở phiên bản SP1 được ra mắt vào ngày 8/6 vừa qua, đã có nhiều tính năng được chỉnh sửa hoàn thiện cũng như khắc phục những lỗi trong quá trình sử dụng. Cùng điểm qua một vài thay đổi ở phiên bản SP1 lần này.', 'Tin chuyên ngành', 'enjiCAD đã chính thức phát hành phiên bản enjiCAD 2021 SP2', 'enjicad-da-chinh-thuc-phat-hanh-phien-ban-enjicad-2021-sp2', NULL, NULL, 'enjiCAD đã chính thức phát hành phiên bản enjiCAD 2021 SP2', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (509, 'vi', 'Mới đây, phần mềm mô phỏng hậu quả DNV PHAST đã phát hành phiên bản mới v8.4 với nhiều cải tiến về tính năng và độ chính xác.', 'Tin chuyên ngành', 'Phần mềm mô phỏng hậu quả DNV PHAST phát hành phiên bản mới v8.4', 'phan-mem-mo-phong-hau-qua-dnv-phast-phat-hanh-phien-ban-moi-v84', NULL, NULL, 'Phần mềm mô phỏng hậu quả DNV PHAST phát hành phiên bản mới v8.4', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (512, 'vi', 'Allplan là phần mềm BIM hiếm hoi được công  nhận về mặt triển khai tốt nhất bản vẽ 2D (all in one). Allplan kết hợp các công cụ mạnh mẽ dùng để tạo bản vẽ 2D chứa các yếu tố CAD cần thiết. Điểm mạnh của Allplan nằm ở độ tin cậy và chính xác khi triển khai bản vẽ. Phần mềm cung cấp nhiều công cụ vẽ đối tượng 2D và các khối hình học 3D một cách dễ dàng.', 'Tin chuyên ngành', 'Chức năng CAD trong Allplan', 'chuc-nang-cad-trong-allplan', NULL, NULL, 'Chức năng CAD trong Allplan', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (513, 'vi', 'GeoSIG với chuyên môn hơn 25 năm cung cấp các giải pháp giám sát kết cấu, có thể đáp ứng trong việc giám sát mọi kết cấu khó khăn nhất.', 'Tin chuyên ngành', 'Giám sát kết cấu công trình với GeoSIG', 'giam-sat-ket-cau-cong-trinh-voi-geosig', NULL, NULL, 'Giám sát kết cấu công trình với GeoSIG', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (514, 'vi', '', 'Tin chuyên ngành', 'THƯ MỜI THAM DỰ HỘI THẢO TRỰC TUYẾN: PIPENET CHO CÁC ỨNG DỤNG LNG (KHÍ THIÊN NHIÊN HÓA LỎNG)', 'thu-moi-tham-du-hoi-thao-truc-tuyen:-pipenet-cho-cac-ung-dung-lng-khi-thien-nhien-hoa-long', NULL, NULL, 'THƯ MỜI THAM DỰ HỘI THẢO TRỰC TUYẾN: PIPENET CHO CÁC ỨNG DỤNG LNG (KHÍ THIÊN NHIÊN HÓA LỎNG)', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (515, 'vi', 'Để hoàn thiện hơn trong chuỗi giải pháp BIM 5D Cubicost, Glodon sẽ chính thức ra mắt sản phẩm TME C nhằm phục vụ cho công tác đo bóc khối lượng trong hệ thống MEP. Bên cạnh các giải pháp TAS C, TRB C, TBQ C phục vụ cho công tác bóc tách khối lượng kiến trúc kết cấu và dự toán, thì TME C sẽ là sản phẩm cuối cùng để khép kín được quy trình BIM 5D.   Buổi ra mắt sẽ được tổ chức ở Singapore bằng tiếng Anh vào lúc 10h sáng (GMT+8)  tức 9h sáng theo giờ Việt Nam do Glondon international tổ chức.', 'Tin công ty', 'Cubicost TMEC ra mắt - Đổi mới bóc tách khối lượng MEP trên nền tảng BIM - Trải nghiệm nâng cao MEP QTO', 'cubicost-tmec-ra-mat---doi-moi-boc-tach-khoi-luong-mep-tren-nen-tang-bim---trai-nghiem-nang-cao-mep-qto', NULL, NULL, 'Cubicost TMEC ra mắt - Đổi mới bóc tách khối lượng MEP trên nền tảng BIM - Trải nghiệm nâng cao MEP', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (516, 'vi', 'ALLPLAN giúp các kiến trúc sư, kỹ sư, nhà thiết kế bê tông đúc sẵn và nhà thầu khẳng định vị thế trong ngành AEC trong tương lai khi ngành này trải qua quá trình chuyển đổi số. ALLPLAN giải quyết toàn bộ quy trình “Thiết kế đến Thi công”, từ ý tưởng đầu tiên đến thiết kế chi tiết cuối cùng cho địa điểm xây dựng và các yếu tố tiền chế.', 'Tin chuyên ngành', 'BUILD THE FUTURE - ALLPLAN GLOBAL SUMMIT', 'build-the-future---allplan-global-summit', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (517, 'vi', 'Trong những năm gần đây, xu hướng chuyển đổi số và ứng dụng công nghệ 4.0 ngày càng được quan tâm và từng bước được áp dụng mang lại hiệu quả tốt cho nhiều doanh nghiệp tại Việt Nam. Đặc biệt trong lĩnh vực nội thất và vật liệu xây dựng, các giải pháp chuyển đổi số phục vụ hoạt động kinh doanh trên môi trường mạng internet đang ngày càng chiếm ưu thế với tình hình dịch bệnh Covid-19 hiện nay.', 'Tin chuyên ngành', 'Hội thảo trực tuyến với chủ đề “Các giải pháp chuyển đổi số trong kinh doanh Nội thất và Vật liệu xây dựng’’', 'hoi-thao-truc-tuyen-voi-chu-de-cac-giai-phap-chuyen-doi-so-trong-kinh-doanh-noi-that-va-vat-lieu-xay-dung’’', NULL, NULL, 'Hội thảo trực tuyến với chủ đề “Các giải pháp chuyển đổi số trong kinh doanh Nội thất và Vật liệu xâ', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (518, 'vi', 'Ngày 04/10/2021, Công ty Cổ phần Công nghệ và Tư vấn CIC và Công ty TNHH Dịch vụ Cơ khí Hàng Hải PTSC M&C đã cùng ký kết hợp đồng cung cấp phần mềm Ansys Mechanical Pro và Ansys Discovery Modeling.', 'Tin công ty', 'CIC cung cấp phần mềm Ansys Mechanical Pro và Ansys Discovery Modeling cho cho PTSC M&C', 'cic-cung-cap-phan-mem-ansys-mechanical-pro-va-ansys-discovery-modeling-cho-cho-ptsc-mamp;c', NULL, NULL, 'CIC cung cấp phần mềm Ansys Mechanical Pro và Ansys Discovery Modeling cho cho PTSC M&C', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (519, 'vi', 'Allplan Bridge là giải pháp BIM chuyên nghiệp để hỗ trợ các công trình cầu đường. Các kỹ sư làm việc với một phần mềm duy nhất từ bước tạo mô hình tham số bao gồm thành phần dự ứng lực đến việc tích hợp tiến độ xây dựng cũng như phân tích kết cấu, thiết lập mô hình cốt thép 3D và các bản vẽ triển khai.', 'Tin chuyên ngành', 'ALLPLAN BRIGDE – Giải pháp BIM chuyên dụng cho kỹ sư thiết kế công trình cầu đường', 'allplan-brigde-–-giai-phap-bim-chuyen-dung-cho-ky-su-thiet-ke-cong-trinh-cau-duong', NULL, NULL, 'ALLPLAN BRIGDE – Giải pháp BIM chuyên dụng cho kỹ sư thiết kế công trình cầu đường', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (520, 'vi', 'Allplan là một trong những giải pháp phần mềm triểu khai bản mô hình, bản vẽ kĩ thuật tương đối hiệu quả trong xây dựng. Trên thị trường ngành xây dựng hiện tại, ngoài công cụ AutoCAD truyền thống, có rất nhiều phần mềm BIM làm tốt công việc này. Vậy, tại sao nên chọn Allplan làm giải pháp triển khai mô hình, bản vẽ kĩ thuật khi thiết kế công trình xây dựng?', 'Tin chuyên ngành', 'TẠI SAO NÊN CHỌN ALLPLAN LÀM GIẢI PHÁP TRIỂN KHAI MÔ HÌNH, BẢN VẼ KĨ THUẬT TRONG XÂY DỰNG?', 'tai-sao-nen-chon-allplan-lam-giai-phap-trien-khai-mo-hinh-ban-ve-ki-thuat-trong-xay-dung', NULL, NULL, 'TẠI SAO NÊN CHỌN ALLPLAN LÀM GIẢI PHÁP TRIỂN KHAI MÔ HÌNH, BẢN VẼ KĨ THUẬT TRONG XÂY DỰNG?', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (521, 'vi', 'BIM được phát triển dựa trên nền tảng công nghệ số, đang được áp dụng rộng rãi trong ngành Xây dựng ở nhiều quốc gia và được coi là một trong những giải pháp quan trọng để tiếp cận cuộc cách mạng công nghiệp 4.0 trong ngành Xây dựng.', 'Tin chuyên ngành', 'ỨNG DỤNG BIM – ALLPLAN TRONG KẾT CẤU CÔNG TRÌNH – NHỮNG DỰ ÁN THỰC TẾ MANG LẠI HIỆU QUẢ CAO', 'ung-dung-bim-–-allplan-trong-ket-cau-cong-trinh-–-nhung-du-an-thuc-te-mang-lai-hieu-qua-cao', NULL, NULL, 'ỨNG DỤNG BIM – ALLPLAN TRONG KẾT CẤU CÔNG TRÌNH – NHỮNG DỰ ÁN THỰC TẾ MANG LẠI HIỆU QUẢ CAO', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (522, 'vi', 'Cột bê tông cốt thép, dầm bê tông cốt thép là cấu kiện quan trọng thường được sử dụng rộng rãi trong các tòa nhà cao tầng. Các kỹ sư luôn phải xem xét cách để có thể gia cố cốt thép trên mô hình một cách nhanh chóng cũng như tạo những bản vẽ thi công một cách nhanh chóng và hiệu quả.', 'Tin chuyên ngành', 'ALLPLAN – TÍNH NĂNG TỰ ĐỘNG GIA CỐ CHO CỘT, DẦM BÊ TÔNG CỐT THÉP', 'allplan-–-tinh-nang-tu-dong-gia-co-cho-cot-dam-be-tong-cot-thep', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (523, 'vi', 'Từ việc lên ý tưởng ban đầu cho đến việc triển khai hiệu quả trên công trường, Allplan AEC 2022 mang đến phương pháp làm việc tích hợp cho các Kiến trúc sư, Kỹ sư và Nhà thầu trên một nền tảng duy nhất. Khả năng xây dựng ở mức tốt nhất được hỗ trợ bởi các quy trình công việc được liên kết liền mạch giúp rút ngắn các quy trình phối hợp, tăng năng suất và giá trị.', 'Tin chuyên ngành', 'PHIÊN BẢN MỚI ALLPLAN AEC 2022 – GIẢI PHÁP BIM TỐT NHẤT CHO NGÀNH XÂY DỰNG', 'phien-ban-moi-allplan-aec-2022-–-giai-phap-bim-tot-nhat-cho-nganh-xay-dung', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (524, 'vi', 'Ngày 23/10 vừa qua, các học viên tham gia Khóa đào tạo sử dụng phần mềm BIM – Cubicost tại Công ty Cổ phần Fecon đã chính thức hoàn thành khóa học kéo dài gần 2 tháng và nhận được chứng chỉ phần mềm Cubicost TASC từ CIC.', 'Tin công ty', 'HOÀN THÀNH KHÓA ĐÀO TẠO PHẦN MỀM BIM – CUBICOST DÀNH CHO FECONERS KHỐI KỸ THUẬT', 'hoan-thanh-khoa-dao-tao-phan-mem-bim-–-cubicost-danh-cho-feconers-khoi-ky-thuat', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (525, 'vi', 'Mô hình hóa thông tin công trình 4D (BIM) là quá trình sử dụng mô hình 3D, kết hợp với thông tin liên quan đến thời gian và tiến độ, để tạo ra một chuỗi xây dựng ảo. Nói một cách đơn giản, mô hình 3D + thông tin thời gian = 4D.', 'Tin chuyên ngành', '4D BIM: Nó có nghĩa là gì, các công ty xây dựng sẽ tham gia như thế nào?', '4d-bim:-no-co-nghia-la-gi-cac-cong-ty-xay-dung-se-tham-gia-nhu-the-nao', NULL, NULL, '4D BIM: Nó có nghĩa là gì, các công ty xây dựng sẽ tham gia như thế nào?', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (526, 'vi', '', 'Quan hệ cổ đông', 'Nghị quyết HĐQT v/v hủy đăng ký giao dịch Upcom và hủy đăng ký cổ phiếu tại VSD', 'nghi-quyet-hdqt-vv-huy-dang-ky-giao-dich-upcom-va-huy-dang-ky-co-phieu-tai-vsd', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (527, 'vi', 'Mỗi năm công nghệ BIM ngày càng phát triển và trở nên phổ biến, rất nhanh chóng sẽ không ai còn ngạc nhiên về việc sử dụng BIM trong thiết kế. Trong một thị trường đang phát triển, các công ty thấy mình phải phát triển các phương pháp tiếp cận độc đáo khi làm việc với BIM để tạo sự khác biệt với các đối thủ cạnh tranh của họ.', 'Tin chuyên ngành', 'Cách tiếp cận 8 bước cho phép các công ty phân biệt các dịch vụ BIM của họ', 'cach-tiep-can-8-buoc-cho-phep-cac-cong-ty-phan-biet-cac-dich-vu-bim-cua-ho', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (528, 'vi', 'Allplan Brigde 2022 sử dụng một mô hình thông số duy nhất cho hình học, phân tích nội lực, thiết kế và triển khai cốt thépINSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (529, 'vi', 'Allplan Engineering Building 2022 là giải pháp BIM tối ưu dành cho các kỹ sư dân dụng và các dự án kết cấu dân dụng. Kết cấu bê tông có hình học phức tạp, có thể được mô hình hóa đầy đủ, gia cố và chi tiết một cách nhanh chóng và hiệu quả.INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (530, 'vi', 'CIC “Cung cấp Thiết bị định vị tuyến cáp ngầm RD8200 của hãng RadioDetection cho Công ty Điện lực Hoàn Kiếm', 'Tin công ty', 'CIC “Cung cấp Thiết bị dò tuyến cáp ngầm” cho Công ty Điện lực Hoàn Kiếm', 'cic-cung-cap-thiet-bi-do-tuyen-cap-ngam-cho-cong-ty-dien-luc-hoan-kiem', NULL, NULL, 'CIC “Cung cấp Thiết bị dò tuyến cáp ngầm” cho Công ty Điện lực Hoàn Kiếm', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (531, 'vi', 'PTV Group đang có chương trình khuyến mại lớn nhất năm, áp dụng từ 01/11/2021 đến 17/12/2021!', 'Tin khuyến mại', 'Chương trình khuyến mại lớn nhất năm của PTV Group', 'chuong-trinh-khuyen-mai-lon-nhat-nam-cua-ptv-group', NULL, NULL, 'Chương trình khuyến mại lớn nhất năm của PTV Group', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (532, 'vi', 'Planbar là giải pháp độc đáo của ALLPLAN để vẽ chi tiết các cấu kiện bê tông đúc sẵn cho phép tạo dữ liệu sản xuất đáng tin cậy INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (533, 'vi', 'Allplan Basic là công cụ mạnh mẽ dùng để tạo bản vẽ 2D chứa các yếu tố CAD cần thiết. Điểm mạnh của Allplan Basic nằm ở độ tin cậy và chính xác khi triển khai bản vẽ. Phần mềm cung cấp nhiều công cụ vẽ đối tượng 2D và các khối hình học 3D một cách dễ dàng', 'Tin chuyên ngành', 'ALLPLAN BASIC', 'allplan-basic', NULL, NULL, 'ALLPLAN BASIC', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (534, 'vi', 'Từ 21/11/2021 tới 22/01/2022, Piletest thực hiện chương trình khuyến mãi đặc biệt khi mua thiết bị PET với ưu đãi giảm giá lên tới 20%', 'Tin khuyến mại', 'Chương trình khuyến mại cho thiết bị kiểm tra biến dạng nhỏ của cọc PET - Hãng Piletest (Israel)', 'chuong-trinh-khuyen-mai-cho-thiet-bi-kiem-tra-bien-dang-nho-cua-coc-pet-hang-piletest-israel', NULL, NULL, 'Chương trình khuyến mại cho thiết bị kiểm tra biến dạng nhỏ của cọc PET - Hãng Piletest (Israel)', 'siêu âm cọc khoan nhồi, cọc khoan nhồi, piletest, siêu âm cọc, CHUM, khuyến mãi') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (535, 'vi', 'Bộ công cụ BIM quốc tế được thiết kế để giải quyết khoảng cách về kiến thức và cung cấp một bộ công cụ để đưa BIM vào thực tiễn mua sắm công và thực hiện dự án. Bộ công cụ là một bộ tài liệu mẫu và hướng dẫn, phù hợp với tiêu chuẩn ISO 19650 và bao gồm các thành phần chính tạo điều kiện thuận lợi cho việc triển khai các quy trình quản lý thông tin cho các tổ chức ở mọi cấp độ áp dụng BIM.INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (536, 'vi', 'Với dự án ở Hausleiten, nhóm xây dựng Peri 3D đã hoàn thành 5 dự án bằng công nghệ in 3D trong một năm: ngôi nhà in đầu tiên ở miền Bắc nước Đức , ngôi nhà dành cho nhiều gia đình đầu tiên và tòa nhà in lớn nhất ở châu Âu , ngôi nhà in đầu tiên ở Mỹ. (Tempe / Arizona), và một phần mở rộng tòa nhà chung cư ở miền nam nước Đức', 'Tin chuyên ngành', 'Strabag và Peri xây dựng tòa văn phòng lớn nhất Châu Âu bằng công nghệ 3D', 'strabag-va-peri-xay-dung-toa-van-phong-lon-nhat-chau-au-bang-cong-nghe-3d', NULL, NULL, 'Strabag và Peri xây dựng tòa văn phòng lớn nhất Châu Âu bằng công nghệ 3D', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (537, 'vi', '', 'Quan hệ cổ đông', 'CBTT Đơn xin từ nhiệm chức danh thành viên HĐQT của Ông Đặng Quyết Thắng', 'cbtt-don-xin-tù-nhiẹm-chúc-danh-thành-vien-hdqt-của-ong-dang-quyet-thang', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (538, 'vi', 'enjiCAD được biết đến là một phần mềm thiết kế hiệu quả và chính xác với tốc độ xử lý cao, đó cũng là lý do khiến cho enjiCAD trở thành phần mềm CAD được người sử dụng tin dùng. Sau thời gian phát triển và liên tục cải tiến, enjiCAD nay càng được nâng cao hiệu suất và các chỉ số khác để dần đáp ứng tốt nhất nhu cầu của người sử dụng.', 'Tin chuyên ngành', 'enjiCAD 2022 chính thức phát hành', 'enjicad-2022-chinh-thuc-phat-hanh', NULL, NULL, 'enjiCAD 2022 chính thức phát hành', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (539, 'vi', 'Với sự phát triển nhanh chóng của xây dựng dân dụng và nhu cầu sử dụng điện gia tang trong những năm gần đây yêu cầu hệ thống truyền tải điện phát triển đáng kể. Đồng thời việc quản lý hiệu quả của hệ thống truyền tải quy mô lớn này và đảm bảo hệ thống truyền tải hoạt động ổn định càng trở lên quan quan trọng để đảm bảo tính bền vững về kinh tế. Việc mất điện không chỉ gây tổn thất cho các công ty lưới điện mà còn có thể gây ra những hậu quả nghiêm trọng cho người sử dụng cuối cùng và toàn xã hội.INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (540, 'vi', 'Lợi ích của mô hình thông số có thể được áp dụng cho quy trình làm việc toàn cầu, dẫn đến một giải pháp hoàn chỉnh cuối. Hơn nữa, phương pháp này cho phép tái sử dụng dữ liệu dễ dàng, có thể giảm mạnh chi phí và thời gian thiết kế cầu.', 'Tin chuyên ngành', 'ƯU ĐIỂM CỦA MÔ HÌNH CẦU THAM SỐ', 'uu-diem-cua-mo-hinh-cau-tham-so', NULL, NULL, 'ƯU ĐIỂM CỦA MÔ HÌNH CẦU THAM SỐ', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (541, 'vi', 'Các kỹ sư được giao nhiệm vụ hoàn thành các dự án khó khăn trong các mốc thời gian cố định và ngân sách thiết kế hạn chế, vì vậy họ cần những chiến lược để làm việc hiệu quả. Dưới đây là 5 công cụ thiết kế Allplan sẽ giúp các kỹ sư hoàn thành nhiều việc hơn và tối ưu thời gian hơn:', 'Tin chuyên ngành', 'ĐIỂM DANH 5 CÔNG CỤ THIẾT KẾ TRONG ALLPLAN – LỰA CHỌN HÀNG ĐẦU CHO CÁC KỸ SƯ', 'diem-danh-5-cong-cu-thiet-ke-trong-allplan-–-lua-chon-hang-dau-cho-cac-ky-su', NULL, NULL, 'ĐIỂM DANH 5 CÔNG CỤ THIẾT KẾ TRONG ALLPLAN – LỰA CHỌN HÀNG ĐẦU CHO CÁC KỸ SƯ', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (542, 'vi', 'Đầu tháng 12 vừa qua, Công ty CP Công nghệ và Tư vấn CIC đã ký hợp đồng cung cấp thiết bị đo gió bằng công nghệ LIDAR model ZX300 của hãng ZXLidar cho Công ty CP Năng lượng Bitexco. Thiết bị được đặt trên đảo phục vụ việc khảo sát, đánh giá năng lượng gió ngoài khơi.', 'Tin công ty', 'CIC và BITEXCO ký kết hợp đồng cung cấp thiết bị đo gió bằng LIDAR ZX300', 'cic-va-bitexco-ky-ket-hop-dong-cung-cap-thiet-bi-do-gio-bang-lidar-zx300', NULL, NULL, 'CIC và BITEXCO ký kết hợp đồng cung cấp thiết bị đo gió bằng LIDAR ZX300', 'thiết bị đo gió, lidar, zx300') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (543, 'vi', 'Tháng 11 vừa qua, Chúng tôi – Công ty CP Công nghệ và Tư vấn CIC đã cung cấp cho Công ty Điện lực Ba Đình bộ thiết bị định vị tuyến cáp ngầm RD8200.', 'Tin công ty', 'CIC cung cấp thiết bị dò cáp ngầm RD8200 của hãng Radiodetection cho Công ty Điện lực Ba Đình', 'cic-cung-cap-thiet-bi-do-cap-ngam-rd8200-cua-hang-radiodetection-cho-cong-ty-dien-luc-ba-dinh', NULL, NULL, 'CIC cung cấp thiết bị dò cáp ngầm RD8200 của hãng Radiodetection cho Công ty Điện lực Ba Đình', 'thiết bị dò cáp ngầm, định vị cáp ngầm, rd8200, radiodetection') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (544, 'vi', 'Công ty Sumitomo Mitsui Construction Co., Ltd là khách hàng truyền thống của CIC, là một trong những công ty xây dựng lớn nhất của Nhật Bản, có văn phòng tại Việt Nam, Philippines và rất nhiều quốc gia khác trên thế giới. Sumitomo đã và đang sử dụng thiết bị siêu âm cọc khoan nhồi CHUM của hãng Piletest (Israel) và mới đây lại tiếp tục đặt hàng thêm thiết bị này từ CIC để phục vụ cho công việc và khối lượng dự án lớn của mình.', 'Tin công ty', 'CIC tiếp tục cung cấp thiết bị siêu âm cọc khoan nhồi CHUM của hãng Piletest (Israel) cho Công ty Sumitomo Mitsui Construction Co., Ltd', 'cic-tiep-tuc-cung-cap-thiet-bi-sieu-am-coc-khoan-nhoi-chum-cua-hang-piletest-israel-cho-cong-ty-sumitomo-mitsui-construction-co-ltd', NULL, NULL, 'CIC tiếp tục cung cấp thiết bị siêu âm cọc khoan nhồi CHUM của hãng Piletest (Israel) cho Công ty Su', 'siêu âm cọc khoan nhồi, cọc khoan nhồi, piletest, siêu âm cọc, CHUM') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (545, 'vi', 'Nối tiếp thành công của buổi Hội thảo trực tuyến về Robot cống ngầm ngày 25/08/2021, Công ty CP Công nghệ và Tư vấn CIC đã được Sở Xây dựng Đà Nẵng và Hiệp hội Xây dựng Đà Nẵng tin tưởng và mời trình bày tại hội thảo thường niên của Hiệp hội về các giải pháp công nghệ cho lĩnh vực xây dựng, đặc biệt trọng tâm vào hai giải pháp Robot cống ngầm và Thiết bị định vị cáp ngầm', 'Tin công ty', 'CIC TRÌNH BÀY VỀ CÔNG NGHỆ ROBOT CỐNG NGẦM VÀ THIẾT BỊ ĐỊNH VỊ CÁP NGẦM TẠI HỘI THẢO CỦA SỞ XÂY DỰNG ĐÀ NẴNG VÀ HIỆP HỘI XÂY DỰNG ĐÀ NẴNG', 'cic-trinh-bay-ve-cong-nghe-robot-cong-ngam-va-thiet-bi-dinh-vi-cap-ngam-tai-hoi-thao-cua-so-xay-dung-da-nang', NULL, NULL, 'CIC TRÌNH BÀY VỀ CÔNG NGHỆ ROBOT CỐNG NGẦM VÀ THIẾT BỊ ĐỊNH VỊ CÁP NGẦM TẠI HỘI THẢO CỦA SỞ XÂY DỰNG', 'robot cống ngầm, định vị cáp ngầm, thiết bị định vị cáp ngầm, máy định vị cáp ngầm, siêu âm đất') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (546, 'vi', 'Sáng ngày 08/12/2021 vừa qua, công ty CP Công nghệ và Tư vấn CIC cùng hãng Radiodetection (Anh Quốc) và Tập đoàn Điện lực Việt Nam EVN đã phối hợp tổ chức thành công Hội thảo trực tuyến về “Thiết bị dò cáp ngầm”.', 'Tin công ty', 'Hội thảo về “Thiết bị dò cáp ngầm” do công ty CIC, hãng Radiodetection (Anh Quốc) và Tập đoàn Điện lực Việt Nam EVN phối hợp tổ chức đã diễn ra thành công tốt đẹp', 'hoi-thao-ve-thiet-bi-do-cap-ngam-do-cong-ty-cic-va-hang-radiodetection-anh-quoc-phoi-hop-to-chuc-da-dien-ra-thanh-cong-tot-dep', NULL, NULL, 'Hội thảo về “Thiết bị dò cáp ngầm” do công ty CIC và hãng Radiodetection (Anh Quốc) phối hợp tổ chức', 'thiết bị dò cáp ngầm, định vị cáp ngầm, rd8200, radiodetection') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (551, 'vi', 'Công ty CP Công nghệ và Tư vấn CIC mới đây đã ký hợp đồng cung cấp 2 thiết bị đo chấn động GMSplus-73 của hãng GeoSIG (Thụy Sỹ) cho dự án Nhà máy Thủy điện Hòa Bình mở rộng.', 'Tin công ty', 'CIC cung cấp thiết bị đo chấn động của hãng GeoSIG (Thụy Sỹ) cho Dự án Nhà máy Thủy điện Hòa Bình mở rộng', 'cic-cung-cap-thiet-bi-do-chan-dong-cua-hang-geosig-thuy-sy-cho-du-an-nha-may-thuy-dien-hoa-binh-mo-rong', NULL, NULL, 'CIC cung cấp thiết bị đo chấn động của hãng GeoSIG (Thụy Sỹ) cho Dự án Nhà máy Thủy điện Hòa Bình mở', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (558, 'vi', 'Dưới đây, CIC xin cung cấp các yêu cầu về cấu hình cho phần mềm AllPlan phiên bản 2022', 'Tin chuyên ngành', 'Yêu cầu hệ thống cho Allplan phiên bản 2022', 'yeu-cau-he-thong-allplan-2022', NULL, NULL, 'Yêu cầu hệ thống Allplan 2022', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (552, 'vi', 'IDEA StatiCa 21.1 là phiên bản thứ hai trong năm nhưng mang nhiều tính năng hơn so với phiên bản phát hành vào mùa xuân. IdeaStatica đã cố gắng để đạt được gì với phiên bản này? Nâng cao quy trình BIM trong công việc lên cấp độ tiếp theo, cho phép các kỹ sư thiết kế nhiều hơn trong bê tông cốt thép và bê tông dự ứng lực, đồng thời triển khai nhiều tính năng cho thiết kế liên kết thép mà IdeaStatica được yêu cầu từ khắp nơi trên thế giới.', 'Tin chuyên ngành', 'Phát hành version mới phần mềm IDEA StatiCa 21.1', 'phat-hanh-version-moi-phan-mem-idea-statica-211', NULL, NULL, 'Phát hành version mới phần mềm IDEA StatiCa 21.1', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (667, 'vi', 'Vừa qua, tại văn phòng của Viện Khoa học và Công nghệ Giao thông Vận tải (ITST) - 1252 Đường Láng - Đống Đa - Hà Nội, Công ty CP Công nghệ và Tư vấn CIC kết hợp cùng Trung tâm Tư vấn Giao thông Vận tải (Trancocen) – Trường Đại học Giao thông Vận tải đã tổ chức buổi hội thảo để giới thiệu về Giải pháp quản lý giao thông thông minh PTV OPTIMA, giải pháp tối ưu hóa hệ thống đèn tín hiệu PTV BALANCE và PTV EPICS cho Lãnh đạo và đại diện các trung tâm, phòng ban trực thuộc của Viện Khoa học và Công nghệ Giao thông Vận tải (ITST).', 'Tin chuyên ngành', 'HỘI THẢO ‘’ỨNG DỤNG GIẢI PHÁP QUẢN LÝ GIAO THÔNG THÔNG MINH, TỐI ƯU HÓA ĐÈN TÍN HIỆU CỦA HÃNG PTV GROUP’’', 'hoi-thao-‘’ung-dung-giai-phap-quan-ly-giao-thong-thong-minh-toi-uu-hoa-den-tin-hieu-cua-hang-ptv-group’’', NULL, NULL, 'HỘI THẢO ‘’ỨNG DỤNG GIẢI PHÁP QUẢN LÝ GIAO THÔNG THÔNG MINH, TỐI ƯU HÓA ĐÈN TÍN HIỆU CỦA HÃNG PTV GR', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (743, 'vi', 'Tháng 8 vừa qua, Công ty Rita Võ và Công ty CIC đã ký kết thành công hợp đồng triển khai phần mềm OPERA - một phần mềm chuyên dụng cho thiết kế, bóc tách vật tư, gia công nhôm kính.', 'Tin công ty', 'Rita Võ Life Window và CIC tiếp tục triển khai phần mềm chuyên dụng cho thiết kế, bóc tách vật tư và gia công kính OPERA', 'rita-vo-life-window-va-cic-tiep-tuc-trien-khai-phan-mem-chuyen-dung-cho-thiet-ke-boc-tach-vat-tu-va-gia-cong-kinh-opera', NULL, NULL, 'Rita Võ Life Window và CIC tiếp tục triển khai phần mềm chuyên dụng cho thiết kế, bóc tách vật tư và', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (553, 'vi', 'Thời gian vừa qua hãng CSI đã cho ra mắt phần mềm SAP2000 v23, CSiBridge v23, Etabs v19, SAFE v2020, CSiCol v10 và Perform 3D v8. Bên cạnh đó với phần mềm tính toán thiết kế đường ống áp lực CSiPlant cũng đã phát hành version mới CSiPlant v7. Dưới đây là tổng hợp các tính năng mới nhất nổi bật của phần mềm này:', 'Tin chuyên ngành', 'Tính năng mới của phần mềm CSi Plant v7', 'tinh-nang-moi-cua-phan-mem-csi-plant-v7', NULL, NULL, 'Tính năng mới của phần mềm CSi Plant v7', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (554, 'vi', 'Adapt Builder v21.0 được hãng Risatech phát hành ngày 12/17/2021, dưới đây là tổng hợp những tính năng mới nhất của phần mềm Adapt Builder phiên bản v21 mới nhất', 'Tin chuyên ngành', 'Tính năng mới của phần mềm ADAPT-Builder version 21.0', 'tinh-nang-moi-cua-phan-mem-adapt-builder-version-210', NULL, NULL, 'Tính năng mới của phần mềm ADAPT-Builder version 21.0', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (555, 'vi', 'Cọc khoan nhồi là một phương pháp thi công được nhiều người lựa chọn cho các công trình xây dựng. Để đảm bảo cọc sau khi thi công đã đúng chuẩn và có thể sử dụng, cần thực hiện kiểm tra đánh giá chất lượng cọc. Trên thế giới hiện nay có nhiều phương pháp xác định sự đồng nhất của bê tông cọc khoan nhồi theo phương thức không phá huỷ kết cấu như phương pháp hồi âm hay còn gọi là phương pháp biến dạng nhỏ (PIT/PET), phương pháp kiểm tra đồng nhất bằng nhiệt, phương pháp xung siêu âm truyền qua ống. Ở Việt Nam, phương pháp xung siêu âm truyền qua ống ( siêu âm cọc khoan nhồi) đang được sử dụng phổ biến để đánh giá chất lượng của cọc khoan nhồi. Nội dung chi tiết của phương pháp siêu âm cọc khoan nhồi được quy định trong tiêu chuẩn Việt Nam TCVN 9396:2012INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (556, 'vi', 'Sắp tới vào ngày 19/01/2022, hãng phần mềm ADAPT sẽ tổ chức hội thảo online với nội dung Giới thiệu tính năng mới phần mềm ADAPT-Builder V21', 'Tin chuyên ngành', 'Webinar - Giới thiệu tính năng mới phần mềm ADAPT-Builder V21', 'webinar-gioi-thieu-tinh-nang-moi-phan-mem-adapt-builder-v21', NULL, NULL, 'Webinar - Giới thiệu tính năng mới phần mềm ADAPT-Builder V21', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (557, 'vi', 'Mới đây, công ty CP Công nghệ và Tư vấn CIC tiếp tục ký hợp đồng cung cấp thiết bị đo chấn động GMSplus-43 của hãng GeoSIG (Thụy Sỹ) cho dự án Cung cấp, lắp đặt bảo dưỡng định kỳ và xử lý, khắc phục hư hỏng hệ thống quan trắc tại Thủy điện Sông Bung 2 và Sông Bung 4 – Chủ đầu tư: Công ty Thủy điện Sông Bung.', 'Tin công ty', 'CIC cung cấp thiết bị đo chấn động của hãng GeosSIG (Thụy Sỹ) cho Dự án Thủy điện Sông Bung 2 và Sông Bung 4', 'cic-cung-cap-thiet-bi-do-chan-dong-cua-hang-geossig-thuy-sy-cho-du-an-thuy-dien-song-bung-2-va-song-bung-4', NULL, NULL, 'CIC cung cấp thiết bị đo chấn động của hãng GeosSIG (Thụy Sỹ) cho Dự án Thủy điện Sông Bung 2 và Sôn', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (559, 'vi', 'Hiện nay, nhằm đảm bảo sự an toàn sức khỏe cho cộng đồng trong mùa COVID-19, nhiều công ty đã cho nhân viên của mình làm việc từ xa. Với hơn 50 năm kinh nghiệm trong lĩnh vực xây dựng, ALLPLAN cung cấp giải pháp ‘làm việc từ xa’ cho các kỹ sư xây dựng và kiến trúc sư. Để công trình xây dựng không bị trì hoãn thời gian hoàn thành. Đặc biệt, đối với các dự án thiết kế theo quy trình BIM xây dựng.', 'Tin chuyên ngành', 'ALLPLAN cung cấp giải pháp làm việc từ xa cho ngành xây dựng', 'allplan-cung-cap-giai-phap-lam-viec-tu-xa-cho-nganh-xay-dung', NULL, NULL, 'ALLPLAN cung cấp giải pháp làm việc từ xa cho ngành xây dựng', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (560, 'vi', 'Chuyển từ thiết kế 2D sang 3D là một điều nhiều kiến trúc sư và kỹ sư e ngại. Nhiều người thiết kế lo lắng khi nghĩ đến việc phải học cách chuyển từ phác thảo bản vẽ sang dựng mô hình, cũng như việc học cách sử dụng một phần mềm dựng mô hình 3D mới. Họ nghĩ điều này sẽ làm giảm hiệu quả thiết kế của mình. Tuy nhiên, sự thật thì hoàn toàn ngược lại. Một khi kiến trúc sư và kỹ sư đã làm quen được với phần mềm, các công cụ dựng mô hình 3D cung cấp nhiều lợi thế và có thế giúp tăng tốc quá trình thiết kế. Điều này đặc biệt đúng đối với các chương trình dựng mô hình 3D tích hợp phương pháp tiếp cận cho cả thiết kế 2D và 3D.', 'Tin chuyên ngành', 'KẾT HỢP THIẾT KẾ 2D VÀ 3D ĐỂ ĐẠT ĐƯỢC TÍNH LINH HOẠT TỐI ƯU', 'ket-hop-thiet-ke-2d-va-3d-de-dat-duoc-tinh-linh-hoat-toi-uu', NULL, NULL, 'KẾT HỢP THIẾT KẾ 2D VÀ 3D ĐỂ ĐẠT ĐƯỢC TÍNH LINH HOẠT TỐI ƯU', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (561, 'vi', 'Ngày 14/01/2022 vừa qua, tập thể Công ty CP Công nghệ và Tư vấn CIC đã tổ chức thành công tốt đẹp Lễ tổng kết Hoạt động sản xuất kinh doanh năm 2021 và Kế hoạch phát triển năm 2022, để lại nhiều niềm vui và phấn khởi trong lòng ban lãnh đạo và CBNV công ty.', 'Tin công ty', 'CIC tổ chức thành công tốt đẹp "Lễ tổng kết Hoạt động sản xuất kinh doanh năm 2021 và Kế hoạch phát triển năm 2022"', 'cic-to-chuc-thanh-cong-tot-deple-tong-ket-hoat-dong-san-xuat-kinh-doanh-nam-2021-va-ke-hoach-phat-trien-nam-2022-', NULL, NULL, 'CIC tổ chức thành công tốt đẹp "Lễ tổng kết Hoạt động sản xuất kinh doanh năm 2021 và Kế hoạch phát', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (562, 'vi', 'Cùng với việc ra mắt phần mềm SAFE 2020 thay thế cho SAFE 2016, hãng CSI mới phát hành thêm phiên bản hoàn toàn mới của phần mềm ETABS v20.0.0. Với một loạt cải tiến mới trong mô hình, phân tích, bổ sung tiêu chuẩn thiết kế và tối ưu hóa dữ liệu đầu ra... Dưới đây là tổng hợp các tính năng trong phần mềm ETABS v20.0.0 mới phát hành.', 'Tin chuyên ngành', 'Tính năng mới trong Etabs v20', 'tinh-nang-moi-trong-etabs-v20', NULL, NULL, 'Tính năng mới trong Etabs v20 mới phát hành', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (581, 'vi', 'Cọc khoan nhồi là một phương pháp thi công được nhiều người lựa chọn cho các công trình xây dựng. Tuy nhiên, trong quá trình thi công cọc khoan nhồi thường gặp phải các sự cố sau:', 'Tin chuyên ngành', 'CÁC SỰ CỐ VÀ BIỆN PHÁP XỬ LÝ KHI THI CÔNG CỌC KHOAN NHỒI', 'cac-su-co-va-bien-phap-xu-ly-khi-thi-cong-coc-khoan-nhoi', NULL, NULL, 'CÁC SỰ CỐ VÀ BIỆN PHÁP XỬ LÝ KHI THI CÔNG CỌC KHOAN NHỒI', 'siêu âm cọc khoan nhồi, cọc khoan nhồi, siêu âm cọc, CHUM') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (563, 'vi', 'Mới đây, Công ty Cổ phần Công nghệ và Tư vấn CIC đã hoàn thành việc cung cấp, chuyển giao, đào tạo phần mềm sản xuất nội thất gỗ công nghiệp Haixun 4.0 cho Công ty Cổ phần Thiết kế - Xây dựng & Đào tạo Kiến Thiết Việt.', 'Tin công ty', 'CIC hoàn thành chuyển giao phần mềm sản xuất nội thất Haixun 4.0 cho Nội thất Kiến thiết Việt', 'cic-hoan-thanh-chuyen-giao-phan-mem-san-xuat-noi-that-haixun-40-cho-noi-that-kien-thiet-viet', NULL, NULL, 'CIC hoàn thành chuyển giao phần mềm sản xuất nội thất Haixun 4.0 cho Nội thất Kiến thiết Việt', 'haixun, phần mềm nội thất') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (564, 'vi', 'Đôi khi việc mang theo tất cả các thiết bị của bạn đến vị trí làm việc gặp khó khăn. Bạn cần rảnh tay để xem bản đồ, bản vẽ hoặc mang các thiết bị khác. ', 'Tin chuyên ngành', 'Radiodetection ra mắt balo và túi đựng mới cho máy dò cáp ngầm', 'radiodetection-ra-mat-balo-va-tui-dung-moi-cho-may-do-cap-ngam', NULL, NULL, 'Radiodetection ra mắt balo và túi đựng mới cho máy dò cáp ngầm', 'radiodetection, siêu âm xuyên đất, radar xuyên đất') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (565, 'vi', 'Ngày 29/12/2021 Công ty cổ phần Công nghệ và Tư vấn CIC đã thực hiện bàn giao bộ thiết bị giám sát chấn động của hãng DMT cho Thủy điện Trung Sơn. Nhiệm vụ chính của bộ thiết bị này là phục vụ trong giám sát chấn động rung tại công trình thuỷ điện Trung Sơn', 'Tin công ty', 'CIC cung cấp bộ thiết bị giám sát chấn động rung cho  Thủy Điện Trung Sơn', 'cic-cung-cap-bo-thiet-bi-giam-sat-chan-dong-rung-cho-thuy-dien', NULL, NULL, 'CIC cung cấp bộ thiết bị giám sát chấn động rung cho  Thủy điện Trung Sơn', 'giám sát chấn động DMT, SUMMIT M VIPA, TCVN 7378:2004, TCVN 7191:2002') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (566, 'vi', 'Năng lượng điện gió là nguồn năng lượng có triển vọng và phát triển trong thời gian gần đây. Để đáp ứng nhu cầu ngày càng tăng, AQ System đã cho ra mắt thiết bị AQ 510 với khả năng cung cấp dữ liệu gió vượt trội trong điều kiện sương mù.', 'Tin chuyên ngành', 'Thiết bị đo gió trên cao AQ 510 vượt trội về khả năng hoạt động dưới điều kiện sương mù', 'thiet-bi-do-gio-tren-cao-aq-510-vuot-troi-ve-kha-nang-hoat-dong-duoi-dieu-kien-suong-mu', NULL, NULL, 'Thiết bị đo gió trên cao AQ 510 vượt trội về khả năng hoạt động dưới điều kiện sương mù', 'thiết bị đo gió, aq150') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (572, 'vi', 'DNV ra mắt phần mềm Phast và phần mềm Safeti phiên bản mới 8.61. Với một phương pháp mới để lập mô hình độc hại gây tử vong và một số bản sửa lỗi nhỏ.', 'Tin chuyên ngành', 'DNV phát hành phiên bản mới của phần mềm PHAST và phần mềm SAFETI', 'dnv-phat-hanh-phien-ban-moi-cua-phan-mem-phast-va-phan-mem-safeti', NULL, NULL, 'DNV phát hành phiên bản mới của phần mềm PHAST và phần mềm SAFETI', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (573, 'vi', 'Vào các ngày mùng 2, mùng 8 và mùng 10 tháng 3 năm 2022, Pipenet sẽ tổ chức các buổi đào tạo về Hydraulic transient force và Pump Model ở các khung giờ khác nhau, phù hợp theo nhu cầu của khách hàng.', 'Tin chuyên ngành', 'HỘI THẢO PHẦN MỀM PIPENET MODULE PIPENET TRANSIENT (ONLINE MIỄN PHÍ)', 'hoi-thao-phan-mem-pipenet-module-pipenet-transient-online-mien-phi', NULL, NULL, 'HỘI THẢO PHẦN MỀM PIPENET MODULE PIPENET TRANSIENT (ONLINE MIỄN PHÍ)Mô-đun PIPENET Transient là một', 'Pipenet') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (574, 'vi', 'Bạn đã biết tới nền tảng Bentley iTwin là cách tốt nhất để xây dựng một ứng dụng cặp song sinh kỹ thuật số (digital twin) trên web và máy tính. Có thể bạn không biết, giờ đây có thể tạo một ứng dụng “chạy bằng iTwin” (Powered by iTwin) hoàn toàn nguyên bản cho iPhone và iPad.', 'Tin chuyên ngành', 'Bentley iTwin cho iPhone và iPad', 'bentley-itwin-cho-iphone-va-ipad', NULL, NULL, 'Bentley iTwin cho iPhone và iPad', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (575, 'vi', 'Sau đây mình xin giới thiệu tới anh em một vài công cụ rất hữu dụng nhưng ít ai biết tới trong enjiCAD, sẽ giúp anh em tăng tốc độ thiết kế lên rất nhiều.', 'Tin chuyên ngành', 'Gợi ý một vài công cụ rất hay trên phần mềm enjiCAD giúp hỗ trợ công việc thiết kế hàng ngày', 'goi-y-mot-vai-cong-cu-rat-hay-tren-phan-mem-enjicad-giup-ho-tro-cong-viec-thiet-ke-hang-ngay', NULL, NULL, 'Gợi ý một vài công cụ rất hay trên phần mềm enjiCAD giúp hỗ trợ công việc thiết kế hàng ngày', 'phần mềm cad, bàn giao phần mềm CAD, AutoCAD, enjiCAD') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1110, 'vi', 'Trong bài viết dưới đây, chúng tôi sẽ hướng dẫn các bạn cách truy cập các phần mềm của CSI thông qua nền tảng đám mây Cloud.', 'Tin chuyên ngành', 'Hướng dẫn truy cập phần mềm CSI qua nền tảng đám mây', 'huong-dan-truy-cap-phan-mem-csi-qua-nen-tang-dam-may', NULL, NULL, 'Hướng dẫn truy cập phần mềm CSI qua nền tảng đám mây', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (576, 'vi', 'RD Map là ứng dụng Android miễn phí được phát triển bởi RADIODETECTION. Nó cho phép người sử dụng tạo bản đồ các tuyến cáp, đường cống ngầm và chia sẻ chúng từ hiện trường. RD Map tương thích với nhiều loại máy dò cáp ngầm được sản xuất bởi RADIODETECTION như: RD7100, RD8100, RD7200, RD8200.', 'Tin chuyên ngành', 'LẬP BẢN ĐỒ CÁC TUYẾN CÁP NGẦM BẰNG ỨNG DỤNG RD MAP', 'lap-ban-do-cac-tuyen-cap-ngam-bang-ung-dung-rd-map', NULL, NULL, 'LẬP BẢN ĐỒ CÁC TUYẾN CÁP NGẦM BẰNG ỨNG DỤNG RD MAP', 'radiodetection, siêu âm xuyên đất, radar xuyên đất, dò tìm cáp ngầm') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (577, 'vi', 'Giám sát chấn động nổ mìn theo QCVN 01:2019/BCT “Quy chuẩn kỹ thuật quốc gia về an toàn trong sản xuất, thử nghiệm, nghiệm thu, bảo quản, vận chuyển, sử dụng, tiêu hủy vật liệu nổ công nghiệp và bảo quản tiền chất thuốc nổ”  là việc sử dụng các phương tiện, thiết bị để đo, phân tích và đánh giá mức độ chấn động, mức độ tác động sóng không khí do nổ mìn gây ra.', 'Tin chuyên ngành', 'Quy định mới nhất về giám sát chấn động nổ mìn', 'quy-dinh-ve-giam-sat-chan-dong-no-min', NULL, NULL, 'Quy định mới nhất về giám sát chấn động nổ mìn', 'giám sát chấn động online, thiết bị giám sát nổ mìn, thiết bị giám sát chấn động') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (578, 'vi', 'Nhiệm vụ số hóa BIM hiện đang bao trùm toàn bộ ngành công nghiệp AEC. Hối thúc chúng ta cần phải nhanh chóng bắt kịp với tốc độ biến đổi đó.', 'Tin chuyên ngành', 'TRIỂN KHAI CÔNG NGHỆ BIM 5D VÀO CÁC DỰ ÁN XÂY DỰNG', 'trien-khai-cong-nghe-bim-5d-vao-cac-du-an-xay-dung', NULL, NULL, 'TRIỂN KHAI CÔNG NGHỆ BIM 5D VÀO CÁC DỰ ÁN XÂY DỰNG', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (633, 'vi', 'Để đáp ứng nhu cầu khách hàng trên thế giới, AQ System đã cung cấp những dịch vụ giúp khách hàng có thể tối ưu hóa quy trình đo gió trên cao', 'Tin chuyên ngành', 'AQ System cung cấp các dịch vụ giúp tối ưu hóa quy trình đo gió trên cao', 'aq-system-cung-cap-cac-dich-vu-giup-toi-uu-hoa-quy-trinh-do-gio-tren-cao', NULL, NULL, 'AQ System cung cấp các dịch vụ giúp tối ưu hóa quy trình đo gió trên cao', 'đo gió, thiết bị đo gió, điện gió, đo gió trên cao') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (634, 'vi', 'Hiện nay, việc sử dụng các mẫu cửa có kết hợp soi huỳnh đang ngày càng phổ biến trong thiết kế nội thất gỗ công nghiệp vì tính thẩm mỹ của nó. Phần mềm Cabinet Vision hiện tại cũng đã hỗ trợ việc tạo và lưu trữ các mẫu huỳnh đa dạng về họa tiết và chủng loại vật liệu.INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (580, 'vi', 'Đá ở độ sâu phải chịu các ứng suất do trọng lượng của các địa tầng bên trên và từ các ứng suất bị khóa buộc có nguồn gốc kiến tạo. Khi một khe hở được đào trong đá, trường ứng suất bị phá vỡ cục bộ và một tập hợp ứng suất mới được tạo ra trong các lớp đá xung quanh khe hở. Kiến thức về cường độ, hướng của các ứng suất tại chỗ và ứng suất gây ra là một phần thiết yếu của thiết kế đào dưới đất vì trong nhiều trường hợp, cường độ của đá bị vượt quá giới hạn và mất ổn định dẫn đến có thể gây ra hậu quả nghiêm trọng đối với hoạt động của đào hầm.', 'Tin chuyên ngành', 'Ứng dụng PLAXIS cho công tác đào hầm trong đá khối', 'ung-dung-plaxis-cho-cong-tac-dao-ham-trong-da-khoi', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (582, 'vi', 'Khóa học Quick Start Course là phần giới thiệu thực hành kéo dài 4 giờ về các tính năng và chức năng cơ bản của ADAPT-Builder, hướng dẫn sử dụng các công cụ chuyên nghiệp và các mô hình ví dụ để người dùng làm quen với giao diện cũng như quy trình làm việc của phần mềm từ công đoạn mô hình hóa kết cấu, tải trọng, phân tích, thiết kế và lưu lại một mô hình trong phần mềm ADAPT-Builder. Kéo dài trong 2 ngày (với các phiên tùy chọn, theo giờ hành chính hàng ngày), khóa học hướng đến những người dùng mới làm quen với phần mềm ADAPT-Builder, tuy nhiên, các mẹo và thủ thuật do người hướng dẫn cung cấp trong suốt khóa học có thể chứng minh giá trị đối với ngay cả những người thành thạo hoặc đã sử dụng Adapt-Builder trước đây.', 'Tin chuyên ngành', 'Khóa đào tạo ADAPT-Builder ngày 22 - 25 tháng 3 (trực tuyến)', 'khoa-dao-tao-adapt-builder-ngay-22---25-thang-3-truc-tuyen', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (583, 'vi', 'ZX Lidar đã thông báo rằng các thiết bị đo gió trên cao đủ điều kiện để đáp ứng tiêu chuẩn IEC 61400-12-1:2017. Kết quả cho thấy thiết bị có độ chính xác cao và công nghệ Lidar đã được chấp nhận để đưa vào nhiều ứng dụng, khảo sát trong đó có đánh giá tài nguyên gió.', 'Tin chuyên ngành', 'ZX Lidar đáp ứng đầy đủ tiêu chuẩn IEC', 'zx-lidar-dap-ung-day-du-tieu-chuan-iec', NULL, NULL, 'ZX Lidar đáp ứng đầy đủ tiêu chuẩn IEC', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (584, 'vi', 'Với mong muốn giới thiệu giải pháp đến với các doanh nghiệp ngành than, vào Thứ 6, ngày 18/03/2022 tới đây, Công ty CIC phối hợp với hãng Seequent tổ chức Hội thảo online với chủ đề: “Chuyển đổi số trong các doanh nghiệp ngành than - Giải pháp LeapFrog của Hãng phần mềm Seequent”', 'Tin chuyên ngành', 'Hội thảo trực tuyến: “Chuyển đổi số trong các doanh nghiệp ngành than - Giải pháp LeapFrog của Hãng phần mềm Seequent”', 'hoi-thao-truc-tuyen:-chuyen-doi-so-trong-cac-doanh-nghiep-nganh-than-giai-phap-leapfrog-cua-hang-phan-mem-seequent', NULL, NULL, 'Hội thảo trực tuyến: “Chuyển đổi số trong các doanh nghiệp ngành than - Giải pháp LeapFrog của Hãng', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (585, 'vi', 'Công việc kinh doanh nội thất và sản phẩm vật liệu xây dựng ngày càng được hỗ trợ mạnh mẽ hơn với sự phát triển, tiến bộ của các công nghệ thực tế ảo tăng cường, trí tuệ nhân tạo.', 'Tin chuyên ngành', 'Ứng dụng thực tế ảo tăng cường (AR) vào hoạt động kinh doanh vật liệu trang trí, hoàn thiện', 'ung-dung-thuc-te-ao-tang-cuong-ar-vao-hoat-dong-kinh-doanh-vat-lieu-trang-tri-hoan-thien', NULL, NULL, 'Ứng dụng thực tế ảo tăng cường (AR) vào hoạt động kinh doanh vật liệu trang trí, hoàn thiện', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (586, 'vi', 'Allplan Bridge Modeler là giải pháp mạnh mẽ cho mô hình tham số bốn chiều của cầu. Phần mềm hỗ trợ các kỹ sư trong tất cả các giai đoạn lập kế hoạch, từ ý tư ởng ban đầu đến kế hoạch thực hiện. Mô tả tham số của mô hình cầu nâng khả năng sử dụng lên một tầm cao mới và cho phép các kỹ sư làm việc linh hoạt và nhanh chóng.', 'Tin chuyên ngành', 'CÁC ĐIỂM NỔI BẬT VỀ HIỆU  SUẤT ALLPLAN BRIDGE MODELER', 'cac-diem-noi-bat-ve-hieusuat-allplan-bridge-modeler', NULL, NULL, 'CÁC ĐIỂM NỔI BẬT VỀ HIỆU  SUẤT ALLPLAN BRIDGE MODELER', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (587, 'vi', 'Nhiều khách hàng khi tìm hiểu và mua phần mềm enjiCAD bản quyền đều ít nhiều gặp những thắc mắc về phiên bản đơn (Standalone) và bản mạng (Network). Rằng chúng có khác gì nhau, tính năng của chúng có thay đổi gì? Bài viết này sẽ làm rõ những đặc điểm cũng như những điều cần biết về hai phiên bản này của phần mềm enjiCAD.', 'Tin chuyên ngành', 'Những điều cần biết về phiên bản mạng - Network của phần mềm enjiCAD', 'nhung-dieu-can-biet-ve-phien-ban-mang---network-cua-phan-mem-enjicad', NULL, NULL, 'Những điều cần biết về phiên bản mạng - Network của phần mềm enjiCAD', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (588, 'vi', 'Từ đầu tháng 3/2022 vừa qua, Hãng phần mềm Haixun chính thức cho ra mắt bản cập nhật tháng 3 với nhiều tính năng được cập nhật, cải tiến.', 'Tin chuyên ngành', 'Haixun 4.0 phát hành phiên bản nâng cấp hỗ trợ xử lý các mẫu sản phẩm bo cong', 'haixun-40-phat-hanh-phien-ban-nang-cap-ho-tro-xu-ly-cac-mau-san-pham-bo-cong', NULL, NULL, 'Haixun 4.0 phát hành phiên bản nâng cấp hỗ trợ xử lý các mẫu sản phẩm bo cong', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (589, 'vi', 'Hãng CSI (Computers and Structures, Inc.) vừa phát hành phiên bản mới phần mềm SAP2000 v24, với một số bổ sung trong tiêu chuẩn thiết kế và khả năng phân tích. Dưới đây là một số thay đổi chính được bổ sung trong phiên bản mới này: ', 'Tin chuyên ngành', 'Phát hành SAP2000 v24.0.0', 'phat-hanh-sap2000 v2400', NULL, NULL, 'Phát hành SAP2000 v24.0.0', '') ON CONFLICT (entity_id, locale) DO NOTHING;
