INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (593, 'vi', 'Từ ngày 23-27/3 sắp tới tại Cung Triển lãm Kiến trúc Xây dựng Quốc gia, CIC chuyển giao công nghệ thực tế ảo tăng cường (AR) cho thương hiệu sàn gỗ Hàn Quốc Donghwa sử dụng ngay tại Triển lãm.', 'Tin công ty', 'CIC chuyển giao công nghệ thực tế ảo tăng cường (AR) cho thương hiệu sàn gỗ Hàn Quốc Dongwha tại triển lãm Vietbuild Hanoi 2022', 'cic-chuyen-giao-cong-nghe-thuc-te-ao-tang-cuong-ar-cho-thuong-hieu-san-go-han-quoc-dongwha-tai-trien-lam-vietbuild-hanoi-2022', NULL, NULL, 'CIC chuyển giao công nghệ thực tế ảo tăng cường (AR) cho thương hiệu sàn gỗ Hàn Quốc Dongwha tại tri', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (594, 'vi', 'Tính năng in bản vẽ ở các phần mềm CAD nói chung và ở enjiCAD đôi lúc ta gặp những lỗi bản vẽ in ra bị mờ hoặc thậm chí mất nét. Để in một bản vẽ CAD ra tưởng chừng đơn giản nhưng đôi khi một số lỗi xảy ra lại không đơn giản như ta nghĩ. Bài viết sau đây sẽ giúp tổng hợp cách giải quyết các lỗi thường gặp khi in ấn, sao cho bản vẽ CAD in ra cho chất lượng tốt nhất với yêu cầu.', 'Tin chuyên ngành', 'Một số lỗi thường gặp và cách khắc phục khi in ấn với Plotter trong enjiCAD', 'mot-so-loi-thuong-gap-va-cach-khac-phuc-khi-in-an-voi-plotter-trong-enjicad', NULL, NULL, 'Một số lỗi thường gặp và cách khắc phục khi in ấn với Plotter trong enjiCAD', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (595, 'vi', 'Cabinet Vision là công cụ phần mềm hàng đầu trong ngành để thiết kế và sản xuất tủ bếp, tủ áo, đồ dùng thương mại và hơn thế nữa. Phiên bản Cabinet Vision 2022 đã được ra mắt với nhiều tính năng vượt trội và ưu việt.', 'Tin chuyên ngành', 'Chương trình hội thảo trực tuyến “Giới thiệu tính năng cập nhật phần mềm thiết kế và sản xuất tủ bếp Cabinet Vision phiên bản 2022”', 'chuong-trinh-hoi-thao-truc-tuyen-gioi-thieu-va-huong-dan-tinh-nang-cap-nhat-cua-phan-mem-cabinet-vision-ban-quyen-2022', NULL, NULL, 'Chương trình hội thảo trực tuyến “Giới thiệu và hướng dẫn tính năng cập nhật của phần mềm Cabinet Vi', '') ON CONFLICT (entity_id, locale) DO NOTHING;
