INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (686, 'vi', 'Để nói về nguyên nhân máy mở File cad chậm, khi làm việc hay bị giật lag, treo máy thậm chí tắt đột ngột thì chúng ta có thể chia làm 2 nguyên nhân chính: các tinh chỉnh trong phần mềm CAD khiến máy nặng hơn và phần cứng không đáp ứng được. Bài viết này CIC sẽ chỉ ra các cách để enjiCAD chạy mượt mà và ổn định hơn.', 'Tin chuyên ngành', '5 thao tác tăng tốc mở file CAD, giảm giật, lag, treo máy khi sử dụng', '5-thao-tac-tang-toc-mo-file-cad-giam-giat-lag-treo-may-khi-su-dung', NULL, NULL, '5 thao tác tăng tốc mở file CAD, giảm giật, lag, treo máy khi sử dụng', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (610, 'vi', 'Trân trọng kính mời quý khác hàng tham dự Chương trình hội nghị trực tuyến “Giải pháp xây dựng tương lai – ALLPLAN trong xây dựng cơ sở hạ tầng.”', 'Tin chuyên ngành', 'Webinar: Build the Future – ALLPLAN Infrastructure Digital Conference', 'webina:-build-the-future-–-allplan-infrastructure-digital-conference', NULL, NULL, 'Webinar: Build the Future – ALLPLAN Infrastructure Digital Conference', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (611, 'vi', 'Allplan Bridge Prestressing là giải pháp mạnh mẽ cho việc mô hình tham số bốn chiều của công trình cầu. Phần mềm hỗ trợ các kỹ sư trong tất cả các giai đoạn lập kế hoạch, từ lên ý tưởng ban đầu đến thực hiện kế hoạch thực thi. Mô tả tham số của mô hình cầu với cáp dự ứng lực nâng khả năng sử dụng lên một tầm cao mới và cho phép các kỹ sư làm việc linh hoạt và nhanh chóng.', 'Tin chuyên ngành', 'ALLPLAN BRIDGE PRESTRESSING', 'allplan-bridge-prestressing', NULL, NULL, 'ALLPLAN BRIDGE PRESTRESSING', '') ON CONFLICT (entity_id, locale) DO NOTHING;
