INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (619, 'vi', 'Ngày 8/4 vừa qua, Công ty Cổ phần Công nghệ và Tư vấn CIC phối hợp với CVSEA tổ chức thành công hội thảo trực tuyến về phần mềm Cabinet Vision phiên bản 2022 với nhiều điểm tối ưu nổi bật.', 'Tin chuyên ngành', 'CIC tổ chức thành công Hội thảo trực tuyến “Giới thiệu tính năng cập nhật phần mềm thiết kế và sản xuất tủ bếp Cabinet Vision phiên bản 2022”', 'cic-to-chuc-thanh-cong-hoi-thao-truc-tuyen-gioi-thieu-tinh-nang-cap-nhat-phan-mem-thiet-ke-va-san-xuat-tu-bep-cabinet-vision-phien-ban-2022', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (620, 'vi', 'Tính năng Sheetset có lẽ đã rất quen thuộc với người sử dụng các phần mềm CAD. Một ứng dụng rất hay nữa của tính năng này đó là cho phép người dùng đóng gói cả một dự án với nhiều bản vẽ thành phần và gửi đi. Hãy cùng tìm hiểu ở bài viết dưới đây.', 'Tin chuyên ngành', 'Chia sẻ phương pháp đóng gói dự án và gửi đi trên Sheetset manager phần mềm enjiCAD', 'chia-se-phuong-phap-dong-goi-du-an-va-gui-di-tren-sheetset-manager-phan-mem-enjicad', NULL, NULL, 'Chia sẻ phương pháp đóng gói dự án và gửi đi trên Sheetset manager phần mềm enjiCAD', 'phần mềm cad, bàn giao phần mềm CAD, AutoCAD, enjiCAD') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (621, 'vi', 'Trong quá trình sử dụng enjiCAD nói riêng hay phần mềm CAD nói chung đôi khi chúng ta ấn nhầm một số nút nào đó khiến cho thanh công cụ thao tác biến mất và không thể sử dụng các tính năng trên đó. Đây là vấn đề rất nhiều người đã gặp phải, và bài viết sau đây sẽ chỉ ra một số cách khắc phục hiệu quả vấn đề này.', 'Tin chuyên ngành', 'Cách khắc phục khi bị mất thanh công cụ trong phần mềm enjiCAD', 'cach-khac-phuc-khi-bi-mat-thanh-cong-cu-trong-phan-mem-enjicad', NULL, NULL, 'Cách khắc phục khi bị mất thanh công cụ trong phần mềm enjiCAD', 'phần mềm cad, bàn giao phần mềm CAD, AutoCAD, enjiCAD') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (622, 'vi', 'Cứ mỗi mùa mưa đến, ám ảnh về ngập lụt, tắc đường luôn đeo bám người dân ở các đô thị lớn như Hà Nội, Hồ Chí Minh,... Nguyên nhân chính của tình trạng này là do rác thải bịt kín các cống thoát nước gây tắc nghẽn, ngập úng. Bên cạnh đó, rễ cây mọc xuyên qua thành cống hay dầu mỡ từ các cơ sở kinh doanh ăn uống cũng góp phần làm tắc nghẽn hệ thống cống thoát nước. Để khắc phục vấn đề này, ngoài việc tuyên truyền, nâng cao ý thức người dân, cần áp dụng các công nghệ mới giúp xử lý tắc nghẽn các đường cống ngầm.', 'Tin chuyên ngành', 'Rô bốt vệ sinh cống ngầm - Trở thủ đắc lực giúp xử lý tắc nghẽn các đường cống ngầm', 'ro-bot-ve-sinh-cong-ngam-–-tro-thu-dac-luc-giup-xu-ly-tac-nghen-cac-duong-cong-ngam', NULL, NULL, 'Rô bốt vệ sinh cống ngầm – trợ thủ đắc lực giúp xử lý tắc nghẽn các đường cống ngầm', 'rô bốt cống ngầm') ON CONFLICT (entity_id, locale) DO NOTHING;
