INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (625, 'vi', 'Vào 8h00 ngày 15/04  vừa qua, Công ty CP Công nghệ và Tư vấn CIC đã tổ chức thành công Đại hội cổ đông thường niên năm 2022. Tại Đại hội nhiều nội dung và nhân sự đã được thống nhất hứa hẹn một nhiệm kỳ mới với nhiều sự khởi sắc trong hoạt động sản xuất, kinh doanh.', 'Tin công ty', 'Công ty CP Công nghệ và Tư vấn CIC tổ chức thành công Đại hội cổ đông thường niên năm 2022', 'cong-ty-cp-cong-nghe-va-tu-van-cic-to-chuc-thanh-cong-dai-hoi-co-dong-thuong-nien-nam-2022', NULL, NULL, 'Công ty CP Công nghệ và Tư vấn CIC tổ chức thành công Đại hội cổ đông thường niên năm 2022', '') ON CONFLICT (entity_id, locale) DO NOTHING;
