INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (857, 'vi', 'Vào ngày 30/01/2023 vừa qua, tập thể Công ty CP Công nghệ và Tư vấn CIC đã có chương trình giao lưu Khai xuân Quý Mão 2023 với nhiều hoạt động hấp dẫn, vui tươi và ý nghĩa. Tập thể Ban Giám đốc và cán bộ nhân viên CIC cùng các cô chú cựu cán bộ đã có mặt đông đủ để tham gia hoạt động thường niên đặc biệt này,', 'Tin công ty', 'Tập thể CIC tổ chức Khai xuân Quỹ Mão 2023', 'tap-the-cic-to-chuc-khai-xuan-quy-mao-2023', NULL, NULL, 'Tập thể CIC tổ chức Khai xuân Quỹ Mão 2023', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (858, 'vi', 'Đánh giá tài nguyên khả thi là yếu tố quan trọng nhất của bất kỳ dự án năng lượng nào.Phao nổi đo gió FLIDAR giúp thu thập dữ liệu và tài nguyên đáng tin cậy để hỗ trợ các quyết định đầu tư điện gió ngoài khơi. Nhận thấy tiềm năng này, Carbon Trust đã vạch ra một lộ trình để đảm bảo độ tin cậy trong thương mại và khả năng sử dụng của dữ liệu, bao gồm cả quy trình chứng nhận.', 'Tin chuyên ngành', 'Ụ nổi đo gió FLIDAR của hãng RPS đạt được chứng nhận L2 (L2-Certification)', 'u-noi-do-gio-cua-hang-rps-dat-duoc-chung-nhan-l2-l2-certification', NULL, NULL, 'Ụ nổi đo gió của hãng RPS đạt được chứng nhận L2 (L2-Certification)', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (859, 'vi', 'Để thực hiện được mục tiêu giảm phát thải carbon ra môi trường, tiết kiệm nhiên liệu sử dụng, các doanh nghiệp xi măng cần ứng dụng các công nghệ hiện đại khác nhau trong nhiều khâu của quy trình sản xuất.', 'Tin chuyên ngành', 'Thúc đẩy mục tiêu giảm khí thải carbon trong ngành sản xuất xi măng tại Việt Nam', 'thuc-day-muc-tieu-giam-khi-thai-carbon-trong-nganh-san-xuat-xi-mang-tai-viet-nam', NULL, NULL, 'Thúc đẩy mục tiêu giảm khí thải carbon trong ngành sản xuất xi măng tại Việt Nam', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (860, 'vi', 'We are pleased to invite you to a free training webinar, held on different days in various time zones for your convenience. The webinar duration is about 2 hours.', 'Tin chuyên ngành', 'PIPENET Standard Module - Free Training Webinar 2023', 'pipenet-standard-module-free-training-webinar-2023', NULL, NULL, 'PIPENET Standard Module - Free Training Webinar 2023', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (861, 'vi', 'Đánh số thứ tự trong khi thiết kế bản vẽ CAD phục vụ việc ghi vị trí, đánh dấu các đối tượng có trong bản vẽ. Và trong thực tế chúng ta thường gặp rất nhiều trường hợp khác nhau yêu cầu việc ghi chú số, đánh số thứ tự với số lượng lớn các chi tiết, điểm. Khi này chúng ta sẽ cần sử dụng linh hoạt các tính năng, công cụ có sẵn trong phần mềm để có thể tạo ra số thứ tự nhanh nhất. Hãy cùng CIC đi qua các bước để đánh số thự tự trong bản vẽ CAD một cách hoàn toàn tự động.', 'Tin chuyên ngành', 'Hướng dẫn các phương pháp đánh số thứ tự tự động trong CAD nhanh chóng và tiện lợi', 'huong-dan-cac-phuong-phap-danh-so-thu-tu-tu-dong-trong-cad-nhanh-chong-va-tien-loi', NULL, NULL, 'Hướng dẫn các phương pháp đánh số thứ tự tự động trong CAD nhanh chóng và tiện lợi', '') ON CONFLICT (entity_id, locale) DO NOTHING;
