INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (864, 'vi', 'Hãng phần mềm Computers and Structures, Inc. (CSI) vừa phát hành phiên bản cập nhật mới nhất của phần mềm SAP2000 v24.2.0 & CSiBridge v24.2.0. Chúng tôi - Công ty Cổ phần công nghệ và Tư vấn CIC là  Đại lý ủy quyền của hãng CSI tại Việt Nam, Lào và Campuchia xin gửi tới quý khách hàng những tính năng cập nhật mới nhất.', 'Tin chuyên ngành', 'Phát hành bản cập nhật SAP2000 v24.2.0 và CSiBridge v24.2.0', 'phat-hanh-ban-cap-nhat-sap2000-v2420-va-csibridge-v2420', NULL, NULL, 'Phát hành bản cập nhật SAP2000 v24.2.0 và CSiBridge v24.2.0', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (865, 'vi', 'Thiết bị siêu âm cọc PET (Pile Echo Tester) là một giải pháp cơ động cao, thân thiện với người sử dụng trong việc kiểm tra một số lượng lớn các cọc một cách nhanh chóng và chính xác. Không đòi hỏi phải mất nhiều thời gian đào tạo. Hãy cùng CIC tìm hiểu 8 bước kiểm tra tính toàn vẹn của cọc bằng thiết bị siêu âm cọc PET qua bài viết dưới đây.', 'Tin chuyên ngành', 'Cách kiểm tra tính toàn vẹn của cọc bằng thiết bị siêu âm cọc PET', 'cach-kiem-tra-tinh-toan-ven-cua-coc-bang-thiet-bi-sieu-am-coc-pet', NULL, NULL, 'Cách kiểm tra tính toàn vẹn của cọc bằng thiết bị siêu âm cọc PET', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (866, 'vi', 'Phương pháp động biến dạng nhỏ sử dụng lý thuyết truyền sóng ứng suất để phân tích sóng phản xạ đo được khi thí nghiệm, qua đó xác định độ sâu và dự báo mức độ khuyết tật của cọc. Phương pháp này được áp dụng để phát hiện khuyết tật trên cọc đơn chế tạo bằng bê tông cốt thép hoặc bằng thép, hạ theo phương thẳng đứng hoặc xiên. Hãy cùng CIC tìm hiểu về cách kiểm tra khuyết tật cọc bằng phương pháp động biến dạng nhỏ.', 'Tin chuyên ngành', 'Kiểm tra khuyết tật cọc bằng phương pháp động biến dạng nhỏ', 'kiem-tra-khuyet-tat-coc-bang-phuong-phap-dong-bien-dang-nho', NULL, NULL, 'Kiểm tra khuyết tật cọc bằng phương pháp động biến dạng nhỏ', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (867, 'vi', 'Cơ sở hạ tầng là huyết mạch của xã hội – tạo điều kiện cho nhiều dịch vụ giúp con người, hàng hóa và nền kinh tế vận động. Cơ sở hạ tầng đóng một vai trò quan trọng trong cuộc sống hàng ngày: từ đường bộ, đường sắt, cầu, cảng, mang lại sự kết nối cho đến các con đập, đảm bảo nguồn cung cấp nước. Không có gì ngạc nhiên khi các dự án hạ tầng kỹ thuật luôn là những công trường xây dựng lớn nhất trên thế giới. Allplan đã được sử dụng để hỗ trợ thiết kế những công trình tiêu biểu này.', 'Tin chuyên ngành', 'Định hình thế giới với Allplan: Những dự án hạ tầng kỹ thuật lớn nhất trên thế giới', 'dinh-hinh-the-gioi-voi-allplan:-nhung-du-an-ha-tang-ky-thuat-lon-nhat-tren-the-gioi', NULL, NULL, 'Định hình thế giới với Allplan: Những dự án hạ tầng kỹ thuật lớn nhất trên thế giới', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (868, 'vi', 'Tín chỉ carbon là chứng nhận đại diện cho quyền phát thải ra một tấn carbon dioxide (CO2) hoặc khí nhà kính khác được tổng hợp tương đương 1 tấn CO2 (viết tắt là tCO2e). Đây là đơn vị mua bán trên thị trường tín chỉ carbon.', 'Tin chuyên ngành', 'Tín chỉ carbon là gì ? Cơ hội cho lâm nghiệp hay thách thức với doanh nghiệp sản xuất tại Việt Nam?', 'tin-chi-carbon-la-gico-hoi-cho-lam-nghiep-hay-thach-thuc-voi-doanh-nghiep-san-xuat-tai-viet-nam', NULL, NULL, 'Tín chỉ carbon là gì ? Cơ hội cho lâm nghiệp hay thách thức với doanh nghiệp sản xuất tại Việt Nam?', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (869, 'vi', 'Foxit PDF Editor bản quyền đem lại nhiều chức năng tuyệt vời cho người dùng trong đọc và biên tập file PDF. Trong bài viết dưới đây, CIC sẽ hướng dẫn các bạn kích hoạt bản quyền cho phần mềm Foxit PDF Editor.', 'Tin chuyên ngành', 'Hướng dẫn kích hoạt bản quyền Foxit PDF Editor', 'huong-dan-kich-hoat-ban-quyen-foxit-pdf-editor', NULL, NULL, 'Hướng dẫn kích hoạt bản quyền Foxit PDF Editor', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (870, 'vi', 'DWF là một định dạng tệp phiên bản nén cao của file CAD để xem, in và thiết kế. Trên enjiCAD 2023 hỗ trợ nhập file DWF, hãy cùng CIC tìm hiểu tính năng này trên enjiCAD nhé.', 'Tin chuyên ngành', 'Cách nhập DWF trong enjiCAD 2023', 'cach-nhap-dwf-trong-enjicad-2023', NULL, NULL, 'Cách nhập DWF trong enjiCAD 2023', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (871, 'vi', 'Trước khi triển khai các dự án điện gió thì việc khảo sát đo tốc độ gió là vấn đề tiên quyết. So với việc khảo sát gió trên đất liền, các vấn đề về điều kiện thời tiết, vận chuyển, di chuyển… gây ra khó khăn rất lớn tới công việc khảo sát gió ngoài khơi. Hãy cùng CIC tìm hiểu 3 cách khảo sát gió phổ biến hiện nay cho các dự án điện gió ngoài khơi.', 'Tin chuyên ngành', '3 cách khảo sát đo gió cho các dự án điện gió ngoài khơi', '3-cach-khao-sat-do-gio-cho-cac-du-an-dien-gio-ngoai-khoi', NULL, NULL, '3 cách khảo sát đo gió cho các dự án điện gió ngoài khơi', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (872, 'vi', 'Những năm gần đây, tín chỉ carbon được xem là nguồn lực mới cho Việt Nam, đặc biệt đối với ngành lâm nghiệp. Tuy nhiên tính đến thời điểm hiện tại, ngoài Quảng Nam đã và đang xây dựng đề án bán tín chỉ carbon rừng, hầu hết các doanh nghiệp đều rất mơ hồ về thị trường mới này.', 'Tin chuyên ngành', 'Thị trường tín chỉ carbon – Lộ trình phát triển tại Việt Nam', 'thi-truong-tin-chi-cacbon-–-lo-trinh-phat-trien-tai-viet-nam', NULL, NULL, 'Thị trường tín chỉ carbon – Lộ trình phát triển tại Việt Nam', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (873, 'vi', 'Ngày 8/3/2023, CIC trở thành nhà cung cấp phần mềm enjiCAD và giải pháp BIM toàn diện trong xây dựng cho Công ty TNTech. ', 'Tin công ty', 'CIC ký kết thỏa thuận hợp tác cùng Công ty CP TNTech', 'cic-ky-ket-thoa-thuan-hop-tac-cung-cong-ty-cp-tntech', NULL, NULL, 'CIC ký kết thỏa thuận hợp tác cùng Công ty CP TNTech', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (874, 'vi', 'Vào ngày 3/3 vừa qua, Công ty CP Công nghệ và Tư vấn CIC đã phối hợp cùng Ban Quản lý ĐTXD Dân dụng & Công nghiệp TP. Đà Nẵng tổ chức hội thảo “Những điểm mới về cơ chế chính sách áp dụng BIM và triển khai dự án thực tế”, đem đến những cập nhật mới nhất về chính sách và phương hướng áp dụng BIM vào các dự án thực tế trên địa bàn TP. Hồ Chí Minh', 'Tin công ty', 'CIC phối hợp cùng Ban Quản lý ĐTXD Dân dụng & Công nghiệp TP. Đà Nẵng tổ chức hội thảo “Những điểm mới về cơ chế chính sách áp dụng BIM và triển khai dự án thực tế”', 'cic-phoi-hop-cung-ban-quan-ly-dtxd-dan-dung-amp;-cong-nghiep-tp-da-nang-to-chuc-hoi-thao-nhung-diem-moi-ve-co-che-chinh-sach-ap-dung-bim-va-trien-khai-du-an-thuc-te', NULL, NULL, 'CIC phối hợp cùng Ban Quản lý ĐTXD Dân dụng & Công nghiệp TP. Đà Nẵng tổ chức hội thảo', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (875, 'vi', 'Tại Triển lãm Vietbuild Hà Nội lần thứ nhất năm 2023, CIC sẽ cùng phối hợp với Gopco, đơn vị cung cấp máy gia công ngành nhôm kính, để giới thiệu công nghệ mới cho khách hàng ngành nhôm kính, trong đó có phần mềm bóc tách dự toán Opera Job Management và máy móc gia công.', 'Tin công ty', 'CIC phối hợp cùng với Gopco giới thiệu phần mềm Opera Job Management cho khách hàng ngành nhôm kính tại triển lãm Vietbuild 2023', 'cic-phoi-hop-cung-voi-gopco-gioi-thieu-phan-mem-opera-job-management-cho-khach-hang-nganh-nhom-kinh-tai-trien-lam-vietbuild-2023', NULL, NULL, 'CIC phối hợp cùng với Gopco giới thiệu phần mềm Opera Job Management cho khách hàng ngành nhôm kính', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (876, 'vi', 'Trong quá trình sử dụng và thiết kế trên các phần mềm CAD 2D như AutoCAD hay enjiCAD, chúng ta sẽ không khó bắt gặp phải trường hợp Font chữ trong các bản vẽ khi mở ra bị sai nét, biến thành các ký tự đặc biệt, đó là khi bản vẽ CAD của bạn đang bị lỗi Font. Điều này xảy ra là do các phần mềm chưa hỗ trợ font Tiếng Việt dẫn tới việc hiển thị Font không chuẩn xác, việc này là hoàn toàn bình thường. Dưới đây, CIC sẽ liệt kê một số nguyên nhân cũng như giải pháp để khắc phục lỗi font chữ trong CAD.', 'Tin chuyên ngành', 'Những cách khắc phục hiệu quả lỗi Font chữ trong phần mềm CAD', 'nhung-cach-khac-phuc-hieu-qua-loi-font-chu-trong-phan-mem-cad', NULL, NULL, 'Những cách khắc phục hiệu quả lỗi Font chữ trong phần mềm CAD', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (877, 'vi', 'Chiều ngày 10/03/2023, tại văn phòng Khoa Xây dựng - Học viện Hàng không Việt Nam, Đại diện Công ty CP Công nghệ và Tư vấn CIC đã đến tham quan trao đổi kinh nghiệm và các định hướng hợp tác phát triển với Khoa xây dựng và Học viện Hàng không Việt Nam. Buổi gặp mặt trao đổi đã được chủ trì tiếp đón bởi PGS.TS Nguyễn Thành Đạt - phụ trách Khoa Xây dựng.', 'Tin công ty', 'CÔNG TY CP CÔNG NGHỆ VÀ TƯ VẤN CIC ĐẾN THAM QUAN TRAO ĐỔI KINH NGHIỆM VÀ ĐỊNH HƯỚNG HỢP TÁC PHÁT TRIỂN TẠI HỌC VIỆN HÀNG KHÔNG VIỆT NAM', 'cong-ty-cp-cong-nghe-va-tu-van-cic-den-tham-quan-trao-doi-kinh-nghiem-va-dinh-huong-hop-tac-phat-trien-tai-hoc-vien-hang-khong-viet-nam', NULL, NULL, 'CIC ĐẾN THAM QUAN TRAO ĐỔI KINH NGHIỆM VÀ ĐỊNH HƯỚNG HỢP TÁC PHÁT TRIỂN TẠI HỌC VIỆN HÀNG KHÔNG VN', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (878, 'vi', 'Trước khi thi công dự án điện gió, cần xem xét tiềm năng tài nguyên gió tại nơi lắp đặt và thi công dự án điện gió. Cho đến nay, việc khảo sát gió cho các nhà máy điện gió dựa vào cột đo gió vẫn được sử dụng làm tiêu chuẩn.', 'Tin chuyên ngành', 'Cột đo gió – Giải pháp đo gió cho các dự án điện gió', 'cot-do-gio-–-giai-phap-do-gio-cho-cac-du-an-dien-gio', NULL, NULL, 'Cột đo gió – Giải pháp đo gió cho các dự án điện gió', '') ON CONFLICT (entity_id, locale) DO NOTHING;
