INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (888, 'vi', 'Trong sáng ngày 16/03 vừa qua, Chi bộ Công ty CP Công nghệ và Tư vấn CIC đã tiến hành tổ chức “Lễ kết nạp Đảng viên” nhằm thực hiện kết nạp Đảng cho 2 đồng chí Trần Ngọc Quỳnh và Phạm Chí Hiếu.', 'Tin công ty', 'Chi bộ Công ty CP Công nghệ và Tư vấn CIC tiến hành tổ chức “Lễ kết nạp Đảng viên”', 'chi-bo-cong-ty-cp-cong-nghe-va-tu-van-cic-tien-hanh-to-chuc-le-ket-nap-dang-vien', NULL, NULL, 'Chi bộ Công ty CP Công nghệ và Tư vấn CIC tiến hành tổ chức “Lễ kết nạp Đảng viên”', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (889, 'vi', 'Vào ngày 17/03/2020, Thủ tướng đã ra quyết định số 258/QĐ-TTg về việc Phê duyệt Lộ trình áp dụng Mô hình thông tin công trình (BIM) trong hoạt động xây dựng, đánh dấu một bước tiến trong quá trình áp dụng BIM trong ngành xây dựng tại Việt Nam.', 'Tin chuyên ngành', 'Thủ tướng chính phủ ban hành Quyết định về Lộ trình áp dụng Mô hình thông tin công trình (BIM) trong hoạt động xây dựng', 'thu-tuong-chinh-phu-ban-hanh-quyet-dinh-ve-lo-trinh-ap-dung-mo-hinh-thong-tin-cong-trinh-bim-trong-hoat-dong-xay-dung', NULL, NULL, 'Thủ tướng chính phủ ban hành Quyết định về Lộ trình áp dụng Mô hình thông tin công trình (BIM) trong', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (890, 'vi', 'Công ty CIC và điện lực tỉnh Đồng Tháp vừa phối hợp tổ chức thành công hội thảo về thiết bị dò cáp ngầm RD8200 của hãng Radiodetection (Anh quốc) vào ngày 15/03/2023 tại Điện lực tỉnh Đồng Tháp. Sự kiện quy tụ đại diện của CIC và PC Đồng Tháp, với mục đích giới thiệu, demo và giải đáp thắc mắc về thiết bị RD8200 và hỗ trợ sử dụng trong công tác thực tiễn của PC Đồng Tháp.', 'Tin công ty', 'Công ty CIC và Điện lực Tỉnh Đồng tháp tổ chức thành công hội thảo thiết bị dò cáp ngầm RD8200', 'cong-ty-cic-va-dien-luc-tinh-dong-thap-to-chuc-thanh-cong-hoi-thao', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (891, 'vi', 'Hội thảo giữa công ty CIC và trường Bách khoa - Đại học Cần Thơ đã diễn ra thành công vào ngày 17/3/2023 tại hội trường trường Bách khoa. Sự kiện đã thu hút sự quan tâm và tham gia của nhiều giảng viên và sinh viên đến từ Khoa Kỹ thuật Công trình Giao thông của trường, cùng với đại diện của công ty CIC.', 'Tin công ty', 'Công ty CIC và Đại học Bách Khoa (ĐH Cần Thơ) tổ chức thành công hội thảo phần mềm enjiCAD và thiết bị dò cáp ngầm RD8200', 'cong-ty-cic-va-dai-hoc-bach-khoa-dh-can-tho-to-chuc-thanh-cong-hoi-thao-phan-mem-enjicad-va-thiet-bi-do-cap-ngam-rd8200', NULL, NULL, 'Công ty CIC và Đại học Bách Khoa (ĐH Cần Thơ) tổ chức thành công hội thảo phần mềm enjiCAD và thiết ', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (892, 'vi', 'Những công nghệ mới đang thay đổi tương lai của ngành xây dựng. Hòa vào dòng chảy tương lai này, Công ty CP TNTech đã hợp tác với Công ty CP Công nghệ và Tư vấn CIC mang tới những giải pháp CNTT tích hợp tổng thể trong lĩnh vực xây dựng hạ tầng.', 'Tin công ty', 'TNTech hợp tác CIC bắt nhịp xu thế tương lai ngành xây dựng', 'tntech-hop-tac-cic-bat-nhip-xu-the-tuong-lai-nganh-xay-dung', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (893, 'vi', 'Để tiếp tục triển khai các hoạt động của PC An Giang và công ty CIC, vào ngày 16/03/2023, tại PC An Giang đã tiến hành buổi demo giới thiệu sản phẩm và hướng dẫn sử dụng phần mềm enjiCAD và thiết bị dò cáp ngầm RD8200 do Công ty Cổ phần Công nghệ và Tư vấn CIC (thuộc Bộ xây dựng) thực hiện.', 'Tin công ty', 'Công ty CIC và Điện lực An Giang tổ chức thành công hội thảo về phần mềm enjiCAD và thiết bị RD8200', 'cong-ty-cic-va-pc-an-giang-to-chuc-thanh-cong-hoi-thao-ve-phan-mem-enjicad-va-thiet-bi-rd8200', NULL, NULL, 'Công ty CIC và PC An Giang tổ chức thành công hội thảo về phần mềm enjiCAD và thiết bị RD8200', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (894, 'vi', 'Dù khoa học công nghệ có phát triển, chúng ta vẫn thực sự không thể nhìn thấy địa chất ở độ sâu hàng nghìn mét dưới lòng đất nơi có than, dầu và khí đốt tự nhiên và trữ lượng của chúng. Do đó, việc xây dựng các mô hình địa chất từ dữ liệu của nhiều cuộc khảo sát khác nhau để ước tính các điều kiện dưới bề mặt và đánh giá điều kiện vỉa, trữ lượng tài nguyên là vô cùng cần thiết.', 'Tin chuyên ngành', 'Giải pháp xây dựng và quản lý dữ liệu thông tin địa chất khoáng sản', 'giai-phap-xay-dung-va-quan-ly-du-lieu-thong-tin-dia-chat-khoang-san', NULL, NULL, 'Giải pháp xây dựng và quản lý dữ liệu thông tin địa chất khoáng sản', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (895, 'vi', 'Bụi bẩn tích tụ trên các tấm pin mặt trời sẽ ngăn không cho ánh sáng mặt trời đến được các tấm pin, do đó làm giảm sản lượng điện, có thể lên đến 50% nếu pin mặt trời không được làm sạch trong một tháng. Để làm sạch bụi bẩn thường xuyên, một hệ thống làm sạch tự động giúp loại bỏ bụi bẩn trên tấm pin mặt trời đã được phát triển.', 'Tin chuyên ngành', 'Giải pháp vệ sinh tấm pin năng lượng mặt trời', 'giai-phap-ve-sinh-tam-pin-nang-luong-mat-troi', NULL, NULL, 'Giải pháp vệ sinh tấm pin năng lượng mặt trời', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (896, 'vi', 'Là ngành sản xuất tiềm ẩn nhiều nguy cơ gây ô nhiễm môi trường, thời gian qua, Tập đoàn Công nghiệp Than – Khoáng sản Việt Nam (TKV) đã đầu tư hàng nghìn tỷ đồng mỗi năm cho công tác bảo vệ môi trường, xử lý ô nhiễm bụi, tiếng ồn, đổi mới công nghệ khai thác theo hướng sản xuất “xanh” và phát triển bền vững.', 'Tin chuyên ngành', 'Hệ thống phun sương dập bụi – Mục tiêu phát triển xanh trong công tác bảo vệ môi trường ngành Than', 'he-thong-phun-suong-dap-bui-–-muc-tieu-phat-trien-xanh-trong-cong-tac-bao-ve-moi-truong-nganh-than', NULL, NULL, 'Hệ thống phun sương dập bụi – Mục tiêu phát triển xanh trong công tác bảo vệ môi trường ngành Than', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (897, 'vi', 'Ngày 23/03 vừa qua, tại Trường Đại Học GTVT Thành Phố Hồ Chí Minh, Hội thảo “Giải pháp toàn diện trong thiết kế và quản lý xây dựng” đã được diễn ra thành công với sự góp mặt từ các quý thầy cô, các doanh nghiệp và đông đảo các bạn sinh viên đang học tập tại nhà trường.', 'Tin công ty', 'Tổ chức thành công Hội thảo “Giải pháp toàn diện trong thiết kế và quản lý xây dựng”', 'to-chuc-thanh-cong-hoi-thao-giai-phap-toan-dien-trong-thiet-ke-va-quan-ly-xay-dung', NULL, NULL, 'Tổ chức thành công Hội thảo “Giải pháp toàn diện trong thiết kế và quản lý xây dựng”', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (898, 'vi', 'Computers and Structures, Inc. vừa phát hành phiên bản mới CSiPlant v8.0.0 thay thế cho v7 trước đó. Với những khách hàng đang sử dụng CSiPlant v7 có bảo trì sẽ được nâng cấp lên CSiPlant v8.0.0 hoàn toàn miễn phí. Dưới đây là một số tính năng và thay đổi trong phiên bản mới:', 'Tin chuyên ngành', 'CSiPlant v8.0.0 được phát hành', 'csiplant-v800-duoc-phat-hanh', NULL, NULL, 'CSiPlant v8.0.0 được phát hành', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (899, 'vi', 'Vào đầu năm 2023, Giám đốc Khu vực Châu Á Thái Bình Dương của hãng DNV - Ông Kim Hag Sung, đã gửi đến CIC văn bản xác nhận Quan hệ Hợp tác giữa DNV và CIC cũng như công bố CIC tiếp tục là đại diện ủy quyền chính thức của DNV trong việc phân phối các phần mềm Đánh giá rủi ro định lương (QRA) bao gồm: SAFETI, PHAST, LEAK…tại thị trường Việt Nam.', 'Tin công ty', 'CIC tiếp tục là đại diện ủy quyền chính thức của hãng DNV', 'cic-tiep-tuc-la-dai-dien-uy-quyen-chinh-thuc-cua-hang-dnv', NULL, NULL, 'CIC tiếp tục là đại diện ủy quyền chính thức của hãng DNV', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (921, 'vi', 'Thế giới luôn có nhu cầu sử dụng xi măng và bê tông cho xây dựng và phát triển cơ sở hạ tầng bởi bê tông là vật liệu được sử dụng rộng rãi bởi độ bền, chi phí thấp và tính linh động cao. Tuy nhiên, quá trình sản xuất xi măng và bê tông phát thải ra khối lượng lớn CO2 gây ảnh hưởng lớn tới môi trường.', 'Tin chuyên ngành', 'Cắt Giảm Phát Thải Carbon Để Hướng Đến Mục Tiêu “Xi Măng Xanh”', 'cat-giam-phat-thai-carbon-de-huong-den-muc-tieu-xi-mang-xanh', NULL, NULL, 'Cắt Giảm Phát Thải Carbon Để Hướng Đến Mục Tiêu “Xi Măng Xanh”', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (900, 'vi', 'Từ sau quyết định của Phó Thủ Tướng về việc quyết định áp dụng BIM, giải pháp này đang trở thành đề tài nóng hơn bao giờ hết và trở thành một trong những ưu tiên hàng đầu của nhiều công ty ngành xây dựng trong việc chuyển đổi số. Làm thế nào để triển khai các công cụ số hóa phù hợp để tối ưu hóa quy trình hiệu quả?  Hãy cùng khám phá BIM 5D có thể là yếu tố thay đổi Cuộc chơi cho giai đoạn mời thầu và xây dựng hay không?', 'Tin chuyên ngành', 'HỘI NGHỊ BIM UP VIETNAM 2023 TỪ BIM 5D TỚI QUẢN LÝ CHI PHÍ KỸ THUẬT SỐ', 'hoi-nghi-bim-up-vietnam-2023-tu-bim-5d-toi-quan-ly-chi-phi-ky-thuat-so', NULL, NULL, 'HỘI NGHỊ BIM UP VIETNAM 2023 TỪ BIM 5D TỚI QUẢN LÝ CHI PHÍ KỸ THUẬT SỐ', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (902, 'vi', 'Lệnh BO là một lệnh đã tương đối quen thuộc với người dùng các phần mềm CAD 2D. Đây là lệnh tắt của lệnh Boundary tức là lệnh tạo đường bao bằng các đối tượng Pline bao kín đối tượng có sẵn trên bản vẽ. Việc tạo Boundary sẽ giúp cho đối tượng không bị mất đi trong quá trình sử dụng, hoặc hỗ trợ người dùng trong việc tính diện tích, hay đơn giản là tiện cho việc bắt điểm. Hãy cùng CIC tìm hiểu cách sử dụng lệnh BO trong CAD ở bài viết dưới đây.', 'Tin chuyên ngành', 'Hướng dẫn sử dụng lệnh BO để tạo đường bo boundary nhanh chóng trong CAD', 'huong-dan-su-dung-lenh-bo-de-tao-duong-bo-boundary-nhanh-chong-trong-cad', NULL, NULL, 'Hướng dẫn sử dụng lệnh BO để tạo đường bo boundary nhanh chóng trong CAD', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (901, 'vi', 'Allplan Precast (Planbar) là một công cụ BIM tiên tiến để thiết kế các cấu trúc đúc sẵn và tự động chuyển các dữ liệu cần thiết cho hoạt động của dây chuyền sản xuất đúc sẵn.', 'Tin chuyên ngành', 'ALLPLAN PRECAST (PLANBAR) - CÁC PHƯƠNG PHÁP HỖ TRỢ VÀ TỰ ĐỘNG HÓA HIỆN ĐẠI', 'allplan-precast-planbar-cac-phuong-phap-ho-tro-va-tu-dong-hoa-hien-dai', NULL, NULL, 'ALLPLAN PRECAST (PLANBAR) - CÁC PHƯƠNG PHÁP HỖ TRỢ VÀ TỰ ĐỘNG HÓA HIỆN ĐẠI', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (903, 'vi', 'Thông tin kỹ thuật/Trình quản lý tích hợp (TIM) là một nền tảng để lập kế hoạch 3D, cho phép bạn tối ưu hóa các quy trình liên quan đến sản xuất, hậu cần, lắp ráp và có được các báo cáo đồ họa phù hợp. Nhờ thực tế là làm việc tại Tim dựa trên mô hình 3D, quy trình quản lý quy trình rõ ràng và trực quan.', 'Tin chuyên ngành', 'Trình quản lý THÔNG TIN/TÍCH HỢP kỹ thuật (TIM) trong Allplan Precast', 'trinh-quan-ly-thong-tintich-hop-ky-thuat-tim-trong-allplan-precast', NULL, NULL, 'Trình quản lý THÔNG TIN/TÍCH HỢP kỹ thuật (TIM) trong Allplan Precast', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (904, 'vi', 'Trong quá trình thiết kế, rất nhiều người gặp phải trường hợp các file DWG không thể mở được và đôi khi phần mềm không để lại thông báo lỗi trên màn hình, đa phần sẽ gặp phải thông báo "unable to open drawing file because it contains incorrect or corrupted information". Lý do là vì file CAD đã bị lỗi, điều này có nhiều nguyên nhân gây ra, có thể là do máy tính gặp virus, bản vẽ bị xung đột hoặc bản vẽ gặp lỗi từ máy của người khác. Trong bài viết dưới đây, CIC sẽ hướng dẫn bạn  7 cách khắc phục cơ bản cho vấn đề này.', 'Tin chuyên ngành', 'Cách khắc phục file CAD gặp lỗi và không thể mở được - Hướng dẫn chi tiết', 'cach-khac-phuc-file-cad-gap-loi-va-khong-the-mo-duoc-huong-dan-chi-tiet', NULL, NULL, 'Cách khắc phục file CAD gặp lỗi và không thể mở được - Hướng dẫn chi tiết', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (905, 'vi', 'Hiệu quả của tấm pin năng lượng mặt trời có thể giảm mạnh nếu bụi bẩn tích tụ, để duy trì hiệu quả tối đa, các tấm pin cần được làm sạch. So với phương pháp vệ sinh thủ công, Robot vệ sinh tấm pin năng lượng mặt trời là lựa chọn an toàn, hiệu quả cao cho những trang trại điện mặt trời.', 'Tin chuyên ngành', 'Các tính năng của Robot vệ sinh tấm pin năng lượng mặt trời', 'cac-tinh-nang-cua-robot-ve-sinh-tam-pin-nang-luong-mat-troi', NULL, NULL, 'Các tính năng của Robot vệ sinh tấm pin năng lượng mặt trời', '') ON CONFLICT (entity_id, locale) DO NOTHING;
