INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (907, 'vi', 'Sáng ngày 5/4/2023,  Đại diện Công ty CP Công nghệ và Tư vấn CIC đã tham gia Lễ ký kết Biên bản ghi nhớ hợp tác giữa Autodesk và VC group tại khách sạn Eastin Hà Nội', 'Tin công ty', 'CIC tham gia Lễ ký kết Biên bản ghi nhớ hợp tác giữa Autodesk và VC group', 'cic-tham-gia-le-ky-ket-bien-ban-ghi-nho-hop-tac-giua-autodesk-va-vc-group', NULL, NULL, 'CIC tham gia Lễ ký kết Biên bản ghi nhớ hợp tác giữa Autodesk và VC group', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (908, 'vi', '', 'Quan hệ cổ đông', 'Dự thảo báo cáo hoạt động của BKS', 'du-thao-bao-cao-hoat-dong-cua-bks', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (909, 'vi', 'Vào sáng ngày 7 tháng 4 vừa qua, Công ty CP công nghệ và tư vấn CIC đã tổ chức thành công Đại hội cổ đông thường niên năm 2023  tại Hội trường tầng 6 của Công ty. Đại hội với sự góp mặt đông đảo của các cổ đông cùng đã tổng kết hoạt động năm 2022 và thống nhất một số kế hoạch cho năm 2023.', 'Tin công ty', 'CIC tổ chức thành công Đại hội cổ đông 2023', 'cic-to-chuc-thanh-cong-dai-hoi-co-dong-2023', NULL, NULL, 'CIC tổ chức thành công Đại hội cổ đông 2023', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (910, 'vi', 'Sau quá trình trao đổi và thảo luận, tháng 5/2022, CIC và Heat Transfer Research Inc (HTRI) chính thức ký văn bản thiết lập quan hệ hợp tác lâu dài.', 'Tin công ty', 'CIC CHÍNH THỨC TRỞ THÀNH NHÀ PHÂN PHỐI ĐỘC QUYỀN CỦA HÃNG HEAT TRANSFER RESEARCH INC (HTRI) TẠI VIỆT NAM', 'cic-chinh-thuc-tro-thanh-nha-phan-phoi-doc-quyen-cua-hang-heat-transfer-research-inc-htri-tai-viet-nam', NULL, NULL, 'CIC CHÍNH THỨC TRỞ THÀNH NHÀ PHÂN PHỐI ĐỘC QUYỀN CỦA HÃNG HEAT TRANSFER RESEARCH INC (HTRI) TẠI VIỆT', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (913, 'vi', '', 'Quan hệ cổ đông', 'Nghị quyết Đại hội đồng cổ đông năm 2023', 'nghi-quyet-dai-hoi-dong-co-dong-nam-2023', NULL, NULL, 'Nghị quyết Đại hội đồng cổ đông năm 2023', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (914, 'vi', 'Song song với việc phát hành phần mềm ETABS v21.0.0 hãng Computers and Structures, Inc. cũng cho ra mắt phiên bản hoàn toàn mới SAFE v21.0.0 với nhiều tính năng cải tiến, và sửa các lỗi trong phiên bản SAFE v20 trước đó. Với nhiều năm nghiên cứu và phát triển, hiện nay phần mềm SAFE đã trở nên thân thuộc với các kỹ sư thiết kế, được ứng dụng phổ biến trong lĩnh vực phân tích thiết kế kết cấu hệ thống sàn như sàn bê tông cốt thép, sàn bê tông cáp dự ứng lực và sàn móng...', 'Tin chuyên ngành', 'Tính năng mới trong phần mềm SAFE v21.0.0', 'tinh-nang-moi-trong-phan-mem-safe-v2100', NULL, NULL, 'Tính năng mới trong phần mềm SAFE v21.0.0', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (911, 'vi', 'We are pleased to invite you to a free training webinar, held on different days in various time zones for your convenience. The webinar duration is about 2 hours.', 'Tin chuyên ngành', 'PIPENET for LNG Industry - Free Training Webinar', 'pipenet-for-lng-industry-free-training-webinar', NULL, NULL, 'PIPENET for LNG Industry - Free Training Webinar', '') ON CONFLICT (entity_id, locale) DO NOTHING;
