INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (915, 'vi', 'ROV (Remotely operated underwater vehicle) là robot được thiết kế đặc biệt để làm việc dưới nước. ROV được kết nối với dây cáp giúp điều khiển, cung cấp năng lượng và truyền dữ liệu.', 'Tin chuyên ngành', 'Robot kiểm tra dưới nước (ROV) là gì? Các loại ROV hiện nay', 'robot-kiem-tra-duoi-nuoc-rov-la-gi-cac-loai-rov-hien-nay', NULL, NULL, 'Robot kiểm tra dưới nước (ROV) là gì? Các loại ROV hiện nay', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (916, 'vi', 'Công ty CP Đầu tư và Xây dựng Hạ tầng Đô thị Việt Nam (VINFRACO) là khách hàng truyền thống của CIC, và là một trong những đơn vị tiên phong ở Việt Nam cách đây nhiều năm đã bắt đầu sử dụng thiết bị siêu âm cọc khoan nhồi CHUM của hãng Piletest (Israel) và mới đây lại tiếp tục đặt hàng thêm thiết bị này từ CIC để phục vụ cho công việc và khối lượng dự án lớn của mình.', 'Tin công ty', 'CIC tiếp tục cung cấp thiết bị siêu âm cọc khoan nhồi CHUM của hãng Piletest (Israel) cho Công ty CP Đầu tư và Xây dựng Hạ tầng Đô thị Việt Nam (VINFRACO)', 'cic-tiep-tuc-cung-cap-thiet-bi-sieu-am-coc-khoan-nhoi-chum-cua-hang-piletest-israel-cho-cong-ty-cp-dau-tu-va-xay-dung-ha-tang-do-thi-viet-nam-vinfraco', NULL, NULL, 'CIC tiếp tục cung cấp thiết bị siêu âm cọc khoan nhồi CHUM của hãng Piletest (Israel) cho Công ty CP', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (917, 'vi', 'Vào ngày 14/04/2023, Công ty CIC và Điện lực Bình Thuận (PC Bình Thuận) đã tổ chức thành công hội thảo tại trụ sở của PC Bình Thuận.', 'Tin công ty', 'Công ty CIC và Điện lực Bình Thuận tổ chức thành công hội thảo', 'cong-ty-cic-va-dien-luc-binh-thuan-pc-binh-thuan-da-to-chuc-thanh-cong-hoi-thao', NULL, NULL, 'Công ty CIC và Điện lực Bình Thuận tổ chức thành công hội thảo', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (918, 'vi', 'Để tiếp tục triển khai các hoạt động của PC Đồng Nai và công ty CIC, vào ngày 31/03/2023, tại PC Đồng Nai đã tiến hành buổi demo giới thiệu sản phẩm và hướng dẫn sử dụng phần mềm enjiCAD và các thiết bị do Công ty Cổ phần Công nghệ và Tư vấn CIC (thuộc Bộ xây dựng) thực hiện.', 'Tin công ty', 'Công ty CIC và Điện lực Đồng Nai tổ chức thành công hội thảo', 'cong-ty-cic-va-pc-dong-nai-to-chuc-thanh-cong-hoi-thao', NULL, NULL, 'Công ty CIC và PC Đồng Nai tổ chức thành công hội thảo', 'PC Đồng Nai, enjiCAD') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (919, 'vi', 'Lisp Nam là một phần mềm vẽ ống gió rất quan trọng trong thiết kế hệ thống HVAC bằng phần mềm CAD. Hãy cùng CIC tìm hiểu chi tiết về cách cài đặt sử dụng về phần mềm vẽ ống gió Lisp Nam trên nhé!', 'Tin chuyên ngành', 'Hướng dẫn cài đặt LISP NAM (HVAC) trên phần mềm enjiCAD 2023', 'huong-dan-cai-dat-lisp-nam-hvac-tren-phan-mem-enjicad', NULL, NULL, 'Hướng dẫn cài đặt LISP NAM (HVAC) trên phần mềm enjiCAD 2023', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (920, 'vi', 'Bạn đang tìm kiếm một Giải pháp thay thế Adobe Acrobat có chi phí cao? Bạn muốn một giải pháp PDF nhẹ hơn, an toàn hơn? Bạn muốn chuẩn hóa giải pháp PDF trong toàn doanh nghiệp của mình với chi phí thấp hơn? Câu trả lời chính là Foxit PDF Editor, hãy cùng CIC tìm hiểu về phần mềm này nhé.', 'Tin chuyên ngành', 'Foxit PDF Editor - Giải pháp thay thế Adobe Acrobat', 'foxit-pdf-editor-giai-phap-thay-the-adobe-acrobat', NULL, NULL, 'Foxit PDF Editor - Giải pháp thay thế Adobe Acrobat', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (922, 'vi', 'Sau tạm dừng sau một thời gian do đại dịch Covid, Triển lãm Quốc tế về Xây dựng, Công nghiệp mỏ và Giao thông - Máy móc, thiết bị, Công nghệ, Phương tiện và Vật liệu lần thứ 4 (CONTECH VIETNAM 2023) sẽ được tổ chức từ ngày 21/4/2023 - 24/4/2023 tại Cung Triển lãm Kiến trúc, Quy hoạch Xây dựng quốc gia, Hà Nội.', 'Tin chuyên ngành', 'CONTECH VIETNAM 2023: Kết nối và thúc đẩy tiềm năng phát triển thị trường xây dựng, công nghệ mỏ và giao thông Việt Nam', 'contech-vietnam-2023:-ket-noi-va-thuc-day-tiem-nang-phat-trien-thi-truong-xay-dung-cong-nghe-mo-va-giao-thong-viet-nam', NULL, NULL, 'CONTECH VIETNAM 2023: Kết nối và thúc đẩy tiềm năng  thị trường xây dựng, công nghệ mỏ và giao thông', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (923, 'vi', 'Lĩnh vực kiến trúc, kỹ thuật và xây dựng (AEC) đã thay đổi đáng kể trong những năm vừa qua. Quá trình chuyển đổi kỹ thuật số dần trở nên tiên tiến hơn. Ngày nay, hầu hết các bên liên quan đều được hỗ trợ bởi các giải pháp kỹ thuật số trong toàn bộ quá trình xây dựng. Phần cuối của một hành trình là sự khởi đầu của một sự thay đổi sâu sắc trong ngành xây dựng và bất động sản dựa trên việc sử dụng dữ liệu một cách đột phá và hiệu quả hơn. Năm 2023 sẽ chứng kiến sức ảnh hưởng của công nghệ lên toàn ngành với một số bước phát triển quan trọng, khi công nghệ trở thành một phần không thể thiếu trong quá trình thiết kế và xây dựng.', 'Tin chuyên ngành', 'Công ty CIC cùng đối tác phối hợp tổ chức Hội thảo chuyên đề về ''''Số hóa trong xây dựng từ thiết kế đến thi công và quản lý dự án"', 'cong-ty-cic-va-ait-solutions-thai-lan-phoi-hop-to-chuc-hoi-thao-chuyen-de-ve-so-hoa-trong-xay-dung-tu-thiet-ke-den-thi-cong-va-quan-ly-du-an-', NULL, NULL, 'Công ty CIC cùng đối tác phối hợp tổ chức Hội thảo chuyên đề về ''''Số hóa trong xây dựng từ thiết kế ', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (924, 'vi', 'Lần lượt trong 2 ngày 26 và 27/04, Công ty CP Công nghệ và Tư vấn CIC cùng các đối tác là Viện Công nghệ Châu Á AIT, Hãng phần mềm Allplan, Trường ĐH Giao Thông Vận Tải Hồ Chí Minh và sự phối hợp cùng đơn vị Truyền thông là Tạp Chí Xây dựng - Bộ Xây Dựng đã tổ chức thành công Hội thảo với chủ đề: “Số hóa trong xây dựng từ thiết kế đến thi công và quản lý dự án”', 'Tin công ty', 'Công ty CIC cùng đối tác tổ chức thành công Hội thảo ''''Số hóa trong xây dựng từ thiết kế đến thi công và quản lý dự án"', 'cong-ty-cic-cung-doi-tac-to-chuc-thanh-cong-hoi-thao-so-hoa-trong-xay-dung-tu-thiet-ke-den-thi-cong-va-quan-ly-du-an-', NULL, NULL, 'Công ty CIC cùng đối tác tổ chức thành công Hội thảo ''''Số hóa trong xây dựng từ thiết kế đến thi côn', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (925, 'vi', 'Robot kiểm tra dưới nước (ROV) là hệ thống robot có thể lặn, được điều khiển từ bờ hoặc thợ lặn dưới nước sử dụng để quan sát độ sâu của các vùng nước lớn. Hãy cùng CIC tìm hiểu các ứng dụng phổ biến của ROV nhé.', 'Tin chuyên ngành', 'Các ứng dụng chính của Robot kiểm tra dưới nước (ROV)', 'cac-ung-dung-chinh-cua-robot-kiem-tra-duoi-nuoc-rov', NULL, NULL, 'Các ứng dụng chính của Robot kiểm tra dưới nước (ROV)', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (926, 'vi', 'Trong quá trình sử dụng và thiết kế trên các phần mềm CAD 2D như AutoCAD hay enjiCAD, chúng ta sẽ không khó bắt gặp phải trường hợp Font chữ trong các bản vẽ khi mở ra bị sai nét, biến thành các ký tự đặc biệt, đó là khi bản vẽ CAD của bạn đang bị lỗi Font. Điều này xảy ra là do các phần mềm chưa hỗ trợ font Tiếng Việt dẫn tới việc hiển thị Font không chuẩn xác, việc này là hoàn toàn bình thường. Dưới đây, CIC sẽ liệt kê một số nguyên nhân cũng như giải pháp để khắc phục lỗi font chữ trong CAD.', 'Tin chuyên ngành', 'Lỗi Font chữ trong phần mềm CAD và những cách khắc phục hiệu quả', 'loi-font-chu-trong-phan-mem-cad-va-nhung-cach-khac-phuc-hieu-qua', NULL, NULL, 'Lỗi Font chữ trong phần mềm CAD và những cách khắc phục hiệu quả', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (927, 'vi', 'Chiều ngày 13/04, CIC và Trung tâm Phối hợp Tìm kiếm Cứu nạn, Hàng hải Việt Nam (MRCC) đã tổ chức Hội thảo về các giải pháp cho lĩnh vực tìm kiếm cứu nạn hàng hải.', 'Tin công ty', 'CIC GIỚI THIỆU ROBOT LẶN BIỂN CHO TRUNG TÂM PHỐI HỢP TÌM KIẾM, CỨU NẠN HÀNG HẢI VIỆT NAM', 'cic-gioi-thieu-robot-lan-bien-cho-trung-tam-phoi-hop-tim-kiem-cuu-nan-hang-hai-viet-nam', NULL, NULL, 'CIC GIỚI THIỆU ROBOT LẶN BIỂN CHO TRUNG TÂM PHỐI HỢP TÌM KIẾM, CỨU NẠN HÀNG HẢI VIỆT NAM', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (928, 'vi', 'Đôi khi trong quá trình làm việc với phần mềm thiết kế CAD như AutoCAD hay phần mềm thay thế enjiCAD ta sẽ gặp phải một số trường hợp hi hữu khiến cho máy tính tắt bất chợt và khi đó bản vẽ chưa được lưu lại. Thực tế đây là trường hợp rất hay xảy ra, ví dụ như khi bị cúp điện, do hệ điều hành hay do phần cứng máy tính. Những vấn đề không mong muốn này ít nhiều kỹ sư đã gặp phải, và nhiều người cảm thấy bối rối khi không biết lấy lại bản vẽ ở đâu. Vậy làm sao để lấy lại file CAD chưa kịp lưu nhanh chóng, cùng CIC tìm hiểu dưới bài viết sau đây nhé.', 'Tin chuyên ngành', 'Hướng dẫn cách lấy lại file CAD bị mất do chưa lưu', 'huong-dan-cach-lay-lai-file-cad-bi-mat-do-chua-kip-luu', NULL, NULL, 'Hướng dẫn cách lấy lại file CAD bị mất do chưa lưu', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (929, 'vi', 'Sắp tới đây, vào ngày 19 tháng 5 năm 2023, Công ty Cổ phần Công nghệ và Tư vấn CIC phối hợp với Carbon Re (V.Q Anh) và STX Group (Hà Lan) sẽ tổ chức Hội thảo với chủ đề “Giải pháp công nghệ giảm phát thải khí nhà kính trong ngành công nghiệp xi măng và thép tại Việt Nam” dưới sự bảo trợ chính thức của Bộ Xây dựng, Đại sứ quán Vương Quốc Anh và Đại sứ quán Hà Lan', 'Tin công ty', 'HỘI THẢO “GIẢI PHÁP CÔNG NGHỆ GIẢM PHÁT THẢI KHÍ NHÀ KÍNH TRONG NGÀNH CÔNG NGHIỆP XI MĂNG VÀ THÉP TẠI VIỆT NAM”', 'hoi-thao-giai-phap-cong-nghe-giam-phat-thai-khi-nha-kinh-trong-nganh-cong-nghiep-xi-mang-va-thep-tai-viet-nam', NULL, NULL, 'HỘI THẢO GIẢI PHÁP CÔNG NGHỆ GIẢM PHÁT THẢI KHÍ NHÀ KÍNH TRONG NGÀNH CÔNG NGHIỆP XI MĂNG VÀ THÉP', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (930, 'vi', 'Robot kiểm tra dưới nước (ROV) được sử dụng trong nhiều lĩnh vực khác nhau như: tìm kiếm cứu nạn, quân sự, giải trí và khám phá, kiểm tra nuôi trồng thủy sản, sinh học biển, dầu khí, năng lượng ngoài khơi, công trình dưới nước… Chúng cho phép người dùng chụp ảnh và quay video, giúp xác định được vị trí mục tiêu dưới nước và khám phá độ sâu của đại dương, sông, hồ. Hôm nay hãy cùng CIC tìm hiểu những lợi ích của ROV so với phương pháp lặn truyền thống nhé!', 'Tin chuyên ngành', 'Lợi ích của Robot kiểm tra dưới nước', 'loi-ich-cua-robot-kiem-tra-duoi-nuoc', NULL, NULL, 'Lợi ích của Robot kiểm tra dưới nước', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (931, 'vi', 'Được sự bảo trợ của Bộ Xây dựng, Đại sứ quán Vương quốc Anh tại Việt Nam và Đại sự quán Hà Lan tại Việt Nam, ngày 19/5/2023 vừa qua, tại Hà Nội, Công ty Cổ phần Công nghệ và tư vấn CIC phối hợp với Công ty Carbon Re và Công ty STX Group tổ chức hội thảo “Giải pháp công nghệ giảm phát thải khí nhà kính trong ngành công nghiệp xi măng và thép tại Việt Nam”.', 'Tin công ty', 'Tổ chức thành công Hội thảo “Giải pháp công nghệ giảm phát thải khí nhà kính trong ngành công nghiệp xi măng và thép tại Việt Nam”', 'to-chuc-thanh-cong-hoi-thao-giai-phap-cong-nghe-giam-phat-thai-khi-nha-kinh-trong-nganh-cong-nghiep-xi-mang-va-thep-tai-viet-nam', NULL, NULL, 'Tổ chức thành công Hội thảo “Giải pháp công nghệ giảm phát thải khí nhà kính trong ngành công nghiệp', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (932, 'vi', 'Ngày 17/05, Chuyên gia phần mềm MIKE của Công ty CIC đã giới thiệu trực tuyến đến các bộ kỹ thuật Công ty Thủy điện Sơn La về phần mềm MIKE +. Phần mềm này chuyên dụng cho bài toán phân tích dòng chảy va đập cho đập thủy điện.', 'Tin công ty', 'CIC giới thiệu phần mềm MIKE của hãng DHI cho thủy điện Sơn La', 'cic-gioi-thieu-phan-mem-mike-cua-hang-dhi-cho-thuy-dien-son-la', NULL, NULL, 'CIC giới thiệu phần mềm MIKE của hãng DHI cho thủy điện Sơn La', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (933, 'vi', 'Hôm qua, ngày 17/5/2023, Công ty CP Công nghệ và Tư vấn CIC cùng hãng phần mềm mô phỏng ANSYS đã tổ chức thành công hội thảo tại Công ty cổ phần Tư vấn Xây dựng Điện 1 (PECC1) về các giải pháp phần mềm của ANSYS cho các lĩnh vực khác nhau, trong đó có Năng lượng tái tạo (Điện gió, Điện mặt trời), Nhiệt điện và Thủy điện – đều là các lĩnh vực chủ chốt của PECC1 hiện nay.', 'Tin công ty', 'CIC CÙNG HÃNG ANSYS VÀ PECC1 TỔ CHỨC HỘI THẢO VỀ CÁC GIẢI PHÁP PHẦN MỀM CHO NHIỆT ĐIỆN, THỦY ĐIỆN VÀ NĂNG LƯỢNG TÁI TẠO', 'cic-cung-hang-ansys-va-pecc1-to-chuc-hoi-thao-ve-cac-giai-phap-phan-mem-cho-nhiet-dien-thuy-dien-va-nang-luong-tai-tao', NULL, NULL, 'CIC CÙNG HÃNG ANSYS VÀ PECC1 TỔ CHỨC HỘI THẢO VỀ CÁC GIẢI PHÁP PHẦN MỀM CHO NHIỆT ĐIỆN, THỦY ĐIỆN', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (934, 'vi', 'Phần mềm chi tiết thép là nền tảng cho các dự án BIM trong kết cấu thép, cho dù bạn đang tích hợp vào quy trình làm việc BIM thực sự và điều phối dữ liệu mô hình với các nghề khác (thường được gọi là macro BIM) hoặc quản lý hàng tồn kho và sản xuất trong cửa hàng của riêng bạn (micro BIM).', 'Tin chuyên ngành', 'SDS2 by ALLPAN - Cách SDS2 cải thiện các dự án BIM trong kết cấu thép', 'sds2-by-allpan---cach-sds2-cai-thien-cac-du-an-bim-trong-ket-cau-thep', NULL, NULL, 'SDS2 by ALLPAN - Cách SDS2 cải thiện các dự án BIM trong kết cấu thép', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (935, 'vi', 'PC Ninh Thuận và Công ty Cổ phần Công nghệ và Tư vấn (CIC), đã tổ chức thành công buổi demo phần mềm enjiCAD.', 'Tin công ty', 'Sự kết hợp thành công giữa Điện lực Ninh Thuận và Công ty CIC', 'su-ket-hop-thanh-cong-giua-pc-ninh-thuan-va-cong-ty-cic', NULL, NULL, 'Sự kết hợp thành công giữa PC Ninh Thuận và Công ty CIC', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (936, 'vi', 'Ngày 25/05 vừa qua, tập thể Công ty CP Công nghệ và Tư vấn CIC đã tổ chức thành công Đại hội Công đoàn nhằm tổng kết hoạt động nhiệm kỳ 2017-2023 và phương hướng nhiệm vụ nhiệm kỳ 2023-2028.', 'Tin công ty', 'CIC tổ chức thành công Đại hội Công đoàn tổng kết hoạt động nhiệm kỳ 2017-2023 và phương hướng nhiệm vụ nhiệm kỳ 2023-2028', 'cic-to-chuc-thanh-cong-dai-hoi-cong-doan-tong-ket-hoat-dong-nhiem-ky-2017-2023-va-phuong-huong-nhiem-vu-nhiem-ky-2023-2028', NULL, NULL, 'CIC tổ chức Đại hội Công đoàn tổng kết hoạt động nhiệm kỳ 2017-2023 và nhiệm vụ 2023-2028', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (937, 'vi', 'DNV đã nhận được sự chấp thuận từ Pipeline and Hazardous Materials Safety Administration (PHMSA) để sử dụng Phast 8.4 như một mô hình thay thế cho sự phân tán khí gas và hơi dễ cháy của Liquefied Natural Gas (LNG).', 'Tin chuyên ngành', 'Phast 8.4 được chấp thuận sử dụng cho tính toán sự phân tán khí gas và hơi dễ cháy của LNG', 'phast-84-duoc-chap-thuan-su-dung-cho-tinh-toan-su-phan-tan-khi-gas-va-hoi-de-chay-cua-lng', NULL, NULL, 'Phast 8.4 được chấp thuận sử dụng cho tính toán sự phân tán khí gas và hơi dễ cháy của LNG', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (938, 'vi', 'Kiểm kê khí nhà kính đóng vai trò quan trọng trong việc bảo vệ môi trường và giảm thiểu tác động của thay đổi khí hậu, là bước quan trọng để Việt Nam đạt mức phát thải ròng bằng 0 (Net Zero ) vào năm 2050.', 'Tin chuyên ngành', 'Kiểm kê Khí nhà kính – Bước hành động quan trọng trong lộ trình đạt Net Zero 2050', 'kiem-ke-khi-nha-kinh-buoc-hanh-dong-quan-trong-trong-lo-trinh-dat-net-zero-2050', NULL, NULL, 'Kiểm kê Khí nhà kính – Bước hành động quan trọng trong lộ trình đạt Net Zero 2050', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (939, 'vi', 'Chiều ngày 12/5/2023, Sở Xây dựng Quảng Ninh kết hợp cùng Công ty Cổ phần Công nghệ và Tư vấn CIC, Viện Kinh Tế Xây Dựng đã tổ chức thành công buổi tập huấn. “Áp dụng BIM cho dự án đầu tư xây dựng, từ cơ chế, chính sách đến thực tiễn”', 'Tin công ty', 'Sở xây dựng Quảng Ninh kết hợp với Công ty Cổ phần Công nghệ và Tư vấn CIC, Viện Kinh Tế Xây Dựng tổ chức thành công lớp tập huấn “Áp dụng BIM cho dự án đầu tư xây dựng, từ cơ chế, chính sách đến thực tiễn”', 'so-xay-dung-quang-ninh-ket-hop-voi-cong-ty-co-phan-cong-nghe-va-tu-van-cic-vien-kinh-te-xay-dung-to-chuc-thanh-cong-lop-tap-huan-ap-dung-bim-cho-du-an-dau-tu-xay-dung-tu-co-che-chinh-sach-den-thuc-tien', NULL, NULL, 'Sở xây dựng Quảng Ninh kết hợp với CIC, Viện Kinh Tế Xây Dựng tổ chức thành công lớp tập huấn', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (940, 'vi', 'Sáng ngày 08/6/2023, tại Hội trường Nhà khách Văn phòng UBND, Sở Xây dựng tỉnh An Giang đã tổ chức Hội thảo tập huấn lộ trình áp dụng Mô hình thông tin công trình (BIM) trong hoạt động xây dựng theo Quyết định số 258/QĐ-TTg của Thủ tướng Chính phủ. Hội thảo do ông Phan Duy Quang – Phó giám đốc Sở Xây dựng chủ trì', 'Tin công ty', 'Hội thảo tập huấn lộ trình áp dụng Mô hình thông tin công trình (BIM) trong hoạt động xây dựng theo Quyết định số 258/QĐ-TTg của Thủ tướng Chính phủ tại An Giang', 'hoi-thao-tap-huan-lo-trinh-ap-dung-mo-hinh-thong-tin-cong-trinh-bim-trong-hoat-dong-xay-dung-theo-quyet-dinh-so-258qd-ttg-cua-thu-tuong-chinh-phu', NULL, NULL, 'Hội thảo tập huấn lộ trình áp dụng Mô hình thông tin công trình (BIM) trong hoạt động xây dựng', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (941, 'vi', 'Vào ngày 10 tháng 6 năm 2023, Lễ giao giải &quot;Kỳ thi Olympic Cơ học toàn quốc lần thứ 33&quot; đã diễn ra tại Hội trường Học viện Kỹ thuật Quân sự. Đây là một sự kiện đặc biệt trong lĩnh vực cơ học, thu hút hàng ngàn thí sinh tài năng đến từ khắp đất nước.', 'Tin công ty', 'CIC tài trợ &quot;Kỳ thi Olympic Cơ học toàn quốc lần thứ 33&quot;', 'cic-tai-tro--ky-thi-olympic-co-hoc-toan-quoc-lan-thu-33-', NULL, NULL, 'CIC tài trợ &quot;Kỳ thi Olympic Cơ học toàn quốc lần thứ 33&quot;', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (942, 'vi', 'Trong 2 ngày 9 và 10 tháng 6 vừa qua, Công ty CP Công nghệ và Tư vấn CIC đã tổ chức một chương trình đào tạo kinh doanh cho CBNV trong công ty. Chương trình này nhằm nâng cao năng lực kinh doanh và bán hàng quan trọng cho đội ngũ CBNV của công ty hướng tới gia tăng hiệu quả doanh số mạnh mẽ. Khóa học được tổ chức bởi Học viện PTI.', 'Tin công ty', 'CIC tổ chức khóa đào tạo kỹ năng kinh doanh cho cán bộ nhân viên', 'cic-to-chuc-khoa-dao-tao-ky-nang-kinh-doanh-cho-can-bo-nhan-vien', NULL, NULL, 'CIC tổ chức khóa đào tạo kỹ năng kinh doanh cho cán bộ nhân viên', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (943, 'vi', 'Ngày 6/6 vừa qua, Công ty CIC đã tổ chức hội thảo "Lộ trình áp dụng mô hình thông tin công trình (BIM) trong hoạt động xây dựng" tại sở xây dựng tỉnh Đồng Nai nhằm thực hiện theo Quyết định số 258/QĐ-TTg ngày 17/3/2023 của Thủ tướng Chính phủ về phê duyệt lộ trình áp dụng mô hình thông tin công trình (BIM) trong hoạt động xây dựng.', 'Tin công ty', 'CIC tổ chức hội thảo "Lộ trình áp dụng mô hình thông tin công trình (BIM) trong hoạt động xây dựng" tại sở xây dựng tỉnh Đồng Nai', 'cic-to-chuc-hoi-thaolo-trinh-ap-dung-mo-hinh-thong-tin-cong-trinh-bim-trong-hoat-dong-xay-dungtai-so-xay-dung-tinh-dong-nai', NULL, NULL, 'CIC tổ chức hội thảo "Lộ trình áp dụng mô hình thông tin công trình (BIM) trong hoạt động xây dựng"', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (944, 'vi', 'CIC đang cần tuyển dụng vị trí SENIOR BIM MODELER với thu nhập hấp dẫn lên tới hơn 1.000$/tháng', 'Tin tuyển dụng', 'TUYỂN DỤNG SENIOR BIM MODELER', 'tuyen-dung-senior-bim-modeler', NULL, NULL, 'TUYỂN DỤNG SENIOR BIM MODELER', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (945, 'vi', 'Ngày 31/5/2023, Công ty CP Công nghệ và Tư vấn CIC cùng hãng phần mềm FLOW SCIENCES đã tổ chức thành công hội thảo tại Công ty cổ phần Tư vấn Xây dựng Điện 1 (PECC1) về phần mềm FLOW 3D cho lĩnh vực Thủy điện.', 'Tin công ty', 'CIC CÙNG HÃNG FLOW SCIENCE VÀ PECC1 TỔ CHỨC HỘI THẢO VỀ PHẦN MỀM FLOW3D CHO MÔ PHỎNG DÒNG CHẢY', 'cic-cung-hang-flow-science-va-pecc1-to-chuc-hoi-thao-ve-phan-mem-flow3d-cho-mo-phong-dong-chay', NULL, NULL, 'CIC CÙNG HÃNG FLOW SCIENCE VÀ PECC1 TỔ CHỨC HỘI THẢO VỀ PHẦN MỀM FLOW3D CHO MÔ PHỎNG DÒNG CHẢY', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (946, 'vi', 'SODAR (Sound Detection And Ranging) là một công nghệ viễn thám trên mặt đất truyền (qua loa) một xung âm thanh hình Sin (thường là 50 ms) vào không khí, sau đó lắng nghe các tín hiệu trả về trong một khoảng thời gian ngắn, đo các sóng âm thanh bị phân tán trở lại. Dựa vào cường độ và sự thay đổi Doppler của xung âm thanh có thể xác định tốc độ và hướng gió. SODAR bao gồm ba hoặc nhiều chùm tia ở các góc khác nhau so với phương thẳng đứng, cho phép thu được biên dạng gió thẳng đứng theo ba chiều.', 'Tin chuyên ngành', 'Sodar - Giải pháp đo gió hiệu quả cho điện gió', 'sodar-giai-phap-do-gio-hieu-qua-cho-dien-gio', NULL, NULL, 'Sodar - Giải pháp đo gió hiệu quả cho điện gió', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (947, 'vi', 'Trong hai ngày 07-08/06, CIC đã tổ chức thành công Hội thảo giới thiệu robot giám sát dưới nước cho Tập đoàn BITEXCO, các đơn vị thủy điện trực thuộc Tập đoàn và thử nghiệm trực tiếp tại Thủy điện Bá Thước 2.', 'Tin công ty', 'CIC GIỚI THIỆU ROBOT GIÁM SÁT DƯỚI NƯỚC CHO TẬP ĐOÀN BITEXCO VÀ CÁC ĐƠN VỊ THÀNH VIÊN', 'cic-gioi-thieu-robot-giam-sat-duoi-nuoc-cho-tap-doan-bitexco-va-cac-don-vi-thanh-vien', NULL, NULL, 'CIC GIỚI THIỆU ROBOT GIÁM SÁT DƯỚI NƯỚC CHO TẬP ĐOÀN BITEXCO VÀ CÁC ĐƠN VỊ THÀNH VIÊN', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (948, 'vi', 'Foxit Software vừa ra mắt sản phẩm mới của mình vào tháng 5 năm 2023 vừa qua với 2 phiên bản PDF Editor Suite Pro for Teams 2023 và PDF Editor Suite for Teams 2023, sản phẩm đã thu hút được sự quan tâm đông đảo của người dùng với nhiều ưu điểm ấn tượng', 'Tin chuyên ngành', 'Foxit Software ra PDF Editor Suite Pro for Teams 2023 và PDF Editor Suite for Teams 2023', 'foxit-software-ra-pdf-editor-suite-pro-for-teams-2023-va-pdf-editor-suite-for-teams-2023', NULL, NULL, 'Foxit Software ra PDF Editor Suite Pro for Teams 2023 và PDF Editor Suite for Teams 2023', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (949, 'vi', 'Hãy cũng CIC tìm hiểu cách làm hiển thị Tab File đang mở trong enjiCAD trong bài viết dưới đây nhé!', 'Tin chuyên ngành', 'Hướng Dẫn Hiển Thị Tab File Đang Mở Trong enjiCAD', 'huong-dan-hien-thi-tab-file-dang-mo-trong-enjicad', NULL, NULL, 'Hướng Dẫn Hiển Thị Tab File Đang Mở Trong enjiCAD', '') ON CONFLICT (entity_id, locale) DO NOTHING;
