INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (951, 'vi', 'Hãng phần mềm PYTHA giới thiệu PYTHA Lite - một phiên bản mới cho các doanh nghiệp sản xuất gỗ công nghiệp. Với PYTHA Lite, chúng tôi mang đến cho bạn một công cụ mạnh mẽ và linh hoạt để tối ưu hóa quy trình thiết kế và sản xuất trong ngành công nghiệp gỗ.', 'Tin chuyên ngành', 'PYTHA phát hành phiên bản PYTHA Lite cho nhóm sản phẩm gỗ công nghiệp', 'pytha-phat-hanh-phien-ban-pytha-lite-cho-nhom-san-pham-go-cong-nghiep', NULL, NULL, 'PYTHA phát hành phiên bản PYTHA Lite cho nhóm sản phẩm gỗ công nghiệp', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (952, 'vi', 'Từ ngày 25-28 tháng 6 năm 2023 tại Hà Nội diễn ra Hội nghị và Triển lãm kỹ thuật Cemtech Asia 2023 với sự tham dự của các chuyên gia, doanh nghiệp ngành xi măng từ hơn 35 quốc gia trong khu vực.', 'Tin chuyên ngành', 'Hội nghị và Triển lãm kỹ thuật Cemtech Asia 2023', 'hoi-nghi-va-trien-lam-ky-thuat-cemtech-asia-2023', NULL, NULL, 'Hội nghị và Triển lãm kỹ thuật Cemtech Asia 2023', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (953, 'vi', 'Ngày 16/6/2023, Ông Shitalkumar Joshi - Giám Đốc Kỹ thuật ANSYS khu vực Châu Á – Thái Bình Dương của hãng ANSYS và đại diện Công ty CIC đã có buổi gặp thân mật với lãnh đạo Tổng Công ty Sản xuất Thiết bị Viettel (VMC).', 'Tin công ty', 'CIC CÙNG ĐẠI DIỆN HÃNG ANSYS GẶP MẶT LÃNH ĐẠO TỔNG CÔNG TY SẢN XUẤT THIẾT BỊ VIETTEL (VMC)', 'cic-cung-dai-dien-hang-ansys-gap-mat-lanh-dao-tong-cong-ty-san-xuat-thiet-bi-viettel-vmc', NULL, NULL, 'CIC CÙNG ĐẠI DIỆN HÃNG ANSYS GẶP MẶT LÃNH ĐẠO TỔNG CÔNG TY SẢN XUẤT THIẾT BỊ VIETTEL (VMC)', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (954, 'vi', 'Năm 2022-2023 là một gia đoạn đánh dấu sự phát triển hợp tác vượt bậc giữa Công ty CP Công nghệ và Tư vấn CIC cùng hãng DNV. Chuyến thăm của Giám đốc điều hành DNV Digital Solutions – Mr Vareide Kenneth mới đây ngày 27/4/2023 lại càng khẳng định sự trân trọng và tin tưởng của DNV đối với CIC và thị trường Việt Nam, đặc biệt trong lĩnh vực Đánh giá rủi ro Định lượng (QRA) và An toàn sức khỏe môi trường (QHSE) với các phần mềm PHAST, SAFETI, SYNERGI LIFE,…', 'Tin công ty', 'CEO DNV-Digital Solutions đến thăm chính thức và làm việc với CIC', 'ceo-dnv-digital-solutions-den-tham-chinh-thuc-va-lam-viec-voi-cic', NULL, NULL, 'CEO DNV-Digital Solutions đến thăm chính thức và làm việc với CIC', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (955, 'vi', 'CIC và PC Bình Dương tổ chức thành công Hội thảo về phần mềm Enjicad ứng dụng trong Ngành điện. ', 'Tin công ty', 'CIC và Điện lực Bình Dương tổ chức thành công hội thảo phần mềm enjiCAD', 'cic-va-dien-luc-binh-duong-pc-binh-duong-to-chuc-thanh-cong-hoi-thao-phan-mem-enjicad', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (956, 'vi', 'Hoạt động tìm kiếm cứu nạn hàng hải là nhiệm vụ đặc biệt quan trọng đối với quốc gia ven biển. Lực lượng tìm kiếm cứu nạn hàng hải với nguồn lực sẵn có cần tận dụng tốt thời gian vàng để chống lại các ảnh hưởng bởi điều kiện thời tiết và biến đổi khí hậu. Trong bối cảnh như vậy, kế hoạch tối ưu đóng một vai trò quan trọng trong việc hoàn thành xuất sắc sứ mệnh. SAROPS là một mô hình hỗ trợ kế hoạch tối ưu cho tàu SAR. Mô hình này hỗ trợ hoạch định con đường hiệu quả nhất cho tàu SAR, SAROPS đã được lực lượng tìm kiếm cứu nạn hàng hải Việt Nam sử dụng trong các tình huống thực tế.', 'Tin chuyên ngành', 'SAROPS - Giải pháp cho hoạt động tìm kiếm cứu nạn hàng hải', 'sarops-giai-phap-cho-hoat-dong-tim-kiem-cuu-nan-hang-hai', NULL, NULL, 'SAROPS - Giải pháp cho hoạt động tìm kiếm cứu nạn hàng hải', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (957, 'vi', 'Chiều ngày 08/06, CIC đã tổ chức thành công Hội thảo giới thiệu robot giám sát dưới nước cho Công ty CP Tư vấn Xây dựng Điện 1 (PECC1).', 'Tin công ty', 'CIC giới thiệu Robot giám sát dưới nước cho PECC1', 'cic-gioi-thieu-robot-giam-sat-duoi-nuoc-cho-pecc1', NULL, NULL, 'CIC giới thiệu Robot giám sát dưới nước cho PECC1', '') ON CONFLICT (entity_id, locale) DO NOTHING;
