INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (959, 'vi', 'Thiết bị PET (Pile Echo Tester) sử dụng phương pháp pulse-echo.  PET đạt được độ chính xác với sai số thấp hơn 2% trong kiểm tra cọc.', 'Tin chuyên ngành', 'Độ chính xác của PET trong kiểm tra cọc là bao nhiêu?', 'do-chinh-xac-cua-pet-trong-kiem-tra-coc-la-bao-nhieu', NULL, NULL, 'Độ chính xác của PET trong kiểm tra cọc là bao nhiêu?', '') ON CONFLICT (entity_id, locale) DO NOTHING;
