INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1076, 'vi', 'Phiên bản cập nhật phần mềm SAP2000 v25.1.0 và CSiBridge v25.1.0 mới nhất đã chính thức được phát hành. Những khách hàng đang sử dụng phần mềm có bản quyền kèm bảo trì còn hiệu lực sẽ được nâng cấp miễn phí.', 'Tin chuyên ngành', 'Chính thức phát hành bản cập nhật phần mềm SAP2000 v25.1.0 và CSiBridge v25.1.0', 'chinh-thuc-phat-hanh-ban-cap-nhat-phan-mem-sap2000-v2510-va-csibridge-v2510', NULL, NULL, 'Chính thức phát hành bản cập nhật phần mềm SAP2000 v25.1.0 và CSiBridge v25.1.0', '') ON CONFLICT (entity_id, locale) DO NOTHING;
