INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1013, 'vi', 'Công ty CIC gửi Thư cảm ơn tới các đơn vị, cơ quan, cán bộ nhân viên Tổ hợp Tư vấn Xây dựng Việt Nam đã quyên góp, ủng hộ gia đình cán bộ CIC trong vụ cháy tại Chung cư phố Khương Hạ ngày 12/9/2023.', 'Tin công ty', 'Thư Cảm ơn Các Đơn vị, Cơ quan, Cán bộ Nhân viên đã quyên góp, hỗ trợ gia đình cán bộ CIC', 'thu-cam-on-cac-don-vi-co-quan-can-bo-nhan-vien-da-quyen-gop-ho-tro-gia-dinh-can-bo-cic', NULL, NULL, 'Thư Cảm ơn Các Đơn vị, Cơ quan, Cán bộ Nhân viên đã quyên góp, hỗ trợ gia đình cán bộ CIC', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1014, 'vi', 'Chương trình Trung thu yêu thương lần thứ 13 do Công ty CIC và Chi đoàn khối văn phòng Đại học Quốc gia TP HCM tổ chức đã mang lại không khí trung thu vui tươi, ấm áp cho các em nhỏ tại xã Hưng Điền A (Vĩnh Long – Long An).', 'Tin công ty', 'CIC và Chi Đoàn khối Văn phòng Đại học Quốc Gia TP.HCM tổ chức chương trình “Trung Thu Yêu Thương” lần thứ 13', 'cic-va-chi-doan-khoi-van-phong-dai-hoc-quoc-gia-tphcm-to-chuc-chuong-trinh-trung-thu-yeu-thuong-lan-thu-13', NULL, NULL, 'CIC và Chi Đoàn khối Văn phòng Đại học Quốc Gia TP.HCM tổ chức chương trình “Trung Thu Yêu Thương” l', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1015, 'vi', 'PTV Lines là phần mềm giao thông công cộng có phạm vị rộng, dễ sử dụng, dựa trên trình duyệt web và có máy chủ tại EU.', 'Tin chuyên ngành', 'PTV Lines – Công cụ giao thông công cộng có phạm vi rộng và dễ sử dụng', 'ptv-lines-la-cong-cu-giao-thong-cong-cong-pham-vi-rong', NULL, NULL, 'PTV Lines – Công cụ giao thông công cộng có phạm vi rộng và dễ sử dụng', '') ON CONFLICT (entity_id, locale) DO NOTHING;
