INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1019, 'vi', 'Cơ chế điều chỉnh biên giới Carbon (viết tắt là CBAM) được EU ban hành và là chính sách nhằm chống rò rỉ carbon đối với hàng hóa nhập khẩu vào thị trường các nước EU dựa trên cường độ phát thải khí nhà kính trong quy trình sản xuất tại nước sở tại.', 'Tin chuyên ngành', 'CBAM là gì? Lộ trình thực hiện Cơ chế điều chỉnh biên giới Carbon (CBAM)', 'cbam-la-gi-lo-trinh-thuc-hien-co-che-dieu-chinh-bien-gioi-carbon-cbam', NULL, NULL, 'CBAM là gì? Lộ trình thực hiện Cơ chế điều chỉnh biên giới Carbon (CBAM)', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1020, 'vi', 'Trong giai đoạn chuyển tiếp từ 1/10/2023 đến 31/12/2025, các nhà nhập khẩu 6 nhóm hàng hóa CBAM chỉ phải báo cáo chất lượng phát thải khí nhà kính mà chưa cần trả phí hay thanh toán.', 'Tin chuyên ngành', 'EU hướng dẫn lộ trình triển khai cơ chế điều chỉnh biên giới Carbon (CBAM)', 'eu-huong-dan-lo-trinh-trien-khai-co-che-dieu-chinh-bien-gioi-carbon-cbam', NULL, NULL, 'EU hướng dẫn lộ trình triển khai cơ chế điều chỉnh biên giới Carbon (CBAM)', '') ON CONFLICT (entity_id, locale) DO NOTHING;
