INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1022, 'vi', 'Hà Tĩnh chuẩn bị sẵn sang cho lộ trình áp dụng mô hình BIM trong hoạt động đầu tư, xây dựng trên địa bàn.', 'Tin công ty', 'Áp dụng mô hình BIM trong hoạt động đầu tư xây dựng trên địa bàn Hà Tĩnh', 'ap-dung-mo-hinh-bim-trong-hoat-dong-dau-tu-xay-dung-tren-dia-ban-ha-tinh', NULL, NULL, 'Áp dụng mô hình BIM trong hoạt động đầu tư xây dựng trên địa bàn Hà Tĩnh', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1023, 'vi', 'Ngày 10/10/2023, Ban Lãnh đạo Công ty CIC đã trao quyết định bổ nhiệm Anh Đinh Huỳnh Thái giữ chức vụ Phó Giám đốc Chi nhánh TP Hồ Chí Minh kể từ ngày 10/10/2023.', 'Tin công ty', 'Bổ nhiệm Anh Đinh Huỳnh Thái giữ chức Phó Giám đốc Chi nhánh TP Hồ Chí Minh', 'bo-nhiem-anh-dinh-huynh-thai-giu-chuc-pho-giam-doc-chi-nhanh-tp-ho-chi-minh', NULL, NULL, 'Bổ nhiệm Anh Đinh Huỳnh Thái giữ chức Phó Giám đốc Chi nhánh TP Hồ Chí Minh', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1024, 'vi', 'Ngày 12/10/2023, Công ty CIC tham gia Đại hội Công đoàn Xây dựng Việt Nam (XDVN) lần thứ XIV, nhiệm kỳ 2023-2028 tại Trung tâm Hội nghị Quốc tế, Hà Nội.', 'Tin công ty', 'CIC tham gia Đại hội Công đoàn Xây dựng Việt Nam lần thứ XIV, nhiệm kỳ 2023-2028', 'khai-mac-dai-hoi-cong-doan-xay-dung-viet-nam-lan-thu-xiv-nhiem-ky-2023-2028', NULL, NULL, 'CIC tham gia đại hội Công đoàn Xây dựng Việt Nam lần thứ XIV, nhiệm kỳ 2023-2028', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1025, 'vi', 'Công ty CIC là một trong những đơn vị triển khai dịch vụ tư vấn kiểm kê khí nhà kính. Trong bài viết này, CIC giới thiệu top 3 phần mềm tính toán LCA- Đánh giá vòng đời sản phẩm chính xác và hiệu quả nhất hiện nay.', 'Tin chuyên ngành', 'Top 3 phần mềm tính toán LCA- Đánh giá vòng đời sản phẩm hiệu quả, chính xác', 'top-3-phan-mem-tinh-toan-lcadanh-gia-vong-doi-san-pham', NULL, NULL, 'Top 3 phần mềm tính toán LCA- Đánh giá vòng đời sản phẩm hiệu quả, chính xác', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1026, 'vi', 'Cage Carbon là phần mềm hỗ trợ kiểm kê khí nhà kính cho doanh nghiệp theo tiêu chuẩn ISO 14064 trong việc quản lý dữ liệu carbon, đưa các mục tiêu và xây dựng lộ trình cắt giảm phát thải ngắn hạn và dài hạn.', 'Tin chuyên ngành', 'CAGE CARBON- Phần mềm kiểm kê khí nhà kính ', 'cage-carbon-phan-mem-kiem-ke-khi-nha-kinh', NULL, NULL, 'CIC giới thiệu phần mềm kiểm kê khí nhà kính - CAGE CARBON', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1027, 'vi', 'Với hơn 40 năm kinh nghiệm và sự đổi mới trong lĩnh vực phần mềm kết cấu, Bocad đã chứng minh mình là một tên tuổi đáng tin cậy trong lĩnh vực kỹ thuật kết cấu. Bocad tự hào về khả năng thực hiện các công việc kỹ thuật kết cấu từ giai đoạn thiết kế, khái niệm đến thiết kế chi tiết.', 'Tin chuyên ngành', 'Bocad - Phần mềm hoàn hảo cho thiết kế kết cấu xây dựng', 'bocad---phan-mem-hoan-hao-cho-thiet-ke-ket-cau-xay-dung', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1028, 'vi', 'Nhân tháng Chuyển đổi số và theo Kế hoạch được giao của Đoàn Khối Cơ quan TW, Đoàn TN Bộ Xây dựng phối hợp với Công ty CIC tổ chức tập huấn trực tuyến về vai trò của BIM trong chuyển đổi số ngành Xây dựng vào chiều ngày 17/10/2023.', 'Tin công ty', 'CIC tập huấn đào tạo vai trò của BIM trong chuyển đổi số ngành xây dựng', 'cic-tap-huan-dao-tao-vai-tro-cua-bim-trong-chuyen-doi-so-nganh-xay-dung', NULL, NULL, 'CIC tập huấn đào tạo vai trò của BIM trong chuyển đổi số ngành xây dựng', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1029, 'vi', 'Phiên bản mới nhất của Allplan - Allplan 2024 đã chính thức ra mắt và sẵn sàng để tải xuống ngay hôm nay!', 'Tin chuyên ngành', 'ALLPLAN 2024 chính thức ra mắt', 'allplan-2024-chinh-thuc-ra-mat', NULL, NULL, 'ALLPLAN 2024 chính thức ra mắt', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1034, 'vi', 'Với phần mềm enjiCAD phiên bản 2024, một trong nhưng thay đổi rất hữu ích là thao tác Viewport nay đã trực quan hơn, dễ dàng và nhanh chóng hơn rất nhiều. Cùng Công ty CIC tìm hiểu những thay đổi này trong bài viết dưới đây.', 'Tin chuyên ngành', 'Phần mềm enjiCAD 2024: Thao tác cùng Viewport dễ dàng hơn bao giờ hết', 'phan-mem-enjicad-2024:-thao-tac-cung-viewport-de-dang-hon-bao-gio-het', NULL, NULL, 'Phần mềm enjiCAD 2024: Thao tác cùng Viewport dễ dàng hơn bao giờ hết', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1030, 'vi', 'Cách tiếp cận tích hợp giữa hai phần mềm địa kỹ thuật GeoStudio và PLAXIS trong phần tích ổn định mái dốc giúp kỹ sư làm việc hiệu quả hơn, rút ra thông tin tốt hơn và thực hiện các dự án tốt hơn.', 'Tin chuyên ngành', 'Phân tích ổn định mái dốc với GeoStudio và PLAXIS version 2023', 'phan-tich-on-dinh-mai-doc-voi-geostudio-va-plaxis-version-2023', NULL, NULL, 'Phân tích ổn định mái dốc với GeoStudio và PLAXIS version 2023', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1031, 'vi', 'Ủy Ban Chứng khoán Nhà nước (UBCKNN) ra mắt sổ tay phối hợp với Tổ chức Tài chính Quốc tế (IFC) tổ chức Lễ ra mắt Sổ tay hướng dẫn báo cáo phát thải khí nhà kính.', 'Tin chuyên ngành', ' Sổ tay hướng dẫn báo cáo phát thải khí nhà kính - Cẩm nang cho các doanh nghiệp', 'so-tay-huong-dan-bao-cao-phat-thai-khi-nha-kinh-cam-nang-cho-cac-doanh-nghiep', NULL, NULL, ' Sổ tay hướng dẫn báo cáo phát thải khí nhà kính - Cẩm nang cho các doanh nghiệp', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1033, 'vi', 'An Cường đã chính thức cho ra mắt trên website công cụ diễn họa các sản phẩm nội thất gỗ ứng dụng công nghệ thực tế ảo tăng cường. Đây là giải pháp công nghệ do CIC hiện đang là nhà phân phối tại Việt Nam.', 'Tin công ty', 'CIC chuyển giao Roomvo - Giải pháp diễn họa trang trí nội thất ứng dụng thực tế ảo tăng cường cho gỗ An Cường', 'cic-chuyen-giao-roomvo-giai-phap-dien-hoa-trang-tri-noi-that-ung-dung-thuc-te-ao-tang-cuong-cho-go-an-cuong', NULL, NULL, 'CIC chuyển giao Roomvo - Giải pháp diễn họa trang trí nội thất ứng dụng thực tế ảo tăng cường cho gỗ', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1032, 'vi', 'Công ty CIC và Hãng AIT Solutions phối hợp tổ chức khóa học phần mềm ETABS trên nền tảng trực tuyến trong 02 ngày, từ 21 đến ngày 22/11/2023. Đặc biệt, khi khách hàng đăng ký theo nhóm từ 03 học viên trở lên sẽ được giảm 30%. ', 'Tin công ty', 'Ra mắt khoá học ETABS nâng cao được Uỷ quyền và cấp phép chính hãng tại Việt Nam', 'ra-mat-khoa-hoc-etabs-nang-cao-duoc-uy-quyen-va-cap-phep-chinh-hang-tai-viet-nam', NULL, NULL, 'Ra mắt khoá học ETABS nâng cao được Uỷ quyền và cấp phép chính hãng tại Việt Nam', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1037, 'vi', 'Ngày 8/11/2023, Công ty Cổ phần Công nghệ và Tư vấn CIC tham gia Diễn đàn phát triển bền vững đô thị Việt Nam 2023 với chủ đề Kết hợp BIM và GIS trong chuyển đổi số cho phát triển đô thị thông minh.', 'Tin công ty', 'CIC tham luận chủ đề BIM + GIS = CIM trong phát triển đô thị thông minh tại Diễn đàn phát triển bền vững đô thị Việt Nam 2023 ', 'cic-tham-luan-chu-de-bimgiscim-trong-phat-trien-do-thi-thong-minh', NULL, NULL, 'CIC tham luận chủ đề BIM + GIS = CIM trong phát triển đô thị thông minh tại Diễn đàn phát triển bền ', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1036, 'vi', 'Thiết bị camera nhiệt cố định AI giám sát trạm biến áp là giải pháp giám sát nhiệt 24/7 đảm bảo nhiệt độ luôn được kiểm soát một cách chính xác và đáng tin cậy tại các điểm quan trọng của trạm biến áp.', 'Tin chuyên ngành', 'Giải pháp giám sát nhiệt thông minh 24/7 cho trạm biến áp', 'giai-phap-giam-sat-nhiet-247-cho-tram-bien-ap', NULL, NULL, 'Giải pháp giám sát nhiệt thông minh 24/7 cho trạm biến áp', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1035, 'vi', 'Phiên bản phần mềm Leapfrog 2023.2 tiếp tục nâng cao khả năng lập mô hình, khả năng tương tác và trực quan hóa của Leapfrog với những cải tiến và một số tính năng mới thú vị.', 'Tin chuyên ngành', 'Phiên bản cập nhật mới nhất Leapfrog Geo 2023.2 có gì mới?', 'phien-ban-cap-nhat-moi-nhat-leapfrog-geo-20232-co-gi-moi', NULL, NULL, 'Phiên bản cập nhật mới nhất Leapfrog Geo 2023.2 có gì mới?', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1038, 'vi', 'Trong bài viết dưới đây, Công ty CIC hướng dẫn các bạn thao tác với các lệnh xác định vị trí tọa độ trong phần mềm enjiCAD phiên bản mới nhất hiện nay.', 'Tin chuyên ngành', 'Phần mềm enjiCAD 2024: Giới thiệu một số tính năng thao tác với tọa độ điểm', 'phan-mem-enjicad-2024:-gioi-thieu-mot-so-tinh-nang-thao-tac-voi-toa-do-diem', NULL, NULL, 'Phần mềm enjiCAD 2024: Giới thiệu một số tính năng thao tác với tọa độ điểm', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1039, 'vi', 'Đề xuất Danh mục các lĩnh vực, cơ sở phát thải khí nhà kính phải thực hiện cập thêm 981 cơ sở, nâng tổng số cơ sở phải thực hiện hiện nay là 2.893 cơ sở, tập trung ở 5 ngành chính.', 'Tin công ty', 'Đề xuất tăng 981 cơ sở phải thực hiện kiểm kê khí nhà kính', 'de-xuat-tang-981-co-so-phai-thuc-hien-kiem-ke-khi-nha-kinh', NULL, NULL, 'Đề xuất tăng 981 cơ sở phải thực hiện kiểm kê khí nhà kính', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1040, 'vi', 'Biomass hay còn được gọi là sinh khối, là nhiên liệu quan trọng để doanh nghiệp hạn chế lượng phát thải ra môi trường, từ đó giảm hiệu ứng nhà kính và giảm các tác nhân đến môi trường. Đây là một trong những giải pháp quan trọng để chúng ta tiến tới đạt phát thải ròng bằng o (net zero).', 'Tin chuyên ngành', 'Biomass – Nhiên liệu cho phát triển xanh ', 'biomass-–-nhien-lieu-cho-phat-trien-xanh', NULL, NULL, 'Biomass – Nhiên liệu cho phát triển xanh', '') ON CONFLICT (entity_id, locale) DO NOTHING;
