INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1081, 'vi', 'Công ty CIC xin giới thiệu bài hướng dẫn thao tác gọi lệnh đã dùng nhanh trên phần mềm CAD nói chung cũng như enjiCAD nói riêng để các bạn có thể tham khảo.', 'Tin chuyên ngành', 'Cách để lặp lại lệnh vừa sử dụng và tùy chỉnh cài đặt bằng chuột phải nhanh chóng', 'cach-de-lap-lai-lenh-vua-su-dung-va-tuy-chinh-cai-dat-bang-chuot-phai-nhanh-chong', NULL, NULL, 'Cách để lặp lại lệnh vừa sử dụng và tùy chỉnh cài đặt bằng chuột phải nhanh chóng', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1082, 'vi', 'Sáng nay, ngày 15/01/2024, Công ty Kiểm định Kỹ thuật An toàn và Tư vấn xây dựng (Incosaf) triển khai khóa huấn luyện An toàn, vệ sinh lao động cho toàn bộ CBCNV Công ty Cổ phần Công nghệ và Tư vấn CIC.', 'Tin công ty', 'CIC tham gia khóa huấn luyện an toàn vệ sinh lao động 2024', 'cic-tham-gia-khoa-huan-luyen-an-toan-ve-sinh-lao-dong-2024', NULL, NULL, 'CIC tham gia khóa huấn luyện an toàn vệ sinh lao động 2024', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1083, 'vi', 'Carbon Sim giúp người tham gia có thể mô phỏng quá trình mua bán, đấu giá trên thị trường tín chỉ carbon trong tương lai một cách thực tế, chân thực nhất.', 'Tin chuyên ngành', 'Carbon Sim – Công cụ mô phỏng giao dịch trên thị trường carbon cho doanh nghiệp', 'carbon-sim-–-cong-cu-mo-phong-giao-dich-tren-thi-truong-carbon-cho-doanh-nghiep', NULL, NULL, 'Carbon Sim – Công cụ mô phỏng giao dịch trên thị trường carbon cho doanh nghiệp', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1089, 'vi', 'Trong bài viết dưới đây, CIC đưa ra một số tips khi sử dụng Revision cloud trong phần mềm enjiCAD. Mời các bạn theo dõi.', 'Tin chuyên ngành', 'Một số Tip sử dụng khoanh vùng đám mây bằng Revision cloud', 'mot-so-tip-su-dung-khoanh-vung-dam-may-bang-revision-cloud', NULL, NULL, 'Một số Tip sử dụng khoanh vùng đám mây bằng Revision cloud', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1088, 'vi', 'Ngày 19/1/2024, Công ty cổ phần Công nghệ và Tư vấn CIC đã tổ chức Lễ Tổng kết hoạt động sản xuất kinh doanh năm 2023 và Kế hoạch triển khai năm 2024. Kết quả kinh doanh của năm 2023 vượt chỉ tiêu đề ra đánh dấu cột mốc quan trọng, thể hiện sự phát triển và chuyển mình CIC trong lĩnh vực công nghệ.', 'Tin công ty', 'CIC tổng kết hoạt động sản xuất kinh doanh năm 2023 và Kế hoạch triển khai năm 2024', 'cic-tong-ket-hoat-dong-san-xuat-kinh-doanh-nam-2023-va-ke-hoach-trien-khai-nam-2024', NULL, NULL, 'CIC tổng kết hoạt động sản xuất kinh doanh năm 2023 và Kế hoạch triển khai năm 2024', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1084, 'vi', 'Tín chỉ carbon là chứng nhận có thể giao dịch thương mại và thể hiện quyền phát thải một lượng khí CO2 hoặc một lượng khí nhà kính khác quy đổi sang CO2 tương đương. Dưới đây là 4 yếu tố quan trọng tác động đến việc hình thành dự án tín chỉ carbon theo tiêu chuẩn quốc tế.', 'Tin chuyên ngành', 'Các tiêu chuẩn quốc tế quan trọng để hình thành dự án tín chỉ carbon', 'cac-tieu-chuan-quoc-te-quan-trong-de-hinh-thanh-du-an-tin-chi-carbon', NULL, NULL, '4 yếu tố quan trọng đối với một dự án tín chỉ carbon', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1085, 'vi', 'ROCK MAPPER là phần mềm ghi lại hiện trạng gương hầm nhanh chóng, chính xác & hiệu quả trong dự án đào hầm và khai thác mỏ.', 'Tin chuyên ngành', 'ROCK MAPPER – Giải pháp ghi lại hiện trạng gương hầm nhanh chóng, chính xác & hiệu quả trong dự án đào hầm và khai thác mỏ', 'rock-mapper-–-giai-phap-ghi-lai-hien-trang-guong-ham-nhanh-chong-chinh-xac-amp;-hieu-qua-trong-du-an-dao-ham-va-khai-thac-mo', NULL, NULL, 'ROCK MAPER – Giải pháp ghi lại hiện trạng gương hầm nhanh chóng, chính xác & hiệu quả trong dự án đà', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1086, 'vi', 'Sử dụng IDEA StatiCa, Dallas Lee - Kỹ sư chính của Robert Bird Group và nhóm của ông đã đạt được độ linh hoạt chính xác cần thiết để lập mô hình các nút giàn ba chiều một cách chính xác, an toàn và hiệu quả cho công trình Skydeck ở Úc.', 'Tin chuyên ngành', 'IDEA StatiCa là giải pháp lý tưởng cho dự án The Queens Wharf Skydeck - Brisbane ở Úc', 'idea-statica-la-giai-phap-ly-tuong-cho-du-an-the-queens-wharf-skydeck-brisbane-o-uc', NULL, NULL, 'IDEA StatiCa là giải pháp lý tưởng cho dự án The Queens Wharf Skydeck - Brisbane ở Úc', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1087, 'vi', 'Trong bài viết này, CIC sẽ hướng dẫn các bạn làm hộp giả dày bằng phần mềm PYTHA thông qua chức năng Sandwich.', 'Tin chuyên ngành', 'Phần mềm PYTHA: Tính năng Sandwich và ứng dụng làm hộp giả dày', 'huong-dan-lam-hop-gia-day-trong-pytha', NULL, NULL, 'Phần mềm PYTHA: Tính năng Sandwich và ứng dụng làm hộp giả dày', '') ON CONFLICT (entity_id, locale) DO NOTHING;
