INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1091, 'vi', 'Opera Job Management là phần mềm bóc tách vật tư, sản xuất nhôm kính chuyên dụng cho các nhà thầu nhôm kính. Trong bài viết này, CIC hướng dẫn các bạn xem trước báo cáo trước khi in với tính năng Document.', 'Tin chuyên ngành', 'Xuất bản thảo hợp đồng, báo cáo mẫu với tính năng Document trong Opera Job Management', 'xuat-ban-thao-hop-dong-bao-cao-mau-voi-tinh-nang-document-trong-opera-job-management', NULL, NULL, 'Xuất bản thảo hợp đồng, báo cáo mẫu với tính năng Document trong Opera Job Management', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1092, 'vi', 'Opera Job Management là một trong các phần mềm nhôm kính cao cấp hỗ trợ công tác bóc tách vật tư, báo giá và hỗ trợ sản xuất được các đơn vị thầu nhôm kính tin tưởng sử dụng với những ưu điểm vượt trội.', 'Tin chuyên ngành', 'Opera Job Management: 5 điểm khác biệt tạo nên thành công cho các nhà thầu nhôm kính', 'opera-job-management:-5-diem-khac-biet-tao-nen-thanh-cong-cho-cac-nha-thau-nhom-kinh', NULL, NULL, 'Opera Job Management: 5 điểm khác biệt tạo nên thành công cho các nhà thầu nhôm kính', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1093, 'vi', 'Khí hóa than dưới lòng đất (UCG) là một quá trình khí hóa được sử dụng để sản xuất khí từ than tại chỗ bằng cách bơm không khí hoặc oxy vào các vỉa than chưa được khai thác và trích khí sản phẩm qua các giếng trên bề mặt. Khí tổng hợp thu được có thể được sử dụng để sản xuất điện, cũng như hóa chất, nhiên liệu lỏng, hydro .v.v', 'Tin chuyên ngành', 'Khí hóa than ngầm: Tiềm năng lớn nhưng còn nhiều thách thức', 'khi-hoa-than-ngam:-tiem-nang-lon-nhung-con-nhieu-thach-thuc', NULL, NULL, 'Khí hóa than ngầm: Tiềm năng lớn nhưng còn nhiều thách thức', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1094, 'vi', 'Bộ Xây dựng dự kiến sẽ kiểm kê khí nhà kính 50 doanh nghiệp sản xuất xi măng để tham gia thị trường giao dịch tín chỉ carbon nhằm thực hiện xanh hóa nền kinh tế, hướng đến phát thải ròng bằng “0” (net zero).', 'Tin chuyên ngành', '50 doanh nghiệp sản xuất xi măng phải kiểm kê phát thải khí nhà kính', '50-doanh-nghiep-san-xuat-xi-mang-phai-kiem-ke-phat-thai-khi-nha-kinh', NULL, NULL, '50 doanh nghiệp sản xuất xi măng phải kiểm kê phát thải khí nhà kính', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1095, 'vi', 'Trong kỷ nguyên số hóa ngành xây dựng, việc chuyển đổi từ các thiết bị đo có dây truyền thống sang hệ thống kết nối Bluetooth đang tái định nghĩa hiệu suất và độ chính xác trong công tác kiểm tra tính đồng nhất của cọc (Pile Integrity Test - PIT).', 'Tin chuyên ngành', 'CÔNG NGHỆ KHÔNG DÂY: BƯỚC NGOẶT MỚI TRONG THỬ ĐỘNG BIẾN DẠNG NHỎ (PIT)', 'cong-nghe-khong-day:-buoc-ngoat-moi-trong-thu-dong-bien-dang-nho-pit', NULL, NULL, 'PET Bluetooth  (Piletest) ', '') ON CONFLICT (entity_id, locale) DO NOTHING;
