INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1096, 'vi', 'SimaPro có cơ sở dữ liệu toàn diện về dữ liệu kiểm kê vòng đời (LCI) chứa dữ liệu về hàng nghìn vật liệu và quy trình, giúp thu thập và phân tích dữ liệu trong suốt vòng đời của sản phẩm dễ dàng hơn.', 'Tin chuyên ngành', 'SimaPro - Phần mềm đánh giá vòng đời sản phẩm (Life Cycle Accessment- LCA)', 'simapro-phan-mem-danh-gia-vong-doi-san-pham-life-cycle-accessmentlca', NULL, NULL, 'SimaPro - Phần mềm đánh giá vòng đời sản phẩm (Life Cycle Accessment- LCA)', '') ON CONFLICT (entity_id, locale) DO NOTHING;
