INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1099, 'vi', 'Theo Architectural Digest, xu hướng nội thất của năm 2024 là sự lên ngôi của những gam màu mới lạ như cam đào, xanh ngọc. Trong đó, chủ nghĩa lãng mạn và vẻ đẹp cổ điển cũng quay trở lại.', 'Tin chuyên ngành', 'Xu hướng nội thất lên ngôi năm 2024', 'xu-huong-noi-that-len-ngoi-nam-2024', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
