INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1102, 'vi', 'Làn sóng chuyển đổi số đang diễn ra mạnh mẽ trên tất cả các phương diện là lý do để các doanh nghiệp Việt cần tham gia ngay cuộc chơi này.', 'Tin công ty', 'Cập nhật các xu hướng chuyển đổi số năm 2024 và những lợi ích không thể bỏ qua', 'cap-nhat-cac-xu-huong-chuyen-doi-so-nam-2024-va-nhung-loi-ich-khong-the-bo-qua', NULL, NULL, 'Cập nhật các xu hướng chuyển đổi số năm 2024 và những lợi ích không thể bỏ qua', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1103, 'vi', 'Các chuyên gia đã có những trao đổi, góc nhìn về các chính sách và lộ trình hình thành thị trường tín chỉ carbon tại Việt Nam ngay sau thông tin Việt Nam bán thành công 10,3 triệu tín chỉ carbon rừng thông qua Ngân hàng Thế giới (WB) với trị giá 51,5 triệu USD.', 'Tin chuyên ngành', 'Thị trường tín chỉ carbon- Những chính sách và lộ trình hình thành', 'thi-truong-tin-chi-carbonnhung-chinh-sach-va-lo-trinh-hinh-thanh', NULL, NULL, 'Thị trường tín chỉ carbon- Những chính sách và lộ trình hình thành', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1239, 'vi', 'Ngày 06/09/2024 tại Hà Nội, Công ty Cổ phần Công nghệ và Tư vấn CIC cùng với hơn 60 đại biểu đến từ nhiều doanh nghiệp, viện nghiên cứu, trường đại học, cơ quan nhà nước và các tổ chức hỗ trợ doanh nghiệp đã tham dự buổi Hội thảo tham vấn Dự thảo sổ tay giới thiệu quy định pháp lý về ESG năm 2024 và báo cáo đánh giá mức độ thực hành ESG trong doanh nghiệp.', 'Tin công ty', 'CIC tham gia Hội thảo tham vấn dự thảo Sổ tay giới thiệu quy định pháp lý về ESG năm 2024 và Báo cáo đánh giá mức độ thực hành ESG trong doanh nghiệp', 'cic-tham-gia-hoi-thao-tham-van-du-thao-so-tay-gioi-thieu-quy-dinh-phap-ly-ve-esg-nam-2024-va-bao-cao-danh-gia-muc-do-thuc-hanh-esg-trong-doanh-nghiep', NULL, NULL, 'CIC tham gia Hội thảo tham vấn dự thảo Sổ tay giới thiệu quy định pháp lý về ESG năm 2024 và Báo cá', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1104, 'vi', 'Smart Parametric là bộ công cụ tạo hình thông minh & mạnh mẽ trong phần mềm PYTHA, giúp người dùng giảm các thao tác trong quá trình thiết kế nội thất.', 'Tin chuyên ngành', 'Hướng dẫn tạo hình thông minh bằng phần mềm PYTHA', 'huong-dan-tao-hinh-thong-minh-bang-phan-mem-pytha', NULL, NULL, 'Hướng dẫn tạo hình thông minh bằng phần mềm PYTHA', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1105, 'vi', 'Trong 2 ngày (từ 29/2 đến ngày 1/3/2024), Công ty cổ phần Công nghệ và Tư vấn CIC tham gia Chương trình đào tạo dành cho đối tác của hãng Ansys tại Kuala Lumpur (Malaysia), bao gồm các quốc gia thuộc khối ASEAN và ANZ.', 'Tin công ty', 'CIC tham gia Chương trình đào tạo dành cho các đối tác của hãng Ansys tại Malaysia', 'cic-tham-gia-chuong-trinh-dao-tao-danh-cho-cac-doi-tac-cua-hang-ansys-tại-malaysia', NULL, NULL, 'CIC tham gia Chương trình đào tạo dành cho các đối tác của hãng Ansys tại Malaysia', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1106, 'vi', 'Delta Zero khi ứng dụng có thể giúp doanh nghiệp sản xuất xi măng tiết kiệm từ 5-7% chi phí nhiên liệu và giảm hơn 10% tổng lượng phát thải carbon.', 'Tin chuyên ngành', 'DELTA ZERO – Giải pháp tiết kiệm nhiên liệu và giảm phát thải carbon', 'delta-zero-–-giai-phap-tiet-kiem-nhien-lieu-va-giam-phat-thai-carbon', NULL, NULL, 'DELTA ZERO – Giải pháp tiết kiệm nhiên liệu và giảm phát thải carbon', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1107, 'vi', 'Với tính năng Inventory Management, Opera Job Management sẽ giúp các doanh nghiệp sản xuất nhôm kính, nhà thầu nhôm kính quản lý kho vật tư dễ dàng, nhanh chóng và hiệu quả hơn.', 'Tin chuyên ngành', 'Quản lý kho vật tư dễ dàng, nhanh chóng bằng Opera Job Management', 'quan-ly-kho-vat-tu-de-dang-nhanh-chong-bang-opera-job-management', NULL, NULL, 'Quản lý kho vật tư dễ dàng, nhanh chóng bằng Opera Job Management', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1108, 'vi', 'Một trong những vấn đề chính của các dự án xây dựng là sự lãng phí về vật liệu và thời gian liên quan tới việc trao đổi công việc giữa các bộ phận, đặc biệt là khi có sự thay đổi trong dự án. Làm thế để cải thiện điều này? Hãy xem bài viết dưới đây của chúng tôi:', 'Tin chuyên ngành', 'Quản lý các thay đổi khi sử dụng IDEA StatiCa Connection', 'quan-ly-cac-thay-doi-khi-su-dung-idea-statica-connection', NULL, NULL, 'Quản lý các thay đổi khi sử dụng IDEA StatiCa Connection', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1109, 'vi', 'Autodesk BIM Collaborate và BIM Collaborate Pro là hai giải pháp về quản lý dữ liệu thiết kế trên nền tảng Autodesk Construction Cloud.', 'Tin chuyên ngành', 'Autodesk BIM Collaborate và BIM Collaborate Pro: Giải pháp tăng cường khả năng phối hợp trên nền tảng Autodesk Construction Cloud', 'autodesk-bim-collaborate-va-bim-collaborate-pro:-giai-phap-tang-cuong-kha-nang-phoi-hop-tren-nen-tang-autodesk-construction-cloud', NULL, NULL, 'Autodesk BIM Collaborate và BIM Collaborate Pro: Giải pháp tăng cường khả năng phối hợp trên nền tản', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1111, 'vi', 'Ngày 8/3 vừa qua, Công ty Cổ phần Công nghệ và Tư vấn CIC đã tổ chức bữa tiếc ấm cúng để chúc mừng chị em nhân kỷ niệm Ngày Quốc tế phụ nữ.', 'Tin công ty', 'CIC Tôn Vinh Phụ Nữ trong Ngày Quốc Tế Phụ Nữ 8/3', 'cic-ton-vinh-phu-nu-trong-ngay-quoc-te-phu-nu-83', NULL, NULL, 'CIC Tôn Vinh Phụ Nữ trong Ngày Quốc Tế Phụ Nữ 8/3', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1112, 'vi', 'Bài viết này dành cho các design trong quá trình thiết kế bằng các phần mềm CAD, trong đó có enjiCAD cách khắc phục lỗi không thể double-click lên đối tượng để edit hay thao tác trên đối tượng.', 'Tin chuyên ngành', 'Cách khắc phục lỗi không thể Double-click lên các đối tượng block hay text trên phần mềm enjiCAD', 'cach-khac-phuc-loi-khong-the-double-click-len-cac-doi-tuong-block-hay-text-tren-phan-mem-enjicad', NULL, NULL, 'Cách khắc phục lỗi không thể Double-click lên các đối tượng block hay text trên phần mềm enjiCAD', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1113, 'vi', 'Giờ Trái Đất 2024 năm nay diễn ra vào ngày 23/3/2024, lần đầu tiên chúng ta tham gia với thông điệp Giảm dấu chân carbon – Hướng tới net zero trong bối cảnh khí nhà kính đang làm trái đất nóng lên.', 'Tin công ty', 'Hưởng ứng Giờ Trái Đất 2024 – Hướng tới Net zero 2050', 'huong-ung-gio-trai-dat-2024-–-huong-toi-net-zero-2050', NULL, NULL, 'Hưởng ứng Giờ Trái Đất 2024 – Hướng tới Net zero 2050', '') ON CONFLICT (entity_id, locale) DO NOTHING;
