INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1115, 'vi', 'Khi thiết kế với enjiCAD, đôi khi ta gặp trường hợp muốn thay đổi độ dày nét vẽ mà chưa biết cách? Bài viết này đội ngũ kỹ thuật của Công ty CIC sẽ hướng dẫn bạn phương pháp thay đổi độ dày nét trên phần mềm enjiCAD nhanh chóng và dễ dàng.', 'Tin chuyên ngành', 'Phương pháp thay đổi độ dày nét trong enjiCAD', 'phuong-phap-thay-doi-do-day-net-trong-enjicad', NULL, NULL, 'Phương pháp thay đổi độ dày nét trong enjiCAD', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1116, 'vi', 'Trước những thách thức và cơ hội toàn cầu cho ngành xây dựng, ông Yves Padrines, Giám đốc điều hành của Tập đoàn Nemetschek đã có bài viết phân tích về công cụ kỹ thuật số trong bối cảnh chuyển đổi số ngành xây dựng.', 'Tin chuyên ngành', 'Công cụ chuyển đổi số: OpenBIM, Digital Twins, AI sẽ làm thay đổi tương lai ngành xây dựng', 'cong-cu-chuyen-doi-so:-openbim-digital-twins-ai-se-lam-thay-doi-tuong-lai-nganh-xay-dung', NULL, NULL, 'Công cụ chuyển đổi số: OpenBIM, Digital Twins, AI sẽ làm thay đổi tương lai ngành xây dựng', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1117, 'vi', 'Hiện nay, Công ty Cổ phần Công nghệ và Tư vấn CIC có đội ngũ chuyên gia tư vấn có nhiều năm kinh nghiệm trong lĩnh vực kiểm kê khí nhà kính, đánh giá vòng đời sản phẩm, tư vấn chứng chỉ xanh và các chứng nhận môi trường, phát triển bền vững.', 'Tin chuyên ngành', 'Chuyên gia kiểm kê khí nhà kính bạn cần biết', 'chuyen-gia-kiem-ke-khi-nha-kinh-ban-can-biet', NULL, NULL, 'Chuyên gia kiểm kê khí nhà kính bạn cần biết', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1118, 'vi', 'Hội thảo về Thiết bị giám sát, quan trắc hồ, đập thủy điện được diễn ra vào sáng ngày 19/3/2024 với sự tham gia của Công ty CP Công nghệ và Tư vấn CIC và Công ty Thủy điện Quảng Trị.', 'Tin công ty', 'CIC và Thủy Điện Quảng Trị tổ chức hội thảo về Thiết bị giám sát, quan trắc hồ, đập thủy điện', 'cic-va-thuy-dien-quang-tri-to-chuc-hoi-thao-ve-thiet-bi-giam-sat-quan-trac-ho-dap-thuy-dien', NULL, NULL, 'CIC và Thủy Điện Quảng Trị tổ chức hội thảo về Thiết bị giám sát, quan trắc hồ, đập thủy điện', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1119, 'vi', 'Mới đây, Công ty CP Công nghệ và Tư vấn CIC đã hoàn thành bàn giao, nghiệm thu cho Viện Khoa học Công nghệ Xây dựng (IBST) các phần mềm hỗ trợ mô phỏng đám cháy PyroSim và Pathfinder của Thunderhead Engineering Consultants, Inc.', 'Tin công ty', 'CIC cung cấp phần mềm mô phỏng cháy PyroSim, Phần mềm mô phỏng hoạt động sơ tán Pathfinder cho IBST', 'cic-cung-cap-phan-mem-mo-phong-chay-pyrosim-phan-mem-mo-phong-hoat-dong-so-tan-pathfinder-cho-ibst', NULL, NULL, 'CIC cung cấp phần mềm mô phỏng cháy PyroSim, Phần mềm mô phỏng hoạt động sơ tán Pathfinder cho IBST', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1121, 'vi', 'Ngày 11/4/2024, Công ty cổ phần Công nghệ và Tư vấn CIC và Hãng Hexagon phối hợp tổ chức hội thảo trực tuyến với chủ đề CADWorx – Giải pháp hoàn thiện cho thiết kế nhà máy hiệu quả.', 'Tin công ty', 'Đừng bỏ lỡ sự kiện tháng 4: Webinar CADWorx - Giải pháp hoàn thiện cho thiết kế nhà máy hiệu quả', 'dung-bo-lo-su-kien-thang-4:-webinar-cadworx-giai-phap-hoan-thien-cho-thiet-ke-nha-may-hieu-qua', NULL, NULL, 'Đừng bỏ lỡ sự kiện tháng 4: Webinar CADWorx - Giải pháp hoàn thiện cho thiết kế nhà máy hiệu quả', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1120, 'vi', 'Công ty cổ phần Công nghệ và Tư vấn CIC vừa hoàn thành bàn giao và hướng dẫn hai bộ thiết bị giám sát chấn động của hãng GeoSIG cho Nhà máy Thủy điện Thượng Kon Tum.', 'Tin công ty', 'CIC bàn giao Hệ thống Giám sát động đất (GeoSIG) cho Nhà máy Thủy điện Thượng Kon Tum', 'cic-ban-giao-he-thong-giam-sat-dong-dat-geosig-cho-nha-may-thuy-dien-thuong-kon-tum', NULL, NULL, 'CIC bàn giao Hệ thống Giám sát động đất (GeoSIG) cho Nhà máy Thủy điện Thượng Kon Tum', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1128, 'vi', 'Biến đổi khí hậu toàn cầu, đặt ra thách thức lớn đối với an ninh năng lượng của mỗi quốc gia. Vì thế, năng lượng sạch hay còn gọi là năng lượng tái tạo được ưu tiên hàng đầu. Cùng CIC tìm hiểu nội dung này trong bài viết dưới đây.', 'Tin chuyên ngành', 'Năng lượng tái tạo là gì? Các dạng năng lượng tái tạo phổ biến hiện nay', 'nang-luong-tai-tao-la-gi-cac-dang-nang-luong-tai-tao-pho-bien-hien-nay', NULL, NULL, 'Năng lượng tái tạo là gì? Các dạng năng lượng tái tạo phổ biến hiện nay', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1122, 'vi', 'Seequent khuyến khích người dùng nên lên kế hoạch chuyển đổi từ PLAXIS LE và PLAXIS Designer sang phần mềm GeoStudio và Leapfrog. Thông tin chi tiết sẽ có trong bài viết dưới đây.', 'Tin chuyên ngành', 'Chuyển đổi từ PLAXIS LE và PLAXIS Designer sang phần mềm GeoStudio và Leapfrog', 'chuyen-doi-tu-plaxis-le-va-plaxis-designer-sang-phan-mem-geostudio-va-leapfrog', NULL, NULL, 'Chuyển đổi từ PLAXIS LE và PLAXIS Designer sang phần mềm GeoStudio và Leapfrog', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1123, 'vi', 'Ngày 20/3/2024, Công ty cổ phần Công nghệ và Tư vấn CIC và Công ty Điện Lực Sóc Trăng tổ chức thành công hội thảo về trao đổi giải pháp công nghệ ứng dụng trong ngành điện lực, trong đó có áp dụng phần mềm enjiCAD cho ngành điện.', 'Tin công ty', 'CIC và Điện Lực Sóc Trăng tổ chức thành công hội thảo về trao đổi về giải pháp công nghệ ứng dụng trong ngành Điện', 'cic-va-dien-luc-soc-trang-to-chuc-thanh-cong-hoi-thao-ve-trao-doi-ve-giai-phap-cong-nghe-ung-dung-trong-nganh-dien', NULL, NULL, 'CIC tổ chức thành công hội thảo về trao đổi về giải pháp công nghệ ứng dụng trong ngành điện', '') ON CONFLICT (entity_id, locale) DO NOTHING;
