INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1663, 'vi', 'CIC tiếp tục bàn giao robot lặn điều khiển từ xa FIFISH V6 Expert của QYSEA cho khách hàng tại Việt Nam, khẳng định năng lực cung cấp giải pháp công nghệ dưới nước hiện đại. Thiết bị hỗ trợ ghi hình 4K, di chuyển linh hoạt 6-DOF và có thể ứng dụng trong khảo sát công trình, quan trắc môi trường, nghiên cứu khoa học, cứu hộ và khám phá dưới nước.', 'Tin công ty', 'CIC Tiếp Tục Bàn Giao Robot Lặn FIFISH V6 Expert,  Mở Rộng Ứng Dụng Công Nghệ ROV Tại Việt Nam', 'cic-tiep-tuc-ban-giao-robot-lan-fifish-v6-expertmo-rong-ung-dung-cong-nghe-rov-tai-viet-nam', NULL, NULL, 'CIC bàn giao robot lặn FIFISH V6 Expert tại Việt Nam', '') ON CONFLICT (entity_id, locale) DO NOTHING;
