INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1145, 'vi', 'Mới đây, Hãng Radiodetection vừa ra mắt sản phẩm RD8200SG – thiết bị xác định vị trí chính xác, tìm và lập bản đồ tiện ích ngầm chỉ trong một thao tác. Thiết bị này được đánh giá sẽ tạo ra bước đột phá trong việc xác định vị trí và lập bản đồ cho các tiện ích ngầm.', 'Tin chuyên ngành', 'Radiodetection ra mắt giải pháp đột phá mới trong việc xác định vị trí và lập bản đồ cho các tiện ích ngầm', 'radiodetection-ra-mat-giai-phap-dot-pha-moi-trong-viec-xac-dinh-vi-tri-va-lap-ban-do-cho-cac-tien-ich-ngam', NULL, NULL, 'Radiodetection ra mắt giải pháp đột phá mới trong việc xác định vị trí và lập bản đồ cho các tiện íc', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1146, 'vi', 'CSI phát hành phiên bản mới SAP2000 v25.2.0 & CSiBridge v25.2.0 một bản cập nhật cho v25.1.0 trước đó. Hãng này cũng khuyến nghị người dùng nâng cấp lên version mới nhất này cho tính ổn định và các cải tiến của phần mềm.', 'Tin chuyên ngành', 'CSI ra mắt phiên bản nâng cấp SAP2000 v25.2.0, CSiBridge v25.2.0', 'csi-ra-mat-phien-ban-nang-cap-sap2000-v2520-csibridge-v2520', NULL, NULL, 'CSI ra mắt phiên bản nâng cấp SAP2000 v25.2.0, CSiBridge v25.2.0', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1147, 'vi', 'Hãng phần mềm Foxit vừa ra mắt bản Foxit PDF Editor Suite V2024.1 - cập nhật nhiều tính nâng mới nhất của Foxit hiện có trên cả nền tảng Windows và Mac.', 'Tin chuyên ngành', 'Foxit PDF Editor Suite V2024.1 – Phiên bản nâng cấp với nhiều tính năng mới nhất', 'foxit-pdf-editor-suite-v20241-–-phien-ban-nang-cap-voi-nhieu-tinh-nang-moi-nhat', NULL, NULL, 'Foxit PDF Editor Suite V2024.1 – Phiên bản nâng cấp với nhiều tính năng mới nhất', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1148, 'vi', 'Foxit software company has just released Foxit PDF Editor Suite V2024.1 - updated with many of Foxit''s latest enhancements available on both Windows and Mac platforms.', 'Tin chuyên ngành', 'Foxit PDF Editor Suite V2024.1 – Upgraded version with many of the latest features', 'foxit-pdf-editor-suite-v20241-–-upgraded-version-with-many-of-the-latest-features', NULL, NULL, 'Foxit PDF Editor Suite V2024.1 – Upgraded version with many of the latest features', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1149, 'vi', 'Hạn ngạch phát thải khí nhà kính là lượng khí nhà kính của quốc gia, tổ chức, cá nhân được phép phát thải trong một khoảng thời gian xác định, được tính theo tấn khí carbon dioxide (CO2) hoặc tấn khí carbon dioxide (CO2) tương đương. Bộ Tài nguyên và Môi trường đề xuất bổ sung quy định về lộ trình phân bổ hạn ngạch phát thải khí nhà kính. Cập nhật năm 2026: Việt Nam đã phê duyệt tổng hạn ngạch phát thải khí nhà kính thí điểm cho năm 2025–2026, áp dụng trước hết với các cơ sở thuộc lĩnh vực nhiệt điện, sắt thép và xi măng.', 'Tin chuyên ngành', 'Hạn ngạch phát thải khí nhà kính là gì? Đề xuất lộ trình phân bổ hạn ngạch phát thải khí nhà kính', 'han-ngach-phat-thai-khi-nha-kinh-la-gi-de-xuat-lo-trinh-phan-bo-han-ngach-phat-thai-khi-nha-kinh', NULL, NULL, 'Hạn ngạch phát thải khí nhà kính là gì? Cập nhật quy định phân bổ hạn ngạch 2025–2026', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1150, 'vi', 'Chương trình đào tạo phần mềm thiết kế và sản xuất nội thất PYTHA CAD 3D sẽ bắt đầu từ tối thứ 5, ngày 25/4/2024 trên nền tảng online do Công ty CP Công nghệ và Tư vấn CIC thực hiện.', 'Tin công ty', 'CIC ra mắt chương trình đào tạo phần mềm thiết kế và sản xuất nội thất PYTHA CAD 3D', 'cic-ra-mat-chuong-trinh-dao-tao-phan-mem-thiet-ke-va-san-xuat-noi-that-pytha-cad-3d', NULL, NULL, 'CIC ra mắt chương trình đào tạo phần mềm thiết kế và sản xuất nội thất PYTHA CAD 3D', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1151, 'vi', 'Phần mềm thiết kế và sản xuất nội thất Pytha 3D CAD là giải pháp phần mềm giúp các nhà thiết tối ưu toàn bộ quy trình từ giai đoạn lên ý tưởng, thiết kế tại văn phòng cho đến quá trình triển khai gia công và sản xuất tại nhà máy với nhiều tính năng, bộ công cụ vượt trội.', 'Tin chuyên ngành', 'Thiết kế tủ bếp nhanh chóng bằng tính năng Cabinet Generator trong phần mềm PYTHA 3D CAD', 'thiet-ke-tu-bep-nhanh-chong-bang-tinh-nang-cabinet-generator-trong-phan-mem-pytha-3d-cad', NULL, NULL, 'Thiết kế tủ bếp nhanh chóng bằng tính năng Cabinet Generator trong phần mềm PYTHA 3D CAD', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1152, 'vi', 'Việc số hóa quản lý giao thông là rất quan trọng đối với việc phát triển các khu đô thị. Tuy nhiên, các thành phố và khu vực nhỏ hơn, do hạn chế về tài nguyên, thường gặp khó khăn trong việc áp dụng các hệ thống số để giám sát và dự đoán các mô hình giao thông. Trong bài viết này, chúng tôi sẽ chia sẻ kinh nghiệm và giải thích những bước số hóa cách quản lý giao thông của các cơ quan quản lý giao thông và các doanh nghiệp ngành giao thông nói riêng. ', 'Tin chuyên ngành', '6 bước dễ dàng để số hóa cách quản lý giao thông của bạn', '6-buoc-de-dang-de-so-hoa-cach-quan-ly-giao-thong-cua-ban', NULL, NULL, '6 bước dễ dàng để số hóa cách quản lý giao thông của bạn', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1153, 'vi', 'Tập đoàn PTV sẽ cung cấp mô hình giao thông chiến lược mới cho Thành phố Hồ Chí Minh và cách mạng hóa việc di chuyển ở siêu đô thị đang mở rộng nhanh chóng này của Việt Nam. Với việc sử dụng phần mềm PTV Visum sẵn có, TP.HCM sẽ được trang bị để vượt qua các thách thức về giao thông và mở đường cho một tương lai tươi sáng hơn, một hướng đi mới cho việc quy hoạch giao thông tại TP Hồ Chí Minh nói riêng và Việt Nam nói chung.', 'Tin chuyên ngành', 'PTV Group cung cấp mô hình vận tải chiến lược mới cho TP Hồ Chí Minh', 'ptv-group-cung-cap-mo-hinh-van-tai-chien-luoc-moi-cho-tp-ho-chi-minh', NULL, NULL, 'PTV Group cung cấp mô hình vận tải chiến lược mới cho TP Hồ Chí Minh', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1154, 'vi', 'Trong bài viết này, đội ngũ kỹ thuật của Công ty CP Công nghệ và Tư vấn CIC hướng dẫn thiết kế tủ cong bằng tính năng Bending trong phần mềm thiết kế và sản xuất nội thất PYTHA CAD 3D.', 'Tin chuyên ngành', 'Hướng dẫn thiết kế tủ cong nhanh chóng với PYTHA 3D CAD', 'huong-dan-thiet-ke-tu-cong-nhanh-chong-voi-pytha-3d-cad', NULL, NULL, 'Hướng dẫn thiết kế tủ cong nhanh chóng với PYTHA 3D CAD', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1159, 'vi', '', 'Quan hệ cổ đông', 'Biên bản họp Đại hội cổ đông năm 2024', 'bien-ban-hop-dai-hoi-co-dong-nam-2024', NULL, NULL, 'Biên bản họp Đại hội cổ đông năm 2024', '') ON CONFLICT (entity_id, locale) DO NOTHING;
