INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1157, 'vi', 'Ngày 25/4/2024, Công ty CP Công nghệ và Tư vấn CIC tổ chức Đại hội cổ đông năm 2024 tại hội trường tầng 6, toà nhà CIC, 37 Lê Đại Hành, Hai Bà Trưng, Hà Nội với sự tham gia của đông đảo các cổ đông. Tại Đại hội, các cổ đông của Công ty CIC đã thông qua các nội dung quan trọng trong hoạt động kinh doanh năm 2023 và kế hoạch kinh doanh năm 2024.', 'Tin công ty', 'CIC tổ chức thành công Đại hội cổ đông 2024', 'cic-to-chuc-thanh-cong-dai-hoi-co-dong-2024', NULL, NULL, 'CIC tổ chức thành công Đại hội cổ đông 2024', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1158, 'vi', 'Vừa qua, Công ty CP Công nghệ và Tư vấn CIC cùng hãng phần mềm PTV Group đã tổ chức hội thảo giới thiệu các phần mềm giao thông của hãng cho Trường Đại học Việt Đức (VGU) - ngôi trường quốc tế công lập đầu tiên và lớn nhất Việt Nam.', 'Tin công ty', 'CIC và hãng PTV Group tổ chức hội thảo giới thiệu các phần mềm giao thông cho VGU', 'cic-va-hang-ptv-group-to-chuc-hoi-thao-gioi-thieu-cac-phan-mem-giao-thong-cho-vgu', NULL, NULL, 'CIC và hãng PTV Group tổ chức hội thảo giới thiệu các phần mềm giao thông cho VGU', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1161, 'vi', 'Vào ngày 21/05/2024, Công ty Cổ phần Công nghệ và Tư vấn CIC phối hợp với hãng HTRI tổ chức hội thảo trực tuyến để chia sẻ về việc xử lý hệ thống gia nhiệt bằng điện với các phần mềm của hãng HTRI.', 'Tin công ty', 'Hội thảo trực tuyến với chủ đề: HTRI – Thiết kế / Mô phỏng bộ gia nhiệt bằng điện', 'hoi-thao-truc-tuyen-voi-chu-de:-htri-–-thiét-kémo-phỏng-bọ-gia-nhiet-bang-dien', NULL, NULL, 'Hội thảo trực tuyến với chủ đề: HTRI – Thiết kế / Mô phỏng bộ gia nhiệt bằng điện', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1162, 'vi', 'Thiết kế, tải trọng và tài liệu cho tất cả các kết nối thép với quy trình BIM trong IDEA StatiCA.', 'Tin chuyên ngành', 'Quy trình BIM với phần mềm IDEA StatiCa Steel', 'quy-trinh-bim-voi-phan-mem-idea-statica-steel', NULL, NULL, 'Quy trình BIM với phần mềm IDEA StatiCa Steel', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1165, 'vi', 'Cùng tìm lời giải cho các nhà quản lý trong việc phát triển, quy hoạch giao thông gắn với phát triển đô thị, thông qua phần mềm PTV VISUM vào quản lý giao thông đang được nhiều thành phố quan tâm, trong đó có TP Vũng Tàu.', 'Tin chuyên ngành', 'Thành phố Vũng Tàu quan tâm ứng dụng PTV VISUM vào quản lý giao thông', 'thanh-pho-vung-tau-quan-tam-ung-dung-ptv-visum-vao-quan-ly-giao-thong', NULL, NULL, 'Thành phố Vũng Tàu quan tâm ứng dụng PTV VISUM vào quản lý giao thông', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1163, 'vi', 'cageCBAM là giải pháp toàn diện được thiết kế để định hướng những quy trình phức tạp của Cơ chế Điều chỉnh biên giới Carbon (CBAM) của EU.', 'Tin công ty', 'cageCBAM – Phần mềm hỗ trợ khai báo hồ sơ CBAM (Thuế carbon châu Âu)', 'cagecbam-–-phan-mem-ho-tro-khai-bao-ho-so-cbam-thue-carbon-chau-au', NULL, NULL, 'cageCBAM – Phần mềm hỗ trợ khai báo hồ sơ CBAM (Thuế carbon châu Âu)', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1164, 'vi', 'Hãng DNV vừa ra đưa ra hướng dẫn khắc phục lỗi ảnh hưởng tính toán Phast CFD và thông báo về hai công cụ hữu ích hỗ trợ việc sử dụng Phast CFD. Đây là thông tin mới nhất dành cho người phần mềm Phast và Safeti 9.0. Hãy theo dõi bài viết chi tiết dưới đây.', 'Tin chuyên ngành', 'Những thông tin mới nhất về phần mềm Phast và Safeti 9.0', 'nhung-thong-tin-moi-nhat-ve-phan-mem-phast-va-safeti-90', NULL, NULL, 'Những thông tin mới nhất về phần mềm Phast và Safeti 9.0', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1166, 'vi', 'Phần mềm kiểm kê khí nhà kính CAGE CARBON được giới thiệu tại Hội nghị Khoa học và Triển lãm quốc tế lần thứ 7 về Điều khiển và tự động hóa (VCCA 2024).', 'Tin công ty', 'Cage Carbon được giới thiệu tại Hội nghị Khoa học và Triển lãm quốc tế lần thứ 7 về Điều khiển và tự động hóa (VCCA 2024)', 'cage-carbon-duoc-gioi-thieu-tai-hoi-nghi-khoa-hoc-va-trien-lam-quoc-te-lan-thu-7-ve-dieu-khien-va-tu-dong-hoa-vcca-2024', NULL, NULL, 'Cage Carbon được giới thiệu tại Hội nghị Khoa học và Triển lãm quốc tế lần thứ 7 về Điều khiển và tự', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1167, 'vi', 'CAGE CARBON greenhouse gas inventory software was introduced at the 7th International Scientific Conference and Exhibition on Control and Automation (VCCA 2024).', 'Tin công ty', 'Cage Carbon was introduced at the 7th International Scientific Conference and Exhibition on Control and Automation (VCCA 2024)', 'cage-carbon-was-introduced-at-the-7th-international-scientific-conference-and-exhibition-on-control-and-automation-vcca-2024', NULL, NULL, 'Cage Carbon was introduced at the 7th International Scientific Conference and Exhibition on Control', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1168, 'vi', 'Ngày 11/5/2024, Đoàn Thanh Niên Công ty CP Công nghệ và Tư vấn CIC tham gia GIẢI CHẠY BỘ VC GROUP RUN 2024 (Lần thứ II) với sự tham gia của các vận động viên là cán bộ, nhân viên thuộc Công ty. Đặc biệt, giải chạy còn thu hút sự tham gia của thành viên gia đình của các cán bộ, nhân viên Công ty.', 'Tin công ty', 'CIC tham gia Giải chạy bộ VC Group Run 2024', 'cic-tham-gia-giai-chay-bo-vc-group-run-2024', NULL, NULL, 'CIC tham gia Giải chạy bộ VC Group Run 2024', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1169, 'vi', 'Ngày 4/5/2024, Công ty CP Công nghệ và Tư vấn CIC phối hợp với Công ty Điện lực Bà Rịa – Vũng Tàu tổ chức thành công hội thảo Giới thiệu phần mềm enjiCAD và các giải pháp cho ngành điện.', 'Tin công ty', 'CIC và Công ty Điện lực Bà Rịa – Vũng Tàu phối hợp tổ chức hội thảo giới thiệu phần mềm enjiCAD và các giải pháp cho ngành điện', 'cic-va-cong-ty-dien-luc-ba-ria-–-vung-tau-phoi-hop-to-chuc-hoi-thao-gioi-thieu-phan-mem-enjicad-va-cac-giai-phap-cho-nganh-dien', NULL, NULL, 'CIC và Công ty Điện lực Bà Rịa – Vũng Tàu phối hợp tổ chức hội thảo giới thiệu phần mềm enjiCAD và c', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1170, 'vi', 'Phần mềm Opera Job Management 3.9 là phiên bản mới nhất vừa được phát hành với nhiều cải tiến về giao diện, sửa lỗi cũng như bổ sung thêm các tính năng mới về thiết kế. Trong bài viết dưới đây, CIC sẽ giúp Quý khách hàng tìm hiểu các tính năng mới này.', 'Tin chuyên ngành', 'Cập nhật tính năng mới trong Opera Job Management phiên bản mới nhất (năm 2025)', 'cap-nhat-tinh-nang-moi-trong-opera-job-management-phien-ban-moi-nhat-nam-2025', NULL, NULL, 'Cập nhật tính năng mới trong Opera Job Management phiên bản mới nhất (năm 2025)', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1171, 'vi', 'Hôm nay, đội ngũ kỹ thuật của Công ty CP Công nghệ và Tư vấn CIC tiếp tục hướng dẫn các bạn cách sử dụng phần mềm enjiCAD với tính năng Lisp Dim tự động các đường polyline-DHL. Mời các bạn theo dõi.', 'Tin chuyên ngành', 'Lisp Dim tự động các đường polyline-DPL bằng phần mềm enjiCAD', 'lisp-dim-tu-dong-cac-duong-polyline-dpl-bang-phan-mem-enjicad', NULL, NULL, 'Lisp Dim tự động các đường polyline-DPL bằng phần mềm enjiCAD', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1172, 'vi', 'City Information Modelling (tên viết tắt: CIM) là mô hình thông tin thành phố được xem xét theo nhiều khía cạnh khác nhau nhưng vẫn tập trung vào cùng một mục tiêu, đó là làm cho quy hoạch và quản lý thành phố tốt hơn.', 'Tin chuyên ngành', 'CIM – Mô hình thông tin đô thị và các ứng dụng cho quy hoạch và quản lý thành phố', 'cim-–-mo-hinh-thong-tin-do-thi-va-cac-ung-dung-cho-quy-hoach-va-quan-ly-thanh-pho', NULL, NULL, 'CIM – Mô hình thông tin đô thị và các ứng dụng cho quy hoạch và quản lý thành phố', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1173, 'vi', 'Mới đây, Sở Xây dựng phối hợp với Công ty cổ phần Công nghệ và Tư vấn CIC tổ chức lớp tập huấn Áp dụng mô hình thông tin công trình (BIM- Builiding Information Modeling) trong ngành xây dựng.', 'Tin công ty', 'Áp dụng mô hình thông tin công trình (BIM) trong ngành xây dựng', 'ap-dung-mo-hinh-thong-tin-cong-trinh-bim-trong-nganh-xay-dung', NULL, NULL, 'Áp dụng mô hình thông tin công trình (BIM) trong ngành xây dựng', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1175, 'vi', 'Trong bài viết dưới đây, đội ngũ kỹ thuật của Công ty CP Công nghệ và Tư vấn CIC hướng dẫn cách chuyển đổi hệ Imperial Dimensions về Metric Dimensions với phần mềm enjiCAD.', 'Tin chuyên ngành', 'Cách chuyển đổi hệ Imperial Dimensions về Metric Dimensions với phần mềm enjiCAD', 'cach-chuyen-doi-he-imperial-dimensions-ve-metric-dimensions-voi-phan-mem-enjicad', NULL, NULL, 'Cách chuyển đổi hệ Imperial Dimensions về Metric Dimensions với phần mềm enjiCAD', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1174, 'vi', 'Trí tuệ nhân tạo (AI) đang dần len lỏi vào mọi ngóc ngách của đời sống, và ngành xây dựng cũng không ngoại lệ. Ngành công nghiệp này đang chứng kiến sự bùng nổ của AI, mang đến nhiều cơ hội mới cho lĩnh vực tư vấn thiết kế.', 'Tin công ty', 'Trí tuệ nhân tạo (AI)- Tương lai của ngành tư vấn thiết kế xây dựng', 'tri-tue-nhan-tao-aituong-lai-cua-nganh-tu-van-thiet-ke-xay-dung', NULL, NULL, 'Trí tuệ nhân tạo (AI)- Tương lai của ngành tư vấn thiết kế xây dựng', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1176, 'vi', 'Trong bài viết dưới đây, đội ngũ kỹ thuật của Công ty CP Công nghệ và Tư vấn CIC hướng dẫn các bước thao tác khi tạo block động với phần mềm CAD nói chung và phần mềm enjiCAD nói riêng.', 'Tin chuyên ngành', 'Các bước thao tác khi tạo block động với phần mềm CAD', 'cac-buoc-thao-tac-khi-tao-block-dong-voi-phan-mem-cad', NULL, NULL, 'Các bước thao tác khi tạo block động với phần mềm enjiCAD', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1177, 'vi', 'Với phần mềm enjiCAD, người dùng có thể sử dụng và tạo đối tượng RTEXT (Remove text).', 'Tin chuyên ngành', 'Hướng dẫn sử dụng và tạo đối tượng RTEXT (Remove text) với phần mềm enjiCAD', 'huong-dan-su-dung-va-tao-doi-tuong-rtext-remove-text-voi-phan-mem-enjicad', NULL, NULL, 'Hướng dẫn sử dụng và tạo đối tượng RTEXT (Remove text) với phần mềm enjiCAD', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1178, 'vi', 'Công ty Cổ phần Công nghệ và Tư vấn CIC đã tích cực gặp gỡ và làm việc với hàng loạt doanh nghiệp xi măng Việt Nam để giới thiệu các giải pháp liên quan đến giảm phát thải khí nhà kính', 'Tin chuyên ngành', 'CIC triển khai tư vấn dịch vụ kiểm kê khí nhà kính cho nhiều khách hàng ngành xi măng', 'cic-trien-khai-tu-van-dich-vu-kiem-ke-khi-nha-kinh-cho-nhieu-khach-hang-nganh-xi-mang', NULL, NULL, 'CIC triển khai tư vấn dịch vụ kiểm kê khí nhà kính cho nhiều khách hàng ngành xi măng', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1179, 'vi', 'Để giảm tác động đến môi trường, các kế hoạch xây dựng trang trại gió thường phải tuân thủ các quy định cục bộ hoặc quy định ở từng quốc gia. Với WindFarmer và Environment Module do DNV phát triển, người dùng có thể thiết kế trang trại gió bằng cách xem xét các yếu tố như tài nguyên gió, tiếng ồn, và bóng nhấp nháy khi cánh quạt tuabin gió quay.', 'Tin chuyên ngành', 'Tối ưu thiết kế bằng  WindFarmer để giảm tác động đến môi trường', 'toi-uu-thiet-ke-bang--windfarmer-de-giam-tac-dong-den-moi-truong', NULL, NULL, 'Tối ưu thiết kế bằng WindFarmer để giảm tác động đến môi trường', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1180, 'vi', 'IDEA Statica vừa phát hành phiên bản mới nhất (V24.0) với những tính năng mới nhất. Đây cũng là thời điểm kỷ niệm 10  năm kể từ khi phát hành phương pháp CBFEM và IDEA StatiCa Connection. IDEA Statica cũng  giới thiệu giải pháp thiết kế kết cấu bê tông 3D mang tính đột phá cho móng và tường chịu lực.', 'Tin chuyên ngành', 'Những tính năng mới trong phần mềm IDEA StatiCa phiên bản mới nhất (V24.0)', 'nhung-tinh-nang-moi-trong-phan-mem-idea-statica-phien-ban-moi-nhat', NULL, NULL, 'Những tính năng mới trong phần mềm IDEA StatiCa phiên bản mới nhất (V24.0)', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1181, 'vi', 'Công ty Cổ phần Công nghệ và Tư vấn CIC tuyển dụng vị trí Sale Engineer - Kỹ sư bán hàng tại Hà Nội với mức lương hấp dẫn.', 'Tin tuyển dụng', 'Tuyển dụng Kỹ sư bán hàng - Sales Engineer tại Hà Nội', 'tuyen-dung-ky-su-ban-hang---sales-engineer-tai-ha-noi', NULL, NULL, 'Tuyển dụng Kỹ sư bán hàng - Sales Engineer tại Hà Nội', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1182, 'vi', 'Giải phóng sức mạnh của SEG-Y với Leapfrog. Quy trình làm việc mới này cho phép các nhà địa chất trực quan hóa và tiến hành giải thích cơ bản với dữ liệu địa chấn và GPR được chuyển đổi theo chiều sâu trong bối cảnh mô hình 3D.', 'Tin chuyên ngành', 'Leapfrog- Tích hợp dữ liệu địa vật lý SEG-Y vào mô hình địa chất', 'leapfrog--tich-hop-du-lieu-dia-vat-ly-seg-y-vao-mo-hinh-dia-chat', NULL, NULL, 'Leapfrog- Tích hợp dữ liệu địa vật lý SEG-Y vào mô hình địa chất', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1183, 'vi', 'Nhằm mang đến cho các CBCNV cùng gia đình có một kỳ nghỉ hè ý nghĩa, Công ty CP Công nghệ và Tư vấn CIC đã tổ chức chuyến du lịch hè 4 ngày 3 đêm tại Trương Gia Giới – Phượng Hoàng Cổ Trấn – Thiên Môn Sơn từ ngày 24/5 đến hết ngày 27/5/2024.', 'Tin công ty', 'CIC -  Kỳ nghỉ hè đáng nhớ tại Trung Quốc: Hành Trình Khám Phá Và Gắn Kết', 'cicky-nghi-he-dang-nho-tai-trung-quoc:-hanh-trinh-kham-pha-va-gan-ket', NULL, NULL, 'CIC -  Kỳ nghỉ hè đáng nhớ tại Trung Quốc: Hành Trình Khám Phá Và Gắn Kết', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1184, 'vi', 'Ngày 07 tháng 05 năm 2024, hãng phần mềm Foxit ra mắt sản phẩm Foxit cho Salesforce - Tạo tài liệu & eSign trên Salesforce AppExchange, một thị trường doanh nghiệp hàng đầu dành cho các chuyên gia và ứng dụng đối tác, trao quyền cho khách hàng tạo và tự động hóa quy trình làm việc với tài liệu từ đầu đến cuối.', 'Tin chuyên ngành', 'Foxit dành cho Salesforce - Tạo tài liệu & eSign hiện đã có sẵn trên AppExchange', 'foxit-danh-cho-salesforce-tao-tai-lieu-amp;-esign-hien-da-co-san-tren-appexchange', NULL, NULL, 'Foxit dành cho Salesforce - Tạo tài liệu & eSign hiện đã có sẵn trên AppExchange', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1185, 'vi', 'Được phát hành bởi Công ty Opera (Ý), Opera Job Management là giải pháp chuyên dụng hỗ trợ thiết kế, bóc tách vật tư và triển khai sản xuất đối với các nhà thầu nhôm kính chuyên nghiệp. Bài viết này, Công ty CP Công nghệ và Tư vấn CIC sẽ cung cấp bộ FAQ- một số câu hỏi thường gặp trong quá trình sử dụng phần mềm này.', 'Tin chuyên ngành', 'FAQ- Những câu hỏi thường gặp khi sử dụng phần mềm Opera Job Management', 'faq--nhũng-cau-hỏi-thuòng-gạp-khi-sủ-dụng-phàn-mèm-opera-job-management', NULL, NULL, 'FAQ- Những câu hỏi thường gặp khi sử dụng phần mềm Opera Job Management', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1186, 'vi', 'Sau phiên bản nâng cấp ra mắt cách đây chưa lâu của phần mềm SAP2000, Hãng phần mềm Computers and Structures, Inc. (CSI) vừa phát hành SAP2000 v25.3.0.', 'Tin chuyên ngành', 'Ra mắt phiên bản SAP2000 V25.3.0', 'ra-mat-phien-ban-sap2000-v2530', NULL, NULL, 'Ra mắt phiên bản SAP2000 V25.3.0', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1187, 'vi', 'Tìm hiểu kiểm kê khí nhà kính (GHG Inventory) là gì, quy trình thực hiện và các yêu cầu bắt buộc doanh nghiệp phải tuân thủ trước năm 2025 theo quy định Nhà nước.Đến hết năm 2025, các cơ sở phải thực hiện các biện pháp giảm nhẹ khí nhà kính.', 'Tin chuyên ngành', 'Kiểm kê khí nhà kính là gì? Lộ trình thực hiện kiểm kê khí nhà kính ', 'kiem-ke-khi-nha-kinh-la-gi-lo-trinh-thuc-hien-kiem-ke-khi-nha-kinh', NULL, NULL, 'Kiểm kê khí nhà kính là gì? Lộ trình thực hiện kiểm kê khí nhà kính cho doanh nghiệp theo ISO 14064', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1188, 'vi', 'Tháng 5/2024, Công ty Cổ phần Công nghệ và Tư vấn CIC đã hoàn thành bàn giao 06 bộ thiết bị dò cáp ngầm, model RD7200 + TX-5 cho một đơn vị quân đội.', 'Tin công ty', 'CIC hoàn thành bàn giao 06 bộ thiết bị dò cáp ngầm', 'cic-hoan-thanh-ban-giao-06-bo-thiet-bi-do-cap-ngam', NULL, NULL, 'CIC hoàn thành bàn giao 06 bộ thiết bị dò cáp ngầm', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1189, 'vi', 'Phiên bản phần mềm enjiCAD mới nhất hiện đã được update thêm rất nhiều cải tiến và nâng cấp, giúp tăng chất lượng của phần mềm, hỗ trợ rất nhiều trong công việc thiết kế của kỹ sư ngày nay. Trong đó không thể không kể tới ứng dụng của các công cụ nâng cao rất độc đáo của enjiCAD. Chúng ta hãy cùng tìm hiểu thêm những công cụ nâng cao của enjiCAD (phần mềm thay thế AutoCAD) qua bài viết sau đây.', 'Tin chuyên ngành', 'Tổng hợp những công cụ hỗ trợ thiết kế rất hay trên enjiCAD (Phần 2)', 'tong-hop-nhung-cong-cu-ho-tro-thiet-ke-rat-hay-tren-enjicad-phan-2', NULL, NULL, 'Tổng hợp những công cụ hỗ trợ thiết kế rất hay trên enjiCAD (Phần 2)', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1190, 'vi', 'Chiều ngày 03/6/2024, Công ty Cổ phần Công nghệ và Tư vấn CIC tham gia Hội thảo áp dụng mô hình thông tin công trình (BIM) trong hoạt động xây dựng trên địa bàn tỉnh do Sở Xây dựng Quảng Ngãi tổ chức.', 'Tin công ty', 'CIC tham gia Hội thảo áp dụng mô hình thông tin công trình (BIM) tại Quảng Ngãi', 'cic-tham-gia-hoi-thao-ap-dung-mo-hinh-thong-tin-cong-trinh-bim-tai-quang-ngai', NULL, NULL, 'CIC tham gia Hội thảo áp dụng mô hình thông tin công trình (BIM) tại Quảng Ngãi', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1191, 'vi', 'Vừa qua ngày 11/06/2024 tại trụ sở Điện lực Tỉnh Bình Phước (PC Bình Phước), Công ty Cổ Phần Công Nghệ và tư vấn CIC  phối hợp tổ chức buổi tập huấn và bàn giao phần mềm enjiCAD cho các cán bộ kỹ thuật của PC Bình Phước.', 'Tin chuyên ngành', 'CIC tập huấn và bàn giao phần mềm enjiCAD cho Điện lực Bình Phước', 'cic-tap-huan-va-ban-giao-phan-mem-enjicad-cho-dien-luc-binh-phuoc', NULL, NULL, 'CIC tập huấn và bàn giao phần mềm enjiCAD cho Điện lực Bình Phước', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1192, 'vi', 'Để giúp người dùng vận hành dễ dàng hơn với phần mềm thiết kế và sản xuất nội thất PYTHA 3D CAD, trong bài viết này, chúng tôi tổng hợp các câu hỏi thường gặp kèm phần giải đáp chi tiết. Mời các bạn cùng theo dõi.', 'Tin chuyên ngành', 'Những câu hỏi thường gặp (FAQ) khi sử dụng phần mềm PYTHA 3D CAD', 'nhung-cau-hoi-thuong-gap-faq-khi-su-dung-phan-mem-pytha-3d-cad', NULL, NULL, 'Những câu hỏi thường gặp (FAQ) khi sử dụng phần mềm PYTHA 3D CAD', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1193, 'vi', 'BIM (Building Information Modeling) đang ngày càng trở nên phổ biến trong ngành xây dựng. Để đáp ứng nhu cầu ngày càng cao của thị trường, Công ty CP Công nghệ và Tư vấn CIC tổ chức Chương trình xác nhận năng lực BIM theo tiêu chuẩn ISO 19650.', 'Tin chuyên ngành', 'Chương trình xác nhận năng lực BIM theo Chuẩn ISO 19650 do CIC phối hợp Viện Tiêu Chuẩn Anh (BSI) đồng tổ chức', 'chuong-trinh-xac-nhan-nang-luc-bim-theo-chuan-iso-19650-do-cic-phoi-hop-vien-tieu-chuan-anh-bsi-dong-to-chuc', NULL, NULL, 'Chương trình xác nhận năng lực BIM theo Chuẩn ISO 19650 do CIC phối hợp Viện Tiêu Chuẩn Anh (BSI) đồ', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1194, 'vi', 'Mới đây, Công ty Cổ phần Công nghệ và Tư vấn CIC vừa trao tặng bản quyền phần mềm enjiCAD và đồng hành cùng Ngày hội hướng nghiệp tại Đại Học Bách Khoa TP Hồ Chí Minh.', 'Tin công ty', 'CIC trao tặng bản quyền phần mềm enjiCAD và đồng hành cùng Ngày hội hướng nghiệp tại Đại Học Bách Khoa TP HCM', 'cic-trao-tang-ban-quyen-phan-mem-enjicad-va-dong-hanh-cung-ngay-hoi-huong-nghiep-tai-dai-hoc-bach-khoa-tp-hcm', NULL, NULL, 'CIC trao tặng bản quyền phần mềm enjiCAD và đồng hành cùng Ngày hội hướng nghiệp tại Đại Học Bách Kh', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1195, 'vi', 'enjiCAD Express chứa một thư viện các công cụ nâng cao để giúp người dùng mở rộng sức mạnh cho thiết kế, gia tăng năng xuất và hiệu quả công việc. Đây là nhóm công cụ rất dễ sử dụng, dễ dàng tích hợp vào menu và thanh công cụ, đồng thời bao gồm một loạt các chức năng như đo kích thước, vẽ, chọn và sửa đổi các đối tượng… Dưới đây sẽ là chi tiết tính năng của nhóm công cụ nâng cao Express Tools trên phần mềm enjiCAD.', 'Tin chuyên ngành', 'Chi tiết tính năng Express Tools trên phần mềm enjiCAD (Phần 1)', 'chi-tiet-tinh-nang-express-tools-tren-phan-mem-enjicad-phan-1', NULL, NULL, 'Chi tiết tính năng Express Tools trên phần mềm enjiCAD (Phần 1)', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1196, 'vi', 'Ngày 13/6 vừa qua, Công ty CP Công nghệ và Tư vấn CIC phối hợp với Hãng phần mềm Opera đã tổ chức thành công buổi hội thảo trực tuyến để giới thiệu về những cập nhật tính năng mới trong phiên bản Opera 3.9 vừa được phát hành.', 'Tin công ty', 'CIC tổ chức thành công hội thảo Opera Job Management cho nhà thầu nhôm kính', 'cic-to-chuc-thanh-cong-hoi-thao-opera-job-management-cho-nha-thau-nhom-kinh', NULL, NULL, 'CIC tổ chức thành công hội thảo Opera Job Management cho nhà thầu nhôm kính', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1197, 'vi', 'Mới đây, Hãng CSI phát hành chính thức phần mềm ETABS Phiên bản V22.0.0. Đây là version mới nhất, bổ sung tính toán tải trọng gió theo TCVN 2737-2023.', 'Tin chuyên ngành', 'Phát hành chính thức phần mềm ETABS V22.0.0', 'phat-hanh-chinh-thuc-phan-mem-etabs-v2200', NULL, NULL, 'Phát hành chính thức phần mềm ETABS V22.0.0', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1198, 'vi', 'I-REC, tên đầy đủ là International Renewable Energy Certificate là bằng chứng xác thực về việc doanh nghiệp sử dụng năng lượng tái tạo, giúp nâng cao hình ảnh thương hiệu và đáp ứng yêu cầu của các đối tác, khách hàng quan tâm đến vấn đề môi trường.', 'Tin chuyên ngành', 'I-REC là gì? Những lợi ích của Chứng chỉ I-REC cho doanh nghiệp', 'i-rec-la-gi-nhung-loi-ich-cua-chung-chi-i-rec-cho-doanh-nghiep', NULL, NULL, 'I-REC là gì? Những lợi ích của Chứng chỉ I-REC cho doanh nghiệp', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1199, 'vi', 'Ngày 21/6/2024, Công ty CP Công nghệ và Tư vấn CIC tham gia hội thảo chuyên đề Áp dụng Mô hình thông tin công trình (BIM) trong hoạt động xây dựng tại Hà Nội.', 'Tin công ty', 'CIC tham gia hội thảo Áp dụng Mô hình thông tin công trình trong hoạt động xây dựng tại Hà Nội', 'cic-tham-gia-hoi-thao-ap-dung-mo-hinh-thong-tin-cong-trinh-trong-hoat-dong-xay-dung-tai-ha-noi', NULL, NULL, 'CIC tham gia hội thảo Áp dụng Mô hình thông tin công trình trong hoạt động xây dựng tại Hà Nội', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1200, 'vi', 'Ngày 24/6/2024, Công ty CP Công nghệ và Tư vấn CIC và Tổng Công ty Tư vấn Thiết kế GTVT-CTCP (TEDI) phối hợp tổ chức Hội thảo Giới thiệu Giải pháp BIM áp dụng tại dự án Đường sắt cao tốc Jakarta-Bandung, cùng với đại diện đến từ Hãng phần mềm Bentley.', 'Tin công ty', 'CIC và TEDI tổ chức Hội thảo Giới thiệu Giải pháp BIM áp dụng tại dự án Đường sắt cao tốc Jakarta-Bandung', 'cic-va-tedi-to-chuc-hoi-thao-gioi-thieu-giai-phap-bim-ap-dung-tai-du-an-duong-sat-cao-toc-jakarta-bandung', NULL, NULL, 'CIC và TEDI tổ chức Hội thảo Giới thiệu Giải pháp BIM áp dụng tại dự án Đường sắt cao tốc Jakarta-Ba', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1201, 'vi', 'Ngày 20/06/2024, Công ty CP Công nghệ và Tư vấn CIC phối hợp với Công ty Điện lực Bạc Liêu tổ chức thành công hội thảo Giới thiệu phần mềm enjiCAD và các giải pháp cho ngành điện.', 'Tin công ty', 'CIC và Công ty Điện lực Bạc Liêu phối hợp tổ chức Hội thảo Giới thiệu phần mềm enjiCAD và các giải pháp cho ngành điện', 'cic-va-cong-ty-dien-luc-bac-lieu-phoi-hop-to-chuc-hoi-thao-gioi-thieu-phan-mem-enjicad-va-cac-giai-phap-cho-nganh-dien', NULL, NULL, 'CIC và Công ty Điện lực Bạc Liêu phối hợp tổ chức Hội thảo Giới thiệu phần mềm enjiCAD và các giải p', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1202, 'vi', 'Bộ Xây dựng đang dự thảo Thông tư hướng dẫn quy trình, quy định kỹ thuật kiểm kê khí nhà kính, đo đạc, báo cáo, thẩm định giảm nhẹ phát thải khí nhà kính ngành Xây dựng. Công ty CP Công nghệ và Tư vấn CIC xin giới thiệu toàn văn của Dự thảo thông tư này.', 'Tin chuyên ngành', 'Bộ Xây dựng lấy ý kiến đóng góp Dự thảo Thông tư Kiểm kê khí nhà kính ngành Xây dựng', 'bo-xay-dung-lay-y-kien-dong-gop-du-thao-thong-tu-kiem-ke-khi-nha-kinh-nganh-xay-dung', NULL, NULL, 'Bộ Xây dựng lấy ý kiến đóng góp Dự thảo Thông tư Kiểm kê khí nhà kính ngành Xây dựng', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1203, 'vi', 'Mới đây, Công ty CP Công nghệ và Tư vấn CIC bàn giao Hệ thống giám sát động đất (GeoSIG) cho nhà máy thủy điện khu vực miền Trung.', 'Tin công ty', 'CIC bàn giao Hệ thống giám sát động đất (GeoSIG) cho nhà máy thủy điện khu vực miền Trung', 'cic-ban-giao-he-thong-giam-sat-dong-dat-geosig-cho-nha-may-thuy-dien-khu-vuc-mien-trung', NULL, NULL, 'CIC bàn giao Hệ thống giám sát động đất (GeoSIG) cho nhà máy thủy điện khu vực miền Trung', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1204, 'vi', 'Ngày 26/6/2024, Công ty CP Công nghệ và Tư vấn CIC tổ chức thành công Hội thảo trực tuyến với chủ đề: Phần mềm Cage Carbon - Cage CBAM trong kiểm kê phát thải khí nhà kính và lập hồ sơ CBAM - Thuế carbon Châu Âu”.', 'Tin công ty', 'CIC tổ chức thành công hội thảo Phần mềm Cage Carbon - Cage CBAM trong kiểm kê khí nhà kính và Lập hồ sơ CBAM- Thuế Carbon Châu  Âu', 'cic-to-chuc-thanh-cong-hoi-thao-phan-mem-cage-carbon-cage-cbam-trong-kiem-ke-khi-nha-kinh-va-lap-ho-so-cbamthue-carbon-chauau', NULL, NULL, 'CIC tổ chức thành công hội thảo Phần mềm Cage Carbon - Cage CBAM trong kiểm kê khí nhà kính và Lập h', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1207, 'vi', 'Lantek là bộ giải pháp phần mềm toàn diện cho ngành công nghiệp gia công kim loại tấm và thép định hình', 'Tin chuyên ngành', 'Những câu hỏi thường gặp khi sử dụng phần mềm gia công kim loại tấm - Lantek', 'nhung-cau-hoi-thuong-gap-khi-su-dung-phan-mem-gia-cong-kim-loai-tam---lantek', NULL, NULL, 'Những câu hỏi thường gặp khi sử dụng phần mềm gia công kim loại tấm - Lantek', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1205, 'vi', 'Bentley Systems, với bộ giải pháp toàn diện và tiên tiến, đã khẳng định vị thế hàng đầu trong lĩnh vực này, mang lại những lợi ích vượt trội về mặt thiết kế, xây dựng và quản lý hệ thống đường sắt tốc độ cao.', 'Tin chuyên ngành', 'Bentley – Giải pháp toàn diện cho đường sắt tốc độ cao', 'bentley-–-giai-phap-toan-dien-cho-duong-sat-toc-do-cao', NULL, NULL, 'Bentley – Giải pháp toàn diện cho đường sắt tốc độ cao', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1206, 'vi', 'Bentley có nhiều giải pháp phần mềm được ứng dụng trong các dự án đường sắt. Trong bài viết dưới đây, chúng tôi xin giới thiệu hai phần mềm đang được ứng dụng phổ biến: OpenRail ConceptStation, OpenRail Designer, OpenRail Overhead Line Designer và OpenTunnel Designer.', 'Tin chuyên ngành', 'Giải pháp phần mềm thiết kế đường sắt của hãng Bentley (OpenRail, OpenTunel)', 'giai-phap-phan-mem-thiet-ke-duong-sat-cua-hang-bentley-openrail-opentunel', NULL, NULL, 'Giải pháp phần mềm thiết kế đường sắt của hãng Bentley (OpenRail, OpenTunel)', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1208, 'vi', 'Mới đây, Hãng phần mềm Foxit vừa ra mắt người dùng hai dòng sản phẩm mới là Foxit PDF Editor và PDF Editor+ với nhiều tính năng mới.', 'Tin chuyên ngành', 'Foxit phát hành Foxit PDF Editor và PDF Editor+', 'foxit-phat-hanh-foxit-pdf-editor-va-pdf-editor', NULL, NULL, 'Foxit phát hành Foxit PDF Editor và PDF Editor+', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1209, 'vi', 'enjiCAD là phần mềm vẽ kỹ thuật được phát triển bởi Công ty Cổ Phần Công Nghệ Và Tư Vấn CIC – Bộ Xây Dựng Việt Nam. Từ khi thương mại hóa vào năm 2019 cho đến nay, enjiCAD đang là một trong trong các phần mềm thiết kế kỹ thuật chuyên nghiệp cho Kỹ sư ở Việt Nam.', 'Tin chuyên ngành', 'Phần mềm enjiCAD được ứng dụng cho những ngành nào?', 'phan-mem-enjicad-duoc-ung-dung-cho-nhung-nganh-nao', NULL, NULL, 'Phần mềm enjiCAD được ứng dụng cho những ngành nào?', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1211, 'vi', 'SAFE v22.0.0 vừa được phát hành với nhiều tính năng và cải tiến mới. Mời các bạn theo dõi trong bài viết dưới dây.', 'Tin chuyên ngành', 'Phát hành phần mềm SAFE v22.0.0', 'phat-hanh-phan-mem-safe-v2200', NULL, NULL, 'Phát hành phần mềm SAFE v22.0.0', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1212, 'vi', 'Ngày 11/7/2024, Computers and Structures, Inc. (CSI) thông báo phát hành phiên bản ETABS v22.1.0. Đây là bản cập nhật từ phiên bản v22.0.0, và CSI khuyến nghị người dùng nâng cấp lên phiên bản mới nhất càng sớm càng tốt.', 'Tin chuyên ngành', 'Khuyến nghị người dùng nâng cấp ETABS phiên bản mới nhất  V22.1.0', 'khuyen-nghi-nguoi-dung-nang-cap-etabs-phien-ban-moi-nhatv2210', NULL, NULL, 'Khuyến nghị người dùng nâng cấp ETABS phiên bản mới nhất  V22.1.0', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1213, 'vi', 'Hãng phần mềm CSI vừa ra thông báo về việc phát hành phần mềm SAFE v22.1.0, bản cập nhật từ v22.0.0. Chúng tôi khuyên người dùng cập nhật ngay phiên bản mới nhất này.', 'Tin chuyên ngành', 'Phát hành phần mềm SAFE v22.1.0 phiên bản cập nhật mới nhất từ CSI', 'phat-hanh-phan-mem-safe-v2210-phien-ban-cap-nhat-moi-nhat-tu-csi', NULL, NULL, 'Phát hành phần mềm SAFE v22.1.0 phiên bản cập nhật mới nhất từ CSI', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1214, 'vi', 'Mới đây, Công ty SCHULLER (Đức) phát hành phần mềm Bocad phiên bản mới nhất V.2024.23 với 37 tính năng mới và hơn 100 cải tiến cho người dùng.', 'Tin chuyên ngành', 'Phát hành Bocad phiên bản 2024.3', 'phat-hanh-bocad-phien-ban-20243', NULL, NULL, 'Phát hành Bocad phiên bản 2024.3', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1215, 'vi', 'Turbo Expo 2024  là sự kiện chính thức được American Society of Mechanical Engineers (ASME) tổ chức, diễn ra tại London từ ngày 24 đến 28/6/2924. Đây là một sự kiện lớn trong ngành công nghiệp tua-bin, tập hợp các chuyên gia, nhà nghiên cứu và lãnh đạo ngành.', 'Tin chuyên ngành', 'Turbo Expo 2024 - Những tài liệu hữu ích cho ngành công nghiệp Turbo', 'turbo-expo-2024nhung-tai-lieu-huu-ich-cho-nganh-cong-nghiep-turbo', NULL, NULL, 'Turbo Expo 2024 - Những tài liệu hữu ích cho ngành công nghiệp Turbo', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1216, 'vi', 'Theo lộ trình áp dụng mô hình thông tin công trình (BIM- Building Information Modeling) đã được Thủ tướng Chính phủ phê duyệt, Hà Nội bước vào giai đoạn đầu tiên với trọng tâm là đào tạo, tập huấn nhằm tháo gỡ hàng loạt vướng mắc cho các đơn vị quản lý, chủ đầu tư. Mục tiêu là giúp các bên liên quan chủ động ứng dụng BIM vào quá trình triển khai thực hiện các dự án đầu tư xây dựng.', 'Tin chuyên ngành', 'Hà Nội chủ động ứng dụng BIM vào các dự án đầu tư xây dựng', 'ha-noi-chu-dong-ung-dung-bim-vao-cac-du-an-dau-tu-xay-dung', NULL, NULL, 'Hà Nội chủ động ứng dụng BIM vào các dự án đầu tư xây dựng', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1217, 'vi', 'Vừa qua ngày 25/7/2024, Công ty CP Công nghệ và Tư vấn CIC đã tổ chức thành công buổi hội thảo trực tuyến giới thiệu hệ thống thu gom rác và thực vật thủy sinh của Hãng Weedoo (Mỹ).', 'Tin công ty', 'CIC tổ chức thành công hội thảo “Hệ thống thu gom rác và thực vật thủy sinh”', 'cic-to-chuc-thanh-cong-hoi-thao-he-thong-thu-gom-rac-va-thuc-vat-thuy-sinh', NULL, NULL, 'CIC tổ chức thành công hội thảo “Hệ thống thu gom rác và thực vật thủy sinh”', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1218, 'vi', 'Ngày 31/07/2024, Công ty CP Công nghệ và Tư vấn CIC kết hợp với hãng Sunrise Systems Limited (Anh Quốc) đã tổ chức thành công Hội thảo trực tuyến với chủ đề: PIPENET - global leader for fluid flow analysis.', 'Tin công ty', 'CIC tổ chức thành công hội thảo trực tuyến: PIPENET - global leader for fluid flow analysis', 'cic-to-chuc-thanh-cong-hoi-thao-truc-tuyen:-pipenet---global-leader-for-fluid-flow-analysis', NULL, NULL, 'CIC  tổ chức thành công hội thảo trực tuyến: PIPENET - global leader for fluid flow analysis', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1219, 'vi', 'Ngày 01/08/2024, Công ty CP Công nghệ và Tư vấn CIC kết hợp cùng hãng phần mềm Hexagon (Thuỵ Điển) đồng tổ chức thành công hội thảo trực tuyến với chủ đề “Tối ưu hoá chuyển đổi số bằng công cụ BIM và quản lý vật tư”. Hội thảo đã thu hút gần 70 đơn vị tham dự gồm các lĩnh vực: Xây dựng, phát triển bất động sản, năng lượng, điện, sản xuất vật tư, quản lý dự án, …', 'Tin công ty', 'CIC và HEXAGON tổ chức thành công hội thảo, mang đến giải pháp chuyển đổi số tối ưu cho ngành xây dựng', 'cic-va-hexagon-to-chuc-thanh-cong-hoi-thao-mang-den-giai-phap-chuyen-doi-so-toi-uu-cho-nganh-xay-dung', NULL, NULL, 'CIC và HEXAGON tổ chức thành công hội thảo, mang đến giải pháp chuyển đổi số tối ưu cho ngành xây dự', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1220, 'vi', 'Mới đây, Đại diện Công ty CP Công nghệ và tư vấn CIC cùng hãng PTV Group đã có buổi làm việc tại Trung tâm Quản lý và Điều hành giao thông thành phố Hà Nội (TRAMOC) để thảo luận về việc áp dụng các giải pháp phần mềm của PTV Group vào quy trình quản lý và điều hành giao thông. Buổi làm việc nhằm mục tiêu tìm kiếm những giải pháp hiệu quả để giải quyết các vấn đề giao thông cấp bách tại Hà Nội, như ùn tắc, quá tải phương tiện công cộng và ô nhiễm môi trường.', 'Tin công ty', 'Ứng dụng giải pháp của PTV Group vào quản lý giao thông Hà Nội', 'ung-dung-giai-phap-cua-ptv-group-vao-quan-ly-giao-thong-ha-noi', NULL, NULL, 'Ứng dụng giải pháp của PTV Group vào quản lý giao thông Hà Nội', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1221, 'vi', 'Vừa qua, Công ty CP Công nghệ và Tư vấn CIC cùng đại diện của hãng PTV Group và chuyên gia từ Đại học Giao thông Vận tải đã có buổi làm việc với đại diện của Tổng Công ty Giải pháp Doanh nghiệp Viettel (Viettel Solutions) để chia sẻ về việc ứng dụng các giải pháp của PTV cho quản lý và điều hành giao thông thông minh.', 'Tin công ty', 'CIC và PTV Group làm việc với Viettel Solutions về các giải pháp cho giao thông thông minh', 'cic-va-ptv-group-lam-viec-voi-viettel-solutions-ve-cac-giai-phap-cho-giao-thong-thong-minh', NULL, NULL, 'CIC và PTV Group làm việc với Viettel Solutions về các giải pháp cho giao thông thông minh', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1222, 'vi', 'Từ nay cho đến hết ngày 15/9/2024, Piletest thực hiện chương trình khuyến mãi đặc biệt là giảm 15% khi mua thiết bị siêu âm cọc khoan nhồi CHUM.', 'Tin khuyến mại', 'Chương trình khuyến mại cho thiết bị siêu âm cọc khoan nhồi CHUM', 'chuong-trinh-khuyen-mai-cho-thiet-bi-sieu-am-coc-khoan-nhoi-chum', NULL, NULL, 'Chương trình khuyến mại cho thiết bị siêu âm cọc khoan nhồi CHUM', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1223, 'vi', 'Vừa qua, Công ty CP Công nghệ và Tư vấn CIC tham gia tích cực Giải Thể thao Các công đoàn Xây dựng Việt Nam 2024 với hai nội dung thi đấu là cầu lông và kéo co.', 'Tin công ty', 'CIC tham gia sôi nổi Giải thể thao các công đoàn Xây dựng Việt Nam 2024', 'cic-tham-gia-soi-noi-giai-the-thao-cac-cong-doan-xay-dung-viet-nam-2024', NULL, NULL, 'CIC tham gia sôi nổi Giải thể thao các công đoàn Xây dựng Việt Nam 2024', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1224, 'vi', 'Công ty CP Công nghệ và Tư vấn CIC vừa phối hợp cùng Công ty TNHH MTV Nước sạch Hà Nội tổ chức buổi giới thiệu những tính năng nổi bật của OpenFlows WaterGEMS – phần mềm ứng dụng mô hình hóa thủy lực của Hãng Bentley. Các chuyên gia cũng tham gia đánh giá khả năng ứng dụng thực tế vào công tác quản lý hệ thống cấp nước tại Hà Nội nói riêng và Việt Nam nói chung.', 'Tin công ty', 'CIC giới thiệu giải pháp OpenFlows WaterGEMS tại Công ty TNHH MTV Nước sạch Hà Nội', 'cic-gioi-thieu-giai-phap-openflows-watergems-tai-cong-ty-tnhh-mtv-nuoc-sach-ha-noi', NULL, NULL, 'CIC giới thiệu giải pháp OpenFlows WaterGEMS tại Công ty TNHH MTV Nước sạch Hà Nội', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1225, 'vi', 'Các chuyên gia đánh giá phần mềm ứng dụng mô hình hóa thủy lực OpenFlows WaterGEMS cung cấp môi trường giao diện dễ sử dụng giúp bạn tự tin phân tích, thiết kế và tối ưu hóa hệ thống phân phối nước sạch của mình.', 'Tin công ty', 'OpenFlows WaterGEMS – Giải pháp phần mềm mạnh mẽ trong việc quản lý và vận hành hệ thống cấp nước', 'openflows-watergems-–-giai-phap-phan-mem-manh-me-trong-viec-quan-ly-va-van-hanh-he-thong-cap-nuoc', NULL, NULL, 'OpenFlows WaterGEMS – Giải pháp phần mềm mạnh mẽ trong việc quản lý và vận hành hệ thống cấp nước', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1226, 'vi', 'Vừa được phát hành phiên bản mới nhất, phần mềm đĩa kỹ thuật nổi tiếng của Bentley là GeoStudio 2024 đã có những cải tiến đáng chú ý, giúp tăng cường khả năng phân tích địa kỹ thuật và cải thiện quy trình làm việc cho các kỹ sư. Trong bài viết dưới đây, Công ty CP Công nghệ và Tư vấn CIC giới thiệu các tính năng mới được cập nhật chi tiết hơn.', 'Tin chuyên ngành', 'Phần mềm phân tích ổn định mái dốc GeoStudio 2024 có gì mới', 'phan-mem-phan-tich-on-dinh-mai-doc-geostudio-2024-co-gi-moi', NULL, NULL, 'Phần mềm phân tích ổn định mái dốc GeoStudio 2024 có gì mới', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1227, 'vi', 'Idea StatiCa được xem là công cụ đột phá trong thiết kế kết cấu trong ngành xây dựng nhờ tính năng mạnh mẽ và khả năng phân tích chi tiết.', 'Tin chuyên ngành', 'Idea StatiCa: Cuộc cách mạng thiết kế kết cấu', 'idea-statica:-cuoc-cach-mang-thiet-ke-ket-cau', NULL, NULL, 'Idea StatiCa: Cuộc cách mạnh thiết kế kết cấu', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1228, 'vi', 'Công ty Cổ phần Công nghệ và Tư vấn CIC (trực thuộc Bộ Xây dựng) đã phối hợp với Viện Tiêu chuẩn Anh BSI, tổ chức thành công khoá đào tạo “Chuyên viên BIM – Chuyên gia BIM theo Tiêu chuẩn ISO-19650”. Đây là khóa học Đạo tạo BIM ISO 19650 lần thứ 2 do Công ty CIC và BSI tổ chức.', 'Tin công ty', 'CIC tổ chức thành công khóa đào tạo Chuyên viên BIM- Chuyên gia BIM theo tiêu chuẩn ISO 19650', 'cic-to-chuc-thanh-cong-khoa-dao-tao-chuyen-vien-bimchuyen-gia-bim-theo-tieu-chuan-iso-19650', NULL, NULL, 'CIC tổ chức thành công khóa đào tạo Chuyên viên BIM- Chuyên gia BIM theo tiêu chuẩn ISO 19650', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1229, 'vi', 'Tại sao cần dùng ETABS khi có thể dùng SAP2000 cho thiết kế kết cấu là câu hỏi của khá nhiều các kỹ sư, đặc biệt là các kỹ sư mới ra trường hoặc mới tiếp cận với thiết kế kết cấu các công trình đặc thù. Dưới đây Công ty CIC xin đưa ra một số lý do tại sao ETABS lại cần thiết để các kỹ sư kết cấu có thể tham khảo.', 'Tin chuyên ngành', 'Tại sao lại cần dùng ETABS khi có thể dùng SAP2000 cho thiết kế kết cấu', 'tai-sao-lai-can-dung-etabs-khi-co-the-dung-sap2000-cho-thiet-ke-ket-cau', NULL, NULL, 'Tại sao lại cần dùng ETABS khi có thể dùng SAP2000 cho thiết kế kết cấu', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1230, 'vi', 'Trong QĐ số 13/2024/QĐ-TTg vừa được ban hành, có 2.166 cơ sở phát thải khí nhà kính phải thực hiện kiểm kê khí nhà kính. Đây là danh sách mới nhất được cập nhật năm 2024.', 'Tin chuyên ngành', 'Danh mục lĩnh vực, cơ sở phát thải khí nhà kính phải thực hiện kiểm kê khí nhà kính cập nhật năm 2024 mới nhất', 'danh-muc-linh-vuc-co-so-phat-thai-khi-nha-kinh-phai-thuc-hien-kiem-ke-khi-nha-kinh-cap-nhat-nam-2024-moi-nhat', NULL, NULL, 'Danh mục lĩnh vực, cơ sở phát thải KNK phải thực hiện kiểm kê KNK cập nhật năm 2024 mới nhất', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1231, 'vi', 'MagiCAD là một phần mềm BIM MEP (Mechanical, Electrical and Plumbing), được phát triển bởi MagiCAD Group, hiện nay thuộc Glodon Asia International. Được thành lập vào năm 1983 tại Phần Lan, MagiCAD đã có hơn 40 năm kinh nghiệm trong lĩnh vực BIM MEP và cung cấp dịch vụ phần mềm toàn diện, chuyên nghiệp.', 'Tin chuyên ngành', 'MagiCAD: Giải pháp BIM toàn diện cho Kỹ thuật Cơ khí, Điện, Đường ống (MEP)', 'magicad:-giai-phap-bim-toan-dien-cho-ky-thuat-co-khi-dien-duong-ong-mep', NULL, NULL, 'MagiCAD: Giải pháp BIM toàn diện cho Kỹ thuật Cơ khí, Điện, Đường ống (MEP)', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1232, 'vi', 'Sigma s6 Wamos II là công nghệ radar giám sát sóng và dòng chảy tiên tiến nhất trên thế giới đã được cộng đồng khoa học thế giới công nhận, đảm bảo an toàn cho ngành hàng hải.', 'Tin chuyên ngành', 'Sigma s6 Wamos II: Công nghệ radar tiên tiến cho an toàn hàng hải', 'sigma-s6-wamos-ii:-cong-nghe-radar-tien-tien-cho-an-toan-hang-hai', NULL, NULL, 'Sigma s6 Wamos II: Công nghệ radar tiên tiến cho an toàn hàng hải', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1233, 'vi', 'Bạn đang gặp khó khăn trong việc vẽ các hồ sơ kiến trúc phức tạp trên enjiCAD nói riêng và các phần mềm CAD nói chung? Trong bài viết này, CIC sẽ giới thiệu tới các bạn công cụ YQArch sẽ là trợ thủ đắc lực, tiết kiệm thời gian và nâng cao chất lượng các bản vẽ.', 'Tin chuyên ngành', 'Hướng dẫn chi tiết cài đặt YQArch để tăng tốc vẽ hồ sơ kiến trúc trên enjiCAD', 'huong-dan-chi-tiet-cai-dat-yqarch-de-tang-toc-ve-ho-so-kien-truc-tren-enjicad', NULL, NULL, 'Hướng dẫn chi tiết cài đặt YQArch để tăng tốc vẽ hồ sơ kiến trúc trên enjiCAD', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1234, 'vi', 'Công ty CP Công nghệ và Tư vấn CIC là một trong những đơn vị tại Việt Nam tư vấn dịch vụ LCA và EPD theo tiêu chuẩn quốc tế với nhiều năm kinh nghiệm, đội ngũ chuyên gia nước ngoài, giải pháp toàn diện và linh hoạt để cùng doanh nghiệp của bạn xây dựng thương hiệu xanh & bền vững.', 'Tin chuyên ngành', 'Tại sao nên lựa chọn CIC là đơn vị tư vấn thực hiện LCA và EPD?', 'tai-sao-nen-lua-chon-cic-la-don-vi-tu-van-thuc-hien-lca-va-epd', NULL, NULL, 'Tại sao nên lựa chọn CIC là đơn vị tư vấn thực hiện LCA và EPD?', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1235, 'vi', 'Vào ngày 23/8/2024, Công ty Cổ phần Công nghệ và Tư vấn CIC kết hợp với Tổng công ty Tư vấn Thiết kế Giao thông Vận tải (TEDI) tổ chức thành công hội thảo đầu tiên trong chuỗi webinar: “ỨNG DỤNG GIẢI PHÁP CỦA BENTLEY TRONG THIẾT KẾ ĐƯỜNG SẮT CAO TỐC”. Hội thảo đã thu hút được sự tham gia đông đảo đến từ phía các kỹ sư đường sắt của Tổng công ty Tư vấn Thiết kế Giao thông Vận tải (TEDI)', 'Tin công ty', 'Webinar số 1: Ứng dụng Giải pháp của Bentley trong thiết kế đường sắt cao tốc', 'webinar-so-1:-ung-dung-giai-phap-cua-bentley-trong-thiet-ke-duong-sat-cao-toc', NULL, NULL, 'Webinar số 1: Ứng dụng Giải pháp của Bentley trong thiết kế đường sắt cao tốc', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1236, 'vi', 'Vào 15h ngày 23/8/2024, tại Hội trường Công ty, Chi bộ Công ty Cổ phần Công nghệ và Tư vấn CIC trang trọng tổ chức Lễ Trao quyết định công nhận Đảng viên Chính thức cho đồng chí Trần Ngọc Quỳnh và Lễ kết nạp Đảng viên mới cho quần chúng Trịnh Văn Tâm.', 'Tin công ty', 'Chi bộ Công ty CIC tiến hành tổ chức “Lễ trao quyết định công nhận Đảng viên chính thức và Lễ kết nạp đảng viên mới”', 'chi-bo-cong-ty-cic-tien-hanh-to-chuc-le-trao-quyet-dinh-cong-nhan-dang-vien-chinh-thuc-va-le-ket-nap-dang-vien-moi', NULL, NULL, 'Chi bộ Công ty CIC tổ chức “Lễ trao quyết định Đảng viên chính thức và Lễ kết nạp Đảng viên mới', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1237, 'vi', 'Ngày 28/8/2024, Công đoàn Công ty CP Công nghệ và Tư vấn CIC kết hợp với Ban lãnh đạo Công ty tổ chức "Bữa cơm công đoàn" năm 2024 dành cho toàn thể CBCNV trong công ty.', 'Tin công ty', 'CIC tổ chức “Bữa cơm công đoàn” năm 2024  tri ân đoàn viên, người lao động', 'cic-to-chuc-bua-com-cong-doan-nam-2024tri-an-doan-vien-nguoi-lao-dong', NULL, NULL, 'CIC tổ chức “Bữa cơm công đoàn” năm 2024  tri ân đoàn viên, người lao động', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1238, 'vi', 'Chương trình đào tạo BIM theo Tiêu chuẩn ISO 19650 do CIC phối hợp cùng Viện Tiêu Chuẩn Anh (BSI) tổ chức vào ngày 08-11/10/2024.', 'Tin chuyên ngành', 'Nắm bắt cơ hội, nâng cao năng lực với khóa học BIM ISO 19650', 'nam-bat-co-hoi-nang-cao-nang-luc-voi-khoa-hoc-bim-iso-19650', NULL, NULL, 'Nắm bắt cơ hội, nâng cao năng lực với khóa học BIM ISO 19650', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1240, 'vi', 'Phần mềm mô hình địa chất, ước tính tài nguyên Leapfrog 2024.1 là phiên bản mới nhất được phát hành, tiếp tục cung cấp sự kết hợp cân bằng giữa chức năng mới và các cải tiến cho các công cụ và quy trình làm việc của các hoạt động khai khoáng và mỏ.', 'Tin chuyên ngành', 'Chính thức phát hành phiên bản Leapfrog 2024.1- Phần mềm mô hình địa chất, ước tính tài nguyên', 'chinh-thuc-phat-hanh-phien-ban-leapfrog-20241phan-mem-mo-hinh-dia-chat-uoc-tinh-tai-nguyen', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1241, 'vi', 'PTV Vissim Automotive là phần mềm mô phỏng được thiết kế đặc biệt chuyên để phục vụ nhu cầu của ngành công nghiệp ô tô.', 'Tin chuyên ngành', 'PTV Vissim Automotive: Phần mềm Mô phỏng giao thông và kiểm tra xe ô tô chuyên nghiệp', 'ptv-vissim-automotive:-phan-mem-mo-phong-giao-thong-va-kiem-tra-xe-o-to-chuyen-nghiep', NULL, NULL, 'PTV Vissim Automotive: Phần mềm Mô phỏng giao thông và kiểm tra xe ô tô chuyên nghiệp', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1242, 'vi', 'Scan to BIM là một giải pháp tiên tiến giúp chuyển đổi dữ liệu từ các bản quét 3D thành mô hình thông tin xây dựng (BIM). Công nghệ Scan to BIM mang lại độ chính xác cao và tiết kiệm thời gian trong việc thiết kế và quản lý các dự án xây dựng. Hãy cùng CIC khám phá Scan to BIM và các phương pháp Scan to BIM phổ biến hiện nay nhé!INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1243, 'vi', 'Chiều 10/9, Cục Quản lý hoạt động xây dựng (Bộ Xây dựng) cùng với Công ty Cổ phần Công nghệ và Tư vấn CIC đã tổ chức Hội nghị thảo luận, trao đổi về việc áp dụng mô hình thông tin công trình (BIM) phục vụ hỗ trợ thẩm định các dự án đầu tư xây dựng.', 'Tin công ty', 'Áp dụng mô hình thông tin công trình (BIM) phục vụ hỗ trợ thẩm định dự án xây dựng', 'ap-dung-mo-hinh-thong-tin-cong-trinh-bim-phuc-vu-ho-tro-tham-dinh-du-an-xay-dung', NULL, NULL, 'Áp dụng mô hình thông tin công trình (BIM) phục vụ hỗ trợ thẩm định dự án xây dựng', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1244, 'vi', 'CSiBridge v26 vừa được phát hành với nhiều tính năng cải tiến vượt trội, hỗ trợ tối đa cho các kỹ sư thiết kế kết cấu. Phần mềm này giờ đây đã tích hợp các tiêu chuẩn thiết kế mới nhất, giúp tăng cường độ chính xác và hiệu quả trong công việc.', 'Tin chuyên ngành', 'CSiBridge v26 chính thức ra mắt: Đột phá mới trong thiết kế kết cấu', 'csibridge-v26-chinh-thuc-ra-mat:-dot-pha-moi-trong-thiet-ke-ket-cau', NULL, NULL, 'CSiBridge v26 chính thức ra mắt: Đột phá mới trong thiết kế kết cấu', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1250, 'vi', 'Sắp tới (ngày 9/10/2024), DNV tổ chức hội thảo trực tuyến ra mắt phiên bản thứ 8 của Báo cáo Triển vọng Chuyển đổi Năng lượng toàn cầu hàng năm. Các lãnh đạo của DNV cùng các lãnh đạo ngành, các chuyên gia chính sách sẽ đưa ra báo cáo về quá trình chuyển đổi năng lượng; đưa ra những dự báo tương lai về quá trình chuyển đổi sang năng lượng sạch trên phạm vi toàn cầu.', 'Tin chuyên ngành', 'DNV tổ chức hội thảo trực tuyến ra mắt Báo cáo Triển vọng Chuyển đổi Năng lượng toàn cầu năm 2024', 'dnv-to-chuc-hoi-thao-truc-tuyen-ra-mat-bao-cao-trien-vong-chuyen-doi-nang-luong-toan-cau-nam-2024', NULL, NULL, 'DNV tổ chức hội thảo trực tuyến ra mắt Báo cáo Triển vọng Chuyển đổi Năng lượng toàn cầu năm 2024', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1245, 'vi', 'Hãng phần mềm Computers and Structures, Inc. chính thức ra mắt phiên bản SAP2000 v26.0.0, mang đến những cải tiến đáng kể và mở ra kỷ nguyên mới cho ngành thiết kế kết cấu.', 'Tin chuyên ngành', 'Chính thức phát hành SAP2000 v26 : Đột phá mới trong thiết kế kết cấu', 'chinh-thuc-phat-hanh-sap2000-v26-:-dot-pha-moi-trong-thiet-ke-ket-cau', NULL, NULL, 'Chính thức phát hành SAP2000 v26 : Đột phá mới trong thiết kế kết cấu', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1246, 'vi', 'Hiện nay, có nhiều phần mềm CAD có thể nhập và xuất tệp DGN, giúp các kỹ sư tăng cường sử dụng các công cụ thiết kế khác nhau. Khả năng tương tác này thúc đẩy hiệu quả và tính linh hoạt trong các dự án đa ngành áp dụng CAD. Trong đó enjiCAD nổi lên là phần mềm thay thế AutoCAD  với bản quyền trọn đời trả phí 1 lần, giao diện quen thuộc, khả năng tương thích đa dạng ngôn ngữ, tối ưu hiệu suất phần cứng được tin dùng.', 'Tin chuyên ngành', 'File DGN là gì? Làm sao để mở file DGN bằng phần mềm enjiCAD', 'file-dgn-la-gi-lam-sao-de-mo-file-dgn-bang-phan-mem-enjicad', NULL, NULL, 'File DGN là gì? Làm sao để mở file DGN bằng phần mềm enjiCAD', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1247, 'vi', 'Bộ Xây dựng đang tổ chức nghiên cứu xây dựng nền tảng Áp dụng mô hình thông tin công trình (BIM) trong quản lý quy hoạch xây dựng, quản lý xây dựng theo quy hoạch và quản lý hạ tầng kỹ thuật đô thị trên toàn quốc.', 'Tin chuyên ngành', 'Áp dụng BIM trong quản lý quy hoạch, xây dựng và hạ tầng kỹ thuật đô thị', 'ap-dung-bim-trong-quan-ly-quy-hoach-xay-dung-va-ha-tang-ky-thuat-do-thi', NULL, NULL, 'Áp dụng BIM trong quản lý quy hoạch, xây dựng và hạ tầng kỹ thuật đô thị', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1248, 'vi', 'Vừa qua, Công ty CP Công nghệ và Tư vấn CIC tổ chức giới thiệu phần mềm Ansys - phần mềm mô phỏng và phân tích kỹ thuật ứng dụng trong ngành đóng tàu cho Công ty Công nghiệp Tàu thủy Dung Quất (DQS). Sự kiện này có sự tham gia của Phó Tổng Giám đốc, Trưởng phòng Thiết kế tàu và các chuyên viên thiết kế Công ty DQS.', 'Tin công ty', 'CIC tổ chức hội thảo ứng dụng phần mềm Ansys trong ngành đóng tàu', 'cic-to-chuc-hoi-thao-ung-dung-phan-mem-ansys-trong-nganh-dong-tau', NULL, NULL, 'CIC tổ chức hội thảo ứng dụng phần mềm Ansys trong ngành đóng tàu', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1249, 'vi', 'Bắt đầu từ phiên bản enjiCAD 2024 người dùng đã có thể nhập các tệp 3D mới như STEP và IGES! enjiCAD tiếp tục nâng cao hiệu quả hoạt động và cải thiện trải nghiệm với tốc độ và chất lượng được tối ưu hóa, khả năng tương thích API mở rộng.', 'Tin chuyên ngành', 'Cách import STEP File vào phần mềm enjiCAD', 'cach-import-step-file-vao-phan-mem-enjicad', NULL, NULL, 'Cách import STEP File vào phần mềm enjiCAD', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1251, 'vi', 'MicroStation – Giải pháp phền mềm Bentley đã giúp một công ty thiết kế vượt qua những thách thức về thiết kế đường ray và hạn chế của địa điểm bằng khả năng mô hình hóa tham số để thiết kế một nhà ga đường sắt ngầm cho các tuyến tàu điện ngầm của Dubai, có vị trí gần một trung tâm mua sắm.', 'Tin chuyên ngành', 'Từ thách thức đến thành công: Bentley MicroStation giúp hiện thực hóa nhà ga đường sắt ngầm ở Dubai', 'tu-thach-thuc-den-thanh-cong:-bentley-microstation-giup-hien-thuc-hoa-nha-ga-duong-sat-ngam-o-dubai', NULL, NULL, 'Từ thách thức đến thành công: Bentley MicroStation giúp hiện thực hóa nhà ga đường sắt ngầm ở Dubai', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1252, 'vi', 'Trung Quốc áp dụng các giải pháp Bentley để hoàn thành dự án đường sắt cao tốc Xi’an - Shiyan tại Trung Quốc với một nửa thời gian. Quy trình kỹ thuật số Digital Workflows của Bentley đã tối ưu hóa tiến độ thi công, nâng cao hiệu quả phối hợp giữa các công cụ và ứng dụng công nghệ số để đem lại hiệu quả cho thiết kế các dự án đường sắt.', 'Tin chuyên ngành', 'Áp dụng giải pháp Bentley vào các dự án đường sắt cao tốc: Bài học từ Trung Quốc', 'ap-dung-giai-phap-bentley-vao-cac-du-an-duong-sat-cao-toc:-bai-hoc-tu-trung-quoc', NULL, NULL, 'Áp dụng giải pháp Bentley vào các dự án đường sắt cao tốc: Bài học từ Trung Quốc', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1253, 'vi', 'Công ty CP Thiết bị và Chuyển giao Công nghệ phòng cháy International nâng cao an toàn phòng cháy chữa cháy với phần mềm PyroSim và Pathfinder do Công ty CIC cung cấp.', 'Tin công ty', 'CIC bàn giao giải pháp phần mềm mô phỏng đám cháy PyroSim, mô phỏng hoạt động sơ tán Pathfinder', 'cic-ban-giao-giai-phap-phan-mem-mo-phong-dam-chay-pyrosim-mo-phong-hoat-dong-so-tan-pathfinder', NULL, NULL, 'CIC bàn giao giải pháp phần mềm mô phỏng đám cháy PyroSim, mô phỏng hoạt động sơ tán Pathfinder', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1254, 'vi', 'Ngày 24/9/2024 Công ty Cổ phần Công nghệ và Tư vấn CIC cùng Chi hội Cấp thoát nước miền Nam tổ chức thành công buổi hội thảo về giải pháp OpenFlow Water của hãng Bentley Systems.', 'Tin công ty', 'Hội thảo: Ứng dụng phần mềm Bentley OpenFlow Water để mô phỏng thủy lực hệ thống cấp nước 2024', 'hoi-thao:-ung-dung-phan-mem-bentley-openflow-water-de-mo-phong-thuy-luc-he-thong-cap-nuoc-2024', NULL, NULL, 'Hội thảo: Ứng dụng phần mềm Bentley OpenFlow Water để mô phỏng thủy lực hệ thống cấp nước 2024', '') ON CONFLICT (entity_id, locale) DO NOTHING;
