INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1258, 'vi', 'Ngày 16/10/2024, Công ty Cổ phần Công nghệ và Tư vấn CIC trân trọng mời Quý vị tham dự hội thảo: Giải pháp mô phỏng đa vật lý của Ansys trong Học thuật và Nghiên cứu: Định hình tương lai qua mô phỏng số.', 'Tin công ty', '[Sự kiện sắp diễn ra] Hội thảo Giải pháp mô phỏng đa vật lý của Ansys trong Học thuật và Nghiên cứu: Định hình tương lai qua mô phỏng số', '[su-kien-sap-dien-ra]-hoi-thao-giai-phap-mo-phong-da-vat-ly-cua-ansys-trong-hoc-thuat-va-nghien-cuu:-dinh-hinh-tuong-lai-qua-mo-phong-so', NULL, NULL, 'Hội thảo Giải pháp mô phỏng đa vật lý của Ansys trong Học thuật và Nghiên cứu:', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1259, 'vi', 'Ngày 27/09/2024, Công ty CP Công nghệ và Tư vấn CIC đã kết hợp cùng hãng phần mềm IDEA Statica (Cộng hoà Séc) tổ chức thành công Hội thảo trực tuyến với chủ đề “Quy trình BIM cho Thép và Bê tông cốt thép với giải pháp của IDEA StatiCa”. Hội thảo thu hút hơn 250 đơn vị tham dự từ nhiều lĩnh vực như xây dựng, quản lý dự án, thi công thiết kế,...', 'Tin công ty', 'CIC tổ chức thành công hội thảo trực tuyến "Quy trình BIM cho Thép và Bê tông cốt thép với giải pháp IDEA StatiCa"', 'cic-to-chuc-thanh-cong-hoi-thao-truc-tuyenquy-trinh-bim-cho-thep-va-be-tong-cot-thep-voi-giai-phap-idea-statica-', NULL, NULL, 'CIC tổ chức thành công hội thảo trực tuyến "Quy trình BIM cho Thép và Bê tông cốt thép với giải pháp', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1260, 'vi', 'Với phiên bản mới nhất 2024.2, phần mềm Deswik về thiết kế và lập kế hoạch khai thác mỏ nâng cao trải nghiệm của người dùng, tối ưu hóa hiệu suất và cải thiện các tính năng nổi bật nhằm hỗ trợ công tác quản lý tài nguyên mỏ hiệu quả hơn.', 'Tin chuyên ngành', 'Deswik 2024.2 tối ưu hóa quy trình thiết kế và lập kế hoạch mỏ', 'deswik-20242-toi-uu-hoa-quy-trinh-thiet-ke-va-lap-ke-hoach-mo', NULL, NULL, 'Deswik 2024.2 tối ưu hóa quy trình thiết kế và lập kế hoạch mỏ', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1625, 'vi', 'Trong bối cảnh chuyển đổi số đang diễn ra mạnh mẽ, ngành khai thác mỏ đang từng bước thay đổi nhờ sự hỗ trợ của các công nghệ tiên tiến, trong đó nổi bật là Mô hình Thông tin Công trình (BIM – Building Information Modeling). Công nghệ này không chỉ cải thiện công tác thiết kế và lập kế hoạch mà còn góp phần nâng cao hiệu quả vận hành, quản lý tài nguyên và đảm bảo an toàn trong quá trình khai thác.', 'Tin chuyên ngành', 'Ứng dụng BIM trong ngành khai thác mỏ – Hiện trạng và tiềm năng tương lai', 'ung-dung-bim-trong-nganh-khai-thac-mo-–-hien-trang-va-tiem-nang-tuong-lai', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1261, 'vi', 'Ngày 1/10/2024, Hãng phần mềm CSI thông báo về việc phát hành phần mềm SAFE v22.2.0, bản cập nhật từ v22.1.0. CSI khuyên người dùng cập nhật ngay phiên bản mới nhất này.', 'Tin chuyên ngành', 'SAFE V22.2.0 ra mắt, cập nhật tính năng mới cho người dùng', 'phat-hanh-phan-mem-safe-phien-ban-cap-nhat-moi-nhat-v2220', NULL, NULL, 'SAFE V22.2.0 ra mắt, cập nhật tính năng mới cho người dùng', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1262, 'vi', 'Hãng CSI vừa ra thông báo về việc phát hành ETABS v22.2.0. Đây là bản cập nhật trung gian từ ETABS v22.1.0. Chúng tôi khuyến nghị người dùng cập nhật phần mềm ETABS lên phiên bản mới càng sớm càng tốt.', 'Tin chuyên ngành', 'Khuyến nghị người dùng cập  nhật ETABS lên phiên bản V22.2.0 (phiên bản mới nhất)', 'khuyen-nghi-nguoi-dung-capnhat-etabs-len-phien-ban-v2220-phien-ban-moi-nhat', NULL, NULL, 'Khuyến nghị người dùng cập  nhật ETABS lên phiên bản V22.2.0 (phiên bản mới nhất)', '') ON CONFLICT (entity_id, locale) DO NOTHING;
