INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1265, 'vi', 'Trong giai đoạn năm 2025-2028, thị trường carbon được triển khai thí điểm; chưa bán tín chỉ carbon ra nước ngoài; từ 2029 Việt Nam sẽ chính thức vận hành thị trường carbon.', 'Tin chuyên ngành', 'Việt Nam sẽ chính thức vận hành thị trường carbon từ năm 2029', 'viet-nam-se-chinh-thuc-van-hanh-thi-truong-carbon-tu-nam-2029', NULL, NULL, 'Việt Nam sẽ chính thức vận hành thị trường carbon từ năm 2029', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1266, 'vi', 'Mới đây, hãng METRON sẽ tham dự Triển lãm Sản phẩm sinh thái và Công nghệ xanh Quốc tế 2024 (IGEM 2024) được tổ chức tại Trung tâm Hội nghị Kuala Lampur, Malaysia từ ngày 9/10 đến 11/10/2024.', 'Tin công ty', 'METRON tham dự Triển lãm Sản phẩm Sinh thái và Công nghệ xanh Quốc tế 2024 (IGEM 2024) tại Malaysia', 'metron-tham-du-trien-lam-san-pham-sinh-thai-va-cong-nghe-xanh-quoc-te-2024-igem-2024-tai-malaysia', NULL, NULL, 'METRON tham dự Triển lãm Sản phẩm Sinh thái và Công nghệ xanh Quốc tế 2024 (IGEM 2024) tại Malaysia', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1267, 'vi', 'Công ty Cổ phần Công nghệ và Tư vấn CIC vừa đạt được thành tích đáng tự hào khi giành hai giải Nhì trong Cuộc thi tuyển Phương án kiến trúc Công trình Trung tâm điều hành và Giám sát vận hành các nhà máy điện  EVNGENCO2 (Trụ sở cơ quan Tổng công ty Phát điện 2 – CTCP). Cuộc thi không có giải nhất.', 'Tin công ty', 'CIC xuất sắc giành 2 giải Nhì trong cuộc thi thiết kế Trung tâm điều hành EVNGENCO2 (không có giải Nhất)', 'cic-xuat-sac-gianh-2-giai-nhi-trong-cuoc-thi-thiet-ke-trung-tam-dieu-hanh-evngenco2-khong-co-giai-nhat', NULL, NULL, 'CIC xuất sắc giành 2 giải Nhì trong cuộc thi thiết kế Trung tâm điều hành EVNGENCO2 (không có giải N', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1268, 'vi', 'Khám phá phiên bản mới của Foxit với AI Assistant thông minh, tích hợp Microsoft Outlook mượt mà. Tăng cường hiệu suất làm việc với PDF nhờ các tính năng cải tiến như Binder, hỗ trợ đa nền tảng và khả năng truy cập tốt hơn.', 'Tin chuyên ngành', 'Đột phá cùng Foxit phiên bản mới 2024: AI Assistant, tích hợp Outlook và nhiều tính năng mới', 'dot-pha-cung-foxit-phien-ban-moi-2024:-ai-assistant-tich-hop-outlook-va-nhieu-tinh-nang-moi', NULL, NULL, 'Đột phá cùng Foxit phiên bản mới 2024: AI Assistant, tích hợp Outlook và nhiều tính năng mới', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1270, 'vi', 'Phần mềm kỹ thuật phân tích và thiết kế hệ thống đường ống áp lực và kết cấu khung CSiPlant vừa được phát hành version mới nhất với những nâng cấp đáng mong đợi. Trong bài viết dưới đây, chúng tôi sẽ cung cấp thông tin chi tiết cho người dùng.', 'Tin chuyên ngành', 'Phát hành CSiPlant 9 – Phần mềm kỹ thuật phân tích và thiết kế hệ thống đường ống áp lực & kết cấu khung', 'phat-hanh-csiplant-9-–-phan-mem-ky-thuat-phan-tich-va-thiet-ke-he-thong-duong-ong-ap-luc-amp;-ket-cau-khung', NULL, NULL, 'Phát hành CSiPlant 9 – Phần mềm kỹ thuật phân tích và thiết kế hệ thống đường ống áp lực & kết cấu k', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1271, 'vi', 'Bước vào quý IV 2024, các doanh nghiệp nằm trong danh sách kiểm kê khí nhà kính thuộc Quyết định 01/2022 và Quyết định 13/2024 đang dần bắt tay vào triển khai kiểm kê phát thải khí nhà kính, với mục tiêu hoàn thành báo cáo kiểm kê khí nhà kính trước tháng 03/2025 để đáp ứng các yêu cầu của Chính phủ, đồng thời có cơ sở xây dựng lộ trình giảm phát thải cho doanh nghiệp. CIC đóng vai trò là đơn vị tư vấn chiến lược, hỗ trợ kỹ thuật trong quá trình kiểm kê này.', 'Tin công ty', 'CIC triển khai Kiểm kê khí nhà kính và tư vấn Tuyên bố sản phẩm môi trường cho Doanh nghiệp ngành Thép và Xi măng', 'cic-trien-khai-kiem-ke-khi-nha-kinh-va-tu-van-tuyen-bo-san-pham-moi-truong-cho-doanh-nghiep-nganh-thep-va-xi-mang', NULL, NULL, 'CIC triển khai Kiểm kê khí nhà kính và tư vấn Tuyên bố sản phẩm môi trường cho Doanh nghiệp ngành Th', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1272, 'vi', 'Ngày 16/10 tại Hà Nội, Công ty CP Công nghệ và Tư vấn CIC kết hợp với Cadfem và Hãng Ansys tổ chức thành công Hội thảo "Giải pháp mô phỏng đa vật lý của Ansys trong Học thuật & Nghiên cứu - Định hình tương lai qua mô phỏng số”. Sự kiện đã thu hút sự tham gia của đông đảo các Giáo sư, Tiến sỹ, Giảng viên, Nhà nghiên cứu từ các trường Đại học, Viện nghiên cứu hàng đầu tại khu vực miền Bắc.', 'Tin công ty', 'Dấu ấn tại Hội thảo "Giải pháp mô phỏng đa vật lý của Ansys trong Học thuật & Nghiên cứu - Định hình tương lai qua mô phỏng số”', 'dau-an-tai-hoi-thaogiai-phap-mo-phong-da-vat-ly-cua-ansys-trong-hoc-thuat-amp;-nghien-cuu-dinh-hinh-tuong-lai-qua-mo-phong-so', NULL, NULL, 'Dấu ấn tại Hội thảo "Giải pháp mô phỏng đa vật lý của Ansys trong Học thuật & Nghiên cứu - Định hình', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1273, 'vi', 'Bocad 2024.4 - phiên bản cập nhật mới nhất năm nay vừa được phát hành với nhiều tính năng mới và cải tiến cho phiên bản cũ.', 'Tin chuyên ngành', 'Phát hành phần mềm Bocad 2024.4 (phiên bản mới nhất): Những thay đổi đáng giá', 'phat-hanh-phan-mem-bocad-20244-phien-ban-moi-nhat:-nhung-thay-doi-dang-gia', NULL, NULL, 'Phát hành phần mềm Bocad 2024.4 (phiên bản mới nhất): Những thay đổi đáng giá', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1274, 'vi', 'Cuối tháng 10/2024, Tập đoàn Matterport sẽ cho ra mắt phiên bản mới với các công nghệ tự động hóa, thông tin chuyên sâu về bất động sản và các chức năng mới mang tính cách mạng, từ đó giúp các doanh nghiệp ngành bất động sản hiểu, hình dung và cải thiện các hoạt động của mình. Hãy cùng chúng tôi khám phá những tính năng mới nhất này nhé.', 'Tin chuyên ngành', 'Sáng tạo không giới hạn với Matterport phiên bản mới nhất 2024', 'sang-tao-khong-gioi-han-voi-matterport-phien-ban-moi-nhat-2024', NULL, NULL, 'Sáng tạo không giới hạn với Matterport phiên bản mới nhất 2024', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1275, 'vi', 'IDEA StatiCa 24.1 đã ra mắt và sẵn sàng hỗ trợ người dùng giải quyết những thách thức về kỹ thuật kết cấu. Cho dù đang làm việc với các kết nối thép, thiết kế bê tông đúc sẵn, hay neo giữ bê tông phức tạp, phiên bản mới nhất này sẽ cung cấp cho người dùng những công cụ thiết yếu để giúp cải thiện độ chính xác của dự án và làm việc nhanh hơn.', 'Tin chuyên ngành', 'Những điểm nổi bật của phiên bản IDEA StatiCA 24.1 (phiên bản mới nhất 2024)', 'nhung-diem-noi-bat-cua-phien-ban-idea-statica-241-phien-ban-moi-nhat-2024', NULL, NULL, 'Những điểm nổi bật của phiên bản IDEA StatiCA 24.1 (phiên bản mới nhất 2024)', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1276, 'vi', 'Định hướng phát triển ngành Xi măng Việt Nam trong thời gian tới là sử dụng tiết kiệm tài nguyên khoáng sản, tiết kiệm năng lượng, giảm phát thải; gắn sản xuất với tái chế, tái sử dụng chất thải, xử lý chất thải và bảo vệ môi trường.', 'Tin chuyên ngành', 'Hướng đi xanh cho doanh nghiệp xi măng phát triển bền vững', 'huong-di-xanh-cho-doanh-nghiep-xi-mang-phat-trien-ben-vung', NULL, NULL, 'Hướng đi xanh cho doanh nghiệp xi măng phát triển bền vững', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1277, 'vi', 'enjiCAD 2025 chính thức được phát hành. Đây là phiên bản hứa hẹn sẽ đưa công việc thiết kế trở nên nhanh chóng, tối ưu hơn bao giờ hết. Phiên bản chính thức lần này của enjICAD bao gồm tính năng mới và những cải tiến rất được kỳ vọng, đặc biệt là tốc độ xử lý và hiệu năng được nâng cao so với những phiên bản trước đó. ', 'Tin chuyên ngành', 'Chính thức ra mắt: Phiên bản enjiCAD 2025', 'chinh-thuc-ra-mat:-phien-ban-enjicad-2025', NULL, NULL, 'Chính thức ra mắt: Phiên bản enjiCAD 2025', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1282, 'vi', 'Quá trình chuyển đổi từ năng lượng hóa thạch sang năng lượng tái tạo sẽ phát triển như thế nào trong 25 năm tới? Bạn có thể tìm được câu trả lời cho chính mình trong bản báo cáo đầy đủ có tên là Energy Transition Outlook 2024 (ETO 2024) do các chuyên gia hàng đầu của Hãng phần mềm DNV (Thụy Điển).', 'Tin chuyên ngành', 'Energy Transition Outlook 2024 của DNV: Phân tích và Dự báo về tương lai của ngành năng lượng trong 25 năm tới', 'energy-transition-outlook-2024-cua-dnv:-phan-tich-va-du-bao-ve-tuong-lai-cua-nganh-nang-luong-trong-25-nam-toi', NULL, NULL, 'Energy Transition Outlook 2024 của DNV: Phân tích và Dự báo về tương lai của ngành năng lượng trong', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1278, 'vi', 'Từ ngày 6 đến 8/11/2024, Công ty CP Công nghệ và Tư vấn CIC tham gia Tuần lễ Ngành nước Việt Nam – Vietnam Water Week 2024 tới tại Cung Triển lãm Kiến trúc Quy hoạch Xây dựng Quốc gia (Hà Nội) với sự bảo trợ của Bộ Xây dựng.', 'Tin công ty', 'CIC tham gia Tuần lễ ngành nước - Vietnam Water Week 2024', 'cic-tham-gia-tuan-le-nganh-nuoc-vietnam-water-week-2024', NULL, NULL, 'CIC tham gia Tuần lễ ngành nước - Vietnam Water Week 2024', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1279, 'vi', 'Mới đây, Công ty CP Công nghệ và Tư vấn CIC tổ chức thành công hội thảo giới thiệu phần mềm enjiCAD tại Công ty Cổ Phần Cấp Nước Phú Hòa Tân và Công Ty Cổ Phần Cấp Nước Gia Định với sự tham gia đông đảo của các cán bộ, nhân viên trong công ty.', 'Tin công ty', 'CIC tổ chức thành công hội thảo Giới thiệu phần mềm enjiCAD và giải pháp tiến tiến riêng cho ngành nước', 'cic-to-chuc-thanh-cong-hoi-thao-gioi-thieu-phan-mem-enjicad-va-giai-phap-tien-tien-rieng-cho-nganh-nuoc', NULL, NULL, 'CIC tổ chức thành công hội thảo Giới thiệu phần mềm enjiCAD và giải pháp tiến tiến riêng cho ngành n', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1280, 'vi', 'Trong hai ngày 31/10 và 1/11/2024, Công ty cổ phần Công nghệ và Tư vấn CIC tham gia tập huấn Lớp bồi dưỡng kiến thức về Mô hình thông tin công trình (BIM) trên địa bàn thành phố Hà Nội do Sở Xây dựng tổ chức.', 'Tin công ty', 'CIC kết hợp với Sở Xây dựng Hà Nội tổ chức Lớp bồi dưỡng kiến thức về Mô hình thông tin công trình (BIM)', 'cic-ket-hop-voi-so-xay-dung-ha-noi-to-chuc-lop-boi-duong-kien-thuc-ve-mo-hinh-thong-tin-cong-trinh-bim', NULL, NULL, 'CIC kết hợp với Sở Xây dựng Hà Nội tổ chức Lớp bồi dưỡng kiến thức về Mô hình thông tin công trình (', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1281, 'vi', 'Bộ Giao thông vận tải (GTVT) đề ra 10 biện phạm và lộ trình thực hiện giảm phát thải trong giao thông đến năm 2030 với mục tiêu giảm 5,9% lượng phát thải khí nhà kính, tương đương 45,62 triệu tấn CO2tđ.', 'Tin chuyên ngành', 'Ban hành 10 giải pháp giảm phát thải cho ngành giao thông đến năm 2030', 'ban-hanh-10-giai-phap-giam-phat-thai-cho-nganh-giao-thong-den-nam-2030', NULL, NULL, 'Ban hành 10 giải pháp giảm phát thải cho ngành giao thông đến năm 2030', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1283, 'vi', 'Tham gia Vietnam Water Week 2024, các doanh nghiệp Việt Nam nói chung và Công ty CP Công nghệ và Tư vấn CIC nói riêng đã có cơ hội trao đổi, chia sẻ, học tập kinh nghiệm, đặc biệt là giải pháp phát triển an toàn, hiệu quả, bền vững, thích ứng và tăng khả năng chống chịu với tác động của biến đổi khí hậu, hội nhập quốc tế.', 'Tin công ty', 'Cơ hội hợp tác toàn cầu, giải quyết các thách thức về tài nguyên nước tại Vietnam Water Week 2024', 'co-hoi-hop-tac-toan-cau-giai-quyet-cac-thach-thuc-ve-tai-nguyen-nuoc-tai-vietnam-water-week-2024', NULL, NULL, 'Cơ hội hợp tác toàn cầu, giải quyết các thách thức về tài nguyên nước tại Vietnam Water Week 2024', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1284, 'vi', 'Trong khuôn khổ của việc thúc đẩy chuyển đổi số trong ngành nước tại Tỉnh Quảng Ninh, Công ty Cổ phần Công nghệ và Tư vấn CIC và Hãng bentley đã tổ chức Hội thảo với chủ đề "Ứng dụng giải pháp OpenFlows" cho công ty cấp sạch Quảng Ninh.  Đây là cơ hội để các chuyên gia và công ty cấp nước sạch Quảng Ninh cùng trao đổi, chia sẻ kinh nghiệm và học hỏi về việc áp dụng công nghệ mới vào quản lý và khai thác tài nguyên nước để phát triển ngành nước  an ninh, an toàn hiệu quả và hội nhập.', 'Tin công ty', 'CIC tổ chức Hội thảo: Ứng dụng giải pháp OpenFlows để phát triển ngành nước Quảng Ninh an ninh, an toàn, hiệu quả, thúc đẩy chuyển đổi số', 'cic-to-chuc-hoi-thao:-ung-dung-giai-phap-openflows-de-phat-trien-nganh-nuoc-quang-ninh-an-ninh-an-toan-hieu-qua-thuc-day-chuyen-doi-so', NULL, NULL, 'Ứng dụng giải pháp OpenFlows để phát triển ngành nước Quảng Ninh an ninh, an toàn, hiệu quả, thúc đẩ', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1285, 'vi', 'Mới đây, Carbon Re đã thành công tích hợp mô hình AI của mình lên hệ thống điều khiển trung tâm ABB Ability Expert Optimizer của công ty vật liệu xây dựng Heidelberg Materials tại Đức.', 'Tin chuyên ngành', 'Công ty sản xuất vật liệu lớn nhất thế giới thử nghiệm mô hình AI trên CarbonRe trong sản xuất xi măng', 'cong-ty-san-xuat-vat-lieu-lon-nhat-the-gioi-thu-nghiem-mo-hinh-ai-tren-carbonre-trong-san-xuat-xi-mang', NULL, NULL, 'Công ty sản xuất vật liệu lớn nhất thế giới thử nghiệm mô hình AI trên CarbonRe trong sản xuất xi mă', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1288, 'vi', 'Trong bài viết dưới đây, chúng tôi gửi đến các bạn bộ nét tiêu chuẩn (LINETYPE) vẽ quy hoạch theo TT 04/2022/TT-BXD và cách cài nét vẽ Quy hoạch trên phần mềm enjiCAD.', 'Tin chuyên ngành', 'Hướng dẫn cài nét vẽ Quy hoạch theo TT 04/2022/TT-BXD trên enjiCAD​', 'huong-dan-cai-net-ve-quy-hoach-theo-tt-042022tt-bxd-tren-enjicad​', NULL, NULL, 'Hướng dẫn cài nét vẽ Quy hoạch theo TT 04/2022/TT-BXD trên enjiCAD​', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1286, 'vi', 'Phần mềm enjiCAD 2025 cho phép người dùng copy nhanh chóng các cài đặt từ các phiên bản enjiCAD cũ hơn sang phiên bản enjiCAD 2025 nhanh chóng mà không cần thao tác thủ công.', 'Tin chuyên ngành', 'Cách chuyển cài đặt từ enjiCAD phiên bản cũ sang enjiCAD phiên bản mới hơn', 'cach-chuyen-cai-dat-tu-enjicad-phien-ban-cu-sang-enjicad-phien-ban-moi-hon', NULL, NULL, 'Cách chuyển cài đặt từ enjiCAD phiên bản cũ sang enjiCAD phiên bản mới hơn', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1287, 'vi', 'Tăng tốc phần cứng trên phần mềm CAD là việc sử dụng các thành phần phần cứng chuyên dụng như GPU để nâng cao hiệu suất và khả năng phản hồi của phần mềm. Sự tăng tốc này cho phép phần mềm CAD xử lý được các phép tính toán phức tạp và thực hiện các tác vụ hiệu quả hơn chỉ dựa vào CPU. Trong bài viết dưới đây, chúng tôi hướng dẫn áp dụng trong phần mềm enjiCAD.', 'Tin chuyên ngành', 'Hướng dẫn cách bật tắt tính năng tăng tốc độ phần cứng trên phần mềm enjiCAD', 'huong-dan-cach-bat-tat-tinh-nang-tang-toc-do-phan-cung-tren-phan-mem-enjicad', NULL, NULL, 'Hướng dẫn cách bật tắt tính năng tăng tốc độ phần cứng trên phần mềm enjiCAD', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1289, 'vi', 'Mới đây, Công ty CP Công nghệ và Tư vấn CIC tổ chức Chương trình khám sức khỏe định kỳ năm 2024 cho gần 50 CBCNV-NLĐ. Địa điểm tại bệnh viện Đại học Y Hà Nội.', 'Tin công ty', 'CIC tổ chức khám sức khỏe định kỳ cho CBNV-NLĐ năm 2024', 'cic-to-chuc-kham-suc-khoe-dinh-ky-cho-cbnv-nld-nam-2024', NULL, NULL, 'CIC tổ chức khám sức khỏe định kỳ cho CBNV-NLĐ năm 2024', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1290, 'vi', 'Nhân dịp kỷ niệm 34 năm Ngày thành lập Công ty Cổ phần Công nghệ và Tư vấn CIC (27/11/1990 – 27/11/2024), Tập thể CBCNV- NLĐ công ty đã có chuyến đi ý nghĩa và tổ chức thành công buổi lễ kỷ niệm trong không khí ấm cúng, trang trọng từ ngày 24/11 đến ngày 25/11/2024 ở Hà Nội và Chi nhánh TP Hồ Chí Minh với nhiều hoạt động gắn kết giữa các thế hệ đã và đang làm việc tại CIC trong suốt 34 năm.', 'Tin công ty', 'CIC tổ chức thành công chương trình kỷ niệm 34 năm Ngày thành lập Công ty', 'cic-to-chuc-thanh-cong-chuong-trinh-ky-niem-34-nam-ngay-thanh-lap-cong-ty', NULL, NULL, 'CIC tổ chức thành công chương trình kỷ niệm 34 năm Ngày thành lập Công ty', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1291, 'vi', 'Kể từ bộ EPD (Tuyên bố sản phẩm môi trường) được xuất bản lần đầu tiên vào năm 1998, tính tới thời điểm hiện tại, hệ thống EPD International đang lưu trữ hơn 10.000 hồ sơ EPD hợp lệ.', 'Tin chuyên ngành', 'EPD International cán mốc công bố hơn 10.000 EPD', 'epd-international-can-moc-cong-bo-hon-10000-epd', NULL, NULL, 'EPD International cán mốc công bố hơn 10.000 EPD', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1292, 'vi', 'Máy bay không người lái (UAV)  từ lâu được phát triển và ứng dụng trong quân đội, nhưng giờ đây UAV được mở rộng ra nhiều lĩnh vực khác, đặc biệt là trong khảo sát địa chất và các mục tiêu địa vật lý. UAV không chỉ giúp khảo sát bề mặt và lòng đất của Trái Đất một cách nhanh chóng, dễ dàng và tiết kiệm chi phí mà còn an toàn và hiệu quả hơn so với phương pháp truyền thống.', 'Tin chuyên ngành', 'Máy bay không người lái (UAV) đơn giản hóa việc khảo sát địa vật lý', 'may-bay-khong-nguoi-lai-uav-don-gian-hoa-viec-khao-sat-dia-vat-ly', NULL, NULL, 'Máy bay không người lái (UAV) đơn giản hóa việc khảo sát địa vật lý', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1293, 'vi', 'Việt Nam và một số quốc gia đặt mục tiêu Net Zero (phát thải ròng bằng 0) trước 2050 nhằm ứng phó với biến đổi khí hậu toàn cầu.', 'Tin chuyên ngành', 'Mục tiêu Net Zero của Việt Nam và thế giới', 'muc-tieu-net-zero-cua-viet-nam-va-the-gioi', NULL, NULL, 'Mục tiêu Net Zero của Việt Nam và thế giới', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1294, 'vi', 'Phần mềm thiết kế, tính toán vật tư sản xuất nhôm kính FP PRO thuộc bộ giải pháp FP SUITE, của hãng phần mềm Emmegisoft (Ý), sử dụng hỗ trợ nhà thầu nhôm kính trong việc thiết kế, bóc tách vật tư, báo giá và kết nối sản xuất. Với mỗi công đoạn trong toàn bộ quy trình, FP PRO có những đặc điểm nổi bật mang tính ưu việt so với các giải pháp khác đang được sử dụng hiện nay. Trong bài viết dưới đây, CIC giới thiệu một số tính năng ưu việt.', 'Tin chuyên ngành', 'Những điểm nổi bật của FP PRO- Phần mềm thiết kế, tính toán vật tư sản xuất nhôm kính', 'nhung-diem-noi-bat-cua-fp-prophan-mem-thiet-ke-tinh-toan-vat-tu-san-xuat-nhom-kinh', NULL, NULL, 'Những điểm nổi bật của FP PRO- Phần mềm thiết kế, tính toán vật tư sản xuất nhôm kính', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1295, 'vi', 'Ngày 19/11/2024, Foxit tiếp tục dẫn đầu ngành khi thông báo ra mắt trợ lý AI trong Foxit Admin Console có thể thực hiện các tác vụ trực tiếp trong bảng điều khiển quản trị giúp người dùng quản lý sản phẩm và giấy phép hiệu quả hơn', 'Tin chuyên ngành', 'Foxit mở rộng vị thế dẫn đầu bằng việc ra mắt Trợ lý AI trong Admin Console', 'foxit-mo-rong-vi-the-dan-dau-bang-viec-ra-mat-tro-ly-ai-trong-admin-console', NULL, NULL, 'Foxit mở rộng vị thế dẫn đầu bằng việc ra mắt Trợ lý AI trong Admin Console', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1296, 'vi', 'Khẳng định cam kết mạnh mẽ của Việt Nam trong ứng phó với biến đổi khí hậu, Thứ trưởng cho biết Việt Nam đã lồng ghép các biện pháp thích ứng và giảm nhẹ phát thải khí nhà kính vào Luật Bảo vệ môi trường năm 2020 và các văn bản quy phạm pháp luật, chiến lược, chương trình, kế hoạch phát triển kinh tế - xã hội của đất nước.', 'Tin chuyên ngành', 'Thông điệp mạnh mẽ của Việt Nam tại COP29 về trách nhiệm chung & hành động quyết liệt', 'thong-diep-manh-me-cua-viet-nam-tai-cop29-ve-trach-nhiem-chung-amp;-hanh-dong-quyet-liet', NULL, NULL, 'Thông điệp mạnh mẽ của Việt Nam tại COP29 về trách nhiệm chung & hành động quyết liệt', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1297, 'vi', 'Hồ sơ tuyên bố môi trường EPD đang ngày càng phổ biến trên thế giới, đặc biệt là đối với các sản phẩm vật liệu xây dựng. Điểm hồ sơ EPD là một phần quan trọng trong thang điểm LEED để đánh giá công trình xanh của USGBC (Hội đồng Công trình xanh Hoa Kỳ).', 'Tin chuyên ngành', 'Vai trò của hồ sơ tuyên bố môi trường EPD trong đánh giá công trình xanh LEED', 'vai-tro-cua-ho-so-tuyen-bo-moi-truong-epd-trong-danh-gia-cong-trinh-xanh-leed', NULL, NULL, 'Vai trò của hồ sơ tuyên bố môi trường EPD trong đánh giá công trình xanh LEED', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1298, 'vi', 'Hệ thống Kiểm tra Đường ray Laser (LRAIL™) là giải pháp kiểm tra đường sắt hiện đại, tích hợp công nghệ AI, quét 3D và chụp 2D, giúp phát hiện nhanh chóng các hư hỏng trên đường ray. Với tốc độ kiểm tra lên đến 120 km/h, LRAIL đảm bảo độ chính xác cao, hiệu quả và tiết kiệm chi phí bảo trì.', 'Tin chuyên ngành', 'LRAIL™ - Giải pháp kiểm tra đường ray bằng Laser hiện đại, tiết kiệm chi phí cho ngành đường sắt', 'lrail™-giai-phap-kiem-tra-duong-ray-bang-laser-hien-dai-tiet-kiem-chi-phi-cho-nganh-duong-sat', NULL, NULL, 'LRAIL™ - Giải pháp kiểm tra đường ray bằng Laser hiện đại, tiết kiệm chi phí cho ngành đường sắt', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1299, 'vi', 'Khám phá các tính năng mới nhất của các phiên bản phần mềm PTV 2025 như Visum, Vissim, Vistro, PTV Hub, PTV Lines, PTV Access, PTV Model2Go, PTV Optima…trong bài viết dưới đây. Với các phiên bản mới nhất của PTV, bạn có thể dễ dàng lập kế hoạch, tối ưu hóa hệ thống giao thông, nâng cao hiệu quả quản lý giao thông với công nghệ tiên tiến.', 'Tin chuyên ngành', 'PTV 2025: Cập nhật công nghệ mới nhất cho ngành giao thông', 'ptv-2025:-cap-nhat-cong-nghe-moi-nhat-cho-nganh-giao-thong', NULL, NULL, 'PTV 2025: Cập nhật công nghệ mới nhất cho ngành giao thông', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1300, 'vi', 'Bạn muốn đo diện tích và chu vi cùng lúc của một hình phẳng trong CAD nói chung và phần mềm enjiCAD nói riêng? Các lệnh có sẵn đôi khi gặp hạn chế trong việc đo các hình dạng phức tạp, đặc biệt là những hình có cung tròn hoặc đường spline. Vì vậy, để khắc phục hạn chế này, người dùng cần sử dụng lisp CAD.', 'Tin chuyên ngành', 'Tính nhanh diện tích và chu vi trong enjiCAD 2025 với Lisp CAD', 'tinh-nhanh-dien-tich-va-chu-vi-trong-enjicad-2025-voi-lisp-cad', NULL, NULL, 'Tính nhanh diện tích và chu vi trong enjiCAD 2025 với Lisp', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1301, 'vi', 'Phần mềm enjiCAD do Công ty Cổ phần Công nghệ và Tư vấn CIC phát triển được tối ưu và nâng cấp rất nhiều và khả năng tương thích giúp cho người dùng tận dụng được khả năng và sức mạnh của các công cụ lisp một cách tối đa. Trong bài viết này, chúng tôi sẽ hướng dẫn bạn tải và sử dụng bộ LISP của enjiCAD, để bạn tối ưu hóa quy trình làm việc và nâng cao năng suất.', 'Tin chuyên ngành', 'Hướng dẫn tải và sử dụng Lisp CAD đầy đủ cho dân thiết kế', 'huong-dan-tai-va-su-dung-lisp-cad-day-du-cho-dan-thiet-ke', NULL, NULL, 'Hướng dẫn tải và sử dụng Lisp CAD đầy đủ cho dân thiết kế', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1402, 'vi', 'BIM Coordinator – Điều phối viên BIM, người đảm bảo sự hợp tác hiệu quả giữa các bộ môn và quản lý mô hình thông tin (BIM) xuyên suốt dự án.', 'Tin chuyên ngành', 'Tất cả những gì bạn cần biết để bắt đầu hành trình trở thành một BIM Coordinator chuyên nghiệp', 'tat-ca-nhung-gi-ban-can-biet-de-bat-dau-hanh-trinh-tro-thanh-mot-bim-coordinator-chuyen-nghiep', NULL, NULL, 'Tất cả những gì bạn cần biết để bắt đầu hành trình trở thành một BIM Coordinator chuyên nghiệp', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1302, 'vi', 'Trong một ngành công nghiệp cạnh tranh đang phải đối mặt với nhu cầu ngày càng tăng về hiệu quả và chính xác, mô-đun MWS Connect của ALLPLAN Precast cung cấp một giải pháp không thể thiếu cho các hoạt động bê tông đúc sẵn hiện đại.', 'Tin chuyên ngành', 'Tận dụng tối đa tiềm năng của hệ thống hàn lưới (MWS) với ALLPLAN', 'tan-dung-toi-da-tiem-nang-cua-he-thong-han-luoi-mws-voi-allplan', NULL, NULL, 'Tận dụng tối đa tiềm năng của hệ thống hàn lưới (MWS) với ALLPLAN', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1303, 'vi', 'Tương tự như FP PRO, FP FACADE là phần mềm thiết kế chuyên biệt cho mặt dựng, vách dựng thuộc bộ giải pháp FP SUITE đến từ hãng phần mềm Emmegisoft (Ý). Được tích hợp dưới dạng module mở rộng trong FP PRO, FP FACADE thừa hưởng giao diện thiết kế trực quan, thân thiện và mang tới nhiều ưu điểm nổi bật khác mà Công ty CIC sẽ điểm qua trong bài viết dưới đây.', 'Tin chuyên ngành', '5 đặc điểm nổi bật của phần mềm FP FACADE trong thiết kế mặt dựng', '5-dac-diem-noi-bat-cua-phan-mem-fp-facade-trong-thiet-ke-mat-dung', NULL, NULL, '5 đặc điểm nổi bật của phần mềm FP FACADE trong thiết kế mặt dựng', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1304, 'vi', 'Sự kiện ký thỏa thuận hợp tác chiến lược giữa Công ty CIC và Công ty tư vấn BIM lớn nhất Singapore đánh dấu bước tiến quan trọng trong việc thúc đẩy chuyển đổi số và ứng dụng Mô hình thông tin công trình (BIM) trong ngành Xây dựng tại Việt Nam.', 'Tin công ty', 'CIC và công ty tư vấn BIM lớn nhất Singapore BIMAGE ký thỏa thuận hợp tác chiến lược', 'cic-va-cong-ty-tu-van-bim-lon-nhat-singapore-bimage-ky-thoa-thuan-hop-tac-chien-luoc', NULL, NULL, 'CIC và công ty tư vấn BIM lớn nhất Singapore BIMAGE ký thỏa thuận hợp tác chiến lược', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1305, 'vi', 'Công nghệ số đang cách mạng hóa ngành xây dựng. Từ khảo sát địa hình, lập bản đồ đến quản lý dự án, công trình, công nghệ Lidar, Photogrammetry và BIM đang dẫn đầu xu hướng.', 'Tin chuyên ngành', 'Ba công nghệ số hóa công trình hàng đầu trong thời đại công nghiệp 4.0', 'ba-cong-nghe-so-hoa-cong-trinh-hang-dau-trong-thoi-dai-cong-nghiep-40', NULL, NULL, 'Ba công nghệ số hóa công trình hàng đầu trong thời đại công nghiệp 4.0', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1306, 'vi', 'Radiodetection - nhà cung cấp hàng đầu về thiết bị định vị hạ tầng ngầm, chính thức công bố khả năng tương thích của thiết bị định vị RD8200SG với hệ điều hành iOS. Bản cập nhật này mang đến cho người dùng iPhone sự tiện lợi và hiệu quả vượt trội trong việc định vị và lập bản đồ các công trình ngầm.', 'Tin chuyên ngành', 'Radiodetection RD8200SG: Tương thích với iOS trong định vị và lập bản đồ công trình ngầm', 'radiodetection-rd8200sg:-tuong-thich-voi-ios-trong-dinh-vi-va-lap-ban-do-cong-trinh-ngam', NULL, NULL, 'Radiodetection RD8200SG: Tương thích với iOS trong định vị và lập bản đồ công trình ngầm', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1310, 'vi', 'Ngày 11 tháng 12 năm 2024, CSI đã ra thông báo về việc phát hành phiên bản mới nhất của phần mềm phân tích kháng chấn, động đất Perform3D v10.0.0, với các cải tiến và phát triển sáng tạo mới. Đây là bản nâng cấp lớn từ Perform3D v9.', 'Tin chuyên ngành', 'Phát hành phiên bản mới phần mềm Perform 3D 10.0.0', 'phat-hanh-phien-ban-moi-phan-mem-perform-3d-1000', NULL, NULL, 'Phát hành phiên bản mới phần mềm Perform 3D 10.0.0', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1307, 'vi', 'Bài "Tác động của chính sách Net Zero tới kiểm soát lạm phát của một số quốc gia và kinh nghiệm cho Việt Nam" do ThS. Trần Mạnh Kiên (Khoa Kinh tế Quốc tế, Trường Đại học Ngân hàng TP. Hồ Chí Minh) thực hiện.', 'Tin chuyên ngành', 'Tác động của chính sách Net Zero tới kiểm soát lạm phát của một số quốc gia và kinh nghiệm cho Việt Nam', 'tac-dong-cua-chinh-sach-net-zero-toi-kiem-soat-lam-phat-cua-mot-so-quoc-gia-va-kinh-nghiem-cho-viet-nam', NULL, NULL, 'Tác động của chính sách Net Zero tới kiểm soát lạm phát của một số quốc gia và kinh nghiệm cho Việt', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1308, 'vi', 'Bù trừ carbon là một cách để các doanh nghiệp và cá nhân bù đắp lượng khí thải mà họ không thể tránh khỏi bằng cách hỗ trợ các dự án giảm phát thải ở nơi khác. Về cơ bản, bạn đang tài trợ cho việc giảm phát thải khí nhà kính (KNK) ở một nơi để bù đắp cho lượng khí thải của bạn ở nơi khác. Trong bài viết này, chúng tôi giới thiệu về tài liệu hướng dẫn bù trừ carbon cho doanh nghiệp.', 'Tin chuyên ngành', 'Bù trừ Carbon là gì? Tài liệu hướng dẫn bù trừ carbon cho doanh nghiệp', 'bu-tru-carbon-la-gi-tai-lieu-huong-dan-bu-tru-carbon-cho-doanh-nghiep', NULL, NULL, 'Bù trừ Carbon là gì? Tài liệu hướng dẫn bù trừ carbon cho doanh nghiệp', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1309, 'vi', 'Cuốn tài liệu EACs và Con đường Giảm Phát thải Phạm vi 2 ở APAC tập trung vào vai trò của Giấy chứng nhận thuộc tính năng lượng (EAC) trong việc giảm phát thải khí nhà kính, đặc biệt là trong bối cảnh các nỗ lực khử cacbon của doanh nghiệp ở khu vực Châu Á - Thái Bình Dương và cuối đua net zero đang diễn ra trên toàn cầu.', 'Tin chuyên ngành', 'Nắm bắt Làn sóng Xanh: Giấy chứng nhận Thuộc tính Năng lượng (EAC) và Tương lai Khử Cacbon Doanh nghiệp ở Châu Á - Thái Bình Dương', 'nam-bat-lan-song-xanh:-giay-chung-nhan-thuoc-tinh-nang-luong-eac-va-tuong-lai-khu-cacbon-doanh-nghiep-o-chau-a-thai-binh-duong', NULL, NULL, 'Nắm bắt Làn sóng Xanh: Giấy chứng nhận Thuộc tính Năng lượng (EAC) và Tương lai Khử Cacbon Doanh ngh', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1311, 'vi', 'Biến đổi khí hậu đang là vấn đề cấp bách toàn cầu, đòi hỏi các giải pháp hiệu quả để giảm phát thải khí nhà kính và hướng tới mục tiêu Net Zero. CO2Tech, với sự hợp tác cùng CO2CRC, đã phát triển một loạt công nghệ tiên tiến, tập trung vào thu giữ, lưu trữ, sử dụng và giảm trừ CO2, góp phần vào mục tiêu chung vì một tương lai bền vững.', 'Tin chuyên ngành', 'CO2Tech: Giải pháp tiên phong trong công nghệ thu giữ và giảm phát thải CO2', 'co2tech:-giai-phap-tien-phong-trong-cong-nghe-thu-giu-va-giam-phat-thai-co2', NULL, NULL, 'CO2Tech: Giải pháp tiên phong trong công nghệ thu giữ và giảm phát thải CO2', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1312, 'vi', 'Giải pháp Bentley đang tạo nên bước đột phá trong ngành nước, giúp tối ưu hóa hệ thống cấp nước và nâng cao hiệu quả quản lý. Vì vậy, ngày 13/12/2024, Công ty CIC đã tổ chức thành công hội thảo giới thiệu bộ giải pháp này tại Công ty CP Nước mặt Sông Đuống (AQUAONE), mở ra cơ hội ứng dụng công nghệ tiên tiến vào quản lý tài nguyên nước hiệu quả và bền vững.', 'Tin công ty', 'CIC tổ chức thành công hội thảo: Ứng dụng giải pháp Bentley, nâng cao hiệu quả quản lý trong ngành nước', 'cic-to-chuc-thanh-cong-hoi-thao:-ung-dung-giai-phap-bentley-nang-cao-hieu-qua-quan-ly-trong-nganh-nuoc', NULL, NULL, 'CIC tổ chức thành công hội thảo: Ứng dụng giải pháp Bentley, nâng cao hiệu quả quản lý trong ngành n', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1313, 'vi', 'Ngày 20/12/2024, Bộ Xây dựng đã ban hành Thông tư 13/2024/TT-BXD, quy định quy trình kỹ thuật kiểm kê khí nhà kính và đo đạc, báo cáo, thẩm định giảm nhẹ phát thải khí nhà kính trong ngành xây dựng.', 'Tin chuyên ngành', 'Bộ Xây dựng ban hành thông tư hướng dẫn quy trình, quy định kiểm kê, báo cáo, thẩm định giảm phát thải KNK ngành Xây dựng', 'bo-xay-dung-ban-hanh-thong-tu-huong-dan-quy-trinh-quy-dinh-kiem-ke-bao-cao-tham-dinh-giam-phat-thai-knk-nganh-xay-dung', NULL, NULL, 'Bộ Xây dựng ban hành thông tư hướng dẫn quy trình, quy định kiểm kê, báo cáo, thẩm định giảm phát th', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1314, 'vi', 'Chi phí thực hiện LCA và công bố EPD là một con số tương đối đáng kể, do đó, doanh nghiệp cần cân nhắc kỹ lưỡng và hợp tác với đơn vị tư vấn giàu kinh nghiệm, uy tín để đảm bảo kết quả đánh giá chính xác, chất lượng cao và phù hợp với các tiêu chuẩn quốc tế.', 'Tin chuyên ngành', 'Chi phí thực hiện LCA và công bố EPD trên nền tảng EPD International', 'chi-phi-thuc-hien-lca-va-cong-bo-epd-tren-nen-tang-epd-international', NULL, NULL, 'Chi phí thực hiện LCA và công bố EPD trên nền tảng EPD International', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1315, 'vi', 'BIM, tên đầy đủ là Building Information Modeling là một quy trình liên quan tới việc tạo lập và quản lý những đặc trưng kỹ thuật số (được gọi là mô hình thông tin kỹ thuật số) trong các khâu thiết kế, thi công và vận hành các công trình (công trình ở đây có thể là công trình xây dựng hay các sản phẩm công nghiệp). Với BIM, các công ty xây dựng nhỏ hiện có khả năng tiếp cận các công nghệ như các tập đoàn lớn, trao quyền cho họ và mang lại kết quả tốt, chất lượng sản phẩm tương đương với các đối thủ cạnh tranh.', 'Tin chuyên ngành', 'BIM (Building Information Modeling) là gì? BIM đã san bằng sân chơi cho các công ty xây dựng quy mô nhỏ như thế nào', 'bim-building-information-modeling-la-gi-bim-da-san-bang-san-choi-cho-cac-cong-ty-xay-dung-quy-mo-nho-nhu-the-nao', NULL, NULL, 'BIM (Building Information Modeling) là gì? BIM đã san bằng sân chơi cho các công ty xây dựng quy mô', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1316, 'vi', 'Ngày 03/1/2025, Công ty Cổ phần Công nghệ và Tư vấn CIC (CIC) đã long trọng tổ chức Lễ tổng kết hoạt động sản xuất kinh doanh năm 2024 và triển khai kế hoạch năm 2025. Sự kiện đánh dấu một năm hoạt động thành công vượt bậc, khẳng định vị thế vững chắc của CIC trong lĩnh vực công nghệ.', 'Tin công ty', 'CIC tổng kết hoạt động sản xuất kinh doanh năm 2024 và kế hoạch triển khai năm 2025', 'cic-tong-ket-hoat-dong-san-xuat-kinh-doanh-nam-2024-va-ke-hoach-trien-khai-nam-2025', NULL, NULL, 'CIC tổng kết hoạt động sản xuất kinh doanh năm 2024 và kế hoạch triển khai năm 2025', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1317, 'vi', 'Theo Quyết định số 13/2024/QĐ-TTg về việc thực hiện kiểm kê khí nhà kính do Thủ tướng Chính phủ ban hành ngày 13/8/2024, có 2.166 doanh nghiệp thuộc các lĩnh vực công nghiệp, xây dựng, giao thông vận tải và nông lâm nghiệp sẽ phải thực hiện kiểm kê khí nhà kính và đáp ứng hạn ngạch phát thải trước ngày 31/3/2025.', 'Tin chuyên ngành', 'Hơn 2.000 doanh nghiệp phải kiểm kê khí nhà kính trước ngày 31/3/2025', 'hon-2000-doanh-nghiep-phai-kiem-ke-khi-nha-kinh-truoc-ngay-3132025', NULL, NULL, 'Hơn 2.000 doanh nghiệp phải kiểm kê khí nhà kính trước ngày 31/3/2025', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1318, 'vi', 'Công ty CP Công nghệ và Tư vấn CIC trân trọng thông báo phát hành phiên bản enjiCAD 2025 SP2. Đây là phiên bản enjiCAD mới nhất trong năm nay với nhiều cải tiến vượt trội cho người thiết kế.', 'Tin chuyên ngành', 'Phát hành phiên bản enjiCAD 2025 SP2: Nâng tầm hiệu suất thiết kế', 'phat-hanh-phien-ban-enjicad-2025-sp2:-nang-tam-hieu-suat-thiet-ke', NULL, NULL, 'Phát hành phiên bản enjiCAD 2025 SP2: Nâng tầm hiệu suất thiết kế', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1323, 'vi', 'Vừa qua ngày 17/01/2025 tại trụ sở Điện lực Tỉnh Bình Dương (PC Bình Dương), Công ty Cổ Phần Công Nghệ và tư vấn CIC phối hợp tổ chức buổi tập huấn và bàn giao phần mềm enjiCAD cho các cán bộ kỹ thuật của PC Bình Dương.', 'Tin chuyên ngành', 'CIC tập huấn và bàn giao phần mềm enjiCAD cho Điện lực Bình Dương', 'cic-tap-huan-va-ban-giao-phan-mem-enjicad-cho-dien-luc-binh-duong', NULL, NULL, 'CIC tập huấn và bàn giao phần mềm enjiCAD cho Điện lực Bình Dương', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1319, 'vi', 'Năm 2025 được dự đoán sẽ là một năm bùng nổ với những đột phá công nghệ mang tính cách mạng, hứa hẹn thay đổi sâu rộng. Cùng Công ty CIC khám phá 5 xu hướng công nghệ nổi bật nhất sẽ định hình tương lai!', 'Tin chuyên ngành', '5 Xu hướng công nghệ định hình năm 2025', '5-xu-huong-cong-nghe-dinh-hinh-nam-2025', NULL, NULL, '5 Xu hướng công nghệ định hình năm 2025', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1320, 'vi', 'Hãng phần mềm CSI vui mừng thông báo về việc phát hành phần mềm ETABS v22.4.0 vào cuối tháng 12 vừa qua. Bản cập nhật này mang đến nhiều cải tiến đáng kể về khả năng phân tích, thiết kế và hiệu suất, nâng cao trải nghiệm người dùng và tối ưu hóa quy trình làm việc.', 'Tin chuyên ngành', 'Thông báo phát hành ETABS v22.4.0', 'thong-bao-phat-hanh-etabs-v2240', NULL, NULL, 'Thông báo phát hành ETABS v22.4.0', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1321, 'vi', 'Chúng tôi vui mừng thông báo phát hành phiên bản SAFE v22.4.0, mang đến những cải tiến đáng kể về khả năng thiết kế, tài liệu hướng dẫn và giao diện lập trình ứng dụng (API).', 'Tin chuyên ngành', 'Thông báo phát hành SAFE v22.4.0', 'thong-bao-phat-hanh-safe-v2240', NULL, NULL, 'Thông báo phát hành SAFE v22.4.0', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1322, 'vi', 'Hà Nội, ngày 08 tháng 01 năm 2025 – Ông Ryo Miyazaki, Giám đốc điều hành kiêm Giám đốc phụ trách kinh doanh thiết bị và giải pháp của Tập đoàn OYO Nhật Bản, đã có chuyến thăm và làm việc tại Công ty Cổ phần Công nghệ và Tư vấn CIC. Chuyến thăm này tiếp tục khẳng định mối quan hệ hợp tác chiến lược lâu dài giữa hai bên, đồng thời mở ra những cơ hội mới trong việc cung cấp các giải pháp công nghệ tiên tiến cho thị trường Việt Nam.', 'Tin công ty', 'Tập đoàn OYO Nhật Bản thăm và làm việc tại CIC: Củng cố Hợp tác Chiến lược Bền vững tại Việt Nam', 'tap-doan-oyo-nhat-ban-tham-va-lam-viec-tai-cic:-cung-co-hop-tac-chien-luoc-ben-vung-tai-viet-nam', NULL, NULL, 'Tập đoàn OYO Nhật Bản thăm và làm việc tại CIC: Củng cố Hợp tác Chiến lược Bền vững tại Việt Nam', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1324, 'vi', 'Trong bối cảnh ngành năng lượng hạt nhân đang phát triển mạnh mẽ, việc tối ưu hóa thiết kế, phân tích kỹ lưỡng và đảm bảo an toàn tuyệt đối cho các nhà máy điện hạt nhân là yếu tố then chốt. CAESAR II & Pipestress - bộ đôi phần mềm tiên tiến từ Hexagon -  được thiết kế đặc biệt để đáp ứng những yêu cầu khắt khe này.  Với khả năng phân tích ứng suất vượt trội, đánh giá độ bền và mô phỏng tải trọng động chính xác, CAESAR II & Pipestress  giúp các kỹ sư  nâng cao hiệu quả thiết kế, rút ngắn thời gian và chi phí, đồng thời đảm bảo an toàn tối đa cho vận hành nhà máy điện hạt nhân.', 'Tin chuyên ngành', 'Bộ đôi phần mềm CAESAR II & Pipestress (Hexagon) tối ưu thiết kế và phân tích cho dự án Nhà máy năng lượng hạt nhân', 'bo-doi-phan-mem-caesar-ii-amp;-pipestress-hexagon-toi-uu-thiet-ke-va-phan-tich-cho-du-an-nha-may-nang-luong-hat-nhan', NULL, NULL, 'Bộ đôi phần mềm CAESAR II & Pipestress (Hexagon) tối ưu thiết kế và phân tích cho dự án Nhà máy năng', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1327, 'vi', 'Là đối tác của Bentley tại Việt Nam, Công ty CIC trân trọng giới thiệu bộ sưu tập webinar về ứng dụng phần mềm PLAXIS trong lĩnh vực đào hầm. Đây là một phần của chuỗi bài viết "Đào đường hầm đến thành công cùng PLAXIS" được đăng tải trên trang chủ của Bentley.', 'Tin chuyên ngành', 'Nâng cao hiệu quả đào hầm với PLAXIS: Thư viện webinar chuyên sâu', 'nang-cao-hieu-qua-dao-ham-voi-plaxis:-thu-vien-webinar-chuyen-sau', NULL, NULL, 'Nâng cao hiệu quả đào hầm với PLAXIS: Thư viện webinar chuyên sâu', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1325, 'vi', 'Tài liệu này cung cấp thông tin chi tiết về Báo cáo bền vững doanh nghiệp CSRD, một quy định mới của Liên minh Châu Âu (EU) nhằm hài hòa hóa và nâng cao các yêu cầu báo cáo về dữ liệu môi trường, xã hội và quản trị (ESG) của các công ty.', 'Tin chuyên ngành', 'Chỉ thị Báo cáo Bền vững Doanh nghiệp (CSRD): Kim chỉ nam cho chuyển đổi bền vững', 'chi-thi-bao-cao-ben-vung-doanh-nghiep-csrd:-kim-chi-nam-cho-chuyen-doi-ben-vung', NULL, NULL, 'Chỉ thị Báo cáo Bền vững Doanh nghiệp (CSRD): Kim chỉ nam cho chuyển đổi bền vững', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1326, 'vi', 'Phiên bản PLAXIS 2024.2 mới nhất trong năm nay bao gồm hai mô hình vật liệu do người dùng định nghĩa mới, một mô hình giúp cải thiện quy trình thiết kế đập chứa đuôi quặng và mô hình còn lại dùng để thiết kế đường hầm trong đá hoặc đất có độ trương nở. Một số cải tiến nhỏ về khả năng sử dụng và các tính năng mới cũng đã được bổ sung.', 'Tin chuyên ngành', 'Hỗ trợ thiết kế an toàn hơn cho đập chứa chất thải và đường hầm trong đá với Plaxis 2024.2', 'ho-tro-thiet-ke-an-toan-hon-cho-dap-chua-chat-thai-va-duong-ham-trong-da-voi-plaxis-20242', NULL, NULL, 'Hỗ trợ thiết kế an toàn hơn cho đập chứa chất thải và đường hầm trong đá với Plaxis 2024.2', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1328, 'vi', 'Tối ưu hóa dự án xây dựng nhờ vào công nghệ và mô hình địa chất tiên tiến giúp rút ngắn thời gian di chuyển, giảm ô nhiễm và tăng hiệu quả cho người dân và doanh nghiệp.', 'Tin chuyên ngành', 'Nâng cao hiệu quả, giảm ô nhiễm với công nghệ và mô hình địa chất tiên tiến', 'nang-cao-hieu-qua-giam-o-nhiem-voi-cong-nghe-va-mo-hinh-dia-chat-tien-tien', NULL, NULL, 'Tối ưu hóa dự án xây dựng: Nâng cao hiệu quả, giảm ô nhiễm với công nghệ và mô hình địa chất tiên ti', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1329, 'vi', 'Trong không khí hân hoan của những ngày đầu năm mới, Công ty cổ phần Công nghệ và Tư vấn CIC đã tổ chức thành công chương trình Khai Xuân Ất Tỵ 2025. Đây là sự kiện thường niên của CIC, thể hiện mong muốn về một năm mới an khang, thịnh vượng và gặt hái nhiều thành công hơn nữa.', 'Tin công ty', 'CIC tổ chức chương trình khai xuân Ất Tỵ 2025 thành công tốt đẹp', 'cic-to-chuc-chuong-trinh-khai-xuan-at-ty-2025-thanh-cong-tot-dep', NULL, NULL, 'CIC tổ chức chương trình khai xuân Ất Tỵ 2025 thành công tốt đẹp', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1330, 'vi', 'PV Elite là phần mềm thiết kế phân tích bồn bể áp lực của hãng  Hexagon AB (Thuỵ Điển). Phần mềm được phát triển và ứng dụng rộng rãi trong các lĩnh vực dầu khí, hoá chất, năng lượng, … trong hơn 30 năm qua. Phiên bản PV Elite v27 vừa chính thức được phát hành.', 'Tin chuyên ngành', 'Chính thức phát hành phần mềm PV Elite v27', 'chinh-thuc-phat-hanh-phan-mem-pv-elite-v27', NULL, NULL, 'Chính thức phát hành phần mềm PV Elite v27', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1331, 'vi', 'Doanh nghiệp của bạn đang tìm kiếm giải pháp để nâng cao hiệu quả gia công CNC? Phần mềm NCBrain sẽ giúp các doanh nghiệp đạt được mục tiêu đó! Với khả năng tối ưu hóa chương trình gia công vượt trội, NCBrain là giải pháp công nghệ đột phá, mang lại những lợi ích đáng kinh ngạc.', 'Tin chuyên ngành', 'NCBrain: Giải pháp tối ưu hóa gia công CNC đột phá', 'ncbrain:-giai-phap-toi-uu-hoa-gia-cong-cnc-dot-pha', NULL, NULL, 'NCBrain: Giải pháp tối ưu hóa gia công CNC đột phá', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1332, 'vi', 'Tiếp nối phần 1 về các công cụ Express Tools của phần mềm enjiCAD, CIC xin gửi tới bạn đọc bài viết giới thiệu thêm về các tính năng nâng cao này.  Trong bài viết này, chúng tôi sẽ tập trung giới thiệu các tính năng Text Tools trong bộ Express Tools của enjiCAD, các công cụ sẽ giúp việc ghi chú, chỉnh sửa text nhanh chóng và chuyên sâu hơn rất nhiều.', 'Tin chuyên ngành', 'Chi tiết tính năng Express Tool trên phần mềm enjiCAD (Phần 2)', 'chi-tiet-tinh-nang-express-tool-tren-phan-mem-enjicad-phan-2', NULL, NULL, 'Chi tiết tính năng Express Tool trên phần mềm enjiCAD (Phần 2)', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1333, 'vi', 'Tiếp nối các phần trước,  CIC  tiếp tục giới thiệu về các tính năng có trong bộ Express Tools của phần mềm enjiCAD. Trong phần này, chúng tôi sẽ giới thiệu các công cụ Layout và các công cụ Dimension giúp hỗ trợ việc ghi chú quản lý bản vẽ CAD dễ dàng tiện lợi hơn rất nhiều.', 'Tin chuyên ngành', 'Chi tiết tính năng Express Tool trên phần mềm enjiCAD (Phần 3)', 'chi-tiet-tinh-nang-express-tool-tren-phan-mem-enjicad-phan-3', NULL, NULL, 'Chi tiết tính năng Express Tool trên phần mềm enjiCAD (Phần 3)', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1429, 'vi', 'Khám phá BIMCollab Twin – giải pháp Môi trường Dữ liệu Chung (CDE) tiên tiến, tuân thủ ISO 19650, giúp Cơ quan quản lý, Chủ đầu tư, Nhà thầu tối ưu quản lý thông tin dự án.', 'Tin chuyên ngành', 'BIMCollab Twin: Môi trường Dữ liệu Chung (CDE) giúp Chủ đầu tư và Nhà thầu quản lý dự án hiệu quả', 'bimcollab-twin:-moi-truong-du-lieu-chung-cde-giup-chu-dau-tu-va-nha-thau-quan-ly-du-an-hieu-qua', NULL, NULL, 'BIMCollab Twin: Môi trường Dữ liệu Chung (CDE) giúp Chủ đầu tư và Nhà thầu quản lý dự án hiệu quả', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1334, 'vi', 'Đây là bộ tài liệu hướng dẫn áp dụng TCVN tổ chức và số hóa thông tin về công trình xây dựng gồm mô hình hóa thông tin công trình (BIM) – Quản lý thông tin sử dụng mô hình hóa thông tin công trình được Bộ Xây dựng ban hành.', 'Tin chuyên ngành', 'Hướng dẫn áp dụng TCVN 14177-1:2024 và TCVN 14177-2:2024 trong quản lý thông tin công trình xây dựng với BIM', 'huong-dan-ap-dung-tcvn-14177-1:2024-va-tcvn-14177-2:2024-trong-quan-ly-thong-tin-cong-trinh-xay-dung-voi-bim', NULL, NULL, 'Hướng dẫn áp dụng TCVN 14177-1:2024 và TCVN 14177-2:2024 trong quản lý thông tin công trình xây dựng', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1336, 'vi', 'Bentley Energy Solution cung cấp hệ sinh thái mở cho các dịch vụ và tích hợp kỹ thuật số nhằm hỗ trợ quản lý vòng đời dự án từ giai đoạn lập kế hoạch &amp; thiết kế → xây dựng → vận hành &amp; bảo trì.', 'Tin chuyên ngành', 'Bentley Energy Solution- Giải pháp toàn diện cho ngành năng lượng', 'bentley-energy-solution--giai-phap-toan-dien-cho-nganh-nang-luong', NULL, NULL, 'Bentley Energy Solution- Giải pháp toàn diện cho ngành năng lượng', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1335, 'vi', 'Quy trình thẩm định báo cáo khí nhà kính cấp cơ sở được quy định chi tiết tại Điều 12, Thông tư 01/2022/TT-BTNMT.', 'Tin chuyên ngành', 'Quy định về quy trình thẩm định kết quả kiểm kê khí nhà kính cấp cơ sở cho doanh nghiệp', 'quy-dinh-ve-quy-trinh-tham-dinh-ket-qua-kiem-ke-khi-nha-kinh-cap-co-so-cho-doanh-nghiep', NULL, NULL, 'Quy định về quy trình thẩm định kết quả kiểm kê khí nhà kính cấp cơ sở cho doanh nghiệp', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1337, 'vi', 'Từ sự thống trị tiếp tục của BIM (Building Information Modeling) đến sự trỗi dậy của AI, AR/VR và phân tích thiết kế bền vững, ngành xây dựng (AEC) đang phát triển nhanh chóng để đáp ứng nhu cầu của khách hàng.  Bằng việc nắm bắt các công nghệ mới này, doanh nghiệp từng bước khẳng định vị thế, cung cấp được các giải pháp công nghệ vượt trội cho khách hàng.', 'Tin chuyên ngành', 'Khám phá các xu hướng định hình ngành xây dựng (AEC) vào năm 2025', 'kham-pha-cac-xu-huong-dinh-hinh-nganh-xay-dung-aec-vao-nam-2025', NULL, NULL, 'Khám phá các xu hướng định hình ngành xây dựng (AEC) vào năm 2025', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1338, 'vi', 'Oasis montaj là giải pháp phần mềm mạnh mẽ trong hệ sinh thái Seequent, được sử dụng chuyên biệt cho lĩnh vực thăm dò địa vật lý, địa hóa và địa chất.', 'Tin chuyên ngành', 'Geosoft | Oasis montaj: Giải pháp phần mềm cho thăm dò địa vật lý đa ngành', 'geosoftoasis-montaj:-giai-phap-phan-mem-cho-tham-do-dia-vat-ly-da-nganh', NULL, NULL, 'Geosoft | Oasis montaj: Giải pháp phần mềm cho thăm dò địa vật lý đa ngành', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1339, 'vi', 'Từ ngày 12-13 tháng 2 năm 2025, Công ty CP Công nghệ và Tư vấn CIC vinh dự tham dự ASEAN-ANZ Channel Partner Bootcamp – sự kiện quan trọng do ANSYS tổ chức tại Four Points by Sheraton Phuket Patong Beach Resort, Thái Lan.', 'Tin công ty', 'Công ty CIC tham dự sự kiện ASEAN-ANZ Channel Partner Bootcamp do ANSYS tổ chức tại Thái Lan', 'cong-ty-cic-tham-du-su-kien-asean-anz-channel-partner-bootcamp-do-ansys-to-chuc-tai-thai-lan', NULL, NULL, 'Công ty CIC tham dự sự kiện ASEAN-ANZ Channel Partner Bootcamp do ANSYS tổ chức tại Thái Lan', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1340, 'vi', 'Trong bối cảnh toàn cầu hướng tới phát triển bền vững và giảm phát thải, Công ty Cổ phần Công nghệ và Tư vấn CIC (CIC) đã khẳng định vị thế tiên phong tại Việt Nam bằng việc cung cấp các giải pháp toàn diện, giúp doanh nghiệp vượt qua thách thức và nắm bắt cơ hội trong xu thế xanh hóa.', 'Tin công ty', 'CIC tiên phong đồng hành cùng doanh nghiệp trên hành trình Net Zero với website chuyên biệt về phát triển bền vững và kiểm kê khí nhà kính', 'cic-tien-phong-dong-hanh-cung-doanh-nghiep-tren-hanh-trinh-net-zero-voi-website-chuyen-biet-ve-phat-trien-ben-vung-va-kiem-ke-khi-nha-kinh', NULL, NULL, 'CIC tiên phong đồng hành cùng doanh nghiệp trên hành trình Net Zero với website chuyên biệt về phát', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1341, 'vi', 'Xchanger Suite là một bộ phần mềm mô phỏng trao đổi nhiệt tiên tiến, được phát triển nhằm hỗ trợ kỹ sư trong thiết kế, phân tích và tối ưu hóa hiệu suất của các thiết bị trao đổi nhiệt. Phiên bản 9.3 mang đến hơn 50 cải tiến quan trọng, giúp nâng cao độ chính xác, hiệu suất và tính linh hoạt trong mô phỏng. Dưới đây là những tính năng nổi bật của bản cập nhật này.', 'Tin chuyên ngành', 'Xchanger Suite 9.3: Phần mềm mô phỏng trao đổi nhiệt phiên bản nâng cấp với hơn 50 cải tiến quan trọng', 'xchanger-suite-93:-phan-mem-mo-phong-trao-doi-nhiet-phien-ban-nang-cap-voi-hon-50-cai-tien-quan-trong', NULL, NULL, 'Xchanger Suite 9.3: Phần mềm mô phỏng trao đổi nhiệt phiên bản nâng cấp với hơn 50 cải tiến quan trọ', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1342, 'vi', 'Để IDEA StatiCa Connection và IDEA StatiCa Member có thể sử dụng được ở mọi nơi trên thế giới, hãng IDEA StatiCA đã triển khai một số tiêu chuẩn mã quốc gia được sử dụng rộng rãi nhất. Tất cả những gì bạn cần làm là chọn tiêu chuẩn tương ứng và bắt đầu làm việc.', 'Tin chuyên ngành', 'Các tiêu chuẩn được hỗ trợ trong IDEA StatiCa Steel', 'cac-tieu-chuan-duoc-ho-tro-trong-idea-statica-steel', NULL, NULL, 'Các tiêu chuẩn được hỗ trợ trong IDEA StatiCa Steel', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1343, 'vi', 'SAP2000 v26.2.0 – Phiên bản phần mềm mới nhất với nhiều tính năng mới, tối ưu hiệu suất, tăng cường độ ổn định và bổ sung các tính năng mới hỗ trợ phân tích và thiết kế kết cấu đã chính thức được phát hành.', 'Tin chuyên ngành', 'CSI Phát Hành SAP2000 v26.2.0 – Cập Nhật Quan Trọng Cho Người Dùng', 'csi-phat-hanh-sap2000-v2620-–-cap-nhat-quan-trong-cho-nguoi-dung', NULL, NULL, 'CSI Phát Hành SAP2000 v26.2.0 – Cập Nhật Quan Trọng Cho Người Dùng', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1347, 'vi', 'Tích hợp trí tuệ nhân tạo (AI), học máy; Khả năng Sản xuất Hybrid – sản xuất lai giữa in 3D và gia công CNC; Nền tảng đám mây là những công nghệ mới đang được ứng dụng nhiều và tạo nên sự chuyển dịch cho ngành cơ khí và hệ thống CAD/CAM hiện nay.', 'Tin chuyên ngành', 'Những đột phá không giới hạn: Tương lai của ngành cơ khí và hệ thống CAD/CAM trên thế giới', 'nhung-dot-pha-khong-gioi-han:-tuong-lai-cua-nganh-co-khi-va-he-thong-cadcam-tren-the-gioi', NULL, NULL, 'Những đột phá không giới hạn: Tương lai của ngành cơ khí và hệ thống CAD/CAM trên thế giới', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1344, 'vi', 'Trong lĩnh vực kỹ thuật kết cấu, việc đảm bảo độ chính xác và an toàn trong thiết kế dưới áp lực là một thách thức lớn. Quá trình thiết kế các kết nối thép thường đòi hỏi nhiều công sức, đặc biệt khi mỗi thay đổi về hình học, tải trọng hoặc vật liệu đều kéo theo hàng giờ chỉnh sửa. Đó là lý do khóa học &quot;Cơ bản về Thiết kế Tham Số&quot; (Parametric Design Basics) ra đời – cung cấp một cách tiếp cận thông minh và tối ưu hơn.', 'Tin chuyên ngành', 'Làm chủ thiết kế tham số với khóa học mới trên IDEA StatiCa Campus', 'lam-chu-thiet-ke-tham-so-voi-khoa-hoc-moi-tren-idea-statica-campus', NULL, NULL, 'Làm chủ thiết kế tham số với khóa học mới trên IDEA StatiCa Campus', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1345, 'vi', 'Sách hướng dẫn Hành động Carbon, một nguồn tài nguyên toàn diện được thiết kế để hướng dẫn các tổ chức trên hành trình khử carbon của mình. Trong bối cảnh biến đổi khí hậu ngày càng gia tăng, nhu cầu hành động bền vững chưa bao giờ cấp bách hơn thế. Sách hướng dẫn này đóng vai trò là lộ trình từng bước để hiểu và thực hiện các chiến lược giảm thiểu carbon hiệu quả.', 'Tin chuyên ngành', 'Giới thiệu tài liệu “Carbon Action Playbook” – Hướng dẫn chiến lược hành động về carbon cho doanh nghiệp', 'gioi-thieu-tai-lieucarbon-action-playbook-–-huong-dan-chien-luoc-hanh-dong-ve-carbon-cho-doanh-nghiep', NULL, NULL, 'Giới thiệu tài liệu “Carbon Action Playbook” – Hướng dẫn chiến lược hành động về carbon cho doanh n', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1346, 'vi', 'Máy bay không người lái trong khai thác mỏ (Mine Drone) là một công cụ vô giá cho công việc trong các hoạt động khai thác mỏ dưới lòng đất và trên bề mặt. Khi công nghệ máy bay không người lái tiếp tục phát triển nhanh chóng, cơ hội tích hợp máy bay không người lái mỏ là vô tận.', 'Tin chuyên ngành', 'Máy bay không người lái trong khai thác mỏ (Mine Drone) cải thiện an toàn và tối ưu hóa khai thác', 'may-bay-khong-nguoi-lai-trong-khai-thac-mo-mine-drone-cai-thien-an-toan-va-toi-uu-hoa-khai-thac', NULL, NULL, 'Máy bay không người lái trong khai thác mỏ (Mine Drone) cải thiện an toàn và tối ưu hóa khai thác', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1348, 'vi', 'Bạn đã bao giờ tham chiếu một bản vẽ vào một bản vẽ khác, nhưng nội dung không hiển thị đúng màu, độ dày đường hoặc kiểu đường dựa trên trạng thái layer trong viewport/bản vẽ hiện tại của bạn chưa? Trong bài viết này, đội ngũ kỹ thuật của Công ty CIC sẽ đồng hành cùng bạn giải quyết vấn đề này bằng cách sử dụng lệnh SETBYLAYER trên enjiCAD nhé.', 'Tin chuyên ngành', 'Bạn đã biết về tính năng SETBYLAYER trên enjiCAD chưa?', 'ban-da-biet-ve-tinh-nang-setbylayer-tren-enjicad-chua', NULL, NULL, 'Bạn đã biết về tính năng SETBYLAYER trên enjiCAD chưa?', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1349, 'vi', 'Công ty CIC và Bentley Systems khẳng định vị thế trong việc tiên phong đổi mới công nghệ, góp phần nâng cao chất lượng và hiệu quả đầu tư hạ tầng giao thông Việt Nam nói chung, các công trình giao thông và đường sắt cao tốc nói riêng trong áp dụng các giải pháp BIM/Digital Twin của Bentley.', 'Tin công ty', 'CIC, Bentley và TEDI tổ chức thành công Hội thảo ứng dụng giải pháp BIM/Digital Twin của Bentley trong các dự án đường sắt cao tốc', 'cic-bentley-va-tedi-to-chuc-thanh-cong-hoi-thao-ung-dung-giai-phap-bimdigital-twin-cua-bentley-trong-cac-du-an-duong-sat-cao-toc', NULL, NULL, 'CIC, Bentley và TEDI tổ chức thành công Hội thảo ứng dụng giải pháp BIM/Digital Twin của Bentley tro', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1350, 'vi', 'Cubicost đã được ứng dụng thành công trong dự án Bệnh viện Tasikmalaya, minh chứng cho khả năng tối ưu hóa quy trình xây dựng, nâng cao hiệu quả hợp tác và thúc đẩy xây dựng bền vững trong lĩnh vực y tế.', 'Tin chuyên ngành', 'Dự án Bệnh viện Tasikmalaya: Cubicost - Giải pháp tối ưu cho công trình y tế hiện đại', 'du-an-benh-vien-tasikmalaya:-cubicost---giai-phap-toi-uu-cho-cong-trinh-y-te-hien-dai', NULL, NULL, 'Dự án Bệnh viện Tasikmalaya: Cubicost - Giải pháp tối ưu cho công trình y tế hiện đại', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1351, 'vi', 'Hãng CSI chính thức phát hành ETABS 22.5.1 và SAFE 22.5.1 với nhiều cập nhật và tính năng mới, xử lý các lỗi do người dùng báo cáo ở các phiên bản trước. Dưới đây là một số tính năng và thay đổi trong ETABS 22.5.1 và SAFE 22.5.1', 'Tin chuyên ngành', 'ETABS 22.5.1 và SAFE 22.5.1: Cập nhật tính năng và cải tiến hiệu suất', 'etabs-2251-va-safe-2251:-cap-nhat-tinh-nang-va-cai-tien-hieu-suat', NULL, NULL, 'ETABS 22.5.1 và SAFE 22.5.1: Cập nhật tính năng và cải tiến hiệu suất', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1352, 'vi', 'Trong thực tiễn kỹ thuật, việc thiết kế đài cọc có thể là một nhiệm vụ đầy thách thức, đặc biệt khi bố trí cọc phức tạp.  Bài viết này sẽ phân tích các loại đài cọc, khái niệm thiết kế đài cọc và các phương án thiết kế khả thi.  ', 'Tin chuyên ngành', 'Cách quản lý thiết kế móng cọc như thế nào?', 'cach-quan-ly-thiet-ke-mong-coc-nhu-the-nao', NULL, NULL, 'Cách quản lý thiết kế móng cọc như thế nào?', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1353, 'vi', 'Khám phá sức mạnh của phân tích xác suất 3D trong đánh giá độ ổn định mái dốc cùng GeoStudio tại Hội thảo trực tuyến miễn phí, được tổ chức vào ngày 11/3/2025.', 'Tin công ty', 'Hội thảo trực tuyến tháng 3: Phân tích địa kỹ thuật - Phân tích ổn định xác suất 3D trong GeoStudio', 'hoi-thao-truc-tuyen-thang-3:-phan-tich-dia-ky-thuat-phan-tich-on-dinh-xac-suat-3d-trong-geostudio', NULL, NULL, 'Hội thảo trực tuyến tháng 3: Phân tích địa kỹ thuật - Phân tích ổn định xác suất 3D trong GeoStudio', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1354, 'vi', 'Một trong những ưu điểm lớn nhất của IDEA StatiCa Detail 24.1 là mô hình hóa nhanh và trực quan trong khi vẫn nắm bắt trung thực các tính năng kết cấu và hiển thị kết quả chính xác.', 'Tin chuyên ngành', 'Mô Hình Hóa Chi Tiết Nhanh Chóng và Trực Quan với IDEA StatiCa Detail (Phiên Bản 24.1)', 'mo-hinh-hoa-chi-tiet-nhanh-chong-va-truc-quan-voi-idea-statica-detail-phien-ban-241', NULL, NULL, 'Mô Hình Hóa Chi Tiết Nhanh Chóng và Trực Quan với IDEA StatiCa Detail (Phiên Bản 24.1)', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1355, 'vi', 'Trong bối cảnh ngành xây dựng không ngừng phát triển và đổi mới, việc ứng dụng công nghệ tiên tiến đã trở thành yếu tố quyết định giúp các doanh nghiệp tối ưu hóa hiệu suất, giảm chi phí và nâng cao chất lượng dự án. Một trong những dự án tiêu biểu cho xu hướng này là Khuôn viên Học viện Công nghệ Singapore (Singapore Institute of Technology - SIT) tại Punggol, Singapore. Dự án này đã ứng dụng nền tảng Cubicost 5D BIM của Glodon để đạt được độ chính xác cao trong ước tính chi phí và tối ưu hóa quy trình xây dựng.', 'Tin chuyên ngành', 'Cubicost 5D BIM – Giải pháp đột phá nâng cao hiệu suất xây dựng tại Singapore Institute of Technology', 'cubicost-5d-bim-–-giai-phap-dot-pha-nang-cao-hieu-suat-xay-dung-tai-singapore-institute-of-technology', NULL, NULL, 'Cubicost 5D BIM – Giải pháp đột phá nâng cao hiệu suất xây dựng tại Singapore Institute of Technolog', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1356, 'vi', 'Sau 1 năm thử nghiệm trên phiên bản Beta, Hãng phần mềm Pytha 3D CAD chính thức phát hành phiên bản V26 của phần mềm PYTHA.', 'Tin chuyên ngành', 'Pytha 3D CAD phát hành chính thức phiên bản V26', 'pytha-3d-cad-phat-hanh-chinh-thuc-phien-ban-v26', NULL, NULL, 'Pytha 3D CAD phát hành chính thức phiên bản V26', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1357, 'vi', 'Trong bối cảnh ngành thiết kế và xây dựng ngày càng đòi hỏi sự chính xác và hiệu quả, enjiCAD nổi lên như một giải pháp phần mềm CAD mạnh mẽ, giúp tối ưu hóa quy trình làm việc và nâng cao năng suất. Bài viết này chúng tôi sẽ hướng dẫn các bạn khắc phục lỗi file .dll is missing trên Windows.', 'Tin chuyên ngành', 'Hướng dẫn khắc phục lỗi file .dll is missing trên Windows (áp dụng cho enjiCAD)', 'huong-dan-khac-phuc-loi-file-dll-is-missing-tren-windows-ap-dung-cho-enjicad', NULL, NULL, 'Hướng dẫn khắc phục lỗi file .dll is missing trên Windows (áp dụng cho enjiCAD)', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1358, 'vi', 'SAP2000 là phần mềm phân tích kết cấu nổi tiếng của Hãng CSI (Mỹ), phát triển dựa trên phương pháp phần tử hữu hạn. Người dùng có thể sử dụng SAP2000 để mô phỏng và phân tích tải trọng sóng trên các cấu trúc ngoài khơi. Hãy cùng chúng ta cùng tìm hiểu trong bài viết dưới đây.', 'Tin chuyên ngành', 'Tính Toán Công Trình Biển Với Tải Trọng Sóng Trong Phần Mềm SAP2000', 'tinh-toan-cong-trinh-bien-voi-tai-trong-song-trong-phan-mem-sap2000', NULL, NULL, 'Tính Toán Công Trình Biển Với Tải Trọng Sóng Trong Phần Mềm SAP2000', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1359, 'vi', 'FIFISH V-EVO của hãng QYSEA là robot lặn tiên tiến, ứng dụng công nghệ ROV (robot điều khiển từ xa) hiện đại bậc nhất, mang đến hiệu suất vượt trội trong khảo sát và nghiên cứu dưới nước. Là đơn vị phân phối chính thức của QYSEA, Công ty CIC vừa hoàn thành bàn giao thiết bị này cho khách hàng, giúp họ tiếp cận những giải pháp công nghệ tối ưu và nâng cao hiệu quả công việc.', 'Tin công ty', 'CIC hoàn thành bàn giao Robot lặn FIFISH V-EVO: Giải pháp công nghệ ROV hiện đại', 'cic-hoan-thanh-ban-giao-robot-lan-fifish-v-evo:-giai-phap-cong-nghe-rov-hien-dai', NULL, NULL, 'CIC hoàn thành bàn giao Robot lặn FIFISH V-EVO: Giải pháp công nghệ ROV hiện đại', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1360, 'vi', 'Để người dùng luôn được trải nghiệm những tính năng ưu việt và sự hỗ trợ tốt nhất, CSI thông báo về việc kết thúc hỗ trợ (EOS) / kết thúc vòng đời (EOL) cho một số phiên bản phần mềm. Bài viết này sẽ cung cấp thông tin chi tiết về chính sách hỗ trợ, cập nhật phiên bản, danh sách các phiên bản bị ảnh hưởng, cũng như những thay đổi quan trọng về giấy phép, đặc biệt là việc ngừng hỗ trợ khóa USB. Hãy cùng tìm hiểu để đảm bảo phần mềm của bạn luôn được cập nhật và hỗ trợ tốt nhất.', 'Tin chuyên ngành', 'Thông Báo Kết Thúc Hỗ Trợ (Eos) / Kết Thúc Vòng Đời (Eol) Các Phần Mềm CSI', 'thong-bao-ket-thuc-ho-tro-eosket-thuc-vong-doi-eol-cac-phan-mem-csi', NULL, NULL, 'Thông Báo Kết Thúc Hỗ Trợ (Eos) / Kết Thúc Vòng Đời (Eol) Các Phần Mềm CSI', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1361, 'vi', 'Với  phần mềm PTV Visum phiên bản 2025, các nhà quản lý giao thông có thể dễ dàng nhập, phân tích và tận dụng dữ liệu lưu lượng hành khách để tối ưu hóa hệ thống giao thông công cộng. Hãy cùng Công ty CIC khám phá cách phần mềm này hoạt động và tác động của nó đến tương lai di chuyển đô thị như thế nào nhé!', 'Tin chuyên ngành', 'Tối Ưu Giao Thông Công Cộng với PTV Visum 2025: Sức Mạnh của Dữ Liệu Hành Khách', 'toi-uu-giao-thong-cong-cong-voi-ptv-visum-2025:-suc-manh-cua-du-lieu-hanh-khach', NULL, NULL, 'Tối Ưu Giao Thông Công Cộng với PTV Visum 2025: Sức Mạnh của Dữ Liệu Hành Khách', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1362, 'vi', 'Trong bối cảnh ngành hàng không toàn cầu đang nỗ lực chuyển đổi số, Sân bay Quốc tế Vancouver (YVR) đã tiên phong ứng dụng công nghệ Digital Twin, tạo ra một bản sao kỹ thuật số sống động của toàn bộ hoạt động sân bay. Sự hợp tác giữa YVR và Unity, "ông lớn" trong lĩnh vực nền tảng 3D thời gian thực, đã mở ra kỷ nguyên mới cho việc tối ưu hóa hiệu suất vận hành và nâng cao trải nghiệm khách hàng tại sân bay.', 'Tin chuyên ngành', 'Công nghệ Digital Twin – Bước đột phá giúp Sân bay Quốc tế Vancouver nâng cao hiệu suất và trải nghiệm khách hàng', 'cong-nghe-digital-twin-–-buoc-dot-pha-giup-san-bay-quoc-te-vancouver-nang-cao-hieu-suat-va-trai-nghiem-khach-hang', NULL, NULL, 'Công nghệ Digital Twin – Bước đột phá giúp Sân bay Quốc tế Vancouver nâng cao hiệu suất và trải nghi', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1363, 'vi', 'Việc điều tra, đánh giá tài nguyên khoáng sản đất hiếm ngày càng đòi hỏi phương pháp tiên tiến nhằm nâng cao độ chính xác và hiệu quả. Trong đó, công nghệ GeoAI—ứng dụng trí tuệ nhân tạo (AI) vào phân tích dữ liệu địa chất—được khuyến khích áp dụng nhằm tối ưu hóa quá trình thu thập, xử lý và đánh giá thông tin.', 'Tin chuyên ngành', 'Ứng dụng công nghệ GeoAI trong đánh giá khoáng sản đất hiếm', 'ung-dung-cong-nghe-geoai-trong-danh-gia-khoang-san-dat-hiem', NULL, NULL, 'Ứng dụng công nghệ GeoAI trong đánh giá khoáng sản đất hiếm', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1364, 'vi', 'Bài viết này sẽ tập trung vào cách Leapfrog Geo đã giúp khách hàng trực quan hóa, nội suy và diễn giải dữ liệu địa vật lý, bao gồm Phân cực cảm ứng (IP), từ kế và chụp cắt lớp địa chấn trong không gian 3D. Điều này giúp hiểu rõ hơn về cấu trúc dưới bề mặt, xác định mục tiêu thăm dò và lập kế hoạch khoan thăm dò.', 'Tin chuyên ngành', 'Tích hợp các phương pháp địa vật lý và sử dụng Leapfrog Geo để xác định ranh giới thăm dò, mô hình địa chất, khoảng sản tại một mỏ vùng Atacama, Chile', 'tich-hop-cac-phuong-phap-dia-vat-ly-va-su-dung-leapfrog-geo-de-xac-dinh-ranh-gioi-tham-do-mo-hinh-dia-chat-khoang-san-tai-mot-mo-vung-atacama-chile', NULL, NULL, 'Tích hợp các phương pháp địa vật lý và sử dụng Leapfrog Geo để xác định ranh giới thăm dò, mô hình đ', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1365, 'vi', 'Với giao diện trực quan và dễ sử dụng, AutoCAD Web là lựa chọn lý tưởng cho những người cần xem và chỉnh sửa nhanh các bản vẽ DWG.', 'Tin chuyên ngành', 'AutoCAD Web: Giải pháp CAD WEB mang xu thế tương lai?', 'autocad-web:-giai-phap-cad-web-mang-xu-the-tuong-lai', NULL, NULL, 'AutoCAD Web: Giải pháp CAD WEB mang xu thế tương lai?', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1366, 'vi', 'CFS (Cold-Formed Steel) là một phần mềm chuyên dụng để thiết kế và phân tích kết cấu thép tạo hình nguội, thực hiện tính toán theo Tiêu chuẩn Mỹ AISI S100 về Thiết kế Kết cấu thép tạo hình nguội và Tiêu chuẩn ASCE 8-22 về Thiết kế kết cấu thép không gỉ tạo hình nguội.', 'Tin chuyên ngành', 'Thiết Kế Và Phân Tích Cấu Kiện Thép Tạo Hình Nguội Với Phần Mềm CFS', 'thiet-ke-va-phan-tich-cau-kien-thep-tao-hinh-nguoi-voi-phan-mem-cfs', NULL, NULL, 'Thiết Kế Và Phân Tích Cấu Kiện Thép Tạo Hình Nguội Với Phần Mềm Cfs', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1367, 'vi', 'Digital twins toàn cầu dự kiến sẽ tăng trưởng từ 17,73 tỷ USD vào năm 2024 lên 259,32 tỷ USD vào năm 2032 cho thấy tiềm năng to lớn và sự quan tâm ngày càng tăng đối với công nghệ này trong ngành năng lượng.', 'Tin chuyên ngành', 'Khám phá 5 sức mạnh của Digital Twins cho các công ty năng lượng', 'kham-pha-5-suc-manh-cua-digital-twins-cho-cac-cong-ty-nang-luong', NULL, NULL, 'Khám phá 5 sức mạnh của Digital Twins cho các công ty năng lượng', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1368, 'vi', 'Trong bối cảnh công nghiệp 4.0 và xu hướng số hóa ngày càng mạnh mẽ, việc quản lý, khai thác hiệu quả dữ liệu 3D không chỉ giúp tối ưu hóa chi phí và vận hành, mà còn góp phần đáng kể vào mục tiêu phát triển bền vững và giảm phát thải cho doanh nghiệp, hướng tới net zero.', 'Tin chuyên ngành', 'Cintoo Cloud: Giải pháp quản lý và khai thác dữ liệu 3D bền vững cho ngành năng lượng và các ngành công nghiệp khác', 'cintoo-cloud:-giai-phap-quan-ly-va-khai-thac-du-lieu-3d-ben-vung-cho-nganh-nang-luong-va-cac-nganh-cong-nghiep-khac', NULL, NULL, 'Cintoo Cloud: Giải pháp quản lý và khai thác dữ liệu 3D bền vững cho ngành năng lượng và các ngành c', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1369, 'vi', 'Chuyên gia đến từ Công ty CHC Navigation (Trung Quốc) đã có buổi giới thiệu và đào tạo chuyên sâu về công nghệ máy quét cầm tay SLAM cùng các phần mềm hỗ trợ dựng mô hình tại Công ty cổ phần Công nghệ và Tư vấn CIC.', 'Tin công ty', 'CHC Navigation Đào Tạo Sử Dụng Máy Quét Cầm Tay Slam Để Quét Và Xây Dựng Bản Đồ 3D Cho CIC', 'chc-navigation-dao-tao-su-dung-may-quet-cam-tay-slam-de-quet-va-xay-dung-ban-do-3d-cho-cic', NULL, NULL, 'CHC Navigation Đào Tạo Sử Dụng Máy Quét Cầm Tay Slam Để Quét Và Xây Dựng Bản Đồ 3D Cho CIC', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1370, 'vi', 'AutoCAD Web là một giải pháp được Autodesk cho ra mắt từ năm 2022, là một giải pháp CAD trên nền tảng web rất tiện lợi và mang xu thế tương lai. AutoCAD Web giúp người dung xử lý các định dạng CAD như file DWG một cách nhanh chóng mà không cần cài bất cứ ứng dụng nào. Cùng chúng tôi điểm qua một số đặc điểm nổi bật về AutoCAD Web dưới đây.', 'Tin chuyên ngành', '20 điều có thể bạn chưa biết về AutoCAD Web ', '20-dieu-co-the-ban-chua-biet-ve-autocad-web', NULL, NULL, '20 điều có thể bạn chưa biết về AutoCAD Web', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1408, 'vi', 'Ngày 26/4/2025, Công ty Cổ phần Công nghệ và Tư vấn CIC trang trọng tổ chức Đại hội đồng cổ đông thường niên năm 2025 nhằm tổng kết hoạt động sản xuất kinh doanh năm 2024 và đề ra phương hướng, kế hoạch sản xuất kinh doanh năm 2025.', 'Tin công ty', 'CIC tổ chức Đại hội đồng cổ đông thường niên năm 2025', 'cic-to-chuc-dai-hoi-dong-co-dong-thuong-nien-nam-2025', NULL, NULL, 'CIC tổ chức Đại hội đồng cổ đông thường niên năm 2025', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1371, 'vi', 'BIM (Building Information Modeling) là tiến trình tạo dựng và sử dụng mô hình kỹ thuật số cho công việc thiết kế, thi công và cả quá trình quản lý vận hành, bảo trì công trình. Có 12 thuật ngữ BIM cần thiết trong xây dựng là chìa khóa quan trọng trong quá trình chuyển đổi số hiện nay.', 'Tin chuyên ngành', '12 thuật ngữ BIM quan trọng trong xây dựng bạn cần biết', '12-thuat-ngu-bim-quan-trong-trong-xay-dung-ban-can-biet', NULL, NULL, '12 thuật ngữ BIM quan trọng trong xây dựng bạn cần biết', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1372, 'vi', 'Mới đây, Công ty cổ phần Công nghệ và Tư vấn CIC phối hợp cùng Sở Xây dựng tỉnh Điện Biên tổ chức chương trình tập huấn &quot;Áp dụng mô hình thông tin công trình (BIM) trong hoạt động xây dựng theo Nghị định số 175/2024/NĐ-CP.', 'Tin công ty', 'Sở Xây dựng Điện Biên và Công ty CIC tổ chức tập huấn Áp dụng BIM trong hoạt động xây dựng theo Nghị định số 175/2024/NĐ-CP', 'so-xay-dung-dien-bien-va-cong-ty-cic-to-chuc-tap-huan-ap-dung-bim-trong-hoat-dong-xay-dung-theo-nghi-dinh-so-1752024nd-cp', NULL, NULL, 'Sở Xây dựng Điện Biên và Công ty CIC tổ chức tập huấn Áp dụng BIM trong hoạt động xây dựng theo Nghị', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1373, 'vi', 'AutoCAD 2026 cải thiện tốc độ mở tệp và khởi động, cùng với các khả năng sáng tạo giúp tiết kiệm thời gian với mọi tệp DWG, mở khóa thông tin chi tiết, tự động hóa với sự trợ giúp của Autodesk AI cùng nhiều tính năng mới khác cải thiện hiệu suất làm việc.', 'Tin chuyên ngành', 'AutoCAD 2026 có gì mới', 'autocad-2026-co-gi-moi', NULL, NULL, 'AutoCAD 2026 có gì mới', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1374, 'vi', 'Công ty CIC triển khai dịch vụ tư vấn kiểm kê khí nhà kính cấp cơ sở cho Xi Măng Cẩm Phả (Quảng Ninh), từ đó giúp các doanh nghiệp ngành xi măng thực hiện trách nhiệm bảo vệ môi trường.', 'Tin công ty', 'CIC cung cấp dịch vụ tư vấn kiểm kê khí nhà kính cấp cơ sở cho Xi măng Cẩm Phả', 'cic-cung-cap-dich-vu-tu-van-kiem-ke-khi-nha-kinh-cap-co-so-cho-xi-mang-cam-pha', NULL, NULL, 'CIC cung cấp dịch vụ tư vấn kiểm kê khí nhà kính cấp cơ sở cho Xi măng Cẩm Phả', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1375, 'vi', 'Có tới 97% lãnh đạo doanh nghiệp tin rằng AI sẽ làm thay đổi mô hình kinh doanh cốt lõi trong vòng hai năm tới, theo nghiên cứu từ Endava vừa công bố mới đây.', 'Tin chuyên ngành', 'AI - Đòn bẩy chiến lược cho doanh nghiệp trong kỷ nguyên số', 'ai-don-bay-chien-luoc-cho-doanh-nghiep-trong-ky-nguyen-so', NULL, NULL, 'AI - Đòn bẩy chiến lược cho doanh nghiệp trong kỷ nguyên số', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1376, 'vi', 'Ngành vận tải biển từ lâu đã là động lực của tăng trưởng kinh tế toàn cầu, đóng vai trò như “xương sống” của thương mại quốc tế.  Tuy nhiên, ngành này đang chịu áp lực lớn trước mục tiêu NetZero trong bối cảnh biến đổi khí hậu và yêu cầu phát triển bền vững. ', 'Tin chuyên ngành', 'Vận tải biển: Động lực tăng trưởng kinh tế toàn cầu trên hành trình hướng tới mục tiêu net zero', 'van-tai-bien:-dong-luc-tang-truong-kinh-te-toan-cau-tren-hanh-trinh-huong-toi-muc-tieu-net-zero', NULL, NULL, 'Vận tải biển: Động lực tăng trưởng kinh tế toàn cầu trên hành trình hướng tới mục tiêu net zero', '') ON CONFLICT (entity_id, locale) DO NOTHING;
