INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1399, 'vi', '“Chuyển đổi xanh là con đường bắt buộc để hiện thực hóa mục tiêu phát thải ròng bằng 0 vào năm 2050 của Việt Nam”.', 'Tin công ty', 'Chuyển đổi xanh không còn là lựa chọn mà là yêu cầu tất yếu', 'chuyen-doi-xanh-khong-con-la-lua-chon-ma-la-yeu-cau-tat-yeu', NULL, NULL, 'Chuyển đổi xanh không còn là lựa chọn mà là yêu cầu tất yếu', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1400, 'vi', 'Ngày 15/4/2025, Sở Xây dựng Thái Nguyên kết hợp với Công ty CP Công nghệ và Tư vấn CIC tổ chức khai mạc Lớp đào tạo nâng cao về mô hình thông tin công trình (BIM) trong hoạt động xây dựng cho 120 học viên là cán bộ, công chức, viên chức, đại diện các chủ đầu tư và ban quản lý dự án trên địa bàn tỉnh.', 'Tin công ty', 'Sở Xây dựng Thái Nguyên và CIC tổ chức tập huấn Áp dụng BIM trong hoạt động xây dựng theo Nghị định số 175/2024/NĐ-CP', 'so-xay-dung-thai-nguyen-va-cic-to-chuc-tap-huan-ap-dung-bim-trong-hoat-dong-xay-dung-theo-nghi-dinh-so-1752024nd-cp', NULL, NULL, 'Sở Xây dựng Thái Nguyên và CIC tổ chức tập huấn Áp dụng BIM trong hoạt động xây dựng theo Nghị định', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1401, 'vi', 'Việc phối hợp hiệu quả giữa các bộ phận chức năng và chiến lược số hóa đã giúp tối ưu hóa quá trình triển khai siêu dự án trị giá 11 tỷ đô la Úc (AUD). Dự án này được kỳ vọng sẽ rút ngắn thời gian di chuyển, giảm thiểu ô nhiễm và nâng cao hiệu quả hoạt động cho cả người dân lẫn doanh nghiệp.', 'Tin chuyên ngành', 'Tối ưu hóa dự án hạ tầng bằng Leapfrog Works, PLAXIS và ProjectWise: Câu chuyện thành công từ North East Link', 'toi-uu-hoa-du-an-ha-tang-bang-leapfrog-works-plaxis-va-projectwise:-cau-chuyen-thanh-cong-tu-north-east-link', NULL, NULL, 'Tối ưu hóa dự án hạ tầng bằng Leapfrog Works, PLAXIS và ProjectWise: Câu chuyện thành công từ North', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1403, 'vi', 'Tìm hiểu “Lisp là gì?” và lý do vì sao Lisp CAD vẫn là công cụ không thể thiếu trong thiết kế kỹ thuật. Khám phá thư viện lisp CAD miễn phí dành riêng cho phần mềm enjiCAD – phần mềm CAD do CIC phát triển với hiệu năng vượt trội.', 'Tin chuyên ngành', 'Lisp là gì? Khám phá Lisp CAD trong enjiCAD- Tải ngay thư viện LISP miễn phí', 'lisp-la-gi-kham-pha-lisp-cad-trong-enjicadtai-ngay-thu-vien-lisp-mien-phi', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1404, 'vi', 'Nhằm phục vụ công tác đào tạo và nghiên cứu chuyên sâu trong lĩnh vực địa chất – địa kỹ thuật, Công ty Cổ phần Công nghệ và Tư vấn CIC vừa hoàn tất việc bàn giao bộ thiết bị địa chấn hố khoan của hãng Geotomographie GmbH (Đức) cho Trường Đại học Bách Khoa – Đại học Quốc gia TP. Hồ Chí Minh.', 'Tin công ty', 'CIC Cung Cấp Thiết Bị Địa Chấn Hố Khoan Của Hãng Geotomographie (Đức) Cho Trường Đại Học Bách Khoa Tp. Hồ Chí Minh', 'cic-cung-cap-thiet-bi-dia-chan-ho-khoan-cua-hang-geotomographie-duc-cho-truong-dai-hoc-bach-khoa-tp-ho-chi-minh', NULL, NULL, 'CIC Cung Cấp Thiết Bị Địa Chấn Hố Khoan Của Hãng Geotomographie (Đức) Cho Trường Đại Học Bách Khoa T', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1405, 'vi', 'Nhằm nâng cao năng lực giảng dạy, nghiên cứu và mô phỏng các vấn đề phức tạp trong địa kỹ thuật và cơ học đất, Công ty Cổ phần Công nghệ và Tư vấn CIC đã bàn giao thành công các phần mềm chuyên dụng PLAXIS 3D WorkSuite của hãng Bentley Systems và GeoStudio (Slope/W, Seep/W) của hãng Seequent (New Zealand) cho Trường Đại học Bách Khoa – Đại học Quốc gia TP. Hồ Chí Minh.', 'Tin công ty', 'CIC Cung Cấp Phần Mềm Mô Phỏng Địa Kỹ Thuật Plaxis 3D Worksuite Và Geostudio Cho Trường Đại Học Bách Khoa Tp. Hồ Chí Minh', 'cic-cung-cap-phan-mem-mo-phong-dia-ky-thuat-plaxis-3d-worksuite-va-geostudio-cho-truong-dai-hoc-bach-khoa-tp-ho-chi-minh', NULL, NULL, 'CIC Cung Cấp Phần Mềm Mô Phỏng Địa Kỹ Thuật Plaxis 3D Worksuite Và Geostudio Cho Trường Đại Học Bách', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1407, 'vi', 'Mới đây, Công ty Cổ phần Công nghệ và Tư vấn CIC phối hợp cùng Trường Đại học Giao thông Vận tải (ĐH GTVT) đã tổ chức hội thảo giới thiệu về các phần mềm giao thông của hãng PTV Group (Đức), bao gồm PTV VISSIM, PTV VISUM và PTV VISWALK Sở Giao thông Vận tải TP. Huế.', 'Tin công ty', 'CIC kết hợp cùng ĐH GTVT tổ chức hội thảo giới thiệu phần mềm giao thông của PTV Group cho Sở GTVT TP. Huế', 'cic-ket-hop-cung-dh-gtvt-to-chuc-hoi-thao-gioi-thieu-phan-mem-giao-thong-cua-ptv-group-cho-so-gtvt-tp-hue', NULL, NULL, 'CIC kết hợp cùng ĐH GTVT tổ chức hội thảo giới thiệu phần mềm giao thông của PTV Group cho Sở GTVT T', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1409, 'vi', 'Erdenet Mining Corp đã chuyển đổi số thành công hoạt động khai khoáng quy mô lớn nhờ ứng dụng giải pháp Seequent, tối ưu hóa quản lý tài nguyên và nâng cao hiệu quả sản xuất.', 'Tin chuyên ngành', 'Erdenet Mining Corp: Tiên phong chuyển đổi số ngành khai khoáng với giải pháp Seequent', 'erdenet-mining-corp:-tien-phong-chuyen-doi-so-nganh-khai-khoang-voi-giai-phap-seequent', NULL, NULL, 'Erdenet Mining Corp: Tiên phong chuyển đổi số ngành khai khoáng với giải pháp Seequent', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1410, 'vi', 'Trong bối cảnh thế giới chuyển mình sang tương lai phi carbon, Indonesia – quốc gia đứng đầu về trữ lượng và sản lượng niken – đang nắm giữ chìa khóa của cuộc cách mạng năng lượng mới.INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1411, 'vi', '', 'Quan hệ cổ đông', 'Nghị quyết Đại hội đồng cổ đông năm 2025', 'nghi-quyet-dai-hoi-dong-co-dong-nam-2025', NULL, NULL, 'Nghị quyết Đại hội đồng cổ đông năm 2025', '') ON CONFLICT (entity_id, locale) DO NOTHING;
