INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1413, 'vi', 'Trong môi trường công nghiệp hiện đại, việc phát hiện sớm sự cố máy móc không chỉ giúp tăng hiệu suất mà còn đảm bảo an toàn cho con người. Một trong những công nghệ mới nổi bật là camera âm thanh (acoustic camera) – thiết bị có khả năng “nghe” và xác định chính xác nguồn âm thanh bất thường để hỗ trợ kiểm tra, bảo trì thiết bị một cách nhanh chóng và chính xác hơn.', 'Tin chuyên ngành', 'Đột Phá Trong Giám Sát An Toàn: Ứng Dụng Camera Âm Thanh Cho Nhà Máy và Khu Công Nghiệp', 'dot-pha-trong-giam-sat-an-toan:-ung-dung-camera-am-thanh-cho-nha-may-va-khu-cong-nghiep', NULL, NULL, 'Đột Phá Trong Giám Sát An Toàn: Ứng Dụng Camera Âm Thanh Cho Nhà Máy và Khu Công Nghiệp', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1415, 'vi', 'Công ty CIC xin trân trọng Thông báo về việc điều chỉnh giá bán sản phẩm đối với phần mềm Opera Job Management.', 'Tin công ty', 'Thông báo về việc điều chỉnh giá bán sản phẩm đối với phần mềm Opera Job Management', 'thong-bao-ve-viec-dieu-chinh-gia-ban-san-pham-doi-voi-phan-mem-opera-job-management', NULL, NULL, 'Thông báo về việc điều chỉnh giá bán sản phẩm đối với phần mềm Opera Job Management', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1414, 'vi', 'Cập nhật mới nhất quý I/2025 về quy định thị trường carbon toàn cầu: Việt Nam ra mắt thị trường carbon quốc gia, nhiều quốc gia như Pakistan, Uganda, Nam Phi ban hành khung pháp lý mới, cùng sự gia tăng hợp tác song phương theo Điều 6 Thỏa thuận Paris. Theo dõi diễn biến quan trọng trong bài viết dưới đây.', 'Tin chuyên ngành', 'Cập nhật tình hình phát triển của các thị trường Carbon trên thế giới trong Quý 1 năm 2025', 'cap-nhat-tinh-hinh-phat-trien-cua-cac-thi-truong-carbon-tren-the-gioi-trong-quy-1-nam-2025', NULL, NULL, 'Cập nhật tình hình phát triển của các thị trường Carbon trên thế giới trong Quý 1 năm 2025', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1416, 'vi', 'Mới đây, Công ty Cổ phần Công nghệ và Tư vấn CIC, đại diện chính thức của hãng phần mềm Heat Transfer Research, Inc. (HTRI) tại Việt Nam, đã phối hợp tổ chức buổi giới thiệu và trình diễn phần mềm Smart PM cho Công ty Cổ phần Lọc – Hóa dầu Bình Sơn (BSR).', 'Tin công ty', 'CIC Phối Hợp Cùng Hãng HTRI Giới Thiệu Và Demo Phần Mềm Smart PM Tại Công Ty Lọc Hóa Dầu Bình Sơn (BSR)', 'cic-phoi-hop-cung-hang-htri-gioi-thieu-va-demo-phan-mem-smart-pm-tai-cong-ty-loc-hoa-dau-binh-son-bsr', NULL, NULL, 'CIC Phối Hợp Cùng Hãng HTRI Giới Thiệu Và Demo Phần Mềm Smart PM Tại Công Ty Lọc Hóa Dầu Bình Sơn (B', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1417, 'vi', 'Công ty CIC được lựa chọn là đơn vị tư vấn cung cấp dịch vụ kiểm kê khí nhà kính cấp cơ sở cho Công ty CP Xi măng Bỉm Sơn – Chi nhánh Quảng Trị.', 'Tin công ty', 'CIC triển khai dịch vụ tư vấn kiểm kê khí nhà kính cấp cơ sở cho Công ty Xi măng Bỉm Sơn – Chi nhánh Quảng Trị', 'cic-trien-khai-dich-vu-tu-van-kiem-ke-khi-nha-kinh-cap-co-so-cho-cong-ty-xi-mang-bim-son-–-chi-nhanh-quang-tri', NULL, NULL, 'CIC triển khai dịch vụ tư vấn kiểm kê khí nhà kính cấp cơ sở cho Công ty Xi măng Bỉm Sơn – Chi nhánh', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1418, 'vi', 'Phiên bản mới nhất – IDEA StatiCa v25 – ra mắt với nhiều cải tiến vượt trội, tập trung vào khả năng tự động hóa quy trình thiết kế kết cấu thép, mô hình hóa các liên kết phức tạp, và đặc biệt là phân tích điều kiện làm việc của liên kết trong môi trường chịu lửa.', 'Tin chuyên ngành', '[CẬP NHẬT VERSION MỚI] IDEA StatiCa v25: Tăng Tốc Thiết Kế Kết Cấu, Đáp Ứng Chuẩn Toàn Cầu', '[cap-nhat-version-moi]-idea-statica-v25:-tang-toc-thiet-ke-ket-cau-dap-ung-chuan-toan-cau', NULL, NULL, '[CẬP NHẬT VERSION MỚI] IDEA StatiCa v25: Tăng Tốc Thiết Kế Kết Cấu, Đáp Ứng Chuẩn Toàn Cầu', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1421, 'vi', 'Ứng dụng DME trong phát triển Advanced Air Mobility (AAM): Tìm hiểu cách phần mềm Digital Mission Engineering (DME) như Ansys STK được sử dụng để mô hình hóa thiết kế máy bay, quản lý không phận, tích hợp cộng đồng và đảm bảo hoạt động AAM an toàn, hiệu quả.', 'Tin chuyên ngành', 'Tính cơ động trên không tiên tiến: Sử dụng DME để hiểu những thách thức phức tạp của nhiệm vụ', 'tinh-co-dong-tren-khong-tien-tien:-su-dung-dme-de-hieu-nhung-thach-thuc-phuc-tap-cua-nhiem-vu', NULL, NULL, 'Tính cơ động trên không tiên tiến: Sử dụng DME để hiểu những thách thức phức tạp của nhiệm vụ', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1419, 'vi', 'Sự kiện BIM UP Vietnam 2025 – Kiến tạo tương lai số bóc tách khối lượng, BIM 5D bứt phá cùng AI sẽ được tổ chức vào ngày 20 tháng 5 năm 2025.', 'Tin công ty', '[Sự kiện sắp diễn ra]BIM UP Vietnam 2025 – Kiến tạo tương lai số bóc tách khối lượng, BIM 5D bứt phá cùng AI', '[su-kien-sap-dien-ra]bim-up-vietnam-2025-–-kien-tao-tuong-lai-so-boc-tach-khoi-luong-bim-5d-but-pha-cung-ai', NULL, NULL, '[Sự kiện sắp diễn ra]BIM UP Vietnam 2025 – Kiến tạo tương lai số bóc tách khối lượng, BIM 5D bứt phá', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1420, 'vi', 'Trên phần mềm enjiCAD, người dùng có thể dễ dàng thay đổi hiển thị của các tính năng có trên thanh ribbon. Các thành phần có thể thay đổi gồm tên hiển thị, hình ảnh icon, description của lệnh khi ta trỏ chuột vào… Cách thao tác cũng rất dễ dàng có thể làm trực tiếp. Chi tiết về các bước thực hiện, mời các bạn đọc bài viết dưới đây.', 'Tin chuyên ngành', 'enjiCAD Tips: Cách thay đổi tên hiển thị của lệnh trên thanh Ribbon vô cùng đơn giản', 'enjicad-tips:-cach-thay-doi-ten-hien-thi-cua-lenh-tren-thanh-ribbon-vo-cung-don-gian', NULL, NULL, 'enjiCAD Tips: Cách thay đổi tên hiển thị của lệnh trên thanh Ribbon vô cùng đơn giản', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1422, 'vi', 'Khám phá cách AI không chỉ tạo ra ROI mà còn mở khóa giá trị bền vững cho doanh nghiệp qua góc nhìn của Vijay Guntur – CTO HCLTech.', 'Tin chuyên ngành', 'Khai mở tiềm năng doanh nghiệp bằng AI – Góc nhìn từ HCLTech', 'khai-mo-tiem-nang-doanh-nghiep-bang-ai-–-goc-nhin-tu-hcltech', NULL, NULL, 'Khai mở tiềm năng doanh nghiệp bằng AI – Góc nhìn từ HCLTech', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1423, 'vi', 'BIMCollab ZOOM – Giải pháp thẩm tra, thẩm định mô hình BIM hàng đầu, tối ưu kiểm tra xung đột, nâng cao hiệu quả dự án, được phân phối bởi Công ty CIC.', 'Tin chuyên ngành', 'BIMcollab Zoom: Giải pháp kiểm tra và thẩm định mô hình BIM chuyên sâu cho Cơ quan quản lý và Chủ đầu tư', 'bimcollab-zoom:-giai-phap-kiem-tra-va-tham-dinh-mo-hinh-bim-chuyen-sau-cho-co-quan-quan-ly-va-chu-dau-tu', NULL, NULL, 'BIMcollab Zoom: Giải pháp kiểm tra và thẩm định mô hình BIM chuyên sâu cho Cơ quan quản lý và Chủ đầ', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1424, 'vi', 'TP. Hồ Chí Minh, ngày 22/5/2025 – 140 chuyên gia và đại diện doanh nghiệp trong lĩnh vực giao thông, hạ tầng, đường sắt và công trình ngầm đã cùng quy tụ tại hội thảo Bentley Technology Day 2025, do Công ty CP Công nghệ & Tư vấn CIC phối hợp với Bentley Systems tổ chức. Sự kiện là một điểm nhấn quan trọng trong hành trình chuyển đổi số ngành xây dựng và hạ tầng Việt Nam.', 'Tin công ty', 'CIC tổ chức thành công hội thảo Chuyên đề: Giải pháp số của Bentley cho ngành Đường Sắt, Hạ Tầng và Công Trình Ngầm- Nền tảng tích hợp từ Thiết kế đến vận hành', 'cic-to-chuc-thanh-cong-hoi-thao-chuyen-de:-giai-phap-so-cua-bentley-cho-nganh-duong-sat-ha-tang-va-cong-trinh-ngamnen-tang-tich-hop-tu-thiet-ke-den-van-hanh', NULL, NULL, 'Hội Thảo Bentley Technology Day 2025: Đột Phá Giải Pháp Số Cho Ngành Giao Thông – Hạ Tầng – Đường Sắ', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1425, 'vi', 'Vừa qua, đoàn công tác của Công ty Cổ phần Công nghệ và Tư vấn CIC đã có chuyến thăm và làm việc tại trụ sở chính của Hãng phần mềm Computer and Structures, Inc. (CSI) tại Hoa Kỳ – một trong những tên tuổi hàng đầu thế giới trong lĩnh vực phần mềm thiết kế kết cấu công trình. Đây không chỉ là dịp để tăng cường hợp tác giữa hai bên mà còn là cơ hội để CIC góp mặt trong sự kiện trọng đại – Lễ kỷ niệm 50 năm thành lập CSI.', 'Tin công ty', 'Đoàn CIC làm việc tại Hãng phần mềm CSI (Hoa Kỳ) và tham dự Lễ kỷ niệm 50 năm thành lập CSI', 'doan-cic-lam-viec-tai-hang-phan-mem-csi-hoa-ky-va-tham-du-le-ky-niem-50-nam-thanh-lap-csi', NULL, NULL, 'Đoàn CIC làm việc tại Hãng phần mềm CSI (Hoa Kỳ) và tham dự Lễ kỷ niệm 50 năm thành lập CSI', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1426, 'vi', 'Khám phá cách Generative AI, tự động hóa và các yếu tố kinh tế - xã hội đang định hình lại thị trường lao động Hoa Kỳ đến năm 2030. Bài viết dưới đây được tổng hợp từ báo cáo của McKinsey, cung cấp cái nhìn chuyên sâu về xu hướng nghề nghiệp, kỹ năng cần thiết và các nhóm lao động dễ bị ảnh hưởng.', 'Tin chuyên ngành', 'Tương lai việc làm tại Mỹ dưới tác động của Generative AI: Cơ hội và thách thức đến năm 2030', 'tuong-lai-viec-lam-tai-my-duoi-tac-dong-cua-generative-ai:-co-hoi-va-thach-thuc-den-nam-2030', NULL, NULL, 'Tương lai việc làm tại Mỹ dưới tác động của Generative AI: Cơ hội và thách thức đến năm 2030', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1427, 'vi', 'Tham gia ngay Khóa Đào Tạo Miễn Phí Tháng 6 Cùng Seequent – Cơ Hội Học & Trải Nghiệm Phần Mềm Hàng Đầu!', 'Tin chuyên ngành', 'Khóa Đào Tạo Miễn Phí Tháng 6 Cùng Seequent – Cơ Hội Học & Trải Nghiệm Phần Mềm Hàng Đầu!', 'khoa-dao-tao-mien-phi-thang-6-cung-seequent-–-co-hoi-hoc-amp;-trai-nghiem-phan-mem-hang-dau', NULL, NULL, 'Khóa Đào Tạo Miễn Phí Tháng 6 Cùng Seequent – Cơ Hội Học & Trải Nghiệm Phần Mềm Hàng Đầu!', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1428, 'vi', 'Tối ưu hóa quy trình BIM của bạn với enjiCAD 2025! Phần mềm cho phép nhập và xuất các tệp IFC, RVT dễ dàng, giúp kỹ sư và quản lý dự án khai thác tối đa dữ liệu BIM mà không cần phần mềm chuyên dụng khác.', 'Tin chuyên ngành', 'Khai thác sức mạnh BIM trong dự án với enjiCAD 2025: Import/Export IFC, RVT dễ dàng', 'khai-thac-suc-manh-bim-trong-du-an-voi-enjicad-2025:-importexport-ifc-rvt-de-dang', NULL, NULL, 'Khai thác sức mạnh BIM trong dự án với enjiCAD 2025: Import/Export IFC, RVT dễ dàng', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1430, 'vi', 'Công ty Cổ phần Công nghệ và Tư vấn CIC vui mừng thông báo đã hoàn thành việc bàn giao và đào tạo phần mềm VISUM (Standard Modeller) – giải pháp quy hoạch và mô hình hóa giao thông hàng đầu của hãng PTV Group (CHLB Đức) – cho Công ty CP Tư vấn Thiết kế và Kiểm định Công trình Xây dựng Quang Huy, một trong những đơn vị tư vấn giao thông – hạ tầng kỹ thuật uy tín tại Việt Nam.', 'Tin công ty', 'CIC Hoàn Thành Bàn Giao Và Đào Tạo Phần Mềm Quy Hoạch Giao Thông Visum Cho Tư Vấn Quang Huy', 'cic-hoan-thanh-ban-giao-va-dao-tao-phan-mem-quy-hoach-giao-thong-visum-cho-tu-van-quang-huy', NULL, NULL, 'CIC Hoàn Thành Bàn Giao Và Đào Tạo Phần Mềm Quy Hoạch Giao Thông Visum Cho Tư Vấn Quang Huy', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1431, 'vi', 'Ngày 30/05/2025 vừa qua, Công ty CIC và IDEA StatiCa tổ chức thành công webinar với chủ đề "Tự động hóa, tối ưu & tính toán chịu lửa cho liên kết kết cấu thép với IDEA StatiCa v25",  đã thu hút sự tham gia của đông đảo kỹ sư thiết kế, đặc biệt là kỹ sư kết cấu, quản lý kỹ thuật cùng các chuyên gia hàng đầu đến từ nhiều doanh nghiệp thuộc ngành xây dựng.', 'Tin công ty', 'CIC Tổ Chức Thành Công Hội Thảo Trực Tuyến: Tự động hóa, tối ưu & tính toán chịu lửa cho liên kết kết cấu thép với IDEA StatiCa v25', 'cic-to-chuc-thanh-cong-hoi-thao-truc-tuyen:-tu-dong-hoa-toi-uu-amp;-tinh-toan-chiu-lua-cho-lien-ket-ket-cau-thep-voi-idea-statica-v25', NULL, NULL, 'CIC Tổ Chức Thành Công Hội Thảo Trực Tuyến: Tự động hóa, tối ưu & tính toán chịu lửa cho liên kết kế', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1432, 'vi', 'Công ty CIC được lựa chọn là đơn vị tư vấn cung cấp dịch vụ kiểm kê khí nhà kính cấp cơ sở cho Công ty CP Xi măng Bỉm Sơn.', 'Tin công ty', 'CIC triển khai dịch vụ tư vấn kiểm kê khí nhà kính cấp cơ sở cho Công ty Xi măng Bỉm Sơn', 'cic-trien-khai-dich-vu-tu-van-kiem-ke-khi-nha-kinh-cap-co-so-cho-cong-ty-xi-mang-bim-son', NULL, NULL, 'CIC triển khai dịch vụ tư vấn kiểm kê khí nhà kính cấp cơ sở cho Công ty Xi măng Bỉm Sơn', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1433, 'vi', 'Tham gia chương trình khuyến mại tháng 6 của IDEA StatiCa, quý khách hàng sẽ mua được phần mềm với chi phí hấp dẫn & tiết kiệm đáng kể  trước khi chính sách tăng giá có hiệu lực từ 01/07/2025.', 'Tin khuyến mại', 'Cơ hội sở hữu phiên bản mới nhất IDEA StatiCa V25 với ưu đãi độc quyền tháng 6', 'co-hoi-so-huu-phien-ban-moi-nhat-idea-statica-v25-voi-uu-dai-doc-quyen-thang-6', NULL, NULL, 'Cơ hội sở hữu phiên bản mới nhất IDEA StatiCa V25 với ưu đãi độc quyền tháng 6', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1434, 'vi', 'Khám phá các giải pháp xây dựng thành phố phát thải carbon thấp: từ quản trị chính sách đến công nghệ sáng tạo, kinh tế tuần hoàn và thay đổi lối sống. Bài học cho đô thị Việt Nam hướng tới Net Zero.', 'Tin chuyên ngành', 'Giải pháp xây dựng thành phố phát thải carbon thấp: Bài học kinh nghiệm từ các đô thị trên thế giới', 'giai-phap-xay-dung-thanh-pho-phat-thai-carbon-thap:-bai-hoc-kinh-nghiem-tu-cac-do-thi-tren-the-gioi', NULL, NULL, 'Giải pháp xây dựng thành phố phát thải carbon thấp: Bài học kinh nghiệm từ các đô thị trên thế giới', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1435, 'vi', 'Hội nghị ECO Platform 2025 tại Brussels đánh dấu bước ngoặt cho Tuyên bố Môi trường Sản phẩm (EPD) – công cụ minh bạch hóa dữ liệu môi trường. Khám phá cách EPD giúp doanh nghiệp tối ưu hóa sản xuất, nâng cao uy tín và bứt phá trong chiến lược bền vững', 'Tin chuyên ngành', 'Doanh Nghiệp Bứt Phá Với EPD: Hội Nghị ECO 2025 Brussels Định Hình Chuẩn Mực Mới Cho Sản Phẩm Xanh', 'doanh-nghiep-but-pha-voi-epd:-hoi-nghi-eco-2025-brussels-dinh-hinh-chuan-muc-moi-cho-san-pham-xanh', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1436, 'vi', 'Seequent ra mắt Leapfrog 2025.1 – phiên bản mới nhất dành cho ngành khai thác mỏ để mô hình hóa địa chất và ước tính tài nguyên nhanh hơn, thông minh hơn.', 'Tin chuyên ngành', 'Seequent ra mắt Leapfrog 2025.1 để mô hình hóa địa chất và ước tính tài nguyên nhanh hơn, thông minh hơn', 'seequent-ra-mat-leapfrog-20251-de-mo-hinh-hoa-dia-chat-va-uoc-tinh-tai-nguyen-nhanh-hon-thong-minh-hon', NULL, NULL, 'Seequent ra mắt Leapfrog 2025.1 để mô hình hóa địa chất và ước tính tài nguyên nhanh hơn, thông minh', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1437, 'vi', 'Khám phá những tính năng mới trong Oasis montaj 2025.1, bản cập nhật khẳng định lại cam kết của Seequent trong việc thúc đẩy nghiên cứu địa vật lý và cải thiện quy trình làm việc dữ liệu cho các nhà khoa học về địa chất làm việc trong các dự án thăm dò.', 'Tin chuyên ngành', 'Phiên bản cập nhật Oasis montaj 2025.1 Có gì mới', 'phien-ban-cap-nhat-oasis-montaj-20251-co-gi-moi', NULL, NULL, 'Phiên bản cập nhật Oasis montaj 2025.1 Có gì mới', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1438, 'vi', 'Công ty cổ phần Công nghệ và Tư vấn CIC được lựa chọn là đơn vị tư vấn cung cấp dịch vụ kiểm kê khí nhà kính cấp cơ sở cho Công ty Xi măng VICEM Hoàng Thạch.', 'Tin công ty', 'CIC triển khai dịch vụ tư vấn kiểm kê khí nhà kính cấp cơ sở cho Công ty Xi măng VICEM Hoàng Thạch', 'cic-trien-khai-dich-vu-tu-van-kiem-ke-khi-nha-kinh-cap-co-so-cho-cong-ty-xi-mang-vicem-hoang-thach', NULL, NULL, 'CIC triển khai dịch vụ tư vấn kiểm kê khí nhà kính cấp cơ sở cho Công ty Xi măng VICEM Hoàng Thạch', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1439, 'vi', 'Trong bối cảnh ngành năng lượng toàn cầu đang nỗ lực tối ưu hóa hiệu suất và đảm bảo an toàn, một nghiên cứu đột phá từ nhà sản xuất drone công nghiệp Flyability đã cho thấy công nghệ không người lái đang thực sự làm thay đổi cuộc chơi, giúp giảm thời gian bảo trì các hạng mục phức tạp trong nhà máy điện từ một tuần xuống chỉ còn vài giờ.', 'Tin chuyên ngành', 'Công nghệ drone tạo ra cuộc cách mạng trong bảo trì nhà máy điện', 'cong-nghe-drone-tao-ra-cuoc-cach-mang-trong-bao-tri-nha-may-dien', NULL, NULL, 'Công nghệ drone tạo ra cuộc cách mạng trong bảo trì nhà máy điện', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1440, 'vi', 'Chiều ngày 10/06/2025, Công ty Cổ phần Công nghệ và Tư vấn CIC (trực thuộc Bộ Xây dựng) đã tổ chức thành công hội thảo trực tuyến với chủ đề “Báo cáo LCA và Chứng nhận EPD: Nền tảng hướng tới sản xuất xanh và phát triển bền vững”. Sự kiện thu hút nhiều doanh nghiệp, chuyên gia trong và ngoài nước, nhấn mạnh vai trò của LCA và EPD trong bối cảnh yêu cầu minh bạch môi trường ngày càng tăng và cảnh báo nguy cơ “tẩy xanh” (greenwashing) trong ngành xây dựng.', 'Tin công ty', 'CIC tổ chức thành công webinar: Báo cáo LCA và Chứng nhận EPD: Nền tảng hướng tới sản xuất xanh và phát triển bền vững”', 'cic-to-chuc-thanh-cong-webinar:-bao-cao-lca-va-chung-nhan-epd:-nen-tang-huong-toi-san-xuat-xanh-va-phat-trien-ben-vung', NULL, NULL, 'CIC tổ chức thành công webinar: Báo cáo LCA và Chứng nhận EPD: Nền tảng hướng tới sản xuất xanh và p', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1441, 'vi', 'Chúng tôi tự hào giới thiệu PROKON 5.3 – bản cập nhật mới nhất mang đến những tính năng đột phá giúp bạn thiết kế và phân tích kết cấu hiệu quả hơn bao giờ hết.', 'Tin chuyên ngành', 'PROKON 5.3 Đã Ra Mắt: Nâng Tầm Thiết Kế và Hiệu Quả!', 'prokon-53-da-ra-mat:-nang-tam-thiet-ke-va-hieu-qua', NULL, NULL, 'PROKON 5.3 Đã Ra Mắt: Nâng Tầm Thiết Kế và Hiệu Quả!', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1442, 'vi', 'Chúng tôi hân hạnh thông báo về sự ra mắt của ETABS 22.6.0 bản cập nhật mới nhất mang đến hàng loạt cải tiến quan trọng, giúp các kỹ sư thiết kế và phân tích kết cấu hiệu quả hơn, chính xác hơn và tuân thủ các tiêu chuẩn mới nhất', 'Tin chuyên ngành', 'ETABS 22.6.0: Nâng Cấp Toàn Diện, Tối Ưu Hóa Thiết Kế Kết Cấu', 'etabs-2260:-nang-cap-toan-dien-toi-uu-hoa-thiet-ke-ket-cau', NULL, NULL, 'ETABS 22.6.0: Nâng Cấp Toàn Diện, Tối Ưu Hóa Thiết Kế Kết Cấu', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1443, 'vi', 'Ứng dụng mở và bản song sinh kỹ thuật số (Digital Twin) của Bentley giúp PT Wijaya Karya đẩy nhanh tiến độ thi công dự án đường sắt cao tốc Jakarta – Bandung, tiết kiệm 185 triệu USD và rút ngắn 6 tháng thi công.', 'Tin chuyên ngành', 'Dự án đường sắt cao tốc Jakarta – Bandung: Bước đột phá hạ tầng 7,8 tỷ USD của Indonesia', 'du-an-duong-sat-cao-toc-jakarta-–-bandung:-buoc-dot-pha-ha-tang-78-ty-usd-cua-indonesia', NULL, NULL, 'Dự án đường sắt cao tốc Jakarta – Bandung: Bước đột phá hạ tầng 7,8 tỷ USD của Indonesia', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1444, 'vi', 'Để giúp quý khách hàng sử dụng thành thạo lisp cắt DIM trong enjiCAD, chúng tôi đã xây dựng bài viết hướng dẫn chi tiết với thao tác nhanh, đơn giản, dễ thực hiện. Mời các bạn cùng theo dõi.', 'Tin chuyên ngành', 'Hướng dẫn Load lisp cắt dim và sử dụng Lisp cắt dim trong enjiCAD', 'huong-dan-load-lisp-cat-dim-va-su-dung-lisp-cat-dim-trong-enjicad', NULL, NULL, 'Hướng dẫn Load lisp cắt dim và sử dụng Lisp cắt dim trong enjiCAD', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1445, 'vi', 'Cùng chúng tôi khám phá 6 nền tảng CDE phổ biến tại Việt Nam bao gồm Autodesk Construction Cloud, Trimble Connect, BIMCollab TWIN, BIMPlus, Bentley Infrastructure Cloud, Revizto giúp tối ưu quy trình BIM, tăng hiệu quả cộng tác và chuyển đổi số ngành xây dựng.', 'Tin chuyên ngành', 'Top 6 nền tảng CDE giúp Chủ đầu tư và kỹ sư quản lý dự án BIM hiệu quả vượt trội', 'top-6-nen-tang-cde-giup-chu-dau-tu-va-ky-su-quan-ly-du-an-bim-hieu-qua-vuot-troi', NULL, NULL, 'Top 6 nền tảng CDE giúp Chủ đầu tư và kỹ sư quản lý dự án BIM hiệu quả vượt trội', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1446, 'vi', 'IFC (tên đầy đủ là Industry Foundation Classes) là một định dạng dữ liệu mở, không phụ thuộc vào nhà cung cấp, cho phép chia sẻ dữ liệu CAD. IDEA StatiCa cho phép người dùng chia sẻ thiết kế liên kết ở định dạng mà các phần mềm BIM khác có thể đọc được chỉ bằng một nút bấm. Trong bài viết này, chúng tôi sẽ hướng dẫn bạn chi tiết cách xuất tệp IFC từ IDEA StatiCa.', 'Tin chuyên ngành', 'Xuất tệp IFC từ IDEA StatiCa', 'xuat-tep-ifc-tu-idea-statica', NULL, NULL, 'Xuất tệp IFC từ IDEA StatiCa', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1447, 'vi', 'Nghị định 119/2025/NĐ-CP quy định mới về kiểm kê khí nhà kính & thị trường carbon Việt Nam cho thấy Việt Nam đang hoàn thiện thể chế chính sách, thực hiện mục tiêu Net Zero.', 'Tin chuyên ngành', 'Nghị định 119/2025/NĐ-CP: Việt Nam tăng tốc giảm phát thải,  hướng tới Net Zero', 'nghi-dinh-1192025nd-cp:-viet-nam-tang-toc-giam-phat-thai--huong-toi-net-zero', NULL, NULL, 'Nghị định 119/2025/NĐ-CP: Việt Nam tăng tốc giảm phát thải,  hướng tới Net Zero', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1448, 'vi', 'Hiện nay, người dùng Opera Job Management đã có thể nâng cấp từ việc sử dụng khóa cứng đơn (Single License) sang mô hình khóa cứng mạng (Network License) linh hoạt và tối ưu hơn. Bài viết này sẽ cung cấp cái nhìn tổng quan về những lợi ích vượt trội, cách thức kết nối và yêu cầu cấu hình máy chủ khi cài đặt phần mềm để sử dụng mô hình này.', 'Tin chuyên ngành', 'Sử dụng phần mềm Opera Job Management với Network License', 'su-dung-phan-mem-opera-job-management-voi-network-license', NULL, NULL, 'Opera Job Management: Nâng cấp sử dụng mô hình Network License', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1449, 'vi', 'Lò đốt công nghiệp là thiết bị cốt lõi trong các nhà máy lọc dầu. Việc áp dụng phần mềm Xfh® Ultra 1.0 của HTRI sẽ giúp các nhà máy lọc dầu nâng cao công suất lò đốt công nghiệp', 'Tin chuyên ngành', 'Nâng Cao Công Suất Lò Đốt Công Nghiệp Trong Nhà Máy Lọc Dầu Bằng HTRI Xfh® Ultra', 'nang-cao-cong-suat-lo-dot-cong-nghiep-trong-nha-may-loc-dau-bang-htri-xfh®-ultra', NULL, NULL, 'Nâng Cao Công Suất Lò Đốt Công Nghiệp Trong Nhà Máy Lọc Dầu Bằng HTRI Xfh® Ultra', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1450, 'vi', 'CIC được lựa chọn là đơn vị tư vấn cung cấp dịch vụ kiểm kê khí nhà kính cấp cơ sở cho Công ty Gang Thép Thái Nguyên (TISCO).', 'Tin công ty', 'CIC tư vấn kiểm kê khí nhà kính cấp cơ sở cho Công ty CP Gang Thép Thái Nguyên (TISCO)', 'cic-tu-van-kiem-ke-khi-nha-kinh-cap-co-so-cho-cong-ty-cp-gang-thep-thai-nguyen-tisco', NULL, NULL, 'CIC tư vấn kiểm kê khí nhà kính cấp cơ sở cho Công ty CP Gang Thép Thái Nguyên (TISCO)', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1451, 'vi', 'Công ty Cổ phần Công nghệ và Tư vấn CIC được lựa chọn là đơn vị tư vấn cung cấp dịch vụ kiểm kê khí nhà kính cấp cơ sở cho Nhà máy điện Diesel Phú Qúy – Điện lực Bình Thuận.', 'Tin công ty', 'CIC tư vấn kiểm kê khí nhà kính cấp cơ sở cho Nhà máy điện Diesel Phú Qúy – Điện lực Bình Thuận', 'cic-tu-van-kiem-ke-khi-nha-kinh-cap-co-so-cho-nha-may-dien-diesel-phu-quy-–-dien-luc-binh-thuan', NULL, NULL, 'CIC tư vấn kiểm kê khí nhà kính cấp cơ sở cho Nhà máy điện Diesel Phú Qúy – Điện lực Bình Thuận', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1452, 'vi', 'HTRI đã được yêu cầu thực hiện các phương pháp để giảm thiểu sự phân bố dòng chảy không đồng đều này bằng hai công cụ mạnh mẽ là HTRI Xist® và CFD. Bài viết này sẽ phân tích sâu về hai phần mềm này.', 'Tin chuyên ngành', 'Giảm Thiểu Phân Bố Dòng Chảy Không Đồng Đều Trong Bộ Ngưng Tụ Hơi Nước Bằng Phần Mềm HTRI và CFD', 'giam-thieu-phan-bo-dong-chay-khong-dong-deu-trong-bo-ngung-tu-hoi-nuoc-bang-phan-mem-htri-va-cfd', NULL, NULL, 'Giảm Thiểu Phân Bố Dòng Chảy Không Đồng Đều Trong Bộ Ngưng Tụ Hơi Nước Bằng Phần Mềm HTRI và CFD', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1453, 'vi', 'enjiCAD cung cấp bộ công cụ giúp người dùng có thể tạo bảng, chỉnh sửa, quản lý bảng một cách dễ dàng.', 'Tin chuyên ngành', 'Tìm hiểu về các công cụ hỗ trợ bảng trong enjiCAD', 'tim-hieu-ve-cac-cong-cu-ho-tro-bang-trong-enjicad', NULL, NULL, 'Tìm hiểu về các công cụ hỗ trợ bảng trong enjiCAD', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1454, 'vi', 'dTwin cho phép tích hợp dữ liệu đa dạng, cung cấp bảng điều khiển và báo cáo thời gian thực để ra quyết định tốt hơn, từ đó giúp chủ đầu tư tiết kiệm chi phí và tối ưu hóa tài nguyên.', 'Tin chuyên ngành', 'dTwins – Nền tảng Digital Twins giúp chủ đầu tư nâng cao hiệu năng quản lý tòa nhà', 'dtwins-–-nen-tang-digital-twins-giup-chu-dau-tu-nang-cao-hieu-nang-quan-ly-toa-nha', NULL, NULL, 'dTwins – Nền tảng Digital Twins giúp chủ đầu tư nâng cao hiệu năng quản lý tòa nhà', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1455, 'vi', 'Presti AI thay thế các buổi chụp ảnh tốn kém và dựng hình 3D bằng trình tạo ảnh AI chỉ trong vài giây, tái định nghĩa visual marketing cho ngành nội thất với ưu điểm nổi bật về tăng tốc tạo ảnh, tiết kiệm chi phí và khẳng định giá trị thương hiệu.', 'Tin chuyên ngành', 'Presti AI: Tái Định Nghĩa Visual Marketing Ngành Nội Thất Giúp Bạn Dẫn Đầu Thị Trường', 'presti-ai:-tai-dinh-nghia-visual-marketing-nganh-noi-that-giup-ban-dan-dau-thi-truong', NULL, NULL, '1.	Presti AI: Tái Định Nghĩa Visual Marketing Ngành Nội Thất Giúp Bạn Dẫn Đầu Thị Trường', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1456, 'vi', 'ARCHITEChTURES AI – giải pháp Trí tuệ nhân tạo tạo sinh đang viết lại luật chơi của ngành kiến trúc và xây dựng toàn cầu khi sử dụng AI để tạo ra các thiết kế chỉ trong vài phút thay vì vài tháng.', 'Tin chuyên ngành', 'ARCHITEChTURES AI: Khi Trí Tuệ Nhân Tạo Định Hình Lại Skyline Tương Lai - Bạn Đã Sẵn Sàng Cho Cuộc Cách Mạng?', 'architechtures-ai:-khi-tri-tue-nhan-tao-dinh-hinh-lai-skyline-tuong-lai-ban-da-san-sang-cho-cuoc-cach-mang', NULL, NULL, 'ARCHITEChTURES AI: Khi Trí Tuệ Nhân Tạo Định Hình Lại Skyline Tương Lai - Bạn Đã Sẵn Sàng Cho Cuộc C', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1457, 'vi', 'Finch 3D là một nền tảng thiết kế tạo sinh dựa trên trí tuệ nhân tạo (AI Generative Design Platform), tối ưu hóa thiết kế BIM cho kiến trúc sư, thiết kế.', 'Tin chuyên ngành', 'Finch 3D – Giải Pháp AI Đột Phá Tối Ưu Hóa Thiết Kế BIM Cho Kiến Trúc Sư', 'finch-3d-–-giai-phap-ai-dot-pha-toi-uu-hoa-thiet-ke-bim-cho-kien-truc-su', NULL, NULL, 'Finch 3D – Giải Pháp AI Đột Phá Tối Ưu Hóa Thiết Kế BIM Cho Kiến Trúc Sư', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1458, 'vi', 'Pathw.ai – phần mềm AI trong thiết kết cấu, giúp tự động phân tích và chuẩn hóa quy trình chi tiết liên kết kết cấu thép, giảm 40–70% thời gian thiết kế, loại bỏ sai sót, tối ưu hóa hợp tác và mang lại ROI nhanh chóng cho ngành xây dựng.', 'Tin chuyên ngành', 'Pathw.ai – Phần mềm AI trong thiết kế kết cấu (ngành xây dựng)', 'pathwai-–-phan-mem-ai-trong-thiet-ke-ket-cau-nganh-xay-dung', NULL, NULL, 'Pathw.ai – Phần mềm AI trong thiết kế kết cấu (ngành xây dựng)', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1540, 'vi', 'Vừa qua, Công ty Cổ phần Công nghệ và Tư vấn CIC đã có buổi làm việc và trao đổi chuyên môn với Viện Khoa học Công nghệ mỏ – VINACOMIN, dưới sự chủ trì của Phó Viện trưởng TS. Nhữ Việt Tuấn cùng đại diện các phòng chuyên môn của Viện và đại diện Tổng Công ty Công nghiệp Mỏ Việt Bắc – TKV – CTCP.', 'Tin công ty', 'CIC giới thiệu giải pháp giám sát sạt trượt tiên tiến của CHCNAV tới  Viện Khoa học Công nghệ mỏ – VINACOMIN', 'cic-gioi-thieu-giai-phap-giam-sat-sat-truot-tien-tien-cua-chcnav-toivien-khoa-hoc-cong-nghe-mo-–-vinacomin', NULL, NULL, 'CIC giới thiệu giải pháp giám sát sạt trượt tiên tiến của CHCNAV tới  Viện Khoa học Công nghệ mỏ – V', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1459, 'vi', 'Swapp AI – nền tảng AI tự động hóa hồ sơ thi công từ Revit, giảm 50–70% thời gian, đảm bảo chuẩn BIM & nhất quán bản vẽ, giúp kiến trúc sư tập trung sáng tạo.', 'Tin chuyên ngành', 'Swapp AI – Tự Động Hóa Hồ Sơ Thi Công, Giải Phóng Sức Sáng Tạo Cho Kiến Trúc Sư', 'swapp-ai-–-tu-dong-hoa-ho-so-thi-cong-giai-phong-suc-sang-tao-cho-kien-truc-su', NULL, NULL, 'Swapp AI – Tự Động Hóa Hồ Sơ Thi Công, Giải Phóng Sức Sáng Tạo Cho Kiến Trúc Sư', '') ON CONFLICT (entity_id, locale) DO NOTHING;
