INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1462, 'vi', 'Khi sử dụng Opera Job Management phiên bản 3.9.1, người dùng có thể cập nhật danh sách các mã vật tư mới kèm một số thuộc tính cơ bản bằng việc sử dụng các file mẫu đã có với tính năng Price Update. Nhờ đó, thời gian xây dựng cơ sở dữ liệu ban đầu đã giảm đáng kể so với các thao tác nhập trên các phiên bản trước đó.', 'Tin chuyên ngành', 'Cập nhật dữ liệu vật tư hàng loạt trong Opera Job Management phiên bản 3.9.1', 'cạp-nhạt-dũ-liẹu-vạt-tu-hàng-loạt-trong-opera-job-management-phien-ban-391', NULL, NULL, 'Cập nhật dữ liệu vật tư hàng loạt trong Opera Job Management phiên bản 3.9.1', '') ON CONFLICT (entity_id, locale) DO NOTHING;
