INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1464, 'vi', 'OpenSpace AI là nền tảng ghi lại và phân tích thực tế công trường hàng đầu thế giới; xây dựng một "Bản sao Kỹ thuật số" (Digital Twin) toàn diện và sống động của dự án bằng một mô hình thực tế ảo, đa chiều.', 'Tin chuyên ngành', 'OpenSpace AI: Tái Định Nghĩa Hiện Thực Công Trường Bằng Trí Tuệ Nhân Tạo', 'openspace-ai:-tai-dinh-nghia-hien-thuc-cong-truong-bang-tri-tue-nhan-tao', NULL, NULL, 'OpenSpace AI: Tái Định Nghĩa Hiện Thực Công Trường Bằng Trí Tuệ Nhân Tạo', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1465, 'vi', 'Hãng Bentley vừa ra gửi thông báo quý khách hàng tham dự Buổi hội thảo trực tuyến Be Empowered sẽ diễn ra vào 15h (giờ Việt Nam) ngày 8/7/2025 để khám phá OpenPaths Advanced &amp; Ultimate – lập kế hoạch, mô hình hóa và phân tích giao thông.', 'Tin công ty', '[Đừng bỏ lỡ ]Webinar miễn phí: Khám phá OpenPaths Advanced &amp; Ultimate – Giải pháp lập kế hoạch, mô hình hóa và phân tích giao thông.', '[dung-bo-lo-]webinar-mien-phi:-kham-pha-openpaths-advanced-amp;-ultimate-–-giai-phap-lap-ke-hoach-mo-hinh-hoa-va-phan-tich-giao-thong', NULL, NULL, 'Webinar Khám phá OpenPaths Advanced &amp; Ultimate – Lập kế hoạch, mô hình hóa và phân tích giao thông', '') ON CONFLICT (entity_id, locale) DO NOTHING;
