INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1470, 'vi', 'Structure Plus là nền tảng đám mây đột phá, sử dụng công nghệ AI để tái định hình hoàn toàn quy trình thiết kế kết cấu, mang đến một kỷ nguyên mới của hiệu quả và sự thông minh.', 'Tin chuyên ngành', 'Structure Plus: Kỷ nguyên AI trong Tối ưu hóa Kết cấu - Tiết kiệm hơn, Nhanh hơn, Bền vững hơn', 'structure-plus:-ky-nguyen-ai-trong-toi-uu-hoa-ket-cau-tiet-kiem-hon-nhanh-hon-ben-vung-hon', NULL, NULL, 'Structure Plus: Kỷ nguyên AI trong Tối ưu hóa Kết cấu - Tiết kiệm hơn, Nhanh hơn, Bền vững hơn', '') ON CONFLICT (entity_id, locale) DO NOTHING;
