INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1472, 'vi', 'Ngày 04/07/2025, Quyết định số 21/2025/QĐ-TTg đã được ban hành, đánh dấu một bước tiến quan trọng trong việc định hình khuôn khổ pháp lý cho các hoạt động đầu tư bền vững tại Việt Nam. Văn bản này làm rõ các tiêu chí môi trường và quy trình xác nhận cụ thể cho các dự án đầu tư mong muốn được công nhận thuộc danh mục phân loại xanh, mở đường cho việc tiếp cận các cơ chế tài chính ưu đãi như tín dụng xanh và trái phiếu xanh.', 'Tin chuyên ngành', 'Quyết định 21/2025/QĐ-TTg: Hướng dẫn chi tiết tiêu chí và quy trình xác nhận "Dự án Xanh"', 'quyet-dinh-212025qd-ttg:-huong-dan-chi-tiet-tieu-chi-va-quy-trinh-xac-nhandu-an-xanh-', NULL, NULL, 'Quyết định 21/2025/QĐ-TTg: Hướng dẫn chi tiết tiêu chí và quy trình xác nhận "Dự án Xanh"', '') ON CONFLICT (entity_id, locale) DO NOTHING;
