INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1476, 'vi', 'Ngày 11 tháng 7 năm 2025, Công ty Cổ phần Công nghệ và Tư vấn CIC đã tổ chức thành công Đại hội cổ đông bất thường năm 2025. Đại hội đã diễn ra trong không khí nghiêm túc và chuyên nghiệp, với sự tham gia của đông đảo cổ đông và các thành viên trong Ban lãnh đạo công ty.', 'Quan hệ cổ đông', 'Công ty Cổ phần Công nghệ và Tư vấn CIC tổ chức thành công Đại hội cổ đông bất thường 2025', 'cong-ty-co-phan-cong-nghe-va-tu-van-cic-to-chuc-thanh-cong-dai-hoi-co-dong-bat-thuong-2025', NULL, NULL, 'Công ty Cổ phần Công nghệ và Tư vấn CIC tổ chức thành công Đại hội cổ đông bất thường 2025', '') ON CONFLICT (entity_id, locale) DO NOTHING;
