INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1478, 'vi', 'GeologicAI là tên của một công ty công nghệ chuyên phát triển nền tảng quét lõi khoan (core scanning), AI phân tích dữ liệu địa chất, và quản lý dữ liệu thăm dò khoáng sản theo hướng tự động hóa, tốc độ cao.', 'Tin chuyên ngành', 'GeologicAI- Hệ sinh thái công nghệ đột phá cho khoáng sản bền vững', 'geologicai--he-sinh-thai-cong-nghe-dot-pha-cho-khoang-san-ben-vung', NULL, NULL, 'GeologicAI – Hệ sinh thái công nghệ đột phá cho khoáng sản bền vững', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1479, 'vi', 'Tìm hiểu cách sử dụng tính năng DWG CONVERT trên enjiCAD để chuyển đổi file DWG giữa các phiên bản AutoCAD như 2018, 2013, 2010 dễ dàng, nhanh chóng.', 'Tin chuyên ngành', 'Hướng dẫn chuyển đổi file bản vẽ CAD sang version DWG khác nhanh chóng bằng enjiCAD', 'huong-dan-chuyen-doi-file-ban-ve-cad-sang-version-dwg-khac-nhanh-chong-bang-enjicad', NULL, NULL, 'Hướng dẫn chuyển đổi file bản vẽ CAD sang version DWG khác nhanh chóng bằng enjiCAD', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1480, 'vi', 'Mới đây, Công ty Cổ phần Công nghệ và Tư vấn CIC phối hợp cùng hãng Heat Transfer Research, Inc. (HTRI – Hoa Kỳ) đã tổ chức thành công hội thảo trực tuyến chuyên đề về ứng dụng phần mềm HTRI Xace trong đánh giá hệ thống làm mát động cơ đa chức năng.', 'Tin công ty', 'CIC tổ chức thành công Hội Thảo Trực Tuyến Về Ứng Dụng Phần Mềm HTRI XACE Trong Hệ Thống Làm Mát Động Cơ', 'cic-to-chuc-thanh-cong-hoi-thao-truc-tuyen-ve-ung-dung-phan-mem-htri-xace-trong-he-thong-lam-mat-dong-co', NULL, NULL, 'CIC tổ chức thành công Hội Thảo Trực Tuyến Về Ứng Dụng Phần Mềm HTRI XACE Trong Hệ Thống Làm Mát Độn', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1481, 'vi', 'Khám phá 6 cách tối ưu file CAD giúp giảm giật lag, nâng cao tốc độ xử lý và duy trì hiệu suất ổn định. Hướng dẫn từ chuyên gia CAD với tips phần cứng, Xref, Purge/Audit & cài đặt hiển thị.', 'Tin chuyên ngành', '6 Mẹo Tăng Tốc Độ Xử Lý File CAD: Nói Không Với Lag, Nâng Cao Hiệu Suất Thiết Kế', '6-meo-tang-toc-do-xu-ly-file-cad:-noi-khong-voi-lag-nang-cao-hieu-suat-thiet-ke', NULL, NULL, '6 Mẹo Tăng Tốc Độ Xử Lý File CAD: Nói Không Với Lag, Nâng Cao Hiệu Suất Thiết Kế', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1482, 'vi', 'Các tính năng nằm trong module mở rộng Curtain Wall của phần mềm nhôm kính Opera Job Management sẽ xử lý được các bài toán thường gặp trong thiết kế và tính toán vật tư cho các sản phẩm mặt dựng, vách dựng lớn.', 'Tin chuyên ngành', 'Phần mềm nhôm kính Opera Job Management: Tìm hiểu các tính năng trong module mặt dựng', 'phan-mem-nhom-kinh-opera-job-management:-tim-hieu-cac-tinh-nang-trong-module-mat-dung', NULL, NULL, 'Phần mềm nhôm kính Opera Job Management: Tìm hiểu các tính năng trong module mặt dựng', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1483, 'vi', 'Tìm hiểu tổng quan về khái niệm Digital Twin City (thành phố song sinh số), framework phát triển thành phố số thông minh theo tài liệu chính thống từ Diễn đàn Kinh tế Thế giới (WEF). Báo cáo này sẽ phân tích  các yếu tố kỹ thuật và chính sách, cùng những bài học thực tiễn trên toàn cầu và là tài liệu quan trọng dành cho doanh nghiệp, chính quyền đô thị và chuyên gia công nghệ.', 'Tin chuyên ngành', 'Digital Twin City – Giải pháp kiến tạo Thành phố số thông minh và bền vững', 'digital-twin-city-–-giai-phap-kien-tao-thanh-pho-so-thong-minh-va-ben-vung', NULL, NULL, 'Digital Twin City – Giải pháp kiến tạo Thành phố số thông minh và bền vững', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1484, 'vi', 'Trong hành trình chuyển đổi xanh và phát triển bền vững, Đánh giá Vòng đời sản phẩm (LCA) trở thành công cụ không thể thiếu giúp doanh nghiệp hiểu và tối ưu hóa tác động môi trường. Nhưng một câu hỏi sống còn vẫn còn bỏ ngỏ: Làm thế nào để thu thập dữ liệu đầu vào một cách đầy đủ, chính xác và đáng tin cậy cho LCA?', 'Tin chuyên ngành', 'Hướng Dẫn Thu Thập Dữ Liệu Đáng Tin Cậy Cho Đánh Giá Vòng Đời Sản Phẩm (LCA)', 'huong-dan-thu-thap-du-lieu-dang-tin-cay-cho-danh-gia-vong-doi-san-pham-lca', NULL, NULL, 'Hướng Dẫn Thu Thập Dữ Liệu Đáng Tin Cậy Cho Đánh Giá Vòng Đời Sản Phẩm (LCA)', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1485, 'vi', 'Nâng cao năng lực kỹ sư kết cấu với ETABS v22.7.0 & SAFE v22.7.0 với các tính năng vượt trội vừa được công bố trong tháng 7/2025.', 'Tin chuyên ngành', 'ETABS v22.7.0 & SAFE v22.7.0 vừa ra mắt, đẩy nhanh thiết kế dầm và khung thép', 'etabs-v2270-amp;-safe-v2270-vua-ra-mat-day-nhanh-thiet-ke-dam-va-khung-thep', NULL, NULL, 'ETABS v22.7.0 & SAFE v22.7.0 vừa ra mắt, đẩy nhanh thiết kế dầm và khung thép', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1486, 'vi', 'Hãng CSI vừa mới phát hành bản cập nhật mới cho SAP2000 v26 và CSiBridge v26, cập nhật một số tính năng mới mà kỹ sư kết cấu không thể bỏ qua.', 'Tin chuyên ngành', 'Phát hành SAP2000 v26.3.0 và CSiBridge v26.3.0 (version mới nhất 2025)', 'phat-hanh-sap2000-v2630-va-csibridge-v2630-version-moi-nhat-2025', NULL, NULL, 'Phát hành SAP2000 v26.3.0 và CSiBridge v26.3.0 (version mới nhất 2025)', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1487, 'vi', 'STAAD.Pro 2025 bổ sung nhiều chức năng mới nhằm nâng cao hiệu quả làm việc cho các kỹ sư trên toàn thế giới, đồng thời đã khắc phục nhiều vấn đề đã được báo cáo. Chúng tôi đặc biệt khuyến nghị quý vị nên sử dụng phiên bản này để cải thiện trải nghiệm làm việc của mình.', 'Tin chuyên ngành', 'Nâng cao hiệu quả và độ chính xác trong phân tích và thiết kế kết cấu với phiên bản STAAD.Pro 2025', 'nang-cao-hieu-qua-va-do-chinh-xac-trong-phan-tich-va-thiet-ke-ket-cau-voi-phien-ban-staadpro-2025', NULL, NULL, 'Nâng cao hiệu quả và độ chính xác trong phân tích và thiết kế kết cấu với phiên bản STAAD.Pro 2025', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1488, 'vi', 'Bentley System vui mừng thông báo phát hành SACS 2025  (phiên bản mới nhất) với hiệu suất thiết kế kết cấu ngoài khơi vượt trội, từ đó cải thiện hiệu suất làm việc cho các kỹ sư.', 'Tin chuyên ngành', 'Phần mềm SACS 2025: Nâng Cao Hiệu Suất Thiết Kế Kết Cấu Ngoài Khơi', 'phan-mem-sacs-2025:-nang-cao-hieu-suat-thiet-ke-ket-cau-ngoai-khoi', NULL, NULL, 'Phần mềm SACS 2025: Nâng Cao Hiệu Suất Thiết Kế Kết Cấu Ngoài Khơi', '') ON CONFLICT (entity_id, locale) DO NOTHING;
