INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1490, 'vi', 'Công ty CIC cung cấp dịch vụ tư vấn BIM cho các cơ quan quản lý nhà nước, Chủ đầu tư bất động sản (tập đoàn, công ty phát triển dự án), Ban quản lý dự án, Tổng thầu xây dựng, đơn vị thi công… về chuyển đổi số sang mô hình BIM, từ đó giúp các doanh nghiệp xây dựng áp dụng công nghệ BIM một cách hiệu quả, mang lại nhiều lợi ích về kinh tế, kỹ thuật và quản lý dự án.', 'Tin chuyên ngành', 'Dịch vụ tư vấn BIM là gì – Hành trình chuyển đổi số cùng CIC', 'dich-vu-tu-van-bim-la-gi-–-hanh-trinh-chuyen-doi-so-cung-cic', NULL, NULL, 'Dịch vụ tư vấn BIM là gì – Hành trình chuyển đổi số cùng CIC', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1492, 'vi', 'Trong thiết kế kỹ thuật, việc nhập dữ liệu tọa độ từ Excel vào enjiCAD giúp kỹ sư thiết kế tiết kiệm thời gian và tăng độ chính xác. Bài viết này hướng dẫn bạn cách thực hiện ba thao tác quan trọng: rải điểm từ Excel, nối đường polyline, và kiểm tra tọa độ địa lý tự động.', 'Tin chuyên ngành', 'Hướng dẫn tự động rải điểm từ Excel vào enjiCAD, nối đường pline & kiểm tra tọa độ địa lý', 'huong-dan-tu-dong-rai-diem-tu-excel-vao-enjicad-noi-duong-pline-amp;-kiem-tra-toa-do-dia-ly', NULL, NULL, 'Hướng dẫn tự động rải điểm từ Excel vào enjiCAD, nối đường pline & kiểm tra tọa độ địa lý', '') ON CONFLICT (entity_id, locale) DO NOTHING;
