INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1493, 'vi', 'Vừa qua, Công ty cổ phần Công nghệ và Tư vấn CIC đã phối hợp tổ chức thành công hội thảo “Ứng dụng Trí tuệ nhân tạo trong quản lý dự án và công việc” tại Ban Quản lý Dự án Đầu tư Xây dựng các Công trình Dân dụng và Công nghiệp TP.HCM (Ban DD&CN). Sự kiện thu hút sự tham dự đầy đủ của Ban Lãnh đạo, các trưởng, phó ban chuyên ngành cùng đông đảo cán bộ từ các phòng ban chức năng – thể hiện rõ tinh thần sẵn sàng đổi mới và chuyển đổi số mạnh mẽ tại đơn vị.', 'Tin công ty', 'Ban Dân dụng và Công nghiệp TP.HCM tiên phong ứng dụng AI vào quản lý dự án', 'ban-dan-dung-va-cong-nghiep-tphcm-tien-phong-ung-dung-ai-vao-quan-ly-du-an', NULL, NULL, 'Ban Dân dụng và Công nghiệp TP.HCM tiên phong ứng dụng AI vào quản lý dự án', '') ON CONFLICT (entity_id, locale) DO NOTHING;
