INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1496, 'vi', 'Bentley Systems chính thức tích hợp Google Maps vào MicroStation 2025, mang lại chất lượng hình ảnh và dữ liệu vượt trội. Công ty CIC, với vai trò là đối tác chiến lược, cung cấp thông tin chi tiết về lộ trình chuyển đổi và hướng dẫn nâng cấp để các doanh nghiệp và kỹ sư tận dụng tối đa tính năng đột phá này.', 'Tin chuyên ngành', 'MicroStation 2025: Tích Hợp Google Maps - Nâng Tầm Trải Nghiệm Thiết Kế Với Dữ Liệu Bản Đồ Vượt Trội', 'microstation-2025:-tich-hop-google-maps-nang-tam-trai-nghiem-thiet-ke-voi-du-lieu-ban-do-vuot-troi', NULL, NULL, 'MicroStation 2025: Tích Hợp Google Maps - Nâng Tầm Trải Nghiệm Thiết Kế Với Dữ Liệu Bản Đồ Vượt Trội', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1507, 'vi', 'Ngày 27/8/2025, Seequent tổ chức hội thảo trực tuyến với chủ đề: Phân tích địa chất từ hình ảnh lõi khoan, khám phá tính năng  của Drillhole Correlation của Leapfrog.', 'Tin công ty', 'Webinar miễn phí tháng 8: Sử dụng Leapfrog Geo phân tích địa chất trực tiếp từ hình ảnh lõi khoan', 'webinar-mien-phi-thang-8:-su-dung-leapfrog-geo-phan-tich-dia-chat-truc-tiep-tu-hinh-anh-loi-khoan', NULL, NULL, 'Webinar miễn phí tháng 8: Sử dụng Leapfrog Geo phân tích địa chất trực tiếp từ hình ảnh lõi khoan', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1497, 'vi', 'Khám phá các tính năng đột phá Templates và Company Sets trong IDEA StatiCa 25.0. Với vai trò là đối tác chính thức, CIC hướng dẫn cách tăng tốc độ thiết kế, đảm bảo tiêu chuẩn doanh nghiệp và giảm thiểu sai sót cho các kỹ sư kết cấu tại Việt Nam.', 'Tin chuyên ngành', 'Tối Ưu Hóa Thiết Kế Liên Kết Thép với IDEA StatiCa 25.0: Nhanh hơn, Đồng bộ hơn nhờ Templates và Company Sets', 'toi-uu-hoa-thiet-ke-lien-ket-thep-voi-idea-statica-250:-nhanh-hon-dong-bo-hon-nho-templates-va-company-sets', NULL, NULL, 'Tối Ưu Hóa Thiết Kế Liên Kết Thép với IDEA StatiCa 25.0: Nhanh hơn, Đồng bộ hơn nhờ Templates và Com', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1498, 'vi', 'Đại diện của Công ty CIC sẽ có bài tham luận tại SACA Connect tháng 8 với chủ đề “Kết nối doanh nghiệp ngành Tư vấn Xây dựng: Ba góc nhìn – Một mục tiêu”. Sự kiện được tổ chức vào ngày 28/8/2025 tại TP Hồ Chí Minh.', 'Tin công ty', '[Sự kiện tháng 8] CIC tham gia SACA Connect: Kết Nối Doanh Nghiệp Ngành Tư vấn Xây Dựng ', '[su-kien-thang-8]-cic-tham-gia-saca-connect:-ket-noi-doanh-nghiep-nganh-tu-van-xay-dung', NULL, NULL, '[Sự kiện tháng 8] CIC tham gia SACA Connect: Kết Nối Doanh Nghiệp Ngành Tư vấn Xây Dựng ', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1499, 'vi', 'Việc lựa chọn phần mềm địa chất phù hợp có thể khó khăn, ngay cả đối với những chuyên gia dữ liệu dày dạn kinh nghiệm. Với quá nhiều lựa chọn có sẵn, làm thế nào để  tìm ra giải pháp phù hợp nhất với nhu cầu của mình. Bài viết dưới đây sẽ phân tích các công cụ và nền tảng phần mềm địa chất hàng đầu, giúp  tinh gọn quản lý dữ liệu, tăng cường khả năng cộng tác, và đưa các hoạt động địa chất bước vào kỷ nguyên số.', 'Tin chuyên ngành', 'Top 8 cơ sở dữ liệu địa chất hàng đầu cho thăm dò khoáng sản năm 2025', 'top-8-co-so-du-lieu-dia-chat-hang-dau-cho-tham-do-khoang-san-nam-2025', NULL, NULL, 'Top 8 cơ sở dữ liệu địa chất hàng đầu cho thăm dò khoáng sản năm 2025', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1500, 'vi', 'Vĩnh Long, ngày 06/08/2025 – Công ty Cổ phần Công nghệ và Tư vấn CIC, với sự đồng thuận của Công ty Cổ phần Cấp nước Vĩnh Long (VWACO), đã tổ chức thành công buổi giới thiệu phần mềm mô phỏng thủy lực OpenFlows Water. Đây là giải pháp tiên tiến nhằm hỗ trợ quản lý và vận hành hệ thống cấp nước sạch hiệu quả, bắt kịp xu hướng ứng dụng công nghệ trong ngành cấp nước.', 'Tin công ty', 'CIC Giới Thiệu Giải Pháp Phần Mềm OpenFlows Water tại VWACO', 'cic-gioi-thieu-giai-phap-phan-mem-openflows-water-tai-vwaco', NULL, NULL, 'CIC Giới Thiệu Giải Pháp Phần Mềm OpenFlows Water tại VWACO', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1501, 'vi', 'Thị trường tín chỉ carbon tại Việt Nam đang bước vào giai đoạn phát triển đầy sôi động, được thúc đẩy mạnh mẽ bởi một chiến lược quốc gia bài bản và hàng loạt các hoạt động hợp tác quốc tế then chốt. Những động thái này không chỉ khẳng định cam kết Net Zero mạnh mẽ mà còn mở ra một sân chơi mới với vô vàn cơ hội cho các doanh nghiệp trong các khối ngành kỹ thuật.', 'Tin chuyên ngành', 'Thị Trường Carbon Việt Nam Tăng Tốc: Chiến Lược Quốc Gia và Cơ Hội Cho Doanh Nghiệp', 'thi-truong-carbon-viet-nam-tang-toc:-chien-luoc-quoc-gia-va-co-hoi-cho-doanh-nghiep', NULL, NULL, 'Thị Trường Carbon Việt Nam Tăng Tốc: Chiến Lược Quốc Gia và Cơ Hội Cho Doanh Nghiệp', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1502, 'vi', 'Ngày 14/08/2025, Công ty Cổ phần Công nghệ và Tư vấn CIC phối hợp cùng Tổng Công ty Tư vấn thiết kế Giao thông Vận tải – CTCP (TEDI) tổ chức thành công Hội thảo giới thiệu giải pháp công nghệ cao của hãng CHCNAV, phục vụ công tác khảo sát, thiết kế và thi công các dự án đường sắt đô thị đường sắt cao tốc tại Việt Nam.', 'Tin công ty', 'CIC và TEDI tổ chức thành công Hội thảo “Giải pháp công nghệ cao phục vụ khảo sát thiết kế các dự án Đường sắt Đô thị và Đường sắt Cao tốc”', 'cic-va-tedi-to-chuc-thanh-cong-hoi-thao-giai-phap-cong-nghe-cao-phuc-vu-khao-sat-thiet-ke-cac-du-an-duong-sat-do-thi-va-duong-sat-cao-toc', NULL, NULL, 'CIC và TEDI tổ chức thành công Hội thảo “Giải pháp công nghệ cao phục vụ khảo sát thiết kế các dự án', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1503, 'vi', 'Công ty cổ phần Công nghệ và Tư vấn CIC chính thức trở thành Hội viên Hiệp Hội Xây Dựng & Vật Liệu Xây Dựng Tp. Hồ Chí Minh (SACA) từ tháng 8/2025.', 'Tin công ty', 'CIC trở thành hội viên chính thức Hiệp hội SACA', 'cic-tro-thanh-hoi-vien-chinh-thuc-hiep-hoi-saca', NULL, NULL, 'CIC trở thành hội viên chính thức Hiệp hội SACA', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1504, 'vi', 'Digital Twin không chỉ là một công nghệ mới mà đang dần trở thành một phần cốt lõi của cơ sở hạ tầng thủy điện thông minh.', 'Tin chuyên ngành', 'Digital Twin: Công cụ tối ưu hóa sản xuất và bảo trì trong ngành thủy điện', 'digital-twin:-cong-cu-toi-uu-hoa-san-xuat-va-bao-tri-trong-nganh-thuy-dien', NULL, NULL, 'Digital Twin: Công cụ tối ưu hóa sản xuất và bảo trì trong ngành thủy điện', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1505, 'vi', 'Trước đây, lựa chọn phổ biến nhất cho phần mềm CAD là AutoCAD, tuy nhiên, AutoCAD có giá bản quyền cao và tốn tài nguyên phần cứng. Vì vậy, hãy cùng CIC khám phá Top 3 phần mềm CAD có thể thay thế AutoCAD với chi phí thấp và hiệu năng cao trong bài viết dưới đây.', 'Tin chuyên ngành', 'Top 3 Phần Mềm Thay Thế AutoCAD Tốt Nhất 2026: Bản Quyền Vĩnh Viễn, Chi Phí Thấp', 'top-3-phan-mem-thay-the-autocad-tot-nhat-2026:-ban-quyen-vinh-vien-chi-phi-thap', NULL, NULL, 'Top 3 Phần Mềm Thay Thế AutoCAD Tốt Nhất 2026: Bản Quyền Vĩnh Viễn, Chi Phí Thấp', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1506, 'vi', 'Laser Scanning 3D (hay còn gọi là quét 3D laser) là phương pháp không tiếp xúc, sử dụng tia laser để thu thập dữ liệu, được ứng dụng trong các ngành như xây dựng, kỹ thuật, dầu khí, khảo cổ học và y tế. Đây là nền tảng không thể thiếu để xây dựng các mô hình BIM và Digital Twins thông minh.', 'Tin chuyên ngành', 'Khai phá sức mạnh của công nghệ Laser Scanning 3D: Nền tảng cho BIM và Digital Twins', 'khai-pha-suc-manh-cua-cong-nghe-laser-scanning-3d:-nen-tang-cho-bim-va-digital-twins', NULL, NULL, 'Khai phá sức mạnh của công nghệ Laser Scanning 3D: Nền tảng cho BIM và Digital Twins', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1508, 'vi', 'Seequent – Công ty thành viên của Bentley chuyên cung cấp giải pháp địa chất dưới bề mặt – vừa ra mắt tính năng mới của phần mềm mô hình hóa địa chất 3D Leapfrog Geo: truyền trực tuyến (streaming) ảnh lõi khoan độ phân giải cao trực tiếp từ nền tảng đám mây Imago vào giao diện mô hình hóa. Nhờ đó, người dùng không chỉ mô hình hóa nhanh hơn mà còn có thể làm việc trực tiếp với hình ảnh lõi khoan chất lượng cao – tất cả trong một môi trường duy nhất.', 'Tin chuyên ngành', 'Khai thác tối đa sức mạnh hình ảnh lõi khoan với Leapfrog Geo 2025.2', 'khai-thac-toi-da-suc-manh-hinh-anh-loi-khoan-voi-leapfrog-geo-20252', NULL, NULL, 'Khai thác tối đa sức mạnh hình ảnh lõi khoan với Leapfrog Geo 2025.2', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1509, 'vi', 'Trong những bản vẽ kỹ thuật ở một số lĩnh vực sẽ yêu cầu việc sử dụng số lượng lớn các đối tượng Block Attribute, các Mtext để hiển thị các đối tượng có tính chất lặp lại. Khi đó, việc sửa đổi giá trị các yếu tố trong loạt đối tượng này cần có cách làm nhanh chóng và hiệu quả. Trong bài viết này, đội ngũ kỹ sư của CIC sẽ giới thiệu tới các bạn một số phương pháp thao tác nhanh và hiệu quả.', 'Tin chuyên ngành', 'Cách chỉnh sửa Text lặp lại nhanh chóng trong bản vẽ CAD', 'cach-chinh-sua-text-lap-lai-nhanh-chong-trong-ban-ve-cad', NULL, NULL, 'Cách chỉnh sửa Text lặp lại nhanh chóng trong bản vẽ CAD', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1510, 'vi', 'Các doanh nghiệp tiên phong trong ngành sản xuất – được McKinsey gọi là “Lighthouses” (Ngọn Hải Đăng) – đang ngày càng khai thác sâu sắc hơn những giá trị mà AI và Gen AI (Trí tuệ nhân tạo tạo sinh) mang lại. Với hơn 60% sáng kiến mới áp dụng AI toàn diện, những nhà máy này đang thiết lập một chuẩn mực mới về hiệu quả vận hành, tốc độ triển khai, và khả năng thích nghi quy mô.', 'Tin chuyên ngành', 'AI đang thay đổi cuộc chơi sản xuất như thế nào? Góc nhìn từ các doanh nghiệp dẫn đầu toàn cầu', 'ai-dang-thay-doi-cuoc-choi-san-xuat-nhu-the-nao-goc-nhin-tu-cac-doanh-nghiep-dan-dau-toan-cau', NULL, NULL, 'AI đang thay đổi cuộc chơi sản xuất như thế nào? Góc nhìn từ các doanh nghiệp dẫn đầu toàn cầu', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1511, 'vi', 'Hãng GeoSIG phối hợp cùng GradeSens – công ty Thụy Sĩ tiên phong trong lĩnh vực phân tích thông minh cho ngành thủy điện – trân trọng kính mời Quý vị tham dự hội thảo trực tuyến (webinar) chuyên đề về Ứng dụng AI trong Bảo trì Dự đoán cho Nhà máy thủy điện.', 'Tin công ty', 'THƯ MỜI THAM DỰ WEBINAR: Ứng dụng AI trong Bảo trì Dự đoán cho Nhà máy thủy điện', 'thu-moi-tham-du-webinar:-ung-dung-ai-trong-bao-tri-du-doan-cho-nhà-máy-thủy-diẹn', NULL, NULL, 'THƯ MỜI THAM DỰ WEBINAR: Ứng dụng AI trong Bảo trì Dự đoán cho Nhà máy thủy điện', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1512, 'vi', 'AI đã tạo ra một bước ngoặt trong Cách mạng Công nghiệp 4.0. Khám phá cách các Nhà máy Tiên phong (Lighthouse) đang dẫn đầu và 3 lựa chọn chiến lược—Đổi mới, Tăng tốc, hoặc Theo sau—giúp doanh nghiệp của bạn tồn tại và bứt phá trong cuộc đua cạnh tranh.', 'Tin chuyên ngành', 'AI trong Sản xuất: Bước ngoặt Cách mạng 4.0 và Lựa chọn chiến lược để không bị tụt hậu', 'ai-trong-san-xuat:-buoc-ngoat-cach-mang-40-va-lua-chon-chien-luoc-de-khong-bi-tut-hau', NULL, NULL, 'AI trong Sản xuất: Bước ngoặt Cách mạng 4.0 và Lựa chọn chiến lược để không bị tụt hậu', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1513, 'vi', 'Khám phá cách tự động hóa tối ưu liên kết thép bằng IDEA StatiCa API và Grasshopper. Tiết kiệm thời gian, chi phí vật liệu và đảm bảo thiết kế an toàn theo tiêu chuẩn.', 'Tin chuyên ngành', 'Hướng Dẫn Tối Ưu Liên Kết Thép Tự Động với IDEA StatiCa API', 'huong-dan-toi-uu-lien-ket-thep-tu-dong-voi-idea-statica-api', NULL, NULL, 'Hướng Dẫn Tối Ưu Liên Kết Thép Tự Động với IDEA StatiCa API', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1514, 'vi', 'Vừa qua, Báo cáo kiểm kê khí nhà kính (KNK) năm 2024 của Công ty Cổ phần Thép Việt Ý, do CIC tư vấn thực hiện, đã chính thức vượt qua phiên thẩm định quan trọng của Hội đồng thẩm định tỉnh Hưng Yên. Đây là một bước tiến quan trọng, khẳng định sự tuân thủ nghiêm túc của Thép Việt Ý và năng lực chuyên môn của Công ty CIC trong lĩnh vực tư vấn môi trường.', 'Tin công ty', 'CIC hoàn thành hỗ trợ Công ty CP Thép Việt Ý thẩm định Báo cáo Kiểm kê khí nhà kính cấp cơ sở năm 2024', 'cic-hoan-thanh-ho-tro-cong-ty-cp-thep-viet-y-tham-dinh-bao-cao-kiem-ke-khi-nha-kinh-cap-co-so-nam-2024', NULL, NULL, 'CIC hoàn thành hỗ trợ Công ty CP Thép Việt Ý thẩm định Báo cáo Kiểm kê khí nhà kính cấp cơ sở năm 20', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1515, 'vi', 'Khoảng cách hiệu suất giữa các doanh nghiệp biết và không biết cách dùng AI đã tăng lên 3,8 lần. Bài viết phân tích 4 yếu tố cốt lõi giúp các nhà lãnh đạo bứt phá: từ sự bảo trợ của CEO đến đầu tư vào dữ liệu', 'Tin chuyên ngành', ' Ứng Dụng AI Trong Doanh Nghiệp với 4 Bí Quyết Vượt Trội Từ Các Công Ty Dẫn Đầu', 'ung-dung-ai-trong-doanh-nghiep-voi-4-bi-quyet-vuot-troi-tu-cac-cong-ty-dan-dau', NULL, NULL, 'Ứng Dụng AI Trong Doanh Nghiệp với 4 Bí Quyết Vượt Trội Từ Các Công Ty Dẫn Đầu', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1516, 'vi', 'Hướng dẫn 5 bước giúp doanh nghiệp xây dựng kế hoạch giảm phát thải khí nhà kính, đáp ứng quy định, tối ưu chi phí và sẵn sàng cho mục tiêu Net Zero.', 'Tin chuyên ngành', '5 Bước Xây Dựng Kế Hoạch Giảm Phát Thải Hiệu Quả Cho Doanh Nghiệp', '5-buoc-xay-dung-ke-hoach-giam-phat-thai-hieu-qua-cho-doanh-nghiep', NULL, NULL, '5 Bước Xây Dựng Kế Hoạch Giảm Phát Thải Hiệu Quả Cho Doanh Nghiệp', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1517, 'vi', 'Công ty Cổ phần Công nghệ và Tư vấn CIC chính thức công bố ký kết hợp đồng tư vấn triển khai chứng nhận công trình xanh BREEAM cho một chủ đầu tư lớn tại Việt Nam. Đây là dự án đầu tiên tại Việt Nam được tư vấn và chuẩn bị hồ sơ để xin cấp chứng nhận BREEAM từ tổ chức BRE Global (Vương quốc Anh), đánh dấu một bước tiến quan trọng trong lĩnh vực xây dựng bền vững tại Việt Nam và khẳng định năng lực dẫn đầu của CIC.', 'Tin công ty', 'CIC Chính Thức Tư Vấn Chứng Nhận Công Trình Xanh BREEAM Đầu Tiên Tại Việt Nam', 'cic-chinh-thuc-tu-van-chung-nhan-cong-trinh-xanh-breeam-dau-tien-tai-viet-nam', NULL, NULL, 'CIC Chính Thức Tư Vấn Chứng Nhận Công Trình Xanh BREEAM Đầu Tiên Tại Việt Nam', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1518, 'vi', 'Ngày 10/09/2025, Công ty Cổ phần Công nghệ và Tư vấn CIC và  Tập đoàn Công nghiệp Than - Khoáng sản Việt Nam (TKV) đồng tổ chức hội thảo chuyên đề: “An toàn mỏ – Giải pháp giám sát sạt trượt toàn diện”. Sự kiện nhằm giới thiệu giải pháp tiên tiến của hãng CHCNAV, mở ra bước tiến quan trọng trong việc ứng dụng công nghệ hiện đại vào công tác đảm bảo an toàn khai thác mỏ tại Việt Nam.', 'Tin công ty', 'CIC và Tập đoàn Công nghiệp Than - Khoáng sản Việt Nam tổ chức Hội thảo “An toàn Mỏ - Giải pháp Giám sát Sạt trượt Mỏ Toàn diện”', 'cic-va-tap-doan-cong-nghiep-than-khoang-san-viet-nam-to-chuc-hoi-thao-an-toan-mo-giai-phap-giam-sat-sat-truot-mo-toan-dien', NULL, NULL, 'CIC và Tập đoàn Công nghiệp Than - Khoáng sản Việt Nam tổ chức Hội thảo “An toàn Mỏ - Giải pháp Giám', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1519, 'vi', 'Tìm hiểu 5 phần mềm BIM phổ biến nhất hiện nay, cập nhật tính năng mới, ưu nhược điểm và hướng dẫn chọn công cụ phù hợp cho doanh nghiệp xây dựng.', 'Tin chuyên ngành', 'Khám phá 5 Phần mềm BIM phổ biến nhất dành cho doanh nghiệp xây dựng', 'kham-pha-5-phan-mem-bim-pho-bien-nhat-danh-cho-doanh-nghiep-xay-dung', NULL, NULL, 'Khám phá 5 Phần mềm BIM phổ biến nhất dành cho doanh nghiệp xây dựng', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1524, 'vi', 'Từ những con đường tỉnh lẻ Romania đến các bản sao số (digital twins) ở Pháp và AI mang tính tác nhân (agentic AI), năm lãnh đạo tại Bentley giải thích điều gì đang bị đe dọa — và cách thiết kế thông minh cùng công nghệ có thể đảo ngược thế cân bằng.', 'Tin chuyên ngành', 'Trí tuệ nhân tạo, khí hậu và tương lai của cơ sở hạ tầng', 'tri-tue-nhan-tao-khi-hau-va-tuong-lai-cua-co-so-ha-tang', NULL, NULL, 'Trí tuệ nhân tạo, khí hậu và tương lai của cơ sở hạ tầng', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1520, 'vi', 'Greenwashing (tẩy xanh) là thuật ngữ chỉ các chiến thuật marketing đánh lừa công chúng, gây xói mòn lòng tin và cản trở giải pháp thiết thực ứng phó với khủng hoảng khí hậu.', 'Tin chuyên ngành', 'Greenwashing (tẩy xanh) là gì và rủi ro cho doanh nghiệp', 'greenwashing-tay-xanh-la-gi-va-rui-ro-cho-doanh-nghiep', NULL, NULL, 'Greenwashing (tẩy xanh) là gì và rủi ro cho doanh nghiệp', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1521, 'vi', 'Khám phá cách ứng dụng AI trong CAD để tự động hóa quy trình, tạo đoạn code LISP, tối ưu hiệu suất và nâng cao độ chính xác cho kỹ sư.', 'Tin chuyên ngành', 'Ứng dụng Trí tuệ Nhân tạo (AI) trong CAD', 'ung-dung-tri-tue-nhan-tao-ai-trong-cad', NULL, NULL, 'Ứng dụng Trí tuệ Nhân tạo (AI) trong CAD', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1522, 'vi', 'Net Zero 2050 không chỉ là một cam kết môi trường – mà là hướng đi tất yếu cho mọi tổ chức mong muốn phát triển lâu dài.', 'Tin chuyên ngành', 'Net Zero 2050 là gì? Doanh nghiệp Việt Nam đã sẵn sàng bước vào kỳ nguyên phát triển bền vững', 'net-zero-2050-la-gi-doanh-nghiep-viet-nam-da-san-sang-buoc-vao-ky-nguyen-phat-trien-ben-vung', NULL, NULL, 'Net Zero 2050 là gì? Doanh nghiệp Việt Nam đã sẵn sàng bước vào kỳ nguyên phát triển bền vững', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1523, 'vi', 'Dự án đập Semantok dài nhất khu vực đã được tối ưu hóa thiết kế địa kỹ thuật nhờ bộ công cụ mô phỏng hiện trường thực PLAXIS và GeoStudio, góp phần tiết kiệm hàng triệu USD và nâng cao độ an toàn công trình. Xem chi tiết cách PT Hutama Karya vượt qua những thách thức với sự hỗ trợ từ phần mềm Bentley và Seequent.', 'Tin chuyên ngành', 'Ứng dụng phần mềm PLAXIS và GeoStudio trong tối ưu thiết kế địa kỹ thuật đập Semantok – Công trình đập dài nhất Đông Nam Á', 'ung-dung-phan-mem-plaxis-va-geostudio-trong-toi-uu-thiet-ke-dia-ky-thuat-dap-semantok-–-cong-trinh-dap-dai-nhat-dong-nam-a', NULL, NULL, 'Ứng dụng PLAXIS và GeoStudio tối ưu thiết kế địa kỹ thuật đập Semantok – công trình kỷ lục tại Đông', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1525, 'vi', 'Seequent Evo là nền tảng đám mây tiên tiến giúp quản lý dữ liệu địa chất tập trung, nâng cao hợp tác. Evo tập hợp dữ liệu từ cả giải pháp của Seequent như: Leapfrog Geo, Oasis montaj, MX Deposit, tìm kiếm địa lý (geospatial search) với nền tảng Cesium của Bentley Systems… và ứng dụng bên thứ ba vào một nguồn duy nhất, đảm bảo thông tin luôn cập nhật liên tục, chính xác và dễ chia sẻ.', 'Tin chuyên ngành', 'Seequent ra mắt Seequent Evo-Nền tảng đám mây tiên tiến, quản lý dữ liệu địa chất hiệu quả', 'seequent-ra-mat-san-pham-seequent-evo', NULL, NULL, 'Seequent ra mắt Seequent Evo-Nền tảng đám mây tiên tiến, quản lý dữ liệu địa chất hiệu quả', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1526, 'vi', 'Trong quá trình thiết kế bản vẽ kỹ thuật bằng các phần mềm CAD, việc đánh số thứ tự cho các đối tượng như ký hiệu, vị trí, chi tiết… là thao tác quen thuộc. Tuy nhiên, nếu làm thủ công sẽ mất nhiều thời gian, dễ nhầm lẫn và khó chỉnh sửa khi bản vẽ có thay đổi. Không ít người nghĩ rằng chỉ có thể dùng Lisp để tự động hóa việc này, nhưng thực tế ngay trong phần mềm đã có sẵn những công cụ hỗ trợ bạn đánh số thứ tự nhanh chóng, chính xác và linh hoạt mà không cần dùng Lisp.', 'Tin chuyên ngành', 'Cách đánh số thứ tự trong enjiCAD tự động mà không cần dùng lisp', 'cach-danh-so-thu-tu-trong-enjicad-tu-dong-ma-khong-can-dung-lisp', NULL, NULL, 'Cách đánh số thứ tự trong enjiCAD tự động mà không cần dùng lisp', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1527, 'vi', 'Trong quá trình thiết kế khi gặp những bản vẽ đang không ở đúng tỷ lệ bản vẽ 1:1 ta có thể sẽ gặp nhiều rắc rối trong quá trình triển khai các bước liên quan. Đôi khi việc này xảy ra sau hàng tá các chỉnh sửa, căn chỉnh, hoặc đơn giản là sau khi ta nhận được bản vẽ từ người khác. Vậy cách đưa bản vẽ về tỷ lệ 1:1 đơn giản, nhanh chóng như thế nào? Các bạn theo dõi nội dung dưới đây để có được lời giải đáp nhé.', 'Tin chuyên ngành', 'Cách chuyển bản vẽ về tỷ lệ 1:1 đơn giản, nhanh chóng', 'cach-chuyen-ban-ve-ve-ty-le-1:1-don-gian-nhanh-chong', NULL, NULL, 'Cách chuyển bản vẽ về tỷ lệ 1:1 đơn giản, nhanh chóng', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1528, 'vi', '', 'Quan hệ cổ đông', 'Thông báo về việc chào bán Cổ phần cho Cổ đông hiện hữu để tăng Vốn điều lệ của Công ty', 'thong-bao-ve-viec-chao-ban-co-phan-cho-co-dong-hien-huu-de-tang-von-dieu-le-cua-cong-ty', NULL, NULL, 'Thông báo về việc chào bán Cổ phần cho Cổ đông hiện hữu để tăng Vốn điều lệ của Công ty', '') ON CONFLICT (entity_id, locale) DO NOTHING;
