INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1530, 'vi', 'CIC tổ chức thành công hội thảo giới thiệu phần mềm OpenFlows Water (WaterGEMS) – Giải pháp mô phỏng thủy lực hỗ trợ chuyển đổi số hệ thống cấp nước tại HueWACO vào ngày 11/9/2025.', 'Tin công ty', 'CIC tổ chức hội thảo giới thiệu giải pháp OpenFlows Water (WaterGEMS) hỗ trợ HueWACO chuyển đổi số hệ thống cấp nước', 'cic-to-chuc-hoi-thao-gioi-thieu-giai-phap-openflows-water-ho-tro-huewaco-chuyen-doi-so-he-thong-cap-nuoc', NULL, NULL, 'CIC tổ chức hội thảo giới thiệu giải pháp OpenFlows Water (WaterGEMS) hỗ trợ HueWACO chuyển đổi số h', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1531, 'vi', 'ZX Lidars tự hào ra mắt sản phẩm mới nhất, ZX300e. Đây là sản phẩm được thiết kế với mục tiêu tối ưu hóa hiệu suất và độ chính xác trong các điều kiện thực tế. ', 'Tin chuyên ngành', 'ZX300e - Định nghĩa lại Chuẩn mực Lidar đo gió ', 'zx300e-dinh-nghia-lai-chuan-muc-lidar-do-gio', NULL, NULL, 'ZX300e - Định nghĩa lại Chuẩn mực Lidar đo gió', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1532, 'vi', 'Vinhomes Green Paradise – siêu dự án tại Cần Giờ với tổng vốn đầu tư 11 tỷ USD hướng đến mục tiêu đạt chứng nhận BREEAM Communities, tiêu chuẩn quốc tế hàng đầu cho quy hoạch đô thị bền vững.', 'Tin chuyên ngành', 'Vinhomes Green Paradise Cần Giờ: Hướng đến đô thị chuẩn ESG theo tiêu chuẩn BREEAM Communities', 'vinhomes-green-paradise-can-gio:-huong-den-do-thi-chuan-esg-theo-tieu-chuan-breeam-communities', NULL, NULL, 'Vinhomes Green Paradise Cần Giờ: Hướng đến đô thị chuẩn ESG theo tiêu chuẩn BREEAM Communities', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1533, 'vi', 'Mới đây, CIC đã hoàn thành  bàn giao Robot lặn chuyên nghiệp FIFISH E-MASTER PLUS của hãng QYSEA (Trung Quốc) cho Công ty Thủy điện Huội Quảng - Bản Chát, đánh dấu một bước tiến quan trọng trong việc đưa công nghệ ROV (Robot điều khiển từ xa) vào phục vụ thực tế tại các công trình thủy điện.', 'Tin công ty', 'CIC hoàn thành bàn giao Robot lặn chuyên nghiệp cho Công ty Thủy Điện Huội Quảng - Bản Chát', 'cic-hoan-thanh-ban-giao-robot-lan-chuyen-nghiep-cho-cong-ty-thuy-dien-huoi-quang-ban-chat', NULL, NULL, 'CIC hoàn thành bàn giao Robot lặn chuyên nghiệp cho Công ty Thủy Điện Huội Quảng - Bản Chát', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1534, 'vi', 'Công ty Cổ phần Công nghệ và Tư vấn CIC đã hoàn tất việc bàn giao bộ thiết bị đo ảnh điện – Electrical Resistivity Tomography (ERT), model Syscal ProSwitch 48 do hãng IRIS Instruments (Pháp) sản xuất, cho Trường Đại học Bách Khoa – Đại học Quốc gia TP. Hồ Chí Minh.', 'Tin công ty', 'CIC bàn giao thiết bị đo ảnh điện Syscal Proswitch 48 cho Trường Đại học Bách Khoa Tp.HCM', 'cic-ban-giao-thiet-bi-do-anh-dien-syscal-proswitch-48-cho-truong-dai-hoc-bach-khoa-tphcm', NULL, NULL, 'CIC bàn giao thiết bị đo ảnh điện Syscal Proswitch 48 cho Trường Đại học Bách Khoa Tp.HCM', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1535, 'vi', 'Trong bối cảnh cuộc cách mạng công nghệ 4.0 ngày càng lan tỏa sâu rộng, trí tuệ nhân tạo đang trở thành “chìa khóa vàng” mở ra kỷ nguyên mới cho ngành xây dựng và hạ tầng. Bài viết này khám phá cách AI đang tái định hình quy trình thiết kế, thi công và quản lý công trình — từ tối ưu hóa chi phí, nâng cao hiệu suất đến đảm bảo an toàn – và nhìn về xu hướng mà các chuyên gia lẫn doanh nghiệp cần chuẩn bị để không bị bỏ lại phía sau.', 'Tin công ty', 'ENR FutureTech 2025: Trí tuệ nhân tạo dẫn dắt tương lai ngành xây dựng ', 'enr-futuretech-2025:-tri-tue-nhan-tao-dan-dat-tuong-lai-nganh-xay-dung', NULL, NULL, 'ENR FutureTech 2025: Trí tuệ nhân tạo dẫn dắt tương lai ngành xây dựng ', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1536, 'vi', 'Là đối tác chính thức của PTV Group, CIC cung cấp phần mềm VISUM cho TEDI South, góp phần nâng tầm năng lực quy hoạch giao thông tại Việt Nam.', 'Tin công ty', 'CIC cung cấp phần mềm quy hoạch giao thông VISUM của PTV Group (Đức) cho TEDI South', 'cic-cung-cap-phan-mem-quy-hoach-giao-thong-visum-cua-ptv-group-duc-cho-tedi-south', NULL, NULL, 'CIC cung cấp phần mềm quy hoạch giao thông VISUM của PTV Group (Đức) cho TEDI South', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1539, 'vi', 'Trí tuệ nhân tạo (AI) đang tạo ra một cuộc cách mạng thực sự trong ngành xây dựng, thay đổi toàn diện từ khâu lên ý tưởng, thiết kế, thi công cho đến vận hành. Việc ứng dụng AI không chỉ mang lại hiệu suất vượt trội mà còn mở ra những tiêu chuẩn mới về độ chính xác và an toàn. Tuy nhiên, đi cùng với những lợi ích to lớn là các rào cản về chi phí và dữ liệu.', 'Tin chuyên ngành', 'AI trong Xây dựng: Ứng dụng thực tế, Công cụ và Lợi ích 2025', 'ai-trong-xay-dung:-ung-dung-thuc-te-cong-cu-va-loi-ich-2025', NULL, NULL, 'AI trong Xây dựng: Ứng dụng thực tế, Công cụ và Lợi ích 2025.', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1537, 'vi', 'Khi nhắc đến enjiCAD, nhiều người dùng thường nghĩ ngay đến một giải pháp CAD mạnh mẽ, thay thế hiệu quả cho các phần mềm đắt đỏ khác trong việc thực hiện các bản vẽ kỹ thuật 2D, đặc biệt là trong lĩnh vực điện. Tuy nhiên, khả năng của enjiCAD không chỉ dừng lại ở đó. Phần mềm này được trang bị hàng loạt tính năng nâng cao và công cụ tiện ích, giúp tối ưu hóa quy trình làm việc, tăng cường hiệu suất và mở rộng phạm vi ứng dụng sang nhiều lĩnh vực khác.', 'Tin chuyên ngành', 'Giới Thiệu Một Số Công Cụ, Tính Năng Hỗ Trợ Ngành Điện Trên enjiCAD', 'gioi-thieu-mot-so-cong-cu-tinh-nang-ho-tro-nganh-dien-tren-enjicad', NULL, NULL, 'Giới Thiệu Một Số Công Cụ, Tính Năng Hỗ Trợ Ngành Điện Trên enjiCAD', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1538, 'vi', 'IDEA StatiCa sẽ ngừng hỗ trợ các phiên bản sản phẩm Expert và Enhanced từ ngày 31/12/2025. Khách hàng cần nâng cấp lên phiên bản mới để đảm bảo quyền truy cập và bảo trì phần mềm.', 'Tin chuyên ngành', 'IDEA StatiCa thông báo ngừng hỗ trợ một số sản phẩm vào cuối năm 2025', 'idea-statica-thong-bao-ngung-ho-tro-mot-so-san-pham-vao-cuoi-nam-2025', NULL, NULL, 'IDEA StatiCa thông báo ngừng hỗ trợ một số sản phẩm vào cuối năm 2025', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1541, 'vi', '', 'Quan hệ cổ đông', 'Thông báo ngày đăng ký cuối cùng thực hiện quyền tham dự ĐHCĐ bất thường lần 2 năm 2025', 'thong-bao-ngay-dang-ky-cuoi-cung-thuc-hien-quyen-tham-du-dhcd-bat-thuong-lan-2-nam-2025', NULL, NULL, 'Thông báo ngày đăng ký cuối cùng thực hiện quyền tham dự ĐHCĐ bất thường lần 2 năm 2025', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1542, 'vi', '', 'Quan hệ cổ đông', 'Thông báo tổ chức Đại hội cổ đông bất thường', 'thong-bao-to-chuc-dai-hoi-co-dong-bat-thuong', NULL, NULL, 'Thông báo tổ chức Đại hội cổ đông bất thường', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1543, 'vi', 'Người dùng từ lâu mong muốn có sự kết nối mượt mà giữa Deswik và Seequent. Với sự tích hợp mới, dữ liệu thiết kế mỏ từ Deswik có thể được chuyển trực tiếp sang Leapfrog thông qua Evo, đảm bảo giữ nguyên độ chính xác cả về hình dạng lẫn thuộc tính và tăng cường sự hợp tác giữa các nhà khoa học địa chất và kỹ sư khai thác mỏ.', 'Tin chuyên ngành', 'Kết nối liền mạch dữ liệu địa chất và kế hoạch khai thác bằng hệ thống Seequent Evo và phần mềm Deswik', 'ket-noi-lien-mach-du-lieu-dia-chat-va-ke-hoach-khai-thac-bang-he-thong-seequent-evo-va-phan-mem-deswik', NULL, NULL, 'Kết nối liền mạch dữ liệu địa chất và kế hoạch khai thác bằng hệ thống Seequent Evo và phần mềm Desw', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1544, 'vi', 'Mới đây, Công ty CIC – đối tác phân phối chính thức các giải pháp đo đạc, khảo sát của hãng CHCNAV tại Việt Nam – đã có buổi làm việc và trình bày giới thiệu đến Công ty Cổ phần Tư vấn Đầu tư và Xây dựng Giao thông Vận tải (TRICC) các giải pháp khảo sát địa hình hiện đại, ứng dụng công nghệ cao trong lĩnh vực thiết kế và thi công hạ tầng giao thông, đặc biệt là đường sắt và công trình giao thông thủy – bộ.', 'Tin công ty', 'CIC giới thiệu các giải pháp khảo sát địa hình của CHCNAV đến Công ty Cổ phần Tư vấn Đầu tư và Xây dựng Giao thông Vận tải (TRICC)', 'cic-gioi-thieu-cac-giai-phap-khao-sat-dia-hinh-cua-chcnav-den-cong-ty-co-phan-tu-van-dau-tu-va-xay-dung-giao-thong-van-tai-tricc', NULL, NULL, 'CIC giới thiệu các giải pháp khảo sát địa hình của CHCNAV đến Công ty Cổ phần Tư vấn Đầu tư và Xây d', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1545, 'vi', 'Vừa qua, Công ty Cổ phần Công nghệ và Tư vấn CIC và hãng Heat Transfer Research, Inc. (HTRI) tổ chức thành công hội thảo giới thiệu các giải pháp phần mềm tính toán và tối ưu hóa truyền nhiệt, với sự tham dự của đội ngũ kỹ sư và chuyên gia từ Công ty Cổ phần Tư vấn Xây dựng Điện 4 (PECC4).', 'Tin công ty', 'CIC phối hợp cùng HTRI tổ chức hội thảo giới thiệu phần mềm tối ưu hóa truyền nhiệt cho PECC4', 'cic-phoi-hop-cung-htri-to-chuc-hoi-thao-gioi-thieu-phan-mem-toi-uu-hoa-truyen-nhiet-cho-pecc4', NULL, NULL, 'CIC phối hợp cùng HTRI tổ chức hội thảo giới thiệu phần mềm tối ưu hóa truyền nhiệt cho PECC4', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1546, 'vi', 'Ngành xây dựng đang bộc lộ nhiều thách thức về chi phí, tiến độ, an toàn lao động và chất lượng dự án. Trong bối cảnh chuyển đổi số, trí tuệ nhân tạo (AI) đang trở thành động lực chiến lược giúp doanh nghiệp vượt qua những bài toán cổ hữu. Từ thiết kế đến vận hành, từ giám sát đến dự đoán, AI trong ngành xây dựng mở ra kỷ nguyên mới: thông minh hơn, an toàn hơn, bền vững hơn.', 'Tin chuyên ngành', 'AI trong ngành xây dựng: Chìa khóa cho tương lai bền vững và chuyển đổi số hiệu quả', 'ai-trong-nganh-xay-dung:-chia-khoa-cho-tuong-lai-ben-vung-va-chuyen-doi-so-hieu-qua', NULL, NULL, 'AI trong ngành xây dựng: Chìa khóa cho tương lai bền vững và chuyển đổi số hiệu quả', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1547, 'vi', 'Phiên bản IDEA StatiCa 25.1 chính thức phát hành, mang đến những cải tiến đột phá nhằm loại bỏ sự phức tạp trong mô hình hóa và các rào cản thủ công. Bản cập nhật này tập trung vào tính năng neo mở rộng bao gồm các tấm bê tông đúc sẵn và thiết kế đa bề mặt; Thiết kế hàng loạt và cập nhật liên kết với báo cáo nhanh hơn, đồng thời cải tạo bê tông hiện có bằng cốt thép trơn và gân cáp không liên kết. Ngoài ra, trong phiên bản mới còn có quy trình làm việc ETABS/SAP2000 sang Detail mới cho các kiểm tra tường bê tông chịu cắt.', 'Tin chuyên ngành', 'Phát hành IDEA StatiCa 25.1 nâng cấp toàn diện quy trình làm việc cho kỹ sư kết cấu thép', 'phat-hanh-idea-statica-251-nang-cap-toan-dien-quy-trinh-lam-viec-cho-ky-su-ket-cau-thep', NULL, NULL, 'Phát hành IDEA StatiCa 25.1 nâng cấp toàn diện quy trình làm việc cho kỹ sư kết cấu thép', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1548, 'vi', '', 'Quan hệ cổ đông', 'Thông báo Dời ngày tổ chức ĐHCĐ bất thường lần 2 năm 2025', 'thong-bao-doi-ngay-to-chuc-dhcd-bat-thuong-lan-2-nam-2025', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1549, 'vi', 'Công ty CIC cung cấp dịch vụ tư vấn LCA và chứng nhận EPD, hỗ trợ doanh nghiệp đáp ứng tiêu chuẩn xuất khẩu vào các thị trường EU, Mỹ, Úc và tham gia chuỗi cung ứng toàn cầu. Gần đây, CIC đã khởi động dự án tư vấn LCA – EPD cho sản phẩm ván ép xuất khẩu tại một nhà máy ở Bắc Giang.', 'Tin công ty', 'CIC tư vấn LCA & Chứng nhận EPD cho sản phẩm ngành gỗ', 'cic-tu-van-lca-amp;-chung-nhan-epd-cho-san-pham-nganh-go', NULL, NULL, 'CIC tư vấn LCA & Chứng nhận EPD cho sản phẩm ngành gỗ', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1569, 'vi', 'Perform3D Phiên bản v11.0.0 được phát hành ngày 9/12/2025 với các tính năng mới và cải tiến, tăng hiệu suất làm việc.', 'Tin chuyên ngành', 'Các tính năng mới và cải tiến của phần mềm Perform3D phiên bản mới nhất', 'cac-tinh-nang-moi-va-cai-tien-cua-phan-mem-perform3d-phien-ban-moi-nhat', NULL, NULL, 'Các tính năng mới và cải tiến của phần mềm Perform3D phiên bản mới nhất', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1550, 'vi', 'Computers and Structures, Inc. (CSI) – nhà cung cấp phần mềm kết cấu hàng đầu thế giới – vừa chính thức phát hành ETABS v23.0.0 và SAFE v23.0.0, đánh dấu bước nâng cấp toàn diện về hiệu năng, khả năng phân tích – thiết kế và tích hợp tiêu chuẩn mới, đặc biệt là TCVN 5574:2018 dành cho thị trường Việt Nam.', 'Tin chuyên ngành', 'ETABS v23 & SAFE v23 chính thức phát hành, tích hợp TCVN 5574:2018', 'etabs-v23-amp;-safe-v23-chinh-thuc-phat-hanh-tich-hop-tcvn-5574:2018', NULL, NULL, 'ETABS v23 & SAFE v23 chính thức phát hành, tích hợp TCVN 5574:2018', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1551, 'vi', '', 'Quan hệ cổ đông', 'Nghị quyết của HĐQT về việc xử lý Cổ phần lẻ và cổ phần không bán hết', 'nghi-quyet-cua-hdqt-ve-viec-xu-ly-co-phan-le-va-co-phan-khong-ban-het', NULL, NULL, 'Nghị quyết của HĐQT về việc xử lý Cổ phần lẻ và cổ phần không bán hết', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1552, 'vi', 'BIM manager (quản lý BIM) là một chuyên gia xử lý quy trình triển khai BIM qua các giai đoạn khác nhau của quá trình thực hiện dự án, duy trì và kiểm soát tất cả các quy trình của dự án.', 'Tin chuyên ngành', 'BIM Manager là gì? Vai trò và quy trình quản lý BIM', 'bim-manager-la-gi-vai-tro-va-quy-trinh-quan-ly-bim', NULL, NULL, 'BIM Manager là gì? Vai trò và quy trình quản lý BIM', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1553, 'vi', 'CIC thông báo chương trình ưu đãi đặc biệt dành riêng cho các khách hàng quan tâm phần mềm IDEA Statica nhân dịp ra mắt phiên bản mới nhất.', 'Tin khuyến mại', 'ƯU ĐÃI CHO KHÁCH HÀNG MUA IDEA STATICA NHÂN DỊP RA MẮT PHIÊN BẢN MỚI', 'uu-dai-cho-khach-hang-mua-idea-statica-nhan-dip-ra-mat-phien-ban-moi', NULL, NULL, 'ƯU ĐÃI CHO KHÁCH HÀNG MUA IDEA STATICA NHÂN DỊP RA MẮT PHIÊN BẢN MỚI', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1554, 'vi', 'Công ty  CIC được vinh danh tại Lễ Trao Giải Đối Tác Xuất Sắc Bentley 2025, Đạt Mốc "1 Million Dollar Award",  ghi nhận những thành tựu vượt trội trong việc thúc đẩy công nghệ kỹ thuật hạ tầng.', 'Tin công ty', 'CIC được vinh danh tại Lễ Trao Giải Đối Tác Xuất Sắc Bentley 2025, Đạt Mốc "1 Million Dollar Award"', 'cic-duoc-vinh-danh-tai-le-trao-giai-doi-tac-xuat-sac-bentley-2025-dat-moc1-million-dollar-award-', NULL, NULL, 'CIC được vinh danh tại Lễ Trao Giải Đối Tác Xuất Sắc Bentley 2025, Đạt Mốc "1 Million Dollar Award"', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1555, 'vi', 'Lisp dịch bản vẽ translate text là công cụ giúp dịch ngôn ngữ trực tiếp trong enjiCAD - giúp các kỹ sư tiết kiệm thời gian và công sức.', 'Tin chuyên ngành', 'Giới thiệu LISP dịch ngôn ngữ trực tiếp trong enjiCAD', 'gioi-thieu-lisp-dich-ngon-ngu-truc-tiep-trong-enjicad', NULL, NULL, 'Giới thiệu LISP dịch ngôn ngữ trực tiếp trong enjiCAD', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1556, 'vi', 'Công ty CP Công nghệ và Tư vấn CIC vinh dự đồng hành cùng đối tác PYTHA tại Hội chợ Quốc tế lần thứ 16 Ngành Công nghiệp Chế biến Gỗ Việt Nam -VietnamWood 2025, diễn ra từ ngày 19–22/11/2025 tại Trung tâm Hội chợ &amp; Triển lãm Sài Gòn (SECC), TP. Hồ Chí Minh.', 'Tin công ty', 'CIC hợp tác cùng PYTHA tham gia Triển lãm VietnamWood 2025', 'cic-hop-tac-cung-pytha-tham-gia-trien-lam-vietnamwood-2025', NULL, NULL, 'CIC hợp tác cùng PYTHA tham gia Triển lãm VietnamWood 2025', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1557, 'vi', 'Trimble đang mở rộng danh mục giải pháp quan trắc tự động với nền tảng IoT địa kỹ thuật từ Worldsensing, tạo nên một hệ sinh thái giám sát địa kỹ thuật – địa không gian toàn diện nhất trên thị trường hiện nay.', 'Tin chuyên ngành', 'Worldsensing hỗ trợ mở rộng danh mục giám sát tự động địa kỹ thuật của Trimble bằng công nghệ IoT địa kỹ thuật', 'worldsensing-ho-tro-mo-rong-danh-muc-giam-sat-tu-dong-dia-ky-thuat-cua-trimble-bang-cong-nghe-iot-dia-ky-thuat', NULL, NULL, 'Worldsensing hỗ trợ mở rộng danh mục giám sát tự động địa kỹ thuật của Trimble bằng công nghệ IoT đị', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1558, 'vi', 'Ngành gia công nhôm kính đang chuyển mình mạnh mẽ nhờ sự phát triển của công nghệ tự động hóa và kết nối dữ liệu. Trong xu hướng đó, Emmegi Group – thương hiệu hàng đầu thế giới về thiết bị gia công nhôm – đã giới thiệu +QUADRA, dòng máy CNC gia công nhôm kính đa chức năng được xem như “trái tim” của nhà máy thông minh (Smart Factory) thế hệ mới.', 'Tin chuyên ngành', '+QUADRA – Bước tiến của máy CNC gia công nhôm kính trong kỷ nguyên nhà máy thông minh', 'quadra-–-buoc-tien-cua-may-cnc-gia-cong-nhom-kinh-trong-ky-nguyen-nha-may-thong-minh', NULL, NULL, '+QUADRA – Bước tiến của máy CNC gia công nhôm kính trong kỷ nguyên nhà máy thông minhNgành gia công', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1559, 'vi', 'Webinar được IDEA StatiCA tổ chức vào ngày 20/11/2025,  hướng dẫn thiết kế tường chuyển (Wall Transfer) từ ETABS sang IDEA StatiCa với CSFM, kiểm tra ULS–SLS và quy trình phân tích chi tiết cho kỹ sư kết cấu.', 'Tin chuyên ngành', 'Hội thảo trực tuyến: Thiết kế tường chuyển (Wall Transfer) – từ ETABS sang IDEA StatiCa', 'hoi-thao-truc-tuyen:-thiet-ke-tuong-chuyen-wall-transfer-–-tu-etabs-sang-idea-statica', NULL, NULL, 'Hội thảo trực tuyến: Thiết kế tường chuyển (Wall Transfer) – từ ETABS sang IDEA StatiCa', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1560, 'vi', 'VietnamWood 2025 khép lại thành công với điểm nhấn từ gian hàng CIC & PYTHA. Khám phá giải pháp PYTHA 3D CAD kết nối sản xuất và tính năng AI Assistant V26 mới nhất.', 'Tin công ty', 'VietnamWood 2025: Dấu ấn công nghệ từ CIC & PYTHA với giải pháp 3D CAD và AI đột phá', 'vietnamwood-2025:-dau-an-cong-nghe-tu-cic-amp;-pytha-voi-giai-phap-3d-cad-va-ai-dot-pha', NULL, NULL, 'VietnamWood 2025: Dấu ấn công nghệ từ CIC & PYTHA với giải pháp 3D CAD và AI đột phá', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1561, 'vi', 'Ngày 24/11/2025 tại TP.HCM, Hội thảo chuyên đề "Công nghệ số và AI trong ngành Xây dựng" do BIMAGE Consulting và CIC tổ chức đã thu hút sự quan tâm lớn của giới chuyên môn. Sự kiện không chỉ phác họa bức tranh toàn cảnh về thị trường xây dựng Việt Nam trong kỷ nguyên 4.0 mà còn mang đến những giải pháp công nghệ giúp giải quyết các "điểm nghẽn" về chi phí và tiến độ.', 'Tin công ty', 'CIC và BIMAGE  Consulting tổ chức thành công hội thảo Công nghệ số và AI trong ngành xây dựng', 'cic-va-bimageconsulting-to-chuc-thanh-cong-hoi-thao-cong-nghe-so-va-ai-trong-nganh-xay-dung', NULL, NULL, 'CIC và BIMAGE  Consulting tổ chức thành công hội thảo Công nghệ số và AI trong ngành xây dựng', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1562, 'vi', 'Deswik và Ventsim là hai phần mềm quan trọng được sử dụng trong ngành công nghiệp khai thác mỏ, đặc biệt là khai thác dưới lòng đất. Chúng kết hợp với nhau để tạo ra các mô hình chính xác hơn, giúp các kỹ sư quản lý nhiệt độ và luồng không khí (thông gió) trong mỏ hiệu quả hơn.', 'Tin chuyên ngành', 'Sức Mạnh Từ Bộ Đôi phần mềm Deswik và Ventsim trong mô phỏng nhiệt độ tầng (strata hear)', 'suc-manh-tu-bo-doi-phan-mem-deswik-va-ventsim-trong-mo-phong-nhiet-do-tang-strata-hear', NULL, NULL, 'Sức Mạnh Từ Bộ Đôi phần mềm Deswik và Ventsim trong mô phỏng nhiệt độ tầng (strata hear)', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1563, 'vi', 'enjiCAD 2026 chính thức ra mắt, đánh dấu bước tiến mới trong công nghệ thiết kế CAD hiện đại. Phiên bản năm nay mang đến hiệu suất vượt trội, giao diện trực quan hơn cùng hàng loạt công cụ thông minh giúp tối ưu quy trình thiết kế.', 'Tin chuyên ngành', 'enjiCAD 2026 chính thức phát hành với hàng loạt công cụ thông minh', 'enjicad-2026-chinh-thuc-phat-hanh-voi-hang-loat-cong-cu-thong-minh', NULL, NULL, 'enjiCAD 2026 chính thức phát hành với hàng loạt công cụ thông minh', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1564, 'vi', 'Ngày 26/11 tại Bộ Xây dựng, Hội thảo chuyên đề "Công nghệ số và AI trong ngành Xây dựng" do BIMAGE Consulting và CIC tổ chức đã mang đến những giải pháp công nghệ giúp giải quyết các "điểm nghẽn" về chi phí và tiến độ đối với hoạt động xây dựng.', 'Tin công ty', 'CIC tổ chức thành công hội thảo AI và Công nghệ số tại Hà Nội', 'cic-to-chuc-thanh-cong-hoi-thao-ai-va-cong-nghe-so-tai-ha-noi', NULL, NULL, 'Công nghệ số và AI tháo gỡ điểm nghẽn của ngành xây dựng như thế nào?', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1565, 'vi', 'Ngày 27/11/2025, Công ty Cổ phần Công nghệ và Tư vấn CIC đã long trọng tổ chức Lễ kỷ niệm 35 năm thành lập, đánh dấu một hành trình bền bỉ đưa công nghệ tiên tiến vào phục vụ ngành kỹ thuật Việt Nam. Sự kiện quy tụ lãnh đạo Bộ Xây dựng, các cơ quan quản lý, đối tác quốc tế, khách hàng trên cả nước cùng nhiều thế hệ lãnh đạo – cán bộ CIC.', 'Tin công ty', 'CIC kỷ niệm 35 năm thành lập: Dấu mốc quan trọng trên hành trình làm chủ công nghệ cho ngành kỹ thuật Việt Nam', 'cic-ky-niem-35-nam-thanh-lap:-dau-moc-quan-trong-tren-hanh-trinh-lam-chu-cong-nghe-cho-nganh-ky-thuat-viet-nam', NULL, NULL, 'CIC kỷ niệm 35 năm thành lập: Dấu mốc quan trọng trên hành trình làm chủ công nghệ cho ngành kỹ thuậ', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1566, 'vi', 'Công ty Cổ phần Công nghệ và Tư vấn CIC xin trân trọng gửi tới Quý khách hàng và Quý đối tác lời cảm ơn chân thành và sâu sắc nhất đã dành thời gian tham dự sự kiện, gửi lời chúc mừng và luôn đồng hành cùng CIC trong 35 năm qua.', 'Tin công ty', 'THƯ CẢM ƠN', 'thu-cam-on', NULL, NULL, 'THƯ CẢM ƠN', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1568, 'vi', 'Tháng 12, CIC tuyển dụng nhiều vị trí hấp dẫn: Senior BIM, Quản lý chất lượng dự án BIM, Sales Engineer, Nhân viên kinh doanh giải pháp AI, Technical Support.', 'Tin tuyển dụng', 'CIC Tuyển Dụng: BIM, AI, Sales Engineer & Hỗ Trợ Kỹ Thuật', 'cic-tuyen-dung:-bim-ai-sales-engineer-amp;-ho-tro-ky-thuat', NULL, NULL, 'CIC Tuyển Dụng: BIM, AI, Sales Engineer & Hỗ Trợ Kỹ Thuật', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1567, 'vi', 'Giải pháp OpenSpace ứng dụng BIM và AI trong xây dựng của CIC đạt giải Ba tại Hội nghị Khoa học Cán bộ trẻ toàn quốc  lần thứ XVII.', 'Tin công ty', 'Giải pháp ứng dụng BIM và AI trong xây dựng của CIC đạt giải Ba tại Hội nghị Khoa học Cán bộ trẻ toàn quốc', 'giai-phap-ung-dung-bim-va-ai-trong-xay-dung-cua-cic-dat-giai-ba-tai-hoi-nghi-khoa-hoc-can-bo-tre-toan-quoc', NULL, NULL, 'Giải pháp ứng dụng BIM và AI trong xây dựng của CIC đạt giải Ba tại Hội nghị Khoa học Cán bộ trẻ toà', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1570, 'vi', '8 nhóm công trình được miễn giấy phép xây dựng sau khi Quốc hội chính thức thông qua Luật Xây dựng (sửa đổi), đặt ra yêu cầu cấp thiết cho các Chủ đầu tư, Nhà thầu và Đơn vị tư vấn trong việc chuẩn hóa thiết kế, tuân thủ quy hoạch và kiểm soát chi phí ngay từ đầu.', 'Tin chuyên ngành', 'Chi Tiết 08 Nhóm Công Trình Được Miễn Giấy Phép Xây Dựng (Cập Nhật Mới Nhất)', 'chi-tiet-08-nhom-cong-trinh-duoc-mien-giay-phep-xay-dung-cap-nhat-moi-nhat', NULL, NULL, 'Chi Tiết 08 Nhóm Công Trình Được Miễn Giấy Phép Xây Dựng (Cập Nhật Mới Nhất)', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1571, 'vi', 'Holcim và 44.01 triển khai dự án thí điểm khoáng hóa CO₂ tại UAE, lần đầu kết hợp thu giữ CO₂ từ sản xuất xi măng với công nghệ khoáng hóa tại chỗ, hướng tới Net Zero 2050.', 'Tin chuyên ngành', 'Lần đầu tiên trên thế giới khoáng hóa CO₂ trực tiếp từ sản xuất xi măng', 'lan-dau-tien-tren-the-gioi-khoang-hoa-co₂-truc-tiep-tu-san-xuat-xi-mang', NULL, NULL, 'Lần đầu tiên trên thế giới khoáng hóa CO₂ trực tiếp từ sản xuất xi măng', '') ON CONFLICT (entity_id, locale) DO NOTHING;
