INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1573, 'vi', 'Ngày 19/12/2025 vừa qua, dự án xây dựng mới Nhà văn hóa Thanh niên TP.HCM đã chính thức khởi công. Công ty CIC vinh dự được tham gia dự án với vai trò tư vấn và triển khai BIM, góp phần đặt nền móng số hóa cho công trình biểu tượng này.', 'Tin công ty', 'CIC đồng hành triển khai BIM cho dự án xây mới Nhà Văn hóa Thanh Niên TP.HCM', 'cic-dong-hanh-trien-khai-bim-cho-du-an-xay-moi-nha-van-hoa-thanh-nien-tphcm', NULL, NULL, 'CIC đồng hành triển khai BIM cho dự án xây mới Nhà Văn hóa Thanh Niên TP.HCM', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1574, 'vi', 'Phần mềm GEO5 phiên bản 2026 đánh dấu một bước nâng cấp quan trọng với hàng loạt cải tiến về hiếu suất và độ chính xác thiết kế. Phiên bản mới này giúp kỹ sư rút ngắn thời gian thiết kế, giảm sai sót khi chuyển dữ liệu và nâng cao độ tin cậy của kết quả tính toán trong các dự án thực tế.', 'Tin chuyên ngành', 'GEO5 2026 nâng cấp toàn diện công cụ địa kỹ thuật, tăng mạnh hiệu suất và độ chính xác thiết kế', 'geo5-2026-nang-cap-toan-dien-cong-cu-dia-ky-thuat-tang-manh-hieu-suat-va-do-chinh-xac-thiet-ke', NULL, NULL, 'GEO5 2026 nâng cấp toàn diện công cụ địa kỹ thuật, tăng mạnh hiệu suất và độ chính xác thiết kế', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1575, 'vi', '', 'Quan hệ cổ đông', 'Thông báo hoàn thành thủ tục tăng vốn điều lệ và cấp Giấy chứng nhận sở hữu cổ phần theo mẫu mới', 'thong-bao-hoan-thanh-thu-tuc-tang-von-dieu-le-va-cap-giay-chung-nhan-so-huu-co-phan-theo-mau-moi', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1577, 'vi', 'PV Elite 28 đã chính thức ra mắt! Giải pháp hàng đầu trong thiết kế bồn bể áp lực và thiết bị trao đổi nhiệt, tiếp tục bứt phá với phiên bản mới nhất.', 'Tin chuyên ngành', 'Phát hành PV Elite V28 với nhiều tính năng cải tiến hiệu suất', 'phat-hanh-pv-elite-v28-voi-nhieu-tinh-nang-cai-tien-hieu-suat', NULL, NULL, 'Phát hành PV Elite V28 với nhiều tính năng cải tiến hiệu suất', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1578, 'vi', 'Ngày 16/1/2026, Công ty CP Công nghệ và Tư vấn CIC tổ chức tổng kết hoạt động kinh doanh năm 2025 và Định hướng phát triển 2026.', 'Tin công ty', 'CIC tổng kết hoạt động kinh doanh năm 2025 và định hướng phát triển giai đoạn mới', 'cic-tong-ket-hoat-dong-kinh-doanh-nam-2025-va-dinh-huong-phat-trien-giai-doan-moi', NULL, NULL, 'CIC tổng kết hoạt động kinh doanh năm 2025 và định hướng phát triển giai đoạn mới', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1635, 'vi', 'Ngày 24/04/2026, tại Tầng 4 tòa nhà VG Building, 235 Nguyễn Trãi, Hà Nội, Công ty Cổ phần Công nghệ và Tư vấn CIC đã tổ chức thành công Đại hội đồng cổ đông thường niên năm 2026.', 'Tin công ty', 'CIC tổ chức thành công Đại hội đồng cổ đông thường niên 2026', 'cic-to-chuc-thanh-cong-dai-hoi-dong-co-dong-thuong-nien-2026', NULL, NULL, 'CIC tổ chức thành công Đại hội đồng cổ đông thường niên 2026', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1579, 'vi', 'CIC ghi dấu ấn tại Hội thảo Khoa học Công nghệ và Đổi mới Sáng tạo, chuyển đổi số ngành VLXD với bài tham luận mang tính định hướng về bộ công cụ LCA-EPD cho doanh nghiệp hướng tới phát triển bền vững.', 'Tin công ty', 'CIC ghi dấu ấn tại Hội thảo Khoa học Công nghệ và Đổi mới Sáng tạo, chuyển đổi số ngành VLXD', 'cic-ghi-dau-an-tai-hoi-thao-khoa-hoc-cong-nghe-va-doi-moi-sang-tao-chuyen-doi-so-nganh-vlxd', NULL, NULL, 'CIC ghi dấu ấn tại Hội thảo Khoa học Công nghệ và Đổi mới Sáng tạo, chuyển đổi số ngành VLXD', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1580, 'vi', 'Trong tính toán kết cấu, thiết kế bản mã chân cột (base plate) là một nhiệm vụ quen thuộc nhưng chưa bao giờ đơn giản. Từ việc đảm bảo khả năng chịu lực đến việc tuân thủ các tiêu chuẩn nghiêm ngặt như AISC hay ACI, các kỹ sư luôn cần một công cụ mạnh mẽ để vừa đảm bảo an toàn, vừa tiết kiệm thời gian. Dưới đây là tổng hợp 5 loại bản mã chân cột phổ biến nhất mà IDEA StatiCa có thể giúp bạn xử lý triệt để, từ khâu mô hình hóa đến kiểm tra.', 'Tin chuyên ngành', 'Tối Ưu Hóa Thiết Kế Bản Mã Chân Cột Với Giải Pháp Toàn Diện Từ IDEA StatiCa', 'toi-uu-hoa-thiet-ke-ban-ma-chan-cot-voi-giai-phap-toan-dien-tu-idea-statica', NULL, NULL, 'Tối Ưu Hóa Thiết Kế Bản Mã Chân Cột Với Giải Pháp Toàn Diện Từ IDEA StatiCa', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1581, 'vi', 'Seequent giải quyết bài toán xác định vật liệu chưa nổ (UXO) thông qua một hệ sinh thái công nghệ với phần mềm Oasis montaj và UXO Marine là nền tảng cốt lõi. Giải pháp hỗ trợ toàn bộ vòng đời dự án.', 'Tin chuyên ngành', 'Cách tiếp cận công nghệ của Seequent cho các dự án ngoài khơi trong quản lý rủi ro vật liệu chưa nổ bằng phần mềm Oasis montaj', 'cach-tiep-can-cong-nghe-cua-seequent-cho-cac-du-an-ngoai-khoi-trong-quan-ly-rui-ro-vat-lieu-chua-no-bang-phan-mem-oasis-montaj', NULL, NULL, 'Cách tiếp cận công nghệ của Seequent cho các dự án ngoài khơi trong quản lý rủi ro vật liệu chưa nổ', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1582, 'vi', 'Tiếp nối thành công của phiên bản v11, sau 3 năm chờ đợi, Hãng CSI đã chính thức phát hành phiên bản kế nhiệm CSiCol v12 với nhiều cải tiến vượt trội và sử dụng hình thức cấp phép bằng Đăng nhập đám mây (Cloud Sign-in Licensing).', 'Tin chuyên ngành', 'CSiCol v12.0.0 - Phiên bản mới nhất từ CSI chính thức ra mắt', 'csicol-v1200---phien-ban-moi-nhat-tu-csi-chinh-thuc-ra-mat', NULL, NULL, 'CSiCol v12.0.0 - Phiên bản mới nhất từ CSI chính thức ra mắt', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1583, 'vi', 'Công ty CP Công nghệ và Tư vấn CIC cung cấp hệ thống thử động biến dạng lớn (PDA) GPC – Pile Driving Analysis cho Công ty Cổ phần Tư vấn Xây dựng và Đầu tư Tổng hợp, góp phần tăng cường năng lực kiểm tra – nghiệm thu cọc tại hiện trường theo hướng nhanh, chính xác và không phá hủy.', 'Tin công ty', 'CIC Cung Cấp Thiết Bị Thí Nghiệm Thử Động Biến Dạng Lớn (PDA) Cho Công Ty Cổ Phần Tư Vấn Xây Dựng Và Đầu Tư Tổng Hợp', 'cic-cung-cap-thiet-bi-thi-nghiem-thu-dong-bien-dang-lon-pda-cho-cong-ty-co-phan-tu-van-xay-dung-va-dau-tu-tong-hop', NULL, NULL, 'Thiết Bị Thí Nghiệm Thử Động Biến Dạng Lớn (PDA) GPC: Giải Pháp Kiểm Định Cọc Chuyên Sâu', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1584, 'vi', 'Ngày 29/1/2026, Hội thảo trực tuyến giới thiệu "HiCAD - Giải pháp CAD 3D cho Kết cấu thép và Mặt dựng (Facade)"  do công ty CIC và ISD Group tổ chức thu hút hơn 60 khách mời đến từ các doanh nghiệp hoạt động trong lĩnh vực thiết kế thi công kết cấu thép và mặt dựng nhôm kính, kết cấu bao che công trình.  Sự kiện này không đơn thuần là một buổi giới thiệu giải pháp công nghệ mà còn bước đầu đáp ứng nhu cầu tự động hóa thiết kế và sản xuất của ngành xây dựng nói chung.', 'Tin công ty', 'CIC tổ chức thành công hội thảo HiCAD - Giải pháp CAD 3D cho Kết cấu thép và Mặt dựng (Facade)', 'cic-to-chuc-thanh-cong-hoi-thao-hicad-giai-phap-cad-3d-cho-ket-cau-thep-va-mat-dung-facade', NULL, NULL, 'CIC tổ chức thành công hội thảo HiCAD - Giải pháp CAD 3D cho Kết cấu thép và Mặt dựng (Facade)', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1585, 'vi', 'Trong phân tích thiết kế kết cấu, phần mềm RAM Concept là phần mềm chuyên dụng để phân tích và thiết kế hệ thống sàn bê tông, đặc biệt là sàn phẳng, sàn có dầm và sàn dự ứng lực (PT). Với việc ra mắt phiên bản RAM Concept 2025 (phát hành tháng 12/2025), Hãng Bentley tiếp tục mang đến nhiều cập nhật quan trọng về tiêu chuẩn thiết kế, xử lý tải trọng và tối ưu hóa quy trình cài đặt, giúp kỹ sư nâng cao độ chính xác trong tính toán.', 'Tin chuyên ngành', 'RAM Concept 2025: Bước Cải Tiến Mới Trong Thiết Kế Sàn Bê Tông Dự Ứng Lực', 'ram-concept-2025:-buoc-cai-tien-moi-trong-thiet-ke-san-be-tong-du-ung-luc', NULL, NULL, 'RAM Concept 2025: Bước Cải Tiến Mới Trong Thiết Kế Sàn Bê Tông Dự Ứng Lực', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1586, 'vi', 'Ngày 5/2/2026, Hãng IDEA StatiCA tổ chức hội thảo trực tuyến với chủ đề Thiết kế tường chuyển ngầm an toàn – từ ETABS sang IDEA StatiCa. Trân trọng kính  mời Quý khách hàng đăng ký tham gia.', 'Tin chuyên ngành', 'Webinar tháng 2/2026: Thiết kế tường chuyển ngầm an toàn – từ ETABS sang IDEA StatiCa', 'webinar-thang-22026:-thiet-ke-tuong-chuyen-ngam-an-toan-–-tu-etabs-sang-idea-statica', NULL, NULL, 'Webinar tháng 2/2026: Thiết kế tường chuyển ngầm an toàn – từ ETABS sang IDEA StatiCA', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1587, 'vi', 'SAP2000 v27.0.0 vừa được phát hành đã cập nhật tiêu chuẩn thiết kế mới và tối ưu hóa khả năng mô hình hóa.', 'Tin chuyên ngành', 'SAP2000 v27.0.0 chính thức phát hành', 'sap2000-v2700-chinh-thuc-phat-hanh', NULL, NULL, 'SAP2000 v27.0.0 chính thức phát hành', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1588, 'vi', 'Vừa qua công ty CIC ra mắt phiên bản enjiCAD cho hệ điều hành MacOS song hành cùng với enjiCAD Windows. Đây là phiên bản giúp cho người dùng Apple có thể trải nghiệm được phần mềm enjiCAD.', 'Tin chuyên ngành', 'Giới thiệu enjiCAD cho MacOS', 'gioi-thieu-enjicad-cho-macos', NULL, NULL, 'Giới thiệu enjiCAD cho MacOS', '') ON CONFLICT (entity_id, locale) DO NOTHING;
