INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1592, 'vi', 'Bắt đầu từ năm 2026, Công ty CIC chính thức chuyển trụ sở làm việc về Tòa nhà VG Building, 235 Nguyễn Trãi, Thanh Xuân, Hà Nội. Để thuận tiện cho việc liên hệ công tác, chúng tôi xin gửi đến Quý vị chi tiết địa chỉ mới của công ty', 'Tin công ty', 'CIC THÔNG BÁO THAY ĐỔI ĐỊA CHỈ TRỤ SỞ BẮT ĐẦU TỪ NĂM 2026', 'cic-thong-bao-thay-doi-dia-chi-tru-so-bat-dau-tu-nam-2026', NULL, NULL, 'CIC THÔNG BÁO THAY ĐỔI ĐỊA CHỈ TRỤ SỞ BẮT ĐẦU TỪ NĂM 2026', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1593, 'vi', 'Quyết định 263/QĐ-TTg được ban hành ngày 09/02/2026 không chỉ đơn thuần là việc công bố số liệu. Đối với 110 cơ sở thuộc ngành Nhiệt điện, Sắt thép và Xi măng, đây là "phát súng" chính thức bắt đầu kỷ nguyên quản trị doanh nghiệp bằng hạn ngạch phát thải. ', 'Tin chuyên ngành', 'Hướng dẫn thực thi Quyết định 263/QĐ-TTg: Lộ trình giảm phát thải và quản lý hạn ngạch cho doanh nghiệp', 'huong-dan-thuc-thi-quyet-dinh-263qd-ttg:-lo-trinh-giam-phat-thai-va-quan-ly-han-ngach-cho-doanh-nghiep', NULL, NULL, 'Hướng dẫn thực thi Quyết định 263/QĐ-TTg: Lộ trình giảm phát thải và quản lý hạn ngạch cho doanh ngh', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1594, 'vi', 'Bộ Nông nghiệp & Môi trường vừa chính thức ban hành Thông tư số 11/2026/TT-BNNMT quy định về quản lý và vận hành Hệ thống đăng ký quốc gia về hạn ngạch phát thải khí nhà kính và tín chỉ carbon. Thông tư có hiệu lực từ ngày 30/3/2026, đánh dấu bước hoàn thiện hạ tầng pháp lý quan trọng để Việt Nam chính thức vận hành sàn giao dịch carbon trong nước.', 'Tin chuyên ngành', 'Thông tư số 11/2026/TT-BNNMT: Nền tảng pháp lý then chốt cho thị trường carbon Việt Nam', 'thong-tu-so-112026tt-bnnmt:-nen-tang-phap-ly-then-chot-cho-thi-truong-carbon-viet-nam', NULL, NULL, 'Thông tư số 11/2026/TT-BNNMT: Nền tảng pháp lý then chốt cho thị trường carbon Việt Nam', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1595, 'vi', 'Khám phá vai trò thực sự của AI trong ngành xây dựng. Cùng tìm hiểu lý do tại sao việc đưa ra quyết định tốt hơn lại quan trọng hơn các công cụ nhanh hơn.', 'Tin chuyên ngành', 'AI Trong Ngành Xây Dựng: Tại Sao Quyết Định Tốt Hơn Lại Quan Trọng Hơn Công Cụ Nhanh Hơn', 'ai-trong-nganh-xay-dung:-tai-sao-quyet-dinh-tot-hon-lai-quan-trong-hon-cong-cu-nhanh-hon', NULL, NULL, 'AI Trong Ngành Xây Dựng: Tại Sao Quyết Định Tốt Hơn Lại Quan Trọng Hơn Công Cụ Nhanh Hơn', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1596, 'vi', 'Trong môi trường làm việc hiện đại, nơi nhân sự có thể làm việc tại văn phòng, tại nhà hoặc di chuyển liên tục thì tính linh hoạt của license phần mềm không còn là lựa chọn, mà là yêu cầu bắt buộc.', 'Tin chuyên ngành', 'Vì Sao Foxit PDF Editor Linh Hoạt Hơn Adobe Trong Quản Lý License?', 'vi-sao-foxit-pdf-editor-linh-hoat-hon-adobe-trong-quan-ly-license', NULL, NULL, 'Vì Sao Foxit PDF Editor Linh Hoạt Hơn Adobe Trong Quản Lý License?', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1597, 'vi', 'Chuyên gia năng lượng và cố vấn kỹ thuật của DNV vừa hoàn tất quá trình phân loại IEC độc lập cho thiết bị Lidar đo gió ZX 300e. Kết quả xác nhận thiết bị đã đạt hiệu suất cao nhất trong khung phân loại của IEC với: 0% độ không đảm bảo đo tiêu chuẩn (standard uncertainty) và 0% cấp chính xác (accuracy class).', 'Tin chuyên ngành', 'DNV Hoàn Tất Phân Loại IEC Cho Thiết Bị Đo Gió Bằng Công Nghệ Lidar ZX 300e – Đạt Mức Độ Sai Số Thấp Nhất Có Thể', 'dnv-hoan-tat-phan-loai-iec-cho-thiet-bi-do-gio-bang-cong-nghe-lidar-zx-300e-–-dat-muc-do-sai-so-thap-nhat-co-the', NULL, NULL, 'DNV Hoàn Tất Phân Loại IEC Cho Thiết Bị Đo Gió Bằng Công Nghệ Lidar ZX 300e – Đạt Mức Độ Sai Số Thấp', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1598, 'vi', 'Tháng 3/2026, Seequent chính thức triển khai chuỗi hội thảo quốc tế dành cho cộng đồng địa chất và khai thác mỏ, tập trung vào nâng cao kỹ năng mô hình hóa 3D, khai thác dữ liệu thăm dò và kiểm soát xu hướng cấu trúc trong Leapfrog Geo.', 'Tin công ty', 'Chuỗi Webinar tháng 3/2026 của Seequent: Nâng cao diễn giải địa chất 3D', 'chuoi-webinar-thang-32026-cua-seequent:-nang-cao-dien-giai-dia-chat-3d', NULL, NULL, 'Chuỗi Webinar tháng 3/2026 của Seequent: Nâng cao diễn giải địa chất 3D', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1599, 'vi', 'Radiodetection, thương hiệu hàng đầu thế giới về thiết bị dò tìm hạ tầng ngầm, vừa công bố các gói sản phẩm (bundle) mới, kết hợp giữa máy dò kỹ thuật số Survey Grade (SG) với phần mềm bản đồ di động PointMan® Pro và dịch vụ hiệu chỉnh RTK Point One Nav. Đây được xem là bước tiến quan trọng trong việc số hóa dữ liệu hạ tầng ngầm với độ chính xác cấp độ centimet.', 'Tin chuyên ngành', 'Radiodetection Ra Mắt Các Gói Giải Pháp Bản Đồ Số: Kết Hợp Pointman Pro Và Point One Nav', 'radiodetection-ra-mat-cac-goi-giai-phap-ban-do-so:-ket-hop-pointman-pro-va-point-one-nav', NULL, NULL, 'Radiodetection Ra Mắt Các Gói Giải Pháp Bản Đồ Số: Kết Hợp Pointman Pro Và Point One Nav', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1600, 'vi', 'Trong kỷ nguyên chuyển đổi số, việc sở hữu các chứng chỉ năng lực quốc tế là chìa khóa để kiến trúc sư và kỹ sư khẳng định vị thế. CÔNG TY CỔ PHẦN CÔNG NGHỆ VÀ TƯ VẤN CIC phối hợp cùng BSI (Viện Tiêu chuẩn Anh) tổ chức chương trình đào tạo xác nhận năng lực BIM theo tiêu chuẩn ISO 19650 – bộ tiêu chuẩn vàng trong quản lý thông tin dự án xây dựng.', 'Tin công ty', 'CIC MỞ KHÓA ĐÀO TẠO CHUYÊN VIÊN/CHUYÊN GIA BIM THEO ISO 19650', '[thong-bao-moi]-khoa-dao-tao-chuyen-vienchuyen-gia-bim-theo-iso-19650', NULL, NULL, 'THÔNG BÁO MỜI- CIC MỞ KHÓA ĐÀO TẠO CHUYÊN VIÊN/CHUYÊN GIA BIM THEO ISO 19650', '') ON CONFLICT (entity_id, locale) DO NOTHING;
