INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1602, 'vi', 'Tìm hiểu tính năng Drawing Compare trên enjiCAD 2026 – công cụ so sánh file DWG thông minh, giúp phát hiện thay đổi bản vẽ tức thì và tăng hiệu quả cộng tác thiết kế.', 'Tin chuyên ngành', 'enjiCAD 2026 DWG Comparison – Tính Năng So Sánh Bản Vẽ Thông Minh', 'enjicad-2026-dwg-comparison-–-tinh-nang-so-sanh-ban-ve-thong-minh', NULL, NULL, 'enjiCAD 2026 DWG Comparison – Tính Năng So Sánh Bản Vẽ Thông Minh', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1603, 'vi', 'Hãng CSI đã chính thức phát hành phiên bản ETABS v23.2.0 và SAFE 23.2.0 vào ngày 24/02/2026. Bản cập nhật này tập trung chính vào việc bổ sung các tiêu chuẩn thiết kế mới của Châu Âu (Eurocode), Hàn Quốc (KDS) và Canada (NBCC).', 'Tin chuyên ngành', 'Cập nhật Tiêu chuẩn thiết kế mới với ETABS v23.2.0 và SAFE 23.2.0', 'cap-nhat-tieu-chuan-thiet-ke-moi-voi-etabs-v2320-va-safe-2320', NULL, NULL, 'Cập nhật Tiêu chuẩn thiết kế mới với ETABS v23.2.0 và SAFE 23.2.0', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1604, 'vi', 'CIC hoàn thành EPD (Environmental Product Declaration) cho ván ép phủ phim dựa trên LCA theo tiêu chuẩn quốc tế. Giải pháp minh bạch môi trường sản phẩm giúp doanh nghiệp gỗ Việt vượt rào cản xanh, chinh phục thị trường quốc tế.', 'Tin công ty', 'CIC Hoàn Thành EPD Cho Ván Sàn - Giải Pháp Xuất Khẩu Bền Vững', 'cic-hoan-thanh-epd-cho-van-san-giai-phap-xuat-khau-ben-vung', NULL, NULL, 'CIC Hoàn Thành EPD Cho Ván Sàn - Giải Pháp Xuất Khẩu Bền Vững', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1605, 'vi', 'IDEA StatiCa có khả năng phân tích và thẩm tra kết cấu tạm phục vụ thi công. Trong bài viết dưới đây, CIC có bài viết giới thiệu chi tiết về tính năng này.', 'Tin chuyên ngành', 'Thiết Kế Kết Cấu Tạm Phục Vụ Thi Công Bằng IDEA StatiCa', 'thiet-ke-ket-cau-tam-phuc-vu-thi-cong-bang-idea-statica', NULL, NULL, 'Thiết Kế Kết Cấu Tạm Phục Vụ Thi Công Bằng IDEA Statica', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1606, 'vi', 'Phiên bản MicroStation 2026 kết hợp các công cụ tự động hóa được hỗ trợ bởi AI, địa không gian 3D và khả năng mô hình hóa 3D hiệu suất cao giúp các kỹ sư thiết kế và bàn giao các công trình hạ tầng nhanh chóng và hiệu quả hơn.', 'Tin chuyên ngành', 'MicroStation 2026: Phần mềm CAD thông minh hơn cho Kỹ thuật Hạ tầng', 'microstation-2026:-phan-mem-cad-thong-minh-hon-cho-ky-thuat-ha-tang', NULL, NULL, 'MicroStation 2026, phần mềm CAD thông minh hơn cho Kỹ thuật Hạ tầng', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1607, 'vi', 'CSIPlant, Caesar II và AutoPIPE là ba trong số những phần mềm hàng đầu, được các kỹ sư trên toàn thế giới tin dùng.', 'Tin chuyên ngành', 'Top 3 Phần Mềm Phân Tích Ứng Suất Đường Ống Hàng Đầu Hiện Nay', 'top-3-phan-mem-phan-tich-ung-suat-duong-ong-hang-dau-hien-nay', NULL, NULL, 'Top 3 Phần Mềm Phân Tích Ứng Suất Đường Ống Hàng Đầu Hiện Nay', '') ON CONFLICT (entity_id, locale) DO NOTHING;
