INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1612, 'vi', 'AlphaGeometry là một hệ thống AI có khả năng giải các bài toán hình học phức tạp với trình độ tiệm cận huy chương vàng Olympic Toán quốc tế (IMO)', 'Tin chuyên ngành', 'DeepMind giải mã tương lai của ngành BIM với AlphaGeometry', 'deepmindgiai-matuong-lai-cua-nganh-bim-voi-alphageometry', NULL, NULL, 'DeepMind "giải mã" tương lai của ngành BIM với AlphaGeometry', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1613, 'vi', 'Nhằm đáp ứng nhu cầu mở rộng kinh doanh, CIC tuyển dụng nhiều vị trí như Điều phối BIM, Sales Engineer, IT Support. Môi trường làm việc chuyên nghiệp, cơ hội hợp tác quốc tế và chế độ phúc lợi đầy đủ.', 'Tin tuyển dụng', 'THÔNG BÁO TUYỂN DỤNG THÁNG 04 - CÔNG TY CỔ PHẦN CÔNG NGHỆ VÀ TƯ VẤN CIC', 'thong-bao-tuyen-dung-thang-04-cong-ty-co-phan-cong-nghe-va-tu-van-cic', NULL, NULL, 'THÔNG BÁO TUYỂN DỤNG THÁNG 04 - CÔNG TY CỔ PHẦN CÔNG NGHỆ VÀ TƯ VẤN CIC', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1614, 'vi', 'Khám phá cách công nghệ mô hình hóa 3D định hình lại ngành khai thác mỏ tại Úc. Tìm hiểu giải pháp tối ưu hóa tài nguyên, giảm chi phí và nâng cao an toàn lao động cùng CIC.', 'Tin chuyên ngành', 'Vai trò của mô hình 3D trong ngành khai thác mỏ tại Úc', 'vai-tro-cua-mo-hinh-3d-trong-nganh-khai-thac-mo-tai-uc', NULL, NULL, 'Vai trò của mô hình 3D trong ngành khai thác mỏ tại Úc', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1615, 'vi', 'Ngày 19/3/2026, CSI ra mắt bản cập nhật nhật SAP2000 v27.1.0 và CSiBridge v27.1.0, tập trung chính vào việc bổ sung các tiêu chuẩn thiết kế mới của Hàn Quốc (KDS) và Canada (CSA), và của Úc (AS/NZS).', 'Tin chuyên ngành', 'Cập nhật Tiêu chuẩn thiết kế mới với SAP2000 v27.1.0 &  CSiBridge v27.1.0', 'cap-nhat-tieu-chuan-thiet-ke-moi-voi-sap2000-v2710-amp;csibridge-v2710', NULL, NULL, 'Cập nhật Tiêu chuẩn thiết kế mới với SAP2000 v27.1.0 &  CSiBridge v27.1.0', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1616, 'vi', 'Trong bối cảnh ngành xây dựng Việt Nam đang bước vào giai đoạn chuyển đổi số mạnh mẽ, sự xuất hiện của các khái niệm như BIM (Building Information Modeling) và Digital Twin (Bản sao số) không còn là xu hướng xa lạ. Đặc biệt, với sự ra đời của Quyết định số 369/QĐ-BXD ngày 19/3/2026, Bộ Xây dựng đã chính thức đặt ra lộ trình cụ thể để hiện thực hóa việc ứng dụng công nghệ số vào quản lý, khai thác kết cấu hạ tầng. Tuy nhiên, vẫn còn nhiều nhầm lẫn giữa hai khái niệm này. Bài viết dưới đây sẽ phân tích chi tiết sự khác biệt và cách chúng phối hợp để tạo nên cuộc cách mạng trong quản lý dự án.', 'Tin chuyên ngành', 'BIM và Digital Twin: Chìa khóa chuyển đổi số toàn diện vòng đời công trình', 'bim-va-digital-twin:-chia-khoa-chuyen-doi-so-toan-dien-vong-doi-cong-trinh', NULL, NULL, 'BIM và Digital Twin: Chìa khóa chuyển đổi số toàn diện vòng đời công trình', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1617, 'vi', '', 'Quan hệ cổ đông', 'Thông báo và Tài liệu Tổ chức Đại hội đồng cổ đông thường niên năm 2026', 'thong-bao-va-tai-lieu-to-chuc-dai-hoi-dong-co-dong-thuong-nien-nam-2026', NULL, NULL, 'Thông báo và Tài liệu Tổ chức Đại hội đồng cổ đông thường niên năm 2026', '') ON CONFLICT (entity_id, locale) DO NOTHING;
