INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1619, 'vi', 'Chương trình dã ngoại tại Hồ Đồng Đò, Sóc Sơn, Hà Nội dành cho đoàn viên và toàn thể cán bộ nhân viên Công ty CIC vào cuối tháng 3 vừa qua đã đem lại nhiều trải nghiệm mới mẻ, thú vị cho tất cả các thành viên tham gia.', 'Tin công ty', 'Ban Chấp hành Đoàn Thanh niên CIC tổ chức chương trình dã ngoại hưởng ứng Tháng Thanh niên 2026', 'ban-chap-hanh-doan-thanh-nien-cic-to-chuc-chuong-trinh-da-ngoai-huong-ung-thang-thanh-nien-2026', NULL, NULL, 'Ban Chấp hành Đoàn Thanh niên CIC tổ chức chương trình dã ngoại hưởng ứng Tháng Thanh niên 2026', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1620, 'vi', 'Công ty Cổ phần Công nghệ và Tư vấn CIC vừa hoàn thành việc ký kết hợp đồng và bàn giao thiết bị siêu âm cọc khoan nhồi CHUM (Cross Hole Ultrasonic Monitor) của hãng Piletest (Israel) cho Viện Khoa học Công nghệ Xây dựng (IBST). Đây là một bước tiến quan trọng trong việc ứng dụng công nghệ hiện đại nhằm tăng cường năng lực kiểm định chất lượng công trình nền móng tại Việt Nam.', 'Tin công ty', 'CIC bàn giao thành công thiết bị siêu âm cọc khoan nhồi CHUM cho IBST', 'cic-ban-giao-thanh-cong-thiet-bi-sieu-am-coc-khoan-nhoi-chum-cho-ibst', NULL, NULL, 'CIC bàn giao thành công thiết bị siêu âm cọc khoan nhồi CHUM cho IBST', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1621, 'vi', 'Để đo bóc khối lượng XDTH trên phần mềm vẽ kỹ thuật enjiCAD 2026. người dùng theo dõi bài viết chi tiết dưới đây.', 'Tin chuyên ngành', 'Hướng dẫn cài đặt bộ lisp hỗ trợ đo bóc khối lượng XDTH trên enjiCAD 2026', 'huong-dan-cai-dat-bo-lisp-ho-tro-do-boc-khoi-luong-xdth-tren-enjicad-2026', NULL, NULL, 'Hướng dẫn cài đặt bộ lisp hỗ trợ đo bóc khối lượng XDTH trên enjiCAD 2026', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1623, 'vi', 'AutoCAD 2027 được tích hợp AI sẽ là phiên bản đánh dấu bước chuyển mạnh sang CAD thông minh (AI-driven CAD) với hiệu suất làm việc vượt trội.', 'Tin chuyên ngành', 'AutoCAD 2027 – Bước tiến lớn về AI, Cloud và tự động hóa CAD', 'autocad-2027-–-buoc-tien-lon-ve-ai-cloud-va-tu-dong-hoa-cad', NULL, NULL, 'AutoCAD 2027 – Bước tiến lớn về AI, Cloud và tự động hóa CAD', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1622, 'vi', 'Trong kỷ nguyên số hóa, việc thu thập dữ liệu không gian đòi hỏi sự cân bằng giữa tốc độ và độ chính xác. CHCNAV RS7 xuất hiện như một lời giải hoàn hảo, kết hợp sức mạnh của LiDAR tốc độ cao, hệ thống dẫn đường quán tính (Deep INS) và công nghệ hiển thị thực tế ảo tiên tiến nhất.', 'Tin chuyên ngành', 'CHCNAV RS7: Đột Phá Công Nghệ SLAM Và Lập Mô Hình 3D Thời Gian Thực', 'chcnav-rs7:-dot-pha-cong-nghe-slam-va-lap-mo-hinh-3d-thoi-gian-thuc', NULL, NULL, 'CHCNAV RS7: Đột Phá Công Nghệ SLAM và Lập Mô Hình 3D Thời Gian Thực', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1624, 'vi', 'Trong quá trình đo đạc và lập hồ sơ kỹ thuật, việc xuất tọa độ các điểm góc ranh (X, Y) theo hệ tọa độ VN-2000 là yêu cầu rất phổ biến. Tuy nhiên trên phần mềm CAD không có sẵn công cụ hỗ trợ xuất tọa độ trực tiếp ra bảng thống kê. Trong bài viết này, Công ty CIC sẽ giới thiệu các bước xuất tọa độ và lập bảng thống kê tọa độ góc ranh theo hệ VN-2000 bằng lisp.', 'Tin chuyên ngành', 'enjiCAD 2026- Hướng dẫn Xuất tọa độ và lập bảng thống kê tọa độ góc ranh theo hệ VN-2000', 'enjicad-2026huong-dan-xuat-toa-do-va-lap-bang-thong-ke-toa-do-goc-ranh-theo-he-vn-2000', NULL, NULL, 'enjiCAD 2026- Hướng dẫn Xuất tọa độ và lập bảng thống kê tọa độ góc ranh theo hệ VN-2000', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1626, 'vi', 'Cầu Vàm Cống – một trong những biểu tượng giao thông hiện đại của Đồng bằng sông Cửu Long – không chỉ gây ấn tượng bởi quy mô mà còn bởi việc ứng dụng công nghệ giám sát sức khỏe công trình (SHM) tiên tiến. Trái tim của hệ thống này chính là máy ghi gia tốc GMSplus từ GeoSIG (Thụy Sĩ).', 'Tin chuyên ngành', 'Cầu Vàm Cống: Đảm bảo an toàn công trình bằng công nghệ giám sát sức khỏe từ Geosig (Thụy Sỹ)', 'cau-vam-cong:-dam-bao-an-toan-cong-trinh-bang-cong-nghe-giam-sat-suc-khoe-tu-geosig-thuy-sy', NULL, NULL, 'Bảo vệ cầu Vàm Cống bằng "bộ não" công nghệ GMSplus từ GeoSIG sig (Thụy Sỹ)', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1627, 'vi', 'Trong quá trình lập bản vẽ kỹ thuật trong các lĩnh vực như xây dựng, cơ khí chính xác, kiến trúc, điện tử… thì các tệp CAD vẫn đang là cầu nối, là định dạng giúp lưu trữ, trao đổi dữ liệu hiệu quả. Tuy nhiên các tệp CAD chỉ là cách gọi chung nhất, còn thực tế mỗi phần mềm, chuyên môn lại có những định dạng riêng khác nhau, phổ biến như tệp DWG, tệp RVT, tệp STP… Cùng tìm hiểu về chúng và về ứng dụng của chúng, cách quản lý trong thời kỳ bùng nổ về công nghệ và phần mềm ngày nay.', 'Tin chuyên ngành', 'Định dạng file CAD là gì? Có những định dạng nào và sử dụng, quản lý chúng thế nào?', 'dinh-dang-file-cad-la-gi-co-nhung-dinh-dang-nao-va-su-dung-quan-ly-chung-the-nao', NULL, NULL, 'Định dạng file CAD là gì? Có những định dạng nào và sử dụng, quản lý chúng thế nào?', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1629, 'vi', 'Công ty Cổ phần Công nghệ và Tư vấn CIC vừa hoàn thành thành công dự án tư vấn Đánh giá Vòng đời sản phẩm (LCA) và Tuyên bố Sản phẩm Môi trường (EPD) cho 14 sản phẩm thuộc ngành hóa chất xây dựng của Bumatech — một trong những dự án EPD quy mô lớn nhất trong lĩnh vực này tại Việt Nam tính đến thời điểm hiện tại.', 'Tin công ty', 'CIC tư vấn thành công 14 sản phẩm hóa chất xây dựng được công bố trên EPD International', 'cic-tu-van-thanh-cong-14-san-pham-hoa-chat-xay-dung-duoc-cong-bo-tren-epd-international', NULL, NULL, 'CIC tư vấn thành công 14 sản phẩm hóa chất xây dựng được công bố trên EPD International', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1628, 'vi', 'Aspect Pipe Stress (CAESAR II) version 15.1 chính thức ra mắt với giao diện hiện đại, New Analysis Reviewer và 8 cải tiến hiệu suất vượt trội — giúp kỹ sư đường ống phân tích ứng suất nhanh hơn, chính xác hơn và hiệu quả hơn.', 'Tin chuyên ngành', 'CAESAR II Version 15.1 (Aspect Pipe Stress): 8 Tính Năng Mới Cho Kỹ Sư Đường Ống', 'caesar-ii-version-151-aspect-pipe-stress:-8-tinh-nang-moi-cho-ky-su-duong-ong', NULL, NULL, 'CAESAR II Version 15.1 (Aspect Pipe Stress): 8 Tính Năng Mới Cho Kỹ Sư Đường Ống', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1630, 'vi', 'AlphaAir 6 (AA6) – hệ thống LiDAR UAV tầm xa mới nhất từ CHCNAV với tầm đo xa tối đa lên tới  2.100 m, xử lý dạng sóng thế hệ 5, tích hợp camera kép và trọng lượng chỉ 1,35 kg.', 'Tin chuyên ngành', 'AlphaAir 6 – LiDAR UAV Tầm Xa 2.100 m, chinh phục địa hình phức tạp', 'alphaair-6-–-lidar-uav-tam-xa-2100-m-chinh-phuc-dia-hinh-phuc-tap', NULL, NULL, 'AlphaAir 6 – LiDAR UAV Tầm Xa 2.100 m, chinh phục địa hình phức tạp', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1631, 'vi', 'Trong bối cảnh khảo sát thủy văn hiện đại, việc duy trì dữ liệu ổn định tại các khu vực nước đục hay địa hình thay đổi nhanh là một thách thức lớn. Thấu hiểu điều đó, CHC Navigation (CHCNAV) chính thức trình làng D60 – dòng máy đo độ sâu đơn tia tần số kép thế hệ mới, được tối ưu hóa đặc biệt cho các nền tảng tàu mặt nước không người lái (USV).', 'Tin chuyên ngành', 'CHC Navigation giới thiệu máy đo độ sâu đơn tia tần số kép D60 dành cho đo độ sâu bằng tàu không người lái', 'chc-navigation-gioi-thieu-may-do-do-sau-don-tia-tan-so-kep-d60-danh-cho-do-do-sau-bang-tau-khong-nguoi-lai', NULL, NULL, 'Ra mắt máy đo độ sâu đơn tia tần số kép D60 cho khảo sát thủy văn bằng tàu không người lái', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1632, 'vi', 'Trong kỷ nguyên biến đổi khí hậu và áp lực thất thoát nước ngày càng tăng, các đơn vị cấp nước đang tìm kiếm một "chìa khóa" để quản trị thông minh. Digital Twin (Mô hình số song sinh) chính là xu hướng tất yếu, giúp biến dữ liệu rời rạc thành quyết định chính xác. Bài viết này sẽ phân tích vai trò của bộ đôi giải pháp chiến lược từ Bentley – OpenFlows Water và OpenFlows WaterSight – trong việc xây dựng hệ sinh thái vận hành mạng lưới cấp nước toàn diện.', 'Tin chuyên ngành', 'Chuyển đổi số ngành nước 4.0: Quản trị thông minh dựa trên dữ liệu thực với bộ đôi OpenFlows Water & WaterSight', 'chuyen-doi-so-nganh-nuoc-40:-quan-tri-thong-minh-dua-tren-du-lieu-thuc-voi-bo-doi-openflows-water-amp;-watersight', NULL, NULL, 'Chuyển đổi số ngành nước 4.0: Quản trị thông minh dựa trên dữ liệu thực với bộ đôi OpenFlows Water &', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1633, 'vi', 'Công ty CIC đã triển khai thành công hệ thống diễn họa gạch ốp lát Roomvo cho Công ty AMY GRUPO, giúp hoạt động kinh doanh của doanh nghiệp này thuận lợi hơn bao giờ hết.', 'Tin công ty', 'CIC triển khai Roomvo cho nhà sản xuất gạch ốp lát hàng đầu tại Việt Nam', 'cic-trien-khai-roomvo-cho-nha-san-xuat-gach-op-lat-hang-dau-tai-viet-nam', NULL, NULL, 'CIC triển khai Roomvo cho nhà sản xuất gạch ốp lát hàng đầu tại Việt Nam', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1634, 'vi', 'Nhà phát triển ISD Group vừa chính thức ra mắt bản cập nhật SP1 cho HiCAD 2026. Đây là bước tiến quan trọng với nhiều nâng cấp về hiệu năng và các bộ công cụ chuyên sâu, giúp giải quyết các bài toán thiết kế phức tạp trong ngành cơ khí, kết cấu thép và xây dựng nhà máy. Hãy cùng CIC điểm qua những tính năng đắt giá nhất trong phiên bản này.', 'Tin chuyên ngành', 'HiCAD 2026 SP1 ra mắt với hàng loạt cải tiến và tính năng mới nhất', 'hicad-2026-sp1-ra-mat-voi-hang-loat-cai-tien-va-tinh-nang-moi-nhat', NULL, NULL, 'HiCAD 2026 SP1 ra mắt với hàng loạt cải tiến và tính năng mới nhất', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1636, 'vi', 'Bạn gặp lỗi chồng chéo khi đặt Keyplan vào Viewport? Khám phá ngay kỹ thuật sử dụng lệnh VPCLIP và tư duy trừ khối để tạo khung Keyplan tinh tế, chuyên nghiệp mà không cần dùng Wipeout.', 'Tin chuyên ngành', 'TIP – Phương pháp “đục lô” Viewport và tạo Keyplan chuyên nghiệp với bản vẽ CAD', 'huong-dan-lenh-vpclip-duc-lo-viewport-cad', NULL, NULL, 'Hướng dẫn lệnh VPCLIP đục lỗ virwport CAD', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1637, 'vi', '', 'Quan hệ cổ đông', 'Nghị quyết Đại hội cổ đông thường niên năm 2026', 'nghi-quyet-dai-hoi-co-dong-thuong-nien-nam-2026', NULL, NULL, 'Nghị quyết Đại hội cổ đông thường niên năm 2026', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1638, 'vi', 'Máy quét laser cầm tay CHCNAV RS7 được thiết kế cho các ứng dụng trong xây dựng và nội thất, giúp các nhóm thu thập dữ liệu trong nhà mật độ cao và nhanh chóng tạo ra các sản phẩm có thể tái sử dụng.', 'Tin chuyên ngành', 'Công nghệ quét SLAM cầm tay CHCNAV RS7, thiết lập thông minh trong khảo sát xây dựng', 'cong-nghe-quet-slam-cam-tay-chcnav-rs7-thiet-lap-thong-minh-trong-khao-sat-xay-dung', NULL, NULL, 'Công nghệ quét SLAM cầm tay CHCNAV RS7, thiết lập thông minh trong khảo sát xây dựng', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1644, 'vi', 'Công ty CP Công nghệ và Tư vấn CIC chia sẻ giải pháp chứng nhận công trình xanh BREEAM Communities (ESG) tại hội thảo VECAS 2026 ở Đà Nẵng.', 'Tin công ty', 'CIC tham gia và chia sẻ giải pháp tại Hội thảo VECAS: “Công trình xanh và Giải pháp giảm phát thải carbon” tại Đà Nẵng', 'cic-tham-gia-va-chia-se-giai-phap-tai-hoi-thao-vecas:-cong-trinh-xanh-va-giai-phap-giam-phat-thai-carbon-tai-da-nang', NULL, NULL, 'CIC tham gia và chia sẻ giải pháp tại Hội thảo VECAS: “Công trình xanh và Giải pháp giảm phát thải c', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1639, 'vi', 'Vừa qua, đội ngũ chuyên gia của Công ty Cổ phần Công nghệ và Tư vấn CIC đã có buổi gặp gỡ, làm việc và demo giải pháp công nghệ khảo sát công trình trực tiếp tại trụ sở của DELTA GROUP. Buổi làm việc diễn ra sôi nổi cùng sự tham gia của Phòng Kỹ thuật Công nghệ và Phòng Biện pháp Thi công, Phòng dự toán khối lượng DELTA Group.', 'Tin công ty', 'CIC Giới Thiệu Giải Pháp Khảo Sát 3D Laser SLAM và UAV LiDAR Đến Tập Đoàn DELTA', 'cic-gioi-thieu-giai-phap-khao-sat-3d-laser-slam-va-uav-lidar-den-tap-doan-delta', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1640, 'vi', 'Quy hoạch Hà Nội tầm nhìn 100 năm: Đột phá đô thị thông minh với Bản sao số (Digital Twin) và Trí tuệ nhân tạo (AI). Khám phá ngay lộ trình số hóa tương lai!', 'Tin chuyên ngành', 'Digital Twin Và AI: Chìa Khóa Số Hóa Đô Thị Thông Minh Hà Nội', 'digital-twin-va-ai:-chia-khoa-so-hoa-do-thi-thong-minh-ha-noi', NULL, NULL, 'Digital Twin Và AI: Chìa Khóa Số Hóa Đô Thị Thông Minh Hà Nội', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1641, 'vi', 'Ngày 15/05/2026, Công ty Cổ phần Công nghệ và Tư vấn CIC phối hợp cùng Worley tổ chức thành công hội thảo trực tuyến với chủ đề: “Ứng dụng mô hình thông tin công trình (BIM) trong công tác quản lý dự án xây dựng của ngành khai thác mỏ”.', 'Tin công ty', 'CIC và Worley tổ chức thành công hội thảo ứng dụng BIM trong ngành khai thác mỏ', 'cic-va-worley-to-chuc-thanh-cong-hoi-thao-ung-dung-bim-trong-nganh-khai-thac-mo', NULL, NULL, 'CIC và Worley tổ chức thành công hội thảo ứng dụng BIM trong ngành khai thác mỏ', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1664, 'vi', 'Nghị định 217/2026/NĐ-CP đánh dấu bước chuyển quan trọng trong việc áp dụng BIM tại Việt Nam, khi mở rộng phạm vi bắt buộc, nâng giá trị pháp lý của mô hình BIM và thúc đẩy sử dụng môi trường dữ liệu chung CDE. Những thay đổi này giúp chủ đầu tư, đơn vị tư vấn và nhà thầu tối ưu quy trình quản lý dự án, giảm hồ sơ giấy, tăng tính minh bạch và khai thác dữ liệu công trình hiệu quả trong suốt vòng đời vận hành.', 'Tin chuyên ngành', 'Quy định mới trong việc áp dụng BIM tại Việt Nam', 'quy-dinh-moi-trong-viec-ap-dung-bim-tai-viet-nam', NULL, NULL, 'Quy định mới trong việc áp dụng BIM tại Việt Nam', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1642, 'vi', 'Thủ tướng yêu cầu truy quét toàn quốc phần mềm vi phạm từ 07-30/5/2026. Xem ngay 5 bước rà soát và hợp thức hóa phần mềm từ CIC – Uy tín 35 năm, đúng luật, đúng ngân sách.', 'Tin công ty', 'Quy Định Mới Về Bản Quyền Phần Mềm 2026: Doanh Nghiệp Cần Làm Gì Để Tránh Phạt Nặng?', 'quy-dinh-moi-ve-ban-quyen-phan-mem-2026:-doanh-nghiep-can-lam-gi-de-tranh-phat-nang', NULL, NULL, 'Quy Định Mới Về Bản Quyền Phần Mềm 2026: Doanh Nghiệp Cần Làm Gì Để Tránh Phạt Nặng?', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1643, 'vi', 'Được triển khai đồng thời trên các dòng sản phẩm Leapfrog Geo, Leapfrog Edge, Leapfrog Works và Leapfrog Energy vào ngày 5 tháng 5 năm 2026, đại diện cho tiến bộ lớn nhất về thuật toán và quy trình làm việc của nền tảng này trong thời gian gần đây.', 'Tin chuyên ngành', 'Leapfrog 2026.1: Những nâng cấp đáng chú ý cho mô hình hóa địa chất, lập kế hoạch khoan và ước tính tài nguyên', 'leapfrog-20261:-nhung-nang-cap-dang-chu-y-cho-mo-hinh-hoa-dia-chat-lap-ke-hoach-khoan-va-uoc-tinh-tai-nguyen', NULL, NULL, 'Những nâng cấp đáng chú ý cho mô hình hóa địa chất, lập kế hoạch khoan và ước tính tài nguyên trong', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1645, 'vi', 'Áp lực tuân thủ pháp lý về kiểm kê khí nhà kính ngày càng siết chặt – CIC chính thức ra mắt phần mềm CIC – Netzero 2050 App, giải pháp số hóa toàn diện giúp doanh nghiệp đo lường, quản lý và báo cáo phát thải carbon nhanh chóng, chính xác và đúng chuẩn pháp luật.', 'Tin công ty', 'CIC Ra Mắt Phần Mềm Kiểm Kê Khí Nhà Kính – Giải Pháp Số Hóa Cho Doanh Nghiệp Trên Lộ Trình Net Zero', 'cic-ra-mat-phan-mem-kiem-ke-khi-nha-kinh-–-giai-phap-so-hoa-cho-doanh-nghiep-tren-lo-trinh-net-zero', NULL, NULL, 'CIC Ra Mắt Phần Mềm Kiểm Kê Khí Nhà Kính Số Hóa Cho Doanh Nghiệp Hướng Tới Netzero', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1646, 'vi', 'Hơn 200 chuyên gia hạ tầng hàng đầu Việt Nam quy tụ tại New World Saigon ngày 23/4/2026, cùng Bentley Systems khám phá sức mạnh của Digital Twin, BIM và AI — những công nghệ số đang định hình tương lai ngành hạ tầng Việt Nam trong giai đoạn đầu tư lớn nhất lịch sử.', 'Tin công ty', 'Bentley Innovation Day 2026  Tại Tp. Hồ Chí Minh: Khi Công Nghệ Số Mở Đường Cho Hạ Tầng Việt Nam', 'bentley-innovation-day-2026--tai-tp-ho-chi-minh:-khi-cong-nghe-so-mo-duong-cho-ha-tang-viet-nam', NULL, NULL, 'Bentley Innovation Day 2026  Tại Tp. Hồ Chí Minh thành công với sự mở đường cho hạ tầng Việt Nam', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1647, 'vi', 'CIC tổ chức khảo sát thực tế máy dò cáp ngầm Radiodetection RD8200 cùng Tập đoàn Xây dựng DELTA tại hiện trường Điện lực Ba Đình. Thiết bị định vị chính xác độ sâu, hướng đi tuyến cáp – giải pháp an toàn thi công và hạ ngầm đô thị hàng đầu.', 'Tin công ty', 'Máy Dò Cáp Ngầm RD8200: Trải Nghiệm Thực Tế Tại Công Trình Hạ Ngầm Cùng DELTA', 'may-do-cap-ngam-rd8200:-trai-nghiem-thuc-te-tai-cong-trinh-ha-ngam-cung-delta', NULL, NULL, 'Trải Nghiệm Thực Tế Máy Dò Cáp Ngầm RD8200 Tại Công Trình Hạ Ngầm Cùng DELTA', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1648, 'vi', 'Quy trình kích hoạt bản quyền enjiCAD rất đơn giản. Bạn chỉ cần mở phần mềm, truy cập vào menu Help chọn Register và chọn mục Activate License, sau đó nhập thông tin Mã kích hoạt (Serial Number/Key) được cấp và nhấn Activate để hoàn tất.', 'Tin chuyên ngành', 'Hướng dẫn kích hoạt bản quyền phần mềm enjiCAD', 'huong-dan-kich-hoat-ban-quyen-phan-mem-enjicad', NULL, NULL, 'Hướng dẫn kích hoạt bản quyền phần mềm enjiCAD', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1649, 'vi', 'Nhằm đáp ứng nhu cầu mở rộng kinh doanh, CIC tuyển dụng nhiều vị trí như Phát triển dự án BIM, Sales Engineer, AI, Hỗ trợ kĩ thuật. Môi trường làm việc chuyên nghiệp, cơ hội hợp tác quốc tế và chế độ phúc lợi đầy đủ.', 'Tin tuyển dụng', 'CIC tuyển dụng tháng 6/2026', 'cic-tuyen-dung-thang-62026', NULL, NULL, 'CIC tuyển dụng tháng 6/2026', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1650, 'vi', 'Ngày 15/5/2026, Công ty Cổ phần Công nghệ và Tư vấn CIC vinh dự được mời tham dự cuộc họp quan trọng về triển khai nhiệm vụ phát triển công nghệ chiến lược, theo Quyết định số 808/QĐ-TTg ngày 06/5/2026 của Thủ tướng Chính phủ. Cuộc họp do Bộ trưởng Bộ Xây dựng Trần Hồng Minh chủ trì.', 'Tin công ty', 'CIC tham gia Chương trình phát triển công nghệ chiến lược ngành Xây dựng', 'cic-tham-gia-chuong-trinh-phat-trien-cong-nghe-chien-luoc-nganh-xay-dung', NULL, NULL, 'CIC tham gia Chương trình phát triển công nghệ chiến lược ngành Xây dựng', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1651, 'vi', 'Đón đầu xu hướng chuyển đổi số mạnh mẽ của ngành xây dựng và hạ tầng tại Việt Nam, việc làm chủ dữ liệu không gian ba chiều (3D số) đang trở thành chìa khóa cốt lõi để nâng cao năng lực cạnh tranh và tối ưu hóa chi phí. Vừa qua, CIC đã tổ chức thành công buổi hội thảo trực tuyến, giới thiệu giải pháp đột phá: Công nghệ Khảo Sát 3D Laser SLAM và LIDAR UAV từ thương hiệu trắc địa hàng đầu - CHCNAV (Trung Quốc) đến Tập đoàn Coteccons.', 'Tin công ty', 'CIC Giới Thiệu Giải Pháp Khảo Sát 3D Laser SLAM và LIDAR UAV Đến Tập đoàn Coteccons', 'cic-gioi-thieu-giai-phap-khao-sat-3d-laser-slam-va-lidar-uav-den-tap-doan-coteccons', NULL, NULL, 'CIC Giới Thiệu Giải Pháp Khảo Sát 3D Laser SLAM và LIDAR UAV Đến Tập đoàn Coteccons', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1652, 'vi', 'Công ty Cổ phần Công nghệ và Tư vấn CIC vừa chính thức ký kết hợp đồng cung cấp 20 bộ thiết bị siêu âm cọc khoan nhồi CHUM (Cross Hole Ultrasonic Monitor) của hãng Piletest – Israel cho Vingroup nhằm phục vụ công tác kiểm tra chất lượng cọc khoan nhồi trên hàng loạt dự án trải dài từ Bắc vào Nam.', 'Tin công ty', 'CIC cung cấp thiết bị siêu âm cọc khoan nhồi CHUM cho VINGROUP', 'cic-cung-cap-thiet-bi-sieu-am-coc-khoan-nhoi-chum-cho-vingroup', NULL, NULL, 'CIC cung cấp thiết bị siêu âm cọc khoan nhồi CHUM cho VINGROUP', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1653, 'vi', 'Công ty Cổ phần Công nghệ và Tư vấn CIC đã chính thức bàn giao và cung cấp giải pháp phần mềm chuyên dụng OpenFlows Water của hãng Bentley Systems (Mỹ) với số lượng lớn cho Tổng Công ty Cấp nước Sài Gòn (SAWACO).', 'Tin công ty', 'CIC cung cấp giải pháp OpenFlows Water (Bentley Systems) cho Tổng Công ty Cấp nước Sài Gòn (SAWACO)', 'cic-cung-cap-giai-phap-openflows-water-bentley-systems-cho-tong-cong-ty-cap-nuoc-sai-gon-sawaco', NULL, NULL, 'CIC cung cấp giải pháp OpenFlows Water (Bentley Systems) cho Tổng Công ty Cấp nước Sài Gòn (SAWACO)', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1654, 'vi', 'Đối với mạng lưới đường sắt tốc độ cao (High Speed Railway - HSR) vận hành ở dải vận tốc từ 300 km/h đến 350 km/h, các chấn động địa chấn dù là nhỏ nhất cũng ẩn chứa nguy cơ gây biến dạng hình học đường ray, trật bánh và các thảm họa thảm khốc. Bài viết này giới thiệu giải pháp công nghệ Cảnh báo sớm động đất (EEW) và Giám sát sức khỏe kết cấu (SHM) của hãng GeoSIG (Thụy Sĩ) – đơn vị có hơn 30 năm kinh nghiệm trong lĩnh vực giám sát các nhà máy điện hạt nhân, đập thủy điện, đường sắt cao tốc và cơ sở hạ tầng trọng yếu.', 'Tin chuyên ngành', 'GeoSIG - Hệ thống cảnh báo sớm động đất và giám sát sức khỏe kết cấu cho đường sắt tốc độ cao', 'geosig-he-thong-canh-bao-som-dong-dat-va-giam-sat-suc-khoe-ket-cau-cho-duong-sat-toc-do-cao', NULL, NULL, 'GeoSIG - Hệ thống cảnh báo sớm động đất và giám sát sức khỏe kết cấu cho đường sắt tốc độ cao', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1656, 'vi', 'Cách Laing O’Rourke đã ứng dụng BIMcollab trong dự án Sân vận động Everton tại Liverpool để thay thế quy trình phối hợp truyền thống bằng email và Excel. Thông qua việc thiết lập quy trình rõ ràng, ma trận trách nhiệm RACI, đào tạo người dùng và hỗ trợ kỹ thuật liên tục, BIMcollab trở thành nền tảng quản lý vấn đề tập trung, giúp nâng cao hiệu quả phối hợp thiết kế, tăng tính minh bạch và rút ngắn thời gian họp điều phối từ 3 giờ xuống còn 1 giờ.', 'Tin chuyên ngành', 'Laing O’Rourke dùng BIMcollab để trong phối hợp thiết kế siêu dự án sân vận động Everton Stadium tại Liverpool', 'laing-o’rourke-dung-bimcollab-de-trong-phoi-hop-thiet-ke-sieu-du-an-san-van-dong-everton-stadium-tai-liverpool', NULL, NULL, 'Laing O’Rourke dùng BIMcollab trong phối hợp thiết kế siêu dự án sân vận động Everton Stadium', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1655, 'vi', 'BIM (Mô hình Thông tin Công trình) giúp doanh nghiệp giảm chi phí, phát hiện xung đột sớm và quản lý thi công toàn diện. Dưới đây là 10 lợi ích hàng đầu nhất của BIM.', 'Tin chuyên ngành', '10 Lợi Ích Hàng Đầu Của BIM Trong Ngành Xây Dựng (2026)', '10-loi-ich-hang-dau-cua-bim-trong-nganh-xay-dung-2026', NULL, NULL, '10 Lợi Ích Hàng Đầu Của BIM Trong Ngành Xây Dựng (2026)', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1657, 'vi', 'Trước làn sóng khủng hoảng nhân lực nghiêm trọng và già hóa lao động, ngành xây dựng toàn cầu đang đứng trước bước ngoặt sinh tử. Cuộc cách mạng số công trường với sự trỗi dậy của thế hệ rô-bốt thông minh ứng dụng Trí tuệ nhân tạo hiện thân (Embodied AI) chính là "chìa khóa vàng" lúc này. Giải pháp không chỉ giải phóng con người khỏi môi trường độc hại mà còn giúp các nhà thầu tối ưu chi phí, bứt phá tiến độ và nâng cao năng lực cạnh tranh.', 'Tin chuyên ngành', 'Cách mạng số công trường: Giải bài toán khủng hoảng lao động ngành xây dựng bằng rô bốt thông minh', 'cách-mạng-só-cong-truòng:-giải-bài-toán-khủng-hoảng-lao-dọng-ngành-xay-dụng-bàng-ro-bót-thong-minh', NULL, NULL, 'Cách mạng số công trường: Giải bài toán khủng hoảng lao động ngành xây dựng bằng rô bố', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1659, 'vi', 'CIC tiếp tục bàn giao thiết bị siêu âm cọc khoan nhồi CHUM của hãng Piletest cho CICO – đơn vị lâu năm trong lĩnh vực tư vấn xây dựng, khảo sát, quan trắc địa kỹ thuật và kiểm tra chất lượng nền móng. Việc tiếp tục đầu tư thiết bị CHUM giúp CICO nâng cao năng lực kiểm định, chủ động tiến độ thí nghiệm và đáp ứng yêu cầu ngày càng cao về kiểm soát chất lượng công trình tại Việt Nam.', 'Tin công ty', 'CICO tiếp tục lựa chọn thiết bị siêu âm cọc khoan nhồi CHUM của Piletest do CIC phân phối tại Việt Nam', 'cico-tiep-tuc-lua-chon-thiet-bi-sieu-am-coc-khoan-nhoi-chum-cua-piletest-do-cic-phan-phoi-tai-viet-nam', NULL, NULL, 'CICO tiếp tục chọn CHUM Piletest do CIC phân phối', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1660, 'vi', 'Khi công trình cũ phải đáp ứng tiêu chuẩn mới, tải trọng mới hoặc yêu cầu khai thác mới, việc đánh giá lại khả năng chịu lực của cấu kiện và liên kết trở thành nhiệm vụ quan trọng. IDEA StatiCa giúp kỹ sư kiểm tra liên kết thép, mô phỏng suy giảm vật liệu và đề xuất phương án gia cường với độ tin cậy cao hơn.', 'Tin chuyên ngành', 'Gia cường kết cấu hiện hữu: Kỹ sư có thể thiết kế tự tin hơn với IDEA StatiCa như thế nào?', 'gia-cuong-ket-cau-hien-huu:-ky-su-co-the-thiet-ke-tu-tin-hon-voi-idea-statica-nhu-the-nao', NULL, NULL, 'Gia cường kết cấu hiện hữu với IDEA StatiCa', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1661, 'vi', 'Ngày 18/06/2026, Công ty CP Công nghệ và Tư vấn CIC tổ chức hội thảo trực tuyến nhằm cập nhật các quy định pháp lý mới về kiểm kê khí nhà kính, giảm nhẹ phát thải và thị trường carbon tại Việt Nam. Chương trình thu hút sự quan tâm của nhiều doanh nghiệp trong các lĩnh vực phát thải lớn như sắt thép, xi măng, nhiệt điện, đồng thời giới thiệu giải pháp Net Zero 2050 App hỗ trợ doanh nghiệp chuẩn hóa dữ liệu phát thải và sẵn sàng đáp ứng các yêu cầu báo cáo trong giai đoạn tới.', 'Tin công ty', 'CIC tổ chức thành công hội thảo trực tuyến, cập nhật quy định kiểm kê khí nhà kính và thị trường carbon cho doanh nghiệp', 'cic-to-chuc-thanh-cong-hoi-thao-truc-tuyen-cap-nhat-quy-dinh-kiem-ke-khi-nha-kinh-va-thi-truong-carbon-cho-doanh-nghiep', NULL, NULL, 'CIC cập nhật quy định kiểm kê khí nhà kính, thị trường carbon', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1662, 'vi', 'IDEA StatiCa 26.0 mang đến nhiều cải tiến quan trọng cho kỹ sư kết cấu, từ thiết kế và kiểm tra liên kết neo thép – bê tông, dự đoán nhanh khả năng chịu lực bằng Machine Learning, đến hỗ trợ tiêu chuẩn AASHTO trong IDEA StatiCa Detail. Phiên bản mới cũng cải thiện khả năng quản lý mô hình lớn với công nghệ 3D Scene và giới thiệu ứng dụng RC Section, giúp phân tích tiết diện bê tông cốt thép theo định hướng tiêu chuẩn Eurocode thế hệ mới. Đây là bản cập nhật giúp quy trình thiết kế nhanh hơn, trực quan hơn và đáng tin cậy hơn cho các dự án kết cấu thép, bê tông và hạ tầng.', 'Tin chuyên ngành', 'IDEA StatiCA: Những tính năng nổi bật nhất trong phiên bản v26.0', 'idea-statica:-nhung-tinh-nang-noi-bat-nhat-trong-phien-ban-v260', NULL, NULL, 'IDEA StatiCA: Những tính năng nổi bật nhất trong phiên bản v26.0', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1665, 'vi', 'Giải pháp siêu âm cọc khoan nhồi bằng hệ thống thiết bị và phần mềm CHUM (Piletest) giúp tự động hóa quá trình xác định thời gian sóng truyền đầu tiên (FAT) và tính toán tốc độ sóng biểu kiến chính xác. Nhờ tích hợp các thuật toán thông minh giúp loại bỏ nhiễu tín hiệu, giải pháp hỗ trợ các kỹ sư định vị nhanh chóng các khuyết tật bê tông thân cọc (như bọng rỗng, nứt, phân tầng), đánh giá chuẩn xác độ đồng nhất và nghiệm thu chất lượng nền móng công trình một cách an toàn, hiệu quả.', 'Tin chuyên ngành', 'Siêu âm cọc khoan nhồi – Xác định thời gian sóng truyền đầu tiên (FAT) và tốc độ sóng', 'sieu-am-cọc-khoan-nhòi-–-xác-dịnh-thòi-gian-sóng-truyèn-dàu-tien-fat-và-tóc-dọ-sóng', NULL, NULL, 'Siêu âm cọc khoan nhồi – Xác định thời gian sóng truyền đầu tiên (FAT) và tốc độ sóng', 'Siêu âm cọc khoan nhồi, CHUM') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1667, 'vi', 'Tính năng dự đoán tức thời mức sử dụng liên kết bằng mô hình học máy trong IDEA StatiCa Connection hỗ trợ người dùng đánh giá nhanh cấu hình liên kết đang được chọn thông qua các mẫu liên kết tham số có sẵn. Khi thay đổi các thông số như chiều dày bản thép, kích thước bu lông hoặc khoảng cách mép, phần mềm sẽ cập nhật ngay giá trị dự đoán, giúp quá trình tối ưu thiết kế nhanh hơn mà không cần chạy tính toán đầy đủ cho từng phương án trung gian. Tuy nhiên, kết quả dự đoán chỉ mang tính ước tính và không thay thế cho phép tính ứng suất/biến dạng tiêu chuẩn trong bước kiểm tra thiết kế cuối cùng.', 'Tin chuyên ngành', 'IDEA StatiCa- Dự đoán mức sử dụng liên kết nhanh hơn nhờ mô hình học máy', 'du-doan-muc-su-dung-bang-mo-hinh-hoc-may-trong-idea-statica', NULL, NULL, 'IDEA StatiCa: Dự đoán mức sử dụng liên kết nhanh hơn nhờ mô hình học máy', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1669, 'vi', 'Các phần mềm CAD thế hệ mới đang tập trung mạnh vào hiệu suất xử lý bản vẽ, khả năng tương thích DWG, hỗ trợ tự động hóa bằng LISP/API và tối ưu chi phí bản quyền. Đây cũng là những tiêu chí quan trọng mà doanh nghiệp kỹ thuật cần cân nhắc khi lựa chọn giải pháp CAD dài hạn. Với giao diện quen thuộc, khả năng tương thích tốt với dữ liệu CAD phổ biến và mô hình bản quyền linh hoạt, enjiCAD của CIC là lựa chọn phù hợp cho các đơn vị đang tìm kiếm phần mềm CAD thay thế, ổn định và tiết kiệm chi phí.', 'Tin chuyên ngành', 'Xu hướng CAD 2027: Doanh nghiệp kỹ thuật cần phần mềm nhanh, tương thích và tối ưu chi phí', 'xu-huong-cad-2027', NULL, NULL, 'Xu hướng CAD 2027: Doanh nghiệp kỹ thuật cần phần mềm nhanh, tương thích và tối ưu chi phí', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1668, 'vi', 'Sàn giao dịch carbon trong nước chính thức đi vào vận hành tại HNX với mã hạn ngạch VN2025, đánh dấu bước tiến quan trọng trong phát triển thị trường carbon Việt Nam và hỗ trợ doanh nghiệp tuân thủ nghĩa vụ phát thải.', 'Tin chuyên ngành', 'Sàn giao dịch carbon Việt Nam chính thức vận hành từ 29/06/2026', 'san-giao-dich-carbon-viet-nam-chinh-thuc-van-hanh-tu-29062026', NULL, NULL, 'Sàn giao dịch carbon Việt Nam chính thức vận hành từ 29/06/2026', 'sàn giao dịch carbon, tín chỉ carbon') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1670, 'vi', 'Trong bối cảnh thị trường carbon tại Việt Nam bước vào giai đoạn vận hành thí điểm, dữ liệu phát thải đang trở thành yếu tố then chốt đối với doanh nghiệp xi măng. Không chỉ phục vụ kiểm kê khí nhà kính, dữ liệu từ nguyên liệu, năng lượng, clinker và vận hành nhà máy còn là cơ sở xác định hạn ngạch phát thải, chi phí carbon và năng lực cạnh tranh của doanh nghiệp trong cơ chế mới.', 'Tin chuyên ngành', 'Khi dữ liệu phát thải trở thành tài sản mới của ngành xi măng', 'khi-du-lieu-phat-thai-tro-thanh-tai-san-moi-cua-nganh-xi-mang', NULL, NULL, 'Khi dữ liệu phát thải trở thành tài sản mới của ngành xi măng', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1671, 'vi', 'Để giải quyết bài toán quy hoạch phức tạp cho hệ thống Metro đô thị và đường sắt tốc độ cao tại Việt Nam, các phương pháp tính toán tĩnh truyền thống hiện đã không còn đủ độ chính xác. Giải pháp phần mềm OpenTrack từ Thụy Sĩ ra đời như một công cụ mô phỏng vi mô tiên phong, cho phép giải các phương trình vi phân chuyển động theo bước nhảy thời gian thực bằng cách hợp nhất toàn vẹn dữ liệu hạ tầng tín hiệu, động lực học đoàn tàu và biểu đồ lịch trình.', 'Tin chuyên ngành', 'Tối ưu hóa quy hoạch và mô phỏng năng lực vận tải đường sắt toàn diện với Opentrack', 'toi-uu-hoa-quy-hoach-va-mo-phong-nang-luc-van-tai-duong-sat-toan-dien-voi-opentrack', NULL, NULL, 'Phần mềm OpenTrack: Mô phỏng vi mô & Quy hoạch đường sắt hiện đại', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1672, 'vi', 'Bộ Xây dựng ban hành Quyết định số 1041/QĐ-BXD về Hướng dẫn xác định khối lượng công trình, có hiệu lực từ ngày 01/7/2026. Điểm đáng chú ý của văn bản là việc công nhận khối lượng được trích xuất trực tiếp từ mô hình BIM đạt yêu cầu, không bắt buộc phải xác định lại bằng phương pháp thủ công từ hồ sơ thiết kế 2D. Quy định mới được xem là bước tiến quan trọng trong chuẩn hóa quản lý chi phí đầu tư xây dựng, đồng thời mở rộng cơ hội ứng dụng BIM và các công cụ số trong lập dự toán, kiểm soát chi phí và nâng cao hiệu quả triển khai dự án.', 'Tin chuyên ngành', 'Bước ngoặt chuyển đổi số: Bộ Xây dựng chính thức công nhận khối lượng trích xuất trực tiếp từ Mô hình BIM ', 'buoc-ngoat-chuyen-doi-so:-bo-xay-dung-chinh-thuc-cong-nhan-khoi-luong-trich-xuat-truc-tiep-tu-mo-hinh-bim', NULL, NULL, 'Bộ Xây dựng công bố hướng dẫn xác định khối lượng công trình bằng BIM', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1673, 'vi', 'Sáng nay, các thành viên CIC cùng nhau theo dõi trận đấu World Cup 2026 tại phòng họp công ty, tạo nên không khí hào hứng và gắn kết ngay tại văn phòng. Hoạt động không chỉ hưởng ứng ngày hội bóng đá lớn nhất hành tinh, mà còn lan tỏa tinh thần đồng đội, sự phối hợp và năng lượng tích cực – những giá trị luôn hiện diện trong văn hóa làm việc tại CIC.', 'Tin công ty', 'CIC hòa nhịp cùng World Cup 2026', 'cic-hoa-nhip-cung-world-cup-2026', NULL, NULL, 'CIC hòa nhịp cùng World Cup 2026: Lan tỏa tinh thần đồng đội', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1674, 'vi', 'CADprofi là bộ add-on CAD chuyên ngành hỗ trợ kỹ sư thiết kế nhanh hơn trong các lĩnh vực Cơ khí, Kiến trúc, HVAC & Piping và Điện. Phần mềm cung cấp thư viện ký hiệu, cấu kiện, thiết bị tiêu chuẩn, hỗ trợ tự động hóa thao tác vẽ và xuất thống kê vật tư, giúp doanh nghiệp tối ưu hiệu suất thiết kế và chi phí bản quyền.', 'Tin chuyên ngành', 'CADprofi – Phần mềm Add-on CAD giúp tăng tốc thiết kế và chuẩn hóa bản vẽ kỹ thuật', 'cadprofi-–-phan-mem-add-on-cad-giup-tang-toc-thiet-ke-va-chuan-hoa-ban-ve-ky-thuat', NULL, NULL, 'CADprofi là gì? Phần mềm Add-on CAD cho thiết kế kỹ thuật', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1675, 'vi', 'Trong lĩnh vực thiết kế xây dựng hiện nay, việc kết hợp một nền tảng CAD mạnh mẽ với các công cụ chuyên ngành kết cấu là giải pháp giúp kỹ sư nâng cao năng suất, giảm sai sót và tối ưu quy trình làm việc.', 'Tin chuyên ngành', 'enjiCAD và KetcauSoft – Bộ đôi giải pháp CAD & Thiết kế kết cấu tối ưu cho kỹ sư xây dựng', 'enjicad-va-ketcausoft-–-bo-doi-giai-phap-cad-amp;-thiet-ke-ket-cau-toi-uu-cho-ky-su-xay-dung', NULL, NULL, 'enjiCAD và KetcauSoft – Bộ đôi giải pháp CAD & Thiết kế kết cấu tối ưu cho kỹ sư xây dựng', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1676, 'vi', 'Nhiều chủ đầu tư vẫn cho rằng công trình xanh đòi hỏi chi phí cao hơn công trình thông thường. Tuy nhiên, nếu được tích hợp ngay từ giai đoạn thiết kế, khoản đầu tư ban đầu cho công trình xanh không phải là chi phí phát sinh, mà là chiến lược dài hạn giúp tối ưu vận hành, tiết kiệm năng lượng, nâng cao giá trị tài sản, đáp ứng yêu cầu ESG và tăng sức cạnh tranh cho dự án.', 'Tin chuyên ngành', 'Chi phí công trình xanh: Khoản đầu tư dài hạn cho chủ đầu tư', 'dau-tu-cong-trinh-xanh:-khong-phai-chi-phi-ma-la-chien-luoc-dai-han', NULL, NULL, 'Chi phí công trình xanh: Khoản đầu tư dài hạn cho chủ đầu tư', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1677, 'vi', 'CSI chính thức phát hành SAFE v23.3.0, phiên bản cập nhật mới dành cho phân tích và thiết kế hệ sàn, móng bê tông cốt thép và bê tông dự ứng lực. Bản cập nhật bổ sung thiết kế theo tiêu chuẩn CSA A23.3:2024, cải thiện hiệu năng, hỗ trợ Cloud License linh hoạt và tăng cường khả năng đồng bộ quy trình thiết kế. CIC là đối tác phân phối chính thức của CSI tại Việt Nam, cung cấp bản quyền SAFE chính hãng cùng dịch vụ tư vấn, cài đặt và hỗ trợ kỹ thuật chuyên sâu.', 'Tin chuyên ngành', 'SAFE v23.3.0  - Bản cập nhập chính thức 2026 phát hành bởi CIC', 'safe-v2330-chinh-thuc-phat-hanhban-quyen-csi-tai-cic', NULL, NULL, 'SAFE v23.3.0 chính thức phát hành | Bản quyền CSI tại CIC', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1679, 'vi', 'BIM đang mở rộng từ công cụ thiết kế và quản lý công trình thành nền tảng dữ liệu phục vụ quy hoạch đô thị và phát triển thành phố thông minh. Khi kết hợp với GIS, dữ liệu khảo sát, mô phỏng khí hậu, AI và IoT, BIM giúp phân tích hiện trạng, đánh giá nhiều phương án quy hoạch, dự báo tác động đến giao thông, hạ tầng, môi trường và cộng đồng.', 'Tin chuyên ngành', 'BIM trong quy hoạch đô thị: Từ mô hình công trình đến nền tảng dữ liệu cho thành phố thông minh', 'bim-trong-quy-hoach-do-thi:-tu-mo-hinh-cong-trinh-den-nen-tang-du-lieu-cho-thanh-pho-thong-minh', NULL, NULL, 'BIM trong quy hoạch đô thị: Nền tảng cho thành phố thông minh', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1678, 'vi', 'ETABS v23.3.0 là bản cập nhật quan trọng vừa ra mắt mang đến sự ổn định và hiệu năng tối ưu cho người dùng.', 'Tin chuyên ngành', 'ETABS v23.3.0 - Bản Cập Nhật Mới Nhất 2026 Chính Thức Được Phát Hành', 'etabs-v2330-ban-cap-nhat-moi-nhat-2026-chinh-thuc-duoc-phat-hanh', NULL, NULL, 'ETABS v23.3.0 - Bản Cập Nhật Mới Nhất 2026 Chính Thức Được Phát Hành', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1680, 'vi', 'Sàn giao dịch carbon là hệ thống giao dịch tập trung hạn ngạch phát thải khí nhà kính và tín chỉ carbon, được tổ chức vận hành tại Sở Giao dịch Chứng khoán Hà Nội. Bài viết tổng hợp điều kiện trở thành thành viên giao dịch, nguyên tắc mua bán, quyền và nghĩa vụ của các bên theo Nghị định 29/2026/NĐ-CP, đồng thời đưa ra những công việc doanh nghiệp phát thải cần chuẩn bị để tham gia thị trường carbon trong nước.', 'Tin chuyên ngành', 'Sàn giao dịch carbon là gì? Điều kiện tham gia và quy định giao dịch theo Nghị định 29/2026/NĐ-CP', 'san-giao-dich-carbon-la-gi-dieu-kien-tham-gia-va-quy-dinh-giao-dich-theo-nghi-dinh-292026nd-cp', NULL, NULL, 'Sàn giao dịch carbon là gì? Quy định theo Nghị định 29/2026', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1682, 'vi', 'Công ty Cổ phần Công nghệ và Tư vấn CIC vừa tổ chức Hội nghị sơ kết hoạt động kinh doanh 6 tháng đầu năm 2026. Đây là hoạt động quan trọng nhằm đánh giá tình hình thực hiện kế hoạch trong nửa đầu năm, đồng thời xác định các nhiệm vụ trọng tâm cho giai đoạn tiếp theo.', 'Tin công ty', 'CIC sơ kết hoạt động kinh doanh 6 tháng đầu năm 2026: Chủ động đổi mới, tăng cường kết nối', 'cic-so-ket-hoat-dong-kinh-doanh-6-thang-dau-nam-2026:-chu-dong-doi-moi-tang-cuong-ket-noi', NULL, NULL, 'CIC sơ kết hoạt động kinh doanh 6 tháng đầu năm 2026', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1683, 'vi', 'Việt Nam vừa nhận được 56,5 triệu USD từ Ngân hàng Thế giới (World Bank) sau khi cắt giảm được 10,3 triệu tấn khí thải CO2 nhờ các nỗ lực bảo vệ rừng và cải thiện quản lý đất đai.', 'Tin chuyên ngành', 'Việt Nam Nhận 56,5 Triệu USD Từ Tín Chỉ Carbon Rừng Do Ngân Hàng Thế Giới Chi Trả', 'viet-nam-nhan-565-trieu-usd-tu-tin-chi-carbon-rung-do-ngan-hang-the-gioi-chi-tra', NULL, NULL, 'Việt Nam Nhận 56,5 Triệu USD Từ Tín Chỉ Carbon Rừng Do Ngân Hàng Thế Giới Chi Trả', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1684, 'vi', 'Hãng CADprofi chính thức phát hành phiên bản CADprofi 2026.11 với nhiều cải tiến dành cho các nhóm ngành kiến trúc, điện, HVAC & Piping và cơ khí.', 'Tin chuyên ngành', 'CADprofi 2026.11 - Bản cập nhật thư viện, cải tiến công cụ và khả năng tương thích', 'cadprofi-202611-ban-cap-nhat-thu-vien-cai-tien-cong-cu-va-kha-nang-tuong-thich', NULL, NULL, 'CADprofi 2026.11: Cập nhật thư viện mới và tương thích nhiều nền tảng CAD', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1685, 'vi', '', 'Tin công ty', 'THANH LÝ MÁY KIỂM KHO / MÁY QUÉT MÃ VẠCH CASIO IT-800RGC-35', 'thanh-ly-may-kiem-khomay-quet-ma-vach-casio-it-800rgc-35', NULL, NULL, 'THANH LÝ MÁY KIỂM KHO / MÁY QUÉT MÃ VẠCH CASIO IT-800RGC-35', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1686, 'vi', 'Revit 2027 bổ sung Autodesk Assistant, kết nối sâu hơn với Autodesk Forma, tích hợp Issues và nâng cấp hiệu suất. Phiên bản mới cũng cải thiện quy trình thiết kế cho kiến trúc, kết cấu và MEP.', 'Tin chuyên ngành', 'Revit 2027: Bước tiến mới với AI và hệ sinh thái Autodesk Forma', 'revit-2027:-buoc-tien-moi-voi-ai-va-he-sinh-thai-autodesk-forma', NULL, NULL, 'Revit 2027 có gì mới? AI, Autodesk Forma và nâng cấp BIM nổi bật', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1687, 'vi', 'Trí tuệ nhân tạo đang trở thành năng lực cạnh tranh quan trọng của ngành xây dựng, giúp doanh nghiệp dự báo rủi ro, tối ưu chi phí, kiểm soát tiến độ, nâng cao an toàn và cải thiện hiệu quả vận hành công trình. Tuy nhiên, để AI phát huy giá trị, doanh nghiệp cần xây dựng nền tảng dữ liệu đồng bộ, quy trình số hóa rõ ràng và duy trì vai trò kiểm soát của đội ngũ chuyên môn.', 'Tin chuyên ngành', 'AI trong ngành Xây dựng: Từ công cụ hỗ trợ đến năng lực cạnh tranh cốt lõi', 'ai-trong-nganh-xay-dung:-tu-cong-cu-ho-tro-den-nang-luc-canh-tranh-cot-loi', NULL, NULL, 'AI trong ngành Xây dựng: Từ công cụ hỗ trợ đến năng lực cạnh tranh cốt lõi', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1688, 'vi', 'Trí tuệ nhân tạo đang mở ra hướng tiếp cận mới cho ngành địa chất, từ quản lý dữ liệu, phân tích ảnh lõi khoan đến tự động hóa các quy trình mô hình hóa phức tạp. Tuy nhiên, để AI tạo ra giá trị thực, yếu tố quan trọng nhất không chỉ là năng lực của mô hình, mà là chất lượng dữ liệu, ngữ cảnh chuyên môn và khả năng tích hợp vào quy trình làm việc của các chuyên gia địa chất.', 'Tin chuyên ngành', 'Ứng dụng trí tuệ nhân tạo (AI) trong khoa học địa chất', 'ung-dung-tri-tue-nhan-tao-ai-trong-khoa-hoc-dia-chat', NULL, NULL, 'Ứng dụng AI trong khoa học địa chất: Từ dữ liệu đến mô hình thông minh', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1689, 'vi', 'AI đang mở ra hướng mới cho thiết kế kết cấu khi không chỉ hỗ trợ hỏi – đáp như chatbot, mà còn có thể kết hợp với API và phần mềm kỹ thuật để tạo script, dashboard và tự động hóa các tác vụ lặp lại. Qua ví dụ từ IDEA StatiCa, bài viết cho thấy AI giúp kỹ sư chuẩn hóa liên kết, khảo sát tham số thiết kế và tối ưu workflow hiệu quả hơn, nhưng vẫn cần sự kiểm chứng và phán đoán chuyên môn của kỹ sư.', 'Tin chuyên ngành', 'Từ chatbot đến workflow: AI hỗ trợ kỹ sư kết cấu như thế nào?', 'ai-trong-thiet-ke-ket-cau:-tu-chatbot-den-tu-dong-hoa-workflow', NULL, NULL, 'Từ chatbot đến workflow: AI hỗ trợ kỹ sư kết cấu như thế nào?', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1690, 'vi', 'Vừa qua, Công ty Cổ phần Công nghệ và Tư vấn CIC phối hợp cùng hãng GeoSIG (Thụy Sỹ) đã tổ chức thành công Hội thảo trực tuyến với chủ đề: &quot;Nâng cao An toàn Đường sắt cao tốc thông qua Giám sát địa chấn thời gian thực và Hệ thống cảnh báo sớm&quot;. Sự kiện đã thu hút đông đảo sự quan tâm và tham dự của các chuyên gia, nhà quản lý cùng đại diện các doanh nghiệp trong lĩnh vực hạ tầng, giao thông và công trình ngầm.', 'Tin công ty', 'CIC và Hãng GeoSIG (Thụy Sỹ) tổ chức thành công Hội thảo Nâng cao an toàn Đường sắt cao tốc thông qua Giám sát địa chấn thời gian thực', 'cic-va-hang-geosig-thuy-sy-to-chuc-thanh-cong-hoi-thao-nang-cao-an-toan-duong-sat-cao-toc-thong-qua-giam-sat-dia-chan-thoi-gian-thuc', NULL, NULL, 'CIC và GeoSIG  tổ chức thành công Hội thảo Nâng cao an toàn Đường sắt cao tốc', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1691, 'vi', 'Công ty CP Công nghệ và Tư vấn CIC đã cung cấp bộ phần mềm PyroSim và Pathfinder của Thunderhead Engineering, Mỹ, cho Công ty TNHH Dịch vụ PCCC Đức Tâm. Việc trang bị hai công cụ mô phỏng chuyên sâu giúp doanh nghiệp nâng cao năng lực phân tích diễn biến cháy, lan truyền khói và quá trình thoát nạn, từ đó xây dựng các phương án phòng cháy, chữa cháy có cơ sở định lượng, trực quan và khả năng kiểm chứng cao hơn.', 'Tin công ty', 'CIC cung cấp bộ phần mềm mô phỏng cháy và thoát nạn PyroSim – Pathfinder cho Công ty TNHH Dịch vụ PCCC Đức Tâm', 'cic-cung-cap-bo-phan-mem-mo-phong-chay-va-thoat-nan-pyrosim-–-pathfinder-cho-cong-ty-tnhh-dich-vu-pccc-duc-tam', NULL, NULL, 'CIC cung cấp bộ phần mềm mô phỏng cháy và thoát nạn PyroSim – Pathfinder cho Công ty TNHH Dịch vụ PC', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1693, 'vi', 'Vùng phát thải thấp là gì và chính sách này ảnh hưởng thế nào đến doanh nghiệp? INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (1692, 'vi', 'Công ty CP Công nghệ và Tư vấn CIC vừa có buổi đón tiếp và làm việc với ông Thái Nguyễn – Chủ tịch Goble Pile Check (GPC), trong khuôn khổ hợp tác phát triển và chuyển giao công nghệ kiểm tra chất lượng nền móng tại Việt Nam.', 'Tin công ty', 'CIC đón tiếp Chủ tịch Goble Pile Check, thúc đẩy chuyển giao công nghệ kiểm tra biến dạng lớn của cọc PDA tại Việt Nam', 'cic-thuc-day-chuyen-giao-cong-nghe-kiem-tra-bien-dang-lon-cua-coc-pda-tai-viet-nam', NULL, NULL, 'CIC thúc đẩy chuyển giao công nghệ kiểm tra biến dạng lớn của cọc PDA tại Việt Nam', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (19, 'en', 'Ngày 18/01/2019, Công ty CP tin học và tư vấn xây dựng (CIC) đã tổ chức Lễ tổng kết tình hình hoạt động sản xuất kinh doanh năm 2018 và phương hướng hoạt động 2019.', 'News of Company', 'Chào 2019 - Công ty CIC vững bước phát triển', 'chao-2019-cong-ty-cic-vung-buoc-phat-trien', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (20, 'en', 'Phần mềm Vissim 9 phiên bản mới nhất của hãng PTV, giúp bạn hướng đến giải pháp tối ưu trong công tác mô phỏng, phân tích, xử lý các luồng giao thông đô thị.', 'Tin chuyên ngành', 'PTV ra mắt phiên bản mới của phần mềm VISSIM version 9', 'ptv-ra-mat-phien-ban-moi-cua-phan-mem-vissim-version-9', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
