INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (17, 'en', 'Nhân dịp kỷ niệm 28 năm ngày thành lập Công ty Cổ phần Tin học & Tư vấn xây dựng CIC (1990–2018), CIC long trọng tổ chức Lễ kỷ niệm vào ngày 27/11/2018 tại Hội trường 9A – Đào Tấn – Ba Đình - Hà Nội.', 'Tin công ty', 'Lễ Kỉ niệm 28 năm thành lập Công ty CIC', 'le-ki-niem-28-nam-thanh-lap-cong-ty-cic', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (15, 'en', 'Mới đây, vào ngày 10/10/2018, tại khách sạn Rex Saigon, hội thảo mang tên “NHỮNG ĐIỂM MỚI TRONG PHÂN TÍCH DỮ LIỆU VÀ QUẢN LÝ RỦI RO” do Công ty Cổ phần Tin học và Tư vấn Xây dựng (CIC) phối hợp cùng hãng DNV GL (Na Uy) tổ chức đã diễn ra thành công tốt đẹp.', 'Tin công ty', 'CIC và DNV GL kết hợp tổ chức Hội thảo "Những điểm mới trong Phân tích dữ liệu và Quản lý Rủi ro"', 'cic-va-dnv-gl-ket-hop-to-chuc-hoi-thaonhung-diem-moi-trong-phan-tich-du-lieu-va-quan-ly-rui-ro-', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (16, 'en', 'On the 23rd of October in 2018, under the instruction from official dispatch No. 7792 / VP-DT of Hanoi People''s Committee, a workshop on Real-time Traffic Management - PTV OPTIMA was held by Hanoi Department of Transport. Construction Informatics and Consultancy JSC (CIC) in coordination with PTV (Germany) presented and introduced the solution.', 'Tin công ty', 'Workshop: Smart Traffic Management Solution PTV OPTIMA - at Hanoi Department of Department of Transport', 'hoi-thao:-giai-phap-quan-ly-giao-thong-thong-minh-ptv-optima-tai-so-gtvt-ha-noi', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (216, 'en', 'On the 31st of October in 2018 CIC won the package: Supplying equipment for investigation of traffic safety – under the project: &quot;Enhancing the capacity of information technology application in traffic safety statistics, investigation, survey and data analysis ”of Transportation Development and Strategy Institute (TDSI).', 'Tin công ty', 'CIC and the Transportation Development and Strategy Institute (TDSI) completed handover and acceptance of Software Trazer (Traffic AnalyZer and EnumeratoR) of Kritikal  India', 'cic-and-the-transportation-development-and-strategy-institute-tdsi-completed-handover-and-acceptance-of-software-trazer-traffic-analyzer-and-enumerator-of-kritikal--india', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (22, 'en', 'CIC là đại lý ủy quyền của hãng PLAXIS BV tại Việt Nam. Với các giải pháp phần mềm địa kỹ thuật PLAXIS 2D, PLAXIS 3D. dưới đây là 6 lý do người dùng nên chọn giải pháp của PLAXIS.', 'Tin chuyên ngành', '6 Lý do nên chọn PLAXIS', '6-ly-do-nen-chon-plaxis', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (23, 'en', 'Phát triển mới nhất của PIPENET®, PIPENET phiên bản 1.9.0 có hơn 100 cải tiến bao gồm các mẫu, trình xem đồ thị được cải tiến và giao diện người dùng tinh gọn. Có nhiều cải tiến đáng kể làm cách mạng hóa trải nghiệm PIPENET. Đây là một bản tóm tắt các tính năng mới. Chúng tôi chắc chắn rằng khách hàng sẽ được tận hưởng những khả năng vượt trội của PIPENET phiên bản 1.9.0.', 'Tin chuyên ngành', 'Hãng Sunrise System phát hành phiên bản mới PIPENET 1.9.0', 'hang-sunrise-system-phat-hanh-phien-ban-moi-pipenet-190', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
