INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (25, 'en', 'Trong chương trình khuyến mại tháng 4, CIC tiếp tục gửi tới quý khách hàng chương trình giảm giá đặc biệt nhân dịp ngày Giải phóng Miền Nam và ngày Quốc tế lao động 30/4 -1/5.', 'Tin khuyến mại', 'Chương trình khuyến mại : Chào mừng ngày Giải phóng Miền Nam 30/4 - Quốc tế lao động 1/5', 'chuong-trinh-khuyen-mai-chao-mung-ngay-giai-phong-mien-nam-304-quoc-te-lao-dong-15', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
