INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (29, 'en', 'Công ty cổ phần Tin học và tư vấn Xây dựng (Construction Informatics & Consultancy Joint Stock Company - viết tắt CIC) là doanh nghiệp được cổ phần hóa từ Công ty Tin học Xây dựng trực thuộc Bộ Xây Dựng, hoạt động trong lĩnh vực công nghệ thông tin và xây dựng. Qua hơn 20 năm hoạt động, CIC đã cung cấp nhiều sản phẩm phần mềm trong ngành xây dựng và các lĩnh vực kỹ thuật khác tới đông đảo người sử dụng tại Việt Nam.', 'Tin tuyển dụng', 'Tuyển dụng: Kiến trúc sư', 'tuyen-dung-kien-truc-su', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (30, 'en', 'Công ty cổ phần Tin học và tư vấn Xây dựng (Construction Informatics & Consultancy Joint Stock Company - viết tắt CIC) là doanh nghiệp được cổ phần hóa từ Công ty Tin học Xây dựng trực thuộc Bộ Xây Dựng, hoạt động trong lĩnh vực công nghệ thông tin và xây dựng. Qua hơn 20 năm hoạt động, CIC đã cung cấp nhiều sản phẩm phần mềm trong ngành xây dựng và các lĩnh vực kỹ thuật khác tới đông đảo người sử dụng tại Việt Nam.', 'Tin tuyển dụng', 'Tuyển dụng: Kỹ sư lập dự toán', 'tuyen-dung-ky-su-lap-du-toan', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
