INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (85, 'en', 'Hoàn thành khóa đào tạo, hướng dẫn sử dụng thiết bị Georadar Ris Plus với ăngten 40 MHz và ăngten 200 MHz cho Viện Khoa học Địa chất và Khoáng sản', 'Tin công ty', 'Hoàn thành khóa đào tạo, hướng dẫn sử dụng thiết bị Georadar Ris Plus với ăngten 40 MHz và ăngten 200 MHz cho Viện Khoa học Địa chất và Khoáng sản', 'hoan-thanh-khoa-dao-tao-huong-dan-su-dung-thiet-bi-georadar-', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (86, 'en', 'Trường đại học Hồng Đức là trường đại học công lập đa ngành, một địa chỉ uy tín về đào tạo, nghiên cứu khoa học, chuyển giao công nghệ tại khu vực Bắc Trung Bộ.', 'Tin công ty', 'CIC ký hợp đồng cung cấp 01 thiết bị siêu âm cọc khoan nhồi CHUM của hãng Piletest (Israel) và 01 thiết bị định vị cốt thép HM của hãng Elcometer (Anh Quốc) với Trường đại học Hồng Đức', 'cic-ky-hop-dong-cung-cap-01-thiet-bi-sieu-am-coc-khoan-nhoi-', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (87, 'en', 'Trúng thầu và ký hợp đồng cung cấp thiết bị radar xuyên đất (Georadar – GPR) model Ris Plus của hãng IDS (Italia):”Thiết bị trắc địa, địa vật lý” cho Viện Khoa học Địa chất và Khoáng sản', 'Tin công ty', 'Trúng thầu và ký hợp đồng cung cấp thiết bị radar xuyên đất (Georadar )của hãng IDS :”Thiết bị trắc địa, địa vật lý” cho Viện Khoa học Địa chất và Khoáng sản', 'trung-thau-va-ky-hop-dong-cung-cap-thiet-bi-radar-xuyen-dat', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (88, 'en', 'Ngày 8/11/2013, tại trường Đại học kiến trúc Hồ Chí Minh,Cục Giám định Nhà nước về chất lượng công trình xây dựng - Bộ Xây dựng đã tổ chức thành công Hội thảo quốc tế về "CÔNG NGHỆ TIÊN TIẾN TRONG QUAN TRẮC VÀ KIỂM ĐỊNH CÔNG TRÌNH XÂY DỰNG".', 'Tin công ty', 'Hội thảo quốc tế về “CÔNG NGHỆ TIÊN TIẾN TRONG QUAN TRẮC VÀ KIỂM ĐỊNH CÔNG TRÌNH XÂY DỰNG”', 'hoi-thao-quoc-te-ve-cong-nghe-tien-tien-trong-quan-trac', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (89, 'en', 'CIC tiếp tục tổ chức thành công đợt khảo sát thiết bị Radar xuyên đất (GPR/Georadar) tại Hà Nội', 'Tin công ty', 'CIC tiếp tục tổ chức thành công đợt khảo sát thiết bị Radar xuyên đất (GPR Georadar) tại Hà Nội', 'cic-tiep-tuc-chuc-thanh-cong-dot-khao-sat-thiet-bi-radar-xuy', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (90, 'en', 'Sáng ngày 12/09/2013, hội thảo đã diễn ra tại Trường Đại học Thủy Lợi với sự tham gia của đông đảo các giảng viên Khoa Công trình, Viện Kỹ thuật công trình,...', 'Tin công ty', 'Hội thảo “Giới thiệu ứng dụng công nghệ radar xuyên đất (Georadar – GPR) trong khảo sát, kiểm tra tình trạng thân đê, thân đập” tại Đại học Thủy Lợi', 'hoi-thao-gioi-thieu-ung-dung-cong-nghe-radar-xuyen-dat-geora', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (91, 'en', 'Công ty CIC trúng gói thầu “ Mua bán phần mềm Tính toán vết dầu loang, theo dõi hướng di chuyển của dầu tràn”', 'Tin công ty', 'Công ty CIC trúng gói thầu “ Mua bán phần mềm Tính toán vết dầu loang, theo dõi hướng di chuyển của dầu tràn”', 'cong-ty-cic-trung-goi-thau-mua-ban-phan-mem-tinh-toan-vet-da', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (92, 'en', ' Công Ty TNHH Thương Mại Xây Dựng và Chuyển Giao Công Nghệ Mại Lâm là doanh nghiệp tư vấn, triển khai các dịch vụ kỹ thuật trong xây dựng, địa kỹ thuật và môi trường uy tín tại Việt Nam.', 'Tin công ty', 'Ký hợp đồng cung cấp 01 bộ thiết bị siêu âm cọc khoan nhồi CHUM (Hãng Piletest) với Công Ty TNHH Thương Mại Xây Dựng và Chuyển Giao Công Nghệ Mại Lâm', 'ky-hop-dong-cung-cap-01-bo-thiet-bi-sieu-am-coc-khoan-nhoi-c', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (93, 'en', 'Từ ngày 23 - 25/04/2013, Công ty Cổ phần Tin học & Tư vấn Xây dựng (CIC) đã tổ chức thành công các buổi thử nghiệm thiết bị Radar xuyên đất tại Hà Nội với các thông tin chi tiết như sau:', 'Tin công ty', 'CIC tổ chức thành công các buổi thử nghiệm thiết bị Radar xuyên đất GPR Georadar tại Hà Nội', 'cic-chuc-thanh-cong-cac-buoi-thu-nghiem-thiet-bi-radar-xuyen', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (94, 'en', 'Thỏa thuận hợp tác giữa Hiệp hội Tư vấn xây dựng Việt Nam (VECAS) và Công ty CP Tin học và Tư vấn xây dựng', 'Tin công ty', 'Thỏa thuận hợp tác giữa Hiệp hội Tư vấn xây dựng Việt Nam (VECAS) và Công ty CP Tin học và Tư vấn xây dựng', 'thoa-thuan-hop-tac-giua-hiep-hoi-tu-van-xay-dung-viet-nam-ve', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (95, 'en', 'Hãng phần mềm Deltares cung cấp các giải pháp chất lượng cao về thiết kế và phân tích các vấn đề về nước xung quanh khu vực sông, cửa sông, ven biển, ...', 'Tin công ty', 'CIC là nhà phân phối chính thức của Deltares tại Việt Nam', 'cic-la-nha-phan-phoi-chinh-thuc-cua-deltares-tai-viet-nam', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (96, 'en', 'Ngày 11/01/2013, Công ty Cổ phần Tin học & Tư vấn Xây dựng (CIC) đã hoàn tất công tác bàn giao, lắp đặt và hướng dẫn sử dụng thiết bị kiểm tra cáp thép LRM-XXI Diagnostic System cho Viện Cầu Hầm thuộc Viện Khoa học và Công nghệ Giao thông Vận tải (ITST) trong dự án "Mua sắm trang thiết bị thí nghiệm tăng cường năng lực NCKH năm 2012". Đây là dự án cung cấptrang thiết bị nhằm nâng cao công tác nghiên cứu khoa học cho các đơn vị trong viện ITST .', 'Tin công ty', 'Hoàn tất bàn giao và hướng dẫn sử dụng thiết bị kiểm tra cáp thép LRM-XXI Diagnostic System cho Viện Cầu Hầm thuộc Viện Khoa học và Công nghệ Giao thông Vận tải (ITST)', 'hoan-tat-ban-giao-va-huong-dan-su-dung-thiet-bi-kiem-tra-cap', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (97, 'en', 'Ngày 26/12/2012, Công ty Cổ phần Tin học & Tư vấn Xây dựng (CIC) đã hoàn tất công tác bàn giao, lắp đặt và hướng dẫn sử dụng thiết bị thăm dò địa chấn PASI 16S24-U cho Trường Đại học Khoa học Tự nhiên TP.HCM thuộc "dự án thành phần QG-HCM-07". Đây là dự án cung cấp  trang thiết bị phục vụ  phòng thí nghiệm nhằm nâng cao công tác nghiên cứu và giảng dạy cho  khoa Vật lý.', 'Tin công ty', 'Hoàn tất bàn giao và hướng dẫn sử dụng thiết bị thăm dò địa chấn PASI 16S24-U cho Trường Đại học Khoa học Tự nhiên TP.HCM', 'hoan-tat-ban-giao-va-huong-dan-su-dung-thiet-bi-tham-do-dia', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (98, 'en', 'Ngày 17/11/2012, Công ty Cổ phần Tin học & Tư vấn Xây dựng (CIC) đã bắt đầu tiến hành bàn giao, lắp đặt và hướng dẫn sử dụng Thiết bị radar xuyên đất (GPR/Georadar) RIS MF Hi-Mod #2 của Hãng IDS (Italia) cho Công ty TNHH Tư vấn Xây dựng Công trình ngầm Đô thị tại Thành phố Hồ Chí Minh. Nội dung chi tiết bao gồm:', 'Tin công ty', 'Hoàn tất bàn giao, lắp đặt và hướng dẫn sử dụng Thiết bị Radar xuyên đất GPR Georadar cho Công ty TNHH Tư vấn Xây dựng Công trình ngầm Đô thị', 'hoan-tat-ban-giao-lap-dat-va-huong-dan-su-dung-thiet-bi-rada', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (99, 'en', 'Như tin đã đưa, Trường Đại học Khoa học Tự nhiên trực thuộc Trường Đại học Quốc gia TP.HCM là một trường đại học kỹ thuật đầu ngành trong cả nước với các ngành mũi nhọn như: Toán - Tin học, Công nghệ thông tin, Khoa học máy tính, Hệ thống thông tin, Kỹ thuật phần mềm, Vật lý - Vật lý kỹ thuật, Điện tử - Viễn thông, Địa chất, .... Vừa qua, Trường đã tổ chức đấu thầu thành công gói thầu số 2: "Cung cấp và lắp đặt trang thiết bị tiếp theo cho các phòng thí nghiệm cơ bản Khoa Vật lý thuộc Trường Đại học Khoa học Tự nhiên năm 2012 - Dự án thành phần QG-HCM-07", theo hình thức đấu thầu rộng rãi, nhằm nâng cao năng lực công tác nghiên cứu - giảng dạy của Khoa Vật lý, và đã lựa chọn được nhà cung cấp theo đúng trình tự, thủ tục quy định trong Luật Đấu thầu.', 'Tin công ty', 'Ký hợp đồng cung cấp thiết bị thăm dò địa chấn của Hãng PASI Italia cho Trường Đại học Khoa học Tự nhiên Thành Phố Hồ Chí Minh', 'ky-hop-dong-cung-cap-thiet-bi-tham-do-dia-chan-24-kenh-model', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (100, 'en', '"Cung cấp và lắp đặt trang thiết bị tiếp theo cho các phòng thí nghiệm cơ bản Khoa Vật lý thuộc Trường Đại học Khoa học Tự nhiên năm 2012 - Dự án thành phần QG-HCM-07"', 'Tin công ty', 'Trúng thầu cung cấp thiết bị thăm dò địa chấn 24 kênh Model 16S24-U của Hãng PASI (Italia) gói thầu số 2', 'trung-thau-cung-cap-thiet-bi-tham-do-dia-chan-24-kenh-model-', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (101, 'en', 'Hiện tượng cáp dự ứng lực bị đứt trong quá trình khai thác do việc bơm vữa bảo vệ không tốt (để lại các lỗ rỗng) và sự rỉ mòn, đứt các sợi thép bên trong là một vấn đề đáng báo động trong lĩnh vực thi công cầu ví dụ như cầu Thị Nại (Quy Nhơn - Bình Định) - cây cầu vượt biển dài nhất Việt Nam tính cho đến thời điểm này.', 'Tin công ty', 'Cung cấp thiết bị kiểm tra cáp thép LRM®- XXI Diagnostic System cho Gói thầu “Mua sắm trang thiết bị thí nghiệm tăng cường năng lực NCKH 2012” của Viện Khoa học & Công nghệ Giao thông Vận tải (ITST)', 'cung-cap-thiet-bi-kiem-tra-cap-thep-lrmr-xxi-diagnostic', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (102, 'en', 'Ngày 05/09/2012, Công ty Cổ phần Tin học & Tư vấn Xây dựng (CIC) đã ký hợp đồng với Công ty TNHH Tư vấn Xây dựng Công trình ngầm Đô thị để cung cấp Thiết bị Radar xuyên đất RIS MF Hi-Mod #2 của Hãng IDS (Italia).', 'Tin công ty', 'Cung cấp Thiết bị Radar xuyên đất (GPR Georadar) Hãng IDS (Italia) cho Công ty TNHH Tư vấn Xây dựng Công trình ngầm Đô thị', 'cung-cap-thiet-bi-radar-xuyen-dat-gprgeoradar-ris-mf-hi-mod-', NULL, NULL, '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
