INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (295, 'en', 'Entering Q4 2024, enterprises listed in the greenhouse gas inventory under Decision 01/2022 and Decision 13/2024 are gradually beginning to implement greenhouse gas emission inventories, with the goal of completing greenhouse gas inventory reports before March 2025 to meet Government requirements and establish a basis for developing emission reduction roadmaps. CIC plays the role of strategic consultant, providing technical support during this inventory process.', 'News of Company', 'CIC Implements Greenhouse Gas Inventory and EPD for Steel and Cement Industry Enterprises', 'cic-implements-greenhouse-gas-inventory-and-epd-for-steel-and-cement-industry-enterprises', NULL, NULL, 'CIC Implements Greenhouse Gas Inventory and EPD for Steel and Cement Industry Enterprises', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (296, 'en', 'As part of promoting digital transformation in Quang Ninh Province''s water sector, CIC Technology and Consulting Joint Stock Company and Bentley organized a workshop on "Applying OpenFlows Solutions" for Quang Ninh Clean Water Company. This was an opportunity for experts and Quang Ninh Clean Water Company to exchange, share experiences, and learn about applying new technologies in water resource management to develop a secure, safe, efficient, and integrated water industry.', 'News of Company', 'CIC Workshop: Applying OpenFlows Solutions for Secure, Safe, &  Efficient Water Industry Development in Quang Ninh, Promoting Digital Transformation', 'cic-workshop:-applying-openflows-solutions-for-secure-safe-amp;efficient-water-industry-development-in-quang-ninh-promoting-digital-transformation', NULL, NULL, 'Applying OpenFlows Solutions for Secure, Safe, &  Efficient Water Industry Development in Quang Ninh', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (297, 'en', 'On November 19, 2024, Foxit officially announced the launch of the AI Assistant in the Foxit Admin Console, marking a significant advancement in optimizing product and license management. With this feature, Foxit not only reaffirms its leadership position in the industry but also provides an advanced solution that enables administrators to easily carry out complex tasks.', 'Specialized', 'Foxit Expands Leadership Position with the Launch of AI Assistant in Admin Console', 'foxit-expands-leadership-position-with-the-launch-of-ai-assistant-in-admin-console', NULL, NULL, 'Foxit Expands Leadership Position with the Launch of AI Assistant in Admin Console', '') ON CONFLICT (entity_id, locale) DO NOTHING;
