INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (299, 'en', 'On the occasion of the 34th founding anniversary of CIC Technology and Consulting Joint Stock Company (November 27, 1990 – November 27, 2024), the company''s staff and employees had a meaningful trip and successfully organized a commemorative ceremony in a warm and solemn atmosphere  November 24 to November 25, 2024, in Hanoi and Ho Chi Minh City Branch, with many activities connecting generations who have worked at CIC throughout 34 years.', 'News of Company', 'CIC Successfully Organizes Company''s 34th Founding Anniversary Celebration', 'cic-successfully-organizes-company-s-34th-founding-anniversary-celebration', NULL, NULL, 'CIC Successfully Organizes Company''s 34th Founding Anniversary Celebration', '') ON CONFLICT (entity_id, locale) DO NOTHING;
