INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (321, 'en', 'Seequent Evo is an advanced cloud platform that centralizes geoscience data management and enhances collaboration. Evo consolidates data  Seequent solutions such as Leapfrog Geo, Oasis montaj, MX Deposit, geospatial search with Cesium  Bentley Systems, as well as third-party applications into a single source of truth. This ensures information is always continuously updated, accurate, and easy to share. Evo provides an open API, supports AI and machine learning integration, and enables organizations to build custom applications and integrations tailored to their workflows.', 'Specialized', 'Seequent Evo: Cloud Platform for Geoscience Data Management', 'seequent-evo:-cloud-platform-for-geoscience-data-management', NULL, NULL, 'Seequent Evo: Cloud Platform for Geoscience Data Management', '') ON CONFLICT (entity_id, locale) DO NOTHING;
