INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (329, 'en', 'CIC Technology and Consultancy JSC successfully completes the Environmental Product Declaration (EPD) for flooring products. We provide expert LCA and EPD consultancy to help Vietnamese enterprises boost sustainable exports and achieve Net Zero 2050.', 'Specialized', 'CIC Completes EPD for Flooring Products – A Sustainable Export Solution', 'cic-completes-epd-for-flooring-products-–-a-sustainable-export-solution', NULL, NULL, 'CIC Completes EPD for Flooring Products – A Sustainable Export Solution', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (330, 'en', 'Vam Cong Bridge—one of the modern transport symbols of the Mekong Delta—is not only impressive in scale but also for its application of advanced Structural Health Monitoring (SHM) technology. At the heart of this system is the GMSplus accelerograph  GeoSIG (Switzerland).', 'Specialized', 'Vam Cong Bridge: Ensuring Structural Integrity with GeoSIG (Switzerland) Health Monitoring Technology', 'vam-cong-bridge:-ensuring-structural-integrity-with-geosig-switzerland-health-monitoring-technology', NULL, NULL, 'Vam Cong Bridge: Ensuring Structural Integrity with GeoSIG (Switzerland) Health Monitoring Technolog', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (331, 'en', 'CIC Technology and Consultancy Joint Stock Company has successfully completed a consulting project covering Life Cycle Assessment (LCA) and Environmental Product Declaration (EPD) for 14 construction chemical products belonging to Bumatech — one of the largest EPD projects in this sector in Vietnam to date.', 'News of Company', 'CIC Successfully Advises on EPD Certification for 14 Construction Chemical Products Published on EPD International', 'cic-successfully-advises-on-epd-certification-for-14-construction-chemical-products-published-on-epd-international', NULL, NULL, 'CIC Successfully Advises on EPD Certification for 14 Construction Chemical Products Published on EPD', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (332, 'en', 'Discover 10 benefits of BIM (Building Information Modeling) that help businesses reduce costs, detect clashes early, and manage construction comprehensively.', 'Specialized', 'Top 10 Benefits of BIM in Construction (2026)', 'top-10-benefits-of-bim-in-construction-2026', NULL, NULL, 'Top 10 Benefits of BIM in Construction (2026)', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (333, 'en', 'On May 15, 2026, CIC Technology and Consulting Joint Stock Company was honored to be invited to attend an important meeting on the implementation of strategic technology development tasks under Decision No. 808/QD-TTg dated May 6, 2026, issued by the Prime Minister. The meeting was chaired by Minister of Construction Tran Hong Minh.', 'News of Company', 'CIC Participates in the Strategic Technology Development Program for the Construction Industry', 'cic-participates-in-the-strategic-technology-development-program-for-the-construction-industry', NULL, NULL, 'CIC Joins Strategic Technology Program for Construction', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (334, 'en', 'Facing a severe labor shortage and an aging workforce, the global construction industry is standing at a critical turning point. The digital revolution on construction sites, driven by a new generation of intelligent robots powered by Embodied AI, has become the “golden key” to addressing this challenge. This solution not only frees workers  hazardous environments but also helps contractors optimize costs, accelerate project schedules, and strengthen their competitive advantage.', 'Specialized', 'Construction Site Digital Revolution: Solving the Construction Labor Crisis with Intelligent Robots', 'construction-site-digital-revolution:-solving-the-construction-labor-crisis-with-intelligent-robots', NULL, NULL, 'Construction Site Digital Revolution: Solving the Construction Labor Crisis with Robots', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (335, 'en', 'For high-speed railway (HSR) networks operating at speeds of 300 km/h to 350 km/h, even the slightest seismic vibrations may pose risks of track geometry deformation, derailment, and catastrophic accidents. This article introduces the Earthquake Early Warning (EEW) and Structural Health Monitoring (SHM) technology solutions developed by GeoSIG, a Swiss company with more than 30 years of experience in monitoring nuclear power plants, hydropower dams, high-speed railways, and critical infrastructure.', 'Specialized', 'GeoSIG – Earthquake Early Warning and Structural Health Monitoring System for High-Speed Railways', 'geosig-–-earthquake-early-warning-and-structural-health-monitoring-system-for-high-speed-railways', NULL, NULL, 'GeoSIG – Earthquake Early Warning and Structural Health Monitoring System for High-Speed Railways', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (336, 'en', 'Vietnam’s BIM regulations are entering a new phase under Decree No. 217/2026/ND-CP, effective  1 July 2026. The decree introduces important changes to BIM implementation, including the recognition of BIM models as legally equivalent to paper-based design dossiers, the exemption of paper drawings where BIM models are complete and accurate, mandatory Common Data Environment requirements for certain public investment projects, and the use of open data formats such as IFC. These updates mark a major step toward digital construction, helping investors, consultants, and contractors improve collaboration, reduce administrative procedures, and support smarter lifecycle asset management.', 'Specialized', 'New Regulations On Bim Implementation In Vietnam', 'new-regulations-on-bim-implementation-in-vietnam', NULL, NULL, 'New Regulations On Bim Implementation In Vietnam', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (337, 'en', 'CIC Technology and Consultancy Joint Stock Company has successfully delivered another QYSEA FIFISH V6 Expert remotely operated underwater vehicle (ROV) to a customer in Vietnam. The device features 4K UHD imaging, flexible 6-DOF mobility, powerful LED lighting, and compatibility with specialized accessories. FIFISH V6 Expert can be applied in underwater structure inspection, environmental monitoring, scientific research, search and rescue, professional filming, and underwater exploration.', 'News of Company', 'CIC Continues to Deliver FIFISH V6 Expert Underwater ROV, Expanding ROV Technology Applications in Vietnam', 'cic-continues-to-deliver-fifish-v6-expert-underwater-rov-expanding-rov-technology-applications-in-vietnam', NULL, NULL, 'CIC Delivers QYSEA FIFISH V6 Expert ROV in Vietnam', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (338, 'en', 'On June 18, 2026, CIC Technology and Consultancy Joint Stock Company successfully organized an online seminar to update enterprises on the latest legal regulations on greenhouse gas inventory, emissions mitigation, and the carbon market in Vietnam. The event attracted strong interest  enterprises in major emitting sectors such as iron and steel, cement, and thermal power, while also introducing the Net Zero 2050 App, a digital solution designed to help businesses standardize emissions data and prepare for upcoming reporting requirements.', 'News of Company', 'CIC Successfully Hosts Online Seminar to Update Enterprises on Greenhouse Gas Inventory Regulations and Vietnam’s Carbon Market', 'cic-successfully-hosts-online-seminar-to-update-enterprises-on-greenhouse-gas-inventory-regulations-and-vietnam’s-carbon-market', NULL, NULL, 'CIC Successfully Hosts Online Seminar to Update Enterprises on Greenhouse Gas Inventory Regulations', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (339, 'en', 'Vietnam’s Ministry of Construction now allows compliant BIM models to be used directly for quantity takeoff under Decision No. 1041/QD-BXD, reducing manual remeasurement and improving cost control efficiency.', 'Specialized', 'Digital Transformation Milestone: Ministry of Construction Officially Recognizes Quantities Extracted Directly  BIM Models', 'digital-transformation-milestone:-ministry-of-construction-officially-recognizes-quantities-extracted-directlybim-models', NULL, NULL, 'Digital Transformation Milestone: Vietnam Recognizes BIM-Extracted Quantities', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (340, 'en', 'CADprofi is a suite of specialized CAD add-ons that helps engineers work faster in Mechanical Engineering, Architecture, HVAC & Piping, and Electrical Design. The software provides libraries of standardized symbols, components and equipment, automates drafting operations and generates material schedules, helping businesses improve design productivity and optimize software licensing costs.', 'Specialized', 'CADprofi CAD Add-On: Faster Design and Standardized Drawings', 'cadprofi-cad-add-on:-faster-design-and-standardized-drawings', NULL, NULL, 'CADprofi CAD Add-On for Faster Design and Standardized Technical Drawings', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_news_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "title_display", "keywords", "seo_title", "seo_keyword") VALUES (341, 'en', 'CIC Construction Technology and Consultancy Joint Stock Company recently held its Business Performance Review Conference for the first half of 2026. This was an important activity aimed at assessing the implementation of the Company’s plans during the first six months of the year and identifying key priorities for the next phase.', 'News of Company', 'CIC Reviews Business Performance for the First Half of 2026: Proactive Innovation and Stronger Connections', 'cic-reviews-business-performance-for-the-first-half-of-2026:-proactive-innovation-and-stronger-connections', NULL, NULL, 'CIC Reviews First-Half 2026 Business Performance: Proactive Innovation and Stronger Connections', '') ON CONFLICT (entity_id, locale) DO NOTHING;
