INSERT INTO "cic_event_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "keywords", "seo_title", "seo_keyword", "name") VALUES (2, 'vi', 'Ngày 11/4/2024, Công ty cổ phần Công nghệ và Tư vấn CIC và Hãng Hexagon phối hợp tổ chức hội thảo trực tuyến với chủ đề CADWorx – Giải pháp hoàn thiện cho thiết kế nhà máy hiệu quả.', '', 'Đừng bỏ lỡ sự kiện tháng 4: Webinar CADWorx - Giải pháp hoàn thiện cho thiết kế nhà máy hiệu quả', 'dung-bo-lo-su-kien-thang-4:-webinar-cadworx-giai-phap-hoan-thien-cho-thiet-ke-nha-may-hieu-qua', NULL, 'Đừng bỏ lỡ sự kiện tháng 4: Webinar CADWorx - Giải pháp hoàn thiện cho thiết kế nhà máy hiệu quả', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
