INSERT INTO "cic_event_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "keywords", "seo_title", "seo_keyword", "name") VALUES (22, 'vi', 'Visicon BIM là giải pháp kiểm tra chất lượng mô hình BIM dễ dàng mở, xem, kiểm tra và so sánh dự án mô hình BIM. Đây là giải phải tiết kiệm chi phí cho các doanh nghiệp và người dùng. Để hiểu hơn về giải pháp Visicon BIM, Công ty CP Công nghệ và Tư vấn CIC phối hợp với hãng VISICON tổ chức hội thảo trực tuyến vào ngày 6/12/2024.', '', 'Hội thảo trực tuyến tháng 12: Visicon BIM – Giải pháp kiểm tra chất lượng mô hình BIM, nâng cao hiệu quả dự án', 'hoi-thao-truc-tuyen-thang-12:-visicon-bim-–-giai-phap-kiem-tra-chat-luong-mo-hinh-bim-nang-cao-hieu-qua-du-an', NULL, 'Hội thảo trực tuyến tháng 12: Vision BIM – Giải pháp kiểm tra chất lượng mô hình BIM, nâng cao hiệu', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_event_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "keywords", "seo_title", "seo_keyword", "name") VALUES (23, 'vi', 'Khám phá sức mạnh của phân tích xác suất 3D trong đánh giá độ ổn định mái dốc cùng GeoStudio tại Hội thảo trực tuyến miễn phí, được tổ chức vào ngày 11/3/2025.', '', 'Webinar tháng 3: Phân tích địa kỹ thuật - Phân tích ổn định xác suất 3D trong GeoStudio', 'webinar-thang-3:-phan-tich-dia-ky-thuat-phan-tich-on-dinh-xac-suat-3d-trong-geostudio', NULL, 'Webinar tháng 3: Phân tích địa kỹ thuật - Phân tích ổn định xác suất 3D trong GeoStudio', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_event_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "keywords", "seo_title", "seo_keyword", "name") VALUES (24, 'vi', 'Trong quá trình thi công cải tạo các công trình, đặc biệt là công trình cũ thường xuyên xảy ra  vấn đề yêu cầu tính toán lại liên kết khi có sự thay đổi. Giải quyết được bài toán này, phần mềm IDEA StatiCa mang đến giải pháp tối ưu, giúp doanh nghiệp xử lý nhanh chóng các thay đổi, đảm bảo tính toán liên kết chính xác và an toàn cho dự án.', '', '[Webinar tháng 3] - IDEA StatiCa: Giải pháp đáp ứng yêu cầu tính toán lại liên kết khi có sự thay đổi tại công trường', '[webinar-thang-3]-idea-statica:-giai-phap-dap-ung-yeu-cau-tinh-toan-lai-lien-ket-khi-co-su-thay-doi-tai-cong-truong', NULL, '[Webinar tháng 3] - IDEA StatiCa: Giải pháp đáp ứng yêu cầu tính toán lại liên kết khi có sự thay đổ', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_event_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "keywords", "seo_title", "seo_keyword", "name") VALUES (25, 'vi', 'Chúng tôi rất vui mừng được mời bạn tham gia hội thảo trực tuyến độc quyền khám phá vai trò đột phá của PV Elite® trong việc phát triển các cơ sở hiện đại diễn ra vào ngày 1 tháng 4 năm 2025. Phiên này được thiết kế đặc biệt cho các kỹ sư, nhà thiết kế, và quản lý dự án mong muốn khai thác toàn diện tiềm năng của các giải pháp phân tích bình áp lực và thiết bị trao đổi nhiệt.', '', '[Webinar tháng 4] Khai Phá Tiềm Năng của PV Elite® trong Thiết Kế Cơ Sở (Do Hexegon tổ chức)', '[webinar-thang-4]-khai-pha-tiem-nang-cua-pv-elite®-trong-thiet-ke-co-so-do-hexegon-to-chuc', NULL, '[Webinar tháng 4] Khai Phá Tiềm Năng của PV Elite® trong Thiết Kế Cơ Sở (Do Hexegon tổ chức)', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
