INSERT INTO "cic_event_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "keywords", "seo_title", "seo_keyword", "name") VALUES (28, 'vi', 'Chuyển đổi số không còn là xu hướng – đó là con đường sống còn trong ngành đường sắt, hạ tầng & công trình ngầm hiện đại. Chúng tôi trân trọng mời Quý vị tham gia hội thảo chuyên đề do CIC và Bentley tổ chức tại TP.HCM vào ngày 22/5/2025 để cập nhật công nghệ mới, kết nối chuyên gia, và khám phá các case study thực tế đã thay đổi cách thế giới làm hạ tầng.', '', '[Sự kiện tháng 5] Hội thảo chuyên đề: Giải pháp số của Bentley cho Đường sắt, Hạ tầng và Công trình ngầm – Nền tảng tích hợp từ Thiết kế đến Vận hành', '[su-kien-thang-5]-hoi-thao-chuyen-de:-giai-phap-so-cua-bentley-cho-duong-sat-ha-tang-va-cong-trinh-ngam-–-nen-tang-tich-hop-tu-thiet-ke-den-van-hanh', NULL, '[Sự kiện tháng 5] Hội thảo chuyên đề: [Sự kiện tháng 5] Hội thảo chuyên đề: Giải pháp số của Bentley', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
