INSERT INTO "cic_event_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "keywords", "seo_title", "seo_keyword", "name") VALUES (33, 'vi', 'Nhằm giới thiệu thông tin của HiCAD đến khách hàng tại Việt Nam, Công ty Cổ phần Công nghệ và Tư vấn CIC, đại lý ủy quyền của ISD Engineering tại Việt Nam tổ chức chương trình Hội thảo “HiCAD - Giải pháp CAD 3D cho Kết cấu thép và Mặt dựng (Facade) ”.', '', '[29/01/2026] Webinar miễn phí:  HiCAD - Giải pháp CAD 3D cho Kết cấu thép và Mặt dựng (Facade)', 'hoi-thao-truc-tuyen-thang-12026:-hicad-giai-phap-cad-3d-cho-ket-cau-thep-va-mat-dung-facade', NULL, '[29/01/2026] Webinar miễn phí:  HiCAD - Giải pháp CAD 3D cho Kết cấu thép và Mặt dựng (Facade)', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_event_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "keywords", "seo_title", "seo_keyword", "name") VALUES (34, 'vi', 'Ngày 23/4/2026, Công ty CP Công nghệ và Tư vấn CIC phối hợp cùng Bentley System lần đầu tiên tổ chức sự kiện đặc biệt INNOVATION Day tại TP.Hồ Chí Minh. Hội thảo diễn ra trong nửa ngày và tập trung vào tương lai kỹ thuật số của hạ tầng.', '', '[Sự kiện tháng 4] Bentley Innovation Day 2026 tại TP. Hồ Chí Minh định hình tương lai số cho hạ tầng Việt Nam', '[su-kien-thang-4]-bentley-innovation-day-2026-tai-tp-ho-chi-minh-dinh-hinh-tuong-lai-so-cho-ha-tang-viet-nam', NULL, 'Bentley Innovation Day 2026 tại TP. Hồ Chí Minh định hình tương lai số cho hạ tầng Việt Nam', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_event_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "keywords", "seo_title", "seo_keyword", "name") VALUES (35, 'vi', 'Nhằm cập nhật xu hướng chuyển đổi số và chia sẻ kinh nghiệm thực tiễn trong ngành khai thác mỏ, Công ty Cổ phần Công nghệ và Tư vấn CIC cùng Worley tổ chức hội thảo trực tuyến với chủ đề Worley - Ứng dụng mô hình thông tin công trình (BIM) trong quản lý dự án. Sự kiện mang đến cơ hội để doanh nghiệp và chuyên gia tiếp cận các giải pháp mới, đồng thời trao đổi trực tiếp với các đơn vị giàu kinh nghiệm trong lĩnh vực.', '', 'Sự kiện tháng 5: CIC phối hợp với Worley tổ chức hội thảo trực tuyến về ứng dụng BIM trong ngành khai thác mỏ', 'su-kien-thang-5:-cic-phoi-hop-voi-worley-to-chuc-hoi-thao-truc-tuyen-ve-ung-dung-bim-trong-nganh-khai-thac-mo', NULL, 'CIC phối hợp với Worley tổ chức hội thảo trực tuyến về ứng dụng BIM trong ngành khai thác mỏ', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_event_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "keywords", "seo_title", "seo_keyword", "name") VALUES (38, 'vi', 'Công ty Cổ phần Công nghệ và Tư vấn CIC tổ chức hội thảo trực tuyến “Nâng cao An toàn Đường sắt cao tốc thông qua Giám sát địa chấn thời gian thực và Hệ thống cảnh báo sớm” vào ngày 22/07/2026. Chương trình tập trung giới thiệu các công nghệ giám sát địa chấn, cảnh báo sớm động đất và giải pháp GeoSIG trong việc phát hiện rung chấn, tích hợp dữ liệu với hệ thống điều hành, tín hiệu và điều khiển chạy tàu. Hội thảo là cơ hội để các đơn vị quản lý, chủ đầu tư, tư vấn, nhà thầu và chuyên gia trong lĩnh vực giao thông – hạ tầng tiếp cận các mô hình công nghệ giúp nâng cao an toàn cho đường sắt tốc độ cao, metro và các công trình trọng điểm.', '', 'Hội thảo trực tuyến: “Nâng cao An toàn Đường sắt cao tốc thông qua Giám sát địa chấn thời gian thực và Hệ thống cảnh báo sớm”', 'hoi-thao-truc-tuyen:-nang-cao-an-toan-duong-sat-cao-toc-thong-qua-giam-sat-dia-chan-thoi-gian-thuc-va-he-thong-canh-bao-som', NULL, 'Hội thảo trực tuyến: “Nâng cao An toàn Đường sắt cao tốc thông qua Giám sát địa chấn thời gian thực', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_event_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "keywords", "seo_title", "seo_keyword", "name") VALUES (36, 'vi', 'Tham gia buổi Webinar đặc biệt vào ngày 14/05/2026 (Giờ Việt Nam) để cùng CIC khám phá những tính năng vượt trội của phiên bản IDEA StatiCa 26.0. Đăng ký ngay để nhận tư vấn từ chuyên gia!', '', 'Webinar tháng 5: IDEA StatiCa 26.0 tăng khả năng tương tác BIM và AI cho thiết kế', 'webinar-thang-5:-idea-statica-260-tang-kha-nang-tuong-tac-bim-va-ai-cho-thiet-ke', NULL, 'Webinar tháng 5: IDEA StatiCa 26.0 tăng khả năng tương tác BIM và AI cho thiết kế', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
