INSERT INTO "cic_event_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "keywords", "seo_title", "seo_keyword", "name") VALUES (10, 'en', 'On September 27th, 2024, CIC Technology and Consulting JSC, in collaboration with IDEA StatiCa, will host an online webinar on: BIM WORKFLOW for Steel & Concrete WITH IDEA STATICA (BIM workflow for Steel and Concrete with the IDEA StatiCa solution).', '', 'Webinar: BIM WORKFLOW for Steel & Concrete WITH IDEA STATICA', 'webinar:-bim-workflow-for-steel-amp;-concrete-with-idea-statica', NULL, 'Webinar: BIM WORKFLOW for Steel & Concrete WITH IDEA STATICA', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_event_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "keywords", "seo_title", "seo_keyword", "name") VALUES (11, 'en', 'PYROSIM, PATHFINDER & VENTUS WORKSHOP 2024', '', 'PYROSIM, PATHFINDER & VENTUS WORKSHOP 2024', 'pyrosim-pathfinder-amp;-ventus-workshop-2024', NULL, 'PYROSIM, PATHFINDER & VENTUS WORKSHOP 2024', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_event_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "keywords", "seo_title", "seo_keyword", "name") VALUES (12, 'en', 'Visicon BIM is a BIM model quality checking solution that enables easy opening, viewing, checking, and comparing BIM project models. This is a cost-effective solution for businesses and users. To gain deeper insights into the Visicon BIM solution, CIC Technology and Consultancy Joint Stock Company is collaborating with VISICON to host an online seminar on December 6, 2024.', '', 'December Online Webinar: Visicon BIM - BIM Model Quality Checking Solution, Enhancing Project Efficiency', 'december-online-webinar:-visicon-bim-bim-model-quality-checking-solution-enhancing-project-efficiency', NULL, 'December Online Webinar: Visicon BIM - BIM Model Quality Checking Solution, Enhancing Project Effici', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_event_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "keywords", "seo_title", "seo_keyword", "name") VALUES (13, 'en', 'CIC Technology and Consulting Joint Stock Company organizes a specialized seminar with the topic Technology solutions for digital transformation of the mining industry at 9:00 a.m. on April 15, 2025 in Ha Long City.', '', '[April Event] Industry Seminar: "TECHNOLOGY SOLUTIONS FOR DIGITAL TRANSFORMATION IN THE MINING INDUSTRY"', '[april-event]-industry-seminar:technology-solutions-for-digital-transformation-in-the-mining-industry-', NULL, '[April Event] Industry Seminar: "TECHNOLOGY SOLUTIONS FOR DIGITAL TRANSFORMATION IN THE MINING INDUS', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_event_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "keywords", "seo_title", "seo_keyword", "name") VALUES (14, 'en', 'Discover the latest features of IDEA StatiCa v25 in a free webinar on May 30, 2025 – explore automation, parametric design, and fire resistance analysis for steel connections with CIC and IDEA StatiCa.', '', '[May Webinar] IDEA StatiCa v25: Automation, Optimization & Fire Resistance Analysis for Steel Connections', '[may-webinar]-idea-statica-v25:-automation-optimization-amp;-fire-resistance-analysis-for-steel-connections', NULL, '[May Webinar] IDEA StatiCa v25: Automation, Optimization & Fire Resistance Analysis for Steel Connec', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_event_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "keywords", "seo_title", "seo_keyword", "name") VALUES (16, 'en', 'Join CIC & Metsims online workshop on LCA Reporting & EPD Certification. Learn tools for green manufacturing & sustainable growth. Free registration. June 10, 2025.', '', 'Webinar: LCA Reporting and EPD Certification: Building the Foundation for Green Manufacturing & Sustainable Development', 'webinar:-lca-reporting-and-epd-certification:-building-the-foundation-for-green-manufacturing-amp;-sustainable-development', NULL, 'Webinar: LCA Reporting and EPD Certification: Building the Foundation for Green Manufacturing & Sust', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_event_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "keywords", "seo_title", "seo_keyword", "name") VALUES (15, 'en', 'Join CIC &amp; Bentley’s May 2025 workshop in Ho Chi Minh City. Explore cutting-edge digital solutions for railways, infrastructure &amp; underground works. Register now!', NULL, 'Bentley Digital Solutions for Railways &amp; Infrastructure | May 2025 Workshop | CIC Event', 'bentley-digital-solutions-for-railways-amp;-infrastructure--may-2025-workshop--cic-event', NULL, 'Bentley Digital Solutions for Railways &amp; Infrastructure | May 2025 Workshop | CIC Event', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_event_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "keywords", "seo_title", "seo_keyword", "name") VALUES (17, 'en', '', '', 'Digital Technology and AI Workshop Redefines Vietnam’s Construction and Real Estate Industry', 'digital-technology-and-ai-workshop-redefines-vietnam’s-construction-and-real-estate-industry', NULL, 'Digital Technology and AI Workshop Redefines Vietnam’s Construction and Real Estate Industry', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_event_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "keywords", "seo_title", "seo_keyword", "name") VALUES (18, 'en', 'On January 29, 2026, CIC Technology and Consulting Joint Stock Company organized a free online webinar titled “HiCAD – 3D CAD Solution for Steel Structures and Façade” to introduce the HiCAD software and its applications in designing steel structures and façade systems', NULL, '[January 29, 2026] Free Webinar: HiCAD – 3D CAD Solution for Steel Structures and Façade', '[january-29-2026]-free-webinar:-hicad-–-3d-cad-solution-for-steel-structures-and-façade', NULL, '[January 29, 2026] Free Webinar: HiCAD – 3D CAD Solution for Steel Structures and Façade', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_event_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "keywords", "seo_title", "seo_keyword", "name") VALUES (19, 'en', 'Join Bentley Innovation Day 2026 at New World Saigon Hotel on April 23. Explore AI-driven solutions for construction, water, and energy with CIC and Bentley Systems.', NULL, 'Bentley Innovation Day 2026 in Ho Chi Minh City: Shaping the Digital Future for Vietnam’s Infrastructure', 'bentley-innovation-day-2026-in-ho-chi-minh-city:-shaping-the-digital-future-for-vietnam’s-infrastructure', NULL, 'Bentley Innovation Day 2026 in Ho Chi Minh City: Shaping the Digital Future for Vietnam’s Infrastruc', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_event_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "keywords", "seo_title", "seo_keyword", "name") VALUES (20, 'en', 'CIC Construction Technology and Consultancy JSC organizes an online webinar in June 2026 to update businesses on the latest legal regulations related to greenhouse gas inventory, emissions reduction, and Vietnam’s carbon credit market. The event also introduces the Net Zero 2050 App, a digital solution designed to support enterprises in standardizing emissions data, improving reporting readiness, and meeting upcoming compliance requirements.', '', 'June Webinar: “Legal Updates on Greenhouse Gas Inventory and the Carbon Credit Market”', 'june-webinar:-legal-updates-on-greenhouse-gas-inventory-and-the-carbon-credit-market', NULL, 'June Webinar: “Legal Updates on Greenhouse Gas Inventory and the Carbon Credit Market”', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_event_translations" ("entity_id", "locale", "summary", "category_name", "title", "alias", "keywords", "seo_title", "seo_keyword", "name") VALUES (21, 'en', 'CIC Technology and Consultancy JSC cooperates with Worley to organize an online webinar on the application of BIM in construction project management for the mining industry. The event focuses on how BIM and Common Data Environment solutions support centralized data management, multidisciplinary coordination, and improved project execution efficiency across complex mining and infrastructure projects.', '', 'May Event: CIC Cooperates with Worley to Organize an Online Webinar on the Application of BIM in the Mining Industry', 'may-event:-cic-cooperates-with-worley-to-organize-an-online-webinar-on-the-application-of-bim-in-the-mining-industry', NULL, 'CIC and Worley Webinar on BIM Applications in Mining Projects', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (199, 'vi', 'GeoStudio - Gói phần mềm phân tích ổn định mái dốc', 'geostudio', NULL, 'GeoStudio gói phần mềm mô hình hóa địa kỹ thuật dành cho các kỹ sư, chuyên gia địa kỹ thuật', NULL, NULL, 'Phần mềm', 'GeoStudio - Gói phần mềm phân tích ổn định mái dốc', 'GeoStudio', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (305, 'vi', 'Lantek - Phần mềm gia công kim loại tấm', 'phan-mem-thiet-ke-va-gia-cong-kim-loai-lantek', NULL, 'Lantek là bộ giải pháp phần mềm toàn diện cho ngành công nghiệp gia công kim loại tấm và thép định hình.', NULL, NULL, 'Phần mềm', 'Lantek - Phần mềm gia công kim loại tấm', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (57, 'vi', 'RDW - Phần mềm bổ sung TCVN vào các chương trình tính kết cấu nước ngoài RDW', 'rdw-dua-tcvn-vao-cac-chuong-trinh-tinh-ket-cau-nuoc-ngoai', 'Khác', 'Hiện nay các phần mềm SAP90/SAP2000, ETABS (công ty CSI - Mỹ), STAADIII/STAADPRO (công ty REI - Mỹ) được sử dụng rộng rãi tại Việt Nam. Tuy nhiên việc sử dụng chỉ dừng lại ở bước tính toán nội lực do trong các phần mềm này chưa có Tiêu chuẩn thiết kế của Việt nam. RDW chính là phần mềm tiếp nối với SAP, ETABS, STAAD, bổ sung thiết kế và xuất bản vẽ theo TCVN cho các phần mềm nói trên.', NULL, 'Kết cấu công trình', 'Phần mềm', 'Phần Mềm Đưa TCVN VàoCác Chương Trình Tính Kết Cấu Nước Ngoài - RDW', 'thiết kế xây dựng', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (58, 'vi', 'VinaSAS - Phần mềm tính toán thiết kế khung hỗn hợp', 'vinasas-phan-mem-tinh-toan-thiet-ke-khung-hon-hop-1', 'Khác', 'Trong lĩnh vực tư vấn thiết kế xây dựng, vấn đề thiết kế công trình với sự trợ giúp của máy vi tính đã được ứng dụng tương đối rộng rãi ở Việt Nam đi vào từng lĩnh vực như kiến trúc, kết cấu, điện nước... Về mặt thiết kế kết cấu, các công ty tư vấn xây dựng trong cả nước và đặc biệt là các thành phố lớn như Hà Nội, thành phố Hồ Chí Minh, Đà Nẵng... đã sử dụng khá nhiều chương trình tính toán kết cấu, có thể kể ra các chương trình tiêu biểu như KP (trong môi trường DOS), FBT, HT, các chương trình của nước ngoài như SAP, STAAD, MICROFEAP... hoặc các chương trình tự lập bởi các cán bộ sở tại. Các chương trình nói trên chủ yếu đều đưa ra được các kết quả về nội lực, diện tích cốt thép trên các cấu kiện bê tông cốt thép theo các tiêu chuẩn, từ đó các kỹ sư thiết kế phải tiến hành chọn cách bố trí cốt thép và thể hiện chi tiết trên bản vẽ thi công. Cách tiến hành như vậy mới chỉ mang tính tự động hoá một phần, bởi vì trong thiết kế công trình, công việc tính toán thường chiếm thời gian không nhiều, việc thể hiện bản vẽ mới chính là công đoạn tốn phần lớn thời gian thiết kế. Vì vậy một phần mềm có tính tự động hoá cao (tương tự như chương trình PKPM của Trung Quốc ) từ tổ hợp nội lực, thiết kế cấu kiện, đến tự động thể hiện bản vẽ theo TCVN chính là mong muốn của nhiều nhà tư vấn thiết kế.INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (59, 'vi', 'MBW - Phần mềm phân tích, thiết kế móng băng', 'mbw-phan-mem-tinh-mong-bang', 'Khác', 'MBW là phần mềm tự động hoá phân tích thiết kế kết cấu móng băng bê tông cốt thép đưa ra kết quả cuối cùng là bản vẽ kỹ thuật thi công, đồng thời cũng có thể thực hiện phân tích hệ kết cấu dầm giao nhau.', NULL, 'Kết cấu công trình', 'Phần mềm', 'Phần Mềm Phân Tích, Thiết Kế Móng Băng - MBW', 'thiết kế kết cấu móng', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (409, 'vi', 'Caesar II: Phần Mềm Phân Tích Ứng Suất Đường Ống Dành Cho Kỹ Sư Cơ Khí', 'caesar-ii', NULL, 'CAESAR II – Phần mềm phân tích ứng suất đường ống hàng đầu thế giới từ Hexagon PPM.', NULL, NULL, 'Phần mềm', 'Caesar II: Phần Mềm Phân Tích Ứng Suất Đường Ống Dành Cho Kỹ Sư Cơ Khí', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (293, 'vi', 'R160WJ - Rô bốt vệ sinh cống ngầm', 'ro-bot-ve-sinh-cong-ngam', NULL, 'Rô bốt vệ sinh cống ngầm được trang bị vòi phun tia nước áp lực tới 3000 bar, có thể dễ dàng loại bỏ các loại rác thải, bùn, rễ cây, cặn kim loại, bê tông... khỏi đường cống chỉ trong vài phút.', NULL, NULL, 'Thiết bị', 'R160WJ - Rô bốt vệ sinh cống ngầm', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (60, 'vi', 'MCW - Phần mềm phân tích, thiết kế móng cọc', 'mcw-phan-mem-tinh-toan-mong-coc', 'Xây dựng', 'MCW là chương trình tính toán thiết kế và kiểm tra đối với móng cọc đài thấp. Chương trình được xây dựng trên cơ sở  những tiêu chuẩn móng cọc hiện hành  như  Tiêu chuẩn thiết kế móng cọc 20 TCN 21-86 (nay là TCXD205-98), tiêu chuẩn cọc tiết diện nhỏ, Móng cọc CTFE, Nền và móng... và chạy trên môi trường Windows9x/2000/NT.  Chương trình MCW có giao diện đẹp, trực quan, thuận lợi khi nhập số liệu và tính toán, kết quả tính toán đầy đủ ở cả tệp tin kết quả và bản vẽ thi công móng.', NULL, 'Kết cấu công trình', 'Phần mềm', 'PHẦN MỀM PHÂN TÍCH, THIẾT KẾ MÓNG CỌC MCW', 'MCW', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (61, 'vi', 'stCAD - Phần mềm hỗ trợ vẽ thiết kế xây dựng và bóc tiên lượng', 'stcad-ho-tro-ve-thiet-ke-xay-dung-va-boc-tien-luong', 'Xây dựng', 'stCAD là phần mềm hỗ trợ vẽ thiết kế xây dựng và tính tiên lượng dự toán tự động. Với môi trường đồ hoạ đa chức năng, stCAD cung cấp cho kỹ sư xây dựng bộ công cụ hỗ trợ thiết kế khá hoàn thiện. Chỉ bằng một vài thao tác xác lập đơn giản, stCAD đã có thể cung cấp cho các kỹ sư bản vẽ kỹ thuật cuối cùng của các kết cấu: dầm, cột, mặt bằng kết cấu, sàn, móng... một cách nhanh chóng và chính xác theo đúng các tiêu chuẩn hiện hành đang được áp dụng ở Việt Nam. Ngoài ra, stCAD còn có thể đọc kết quả thiết kế của các phần mềm như RDW, VinaSAS, SAP2000, ETABS... để xuất ra bản vẽ cũng như tự động bố trí cốt thép cho cấu kiện từ các kết quả phân tích thiết kế của các phần mềm trên. Hơn thế nữa, stCAD có thể bóc tách tiên lượng dự toán cho các cấu kiện (bóc khối lượng bê tông, ván khuôn, cốt thép).', NULL, 'Kết cấu công trình', 'Phần mềm', 'Phần Mềm Hỗ Trợ Vẽ Thiết Kế Xây Dựng Và Bóc Tiên Lượng - stCAD 5x', 'thiết kế xây dựng', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (62, 'vi', 'enjiCAD - Phần mềm CAD thay thế', 'enjicad_phan_mem_cad_thay_the_autocad', 'Xây dựng', 'enjiCAD là phần mềm CAD dành riêng cho người Việt với bản quyền vĩnh viễn. Giá mua bản quyền vĩnh viễn của enjiCAD còn thấp hơn giá thuê bao 01 năm của phần mềm CAD nổi tiếng khác. ', NULL, 'Kết cấu công trình', 'Phần mềm', 'enjiCAD - Phần mềm CAD thay thế', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (383, 'vi', 'WaterGEMS - Phần mềm Phân tích, thiết kế và tối ưu hóa hệ thống phân phối nước sạch', 'watergems-phan-mem-phan-tich-thiet-ke-va-toi-uu-hoa-he-thong-phan-phoi-nuoc-sach', NULL, 'Là một phần mềm ứng dụng mô hình hóa thủy lực, WaterGEMS cung cấp môi trường giao diện dễ sử dụng giúp bạn tự tin phân tích, thiết kế và tối ưu hóa hệ thống phân phối nước sạch của mình.', NULL, NULL, 'Phần mềm', '', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (208, 'vi', 'CIC PLANNING - Phần mềm Quản lý Dự Án', 'phan-mem-quan-ly-du-cic-planning', NULL, 'CIC PLANNING là phần mềm quản lý điều hành thực hiện các dự án, theo dõi tiến độ thi công, xây lắp, nghiệm thu, thanh quyết toán các hạng mục của từng dự án.', NULL, NULL, 'Phần mềm', 'CIC PLANNING - Phần mềm Quản lý Dự Án', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
