INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (65, 'vi', 'KIW - Phần mềm tính toán, thiết kế khung thép tiền chế ', 'kiw-phan-mem-tinh-toan-thiet-ke-khung-thep-tien-che', 'Xây dựng', 'KIW là phần mềm tự động hoá phân tích thiết kế kết cấu khung thép tiền chế đưa ra kết quả cuối cùng là bản vẽ kỹ thuật thi công đối với khung thép có các cấu kiện thanh tiết diện chữ I. Đặc biệt KIW có khả năng thiết kế tối ưu đảm bảo điều kiện chịu lực và tiết kiệm vật liệu nhất', NULL, 'Đào tạo lái xe', 'Phần mềm', 'KIW - Phần mềm tính toán, thiết kế khung thép tiền chế', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (67, 'vi', 'Escon - Phần mềm dự toán Escon', 'phan-mem-du-toan-escon-15', 'Xây dựng', 'Escon 15 là phần mềm tính đơn giá dự toán, dự thầu, thẩm tra được Công ty CP Tin học và tư vấn xây dựng phát triển từ năm 2000 trải qua nhiều phiên bản như Escon 3, Escon 4, Escon 5, Escon 6, Escon 7 (2011), Escon 8(2012) và hiện nay là Escon phiên bản 15. Thừa kế những tính năng mạnh của các phiên bản trước Escon 15 không ngừng phát triển bổ sung rất nhiều tính năng độc đáo mà chưa một phần mềm lập dự toán xây dựng công trình nào có.', NULL, 'Dự toán công trình', 'Phần mềm', '', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (69, 'vi', 'TecknoSim - Thiết bị Cabin mô phỏng để đào tạo lái xe ô tô ', 'thiet-bi-cabin-mo-phong-dao-tao-lai-xe', NULL, 'Hệ thống mô phỏng lái xe ôtô là một giải pháp tối ưu để đào tạo các lái xe mới và lái xe có kinh nghiệm giúp cải thiện kỹ năng lái xe của họ. Hệ thống cho phép các học viên thành thạo các kỹ năng lái xe và đối mặt với tình huống nguy hiểm trong cuộc sống thực, mà không cần phải đối mặt với nguy hiểm thực sự', NULL, NULL, 'Thiết bị', 'TecknoSim - Thiết bị Cabin mô phỏng để đào tạo lái xe ô tô', 'Hệ thống mô phỏng và đào tạo lái xe', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (332, 'vi', 'LRM - Kiểm tra cáp thép bằng phương pháp từ dư', 'lrm-kiem-tra-cap-thep-bang-phuong-phap-tu-du', NULL, 'Hãng thiết bị LRM (Laboratory Dr Roman Martyna) là công ty hàng đầu thế giới về hệ thống kiểm tra không phá hủy chất lượng cáp và đường ống thép bằng phương pháp từ dư (MFL). Hệ thống LRM-XXI Diagnostic được phát triển bởi Dr.Roman Martyna, người có hơn 30 năm kinh nghiệm sáng chế, cung cấp dịch vụ trong lĩnh vực kiểm tra cáp thép ứng dụng công nghệ hiện đại.', NULL, NULL, 'Phần mềm', 'LRM - Kiểm tra cáp thép bằng phương pháp từ dư', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (241, 'vi', 'Autodesk AutoCAD - Phần mềm vẽ kỹ thuật', 'autodesk-autocad', NULL, 'AutoCAD là phần mềm thiết kế 2D và 3D chuyên nghiệp. Với phiên bản AutoCAD 2020, người dùng sẽ được trang bị thêm các bộ công cụ hỗ trợ (specialized toolsets) cho các lĩnh vực khác nhau cùng với phiên bản AutoCAD nền web, ứng dụng di động.', NULL, NULL, 'Phần mềm', 'Autodesk AutoCAD - Phần mềm vẽ kỹ thuật', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (300, 'vi', 'HOMESTYLER - Giải pháp thiết kế nội thất trên nền tảng cloud', 'homestyler-thiet-ke-3d-nhung-ngoi-nha-trong-mo', NULL, 'Homestyler là giải pháp cung cấp công cụ thiết kế nội thất 3D hiệu quả cho các nhà thiết kế và cung cấp các giải pháp chuyển đổi kỹ thuật số cho ngành nội thất và bất động sản.', NULL, NULL, 'Phần mềm', 'HOMESTYLER - Giải pháp thiết kế nội thất trên nền tảng cloud', 'homestyler, phần mềm nội thất', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (206, 'vi', 'CICTKT - Phần mềm thống kê thép', 'cictkt', NULL, 'Phần mềm hỗ trợ thống kê thép – CICTKT là phần mềm đã được công ty chúng tôi phát triển với giao diện đồ họa thân thiện người dùng. CICTKT sẽ là công cụ trợ giúp đắc lực cho các kỹ sư xây dựng để hoàn thành nhanh chóng việc thống kê toàn bộ cốt thép của mọi công trình xây dựng. CICTKT hoàn toàn miễn phí đối với các đơn vị, cá nhân đã mua một trong số các phần mềm của chúng tôi (có khoá cứng); trong trường hợp quý khách hàng chỉ muốn mua CICTKT thì giá phần mềm cài đặt cho 1 máy sẽ là 500.000 VNĐ (chúng tôi sẽ cung cấp mã cài đặt cho máy tính của quý khách hàng (mã mềm).', NULL, NULL, 'Phần mềm', 'CICTKT - Phần mềm thống kê thép', 'phần mềm thống kê thép', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (72, 'vi', 'Sumac - Phần mềm tính toán san nền', 'sumac', NULL, 'Trong lĩnh vực tư vấn thiết kế, quy hoạch xây dựng và giao thông... sự trợ giúp của máy tính với các phần mềm tính toán ngày càng trở nên thông dụng. Việc xây dựng một chương trình tính toán, mô hình hoá địa hình, tạo đường đồng mức và đặc biệt là tính toán khối lượng đào đắp trong xây dựng và giao thông là hết sức cần thiết. Xuất phát từ nhu cầu đó, trung tâm Phần mềm Xây dựng - thuộc Công ty CP Công nghệ và Tư vấn Xây dựng CIC đã hoàn thành việc xây dựng phần mềm Sumac phục vụ cho công việc mô hình hoá bề mặt địa hình, tạo đường đồng mức, tạo bình đồ, tính toán San nền theo cách tính thực tế của kỹ sư Việt Nam. Chương trình Sumac có giao diện đồ hoạ dễ sử dụng (hệ đồ hoạ này tương tự AutoCAD), có khả năng mô hình hoá một cách chính xác bề mặt địa hình, tạo đường đồng mức, tạo bình đồ bằng phương pháp nội suy lưới ô vuông và tạo mặt cắt địa hình. Kết quả tính toán được thể hiện đầy đủ trên bản vẽ (bề mặt địa hình, đường đồng mức, bình đồ, kết quả tính toán san lấp theo từng ô và tổng cộng khối lượng đào đắp theo từng hàng, cột trên hệ lưới ô vuông). Bản vẽ kết quả có thể được xuất ra dưới định dạng AutoCAD (*.DWG; *.DXF).', NULL, NULL, 'Phần mềm', '', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (201, 'vi', 'GEO5 - Phần mềm phân tích địa kỹ thuật', 'geo5', NULL, 'GEO5 là một bộ phần mềm, cung cấp giải pháp cho hầu hết các vấn đề địa kỹ thuật', NULL, NULL, 'Phần mềm', 'GEO5 - Phần mềm phân tích địa kỹ thuật', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
