INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (88, 'vi', 'Thiết bị siêu âm mối hàn, siêu âm kim loại của Hãng NDT Systems (Hoa Kỳ), Starmans (CH Séc)', 'thiet-bi-sieu-am-moi-han-va-kim-loai', NULL, 'NDT Systems là một trong những hãng thiết bị đi đầu trong lĩnh vực kiểm tra không phá hủy. Sản phẩm của hãng bao gồm một loạt các thiết bị: thiết bị siêu âm đo chiều dày kim loại, siêu âm dò khuyết tật cầm tay, hệ thống siêu âm hiển thị hình ảnh. Cùng với sự phát triển của công nghệ, NDT Systems liên tục đưa ra các dòng sản phẩm mới để phục vụ cho nhu cầu ngày càng cao của khách hàng', NULL, NULL, 'Thiết bị', '', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
