INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (91, 'vi', 'Thiết bị xuyên tĩnh của hãng A.P.Vanden Berg (Hà Lan)', 'thiet-bi-xuyen-tinh-apvanden-berg', NULL, 'Được thành lập từ năm 1968, A.P.Van den Berg là nhà sản xuất, phân phối thiết bị thí nghiệm xuyên tĩnh hàng đầu trên thế giới hiện nay. Ngoài ra, A.P.Van den Berg còn là nhà phân phối các thiết bị thủy lực, tham gia vào các dự án lớn trên toàn thế giới.', NULL, NULL, 'Thiết bị', '', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
