INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (96, 'vi', 'Troxler - Thiết bị đo độ chặt, độ ẩm nền đất đắp, bê tông nhựa', 'thiet-bi-do-do-chat-do-am-troxler', NULL, 'Thành lập năm 1958, Troxler hiện đang là đơn vị hàng đầu trên thế giới về các thiết bị đo lường, kiểm tra chất lượng trong các ngành công nghiệp và xây dựng đường cao tốc.', NULL, NULL, 'Thiết bị', 'Troxler - Thiết bị đo độ chặt, độ ẩm nền đất đắp, bê tông nhựa', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (95, 'vi', 'Geonor  - Thiết bị cắt cánh hiện trường (VST)', 'thiet-bi-cat-canh-hien-truong-vst', NULL, 'Với hơn 30 năm kinh nghiệm, Geonor chuyên cung cấp các sản phẩm thiết bị cắt cánh hiện trường để xác định sức kháng cắt không thoát nước của đất, được sử dụng cho các loại đất dính mềm yếu, bão hoà nước.', NULL, NULL, 'Thiết bị', 'Geonor  - Thiết bị cắt cánh hiện trường (VST)', 'cắt cánh hiện trường', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
