INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (99, 'vi', 'OILMAP DEEP - Giải pháp dầu tràn ở trên bề mặt biển', 'phan-mem-oilmap-deep', NULL, 'OILMAPDEEP là phần mềm cung cấp những phán đoán nhanh chóng của sự di chuyển của dầu tràn ở trên bề mặt biển. Cả sự kết hợp mô đun công nghiệp CDOG và mô hình chùm tự nhiên của OILMAP cũng được hỗ trợ.', NULL, NULL, 'Phần mềm', 'OILMAP DEEP - Giải pháp dầu tràn ở trên bề mặt biển', 'OILMAP DEEP', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (100, 'vi', 'PLAXIS VIP - Gói bảo trì, cập nhật phần mềm Plaxis', 'plaxis-vip', NULL, 'Plaxis VIP là một hệ thống đăng ký bổ sung dựa trên bản quyền truyền thống, được hiểu như là một khoản chi phí bảo trì hàng năm cho phần mềm Plaxis.', NULL, NULL, 'Phần mềm', 'PLAXIS VIP - Gói bảo trì, cập nhật phần mềm Plaxis', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (191, 'vi', 'Thiết bị thí nghiệm nén 3 trục ', 'thiet_bi_thi_nghiem_nen_3_truc', NULL, 'Các thiết bị địa kỹ thuật phòng thí nghiệm thực hiện các thí nghiệm trong các lĩnh vực cơ lý đất, đá trong phòng.', NULL, NULL, 'Thiết bị', 'Thiết bị thí nghiệm nén 3 trục - CBR hãng APS, GDS, Walter -bai', 'thiết bị nén 3 trục, nén đất, nén đá, đo vết lún, uốn nén 4 điểm.', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (101, 'vi', 'PLAXIS MoDeTo - Phần mềm thiết kế cọc monopie', 'plaxis-modeto', NULL, 'PLAXIS MoDeTo - Dòng sản phẩm mới của PLAXIS ứng dụng thiết kế cọc monopile ứng dụng trong các công trình ngoài khơi', NULL, NULL, 'Phần mềm', 'PLAXIS MoDeTo - Phần mềm thiết kế cọc monopie', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
