INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (104, 'vi', 'Renishaw - Thiết bị quét Laser khảo sát, bản đồ hóa 3D biên dạng khảo sát các khu mỏ, khoang rỗng dưới lòng đất', 'thiet-bi-quet-laser-khao-sat-ban-do-hoa-3d-bien-dang-khao-sat-cac-khu-mo-khoang-rong-duoi-long-dat-cua-hang-renishaw-anh-quoc', NULL, 'Được thành lập vào năm 1983, Renishaw là công ty hàng đầu thế giới trong việc thiết kế và sản xuất các hệ thống thiết bị đo laser tốc độ cao sử dụng trong môi trường khắc nghiệt.', NULL, NULL, 'Thiết bị', 'Renishaw - Hãng thiết bị quét Laser khảo sát, bản đồ hóa 3D biên dạng khảo sát các khu mỏ, khoang rỗ', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (190, 'vi', 'Thiết bị giám sát ảnh hưởng chấn động và áp suất sóng không khí/ tiếng ồn của Instantel (Canada)', 'thiet-bi-giam-sat-anh-huong-chan-dong-va', NULL, 'Từ năm 1982, Instantel, một bộ phận của Xmark Corporation và là thành viên của The Stanley Works, đã tạo được vị trí dẫn đầu cho lĩnh vực cung cấp các thiết bị đo đạc dao động phục vụ cho các ngành xây dựng, khai khoáng và địa kỹ thuật. Từ những sensor chuyên dụng, những định dạng ghi dữ liệu phức tạp, cho tới dữ liệu biểu đồ thời gian thực, thu thập dữ liệu từ xa thông qua mạng internet, Instantel tiếp tục quá trình đổi mới liên tục nhằm phục vụ tốt nhất nhu cầu khách hàng.', NULL, NULL, 'Phần mềm', 'Thiết bị giám sát của Instantel ', 'thiết bị theo dõi xây dựng', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (105, 'vi', 'Thiết bị quét Sonar khảo sát và vẽ biên dạng 3D các khoang rỗng dưới lòng đất, quét biên dạng đáy sông, biển của Hãng Imagenex (Canada)', 'thiet-bi-quet-sonar', NULL, 'Imagenex là công ty hàng đầu thế giới về công nghệ quét Sonar. Với công nghệ quét Sonar, không có gì quan trọng hơn là việc có được các hình ảnh rõ nét. Do vậy, Imagenex có đội ngũ thiết kế luôn luôn đi tiên phong trong việc phát triển công nghệ hình ảnh Sonar hiện đại và sản xuất các thiết bị Sonar độ phân giải cao.', NULL, NULL, 'Thiết bị', '', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (107, 'vi', 'AET - ĐÊ MỀM CHỐNG NGẬP - NGĂN LŨ ', 'de-mem-chong-ngap-ngan-lu-hang-aet', NULL, 'Sản phẩm Đê mềm chống ngập Tự động, dễ triển khai Hiệu quả cho các chung cư, các tòa nhà, các tầng hầm. Chống ngập lụt do mưa lũ cho các công trình đang thi công, xây dựng.', NULL, NULL, 'Thiết bị', 'AET - ĐÊ MỀM CHỐNG NGẬP - NGĂN LŨ ', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (108, 'vi', 'OILMAP LAND - Hệ thống mô hình tràn trên đất và dưới nước', 'phan-mem-oilmap-land', NULL, 'OILMAPLAND là hệ thống mô hình tràn trên đất và dưới nước để mô phỏng sự giải phóng của dầu và chất hóa học từ đường ống và kho lưu trữ. OILMAPLAND cần cho một số công cụ mô hình cho tràn dầu và hóa chất mà nó xảy ra trên đất và rồi tràn ra sông suối và ao hồ.', NULL, NULL, 'Phần mềm', 'OILMAP LAND - Hệ thống mô hình tràn trên đất và dưới nước', 'OILMAP LAND', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (109, 'vi', 'CHEMMAP - Phần mềm mô hình hóa quá trình chuyển động của chất thải hóa học', 'phan-mem-chemmap', NULL, 'CHEMMAP là một phần mềm giúp mô hình hóa quá trình chuyển động của các chất thải hóa học để dự đoán quỹ đạo, số phận, tác động và các hiệu ứng sinh học của nhiều loại chất hóa học ba chiều.', NULL, NULL, 'Phần mềm', 'CHEMMAP - Phần mềm giúp mô hình hóa quá trình chuyển động của các chất thải hóa học', 'CHEMMAP', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (110, 'vi', 'SARMAP - Phần mềm dự báo sự chuyển động của vật thể trôi trên biển ', 'phan-mem-sarmap', NULL, 'Tính năng cơ bản: INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (111, 'vi', 'Cơ sở dữ liệu EDS', 'co-so-du-lieu-eds', NULL, 'EDS: Environmental Data ServerTM bao gồm các dữ liệu về hải dương học và khí tượng học được sử dụng để đáp ứng nhu cầu của ngành hàng hải và quản lý sự cố trong ngành (mô phỏng các mô hình mẫu phục vụ công tác tìm kiếm và lên kế hoạch ứng cứu với sự cố tràn dầu/hoá chất) cũng như các ứng dụng trong môi trường.', NULL, NULL, 'Phần mềm', 'Cơ sở dữ liệu EDS - Phần mềm đánh giá thiệt hại do nổ', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (369, 'vi', 'FIFISH PRO W6 - Rô bốt lặn biển', 'fifish-pro-w6-ro-bot-lan-bien', NULL, 'FIFISH PRO W6 là rô bốt chuyên dụng phục vụ cho việc kiểm tra, đánh giá hiện trạng an toàn của các cơ sở hạ tầng ngoài khơi với độ sâu lên tới 350m.', NULL, NULL, 'Thiết bị', '', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (112, 'vi', 'Maros - Công cụ phân tích RAM', 'maros-cong-cu-phan-tich-ram-tham-do-dau', NULL, 'Maros™ là một công cụ phân tích RAM* cao cấp, với những tính năng mở rộng cho việc mô phỏng cấu trúc hoạt động của doanh nghiệp, các nhu cầu, các kế hoạch bảo trì và vận hành. Maros™ hỗ trợ người dùng ra các quyết định chính xác để tối đa hóa mức doanh thu trên vốn đầu tư bỏ ra.', NULL, NULL, 'Phần mềm', 'Maros - Công cụ phân tích RAM', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (113, 'vi', 'Synergi Plant - Phần mềm quản lý rủi ro tài sản', 'synergi-plant-quan-ly-rui-ro-nha-may', NULL, 'Synergi Plant là một giải pháp phần mềm của DNV, được xây dựng trên thực tiễn kỹ thuật và kinh nghiệm quản lý. Phần mềm sẽ cung cấp một cách tiếp cận PDCA hoàn chỉnh để quản lý rủi ro tài sản, đã được sử dụng bởi các khách hàng hoạt động trong nhà máy quy trình thượng nguồn và hạ nguồn ở các vùng khác nhau trên thế giới.', NULL, NULL, 'Phần mềm', 'Synergi Plant - Phần mềm quản lý rủi ro tài sản', 'Synergi Plant', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (114, 'vi', 'PTV Optima - Giải pháp quản lý giao thông thời gian thực', 'giai-phap-quan-ly-giao-thong-thoi-gian-t', NULL, 'PTV Optima là chìa khóa giúp bạn quản lý giao thông một cách hiệu quả. Công cụ mô phỏng này cung cấp những thông tin giao thông theo thời gian thực của toàn bộ mạng lưới giao thông một cách chính xác và đưa ra các dự báo đáng tin cậy về tinh hình giao thông trong 60 phút tiếp theo.', NULL, NULL, 'Phần mềm', 'PTV Optima - Giải pháp quản lý giao thông thời gian thực', 'Giải Pháp Quản Lý Giao Thông ', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (386, 'vi', 'Thiết bị thí nghiệm thử động biến dạng lớn (PDA) - Goble Pile Check (PDA-GPC)', 'thiet-bi-thi-nghiem-thu-dong-bien-dang-lon-pda-goble-pile-check-pda-gpc', NULL, 'Thiết bị thí nghiệm thử động biến dạng lớn (PDA) - Goble Pile Check  là một hệ thống phân tích động cọc không dây được phát triển bởi Goble Pile Test, Inc. of Longmont, Colorado từ năm 2009.', NULL, NULL, 'Thiết bị', 'Thiết bị thí nghiệm thử động biến dạng lớn (PDA) - Goble Pile Check (PDA-GPC)', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (115, 'vi', 'SynerGEE Gas -  Giải pháp khai khác thiết kế và phát triển hệ thống đường ống và mạng hiệu suất cao', 'synergee-gas-mo-phong-he-thong-phan-phoi', NULL, 'SynerGEE® Gas giúp các nhà khai khác thiết kế và phát triển hệ thống đường ống và mạng hiệu suất cao với chi phí phù hợp, khả năng cung cấp đến các mức nhu cầu dự kiến. ', NULL, NULL, 'Phần mềm', 'SynerGEE Gas -  Giải pháp khai khác thiết kế và phát triển hệ thống đường ống và mạng hiệu suất cao', 'SynerGEE Gas', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (285, 'vi', 'Noggin 1000 - Radar xuyên đất kiểm tra, khảo sát chất lượng công trình giao thông', 'gpr-kiem-tra-chat-luong-cong-trinh', NULL, 'Hệ thống radar xuyên đất kiểm tra, khảo sát chất lượng công trình giao thông  Noggin 1000  được sử dụng để phân tích, kiểm tra kết cấu mặt đường ( số lượng, chiều dày các phân lớp); xác định các điểm bất thường, cục bộ như vết nứt, khoảng trống; định vị chính xác các đối tượng bên dưới bề mặt như: cốt thép, đường thoát nước,..', NULL, NULL, 'Thiết bị', 'Hệ thống radar xuyên đất kiểm tra, khảo sát chất lượng công trình giao thông', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (117, 'vi', 'Synergi Water - Phần mềm mô hình hóa và phân tích mạng lưới ống dẫn khép kín', 'synergi-water-phan-mem-mo-phong', NULL, 'Synergi Water - gói phần mềm mô phỏng của chúng tôi cho mô hình hóa và phân tích mạng lưới ống dẫn khép kín của đường ống, bộ máy điều chỉnh, van, máy bơm, hồ chứa nước, bể chứa nước, giếng đào và giếng khoan - cho phép bạn khởi động nhanh chóng, kết quả mô hình chính xác. Synergi Water được sử dụng bởi hàng trăm công ty dịch vụ công cộng, các công ty trung nguồn dầu mỏ và khí đốt và các công ty kỹ thuật trên toàn thế giới.', NULL, NULL, 'Phần mềm', 'Synergi Water - Phần mềm mô hình hóa và phân tích mạng lưới ống dẫn khép kín', 'Synergi Water', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (118, 'vi', 'Synergi Life - Phần mềm quản lý rủi ro và QHSE', 'phan-mem-quan-ly-rui-ro-synergi-life', NULL, 'Synergi Life là một giải pháp dành cho các doanh nghiệp để quản lý rủi ro và QHSE. Phần mềm bao gồm rất nhiều các tiến trình công việc như báo cáo, phân tích, hành động khắc phục, thông tin liên lạc, chia sẻ kinh nghiệm, định hướng và giám sát chỉ số hiệu suất “KPI”.', NULL, NULL, 'Phần mềm', 'Synergi Life - Phần mềm quản lý rủi ro và QHSE', 'Phần mềm quản lý rủi ro', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (119, 'vi', 'Safeti Offshore - Phương pháp đánh giá rủi ro', 'safeti-offshore', NULL, 'Safeti Offshore cung cấp một cách tiếp cận tiêu chuẩn có cấu trúc và hệ thống dành cho việc tiến hành đánh giá định lượng rủi ro ngoài khơi. Nó cung cấp nhiều khả năng mạnh mẽ chính xác, linh hoạt và phong phú để thực hiện đa dạng việc đánh giá định lượng rủi ro cho các công trình ngoài khơi', NULL, NULL, 'Phần mềm', 'Safeti Offshore - Phương pháp đánh giá rủi ro', 'Phương pháp đánh giá rủi ro', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (122, 'vi', 'PTV VISSIM - Phần mềm mô phỏng giao thông', 'phan-mem-mo-phong-giao-thong-ptv-vissim', NULL, 'VISSIM là phần mềm mô phỏng, phân tích luồng giao thông, hỗ trợ công tác phân luồng, góp phần giảm tắc nghẽn giao thông trong các đô thị.', NULL, NULL, 'Phần mềm', 'PTV VISSIM - Phần mềm mô phỏng giao thông', 'Phần mềm mô phỏng giao thông', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (121, 'vi', 'PTV VISUM - Phần mềm quy hoạch giao thông', 'phan-mem-quy-hoach-giao-thong-ptv-visum', NULL, 'PTV VISUM 15 - Phần mềm phân tích, dự báo, lập phương án quy hoạch giao thông đô thị. Visum 15 là phần mềm hàng đầu thế giới để mô hình hóa mạng lưới giao thông. Được thiết kế để phân tích đa phương thức, VISUM kết hợp tất cả các đối tượng có liên quan đến giao thông vận tải (ví dụ: ô tô, xe chở khách, xe hàng, xe buýt, tầu hỏa, xe máy, xe đạp và khách bộ hành) bên trong cùng một mô hình mạng.', NULL, NULL, 'Phần mềm', 'PTV VISUM - Phần mềm quy hoạch giao thông ', 'Phần mềm quy hoạch giao thông', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (123, 'vi', 'LEAK - Phần mềm tính toán tần số rò rỉ ', 'leak-phan-mem-tinh-toan-tan-so-ro-ri', NULL, 'Phần mềm LEAK tính toán tần số rò rỉ của các thiết bị, phân đoạn, các khu vực và các cài đặt từ dữ liệu cơ sở cơ bản', NULL, NULL, 'Phần mềm', 'LEAK - Phần mềm tính toán tần số rò rỉ ', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (124, 'vi', 'Phast Software - Phần mềm mô phỏng hậu quả ', 'phast-phan-mem-mo-phong-hau-qua', NULL, 'Phần mềm phân tích rủi ro - mô hình hóa hậu quả toàn diện cho tất cả các giai đoạn của quá trình thiết kế và vận hành ngành công nghiệp.', NULL, NULL, 'Phần mềm', 'Phần mềm mô phỏng hậu quả Phast Software - CIC Company', 'Phần mềm mô phỏng hậu quả', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (126, 'vi', 'HVE Software - Tái tạo, mô phỏng và phân tích tai nạn xe cơ giới', 'tai-tao-mo-phong-va-phan-tich-tai-nan', NULL, 'Phần mềm này được dùng để tái tạo va chạm xe cơ giới, phần mềm tái hiện tai nạn cho một hoặc nhiều xe va chạm. Mục đích là xác định tốc độ tác động và mức độ nghiêm trọng của tác động dựa trên vị trí tai nạn và thiệt hại phương tiện. Phần mềm cho phép mô phỏng xe cơ giới, bao gồm số lượng xe, va chạm nhiều đối tượng và các dạng va chạm. Phần mềm này giúp các nhà nghiên cứu xác định được các yếu tố góp phần vào vụ tai nạn đường bộ mà còn xác định được tiềm năng kết quả chấn thương của người trong xe từ những tai nạn tương tự.', NULL, NULL, 'Phần mềm', 'HVE Software - Tái tạo, mô phỏng và phân tích tai nạn xe cơ giới', 'Tái tạo, mô phỏng và phân tích tai nạn', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (128, 'vi', 'Safeti - Phần mềm đánh giá rủi ro định lượng', 'phan-mem-danh-gia-rui-ro-safeti', NULL, 'Phần mềm đánh giá định lượng rủi ro và tần suất rủi ro các công trình công nghiệp.', NULL, NULL, 'Phần mềm', 'Safeti - Phần mềm đánh giá rủi ro định lượng', 'Phần mềm đánh giá rủi ro', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (130, 'vi', 'CALPUFF VIEW - Phần mềm  mô hình hóa nguồn phát không ổn định Gaussian', 'phan-mem-calpuff-view', NULL, 'Là dạng mô hình nguồn phát không ổn định Gaussian mô phỏng sự di chuyển tầm xa của hóa chất trong khí quyển, cho những trường hợp khó khăn (tầm nhìn hạn chế, hướng gió, địa hình phức tạp). Cung cấp một giải pháp đồ họa hoàn chỉnh cho hệ thống mô hình hóa CALPUFF, CALMET, và CALPOST. CALPUFF View hỗ trợ EPA version 5.8 và phiên bản cao cấp 6.0 của hệ thống CALPUFF.', NULL, NULL, 'Phần mềm', 'CALPUFF VIEW - Phần mềm  mô hình hóa nguồn phát không ổn định Gaussian', 'CALPUFF VIEW', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (131, 'vi', 'CALRoads VIEW - Phần mềm mô hình hóa phân tán hóa chất ô nhiễm trong không khí', 'calroads-view', NULL, 'Là một mô hình phân tán hóa chất ô nhiễm trong không khí đối với giao thông đô thị, dự đoán nồng độ ô nhiễm không khí của khí (CO,NO2), dạng hạt (PM), và các loại khí trơ khác từ phương tiện nhàn rỗi hoặc di chuyển. . CALRoads View là giao diện tích hợp của các mô hình: CALINE4 , CAL3QHC, and CAL3QHCR.', NULL, NULL, 'Phần mềm', 'CALRoads VIEW - Phần mềm mô hình hóa phân tán hóa chất ô nhiễm trong không khí', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (132, 'vi', 'Auto Track Rail - Phân tích con đường cho xe điện và phương tiện đường sắt', 'auto-track-rail', NULL, 'Auto Track Rail là phần mềm phân tích đường cho xe điện và các phương tiện đường sắt khác, kiểm tra và đánh giá các chuyển động của xe điện và xe đường sắt nhẹ khác. ', NULL, NULL, 'Phần mềm', 'Auto Track Rail - Phần mềm phân tích con đường cho xe điện và các phương tiện đường sắt', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (133, 'vi', 'Auto Track Airport - Phân tích đường vòng 3D cho các hoạt động Airside sân bay', 'auto-track-airport', NULL, 'Công cụ phân tích đường vòng 3D tiên tiến nhất thế giới Phân tích tất cả các khía cạnh của tất cả các hoạt động airside sân bay, kiểm tra máy bay bay chờ, vị trí của khoang thông, thúc đẩy các cuộc diễn tập trở lại, khu vực an toàn của máy ban và sử dụng các điểm phục vụ và cảnh báo cánh cửa để lên kế hoạch di chuyển phương tiện hỗ trợ', NULL, NULL, 'Phần mềm', 'Auto Track Airport - Công cụ phân tích đường vòng 3D cho các hoạt động airside sân bay', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (134, 'vi', 'EcoRisk VIEW - Phần mềm đánh giá rủi ro sinh thái', 'phan-mem-ecorisk-view', NULL, 'EcoRisk VIEW là một chương trình đánh giá rủi ro sinh thái cao cấp toàn diện dựa trên nghị định thư US EPA SLERAP (Screening Level Ecological Risk Assessment Protocol).', NULL, NULL, 'Phần mềm', 'EcoRisk VIEW - Phần mềm đánh giá rủi ro sinh thái', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (135, 'vi', 'Auto Track Junction - Phần mềm tương tác thiết kế đường vòng ', 'auto-track-junction', NULL, 'AutoTrack Junction cho phép bạn tạo ra các đảo với các tiêu chuẩn trên toàn thế giới và đánh giá cho dòng nhanh nhất trong một phần nhỏ của thời gian, nó sẽ có được bằng cách sử dụng các phương pháp truyền thống. Hơn nữa, liên kết động duy nhất để ARCADY cho phép bạn thực hiện các phân tích lưu lượng / công suất cùng một lúc.', NULL, NULL, 'Phần mềm', 'Auto Track Junction - Phần mềm tương tác thiết kế đường vòng ', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (136, 'vi', 'Auto Track Road - Phần mềm phân tích xe qua đường vòng', 'auto-track-road', NULL, 'Auto Track Roads là phần mềm phân tích xe qua đường vòng và chương trình mô phỏng xe đi qua chỗ rẽ tiến tiến nhất thế giới. Dự báo đường vòng của hướng xe ở các vịnh, chỗ đường vòng, vòng xuyến, các khu vực dịch vụ. Với các loại xe được thiết kế sẵn, hỗ trợ cho các xe người dùng tự định nghĩa phức tạp, nhiều mô hình lái xe, khả năng tùy biến các tùy chọn trình diễn và tương tích với các hệ thống CAD, AutoTrack được sử dụng hàng ngày bởi các hàng nghìn kỹ sư trên toàn thế thế giới.', NULL, NULL, 'Phần mềm', 'Auto Track Road - Phần mềm phân tích xe qua đường vòng', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (137, 'vi', 'Trazer - Phần mềm đếm xe bằng video', 'phan-mem-dem-xe-trazer', NULL, 'Phần mềm Trazer, hãng Kritikal có thể phân loại được nhiều loại phương tiện tham gia giao thông như xe trọng tải nặng (xe tải, xe bus …), xe trọng tải nhẹ ( xe hơi, xe jeep,,..), xe hai bánh hay người đi bộ. Ngoài việc đếm phân loại ra, Trazer còn đưa ra các thông tin nhỏ hơn như tốc độ, hướng di chuyển … của phương tiện tham gia giao thông.', NULL, NULL, 'Phần mềm', 'Trazer - Phần mềm đếm xe bằng video', 'Trazer', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (138, 'vi', 'METROCOUNT - Giải pháp thiết kế, sản xuất các thiết bị và phần mềm phân loại xe', 'metro', NULL, 'Giải pháp MetroCount cho bạn nhiều hơn một lớp đơn giản, tốc độ và báo cáo lưu lượng, cho phép bạn tìm kiếm và lưu vào bên trong hệ thống một cách chính xác chi tiết, hoàn toàn tới những trục xe cụ thể. Hệ thống phân loại xe MetroCount kết hợp với trạng thái hình ảnh giao thông khi truy cập phần cứng, là một phần mềm dễ sử dụng. MetroCount cung cấp cho bạn một giải pháp tổng thể để bạn giám sát những vấn để giao thông bạn đang quan tâm, từ những thống kê hàng ngày cho tới những vấn đề quản lý giao thông phức tạp.', NULL, NULL, 'Phần mềm', 'METROCOUNT - Giải pháp thiết kế, sản xuất các thiết bị và phần mềm phân loại xe', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (145, 'vi', 'Emissions VIEW - Chương trình đánh giá rủi ro sinh thái cao cấp', 'phan-mem-emissions-view', NULL, 'Emissions VIEW là một chương trình đánh giá rủi ro sinh thái cao cấp toàn diện dựa trên nghị định thư US EPA SLERAP (Screening Level Ecological Risk Assessment Protocol). EcoRisk view đánh giá toàn diện đa sinh thái đồng thời tính toán giá trị rủi ro đối với hóa chất khác nhau, từ nhiều nguồn, nhiều vị trí tiếp xúc.', NULL, NULL, 'Phần mềm', 'Emissions VIEW - Chương trình đánh giá rủi ro sinh thái cao cấp', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (139, 'vi', 'ARTM VIEW - Mô phỏng sự phát tán và lắng đọng của phóng xạ trong khí quyển', 'phan-mem-artm-view', NULL, 'ARTM VIEW là một giao diện sử dụng cho mô hình ARTM, được xem là tiêu chuẩn mới cho mô hình hóa và tính toán về sự phát tán và lắng đọng của các vật liệu bức xạ trong không khí theo quy định của Luật hạt nhân ở Đức.', NULL, NULL, 'Phần mềm', 'ARTM VIEW - Mô phỏng sự phát tán và lắng đọng của phóng xạ trong khí quyển', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (140, 'vi', 'MAAP & iMAAP - Gói phần mềm phân tích và báo cáo tinh vi và tổng thể', 'pm-maap-imaap-quan-ly-tai-nan-giao-thong', NULL, 'MAAP là một gói phân tích và báo cáo tinh vi và tổng thể, một sản phẩm phần mềm TRL đã được cung cấp cả ở Anh và trên toàn thế giới kể từ năm 1980. Được sử dụng bởi chính quyền địa phương ở khắp nước Anh và quốc tế, nó cung cấp công cụ để lưu trữ và phân tích các yếu tố gây ra tai nạn, địa lý lân cận (thông qua việc xây dựng sẵn công cụ GIS) và một bộ các kiểu dữ liệu khác. iMAAP là thế hệ mới của MAAP. Phiên bản mới iMAAP cung cấp công cụ phù hợp tốt hơn với môi trường công nghệ hiện nay, cung cấp thêm tính năng dựa trên yêu cầu của các chuyên gia là những người sử dụng phần mềm. Cùng với công cụ mới, iMAAP là một hệ thống hoàn toàn linh hoạt trên nền tảng web có khả năng xử lý hàng loạt các hệ cơ sở dữ liệu và các định dạng GIS, cũng như các tiêu chuẩn ngày càng phức tạp, nghiêm ngặt và bảo mật.', NULL, NULL, 'Phần mềm', 'MAAP & iMAAP - Gói phần mềm phân tích và báo cáo tinh vi và tổng thể', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (141, 'vi', 'PERS - Phần mềm Xem lại Môi trường đi bộ', 'phan-mem-pers-xem-lai-moi-truong-di-bo', NULL, 'PERS (Phần mềm Xem lại Môi trường Đi bộ) là ứng dụng phần mềm mới và động để đánh giá chất lượng của môi trường cho phần dành để đi bộ. PERS có thể hộ trợ đưa ra các cơ hội để cải thiện đường dành cho người đi bộ, trong khi hỗ trợ hiệu quả mục tiêu tài nguyên. Khuôn khổ hệ thống của nó cho phép cung cấp cho người đi bộ được đánh giá, xem xét và kiểm toán thông qua việc sử dụng các phương pháp sáng tạo và rất thành công.', NULL, NULL, 'Phần mềm', 'PERS - Phần mềm Xem lại Môi trường đi bộ', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (142, 'vi', 'SCOOT - Hệ thống giám sát giao thông', 'phan-mem-scoot', NULL, 'SCOOT là hệ thống giám sát giao thông, nó kiểm soát tín hiệu trong mạng lưới các nút giao thông; thích ứng và phản ứng tự động tới những nơi giao thông bất thường, tạo hiệu quả đặt biệt trong các khu vục các luồng giao thông không dự báo trước được. Phần mềm này được sử dụng ở trên 170 thị trấn và thành phố ở UK và nhiều nước khác.', NULL, NULL, 'Phần mềm', 'SCOOT - Hệ thống giám sát giao thông', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (143, 'vi', 'AUSTAL VIEW - Phần mềm theo dõi sự phân tán trong không khí của hạt Lagrangia', 'phan-mem-austal-view', NULL, 'AUSTAL VIEW là giao diện đồ họa cho mô hình AUSTAL, có 3 phiên bản (T, G và TG) và 1 module add-on. AUSTAL2000 là mô hình theo dõi sự phân tán trong không khí của hạt Lagrangian (đặt theo tên nhà toán học Lagrange). Mô hình tính đến ảnh hưởng của địa hình đối với gió và gió đối với việc phát tán chất ô nhiễm, theo quy định về ô nhiễm không khí của Đức là TAluft.', NULL, NULL, 'Phần mềm', 'AUSTAL VIEW - Phần mềm theo dõi sự phân tán trong không khí của hạt Lagrangia', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (144, 'vi', 'MOVA - Hệ thống giám sát tín hiệu đèn giao thông', 'phan-mem-mova', NULL, 'MOVA là hệ thống giám sát tín hiệu đèn giao thông ở những nút giao thông. Nó chuyển đổi thông minh giữa cách trì hoãn thấp nhất và lưu lượng tối đa, phụ thuộc vào yêu cầu giao thông. Hiện nay ở Anh đang cân nhắc có ít nhất 3000 vị trí được trang bị MOVA, với mỗi năm nhìn thấy ít nhất 200 vị trí khác được cài đặt.', NULL, NULL, 'Phần mềm', 'MOVA - Hệ thống giám sát tín hiệu đèn giao thông', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (146, 'vi', 'TRANSYT - Phần mềm tối ưu hóa mạng lưới giao thông ', 'phan-mem-toi-uu-hoa-mang-luoi-giao-thong', NULL, 'TRANSYT là giải pháp để thiết kế, mô hình và nghiên cứu năng lực giao thông tại các nút giao riêng biệt cho tới cả mạng lưới phức tạp. TRANSYT có thể nhanh chóng đánh giá được sự thực thi của một nút giao riêng biệt cũng như tạo ra sự tối ưu hóa thời gian cố định định lượng thời gian cho tín hiệu giao thông trong bất kỳ mạng lưới đường bộ nào mà lưu lượng giao thông cần biết đến, bao gồm cả tín hiệu ở đường vòng xuyến. Phiên bản mới nhất (TRANSYT 15) có các tính năng đặc biệt để đánh giá các nút giao bị kiểm soát cô lập, và mạng lưới pha trộn tín hiệu và không có tiến hiệu cùng với vai trò truyền thống của nó.', NULL, NULL, 'Phần mềm', 'TRANSYT - Phần mềm tối ưu hóa mạng lưới giao thông ', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (147, 'vi', 'FETs VIEW - Mô hình sự phát tán trong không khí tích hợp mô hình phát tán hóa chất', 'phan-mem-fets-view', NULL, 'FETs VIEW là một hệ thống mô hình sự phát tán trong không khí tích hợp với các mô hình phân tán hóa chất trong không khí như AERMOD (hoặc CALPUFF) để tạo nên một hệ thống có khả năng kiểm kê cấp độ phát thải, theo dõi và lưu trữ số lượng rất lớn dữ liệu, quản lý các cơ sở với các điểm phát hành khác nhau và hàng chục thậm chí hàng trăm các chất ô nhiễm.', NULL, NULL, 'Phần mềm', 'FETs VIEW - Mô hình sự phát tán trong không khí tích hợp mô hình phát tán hóa chất', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (148, 'vi', 'FETs-RT Web - Theo dõi, chứng minh sự tương quan giữa khí thải ô nhiễm từ các quá trình công nghiệp theo thời gian thực', 'phan-mem-fets-rt-web', NULL, 'FETs-RT Web là 1 dạng web dựa trên thời gian thực, chứng minh sự tương quan giữa khí thải ô nhiễm từ các quá trình công nghiệp và tác động về nồng độ của chúng. Sử dụng dữ liệu của dự báo khí tượng, dữ liệu thực từ các trạm giám sát để làm đầu vào cho một mô hình phân tán hóa chất trong không khí, tính toán nồng độ dự kiến của chất gây ô nhiễm dựa trên các thông số và đặc tính phát xạ.', NULL, NULL, 'Phần mềm', 'FETs-RT Web - Theo dõi, chứng minh sự tương quan giữa khí thải ô nhiễm từ các quá trình công nghiệp ', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (149, 'vi', 'OSCADY PRO - Chương trình tối ưu tín hiệu giao thông theo từng giai đoạn', 'phan-mem-toi-uu-hoa-den-tin-hieu-tai-nut', NULL, 'OSCADY PRO là chương trình tối ưu tín hiệu giao thông theo từng giai đoạn. Phần mềm tạo ra việc sử dụng một số kỹ thuật tối ưu hóa độc đáo để tạo ra một mảng cam kết tốt nhất có thể và thời gian trên số lượng tối thiểu của dữ liệu nút. Nó cũng được dùng cho các nút độc lập, hoặc các kết quả có thể được xuất vào trong TRANSYT để sử dụng trong hệ thống được liên kết.', NULL, NULL, 'Phần mềm', 'OSCADY PRO - Chương trình tối ưu tín hiệu giao thông theo từng giai đoạn', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (150, 'vi', 'PICADY - Phần mềm đánh giá sức chứa và trì hoãn ở nơi ưu tiên giao nhau', 'phan-mem-picady', NULL, 'PICADY đánh giá sức chứa và trì hoãn ở nơi ưu tiên giao nhau Kết hợp nghiên cứu mở rộng của TRL trong thiết kế chỗ giao nhau đang dùng và dự báo tỷ lệ tai nạn, sức chứa, chiều dài hàng đợi và sự trì hoãn (cả về hàng đợi và hình học) ở nơi có sự ưu tiên các nút.', NULL, NULL, 'Phần mềm', 'PICADY - Phần mềm đánh giá sức chứa và trì hoãn ở nơi ưu tiên giao nhau', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (151, 'vi', 'CadnaA - Phần mềm dự đoán tác động của tiếng ồn trong môi trường ', 'phan-mem-cadnaa', NULL, 'CadnaA được phát triển bởi DataKustik, là phần mềm hàng đầu thế giới trong lĩnh vực tính toán, thể hiện, đánh giá và dự đoán tác động của tiếng ồn trong môi trường. Với khả năng ưu việt của mình, CadnaA có thể đáp ứng nhu câù tính toán trong rất nhiều lĩnh vực khác nhau như: khu công nghiệp, đường sắt, đường bộ hay toàn bộ một khu vực dân cư, thành phố', NULL, NULL, 'Phần mềm', 'CadnaA - Phần mềm dự đoán tác động của tiếng ồn trong môi trường ', 'Phần mềm dự đoán tác động của tiếng ồn', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (152, 'vi', 'ARCADY - Phần mềm đánh giá sức chứa và sự trì hoãn vòng xuyến', 'phan-mem-arcady', NULL, 'ARCADY được sử dụng để đánh giá sức chứa và sự trì hoãn ở vòng xuyến. Nó có khả năng để dự báo thực tế tỷ lệ tai nạn giao thông, sức chứa và việc trì hoãn (cả hàng đợi và mặt hình học) cho hầu hết các kích cỡ khác nhau của vòng xuyến, sắp đặt từ nhiều nhánh với các cấp độ vòng xuyến được phân tách cho tới những vòng xuyến bên trong khu vực ngoại ô.', NULL, NULL, 'Phần mềm', 'ARCADY - Phần mềm đánh giá sức chứa và sự trì hoãn vòng xuyến', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (153, 'vi', 'CadnaSAK - Phần mềm tính toán tiếng ồn trong các hội trường công nghiệp', 'phan-mem-cadnasak', NULL, 'CadnaSAK là phần mềm mạnh mẽ để tính toán tiếng ồn trong các hội trường công nghiệp. CadnaSAK tính toán mức độ âm thanh tại các máy trạm được dựa trên dữ liệu phát thải của máy móc thiết bị theo Chỉ thị Máy móc EU- xem xét hình học phòng và các đặc điểm thiết kế. Phân phối tiếng ồn được tính toán và trình bày như bản đồ tiếng ồn. Mức tiếng ồn đặc trưng của các máy trạm được xác định có thể được in trong bảng.', NULL, NULL, 'Phần mềm', 'CadnaSAK - Phần mềm tính toán tiếng ồn trong các hội trường công nghiệp', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (196, 'vi', 'Adapt Builder - Gói phần mềm Tính toán dự ứng lực 3D', 'adapt-builder', NULL, 'Adapt Builder - Phần mềm 3D phần tử hữu hạn phân tích thiết kết kết cấu bê tông dự ứng lực. ', NULL, NULL, 'Phần mềm', 'Adapt Builder - Gói phần mềm Tính toán dự ứng lực 3D', 'Adapt Builder ', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (155, 'vi', 'Bastian - Phần mềm cung cấp cơ sở dữ liệu về dữ liệu âm thanh', 'phan-mem-bastian', NULL, 'Bastian là phần mềm để tính toán trong không khí và truyền tải âm thanh tác động giữa các phòng trong các tòa nhà và truyền tải âm thanh trong không khí từ bên ngoài. Các tính toán trong Bastian được dựa trên các bộ phận từ 1 đến 3 của loạt tiêu chuẩn Châu Âu EN 12354, được thông qua bởi đa số các nước châu Âu như là một phần của tiêu chuẩn quốc gia của họ. Vì vậy, các thủ tục này tính toán hình thành cơ sở chung cho việc tiên lượng cách âm của các tòa nhà. Bastian có thể được áp dụng để dự đoán hiệu suất âm thanh giữa các phòng trong căn hộ và các tòa nhà văn phòng, các lớp học trong nhà trường, và giữa các phòng trong khách sạn hoặc bệnh viện.', NULL, NULL, 'Phần mềm', 'Bastian - Phần mềm cung cấp cơ sở dữ liệu về dữ liệu âm thanh', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (156, 'vi', 'AquaChem - Giải pháp quản lý dữ liệu chất lượng nước của hãng Schlumberger', 'aquachem-quan-ly-chat-luong-nuoc', NULL, 'AquaChem là phần mềm phân tích Dữ liệu Chất lượng nước, Biểu đồ, Báo cáo, và Mô hình Quản lý tài nguyên nước dưới đất, các dự án công nghiệp, và các điểm mỏ yêu cầu giám sát liên tục và thu thập mẫu nước.', NULL, NULL, 'Phần mềm', 'AquaChem - Giải pháp quản lý dữ liệu chất lượng nước của hãng Schlumberger', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (371, 'vi', 'GMSplus - Thiết bị giám sát động đất của hãng GEOSIG (Thụy Sỹ)', 'gmsplus-thiet-bi-giam-sat-dong-dat', NULL, 'GMSPlus là máy ghi động đất thế hệ mới nhất của hãng GEOSIG (Thụy Sỹ), được sử dụng phổ biến tại các nhà máy thủy điện ở Việt Nam.', NULL, NULL, 'Thiết bị', '', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (372, 'vi', 'Autocost – Phần mềm bóc tách báo giá cho đơn vị gia công kim loại tấm', 'autocost-phan-mem-bao-gia-kim-loai-tam', NULL, 'Autocost là phần mềm được tích hợp trên nền tảng CAD hỗ trợ các đơn vị gia công kim loại tấm bóc tách và báo giá cho khách hàng một cách nhanh chóng, chính xác, và dễ dàng sử dụng.', NULL, NULL, 'Phần mềm', 'Autocost – Phần mềm bóc tách báo giá cho đơn vị gia công kim loại tấm', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (157, 'vi', 'Hãng DHI', 'gioi-thieu-dhi', NULL, 'Có một số dự án mà giải pháp tốt nhất cũng là giải pháp duy nhất, và trong những dự án như vậy bạn phải chắc chắn rằng mình sử dụng công cụ tốt nhất và có hỗ trợ kỹ thuật bởi một công ty tốt nhất trên thế giới. Phần mềm MIKE by DHI mang đến công nghệ siêu việt, được hỗ trợ bởi những chuyên gia tốt nhất và đem đến giá trị vượt trội cho khách hàng dựa trên 40 năm kinh nghiệm và công nghệ. <p>Đầu tư vào phần mềm MIKE làm công cụ mô hình của bạn là bạn đang đầu tư cho sự phát triển chuyên môn của mình và là cánh cửa cho bạn tiếp cận với cộng đồng kiến thức lớn nhất và uyên thâm nhất trong lĩnh vực lập mô hình tài nguyên nước trên toàn thế giới.', NULL, NULL, 'Phần mềm', '', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (158, 'vi', 'PIPENET - Phần mềm thiết kế và phân tích ứng suất đường ống', 'pipenet-thiet-ke-phan-tich-duong-ong', NULL, 'PIPENET là một công cụ phần mềm mạnh mẽ để phân tích nhanh dòng chảy trong ống và hệ thống ống dẫn. Phần mềm bao gồm 3 mô-đun, giúp phân tích và tính toán đối với những hệ thống đường ống lớn và phức tạp nhất một cách dễ dàng.', NULL, NULL, 'Phần mềm', 'PIPENET - Phần mềm thiết kế và phân tích ứng suất đường ống', 'Phần mềm thiết kế và phân tích ứng suất đường ống', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (160, 'vi', 'MIKE 21 C - Phần mềm mô phỏng diễn biến phát triển của đáy sông và kênh', 'mike-21-c', NULL, 'MIKE 21C là một trong những công cụ được xây dựng tốt nhất để mô phòng diễn biến phát triển của đáy sông và kênh dẫn do sự thay đổi về cơ chế thủy lực.', NULL, NULL, 'Phần mềm', 'MIKE 21 C - Phần mềm mô phỏng diễn biến phát triển của đáy sông và kênh', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (159, 'vi', 'MIKE 11 - Phần mềm lập mô hình sông không hạn chế', 'mike-11', NULL, 'MIKE 11 là phần mềm lập mô hình sông không hạn chế. Với MIKE 11 bạn sẽ có được một bộ công cụ nổi tiếng và được ứng dụng nhiều nhất trên thế giới cho lập mô hình sông 1 chiều. MIKE 11 được rất nhiều kỹ sư chuyên môn về sông lựa chọn vì nó có độ tin cậy cao, độ linh hoạt, tiện ích và chất lượng. MIKE 11 là bộ công cụ mô hình sông mạnh với nhiều đặc tính hơn bất kỳ bộ sản phẩm cùng loại nào khác. MIKE 11 là sản phẩm phần mềm đã làm cho thương hiệu ''MIKE'' trở thành tên tuổi trong lĩnh vực phần mềm chuyên biệt ngành nước có chất lượng của DHI và là một trong những sản phẩm được sử dụng nhiều nhất trong các sản phẩm của MIKE.', NULL, NULL, 'Phần mềm', 'MIKE 11 - Phần mềm lập mô hình sông không hạn chế', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (161, 'vi', 'Mike 3 - Mô phỏng mô hình dòng chảy bề mặt 3 chiều', 'mo-phong-dong-chay-be-mat-3-chieu-mike-3', NULL, 'Mike 3 là phần mềm lập mô hình 3 chiều cho biển và bờ biển MIKE 3 được xây dựng trên cùng công nghệ như MIKE 21 và là lựa chọn tốt nhất khi dự án yêu cầu phải lập mô hình 3 chiều. Nếu bạn đã quen với MIKE 21 bạn sẽ thấy dễ dàng với MIKE 3. Với sự kết hợp của hai mô hình trên cùng một toolbox, thì không có một công việc mô hình biển, hàng hải nào mà bạn không thực hiện được. Nếu bạn chưa là một chuyên gia về lập mô hình 3 chiều, bạn không phải đi đâu xa. DHI có hỗ trợ kỹ thuật thông qua hơn 30 văn phòng trên toàn thế giới.', NULL, NULL, 'Phần mềm', 'Mike 3 - Mô phỏng mô hình dòng chảy bề mặt 3 chiều', 'mô hình dòng chảy bề mặt 3 chiều', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (325, 'vi', 'Phần mềm Diễn họa gạch ốp lát và sàn gỗ', 'floori', NULL, 'Phần mềm diễn họa gạch ốp lát và sàn gỗ là giải pháp ứng dụng công nghệ thực tế ảo tăng cường (AR) được tích hợp lên website và cho phép khách hàng của bạn có thể đưa hình ảnh, mã sản phẩm của bạn vào không gian trên chính ngôi nhà, sân vườn của khách hàng. ', NULL, NULL, 'Phần mềm', 'Phần mềm Diễn họa gạch ốp lát và sàn gỗ', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (163, 'vi', 'Digitech 3D - Dịch vụ khảo sát địa hình, lập bản đồ, mô phỏng 3D', 'digitech-3d', NULL, 'D3D (DigiTech 3D) - một công ty của Ireland, chuyên cung cấp các dịch vụ nâng cao trong khảo sát địa hình, các dịch vụ lập bản đồ và mô phỏng hình ảnh 3D trên máy tính. Sản phẩm có thể là các bản đồ, hình ảnh độ nét cao, các đoạn phim video chất lượng cao mô phỏng dự án bất động sản. Với việc sử dụng công nghệ của D3D, các công ty phát triển bất động sản và các cơ quan quy hoạch có thể giảm đáng kể thời gian và chi phi cho việc phát triển dự án mới (thành phố, khu dân cư, khu nghỉ dưỡng, sân golf, mỏ, v.v) so với các cách làm truyền thống, đồng thời có thể hình dung và thể hiện một cách trực quan nhất có thể khi mô tả các dự án bất động sản.', NULL, NULL, 'Phần mềm', 'Digitech 3D - Khảo sát địa hình, lập bản đồ, mô phỏng 3D', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (164, 'vi', 'ECOLab - Lập mô hình sinh thái', 'ecolab', NULL, 'ECO Lab có thể làm việc với các mô hình 1 chiều, 2 chiều và 3 chiều. Các mẫu do bạn xác lập ra sẽ thực hiện điều đó. Tập trung vào diễn biến sinh thái và không phải mất thời gian để lập trình Trao đổi ý kiến và mô hình với đồng nghiệp trên toàn thế giới. Đơn giản là chỉ cần gửi một bản sao mẫu mô hình của bạn', NULL, NULL, 'Phần mềm', 'ECOLab - Lập mô hình sinh thái', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (165, 'vi', 'RADIA - Mô phỏng, phân tích và đánh giá tác động của sóng điện từ tới môi trường', 'radia-software', NULL, 'Phần mềm đánh giá ô nhiễm điện từ do điện thoại di động và các thiết bị khác có thể ảnh hưởng có đối với: tác động môi trường, kỹ thuật môi trường, kiểm toán môi trường và quản lý môi trường nói chung. ', NULL, NULL, 'Phần mềm', 'RADIA - Phần mềm mô phỏng, phân tích và đánh giá tác động của sóng điện từ tới môi trường', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (166, 'vi', 'DESCAR - Phần mềm kiểm soát, mô phỏng quá trình ô nhiễm nước', 'descar-software', NULL, 'Phần mềm kiểm soát ô nhiễm nước, mô phỏng quá trình ô nhiễm và đánh giá tác động của ô nhiễm nước.', NULL, NULL, 'Phần mềm', 'DESCAR - Phần mềm kiểm soát, mô phỏng quá trình ô nhiễm nước', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (167, 'vi', 'CUSTIC - Phần mềm mô phỏng ảnh hưởng của tiếng ồn', 'custic-software', NULL, 'CUSTIC là phần mềm mô phỏng ảnh hưởng của tiếng ồn Với các điều kiện cụ thể tại khu vực đánh giá được nhập vào phần mềm, CUSTIC cho phép mô phỏng về hình học và đánh giá tác động của tiếng ồn.', NULL, NULL, 'Phần mềm', 'CUSTIC - Phần mềm mô phỏng ảnh hưởng của tiếng ồn', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (168, 'vi', 'DISPER Software - Phần mềm phân tích sự phát tán không khí ô nhiễm', 'phan-mem-disper-software', NULL, 'DISPER Software là một phần mềm phân tích sự phát tán không khí ô nhiễm. ', NULL, NULL, 'Phần mềm', 'DISPER Software - Phần mềm phân tích sự phát tán không khí ô nhiễm', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (170, 'vi', 'RISK ANALYST - Mô hình đánh giá rủi ro sức khoẻ con người và hệ sinh thái', 'risk-analyst', NULL, 'BREEZE® Risk Analyst là hệ thống mô hình đánh giá rủi ro sức khoẻ con người và hệ sinh thái được thiết kế để tiến hành đánh giá đa chiều rủi ro sức khoẻ con người và mô hình đánh giá rủi ro hệ sinh thái dựa trên mạng lưới thức ăn. BREEZE Risk Analyst kết hợp tất cả các công cụ, cơ sở dữ liệu, chức năng GIS, và các phương trình mô phỏng vận số, vận chuyển, phơi nhiễm thành một ứng dụng phần mềm dễ sử dụng và giá cả phải chăng.', NULL, NULL, 'Phần mềm', 'RISK ANALYST - Mô hình đánh giá rủi ro sức khoẻ con người và hệ sinh thái', 'Risk Analyst', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (171, 'vi', 'INCIDENT ANALYST - Phần mềm mô hình hóa phân tán khí độc công nghiệp', 'phan_mem_mo_hinh_hoa_incident_analyst', NULL, 'Phần mềm mô hình hoá cho Chuyên gia phân tích sự cố BREEZE® của EHS kết hợp một bộ các mô hình phân tán khí độc tiêu chuẩn công nghiệp mật độ vừa và dày đặc nhằm dự đoán nồng độ hoá học và mức độ dễ cháy; Mô hình lửa bức xạ nhiệt để dự đoán thông lượng bức xạ và tăng nhiệt độ; và các mô hình nổ để dự đoán áp lực quá cao từ các vụ nổ hơi nước.', NULL, NULL, 'Phần mềm', 'INCIDENT ANALYST - Phần mềm mô hình hóa phân tán khí độc công nghiệp', 'Incident Analyst', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (422, 'vi', 'MicroStation', 'microstation', NULL, 'MicroStation - CAD dẫn đầu về thiết kế cơ sở hạ tầng 2D và 3D chính xác', NULL, NULL, 'Phần mềm', '', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (172, 'vi', 'Breeze ExDAM - Phần mềm mô phỏng 3D đánh giá thiệt hại vụ nổ', 'breeze-exdam', NULL, 'BREEZE® ExDAM® (mô hình đánh giá thiệt hại do nổ) là một bộ mô phỏng 3D hiệu quả, độc đáo hậu quả của vụ nổ, cho phép người dùng dự đoán được thương tích và thiệt hại do các vụ nổ mạnh và nổ hơi nước gây ra.', NULL, NULL, 'Phần mềm', 'Breeze ExDAM - Phần mềm mô phỏng 3D đánh giá thiệt hại vụ nổ', 'BREEZE ExDAM', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (173, 'vi', 'EFDC EXPLORER - Hệ thống mô hình hóa nước', 'he-thong-mo-hinh-hoa-efdc-explorer-eesm', NULL, 'Hệ thống mô hình hóa EFDC EXPLORER (EEMS) là sản phẩm của hãng phần mềm nổi tiếng DSI (Hoa Kỳ). Đây là một hệ thống mô hình hóa môi trường và thủy động lực học để thực hiện các nghiên cứu kỹ thuật môi trường nước ngọt và nước mặn. Phần mềm này cho phép các kỹ sư và nhà khoa học tạo ra các mô hình môi trường thủy sinh một cách chính xác và hiệu quả. Sử dụng Hệ thống mô hình hóa EEMS để mô hình bất kỳ môi trường sông, hồ, cửa sông hoặc ven biển nào đang đối mặt với những thách thức môi trường. Bên cạnh đó mô hình này còn có thể được sử dụng để báo cáo kết quả một cách rõ ràng và hiệu quả bằng các khả năng xử lý dữ liệu chính xác.', NULL, NULL, 'Phần mềm', 'EFDC EXPLORER - Hệ thống mô hình hóa nước', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (320, 'vi', 'Cabinet Vision - Phần mềm thiết kế và sản xuất nội thất gỗ công nghiệp', 'cabinetvision-thiet-ke-san-xuat-noi-that', NULL, 'Cabinet Vision là giải pháp phần mềm toàn diện cho quá trình thiết kế và sản xuất nội thất gỗ công nghiệp', NULL, NULL, 'Phần mềm', 'Cabinet Vision - Phần mềm thiết kế và sản xuất nội thất gỗ công nghiệp', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (175, 'vi', 'EFDC Explorer - Phần mềm xử lý mã ', 'efdc-explorer', NULL, 'EFDC_Explorer (EE) là một phần mềm hoạt động dựa trên giao diện đồ họa Window. Phần mềm được phát triển bởi công ty Dynamic Solutions-International, LLC(DSI) nhằm thực hiện quá trình tiền và hậu xử lý mã “Environmental Fluid Dynamics Code" (EFDC). EFDC được thiết kế để hỗ trợ việc xây dựng mô hình, Tạo ra lưới hệ Đề Các và lưới cong, kiểm tra, hiệu chỉnh và xem dữ liệu bằng các hình vẽ và hoạt ảnh của các kết quả mô hình EFDC.', NULL, NULL, 'Phần mềm', 'EFDC Explorer - Phần mềm xử lý mã ', 'EFDC Explorer', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (176, 'vi', 'Breeze AERMOD / ISC -  Phần mềm mô phỏng phát tán khí ', 'breeze-aermod-isc', NULL, 'Breeze AERMOD / ISC là một phần mềm mô phỏng phát tán khí thế hệ mới được xây dựng đáp ứng đầy đủ tiêu chuẩn trên toàn thế giới.', NULL, NULL, 'Phần mềm', 'Breeze AERMOD / ISC -  Phần mềm mô phỏng phát tán khí ', 'Breeze AERMOD / ISC', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (177, 'vi', 'PHAROS - Mô hình tính toán sự chuyển động sóng cộng hưởng', 'pharos', NULL, 'Mô hình sóng Pharos được sử dụng để tính toán sự chuyển động sóng cộng hưởng ở các bến cảng. Mô hình này đã được áp dụng trong một loạt các dự án nghiên cứu và kỹ thuật trên toàn thế giới. Biện pháp thi công, như phần kéo dài của đê chắn sóng, hoặc sự điều chỉnh các bến cảng, có thể làm giảm sự khuấy trộn sóng hoặc sự công hưởng ở bến cảng có thể được đánh giá với mô hình.', NULL, NULL, 'Phần mềm', 'PHAROS - Mô hình tính toán sự chuyển động sóng cộng hưởng', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (178, 'vi', 'PROBED - Công cụ thiết kế bảo vệ móng', 'probed', NULL, 'Công cụ thiết kế bảo vệ móng PROBED PROBED là một chương trình mang tính linh hoạt và thân thiện cho việc tính toán bảo vệ đáy và bao bọc đường ống do tác động của sự kết hợp của dòng chảy và sóng liện tục.', NULL, NULL, 'Phần mềm', 'PROBED - Công cụ thiết kế bảo vệ móng', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (179, 'vi', 'BREAKWAT - Công cụ thiết kế cấu trúc bờ biển', 'breakwat', NULL, 'BREAKWAT là công cụ thiết kế cấu trúc bờ biển, thiết kế khái niệm đối với một số loại cấu trúc ven biển theo tải trọng sóng. Đê chắn sóng gò đá hộc với các lớp bao bọc bởi vật liệu đá hoặc các khối bê tông, bờ bảo vệ đê chắn sóng, cấu trúc thùng chìm thẳng đứng, kết cấu kiểu đá gầm và cấu trúc gần đáy có thể được thiết kế bằng cách sử dụng BREAKWAT ', NULL, NULL, 'Phần mềm', 'BREAKWAT - Công cụ thiết kế cấu trúc bờ biển', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (180, 'vi', 'SOBEK - Mô hình dự báo lũ, tối ưu hóa hệ thống thoát nước', 'sobek', NULL, 'SOBEK là một bộ mô hình mạnh mẽ để dự báo lũ, tối ưu hóa hệ thống thoát nước, điều khiển hệ thống dẫn nước, thiết kế cống thoát nước cho dòng nước lũ, hình thái sông, sự ngập mặn và chất lượng nước mặt. ', NULL, NULL, 'Phần mềm', 'SOBEK - Mô hình dự báo lũ, tối ưu hóa hệ thống thoát nước', 'SOBEK', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (181, 'vi', 'DELFT3D - Phần mềm mô phỏng theo không gian 2 chiều, 3 chiều', 'delft3d', NULL, 'BỘ PHẦN MỀM DELFT3D CỦA DELTARES - HÀ LAN là một bộ phần mềm tích hợp mô hình một cách linh hoạt, có thể mô phỏng 02 chiều (Theo chiều ngang hoặc chiều dọc của mặt phẳng) hoặc mô phỏng theo không gian 3 chiều cho Flow (dòng chảy), sediment transport (vận chuyển trầm tích),morphology (hình thái học), waves (sóng), water quality (chất lượng nước), và ecology (hệ sinh thái). Delft3D còn có khả năng xử lý tương tác giữa các quá trình này.', NULL, NULL, 'Phần mềm', 'DELFT3D - Phần mềm mô phỏng theo không gian 2 chiều, 3 chiều', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
