INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (183, 'vi', 'Breeze Roads - Phần mềm mô hình hóa phân tán không khí', 'breeze-roads', NULL, 'Breeze Roads (CALINE4, CAL3QHC, CAL3QHCr) Breeze Roads cho phép mô hình hóa sự phát tán khí, dự báo tác động của các khí carbon monoxide (CO), khí nitơ (NO2),hạt (PM), và nồng độ các khí trơ gây ô nhiễm khác từ các phương tiện di...', NULL, NULL, 'Phần mềm', 'Breeze Roads - Phần mềm mô hình hóa phân tán không khí', 'Breeze Roads', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
