INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (277, 'vi', 'ZX300 - Thiết bị đo gió trên cao bằng công nghệ LiDAR', 'thiet-bi-do-gio-tren-cao-bang-cong-nghe-lidar', NULL, 'Được thành lập từ năm 2007, ZXLidar (Zephir Ltd) đã và đang phát triển là một trong những nhà cung cấp thiết bị đo gió bằng công nghệ LiDAR hàng đầu thế giới. ', NULL, NULL, 'Thiết bị', 'ZX300 - Thiết bị đo gió trên cao bằng công nghệ LiDAR', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (278, 'vi', 'AQ510 - Thiết bị đo gió trên cao công nghệ SoDAR', 'thiet-bi-do-gio-tren-cao-bang-cong-nghe-sodar', NULL, 'AQSystem với kinh nghiệm hơn 30 năm sản xuất và phát triển sản phẩm đo gió bằng công nghệ âm thanh SoDAR. Một trong những mẫu thiết bị đo tốc độ gió Sodar nổi bật nhất hiện nay từ AQSystem chính là AQ510.', NULL, NULL, 'Thiết bị', 'AQ510 - Thiết bị đo gió trên cao công nghệ SoDAR', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (286, 'vi', 'Giải pháp khảo sát đường dây bằng công nghệ LiDAR kết hợp với Drone', 'giai-phap-khao-sat-duong-day-bang-cong-nghe-lidar-ket-hop-voi-drone', NULL, 'Hiện nay trên thế giới, các nhà cung cấp điện, quản lý truyền tải đã và đang chuyển sang sử dụng công nghệ máy bay không người lái để tiến hành khảo sát và phân tích. Các máy bay không người lái Drone, UAV tự động với khả năng mang tải lớn kết hợp với thiết bị LiDAR chuyên dụng là phương pháp thay thế hiệu quả việc khảo sát đường dây truyền tải điện truyền thống.', NULL, NULL, 'Thiết bị', 'Giải pháp khảo sát đường dây bằng công nghệ LiDAR kết hợp với Drone', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
