INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (327, 'vi', 'BREEZE VASDIP - Phần mềm đánh giá thiệt hại do nổ', 'breeze-vasdip', NULL, 'BREEZE VASDIP là một sản phẩm đồng hành tuyệt vời cho BREEZE ExDAM® và các mô hình tính toán các tham số dễ bị tổn thương tương ứng để sử dụng trong các ứng dụng này: HExDAM® (Mô hình đánh giá thiệt hại do nổ áp suất cao) và mô hình VExDAM® (mô hình đánh giá các vụ nổ hơi nước). Ngoài ra, người dùng có thể tính toán sự thay đổi tính dễ tổn thương như thiết kế cấu trúc cá nhân và các tham số thành phần con người khác nhau, cho phép người dùng tối ưu hóa thiết kế của thành phần. Điều này làm tăng tiện ích của các mô đun HExDAM và VExDAM và làm cho VASDIP trở lên vô giá khi thực hiện phân tích chi phí và rủi ro.', NULL, NULL, 'Phần mềm', 'BREEZE VASDIP - Phần mềm đánh giá thiệt hại do nổ', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (282, 'vi', 'SUMMIT M VIPA - Thiết bị giám sát chấn động online của hãng DMT (Đức)', 'thiet-bi-giam-sat-chan-dong-online', NULL, 'Summit M Vipa là hệ thống giám sát liên tục các ảnh hưởng của nổ mìn (chấn động và sóng xung kích trong không khí) đối với con người, công trình theo QCVN 01-2019.', NULL, NULL, 'Thiết bị', 'SUMMIT M VIPA - Thiết bị giám sát chấn động online của hãng DMT (Đức)', 'giám sát chấn động online, thiết bị giám sát nổ mìn, giám sát chấn động', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
