INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (214, 'vi', 'Mappro - Phần mềm Quản lý Quy hoạch và Hạ tầng kỹ thuật Đô thị', 'mappro-phan-mem-quan-ly-quy-hoach-va-ha-', NULL, 'MAPPRO là một giải pháp phần mềm nhằm xây dựng các Hệ thống phục vụ cho các công tác Quản lý quy hoạch đô thị và Hạ tầng kỹ thuật, ứng dụng các công nghệ xử lý bản đồ và GIS, gắn liến với các chức năng, nghiệp vụ trong hoạt động Xây dựng đô thị.', NULL, NULL, 'Phần mềm', '', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (215, 'vi', 'ESPA - Hệ Thống Quản Lý Sản Xuất Nước Sạch , Dịch Vụ Khách Hàng Sử Dụng Nước', 'espa-he-thong-quan-ly-san-xuat-nuoc-sach', NULL, 'ESPA là phần mềm Quản lý sản xuất nước sạch, Quản lý mạng lưới tuyến ống kỹ thuật, Quản lý khách hàng, Quản lý chất lượng nước, Quản lý thất thoát', NULL, NULL, 'Phần mềm', 'ESPA - Hệ Thống Quản Lý Sản Xuất Nước Sạch , Dịch Vụ Khách Hàng Sử Dụng Nước', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (207, 'vi', 'KPW - Phần mềm phân tích, thiết kế khung phẳng', 'kpw', NULL, 'KPW là phần mềm tự động hoá phân tích thiết kế kết cấu khung phẳng bê tông cốt thép đưa ra kết quả cuối cùng là bản vẽ kỹ thuật thi công, đồng thời cũng có thể thực hiện tự động hoá thiết kế kết cấu dàn thép phẳng.', NULL, NULL, 'Phần mềm', 'KPW - Phần mềm phân tích, thiết kế khung phẳng', 'Thiết kế bê tông', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (299, 'vi', 'Pytha 3D CAD - Phần mềm thiết kế và sản xuất nội thất', 'phan-mem-noi-that-go-pytha', NULL, 'Được phát triển bởi PYTHA Lab (1978), Pytha 3D CAD là giải pháp công nghệ giúp các nhà thiết kế và sản xuất đồ nội thất gỗ tối ưu toàn bộ quy trình từ khâu lên ý tưởng, thiết kế tại văn phòng cho đến quá trình triển khai gia công và sản xuất tại nhà máy với nhiều tính năng, bộ công cụ vượt trội.', NULL, NULL, 'Phần mềm', 'Pytha 3D CAD - Phần mềm thiết kế và sản xuất nội thất', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (239, 'vi', 'Kritikal - Hệ thống đếm và phân loại xe', 'kritikal', NULL, 'Hãng KritiKal là hãng thiết kế, ứng dụng và sáng tạo công nghệ hàng đầu ở Ấn Độ và trên thế giới. Tiếng Ấn Độ thì "Kritikal" có nghĩa là "sáng tạo cho tương lai". Được thành lập vào năm 2002, KritiKal là một trong rất ít công ty trên thế giới với thế mạnh trong cả thiết kế hệ thống nhúng và giải pháp hình ảnh theo thời gian thực Kritikal chuyên về các giải pháp xử lý video thời gian thực hoặc video off-line cho các ứng dụng trực tuyến, giải pháp phân tích hình ảnh với công nghệ mới và tiên tiến nhất trên thế giới.', NULL, NULL, 'Phần mềm', 'Kritikal - Hệ thống đếm và phân loại xe', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (240, 'vi', 'Piletest CHUM - Máy siêu âm cọc khoan nhồi', 'may-sieu-am-coc-khoan-nhoi-chum', NULL, 'Thiết bị siêu âm cọc khoan nhồi CHUM của Piletest đáp ứng TCVN 9396:2012 Cọc khoan nhồi - Xác định tính đồng nhất của bê tông - Phương pháp xung siêu âm ', NULL, NULL, 'Thiết bị', 'Piletest CHUM - Máy siêu âm cọc khoan nhồi', 'siêu âm cọc khoan nhồi', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
