INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (314, 'vi', 'Alphacam - Phần mềm CAM lập trình gia công nội thất gỗ tự nhiên', 'alphacam-phan-mem-cam-go-tu-nhien', NULL, 'ALPHACAM là giải pháp CAD/CAM trực quan mạnh mẽ cho các ngành công nghiệp gỗ, kim loại, đá. Phần mềm có tính linh hoạt và độ tin cậy cao, xây dựng nhiều module gồm phay, khắc, tiện, gia công 2 đến 5 trục', NULL, NULL, 'Phần mềm', 'Alphacam - Phần mềm CAM lập trình gia công nội thất gỗ tự nhiên', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (250, 'vi', 'OLGA - Mô phỏng dầu khí để vận chuyển dầu, khí đốt và nước trong cùng đường ống', 'olga', NULL, 'OLGA là phần mềm mô phỏng dầu khí để vận chuyển dầu, khí đốt tự nhiên và nước trong cùng một đường ống', NULL, NULL, 'Phần mềm', 'OLGA - Phần mềm mô phỏng dầu khí để vận chuyển dầu, khí đốt tự nhiên và nước trong cùng đường ống', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (251, 'vi', 'FlowCalc32 CE', 'flowcalc32-ce', NULL, 'FlowCalc32 CE là một  phần mềm mô phỏng định cỡ tấm Orifice  để tính toán các thiết bị đo lưu lượng chênh lệch áp suất khác nhau', NULL, NULL, 'Phần mềm', '', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (252, 'vi', 'OFM - Phần mềm quản lý mỏ dầu ', 'ofm', NULL, 'Phần mềm quản lý mỏ dầu (OFM) cung cấp môi trường tích hợp với chi phí thấp. Phần mềm này có thể thực hiện những công việc phức tạp, phân tích dự đoán, mô phỏng tầng chứa và dữ liệu sản xuất.', NULL, NULL, 'Phần mềm', 'OFM - Phần mềm quản lý mỏ dầu', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (253, 'vi', 'PIPESIM -  Công cụ mô phỏng dòng chảy nhiều pha', 'pipesim', NULL, 'PIPESIM là công cụ mô phỏng dòng chảy nhiều pha dùng cho việc thiết kế và phân tích phỏng đoán hệ thống khai thác sản xuất giếng, dòng chảy, ống dẫn', NULL, NULL, 'Phần mềm', 'PIPESIM -  Công cụ mô phỏng dòng chảy nhiều pha', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
