INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (255, 'vi', 'HTRI - Phần mềm thiết kế và đánh giá thiết bị trao đổi nhiệt', 'htri', NULL, 'HTRI cung cấp một loạt các giải pháp phần mềm cho thiết bị truyền nhiệt được sử dụng bởi các công ty điều hành, nhà thầu kỹ thuật, nhà chế tạo trao đổi và các ngành công nghiệp liên quan.', NULL, NULL, 'Phần mềm', '', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (257, 'vi', 'Pearpoint P354 - Rôbốt kiểm tra cống ngầm', 'robot-kiem-tra-cong-ngam-p354', NULL, 'Rôbốt kiểm tra cống ngầm P354 được sử dụng để kiểm tra tình trạng của các đường cống ngầm hoặc các vị trí có không gian hạn chế.', NULL, NULL, 'Thiết bị', 'Pearpoint P354 - Rôbốt kiểm tra cống ngầm', 'kiểm tra đường ống ngầm', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
