INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (266, 'vi', 'LCMS - Hệ thống kiểm tra bề mặt đường bộ', 'he-thong-kiem-tra-be-mat-duong-bo', NULL, 'LCMS có thể tự động đo, phát hiện và định lượng tất cả các thông số chức năng chính của mặt đường trong một lần duy nhất, bao gồm: vết nứt, vệt lún, độ gồ ghề, kết cấu, ổ gà và độ nhám.', NULL, NULL, 'Thiết bị', 'LCMS - Hệ thống kiểm tra bề mặt đường bộ', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (268, 'vi', 'CubiCost - Phần mềm bóc tách khối lượng trên nền tảng BIM', 'phan-mem-cubicost', NULL, 'Cubicost là bộ phần mềm bóc tách khối lượng trên nền tảng BIM, đã đạt được chứng chỉ chuẩn đầu ra, đầu vào IFC của Building Smart. Bộ phần mềm BIM Cubicost bao gồm bốn phần mềm riêng biệt trên trên nền tảng BIM (TASC, TRBC, TME, TBQ), tập trung vào các nhu cầu khác nhau của công việc bóc tách và xử lý khối lượng. Tất cả bốn phần mềm này đem lại hầu như tất cả các yêu cầu chung của công việc dự toán chi phí xây dựng. Phần mềm Cubicost đã được tin dùng ở rất nhiều nước tại Đông Nam Á như Singapore, Malaysia, Phillipine, Thái Lan và Việt Nam. Cubicost hiện đã có phiên bản hỗ trợ Tiếng Việt!', NULL, NULL, 'Phần mềm', 'CubiCost - Phần mềm bóc tách khối lượng trên nền tảng BIM', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (269, 'vi', 'Summit X One - Thiết bị đo địa chấn đa kênh của hãng DMT (Đức)', 'thiet-bi-do-dia-chan-da-kenh-summit-x', NULL, 'SUMMIT X One là hệ thống thu thập dữ liệu địa chấn  linh hoạt, cung cấp giải pháp tốt nhất cho các phép đo địa chấn 2D và 3D độ phân giải cao ở mọi địa hình.', NULL, NULL, 'Thiết bị', 'Summit X One - Thiết bị đo địa chấn đa kênh của hãng DMT (Đức)', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (270, 'vi', 'ANSYS DISCOVERY', 'ansys-discovery', NULL, 'ANSYS là một phần mềm toàn diện và bao quát hầu hết các lĩnh vực vật lý, giúp can thiệp vào thế giới mô hình ảo và phân tích kỹ thuật cho các giai đoạn thiết kế. Hầu hết các nhà đầu tư rất thích phần mềm phân tích kỹ thuật này so với những gì chúng làm được và số tiền họ phải bỏ ra.', NULL, NULL, 'Phần mềm', '', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (271, 'vi', 'ANSYS STRUCTURE - Tối ưu hóa thiết kế sản phẩm', 'ansys-structure', NULL, 'ANSYS STRUCTURE cho phép bạn giải quyết các vấn đề kỹ thuật kết cấu phức tạp và hỗ trợ đưa ra quyết định thiết kế tốt hơn, nhanh hơn.', NULL, NULL, 'Phần mềm', 'ANSYS STRUCTURE - Tối ưu hóa thiết kế sản phẩm', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (273, 'vi', 'CATIA - Phần mềm thiết kế CAM', 'catia', NULL, 'CATIA là sản phẩm tiên phong của hãng Dassault Systèmes và là giải pháp hàng đầu thế giới về thiết kế và đổi mới sản phẩm. Nó được sử dụng bởi các tổ chức hàng đầu trong nhiều ngành công nghiệp để phát triển các sản phẩm mà chúng ta thấy và sử dụng trong cuộc sống hàng ngày.', NULL, NULL, 'Phần mềm', 'CATIA - Phần mềm thiết kế CAM', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (274, 'vi', 'windPro - Phần mềm tính toán thiết kế, quy hoạch điện gió', 'windpro-thiet-ke-va-quy-hoach-dien-gio', NULL, 'Phần mềm windPRO phục vụ việc thiết kế và quy hoạch các dự án điện gió với các tính năng bao gồm: phân tích dữ liệu gió, tính toán năng suất, đánh giá rủi ro, đánh giá sự phù hợp của địa điểm, tính toán và mô phỏng ảnh hưởng của môi trường. Sử dụng phân tích chi tiết sau giai đoạn xây dựng dữ liệu sản lượng. Bao gồm các module riêng biệt.', NULL, NULL, 'Phần mềm', 'windPro - Phần mềm tính toán thiết kế, quy hoạch điện gió', 'winPRO,  phần mềm thiết kế và quy hoạch điện gió', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (297, 'vi', 'Pearpoint P550c - Dịch vụ khảo sát, kiểm tra đường ống, cống ngầm bằng rô bốt', 'dich-vu-khao-sat-kiem-tra-cong-ngam', NULL, 'Dịch vụ khảo sát, kiểm tra đường ống, cống ngầm bằng rô bốt của hãng PearPoint (USA)', NULL, NULL, 'Thiết bị', 'Pearpoint P550c - Khảo sát, kiểm tra đường ống, cống ngầm bằng rô bốt', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (312, 'vi', 'Zoom Meeting Bản quyền - Phần mềm tổ chức cuộc họp, học online', 'zoom-cloud-meeting-phan-mem-to-chuc-cuoc-hop-hoc-online', NULL, 'ZOOM Cloud Meetings là ứng dụng phổ biến nhất hiện nay trong tổ chức họp, học online. Zoom có nhiều tính năng hỗ trợ tối ưu, tiện dụng nhất như chia sẻ tệp tin, hình ảnh nhanh chóng và gửi tin nhắn với các thành viên cuộc họp bao gồm văn bản, hình ảnh, âm thanh. Ứng dụng được hỗ trợ trên hầu hết nền tảng máy tính, điện thoại và tablet hiện nay.', NULL, NULL, 'Phần mềm', 'Zoom Meeting Bản quyền - Phần mềm tổ chức cuộc họp, học online', 'Zoom Bản quyền', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (317, 'vi', 'Logikal - Phần mềm gia công hệ cửa, hệ vách dựng', 'logikal---phan-mem-gia-cong-he-cua-he-vach-dung-1', NULL, 'Logikal là phần mềm tính toán thiết kế, lập trình sản xuất cửa sổ, hệ cửa đi và hệ mặt dựng.', NULL, NULL, 'Phần mềm', 'Logikal - Phần mềm gia công hệ cửa, hệ vách dựng', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (322, 'vi', 'Enscape 3D - Phần mềm Render nội thất', 'enscape-3d-render-noi-that', NULL, 'Phần mềm render Enscape 3.1 hỗ trợ cho việc thiết kế và trải nghiệm hình ảnh kết xuất đẹp mắt, chuyên nghiệp. Hiện nay, với phiên bản mới nhất của Enscape thì người dùng có thể đưa thiết kế của họ gần với thực tế...', NULL, NULL, 'Phần mềm', 'Enscape 3D - Phần mềm Render nội thất', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (315, 'vi', 'SOFTTECH V6 - Phần mềm thiết kế và sản xuất cửa, mặt dựng', 'softtech-v6-phan-mem-thiet-ke-va-san-xuat-cua-mat-dung', NULL, 'SOFTTECH V6 là phần mềm hỗ trợ tối ưu cho tính toán thiết kế, lập trình sản xuất cửa sổ, hệ cửa đi và hệ mặt dựng.', NULL, NULL, 'Phần mềm', 'SOFTTECH V6 - Phần mềm thiết kế và sản xuất cửa, mặt dựng', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (318, 'vi', 'Range Vision – Thiết bị scan 3D', 'range-vision-–-thiet-bi-scan-3d', NULL, 'RangeVision là công ty chuyên cung cấp thiết bị và phát triển phần mềm liên quan đến công nghệ quét 3D đến từ Nga, Với hơn 10 năm hoạt động, RangeVision có hơn 850 thiết bị được bán ra và 40 đối tác trên toàn cầu. Các dòng sản phẩm chủ lực của công ty bao gồm các thiết bị quét 3D như NEO, Spectrum và Pro cùng với phần mềm hỗ trợ đi kèm', NULL, NULL, 'Thiết bị', 'Range Vision – Thiết bị scan 3D', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (324, 'vi', 'MIKE Animator - Công cụ làm phim điện tử', 'mike-animator-1', NULL, 'MIKE Animator là một công cụ làm phim điện tử giúp bạn có thể chuyển kết quả của MIKE 21, MIKE 3 và MIKE FLOOD sang video trình bày ấn tượng 3 chiều', NULL, NULL, 'Phần mềm', 'MIKE Animator - Công cụ làm phim điện tử', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (329, 'vi', 'PTV VISTRO - Giải pháp phân tích giao thông', 'phan-mem-ptv-vistro-giao-thong', NULL, 'PTV VISTRO đã được phát triển chuyên biệt để phân tích, nghiên cứu, đánh giá tác động của sự phát triển hạ tầng giao thông mới, và tối ưu hóa thời gian đèn tín hiệu. Phần mềm được sử dụng để phân tích và tối ưu giao thông tại một nút giao, hành lang đường, hoặc trên toàn bộ mạng lưới.', NULL, NULL, 'Phần mềm', 'PTV VISTRO - Giải pháp phân tích giao thông', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (331, 'vi', 'AllPlan Engineering - Giải pháp BIM cho các kỹ sư kết cấu', 'phan-mem-allplan-engineering', NULL, 'ALLPLAN là công cụ có thể làm việc được trên cả môi trường 2D và 3D, giao tiếp tốt với các phần mềm khác và đưa ra chất lượng tốt nhất, đáp ứng các dự án xây dựng phức tạp và yêu cầu cao về tiến độ cũng như độ chính xác.', NULL, NULL, 'Phần mềm', 'AllPlan Engineering - Giải pháp BIM cho các kỹ sư kết cấu', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (330, 'vi', 'Opera Job Management - Phần mềm bóc tách vật tư, sản xuất nhôm kính', 'opera-job-management', NULL, 'Opera Job Management là phần mềm bóc tách vật tư, sản xuất nhôm kính chuyên dụng cho các nhà thầu nhôm kính.', NULL, NULL, 'Phần mềm', 'Opera Job Management - Phần mềm bóc tách vật tư, sản xuất nhôm kính', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (400, 'vi', 'Geosoft - Oasis montaj - Giải pháp phần mềm cho thăm dò địa vật lý đa ngành', 'geosoft-oasis-montaj-giai-phap-phan-mem-cho-tham-do-dia-vat-ly-da-nganh', NULL, 'Oasis montaj là giải pháp phần mềm mạnh mẽ trong hệ sinh thái Seequent, được sử dụng chuyên biệt cho lĩnh vực thăm dò địa vật lý, địa hóa và địa chất.', NULL, NULL, 'Phần mềm', 'Oasis montaj: Giải pháp phần mềm cho thăm dò địa vật lý đa ngành', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (343, 'vi', 'Giải pháp diễn họa nội thất gạch ngành ốp lát, ván sàn', 'giai-phap-dien-hoa-noi-that-nganh-gach', NULL, 'Diễn họa nội thất (Interior Design Visualization) là quá trình thể hiện ý tưởng thiết kế công trình bằng những hình ảnh 3D (tĩnh hoặc động), mô phỏng hiện thực ảo của công trình để khách hàng, chủ đầu tư hình dung một cách rõ nét nhất các chi tiết, vật liệu, không gian nội thất. Nó giúp cho quá trình ra quyết định nhanh, dễ dàng và chính xác hơn. Giải pháp này không thể bỏ qua cho các nhà thầu cung cấp gạch ốp lát, ván sàn.', NULL, NULL, 'Phần mềm', 'Giải pháp diễn họa nội thất gạch ngành ốp lát, ván sàn', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
