INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (359, 'vi', 'Delta Zero', 'delta-zero', NULL, 'Delta Zero - Giải pháp công nghệ của hãng Carbon Re đến từ Anh Quốc, sử dụng hệ thống IOT kết hợp phần mềm và thiết bị giúp hỗ trợ tư vấn, hỗ trợ quá trình vận hành nhà máy sản xuất xi măng nhằm hướng đến mục tiêu đạt đến quy trình vận hành tối ưu và giảm lượng phát thải carbon.', NULL, NULL, 'Phần mềm', 'Carbon RE', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (360, 'vi', 'FHC - Phần mềm tính toán thủy lực cho hệ thống phun nước chữa cháy', 'fhc-phan-mem-tinh-toan-thuy-luc-cho-he-thong-phun-nuoc-chua-chay', NULL, 'FHC là phần mềm của Hãng Canute LLP. Phần mềm tính toán thủy lực cho hệ thống phun nước chữa cháy và nước phun sương.', NULL, NULL, 'Phần mềm', 'FHC - Phần mềm tính toán thủy lực cho hệ thống phun nước chữa cháy', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
