INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (408, 'vi', 'Leapfrog Geo - Phần mềm dữ liệu 3D địa chất  ', 'leapfrog-geo-phan-mem-du-lieu-3d-dia-chat', NULL, 'Giải pháp Leapfrog được hãng Seequent giới thiệu lần đầu trong ngành công nghiệp khai khoáng – mỏ vào năm 2004. Đây là một bộ giải pháp phần mềm ứng dụng trong toàn bộ vòng đời của một dự án khai thác mỏ, bắt đầu từ tìm kiếm thăm dò, đánh giá trữ lượng, thực hiện vận hành khai thác, và đóng cửa, hoàn nguyên cho cả dự án.', NULL, NULL, 'Phần mềm', 'Leapfrog Geo - Phần mềm dữ liệu 3D địa chất', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (363, 'vi', 'FIFISH PRO V6 PLUS - Rô bốt kiểm tra dưới nước', 'fifish-pro-v6-ro-bot-kiem-tra-duoi-nuoc', NULL, 'FIFISH PRO V6 PLUS là rô bốt chuyên dụng phục vụ cho việc kiểm tra, đánh giá hiện trạng an toàn của các cơ sở hạ tầng dưới nước ở độ sâu lên tới 150m.', NULL, NULL, 'Thiết bị', 'FIFISH PRO V6 PLUS - Rô bốt kiểm tra dưới nước', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (362, 'vi', 'FIFISH V6 EXPERT - Rô bốt kiểm tra dưới nước', 'fifish-v6-e-ro-bot-kiem-tra-duoi-nuoc', NULL, 'FIFISH V6 EXPERT là rô bốt chuyên dụng phục vụ cho việc kiểm tra, đánh giá hiện trạng an toàn của các cơ sở hạ tầng dưới nước.', NULL, NULL, 'Thiết bị', '', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (365, 'vi', 'MIKE 21 – Mô hình 2 chiều của bờ biển và bờ', 'mike-21-–-mo-hinh-2-chieu-cua-bo-bien-va-bo', NULL, 'MIKE 21 cho đến nay là công cụ linh hoạt nhất để lập mô hình ven biển. Nếu bạn cần mô phỏng các quá trình vật lý, hóa học hoặc sinh học ở các khu vực ven biển hoặc biển, MIKE 21 có các công cụ bạn cần.', NULL, NULL, 'Phần mềm', 'MIKE 21 – Mô hình 2 chiều của bờ biển và bờ', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (366, 'vi', 'MIKE+ - Mô hình nước tích hợp', 'mike-mo-hinh-nuoc-tich-hop', NULL, 'Với MIKE+, bạn có thể tích hợp, lập mô hình và quản lý tất cả các hệ thống nước của mình tại một nơi để có các phân tích toàn diện nhất. Một mô hình hệ thống thu gom, mạng phân phối nước, mạng lưới sông và lũ lụt trong một nền tảng tích hợp, linh hoạt và có thể mở rộng để dễ dàng tích hợp và phát triển mô hình dự báo và thiết kế các hệ thống nước có khả năng chống chịu ảnh hưởng của biến đổi khí hậu tốt hơn.', NULL, NULL, 'Phần mềm', 'MIKE+ - Mô hình nước tích hợp', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (368, 'vi', 'INTERGRAPH SMART 3D - Phần mềm thiết kế nhà máy', 'intergraph-smart-3d-thiet-ke-nha-may', NULL, 'Intergraph Smart® 3D là một bộ công cụ tích hợp đầy đủ phục vụ cho việc thiết kế, quản lý và bảo trì dự án, không chỉ trong giai đoạn thiết kế mà còn trong suốt vòng đời các công trình công nghiệp khác nhau như khai thác quặng, nhà máy điện, công trình lọc dầu, giàn khoan ngoài khơi, nhà máy hoá chất,…', NULL, NULL, 'Phần mềm', '', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (370, 'vi', 'PTV Flows - Phần mềm quản lý lưu lượng giao thông', 'ptv-flows-phan-mem-quan-ly-gaio-thong', NULL, 'PTV Flows là giải pháp tiết kiệm chi phí và dễ sử dụng để quản lý lưu lượng giao thông truy cập theo thời gian thực. Phần mềm dựa trên dữ liệu đám mây, trực quan hóa các vấn đề trong mạng lưới giao thông đường bộ và có thể phát hiện hoặc dự đoán tình trạng tắc nghẽn không mong muốn.', NULL, NULL, 'Phần mềm', 'PTV Flows - Phần mềm quản lý lưu lượng giao thông', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (373, 'vi', 'PyroSim - Phần mềm mô phỏng cháy', 'pyrosim-phan-mem-mo-phong-chay', NULL, 'PyroSim - Lập mô hình mô phỏng hoạt động cháy ở dạng 3D chi tiết và nhanh chóng, nâng cao khả năng phân tích phòng cháy chữa cháy', NULL, NULL, 'Phần mềm', '', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
