INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (405, 'vi', 'HTRI SmartPM™ - Phần mềm mô phỏng nhiệt', 'htri-smartpm™', NULL, 'Phần mềm HTRI SmartPM sử dụng các phương pháp tính toán bộ trao đổi nhiệt độc quyền của HTRI để đưa ra các biện pháp kiểm soát và quản lý, nhằm giảm thiểu tắc nghẽn, giảm thiểu sụt áp do sử dụng năng lượng quá mức gây ra', NULL, NULL, 'Phần mềm', 'HTRI SmartPM™ - Phần mềm mô phỏng nhiệt', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (376, 'vi', 'cageCBAM – Phần mềm hỗ trợ khai báo hồ sơ CBAM (Thuế carbon châu Âu)', 'cagecbam-–-phan-mem-ho-tro-khai-bao-ho-so-cbam-thue-carbon-chau-au', NULL, 'cageCBAM là giải pháp toàn diện được thiết kế để định hướng những quy trình phức tạp của Cơ chế Điều chỉnh biên giới Carbon (CBAM) của EU.', NULL, NULL, 'Phần mềm', 'cageCBAM – Phần mềm hỗ trợ khai báo hồ sơ CBAM (Thuế carbon châu Âu)', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (377, 'vi', 'CAGE CARBON- Phần mềm kiểm kê khí nhà kính', 'cage-carbonphan-mem-kiem-ke-khi-nha-kinh', NULL, 'Cage Carbon là phần mềm hỗ trợ kiểm kê khí nhà kính cho doanh nghiệp theo tiêu chuẩn ISO 14064 trong việc quản lý dữ liệu carbon, đưa các mục tiêu và xây dựng lộ trình cắt giảm phát thải ngắn hạn và dài hạn.', NULL, NULL, 'Phần mềm', 'CAGE CARBON- Phần mềm kiểm kê khí nhà kính', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (378, 'vi', 'EvA ERP Cloud - Phần mềm thiết kế, tính toán vật tư nhôm kính', 'eva-erp-cloud-phan-mem-thiet-ke-tinh-toan-vat-tu-nhom-kinh', NULL, 'EvA ERP Cloud là phần mềm thiết kế, tính toán vật tư nhôm kính, giúp các nhà thầu trong nhiều công đoạn như: Quản lý khách hàng, thiết kế cửa, tạo báo giá, thực hiện khảo sát kiểm tra trước sản xuất, phân bổ lệnh sản xuất, quản lý và theo dõi sản xuất, quản lý kho,…', NULL, NULL, 'Phần mềm', '', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (379, 'vi', 'ROBOT KIỂM TRA TRẠM BIẾN ÁP- IR-ET8040A', 'robot-kiem-tra-tram-bien-apir-et8040a', NULL, 'Rôbôt kiểm tra trạm biến áp là công cụ tiên tiến nhất để kiểm tra cơ sở hạ tầng của trạm biến áp từ xa, kết hợp lập bản đồ không gian quy mô nhỏ, phát hiện quá nhiệt,...', NULL, NULL, 'Thiết bị', 'ROBOT KIỂM TRA TRẠM BIẾN ÁP- IR-ET8040A', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (380, 'vi', 'Hệ thống máy vớt rác và thực vật thủy sinh trên sông-Weedoo', 'he-thong-may-vot-rac-va-thuc-vat-thuy-sinh-tren-song-weedoo', NULL, 'Weedoo là nhà cung cấp hàng đầu về các giải pháp làm sạch và bảo vệ môi trường, đặc biệt tập trung vào các khu vực nước như sông hồ, kênh rạch.', NULL, NULL, 'Thiết bị', 'Hệ thống máy vớt rác và thực vật thủy sinh trên sông-Weedoo', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (381, 'vi', 'AxSTREAM- Phần mềm thiết kế và phân tích máy cánh', 'axstreamphan-mem-thiet-ke-va-phan-tich-may-canh', NULL, 'Phần mềm AxSTREAM là một nền tảng hàng đầu giúp bạn thiết kế, phân tích và tối ưu hóa các loại máy móc tua bin một cách hiệu quả và toàn diện. Phần mềm này hỗ trợ toàn bộ quá trình thiết kế cho các loại máy tua bin như: tua bin, máy nén, máy bơm, quạt, rô-to, ổ trục và quạt gió, cho dù là dòng chảy hướng tâm, hướng trục hay hỗn hợp.', NULL, NULL, 'Phần mềm', '', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (382, 'vi', 'pALERT S303- Máy đo gia tốc, giám sát địa chấn', 'palert-s303may-do-gia-toc-giam-sat-dia-chan', NULL, 'pALERT S303, phiên bản nâng cao của dòng máy đo gia tốc pALERT, được tăng cường các tính năng tiên tiến để giám sát địa chấn tuyệt vời.', NULL, NULL, 'Thiết bị', 'pALERT S303- Máy đo gia tốc, giám sát địa chấn', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (384, 'vi', 'OpenFlows Sewer - Phần mềm lập kế hoạch, thiết kế và phân tích hệ thống thoát nước đô thị', 'openflows-sewer-phan-mem-lap-ke-hoach-thiet-ke-va-phan-tich-he-thong-thoat-nuoc-do-thi', NULL, 'OpenFlows Sewer là một giải pháp tiên tiến để lập kế hoạch, thiết kế và phân tích hệ thống thoát nước đô thị. OpenFlows Sewer là một công cụ toàn diện giúp các kỹ sư và nhà quy hoạch đối phó với những vấn đề phức tạp của hệ thống thoát nước đô thị một cách nhanh chóng và hiệu quả.', NULL, NULL, 'Phần mềm', 'OpenFlows Sewer - Phần mềm lập kế hoạch, thiết kế và phân tích hệ thống thoát nước đô thị', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (385, 'vi', 'PTV Lines - Phần mềm giao thông công cộng', 'ptv-lines-phan-mem-giao-thong-cong-cong', NULL, 'PTV Lines là phần mềm giao thông công cộng có phạm vị rộng, dễ sử dụng, dựa trên trình duyệt web và có máy chủ tại EU.', NULL, NULL, 'Phần mềm', '', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (387, 'vi', 'OpenFlows™ Water- Mô phỏng và quản lí hệ thống cấp nước', 'openflows™-watermo-phong-va-quan-li-he-thong-cap-nuoc', NULL, 'Phần mềm OpenFlows Water là một ứng dụng mô hình thủy lực thân thiện với người dùng được hàng ngàn kỹ sư tin tưởng để hiểu rõ hệ thống phân phối nước và đưa ra các quyết định tốt hơn.', NULL, NULL, 'Phần mềm', 'OpenFlows™ Water- Mô phỏng và quản lí hệ thống cấp nước', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (388, 'vi', 'MagiCAD: Giải pháp BIM toàn diện cho Kỹ thuật Cơ khí, Điện, Đường ống (MEP)', 'magicad:-giai-phap-bim-toan-dien-cho-ky-thuat-co-khi-dien-duong-ong-mep', NULL, 'MagiCAD là một giải pháp toàn diện cho thiết kế MEP (Mechanical, Electrical and Plumbing), được tích hợp chặt chẽ mượt mà với AutoCAD và Revit, mang đến một giải pháp toàn diện từ thiết kế đến quản lý dự án.', NULL, NULL, 'Phần mềm', '', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (389, 'vi', 'Sigma s6 Wamos II - Hệ thống đo sóng và dòng chảy bằng radar', 'sigma-s6-wamos-ii-he-thong-do-song-va-dong-chay-bang-radar', NULL, 'Sigma s6 WaMoS®II là hệ thống đo sóng và dòng chảy bằng radar tiên tiến nhất trên thế giới, đáp ứng yêu cầu và đã được cộng đồng khoa học thế giới công nhận.', NULL, NULL, 'Thiết bị', 'Sigma s6 Wamos II - Hệ thống đo sóng và dòng chảy bằng radar', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (390, 'vi', 'OpenRail Designer- Phần mềm thiết kế mạng lưới đường sắt', 'openrail-designerphan-mem-thiet-ke-mang-luoi-duong-sat', NULL, 'OpenRail Designer là một phần mềm để xử lý nhiều nhiệm vụ phức tạp như thiết kế sân ga/trạm, đường hầm, mô hình hành lang, chuyển hướng và đặt công tắc, điện khí hóa đường dây trên cao, phát triển địa điểm, thiết kế mạng lưới vệ sinh và nước mưa, tiện ích ngầm và tạo báo cáo cắm mốc thi công.', NULL, NULL, 'Phần mềm', 'OpenRail Designer- Phần mềm thiết kế mạng lưới đường sắt', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (392, 'vi', 'Spraycannon 150 – Thiết bị phun sương dập bụi', 'spraycannon-150-–-thiet-bi-phun-suong-dap-bui', NULL, 'Spraycannon 150 là hệ thống phun sương, dập bụi của hãng MB Dustcontrol BV, giúp kiểm soát bụi tự động.', NULL, NULL, 'Thiết bị', 'Spraycannon 150 – Thiết bị phun sương dập bụi', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (398, 'vi', 'FIFISH E-GO - Rô bốt kiểm tra dưới nước', 'fifish-e-go---ro-bot-kiem-tra-duoi-nuoc', NULL, 'FIFISH E-GO là thiết bị robot chuyên dụng cho khám phá và ghi hình dưới nước với hiệu suất cao và thiết kế linh hoạt.', NULL, NULL, 'Thiết bị', 'FIFISH E-GO - Rô bốt kiểm tra dưới nước', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (402, 'vi', 'NX - Phần mềm thiết kế CAM (Siemens PLM Software)', 'nx-phan-mem-thiet-ke-cam-siemens-plm-software', NULL, 'NX - Phần mềm thiết kế CAM (Siemens PLM Software)INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (403, 'vi', 'Deswik- Gói Phần mềm Thiết kế, lập kế hoạch, quản lý vận hành toàn diện cho ngành khai thác mỏ', 'deswikgoi-phan-mem-thiet-ke-lap-ke-hoach-quan-ly-van-hanh-toan-dien-cho-nganh-khai-thac-mo', NULL, 'Deswik là Phần mềm Thiết kế, lập kế hoạch, quản lý vận hành toàn diện cho ngành khai thác mỏ được sử dụng tại hơn 50 quốc gia như một nền tảng tích hợp duy nhất trên toàn bộ chuỗi giá trị quy hoạch khai thác mỏ.', NULL, NULL, 'Phần mềm', 'Deswik - Phần mềm Thiết kế, lập kế hoạch, quản lý vận hành toàn diện cho ngành khai thác mỏ', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (412, 'vi', 'FIFISH E-MASTER PLUS - Rô bốt kiểm tra dưới nước', 'fifish-e-master-plus---ro-bot-kiem-tra-duoi-nuoc-1', NULL, 'FIFISH E-MASTER PLUS là rô bốt chuyên dụng phục vụ cho việc kiểm tra, đánh giá hiện trạng an toàn của các cơ sở hạ tầng dưới nước ở độ sâu lên tới 20', NULL, NULL, 'Thiết bị', 'FIFISH E-MASTER PLUS - Rô bốt kiểm tra dưới nước', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (415, 'vi', 'MÁY QUÉT LASER CẦM TAY RS10', 'may-quet-laser-cam-tay-rs10', NULL, 'CHCNAV RS10 là một máy quét laser 3D cầm tay được tích hợp công nghệ SLAM (Simultaneous Localization and Mapping) tiên tiến.', NULL, NULL, 'Thiết bị', 'MÁY QUÉT LASER CẦM TAY RS10', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (424, 'vi', 'MÁY QUÉT LIDAR 3D CẦM TAY RS7', 'may-quet-lidar-3d-cam-tay-rs7', NULL, 'RS7 là máy quét LiDAR SLAM cầm tay hiệu năng cao của CHCNAV dành cho xây dựng và các ứng dụng nội thất.', NULL, NULL, 'Phần mềm', '', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (406, 'vi', 'Xchanger Suite - Phần mềm đánh giá, mô phỏng và thiết kế thiết bị truyền nhiệt', 'xchanger-suite-phan-mem-danh-gia-mo-phong-va-thiet-ke-thiet-bi-truyen-nhiet', NULL, 'Xchanger Suite là phần mềm mô phỏng và thiết kế quy trình nhiệt tiên tiến nhất, giúp đánh giá, mô phỏng hoặc thiết kế nhiều loại thiết bị truyền nhiệt. Các phương pháp tính toán của HTRI được thực hiện trong hơn nửa thế kỷ nghiên cứu ứng dụng và dữ liệu được thu thập trên các thiết bị truyền nhiệt liên quan đến công nghiệp.', NULL, NULL, 'Phần mềm', 'Xchanger Suite - Phần mềm đánh giá, mô phỏng và thiết kế thiết bị truyền nhiệt', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (407, 'vi', 'Leapfrog Edge - Phần mềm ước tính trữ lượng mỏ chính xác nhất ', 'leapfrog-edge-phan-mem-uoc-tinh-tru-luong-mo-chinh-xac-nhat', NULL, 'Giải pháp Leapfrog được hãng Seequent giới thiệu lần đầu trong ngành công nghiệp khai khoáng – mỏ vào năm 2004. Đây là một bộ giải pháp phần mềm ứng dụng trong toàn bộ vòng đời của một dự án khai thác mỏ, bắt đầu từ tìm kiếm thăm dò, đánh giá trữ lượng, thực hiện vận hành khai thác, và đóng cửa, hoàn nguyên cho cả dự án.', NULL, NULL, 'Phần mềm', 'Leapfrog Edge - Phần mềm ước tính trữ lượng mỏ chính xác nhất', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (413, 'vi', 'HỆ THỐNG MOBILE MAPPING LIDAR ALPHAUNI 20', 'he-thong-mobile-mapping-lidar-alphauni-20', NULL, 'AlphaUni 20 là một hệ thống Lidar Scanner đa nền tảng, mạnh mẽ và toàn diện, đại diện cho thế hệ mới nhất của công nghệ Mobile Mapping từ CHCNAV.', NULL, NULL, 'Thiết bị', 'HỆ THỐNG MOBILE MAPPING LIDAR ALPHAUNI 20', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (414, 'vi', 'HỆ THỐNG RADAR GIÁM SÁT CHUYỂN VỊ PS2000', 'he-thong-radar-giam-sat-chuyen-vi-ps2000', NULL, 'CHCNAV PS2000 là hệ thống giám sát chuyển vị dựa trên công nghệ Radar giao thoa khẩu độ tổng hợp mặt đất (Ground-Based InSAR) tiên tiến.', NULL, NULL, 'Thiết bị', 'HỆ THỐNG RADAR GIÁM SÁT CHUYỂN VỊ PS2000 – GIẢI PHÁP CẢNH BÁO SỚM SẠT LỞ TỪ CHCNAV', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (416, 'vi', 'TÀU KHẢO SÁT THỦY VĂN KHÔNG NGƯỜI LÁI APACHE 3', 'tau-khao-sat-thuy-van-khong-nguoi-lai-apache-3', NULL, 'Apache 3 là một tàu khảo sát không người lái chuyên nghiệp và di động, được phát triển để thực hiện các nhiệm vụ đo sâu (bathymetric survey) một cách tự động.', NULL, NULL, 'Thiết bị', 'TÀU KHẢO SÁT THỦY VĂN KHÔNG NGƯỜI LÁI APACHE 3', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (417, 'vi', 'BIMcollab', 'bimcollab', NULL, 'BIMcollab là một hệ sinh thái và môi trường dữ liệu chung (CDE) toàn diện, được thiết kế để tối ưu hóa sự hợp tác và quản lý thông tin trong suốt vòng đời của một công trình xây dựng, từ giai đoạn thiết kế, thi công cho đến vận hành và bảo trì.', NULL, NULL, 'Phần mềm', 'BIMcollab', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (418, 'vi', 'STAAD.Pro- Phần mềm phân tích và thiết kế kết cấu', 'staadprophan-mem-phan-tich-va-thiet-ke-ket-cau', NULL, 'STAAD là một ứng dụng phân tích và thiết kế phần tử hữu hạn kết cấu toàn diện, cung cấp cho bạn khả năng trực quan hóa mạnh mẽ và nhiều tiêu chuẩn thiết kế quốc tế.', NULL, NULL, 'Phần mềm', '', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (419, 'vi', 'HiCAD-Phần mềm CAD 2D 3D cho cơ khí, kết cấu thép và vách dựng nhôm kính', 'hicad-phan-mem-cad-2d-3d-cho-nhom-kinh', NULL, 'HiCAD là phần mềm CAD 2D/3D dành riêng cho các ngành thiết kế cơ khí, kết cấu thép, kim loại tấm, thiết kế nhà máy và kết cấu công trình.', NULL, NULL, 'Phần mềm', 'HiCAD-Phần mềm CAD 2D/3D cho cơ khí, kết cấu thép và vách dựng nhôm kính', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (420, 'vi', 'ZX300e - Thiết bị đo gió trên cao bằng công nghệ LiDAR', 'thiet-bi-do-gio-tren-cao-zx300e', NULL, 'ZX300e là thiết bị đo gió bằng công nghệ lidar mới nhất của ZXLidars. Độ chính xác và khả năng sử dụng được cải thiện lên đến 300m. Dữ liệu đạt chuẩn được DNV, UL, Wind Pioneers, Ramboll, Brightwind, Natural Power, Deutsche WindGuard… và nhiều tổ chức khác chấp nhận.', NULL, NULL, 'Thiết bị', '', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (421, 'vi', 'BIMcollab Zoom', 'bimcollab-zoom', NULL, ' INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (423, 'vi', 'Autodesk AEC Collection', 'autodesk-aec-collection', NULL, 'Autodesk AEC Collection là bộ giải pháp phần mềm tích hợp dành riêng cho ngành xây dựng.', NULL, NULL, 'Phần mềm', 'Autodesk AEC Collection', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (425, 'vi', 'Prokon- Phần mềm Phân tích và Thiết kế Kỹ thuật Kết cấu', 'prokon', NULL, 'Prokon là Phần mềm Phân tích và Thiết kế Kỹ thuật Kết cấu mạnh mẽ và toàn diện trong lĩnh vực thiết kế và phân tích kết cấu, được phát triển bởi Prokon Software Consultants.', NULL, NULL, 'Phần mềm', 'Phần mềm Phân tích và Thiết kế Kỹ thuật Kết cấu Prokon', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (426, 'vi', 'Robot Xây dựng', 'robot-xay-dung', NULL, 'Robot Xây dựng là giải pháp xây dựng thông minh kết hợp với trí tuệ nhân tạo và mô hình kiến trúc quy mô lớn cho  nhiều kịch bản xây dựng. ', NULL, NULL, 'Phần mềm', 'Robot xây dựng', 'Robot xây dựng', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (427, 'vi', 'OpenTrack Railway - Phần mềm mô phỏng và phân tích hệ thống đường sắt', 'opentrack-railway', NULL, 'OpenTrack là phần mềm mô phỏng và phân tích hệ thống đường sắt chuyên sâu, được phát triển theo mô hình vi mô, cho phép mô phỏng chi tiết hoạt động khai thác tàu trên mạng lưới đường sắt. Phần mềm hỗ trợ đánh giá năng lực tuyến, nhà ga, biểu đồ chạy tàu, hệ thống tín hiệu, khoảng cách chạy tàu tối thiểu, độ trễ, sự cố vận hành và tiêu thụ năng lượng trong quá trình khai thác.', NULL, NULL, 'Phần mềm', 'OpenTrack Railway - Phần mềm mô phỏng và phân tích hệ thống đường sắt', 'OpenTrack Railway', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (428, 'vi', 'CADprofi - Giải pháp Add-on CAD', 'cadprofi', NULL, 'Được phát triển bởi các chuyên gia hàng đầu, CADprofi là phần mềm add-on (ứng dụng mở rộng) chạy trực tiếp trên các nền tảng CAD phổ biến hiện nay như AutoCAD, BricsCAD, enjiCAD,...', NULL, NULL, 'Phần mềm', 'CADprofi', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (429, 'vi', 'SOLIDWORKS - Phần mềm chuyên thiết kế 3D', 'solidworks---phan-mem-chuyen-thiet-ke-3d', NULL, 'Phần mềm Solidworks là một trong những phần mềm chuyên về thiết kế 3D do hãng Dassault System phát hành dành cho những xí nghiệp vừa và nhỏ, đáp ứng hầu hết các nhu cầu thiết kế cơ khí hiện nay. Solidworks được biết đến từ phiên bản Solidworks 1998 và được du nhập vào nước ta với phiên bản 2003 và cho đến nay với phiên bản mới nhất phần mềm này đã phát triển đồ sộ về thư viện cơ khí và phần mềm này không những dành cho những xí nghiệp cơ khí nữa mà còn dành cho các ngành khác như: đường ống, kiến trúc, trang trí nội thất, mỹ thuật …INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (430, 'vi', 'test', 'test', NULL, '', NULL, NULL, 'Phần mềm', '', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (431, 'vi', 'test', 'test-1', NULL, '', NULL, NULL, 'Phần mềm', '', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (434, 'vi', 'CHCNAV X500 rotor UAV- FLYCAM KHẢO SÁT ĐỊA HÌNH', 'the-chcnav-x500-rotor-uavflycam-khao-sat-dia-hinh', NULL, 'The CHCNAV X500 rotor UAV là một thiết bị bay không người lái (UAV) chuyên nghiệp, được thiết kế với tải trọng và thời gian bay vượt trội.', NULL, NULL, 'Phần mềm', 'The CHCNAV X500 rotor UAV - FLycam khảo sát', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (433, 'vi', 'APACHE 6 - Tàu Khảo Sát Thủy Văn Tích Hợp Cảm Biến Đo Sâu Đa Tia', 'apache-6-tau-khao-sat-thuy-van-1', NULL, 'APACHE 6 là tàu khảo sát thủy văn tiên tiến, được tích hợp cho khảo sát đo độ sâu 3D, định vị các vật thể dưới nước, xây dựng hạ tầng ngoài khơi, khảo cổ học dưới nước và cứu hộ. Được chế tạo dựa trên công nghệ tàu ba thân và tối ưu hóa cho các dòng máy đo sâu hồi âm đa tia, APACHE 6 cung cấp chế độ khảo sát hoàn toàn tự động. Thiết bị được hỗ trợ bởi các công nghệ định vị chính xác của CHCNAV đã được chứng minh thực tế, cho phép APACHE 6 hoạt động theo lộ trình được xác định trước ngay cả trong điều kiện dòng chảy bất lợi.INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (435, 'vi', 'CHCNAV H3  - Thiết bị quan trắc và cảnh báo sạt trượt H3', 'chcnav-h3thiét-bị-quan-trac-va-canh-bao-sat-truot-h3', NULL, 'Thiết bị CHCNAV H3 là trạm thu nhận dữ liệu đa thông số tích hợp (All-in-one GNSS Receiver) thiết kế chuyên dụng cho các kịch bản quan trắc hiện trường. Nguyên lý hoạt động của H3 dựa trên sự kết hợp giữa định vị vệ tinh độ chính xác cao và cảm biến gia tốc/độ nghiêng siêu nhạy. ', NULL, NULL, 'Phần mềm', 'CHCNAV H3 – Giải pháp quan trắc sạt trượt bờ dốc mỏ', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword", "title") VALUES (436, 'vi', 'AlphaAir 10 - Hệ thống khảo sát trên không Lidar +RGB tiên tiến', 'alphaair-10', NULL, 'AlphaAir 10 là một giải pháp khảo sát trên không tiên tiến, tích hợp liền mạch các cảm biến LiDAR và RGB để đáp ứng nhu cầu lập bản đồ LiDAR bằng UAV chuyên nghiệp và đo ảnh từ drone.', NULL, NULL, 'Phần mềm', '', '', NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (199, 'en', 'GeoStudio', 'geostudio', NULL, 'GeoStudio gói phần mềm mô hình hóa địa kỹ thuật dành cho các kỹ sư, chuyên gia địa kỹ thuật', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (200, 'en', 'PROKON', 'prokon-software', NULL, 'PROKON® Structural Analysis and Design là một bộ phần mềm hoàn chỉnh cho mô hình, phân tích, thiết kế và triển khai chi tiết kết cấu công trình', NULL, NULL, 'Softwares', '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (57, 'en', 'Phần mềm bổ sung TCVN vào các chương trình tính kết cấu nước ngoài RDW', 'rdw-dua-tcvn-vao-cac-chuong-trinh-tinh-ket-cau-nuoc-ngoai', 'Khác', 'Hiện nay các phần mềm SAP90/SAP2000, ETABS (công ty CSI - Mỹ), STAADIII/STAADPRO (công ty REI - Mỹ) được sử dụng rộng rãi tại Việt Nam. Tuy nhiên việc sử dụng chỉ dừng lại ở bước tính toán nội lực do trong các phần mềm này chưa có Tiêu chuẩn thiết kế của Việt nam. RDW chính là phần mềm tiếp nối với SAP, ETABS, STAAD, bổ sung thiết kế và xuất bản vẽ theo TCVN cho các phần mềm nói trên.', NULL, 'Kết cấu công trình', 'Phần mềm', 'cic', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (58, 'en', 'Phần mềm tính toán thiết kế khung hỗn hợp - VinaSAS', 'vinasas-phan-mem-tinh-toan-thiet-ke-khung-hon-hop-1', 'Khác', 'Trong lĩnh vực tư vấn thiết kế xây dựng, vấn đề thiết kế công trình với sự trợ giúp của máy vi tính đã được ứng dụng tương đối rộng rãi ở Việt Nam đi vào từng lĩnh vực như kiến trúc, kết cấu, điện nước... Về mặt thiết kế kết cấu, các công ty tư vấn xây dựng trong cả nước và đặc biệt là các thành phố lớn như Hà Nội, thành phố Hồ Chí Minh, Đà Nẵng... đã sử dụng khá nhiều chương trình tính toán kết cấu, có thể kể ra các chương trình tiêu biểu như KP (trong môi trường DOS), FBT, HT, các chương trình của nước ngoài như SAP, STAAD, MICROFEAP... hoặc các chương trình tự lập bởi các cán bộ sở tại. Các chương trình nói trên chủ yếu đều đưa ra được các kết quả về nội lực, diện tích cốt thép trên các cấu kiện bê tông cốt thép theo các tiêu chuẩn, từ đó các kỹ sư thiết kế phải tiến hành chọn cách bố trí cốt thép và thể hiện chi tiết trên bản vẽ thi công. Cách tiến hành như vậy mới chỉ mang tính tự động hoá một phần, bởi vì trong thiết kế công trình, công việc tính toán thường chiếm thời gian không nhiều, việc thể hiện bản vẽ mới chính là công đoạn tốn phần lớn thời gian thiết kế. Vì vậy một phần mềm có tính tự động hoá cao (tương tự như chương trình PKPM của Trung Quốc ) từ tổ hợp nội lực, thiết kế cấu kiện, đến tự động thể hiện bản vẽ theo TCVN chính là mong muốn của nhiều nhà tư vấn thiết kế.INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (59, 'en', 'Phần mềm phân tích, thiết kế móng băng - MBW', 'mbw-phan-mem-tinh-mong-bang', 'Khác', 'MBW là phần mềm tự động hoá phân tích thiết kế kết cấu móng băng bê tông cốt thép đưa ra kết quả cuối cùng là bản vẽ kỹ thuật thi công, đồng thời cũng có thể thực hiện phân tích hệ kết cấu dầm giao nhau.', NULL, 'Kết cấu công trình', 'Phần mềm', '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (60, 'en', 'Phần mềm phân tích, thiết kế móng cọc - MCW', 'mcw-phan-mem-tinh-toan-mong-coc', 'Xây dựng', 'MCW là chương trình tính toán thiết kế và kiểm tra đối với móng cọc đài thấp. Chương trình được xây dựng trên cơ sở  những tiêu chuẩn móng cọc hiện hành  như  Tiêu chuẩn thiết kế móng cọc 20 TCN 21-86 (nay là TCXD205-98), tiêu chuẩn cọc tiết diện nhỏ, Móng cọc CTFE, Nền và móng... và chạy trên môi trường Windows9x/2000/NT.  Chương trình MCW có giao diện đẹp, trực quan, thuận lợi khi nhập số liệu và tính toán, kết quả tính toán đầy đủ ở cả tệp tin kết quả và bản vẽ thi công móng.', NULL, 'Kết cấu công trình', 'Phần mềm', '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (61, 'en', 'Phần mềm hỗ trợ vẽ thiết kế xây dựng và bóc tiên lượng - stCAD', 'stcad-ho-tro-ve-thiet-ke-xay-dung-va-boc-tien-luong', 'Xây dựng', 'stCAD là phần mềm hỗ trợ vẽ thiết kế xây dựng và tính tiên lượng dự toán tự động. Với môi trường đồ hoạ đa chức năng, stCAD cung cấp cho kỹ sư xây dựng bộ công cụ hỗ trợ thiết kế khá hoàn thiện. Chỉ bằng một vài thao tác xác lập đơn giản, stCAD đã có thể cung cấp cho các kỹ sư bản vẽ kỹ thuật cuối cùng của các kết cấu: dầm, cột, mặt bằng kết cấu, sàn, móng... một cách nhanh chóng và chính xác theo đúng các tiêu chuẩn hiện hành đang được áp dụng ở Việt Nam. Ngoài ra, stCAD còn có thể đọc kết quả thiết kế của các phần mềm như RDW, VinaSAS, SAP2000, ETABS... để xuất ra bản vẽ cũng như tự động bố trí cốt thép cho cấu kiện từ các kết quả phân tích thiết kế của các phần mềm trên. Hơn thế nữa, stCAD có thể bóc tách tiên lượng dự toán cho các cấu kiện (bóc khối lượng bê tông, ván khuôn, cốt thép).', NULL, 'Kết cấu công trình', 'Phần mềm', '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (62, 'en', 'enjiCAD- engineering CAD ', 'enjicad', 'Xây dựng', 'enjiCAD is a CAD software specifically for Vietnamese users', NULL, 'Kết cấu công trình', 'Softwares', '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (208, 'en', 'Phần mềm Quản lý Dự Án - CIC PLANNING', 'phan-mem-quan-ly-du-cic-planning', NULL, 'Quản lý điều hành thực hiện các dự án, theo dõi tiến độ thi công, xây lắp, nghiệm thu, thanh quyết toán các hạng mục của từng dự án.', NULL, NULL, 'Phần mềm', '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (209, 'en', 'Phần mềm Quản lý Hợp đồng: Đơn vị Chủ đầu tư - CONNA Phiên bản Chủ đầu tư', 'phan-mem-quan-ly-hop-dong-don-vi-chu-dau', NULL, 'Quản lý hợp đồng, phần mềm phát triển với cách tiếp cận mới, sử dụng giao diện đẹp của bộ Office 2007, font chữ Unicode và quản trị dữ liệu dùng chung theo mô hình Client/ Server, tích hợp trên các máy Chủ dữ liệu của các đơn vị. Việc ứng dụng CONNA  có thể linh hoạt áp dụng tùy theo yêu cầu quản lý thực tế của các đơn vị sử dụng, các quy trình và tiêu chuẩn quản lý chất lượng của các đơn vị. CONNA là một phần mềm mở, dễ dàng trong việc mở rộng, thêm các tính năng quản lý và mức độ áp dụng theo nhu cầu nghiệp vụ đặc thù của các đơn vị.', NULL, NULL, 'Phần mềm', '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (210, 'en', 'Phần mềm Quản lý Hợp đồng: Đơn vị Thi Công Xây Lắp - CONNA Phiên bản Thi Công Xây Lắp', 'phan-mem-quan-ly-hop-dong-don-vi-thi-con', NULL, 'Phần mềm phát triển với cách tiếp cận mới, sử dụng giao diện đẹp của bộ Office 2007, font chữ Unicode và quản trị dữ liệu dùng chung theo mô hình Client/ Server, tích hợp trên các máy Chủ dữ liệu của các đơn vị.', NULL, NULL, 'Phần mềm', '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (211, 'en', 'Phần mềm quản lý Hợp đồng Tư vấn thiết kế - Thực hiện tiến độ và Thanh quyết toán', 'phan-mem-quan-ly-hop-dong-tu-van-thiet-k', NULL, 'Phần mềm quản lý hợp đồng tư vấn thiết kế - thực hiện hợp đồng xây dựng, CONNA áp dụng cho mọi tổ chức thuộc ngành xây dựng cũng như các ngành nghề khác trong việc quản lý các hợp động kinh tế, thuộc các cơ quan, đơn vị hành chính sự nghiệp, các doanh nghiệp, ...', NULL, NULL, 'Phần mềm', '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (65, 'en', 'Phần mềm tính toán, thiết kế khung thép tiền chế - KIW', 'kiw-phan-mem-tinh-toan-thiet-ke-khung-thep-tien-che', 'Xây dựng', 'KIW là phần mềm tự động hoá phân tích thiết kế kết cấu khung thép tiền chế đưa ra kết quả cuối cùng là bản vẽ kỹ thuật thi công đối với khung thép có các cấu kiện thanh tiết diện chữ I. Đặc biệt KIW có khả năng thiết kế tối ưu đảm bảo điều kiện chịu lực và tiết kiệm vật liệu nhất', NULL, 'Đào tạo lái xe', 'Phần mềm', '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (66, 'en', 'Đơn giá, Chỉ số giá xây dựng công trình', 'don-gia-chi-so-gia-xay-dung-cong-trinh', 'Xây dựng', 'Công ty cổ phần Công nghệ và Tư vấn CIC đã tư vấn lập đơn giá xây dựng cơ bản, tư vấn lập chỉ số giá cho nhiều tỉnh trên khắp cả nước: Hà Giang, Điện Biên, Tuyên Quang, Bắc Kạn,  Sơn La, Lào Cai, Lạng Sơn, Đắk Nông, Ninh Bình,...', NULL, 'Đơn giá, Chỉ số giá xây dựng công trình', 'Phần mềm', '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (67, 'en', 'Phần mềm dự toán Escon 15 ', 'phan-mem-du-toan-escon-15', 'Xây dựng', 'Escon 15 là phần mềm tính đơn giá dự toán, dự thầu, thẩm tra được Công ty CP Tin học và tư vấn xây dựng phát triển từ năm 2000 trải qua nhiều phiên bản như Escon 3, Escon 4, Escon 5, Escon 6, Escon 7 (2011), Escon 8(2012) và hiện nay là Escon phiên bản 15. Thừa kế những tính năng mạnh của các phiên bản trước Escon 15 không ngừng phát triển bổ sung rất nhiều tính năng độc đáo mà chưa một phần mềm lập dự toán xây dựng công trình nào có.', NULL, 'Dự toán công trình', 'Phần mềm', '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (68, 'en', 'Kiểm tra cáp thép bằng phương pháp từ dư của Hãng LRM', 'thiet-bi-kiem-tra-cap-thep-bang-phuong-phap-tu-du-cua-hang-lrm', NULL, 'Hãng thiết bị LRM (Laboratory Dr Roman Martyna) là công ty hàng đầu thế giới về hệ thống kiểm tra không phá hủy chất lượng cáp và đường ống thép bằng phương pháp từ dư (MFL). Hệ thống LRM-XXI Diagnostic được phát triển bởi Dr.Roman Martyna, người có hơn 30 năm kinh nghiệm sáng chế, cung cấp dịch vụ trong lĩnh vực kiểm tra cáp thép ứng dụng công nghệ hiện đại.', NULL, NULL, 'Thiết bị', '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (69, 'en', 'Hệ thống mô phỏng và đào tạo lái xe TecknoSim', 'he-thong-mo-phong-va-dao-tao-lai-xe', NULL, 'Hệ thống mô phỏng lái xe ôtô là một giải pháp tối ưu để đào tạo các lái xe mới và lái xe có kinh nghiệm giúp cải thiện kỹ năng lái xe của họ. Hệ thống cho phép các học viên thành thạo các kỹ năng lái xe và đối mặt với tình huống nguy hiểm trong cuộc sống thực, mà không cần phải đối mặt với nguy hiểm thực sự', NULL, NULL, 'Thiết bị', '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (241, 'en', 'Autodesk AutoCAD', 'autodesk-autocad', NULL, 'AutoCAD là phần mềm thiết kế 2D và 3D chuyên nghiệp. Với phiên bản AutoCAD 2020, người dùng sẽ được trang bị thêm các bộ công cụ hỗ trợ (specialized toolsets) cho các lĩnh vực khác nhau cùng với phiên bản AutoCAD nền web, ứng dụng di động.', NULL, NULL, 'Softwares', '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (216, 'en', 'IDEA StatiCa Steel -Model, analyze, design, check steel connections', 'idea-statica-steel', NULL, 'IDEA StatiCa Steel - Model, analyze, design, check steel connections', NULL, NULL, 'Softwares', '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (206, 'en', 'Phần mềm thống kê thép - CICTKT', 'cictkt', NULL, 'Phần mềm hỗ trợ thống kê thép – CICTKT là phần mềm đã được công ty chúng tôi phát triển với giao diện đồ họa thân thiện người dùng. CICTKT sẽ là công cụ trợ giúp đắc lực cho các kỹ sư xây dựng để hoàn thành nhanh chóng việc thống kê toàn bộ cốt thép của mọi công trình xây dựng. CICTKT hoàn toàn miễn phí đối với các đơn vị, cá nhân đã mua một trong số các phần mềm của chúng tôi (có khoá cứng); trong trường hợp quý khách hàng chỉ muốn mua CICTKT thì giá phần mềm cài đặt cho 1 máy sẽ là 500.000 VNĐ (chúng tôi sẽ cung cấp mã cài đặt cho máy tính của quý khách hàng (mã mềm).', NULL, NULL, 'Phần mềm', '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (72, 'en', 'Sumac - Phần mềm tính toán san nền', 'sumac', NULL, '           Trong lĩnh vực tư vấn thiết kế, quy hoạch xây dựng và giao thông... sự trợ giúp của máy tính với các phần mềm tính toán ngày càng trở nên thông dụng. Việc xây dựng một chương trình tính toán, mô hình hoá địa hình, tạo đường đồng mức và đặc biệt là tính toán khối lượng đào đắp trong xây dựng và giao thông là hết sức cần thiết. Xuất phát từ nhu cầu đó, trung tâm Phần mềm Xây dựng - thuộc Công ty CP Tin học và Tư vấn Xây dựng (CIC) đã hoàn thành việc xây dựng phần mềm Sumac phục vụ cho công việc mô hình hoá bề mặt địa hình, tạo đường đồng mức, tạo bình đồ, tính toán San nền theo cách tính thực tế của kỹ sư Việt Nam. Chương trình Sumac có giao diện đồ hoạ dễ sử dụng (hệ đồ hoạ này tương tự AutoCAD), có khả năng mô hình hoá một cách chính xác bề mặt địa hình, tạo đường đồng mức, tạo bình đồ bằng phương pháp nội suy lưới ô vuông và tạo mặt cắt địa hình. Kết quả tính toán được thể hiện đầy đủ trên bản vẽ (bề mặt địa hình, đường đồng mức, bình đồ, kết quả tính toán san lấp theo từng ô và tổng cộng khối lượng đào đắp theo từng hàng, cột trên hệ lưới ô vuông). Bản vẽ kết quả có thể được xuất ra dưới định dạng AutoCAD (*.DWG; *.DXF).', NULL, NULL, 'Phần mềm', '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (201, 'en', 'GEO5', 'geo5', NULL, 'GEO5 là một bộ phần mềm, cung cấp giải pháp cho hầu hết các vấn đề địa kỹ thuật', NULL, NULL, 'Phần mềm', '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
