INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (84, 'en', 'Thiết bị kiểm tra kết cấu bê tông cốt thép của Hãng Elcometer (Anh), NDT James Instruments (Hoa Kỳ), Impact Echo (Hoa Kỳ), IDS (Italia).', 'thiet-bi-kiem-tra-ket-cau-be-tong', NULL, 'Thiết bị định vị, xác định hướng, chiều sâu, đường kính và độ ăn mòn cốt thép trong bê tông - Thiết bị xác định cường độ bê tông - Thiết bị siêu âm bê tông', NULL, NULL, 'Thiết bị', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (85, 'en', 'Thiết bị đo độ phản quang của vạch sơn kẻ đường, biển báo giao thông của Hãng Zehntner (Thụy Sĩ)', 'thiet-bi-do-do-phan-quang-cua-zehntner', NULL, 'Với trên 45 năm kinh nghiệm, Zehntner hiện là một trong những hãng đứng đầu thế giới về các thiết bị kiểm tra vạch kẻ đường và biển báo giao thông.', NULL, NULL, 'Thiết bị', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (86, 'en', 'Thiết bị kiểm tra cọc của hãng Piletest (Israel)', 'thiet-bi-kiem-tra-coc-cua-hang-piletest-', NULL, 'Được thành lập cách đây trên 10 năm, Piletest chuyên phát triển các hệ thống kiểm tra cọc nhằm đảm bảo chất lượng cọc, đồng thời cũng cung cấp các thiết bị thực hiện đánh giá chất lượng các hệ thống móng sâu như cọc, cừ, caissons barrettes....', NULL, NULL, 'Thiết bị', '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (189, 'en', 'Thiết bị Radar xuyên đất của hãng GEOScanner', 'thiet-bi-radar-xuyen-dat-hang-geoscanner', NULL, 'U-Explorer là một sản phẩm khảo sát địa vật lý hoàn chỉnh của GEOScanner. Cấu hình anten và bộ điều khiển trung tâm có thể dễ dàng thay đổi nhằm phù hợp với các loại khảo sát địa vật lý khác nhau. Hệ thống Anten do Geoscanner cung cấp đa dạng từ loại khảo sát rất nông kết hợp việc di chuyển tốc độ cao đến loại siêu sâu có độ phân giải chấp nhận được. Bộ điều khiển trung tâm có thể kết nối từ một đến nhiều anten và xử lý cùng một lúc cho kết quả chi tiết, đáng tin cậy', NULL, NULL, 'Thiết bị', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (88, 'en', 'Thiết bị siêu âm mối hàn, siêu âm kim loại của Hãng NDT Systems (Hoa Kỳ), Starmans (CH Séc)', 'thiet-bi-sieu-am-moi-han-va-kim-loai', NULL, 'NDT Systems là một trong những hãng thiết bị đi đầu trong lĩnh vực kiểm tra không phá hủy. Sản phẩm của hãng bao gồm một loạt các thiết bị: thiết bị siêu âm đo chiều dày kim loại, siêu âm dò khuyết tật cầm tay, hệ thống siêu âm hiển thị hình ảnh. Cùng với sự phát triển của công nghệ, NDT Systems liên tục đưa ra các dòng sản phẩm mới để phục vụ cho nhu cầu ngày càng cao của khách hàng', NULL, NULL, 'Thiết bị', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (89, 'en', 'CSiDetail', 'csidetail', NULL, 'CSiDetail Phần mềm kết hợp với ETABS triển khai bản vẽ chi tiết kết cấu công trình', NULL, NULL, 'Phần mềm', '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (90, 'en', 'OILMAP', 'phan-mem-oilmap', NULL, 'OILMAP là phần mềm dùng để mô phỏng sự cố tràn dầu và cung cấp những dự báo nhanh về sự cố dầu tràn.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (91, 'en', 'Thiết bị xuyên tĩnh của hãng A.P.Vanden Berg (Hà Lan)', 'thiet-bi-xuyen-tinh-cua-hang-apvanden-be', NULL, 'Được thành lập từ năm 1968, A.P.Van den Berg là nhà sản xuất, phân phối thiết bị thí nghiệm xuyên tĩnh hàng đầu trên thế giới hiện nay. Ngoài ra, A.P.Van den Berg còn là nhà phân phối các thiết bị thủy lực, tham gia vào các dự án lớn trên toàn thế giới.', NULL, NULL, 'Thiết bị', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (92, 'en', 'CSiXRevit', 'csixrevit', NULL, 'CSiXRevit - công cụ link giữa Etabs, SAP2000, SAFE với phần mềm Autodesk Revit', NULL, NULL, 'Phần mềm', '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (97, 'en', 'PLAXIS 2D', 'plaxis-2d', NULL, 'PLAXIS 2D | Giải pháp phần mềm 2D phần tư hữu hạn ứng dụng trong địa kỹ thuật', NULL, NULL, 'Phần mềm', '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (93, 'en', 'Thiết bị thí nghiệm nén ngang (DMT) của Hãng Studio Prof Marchetti (Italia)', 'thiet-bi-thi-nghiem-nen-ngang-dmt', NULL, 'Thí nghiệm nén ngang Flat Dilatometer Test (DMT) được phát triển lần đầu tiên tại Italia bởi Giáo sư Marchetti vào giữa những năm 70 và hiện đang được sử dụng tại hơn 40 quốc gia trên thế giới.', NULL, NULL, 'Thiết bị', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (94, 'en', 'CSI Apps', 'csi-apps', NULL, 'CSI Apps - Ứng dụng xem mô hình SAP2000, ETABS, và các tiện ích CSiSections, CSiSteel, CSiRebar... trên máy tính bảng và điện thoại thông minh', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (96, 'en', 'Thiết bị đo độ chặt-độ ẩm nền đất đắp, bê tông nhựa của Hãng Troxler (Hoa Kỳ)', 'thiet-bi-do-do-chat-do-am-troxler', NULL, 'Thành lập năm 1958, Troxler hiện đang là đơn vị hàng đầu trên thế giới về các thiết bị đo lường, kiểm tra chất lượng trong các ngành công nghiệp và xây dựng đường cao tốc.', NULL, NULL, 'Thiết bị', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (95, 'en', 'Thiết bị cắt cánh hiện trường (VST) của Hãng Geonor (Na Uy)', 'thiet-bi-cat-canh-hien-truong-vst', NULL, 'Với hơn 30 năm kinh nghiệm, Geonor chuyên cung cấp các sản phẩm thiết bị cắt cánh hiện trường để xác định sức kháng cắt không thoát nước của đất, được sử dụng cho các loại đất dính mềm yếu, bão hoà nước.', NULL, NULL, 'Thiết bị', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (98, 'en', 'PLAXIS 3D', 'plaxis-3d', NULL, 'PLAXIS 3D | Giải pháp phần mềm 3D phần tử hữu hạn trong lĩnh vực địa kỹ thuật', NULL, NULL, 'Phần mềm', '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (99, 'en', 'OILMAP DEEP', 'phan-mem-oilmap-deep', NULL, 'OILMAPDEEP cung cấp những phán đoán nhanh chóng của sự di chuyển của dầu tràn ở trên bề mặt biển. Cả sự kết hợp mô đun công nghiệp CDOG và mô hình chùm tự nhiên của OILMAP cũng được hỗ trợ.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (100, 'en', 'PLAXIS VIP', 'plaxis-vip', NULL, 'Plaxis VIP là một hệ thống đăng ký bổ sung dựa trên bản quyền truyền thống, được hiểu như là một khoản chi phí bảo trì hàng năm cho phần mềm Plaxis.', NULL, NULL, 'Phần mềm', '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (191, 'en', 'Thiết bị thí nghiệm nén ba trục, thiết bị nén cố kết, thiết bị CBR, thiết bị cắt phẳng, CBR, Marshall, thiết bị nén uốn đa năng… của các Hãng APS (Đức), GDS (Anh Quốc), Walter-bai (Thụy Sĩ)', 'thiet-bi-thi-nghiem-nen-ba-truc', NULL, 'Các thiết bị địa kỹ thuật phòng thí nghiệm thực hiện các thí nghiệm trong các lĩnh vực cơ lý đất, đá trong phòng.', NULL, NULL, 'Thiết bị', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (101, 'en', 'PLAXIS MoDeTo', 'plaxis-modeto', NULL, 'PLAXIS MoDeTo - Dòng sản phẩm mới của PLAXIS ứng dụng thiết kế cọc monopile ứng dụng trong các công trình ngoài khơi', NULL, NULL, 'Phần mềm', '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (234, 'en', 'SketchUp Pro', 'sketchup_pro', NULL, 'Phần mềm thiết kế 3D chuyên nghiệp dành cho một loạt các lĩnh vực như kiến trúc , thiết kế nội thất,  ngoại thất và cảnh quan, kỹ thuật dân dụng và cơ khí , thiết kế phim và trò chơi điện tử.', NULL, NULL, 'Phần mềm', '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (197, 'en', 'Adapt PT', 'adapt-pt', NULL, 'ADAPT-PT phần mềm thiết kế sàn dự ứng lực theo phương pháp khung tương đương (2D)', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (198, 'en', 'Adapt ABI', 'adapt-abi', NULL, 'Adapt ABI Phần mềm mô hình, phân tích thiết kế kết cấu cầu bê tông dự ứng lực. Mô hình 3D trực quan, khả năng tạo ra trình độ thi công 4D.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (103, 'en', 'Thiết bị địa vật lý khác: Carota giếng khoan, địa chấn biển, trọng lực, từ telua, đo phân cực kích thích', 'thiet-bi-dia-vat-ly-carota-dia-chan-bien', NULL, '1. Thiết bị carota lỗ khoan 2. Thiết bị phân cực kích thích 3. Thiết bị đo phóng xạ', NULL, NULL, 'Thiết bị', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (104, 'en', 'Thiết bị quét Laser khảo sát, bản đồ hóa 3D biên dạng khảo sát các khu mỏ, khoang rỗng dưới lòng đất của Hãng Renishaw (Anh Quốc)', 'thiet-bi-quet-laser-khao-sat-ban-do-hoa-3d-bien-dang-khao-sat-cac-khu-mo-khoang-rong-duoi-long-dat-cua-hang-renishaw-anh-quoc', NULL, 'Được thành lập vào năm 1983, Renishaw là công ty hàng đầu thế giới trong việc thiết kế và sản xuất các hệ thống thiết bị đo laser tốc độ cao sử dụng trong môi trường khắc nghiệt.', NULL, NULL, 'Thiết bị', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (190, 'en', 'Thiết bị giám sát ảnh hưởng chấn động và áp suất sóng không khí/ tiếng ồn của Instantel (Canada)', 'thiet-bi-giam-sat-anh-huong-chan-dong-va', NULL, 'Từ năm 1982, Instantel, một bộ phận của Xmark Corporation và là thành viên của The Stanley Works, đã tạo được vị trí dẫn đầu cho lĩnh vực cung cấp các thiết bị đo đạc dao động phục vụ cho các ngành xây dựng, khai khoáng và địa kỹ thuật. Từ những sensor chuyên dụng, những định dạng ghi dữ liệu phức tạp, cho tới dữ liệu biểu đồ thời gian thực, thu thập dữ liệu từ xa thông qua mạng internet, Instantel tiếp tục quá trình đổi mới liên tục nhằm phục vụ tốt nhất nhu cầu khách hàng.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (105, 'en', 'Thiết bị quét Sonar khảo sát và vẽ biên dạng 3D các khoang rỗng dưới lòng đất, quét biên dạng đáy sông, biển của Hãng Imagenex (Canada)', 'thiet-bi-quet-sonar', NULL, 'Imagenex là công ty hàng đầu thế giới về công nghệ quét Sonar. Với công nghệ quét Sonar, không có gì quan trọng hơn là việc có được các hình ảnh rõ nét. Do vậy, Imagenex có đội ngũ thiết kế luôn luôn đi tiên phong trong việc phát triển công nghệ hình ảnh Sonar hiện đại và sản xuất các thiết bị Sonar độ phân giải cao.', NULL, NULL, 'Thiết bị', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (107, 'en', 'ĐÊ MỀM CHỐNG NGẬP - NGĂN LŨ (HÃNG AET - ANH QUỐC)', 'de-mem-chong-ngap-ngan-lu-hang-aet', NULL, 'Sản phẩm Đê mềm chống ngập Tự động, dễ triển khai Hiệu quả cho các chung cư, các tòa nhà, các tầng hầm. Chống ngập lụt do mưa lũ cho các công trình đang thi công, xây dựng.', NULL, NULL, 'Thiết bị', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (108, 'en', 'OILMAP LAND', 'phan-mem-oilmap-land', NULL, 'Tính năng cơ bản: INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (109, 'en', 'CHEMMAP', 'phan-mem-chemmap', NULL, 'Tính năng cơ bản: INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (110, 'en', 'SARMAP', 'phan-mem-sarmap', NULL, 'Tính năng cơ bản: INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (111, 'en', 'Cơ sở dữ liệu EDS', 'co-so-du-lieu-eds', NULL, 'Tính năng cơ bản: INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (112, 'en', 'Maros', 'maros-cong-cu-phan-tich-ram-tham-do-dau', NULL, 'Maros™ là một công cụ phân tích RAM* cao cấp, với những tính năng mở rộng cho việc mô phỏng cấu trúc hoạt động của doanh nghiệp, các nhu cầu, các kế hoạch bảo trì và vận hành. Maros™ hỗ trợ người dùng ra các quyết định chính xác để tối đa hóa mức doanh thu trên vốn đầu tư bỏ ra.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (113, 'en', 'Synergi Plant ', 'synergi-plant-quan-ly-rui-ro-nha-may', NULL, 'Synergi Plant là một giải pháp phần mềm của DNV, được xây dựng trên thực tiễn kỹ thuật và kinh nghiệm quản lý. Phần mềm sẽ cung cấp một cách tiếp cận PDCA hoàn chỉnh để quản lý rủi ro tài sản, đã được sử dụng bởi các khách hàng hoạt động trong nhà máy quy trình thượng nguồn và hạ nguồn ở các vùng khác nhau trên thế giới.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (114, 'en', 'PTV Optima', 'giai-phap-quan-ly-giao-thong-ptv-optima', NULL, 'PTV Optima là chìa khóa giúp bạn quản lý giao thông một cách hiệu quả. Công cụ mô phỏng này cung cấp những thông tin giao thông theo thời gian thực của toàn bộ mạng lưới giao thông một cách chính xác và đưa ra các dự báo đáng tin cậy về tinh hình giao thông trong 60 phút tiếp theo.', NULL, NULL, 'Softwares', '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (115, 'en', 'SynerGEE Gas', 'synergee-gas-mo-phong-he-thong-phan-phoi', NULL, 'SynerGEE® Gas giúp các nhà khai khác thiết kế và phát triển hệ thống đường ống và mạng hiệu suất cao với chi phí phù hợp, khả năng cung cấp đến các mức nhu cầu dự kiến. Nhà khai thác cần phải lường trước và đáp ứng sự biến đổi hoạt động và cơ sở hạ tầng qua việc lập kế hoạch các giai đoạn dài và ngắn hạn, SynerGEE® Gas có thể giúp bằng cách sử dụng một trong các công cụ mô hình ổn định và mạnh mẽ nhất thế giới. SynerGEE® Gas cung cấp các mô-đun tính năng nâng cao và được cập nhật mà cho phép bạn tạo ra kết quả mô phỏng nhanh chóng, chính xác. SynerGEE® Gas cung cấp một bộ giải hiệu quả ổn định mà cung cấp các khả năng cân bằng thành phần và nhiệt lượng, thể tích đáng tin cậy và mạnh mẽ. Phần mềm cho phép bạn mô hình hệ thống được tích hợp đa mức áp suất và cung cấp cho bạn toàn quyền kiểm soát các điều khiện ràng buộc khí (trọng lượng, giá trị nhiệt và độ nhớt), phương trình trạng thái, tính toán yếu tố ma sát và hằng số truyền nhiệt.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (116, 'en', 'PTV VISTRO', 'ptv-vistro-toi-uu-hoa-mang-luoi-gt', NULL, 'PTV VISTRO đã được phát triển chuyên biệt để phân tích, nghiên cứu, đánh giá tác động của sự phát triển hạ tầng giao thông mới, và tối ưu hóa thời gian đèn tín hiệu. Phần mềm được sử dụng để phân tích và tối ưu giao thông tại một nút giao, hành lang đường, hoặc trên toàn bộ mạng lưới. PTV Vistro cung cấp lựa chọn các phương pháp phân tích tiêu chuẩn công nghiệp, như HCM2010 và HCM2000. PTV Vistro hiển thị kết quả tức thì cho khối lượng đến năng lực, mức độ dịch vụ (LOS) và chậm trễ của giao thông - với một bảng và đồ thị trong cửa sổ mạng. Chức năng báo cáo thân thiện người dùng tạo ra bảng và số liệu báo cáo nhanh chóng và dễ dàng. <p> </p> Xây dựng mạng lưới hiệu quả với hỗ trợ của Bingmaps, công cụ đồ họa kéo và thả, và các mẫu nút giao. Ngoài ra, một bảng tiến trình công việc sẽ hướng dẫn người sử dụng hiệu quả thông qua các giai đoạn khác nhau của dự án và cung cấp tối ưu hóa thời gian đèn tín hiệu. Phần mềm này cũng hỗ trợ liên kết đến PTV Visum và PTV Vissim.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (117, 'en', 'Synergi Water', 'synergi-water-phan-mem-mo-phong', NULL, 'Synergi Water - gói phần mềm mô phỏng của chúng tôi cho mô hình hóa và phân tích mạng lưới ống dẫn khép kín của đường ống, bộ máy điều chỉnh, van, máy bơm, hồ chứa nước, bể chứa nước, giếng đào và giếng khoan - cho phép bạn khởi động nhanh chóng, kết quả mô hình chính xác. Synergi Water được sử dụng bởi hàng trăm công ty dịch vụ công cộng, các công ty trung nguồn dầu mỏ và khí đốt và các công ty kỹ thuật trên toàn thế giới.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (118, 'en', 'Synergi Life', 'synergi-life-phan-mem-quan-ly-rui-ro-va-', NULL, 'Synergi Life là một giải pháp dành cho các doanh nghiệp để quản lý rủi ro và QHSE. Phần mềm bao gồm rất nhiều các tiến trình công việc như báo cáo, phân tích, hành động khắc phục, thông tin liên lạc, chia sẻ kinh nghiệm, định hướng và giám sát chỉ số hiệu suất “KPI”.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (119, 'en', 'Safeti Offshore', 'safeti-offshore', NULL, 'Safeti Offshore cung cấp một cách tiếp cận tiêu chuẩn có cấu trúc và hệ thống dành cho việc tiến hành đánh giá định lượng rủi ro ngoài khơi. Nó cung cấp nhiều khả năng mạnh mẽ chính xác, linh hoạt và phong phú để thực hiện đa dạng việc đánh giá định lượng rủi ro cho các công trình ngoài khơi', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (122, 'en', 'PTV VISSIM', 'phan-mem-mo-phong-giao-thong-ptv-vissim', NULL, 'VISSIM là phần mềm mô phỏng, phân tích luồng giao thông, hỗ trợ công tác phân luồng, góp phần giảm tắc nghẽn giao thông trong các đô thị.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (121, 'en', 'PTV VISUM', 'phan-mem-quy-hoach-giao-thong-ptv-visum', NULL, 'PTV VISUM 15 - Phần mềm phân tích, dự báo, lập phương án quy hoạch giao thông đô thị. Visum 15 là phần mềm hàng đầu thế giới để mô hình hóa mạng lưới giao thông. Được thiết kế để phân tích đa phương thức, VISUM kết hợp tất cả các đối tượng có liên quan đến giao thông vận tải (ví dụ: ô tô, xe chở khách, xe hàng, xe buýt, tầu hỏa, xe máy, xe đạp và khách bộ hành) bên trong cùng một mô hình mạng.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (123, 'en', 'LEAK ', 'leak-phan-mem-tinh-toan-tan-so-ro-ri', NULL, 'Phần mềm LEAK tính toán tần số rò rỉ của các thiết bị, phân đoạn, các khu vực và các cài đặt từ dữ liệu cơ sở cơ bản', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (124, 'en', 'Phast Software ', 'phast-phan-mem-phan-tich-nguy-hiem', NULL, 'Phần mềm phân tích rủi ro - mô hình hóa hậu quả toàn diện cho tất cả các giai đoạn của quá trình thiết kế và vận hành ngành công nghiệp.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (126, 'en', 'HVE Software', 'tai-tao-mo-phong-va-phan-tichtai-nan', NULL, 'Phần mềm này được dùng để tái tạo va chạm xe cơ giới, phần mềm tái hiện tai nạn cho một hoặc nhiều xe va chạm. Mục đích là xác định tốc độ tác động và mức độ nghiêm trọng của tác động dựa trên vị trí tai nạn và thiệt hại phương tiện. Phần mềm cho phép mô phỏng xe cơ giới, bao gồm số lượng xe, va chạm nhiều đối tượng và các dạng va chạm. Phần mềm này giúp các nhà nghiên cứu xác định được các yếu tố góp phần vào vụ tai nạn đường bộ mà còn xác định được tiềm năng kết quả chấn thương của người trong xe từ những tai nạn tương tự.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (125, 'en', 'Hãng PTV Group', 'gioi-thieu-hang-ptv-group', NULL, 'PTV Group cung cấp công nghệ phần mềm tiên tiến và tư vấn để cho phép đáp ứng các yêu cầu linh hoạt của khách hàng . Nó hỗ trợ những người làm quy hoạch và quản lý giao thông và giao thông thông vận tải, cung cấp cho họ với những báo cáo giao thông mới nhất và hỗ trợ họ tối ưu xác định tài nguyên dài hạn. Từ năm 1979, hoạt động duy nhất của tập đoàn PTV là trở thành nhà cung cấp hàng đầu về các sản phẩm và giải pháp cho quy hoạch đi lại, giao thông và giao thông vận tải.INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (127, 'en', 'Hãng Engineering Dynamics Corporation (EDC)', 'engineering-dynamics-corporation-edc', NULL, 'Công ty Engineering Dynamics Corporation (EDC) có trụ sở tại Beaverton, Oregon, chuyên phát triển phần mềm mô phỏng an toàn của các phương tiện giao thông. Khách hàng của EDC gồm cả các nhà sản xuất phương tiện giao thông, các cơ quan chính phủ, các trường đại học và cả các hãng tư vấn kỹ thuật.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (128, 'en', 'Safeti software', 'safeti-software', NULL, 'Phần mềm đánh giá định lượng rủi ro và tần suất rủi ro các công trình công nghiệp.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (250, 'en', 'CADprofi', 'cadprofi', NULL, 'Developed by leading experts, CADprofi is an add-on software that runs directly on popular CAD platforms such as AutoCAD, BricsCAD, enjiCAD, etc.', NULL, NULL, 'Softwares', 'CADprofi – Professional CAD Add-On Software', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (130, 'en', 'CALPUFF VIEW', 'phan-mem-calpuff-view', NULL, 'Là dạng mô hình nguồn phát không ổn định Gaussian mô phỏng sự di chuyển tầm xa của hóa chất trong khí quyển, cho những trường hợp khó khăn (tầm nhìn hạn chế, hướng gió, địa hình phức tạp). Cung cấp một giải pháp đồ họa hoàn chỉnh cho hệ thống mô hình hóa CALPUFF, CALMET, và CALPOST. CALPUFF View hỗ trợ EPA version 5.8 và phiên bản cao cấp 6.0 của hệ thống CALPUFF.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (131, 'en', 'CALRoads VIEW', 'phan-mem-calroads-view', NULL, 'Là một mô hình phân tán hóa chất ô nhiễm trong không khí đối với giao thông đô thị, dự đoán nồng độ ô nhiễm không khí của khí (CO,NO2), dạng hạt (PM), và các loại khí trơ khác từ phương tiện nhàn rỗi hoặc di chuyển. . CALRoads View là giao diện tích hợp của các mô hình: CALINE4 , CAL3QHC, and CAL3QHCR.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (132, 'en', 'Auto Track Rail', 'auto-track-rail', NULL, 'Phân tích con đường cho xe điện và các phương tiện đường sắt khác Kiểm tra và đánh giá các chuyển động của xe điện và xe đường sắt nhẹ khác. Với các tính năng như Wizard Report, hoạt hình 3D và thư viện một xe điện trên toàn thế giới, nó phải là công cụ đơn giản nhất có sẵn để mô hình xe điện chuyển động. Sử dụng cùng với AutoTrack cho thiết kế đường cao tốc để mô hình các phương tiện đường bộ khác đi.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (133, 'en', 'Auto Track Airport', 'auto-track-airport', NULL, 'Công cụ phân tích đường vòng 3D tiên tiến nhất thế giới Phân tích tất cả các khía cạnh của tất cả các hoạt động airside sân bay, kiểm tra máy bay bay chờ, vị trí của khoang thông, thúc đẩy các cuộc diễn tập trở lại, khu vực an toàn của máy ban và sử dụng các điểm phục vụ và cảnh báo cánh cửa để lên kế hoạch di chuyển phương tiện hỗ trợ', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (134, 'en', 'EcoRisk VIEW', 'phan-mem-ecorisk-view', NULL, 'Là một chương trình đánh giá rủi ro sinh thái cao cấp toàn diện dựa trên nghị định thư US EPA SLERAP (Screening Level Ecological Risk Assessment Protocol). EcoRisk view đánh giá toàn diện đa sinh thái đồng thời tính toán giá trị rủi ro đối với hóa chất khác nhau, từ nhiều nguồn, nhiều vị trí tiếp xúc.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (135, 'en', 'Auto Track Junction', 'auto-track-junction', NULL, 'Tương tác thiết kế đường vòng để lại các kỹ sư kiểm soát! Tạo vòng xuyến từ sự liên kết đang tồn tại, địa điểm chia đảo xuyến, giao cắt, dải rumble điều khiển giao thông. Điều chỉnh hình học và nhận được phản hồi ngay lập tức về việc làm thế nào nó ảnh hưởng đến đường nhanh nhất và tốc độ, tốc độ dòng chảy, chiều dài hàng đợi và mức độ dịch vụ bằng cách sử dụng liên kết động với tiêu chuẩn ngành công nghiệp ARCADY 7. AutoTrack Junction cho phép bạn tạo ra các đảo với các tiêu chuẩn trên toàn thế giới và đánh giá cho dòng nhanh nhất trong một phần nhỏ của thời gian, nó sẽ có được bằng cách sử dụng các phương pháp truyền thống. Hơn nữa, liên kết động duy nhất để ARCADY cho phép bạn thực hiện các phân tích lưu lượng / công suất cùng một lúc.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (136, 'en', 'Auto Track Road', 'auto-track-road', NULL, 'Auto Track Roads - Phân tích Xe qua Đường vòng Chương trình mô phỏng xe đi qua chỗ rẽ tiến tiến nhất thế giới. Dự báo đường vòng của hướng xe ở các vịnh, chỗ đường vòng, vòng xuyến, các khu vực dịch vụ. Với các loại xe được thiết kế sẵn, hỗ trợ cho các xe người dùng tự định nghĩa phức tạp, nhiều mô hình lái xe, khả năng tùy biến các tùy chọn trình diễn và tương tích với các hệ thống CAD, AutoTrack được sử dụng hàng ngày bởi các hàng nghìn kỹ sư trên toàn thế thế giới.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (137, 'en', 'Trazer', 'phan-mem-dem-xe-trazer', NULL, 'Hãng KritiKal là hãng thiết kế, ứng dụng và sáng tạo công nghệ hàng đầu ở Ấn Độ và trên thế giới. Tiếng Ấn Độ thì "Kritikal" có nghĩa là "sáng tạo cho tương lai". Được thành lập vào năm 2002, KritiKal là một trong rất ít công ty trên thế giới với thế mạnh trong cả thiết kế hệ thống nhúng và giải pháp hình ảnh theo thời gian thực Kritikal chuyên về các giải pháp xử lý video thời gian thực hoặc video off-line cho các ứng dụng trực tuyến, giải pháp phân tích hình ảnh với công nghệ mới và tiên tiến nhất trên thế giới.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (138, 'en', 'METROCOUNT', 'metro', NULL, 'Giải pháp MetroCount cho bạn nhiều hơn một lớp đơn giản, tốc độ và báo cáo lưu lượng, cho phép bạn tìm kiếm và lưu vào bên trong hệ thống một cách chính xác chi tiết, hoàn toàn tới những trục xe cụ thể. Hệ thống phân loại xe MetroCount kết hợp với trạng thái hình ảnh giao thông khi truy cập phần cứng, là một phần mềm dễ sử dụng. MetroCount cung cấp cho bạn một giải pháp tổng thể để bạn giám sát những vấn để giao thông bạn đang quan tâm, từ những thống kê hàng ngày cho tới những vấn đề quản lý giao thông phức tạp.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (145, 'en', 'Emissions VIEW', 'phan-mem-emissions-view', NULL, 'Là một chương trình đánh giá rủi ro sinh thái cao cấp toàn diện dựa trên nghị định thư US EPA SLERAP (Screening Level Ecological Risk Assessment Protocol). EcoRisk view đánh giá toàn diện đa sinh thái đồng thời tính toán giá trị rủi ro đối với hóa chất khác nhau, từ nhiều nguồn, nhiều vị trí tiếp xúc.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (139, 'en', 'ARTM VIEW', 'phan-mem-artm-view', NULL, 'Là một giao diện sử dụng cho mô hình ARTM, được xem là tiêu chuẩn mới cho mô hình hóa và tính toán về sự phát tán và lắng đọng của các vật liệu bức xạ trong không khí theo quy định của Luật hạt nhân ở Đức.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (140, 'en', 'MAAP & iMAAP', 'pm-maap-imaap-quan-ly-tai-nan-giao-thong', NULL, 'MAAP là một gói phân tích và báo cáo tinh vi và tổng thể, một sản phẩm phần mềm TRL đã được cung cấp cả ở Anh và trên toàn thế giới kể từ năm 1980. Được sử dụng bởi chính quyền địa phương ở khắp nước Anh và quốc tế, nó cung cấp công cụ để lưu trữ và phân tích các yếu tố gây ra tai nạn, địa lý lân cận (thông qua việc xây dựng sẵn công cụ GIS) và một bộ các kiểu dữ liệu khác. iMAAP là thế hệ mới của MAAP. Phiên bản mới iMAAP cung cấp công cụ phù hợp tốt hơn với môi trường công nghệ hiện nay, cung cấp thêm tính năng dựa trên yêu cầu của các chuyên gia là những người sử dụng phần mềm. Cùng với công cụ mới, iMAAP là một hệ thống hoàn toàn linh hoạt trên nền tảng web có khả năng xử lý hàng loạt các hệ cơ sở dữ liệu và các định dạng GIS, cũng như các tiêu chuẩn ngày càng phức tạp, nghiêm ngặt và bảo mật.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (141, 'en', 'PERS', 'phan-mem-pers-xem-lai-moi-truong-di-bo', NULL, 'PERS (Phần mềm Xem lại Môi trường Đi bộ) là ứng dụng phần mềm mới và động để đánh giá chất lượng của môi trường cho phần dành để đi bộ. PERS có thể hộ trợ đưa ra các cơ hội để cải thiện đường dành cho người đi bộ, trong khi hỗ trợ hiệu quả mục tiêu tài nguyên. Khuôn khổ hệ thống của nó cho phép cung cấp cho người đi bộ được đánh giá, xem xét và kiểm toán thông qua việc sử dụng các phương pháp sáng tạo và rất thành công.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (142, 'en', 'SCOOT', 'phan-mem-scoot', NULL, 'SCOOT là hệ thống giám sát giao thông, nó kiểm soát tín hiệu trong mạng lưới các nút giao thông; thích ứng và phản ứng tự động tới những nơi giao thông bất thường, tạo hiệu quả đặt biệt trong các khu vục các luồng giao thông không dự báo trước được. Phần mềm này được sử dụng ở trên 170 thị trấn và thành phố ở UK và nhiều nước khác.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (143, 'en', 'AUSTAL VIEW', 'phan-mem-austal-view', NULL, 'Là giao diện đồ họa cho mô hình AUSTAL, có 3 phiên bản (T, G và TG) và 1 module add-on. AUSTAL2000 là mô hình theo dõi sự phân tán trong không khí của hạt Lagrangian (đặt theo tên nhà toán học Lagrange). Mô hình tính đến ảnh hưởng của địa hình đối với gió và gió đối với việc phát tán chất ô nhiễm, theo quy định về ô nhiễm không khí của Đức là TAluft.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (144, 'en', 'MOVA', 'phan-mem-mova', NULL, 'MOVA là hệ thống giám sát tín hiệu đèn giao thông ở những nút giao thông. Nó chuyển đổi thông minh giữa cách trì hoãn thấp nhất và lưu lượng tối đa, phụ thuộc vào yêu cầu giao thông. Hiện nay ở Anh đang cân nhắc có ít nhất 3000 vị trí được trang bị MOVA, với mỗi năm nhìn thấy ít nhất 200 vị trí khác được cài đặt.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (146, 'en', 'TRANSYT', 'phan-mem-toi-uu-hoa-mang-luoi-giao-thon', NULL, 'TRANSYT là giải pháp để thiết kế, mô hình và nghiên cứu năng lực giao thông tại các nút giao riêng biệt cho tới cả mạng lưới phức tạp. TRANSYT có thể nhanh chóng đánh giá được sự thực thi của một nút giao riêng biệt cũng như tạo ra sự tối ưu hóa thời gian cố định định lượng thời gian cho tín hiệu giao thông trong bất kỳ mạng lưới đường bộ nào mà lưu lượng giao thông cần biết đến, bao gồm cả tín hiệu ở đường vòng xuyến. Phiên bản mới nhất (TRANSYT 15) có các tính năng đặc biệt để đánh giá các nút giao bị kiểm soát cô lập, và mạng lưới pha trộn tín hiệu và không có tiến hiệu cùng với vai trò truyền thống của nó. TRANSYT xác định tối ưu thời gian cố định...... Xác định thời điểm cố định của tín hiệu trong mạng lưới VISSIM dùng TRANSYT-VISSIM LINK. Xác định tín hiều thời gian cố định của tín hiệu trong mạng Aimsun dùng TRANSYT-Aimsun LINK.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (147, 'en', 'FETs VIEW', 'phan-mem-fets-view', NULL, 'Là một hệ thống mô hình sự phát tán trong không khí tích hợp với các mô hình phân tán hóa chất trong không khí như AERMOD (hoặc CALPUFF) để tạo nên một hệ thống có khả năng kiểm kê cấp độ phát thải, theo dõi và lưu trữ số lượng rất lớn dữ liệu, quản lý các cơ sở với các điểm phát hành khác nhau và hàng chục thậm chí hàng trăm các chất ô nhiễm.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (148, 'en', 'FETs-RT Web', 'phan-mem-fets-rt-web', NULL, 'Là 1 dạng web dựa trên thời gian thực, chứng minh sự tương quan giữa khí thải ô nhiễm từ các quá trình công nghiệp và tác động về nồng độ của chúng. Sử dụng dữ liệu của dự báo khí tượng, dữ liệu thực từ các trạm giám sát để làm đầu vào cho một mô hình phân tán hóa chất trong không khí, tính toán nồng độ dự kiến của chất gây ô nhiễm dựa trên các thông số và đặc tính phát xạ.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (149, 'en', 'OSCADY PRO', 'phan-mem-toi-uu-hoa-den-tin-hieu-tai-nut', NULL, 'OSCADY PRO là chương trình tối ưu tín hiệu giao thông theo từng giai đoạn. Phần mềm tạo ra việc sử dụng một số kỹ thuật tối ưu hóa độc đáo để tạo ra một mảng cam kết tốt nhất có thể và thời gian trên số lượng tối thiểu của dữ liệu nút. Nó cũng được dùng cho các nút độc lập, hoặc các kết quả có thể được xuất vào trong TRANSYT để sử dụng trong hệ thống được liên kết.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (150, 'en', 'PICADY', 'phan-mem-picady', NULL, 'PICADY đánh giá sức chứa và trì hoãn ở nơi ưu tiên giao nhau Kết hợp nghiên cứu mở rộng của TRL trong thiết kế chỗ giao nhau đang dùng và dự báo tỷ lệ tai nạn, sức chứa, chiều dài hàng đợi và sự trì hoãn (cả về hàng đợi và hình học) ở nơi có sự ưu tiên các nút.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (151, 'en', 'CadnaA', 'phan-mem-cadnaa', NULL, 'CadnaA được phát triển bởi DataKustik, là phần mềm hàng đầu thế giới trong lĩnh vực tính toán, thể hiện, đánh giá và dự đoán tác động của tiếng ồn trong môi trường. Với khả năng ưu việt của mình, CadnaA có thể đáp ứng nhu câù tính toán trong rất nhiều lĩnh vực khác nhau như: khu công nghiệp, đường sắt, đường bộ hay toàn bộ một khu vực dân cư, thành phố', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (152, 'en', 'ARCADY', 'phan-mem-arcady', NULL, 'ARCADY được sử dụng để đánh giá sức chứa và sự trì hoãn ở vòng xuyến. Nó có khả năng để dự báo thực tế tỷ lệ tai nạn giao thông, sức chứa và việc trì hoãn (cả hàng đợi và mặt hình học) cho hầu hết các kích cỡ khác nhau của vòng xuyến, sắp đặt từ nhiều nhánh với các cấp độ vòng xuyến được phân tách cho tới những vòng xuyến bên trong khu vực ngoại ô.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (153, 'en', 'CadnaSAK', 'phan-mem-cadnasak', NULL, 'CadnaSAK là phần mềm mạnh mẽ để tính toán tiếng ồn trong các hội trường công nghiệp. CadnaSAK tính toán mức độ âm thanh tại các máy trạm được dựa trên dữ liệu phát thải của máy móc thiết bị theo Chỉ thị Máy móc EU- xem xét hình học phòng và các đặc điểm thiết kế. Phân phối tiếng ồn được tính toán và trình bày như bản đồ tiếng ồn. Mức tiếng ồn đặc trưng của các máy trạm được xác định có thể được in trong bảng.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (196, 'en', 'Adapt Builder', 'adapt-builder', NULL, 'Adapt Builder - Phần mềm 3D phần tử hữu hạn phân tích thiết kết kết cấu bê tông dự ứng lực. ', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (154, 'en', 'Hãng TRL', 'gioi-thieu-cong-ty-trl', NULL, 'TRL hàng đầu thế giới về các sản phẩm phần mềm giao thông và tư vấnTRL (là Phòng thí nghiệm Nghiên cứu Giao thông vận tải của UK) là một tổ chức được quốc tế công nhận xuất sắc trong việc cung cấp những nghiên cứu, tư vấn, và kiểm tra tất cả lĩnh vực liên quan đến vận tải. Được thành lập hơn 70 năm, với 500 nhân viên, bao gồm nhiều chuyên gia quốc tế, cung cấp các giải pháp cơ bản và tiên tiến cho chính phủ, chính quyền địa phương, các cơ quan thẩm định và các công ty tư nhân trên một loạt các dự án.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (155, 'en', 'Bastian', 'phan-mem-bastian', NULL, 'Bastian là phần mềm để tính toán trong không khí và truyền tải âm thanh tác động giữa các phòng trong các tòa nhà và truyền tải âm thanh trong không khí từ bên ngoài. Các tính toán trong Bastian được dựa trên các bộ phận từ 1 đến 3 của loạt tiêu chuẩn Châu Âu EN 12354, được thông qua bởi đa số các nước châu Âu như là một phần của tiêu chuẩn quốc gia của họ. Vì vậy, các thủ tục này tính toán hình thành cơ sở chung cho việc tiên lượng cách âm của các tòa nhà. Bastian có thể được áp dụng để dự đoán hiệu suất âm thanh giữa các phòng trong căn hộ và các tòa nhà văn phòng, các lớp học trong nhà trường, và giữa các phòng trong khách sạn hoặc bệnh viện.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (156, 'en', 'Hãng Schlumberger', 'tong-quan-cong-nghe-schlumberger', NULL, 'AquaChem Phân tích Dữ liệu Chất lượng Nước, Biểu đồ, Báo cáo, và Mô hình Quản lý tài nguyên nước dưới đất, các dự án công nghiệp, và các điểm mỏ yêu cầu giám sát liên tục và thu thập mẫu nước để đảm bảo thực hiện đúng hướng dẫn địa phương quy định.Nhiều mẫu nước được thu từ lĩnh vực này và phân tích trong phòng thí nghiệm, cung cấp các chuyên gia nước các dữ liệu quan trọng cần thiết cho sự hiểu biết các điều kiện chất lượng nước tổng thể tại địa điểm.Địa hóa học dung dịch nước và những phát hiện chất lượng nước nói chung xác định sử dụng nước, làm nổi bật các khu vực của mối quan tâm, và cung cấp hỗ trợ cho các rủi ro giảm nhẹ đối với sức khỏe con người và môi trường.Tuy nhiên, làm cho ý nghĩa của số lượng lớn các dữ liệu được sản xuất bởi các phòng thí nghiệm phân tích đòi hỏi một hệ thống quản lý dữ liệu toàn diện. Ứng dụng Quản lý và báo cáo các dữ liệu chất lượng nước từ các giếng cung cấp, thành phố trực thuộc Trung ương. Tuân thủ báo cáo của các dữ liệu chất lượng nước được thu thập tại các bãi chôn lấp vệ sinh và các điểm bị ô nhiễm. Phân tích các dữ liệu mẫu nước trong tầng nước ngầm lưu trữ và phục hồi (ASR). Đánh giá sự tương tác địa hóa học trong dung dịch nước thoát mỏ axit. Xác định xu hướng khoáng trong nước ngầm trong quá trình thăm dò khai thác mỏ.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (157, 'en', 'Hãng DHI', 'gioi-thieu-dhi', NULL, 'Có một số dự án mà giải pháp tốt nhất cũng là giải pháp duy nhất, và trong những dự án như vậy bạn phải chắc chắn rằng mình sử dụng công cụ tốt nhất và có hỗ trợ kỹ thuật bởi một công ty tốt nhất trên thế giới. Phần mềm MIKE by DHI mang đến công nghệ siêu việt, được hỗ trợ bởi những chuyên gia tốt nhất và đem đến giá trị vượt trội cho khách hàng dựa trên 40 năm kinh nghiệm và công nghệ. <p>Đầu tư vào phần mềm MIKE làm công cụ mô hình của bạn là bạn đang đầu tư cho sự phát triển chuyên môn của mình và là cánh cửa cho bạn tiếp cận với cộng đồng kiến thức lớn nhất và uyên thâm nhất trong lĩnh vực lập mô hình tài nguyên nước trên toàn thế giới.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (158, 'en', 'PIPENET ', 'pipenet-thiet-ke-phan-tich-duong-ong', NULL, 'PIPENET là một công cụ phần mềm mạnh mẽ để phân tích nhanh dòng chảy trong ống và hệ thống ống dẫn. Phần mềm bao gồm 3 mô-đun, giúp phân tích và tính toán đối với những hệ thống đường ống lớn và phức tạp nhất một cách dễ dàng.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (160, 'en', 'MIKE 21 C', 'mike-21-c', NULL, 'MIKE 21C là một trong những công cụ được xây dựng tốt nhất để mô phòng diễn biến phát triển của đáy sông và kênh dẫn do sự thay đổi về cơ chế thủy lực.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (159, 'en', 'MIKE 11', 'mike-11', NULL, 'MIKE 11 lập mô hình sông không hạn chế. Với MIKE 11 bạn sẽ có được một bộ công cụ nổi tiếng và được ứng dụng nhiều nhất trên thế giới cho lập mô hình sông 1 chiều. MIKE 11 được rất nhiều kỹ sư chuyên môn về sông lựa chọn vì nó có độ tin cậy cao, độ linh hoạt, tiện ích và chất lượng. MIKE 11 là bộ công cụ mô hình sông mạnh với nhiều đặc tính hơn bất kỳ bộ sản phẩm cùng loại nào khác. MIKE 11 là sản phẩm phần mềm đã làm cho thương hiệu ''MIKE'' trở thành tên tuổi trong lĩnh vực phần mềm chuyên biệt ngành nước có chất lượng của DHI và là một trong những sản phẩm được sử dụng nhiều nhất trong các sản phẩm của MIKE.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (161, 'en', 'MIKE 3', 'mike-3', NULL, 'Lập mô hình 3 chiều cho biển và bờ biển MIKE 3 được xây dựng trên cùng công nghệ như MIKE 21 và là lựa chọn tốt nhất khi dự án yêu cầu phải lập mô hình 3 chiều. Nếu bạn đã quen với MIKE 21 bạn sẽ thấy dễ dàng với MIKE 3. Với sự kết hợp của hai mô hình trên cùng một toolbox, thì không có một công việc mô hình biển, hàng hải nào mà bạn không thực hiện được. Nếu bạn chưa là một chuyên gia về lập mô hình 3 chiều, bạn không phải đi đâu xa. DHI có hỗ trợ kỹ thuật thông qua hơn 30 văn phòng trên toàn thế giới.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (162, 'en', 'MIKE Animation', 'mike-animation', NULL, 'MIKE Animatorbiểu diễn kết quả của bạn Lợi ích MIKE Animator Xây dựng cầu nối giữa chuyên gia và người không chuyên môn Liên kết các nghiên cứu mô hình và ý tưởng trong nhóm làm việc hiệu quả Cung cấp cho bạn phần trình bày chuyên nghiệp cho khách hàng Hỗ trợ việc thảo luận dễ dàng với các bên liên quan Minh chứng khả năng của mô hình hơn các tài liệu in giấy', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (163, 'en', 'Digitech 3D', 'digitech-3d', NULL, 'D3D (DigiTech 3D) - một công ty của Ireland, chuyên cung cấp các dịch vụ nâng cao trong khảo sát địa hình, các dịch vụ lập bản đồ và mô phỏng hình ảnh 3D trên máy tính. Sản phẩm có thể là các bản đồ, hình ảnh độ nét cao, các đoạn phim video chất lượng cao mô phỏng dự án bất động sản. Với việc sử dụng công nghệ của D3D, các công ty phát triển bất động sản và các cơ quan quy hoạch có thể giảm đáng kể thời gian và chi phi cho việc phát triển dự án mới (thành phố, khu dân cư, khu nghỉ dưỡng, sân golf, mỏ, v.v) so với các cách làm truyền thống, đồng thời có thể hình dung và thể hiện một cách trực quan nhất có thể khi mô tả các dự án bất động sản.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (164, 'en', 'ECOLab', 'ecolab', NULL, 'Lập mô hình sinh thái dễ dàng ECO Lab kết hợp hai thế giới tốt nhất: - bạn sẽ tiếp cận với mô hình chất lượng nước chuẩn được sử dụng rộng rãi và được chứng minh của DHI - bạn tự do hoàn toàn khi xác lập mô hình của chính mình - cách lập hoặc cách nghiên cứu ý tưởng và kiểm tra các ý tưởng của mình qua dữ liệu thực tế Mô hình ECO Lab có thể làm việc với các mô hình 1 chiều, 2 chiều và 3 chiều. Các mẫu do bạn xác lập ra sẽ thực hiện điều đó. Tập trung vào diễn biến sinh thái và không phải mất thời gian để lập trình Trao đổi ý kiến và mô hình với đồng nghiệp trên toàn thế giới. Đơn giản là chỉ cần gửi một bản sao mẫu mô hình của bạn', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (165, 'en', 'RADIA ', 'radia-software', NULL, 'Phần mềm mô phỏng, phân tích và đánh giá tác động của sóng điện từ tới môi trường', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (166, 'en', 'DESCAR ', 'descar-software', NULL, 'Phần mềm kiểm soát ô nhiễm nước, mô phỏng quá trình ô nhiễm và đánh giá tác động của ô nhiễm nước.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (167, 'en', 'CUSTIC ', 'custic-software', NULL, 'CUSTIC: Phần mềm mô phỏng ảnh hưởng của tiếng ồn Với các điều kiện cụ thể tại khu vực đánh giá được nhập vào phần mềm, CUSTIC cho phép mô phỏng về hình học và đánh giá tác động của tiếng ồn.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (168, 'en', 'Hãng Canarina', 'hang-canarina', NULL, 'DISPER software là một phần mềm phân tích sự phát tán không khí ô nhiễm. Chương trình của phần mềm sẽ tính toán nồng độ chất ô nhiễm trong mỗi điểm của không khí, xem xét trong những nguồn gây ô nhiễm và các điều kiện của bầu khí quyển.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (169, 'en', 'BREEZE VASDIP', 'breeze-vasdip', NULL, 'BREEZE VASDIP là một sản phẩm đồng hành tuyệt vời cho BREEZE ExDAM® và các mô hình tính toán các tham số dễ bị tổn thương tương ứng để sử dụng trong các ứng dụng này: HExDAM® (Mô hình đánh giá thiệt hại do nổ áp suất cao) và mô hình VExDAM® (mô hình đánh giá các vụ nổ hơi nước). Ngoài ra, người dùng có thể tính toán sự thay đổi tính dễ tổn thương như thiết kế cấu trúc cá nhân và các tham số thành phần con người khác nhau, cho phép người dùng tối ưu hóa thiết kế của thành phần. Điều này làm tăng tiện ích của các mô đun HExDAM và VExDAM và làm cho VASDIP trở lên vô giá khi thực hiện phân tích chi phí và rủi ro.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (170, 'en', 'RISK ANALYST', 'risk-analyst', NULL, 'BREEZE® Risk Analyst là hệ thống mô hình đánh giá rủi ro sức khoẻ con người và hệ sinh thái được thiết kế để tiến hành đánh giá đa chiều rủi ro sức khoẻ con người và mô hình đánh giá rủi ro hệ sinh thái dựa trên mạng lưới thức ăn. BREEZE Risk Analyst kết hợp tất cả các công cụ, cơ sở dữ liệu, chức năng GIS, và các phương trình mô phỏng vận số, vận chuyển, phơi nhiễm thành một ứng dụng phần mềm dễ sử dụng và giá cả phải chăng.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (171, 'en', 'INCIDENT ANALYST', 'incident-analyst', NULL, 'Phát thải ngẫu nhiênINSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (172, 'en', 'Breeze ExDAM', 'breeze-exdam', NULL, 'BREEZE® ExDAM® (mô hình đánh giá thiệt hại do nổ) là một bộ mô phỏng 3D hiệu quả, độc đáo hậu quả của vụ nổ, cho phép người dùng dự đoán được thương tích và thiệt hại do các vụ nổ mạnh và nổ hơi nước gây ra.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (173, 'en', 'Hệ thống mô hình hóa EFDC EXPLORER ', 'he-thong-mo-hinh-hoa-efdc-explorer-eesm', NULL, 'EESM là sản phẩm của hãng phần mềm nổi tiếng DSI (Hoa Kỳ). Đây là một hệ thống mô hình hóa môi trường và thủy động lực học để thực hiện các nghiên cứu kỹ thuật môi trường nước ngọt và nước mặn. Phần mềm này cho phép các kỹ sư và nhà khoa học tạo ra các mô hình môi trường thủy sinh chính xác và khoa học một cách hiệu quả. Sử dụng Hệ thống mô hình hóa EE để mô hình bất kỳ môi trường sông, hồ, cửa sông hoặc ven biển nào đang đối mặt với những thách thức môi trường và sử dụng công cụ này để báo cáo kết quả một cách rõ ràng và hiệu quả bằng các khả năng xử lý sau mạnh mẽ.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (174, 'en', 'Hãng BREEZE', 'san-pham-va-dich-vu-cua-breeze', NULL, 'BREEZE®, phần mềm mô hình hoá phân tán không khí, cháy, nổ và đánh giá rủi ro hàng đầu trên thị trường được hơn 4.000 chuyên gia EHS sử dụng trong các cơ quan chính phủ, công nghiệp, tư vấn và học thuật ở 90 quốc gia trên toàn thế giới. Phần mềm BREEZE mạnh mẽ, có các giao diện và công cụ trực quan thân thiện, giúp bạn dễ dàng đánh giá tác động của các mối nguy hiểm EHS tại chỗ và các cộng đồng lân cận.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (175, 'en', 'EFDC Explorer', 'efdc-explorer', NULL, 'EFDC_Explorer (EE) là một phần mềm hoạt động dựa trên giao diện đồ họa Window. Phần mềm được phát triển bởi công ty Dynamic Solutions-International, LLC(DSI) nhằm thực hiện quá trình tiền và hậu xử lý mã “Environmental Fluid Dynamics Code" (EFDC). EFDC được thiết kế để hỗ trợ việc xây dựng mô hình, Tạo ra lưới hệ Đề Các và lưới cong, kiểm tra, hiệu chỉnh và xem dữ liệu bằng các hình vẽ và hoạt ảnh của các kết quả mô hình EFDC.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (176, 'en', 'Breeze AERMOD / ISC', 'breeze-aermod-isc', NULL, 'Là một phần mềm mô phỏng phát tán khí thế hệ mới được xây dựng đáp ứng đầy đủ tiêu chuẩn trên toàn thế giới. Breeze AERMOD được phát triển với các tính năng tối ưu hóa mô hình phát tán khí với nhiều tùy chọn cho phép người dùng đặt trạng thái ẩn - hiện đối với các dữ liệu phù hợp. Breeze AERMOD thực sự đem lại hiệu quả cho người dùng dù Breeze AERMOD được sử dụng trong các ngành công nghiệp, chính phủ hay các học viện. Breeze AERMOD được tích hợp với 3Danalyst để thực hiện bài tóan mô hình, phân tích và đánh giá một cách trực quan giúp người dùng có cái nhìn đầy đủ, sâu sắc hơn. Breeze AERMOD gồm ba phiên bản: Standard, Pro, và Pro Plus. Industrial Source Complex (ISC) được sử dụng để đánh giá tác động của khí thải từ nhiều nguồn công nghiệp , ISC là phiên bản nâng cao của ISCST3. Những mô hình này dự báo nồng độ chất ô nhiễm từ: điểm, đường, khu vực, khối lượng, và các nguồn bùng nổ với lượng khí thải biến động trong tất cả các chế độ địa hình.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (177, 'en', 'PHAROS', 'pharos', NULL, 'Mô hình sóng Pharos được sử dụng để tính toán sự chuyển động sóng cộng hưởng ở các bến cảng. Mô hình này đã được áp dụng trong một loạt các dự án nghiên cứu và kỹ thuật trên toàn thế giới. Biện pháp thi công, như phần kéo dài của đê chắn sóng, hoặc sự điều chỉnh các bến cảng, có thể làm giảm sự khuấy trộn sóng hoặc sự công hưởng ở bến cảng có thể được đánh giá với mô hình.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (178, 'en', 'PROBED', 'probed', NULL, 'Công cụ thiết kế bảo vệ móng PROBED PROBED là một chương trình mang tính linh hoạt và thân thiện cho việc tính toán bảo vệ đáy và bao bọc đường ống do tác động của sự kết hợp của dòng chảy và sóng liện tục.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (179, 'en', 'BREAKWAT', 'breakwat', NULL, 'BREAKWAT công cụ thiết kế cấu trúc bờ biển. BREAKWAT là một công cụ thiết kế khái niệm đối với một số loại cấu trúc ven biển theo tải trọng sóng. Đê chắn sóng gò đá hộc với các lớp bao bọc bởi vật liệu đá hoặc các khối bê tông, bờ bảo vệ đê chắn sóng, cấu trúc thùng chìm thẳng đứng, kết cấu kiểu đá gầm và cấu trúc gần đáy có thể được thiết kế bằng cách sử dụng BREAKWAT đến giai đoạn thiết kế khái niệm.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (180, 'en', 'SOBEK', 'sobek', NULL, 'Bộ mô hình 1D/2D toàn bộ cho giải pháp về nước. SOBEK là một bộ mô hình mạnh mẽ để dự báo lũ, tối ưu hóa hệ thống thoát nước, điều khiển hệ thống dẫn nước, thiết kế cống thoát nước cho dòng nước lũ, hình thái sông, sự ngập mặn và chất lượng nước mặt.INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (181, 'en', 'DELFT3D', 'delft3d', NULL, 'BỘ PHẦN MỀM DELFT3D CỦA DELTARES - HÀ LAN là một bộ phần mềm tích hợp mô hình một cách linh hoạt, có thể mô phỏng 02 chiều (Theo chiều ngang hoặc chiều dọc của mặt phẳng) hoặc mô phỏng theo không gian 3 chiều cho Flow (dòng chảy), sediment transport (vận chuyển trầm tích),morphology (hình thái học), waves (sóng), water quality (chất lượng nước), và ecology (hệ sinh thái). Delft3D còn có khả năng xử lý tương tác giữa các quá trình này.', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (182, 'en', 'Breeze CALPUFF', 'breeze-calpuff', NULL, 'Breeze CALPUFF được sử dụng để mô hình phát tán khí thải, đánh giá tác động của khí thải tới môi trường tại các khu vực có quy mô lớn, địa hình phức tạp.', NULL, NULL, 'Phần mềm', '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (183, 'en', 'Breeze Roads', 'breeze-roads', NULL, 'Breeze Roads (CALINE4, CAL3QHC, CAL3QHCr) Breeze Roads cho phép mô hình hóa sự phát tán khí, dự báo tác động của các khí carbon monoxide (CO), khí nitơ (NO2),hạt (PM), và nồng độ các khí trơ gây ô nhiễm khác từ các phương tiện di...', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (184, 'en', 'Mô hình phân tán Screening Air', 'mo-hinh-phan-tan-screening-air', NULL, 'Mô hình phân tán Screening Air Breeze SCREEN3 cho phép mô hình 2D hoặc 3D cho 1 hoặc nhiều nguồn chất thải gây ô nhiễm trên cùng 1 mô hình', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
