INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (202, 'en', 'FB-MultiPier', 'fb-multipier', NULL, 'FB-MultiPier - Phần mềm thiết kế mấu trụ cầu', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (205, 'en', 'Phần mềm phân tích, thiết kế móng đơn -MDW', 'mdw', NULL, 'MDW là phần mềm tự động hoá phân tích thiết kế móng đơn bê tông cốt thép đưa ra kết quả cuối cùng là bản vẽ kỹ thuật thi công.', NULL, NULL, 'Phần mềm', '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (203, 'en', 'TALREN', 'talren', NULL, 'Phần mềm TALREN V5 phân tính, thiết kế ổn định trượt', NULL, NULL, 'Phần mềm', NULL, NULL) ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (204, 'en', 'Phần mềm phân tích, thiết kế khung không gian BTCT - Vinasas Pro', 'vinasaspro', NULL, 'LỜI NÓI ĐẦUINSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (212, 'en', 'Phần mềm quản lý Hợp đồng Tư vấn thiết kế - Thực hiện tiến độ và Thanh quyết toán', 'phan-mem-quan-ly-hop-dong-tu-van-thiet-k-1', NULL, 'Phần mềm quản lý hợp đồng tư vấn thiết kế - thực hiện hợp đồng xây dựng, CONNA áp dụng cho mọi tổ chức thuộc ngành xây dựng cũng như các ngành nghề khác trong việc quản lý các hợp động kinh tế, thuộc các cơ quan, đơn vị hành chính sự nghiệp, các doanh nghiệp, ...', NULL, NULL, 'Phần mềm', '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (213, 'en', 'Phần mềm Quản lý Sản xuất - Các Doanh Nghiệp In Ấn', 'phan-mem-quan-ly-san-xuat-cac-doanh-nghi', NULL, 'Hỗ trợ cho việc theo dõi, giám sát, phối hợp thực hiện từ Ban Giám đốc, phòng Kế hoạch Thị trường, phòng Vật tư, phòng Tài vụ Kế toán, cho đến các Xí nghiệp sản xuất cùng triển khai các hoạt động sản xuất kinh doanh.', NULL, NULL, 'Phần mềm', '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (214, 'en', 'Mappro - Phần mềm Quản lý Quy hoạch và Hạ tầng kỹ thuật Đô thị', 'mappro-phan-mem-quan-ly-quy-hoach-va-ha-', NULL, 'MAPPRO là một giải pháp phần mềm nhằm xây dựng các Hệ thống phục vụ cho các công tác Quản lý quy hoạch đô thị và Hạ tầng kỹ thuật, ứng dụng các công nghệ xử lý bản đồ và GIS, gắn liến với các chức năng, nghiệp vụ trong hoạt động Xây dựng đô thị.', NULL, NULL, 'Phần mềm', '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (215, 'en', 'ESPA - Hệ Thống Quản Lý Sản Xuất Nước Sạch - Dịch Vụ Khách Hàng Sử Dụng Nước', 'espa-he-thong-quan-ly-san-xuat-nuoc-sach', NULL, 'Quản lý sản xuất nước sạch, Quản lý mạng lưới tuyến ống kỹ thuật, Quản lý khách hàng, Quản lý chất lượng nước, Quản lý thất thoát', NULL, NULL, 'Phần mềm', '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (207, 'en', 'Phần mềm phân tích, thiết kế khung phẳng - KPW', 'kpw', NULL, 'KPW là phần mềm tự động hoá phân tích thiết kế kết cấu khung phẳng bê tông cốt thép đưa ra kết quả cuối cùng là bản vẽ kỹ thuật thi công, đồng thời cũng có thể thực hiện tự động hoá thiết kế kết cấu dàn thép phẳng.', NULL, NULL, 'Phần mềm', '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (235, 'en', 'DNV GL Software', 'dnv-gl-software', NULL, 'DNV GL là nhà cung cấp hàng đầu thế giới về phần mềm cho một tương lai an toàn hơn, thông minh và xanh hơn trong công nghiệp dầu khí, năng lượng, hàng hải và chế biến', NULL, NULL, 'Phần mềm', '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (236, 'en', 'Maros', 'maros-cong-cu-phan-tich-ram', NULL, 'Maros™ là một công cụ phân tích RAM* cao cấp, với những tính năng mở rộng cho việc mô phỏng cấu trúc hoạt động của doanh nghiệp, các nhu cầu, các kế hoạch bảo trì và vận hành. Maros™ hỗ trợ người dùng ra các quyết định chính xác để tối đa hóa mức doanh thu trên vốn đầu tư bỏ ra.', NULL, NULL, 'Phần mềm', '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (237, 'en', 'Lake Environmental', 'lake-environmental', NULL, 'Lake Environmental là một công ty của Canada chuyên nghiên cứu và cung cấp các giải pháp phần mềm về lĩnh vực môi trường hóa chất khí (mô phỏng phát tán, theo dõi, kiểm soát, dự báo ...). Công ty có các chuyên gia hàng đầu về CNTT trong lĩnh vực môi trường với các sản phẩm đạt tiêu chuẩn quốc tế và được ứng dụng cho nhiều cơ quan môi trường, viện nghiên cứu, công ty liên quan trên khắp thế giới.', NULL, NULL, 'Phần mềm', '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (238, 'en', 'DataKustik', 'datakustik', NULL, 'Hãng phần mềm mô phỏng tiếng ồn hàng đầu thế giới ! DataKustik là công ty chuyên về sản xuất phần mềm đánh giá và tính toán tác động của tiếng ồn đến môi trường hàng đầu thế giới, được thành lập năm 1991 tại Munich, Đức. Với hơn 20 năm kinh nghiệm trong lĩnh vực tư vấn và phát triển phần mềm liên quan đến tác động của tiếng ồn đến môi trường, DataKustik được công nhận rộng rãi và hợp tác với nhiều tập đoàn, tổ chức hàng đầu thế giới, là thành viên của Tổ Chức Âm Học Đức (DEGA, đây là một thành viên của tổ chức âm học thế giới) và Hiệp Hội Giảm Thiểu Tiếng Ồn Áo (ÖAL).DataKustik cũng đạt được chuẩn ISO 9001:2008 về khả năng đáp ứng yêu cầu của khách hàng.', NULL, NULL, 'Phần mềm', '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (239, 'en', 'Kritikal', 'kritikal', NULL, 'Hãng KritiKal là hãng thiết kế, ứng dụng và sáng tạo công nghệ hàng đầu ở Ấn Độ và trên thế giới. Tiếng Ấn Độ thì &quot;Kritikal&quot; có nghĩa là &quot;sáng tạo cho tương lai&quot;. Được thành lập vào năm 2002, KritiKal là một trong rất ít công ty trên thế giới với thế mạnh trong cả thiết kế hệ thống nhúng và giải pháp hình ảnh theo thời gian thực Kritikal chuyên về các giải pháp xử lý video thời gian thực hoặc video off-line cho các ứng dụng trực tuyến, giải pháp phân tích hình ảnh với công nghệ mới và tiên tiến nhất trên thế giới.', NULL, NULL, 'Phần mềm', '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (240, 'en', 'Máy siêu âm cọc khoan nhồi CHUM (Piletest)', 'may-sieu-am-coc-khoan-nhoi-chum', NULL, 'Đáp ứng TCVN 9396:2012 Cọc khoan nhồi - Xác định tính đồng nhất của bê tông - Phương pháp xung siêu âm ', NULL, NULL, 'Thiết bị', '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (243, 'en', 'Autodesk Revit', 'autodesk-revit', NULL, 'Revit là phần mềm chuyên dụng cho BIM.', NULL, NULL, 'Softwares', '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (244, 'en', '3DsMax', '3dsmax', NULL, 'Phần mềm mô hình 3D và render, để tạo mô hình thiết kế trực quan, các trò chơi và hoạt hình.', NULL, NULL, 'Softwares', '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (245, 'en', 'Architecture Engineering & Construction Collection (AEC)', 'architecture-engineering-amp;-construction-collection-aec', NULL, 'Bộ sưu tập các phần mềm của Autodesk, phục vụ thiết kế kiến trúc, kỹ thuật và xây dựng', NULL, NULL, 'Phần mềm', '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (246, 'en', 'test sản phẩm test', 'test-san-pham', NULL, '', NULL, NULL, 'Phần mềm', '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (247, 'en', 'Phần mềm Render nội thất Enscape 3D', 'phan-mem-render-noi-that-enscape-3d', NULL, 'Phần mềm render Enscape 3.1 hỗ trợ cho việc thiết kế và trải nghiệm hình ảnh kết xuất đẹp mắt, chuyên nghiệp. Hiện nay, với phiên bản mới nhất của Enscape thì người dùng có thể đưa thiết kế của họ gần với thực tế hơn nhờ Material Libraty.', NULL, NULL, 'Softwares', '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
INSERT INTO "cic_products_translations" ("entity_id", "locale", "name", "alias", "category_name", "summary", "guarantee", "application_name", "types_name", "seo_title", "seo_keyword") VALUES (251, 'en', 'SOLIDWORKS – Professional 3D Design Software', 'solidworks-–-professional-3d-design-software', NULL, 'SOLIDWORKS is a professional 3D design software solution developed by Dassault Systèmes. It is particularly suitable for small and medium-sized enterprises and can meet most current mechanical design requirements. SOLIDWORKS is widely recognized for its powerful and user-friendly design capabilities.', NULL, NULL, 'Softwares', '', '') ON CONFLICT (entity_id, locale) DO NOTHING;
